INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Success Merit Scholarship', 'The scholarship provides a 30% tuition fee reduction for new commencing international students, applied from the second session and continuing for the remaining duration of their course.', 'To be eligible, applicants must:; Be an international student commencing at Charles Sturt University in 2027; Meet the entry requirements for your course; Meet all visa requirements; Enrol in an eligible on-campus course', '30% tuition fee reduction from the second session of your course', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.csu.edu.au/scholarships/scholarships-grants/find-scholarship/international/international-student-success-merit-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-student-success-merit-scholarship/a317293ab3dd02a677edfb13d611edfa', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00005F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Success Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Success Scholarship', 'The scholarship provides a 15% tuition fee reduction for new commencing international students, applied from the second session and continuing for the remaining duration of their course.', 'To be eligible, applicants must:; Be an international student commencing at Charles Sturt University in 2027; Meet the entry requirements for your course; Meet all visa requirements; Enrol in an eligible on-campus course', '15% tuition fee reduction from the second session of your course', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.csu.edu.au/scholarships/scholarships-grants/find-scholarship/international/international-student-success-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-student-success-scholarship/7837def98aa45a76ea3a22dc9dafe637', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00005F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Success Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International student merit scholarship', 'This scholarship recognises and rewards excellence for eligible students applying to study at Charles Sturt University. The award provides a 25% tuition fee reduction throughout the entire duration of the course.', 'Open to eligible new commencing international applicants studying in internal/on-campus mode at Albury-Wodonga, Bathurst, Dubbo, Melbourne, Orange, Port Macquarie, Sydney and Wagga Wagga in the approved courses. The scholarship is not available for continuing or transferring students.', 'Value: 25% fee discount for duration of course', 'Undergraduate / VET', NULL, 'https://www.csu.edu.au/scholarships/scholarships-grants/find-scholarship/international/international-student-merit-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-student-merit-scholarship/c91a037cf0236da295f9c434592a7bb4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00005F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International student merit scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International student support scholarship', 'The scholarship provides a 10% fee discount for new commencing international students for the duration of their course.', 'Awarded to eligible new commencing international applicants studying in internal/on-campus mode at Albury-Wodonga, Dubbo, Bathurst, Melbourne, Orange, Port Macquarie, Sydney and Wagga Wagga in the approved courses.', 'Value: 10% fee discount for duration of course', 'Undergraduate / VET', NULL, 'https://www.csu.edu.au/scholarships/scholarships-grants/find-scholarship/international/international-student-support-scholarship-2024', 'https://search.studyaustralia.gov.au/scholarship/international-student-support-scholarship/df2d1a9143d1d93c6a0426d6df1c2ec1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00005F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International student support scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Accounting Honours Scholarship', 'A scholarship for students studying the Bachelor of Commerce (Honours) majoring in accounting or finance. Up to $6000 is available for one year only.', 'An Australian citizen. A New Zealand citizen. Australian permanent resident. Australian humanitarian visa holder. An International student.', 'Up to AUD $6000 — Up to $6000 is available for one year only.', 'Undergraduate / VET', 'Accounting', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/accounting-honours-scholarship-5585A', 'https://search.studyaustralia.gov.au/scholarship/accounting-honours-scholarship/ebd2c29fdb777872f618027bb613ad2e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Accounting Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alfred Research Alliance Honours Scholarship', 'The Alfred Research Alliance Honours Scholarship is for students studying an Honours program on the Alfred campus, through the School of Translational Medicine, the School of Public Health and Preventive Medicine, or the Baker or Burnet institutes. Each scholarship is worth $6000: two are for any student enrolled full time in the Bachelor of Biomedical Science or the Bachelor Science Honours program, while the third is reserved for a Bachelor of Medical Science Honours student.', 'An Australian citizen. ; A New Zealand citizen. ; Australian permanent resident. ; Australian humanitarian visa holder. ; An International student.', 'Up to AUD $6000 — $6000 per annum (48 credit points of study) for a maximum of one year.', 'Undergraduate / VET', 'Medicine, Sciences', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/ara-honours-scholarship-5596A', 'https://search.studyaustralia.gov.au/scholarship/alfred-research-alliance-honours-scholarship/f449849138b638d2701f18a0e635102d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alfred Research Alliance Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Amplifying UNCLOUD Honours Scholarship', 'The Amplifying UNCLOUD Honours Scholarship at Monash University is available for an honours student to conduct a research project, together with one of our study partners or stakeholders, addressing an area of need in vaping prevention research among young adults.', 'Current student enrolled in an Honours program in the Department of General Practice in the School of Public Health and Preventative Medicine at a Monash Campus in Australia.; Have a WAM 65+ (Current students).; Participation in Access Monash Mentoring program or other Monash mentoring programs.', 'Up to AUD $3000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/amplifying-uncloud-honours-scholarship', 'https://search.studyaustralia.gov.au/scholarship/amplifying-uncloud-honours-scholarship/b36f18a8f8a2ed1c8023be2d0d4618fd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Amplifying UNCLOUD Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Arts Coursework Masters Research Grant', 'The Arts Coursework Masters Research Grant provides financial support to Arts masters by coursework international students who are completing a pathway to Higher Degree by Research as part of their coursework studies.', 'You must meet the following criteria:; Current student in a Faculty of Arts Masters by coursework degree at a Monash Campus in Australia.; Have successfully completed APG5084 Designing research and APG5849 Research thesis A.; Enrolment in APG5850 Research thesis B.', 'Up to AUD $6000', 'Postgraduate', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/arts-coursework-masters-research-grant-6293', 'https://search.studyaustralia.gov.au/scholarship/arts-coursework-masters-research-grant/d7976f86b3e6ffb234c04c7de13de74b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Arts Coursework Masters Research Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'DEPM Prostate Cancer Research Scholarship', 'The DEPM Prostate Cancer Research Scholarship is intended to encourage students to undertake further studies at Honours level in medicine at the Monash Alfred campus in the area of Public Health and Preventive Medicine, focusing principally on improving health outcomes for men diagnosed with prostate cancer.', 'Australian or New Zealand citizen, holder of an Australian permanent resident visa, permanent humanitarian visa or international student.; Obtain a minimum weighted average mark (WAM) of 70% or above, across undergraduate study in Bachelor of Medical Sciences (Honours) (MED4301 & MED4302), Bachelor of Biomedical Sciences (Honours) (BMS4100 & BMS4200), or the Bachelor of Health Sciences (Honours) (HSC4011, HSC4001 & 4002).; Commencing or continuing in a full-time School of Public Health and Preventive Medicine Honours program at the Monash Alfred campus (Bachelor of Medical Sciences (Honours) (MED4301 & MED4302), Bachelor of Biomedical Sciences (Honours) (BMS4100 & BMS4200), or the Bachelor of Health Sciences (Honours) (HSC4011, HSC4001 & 4002)).', 'Up to AUD $3000 — $3000 for one year only.', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/depm-prostate-cancer-research-scholarship-6063B', 'https://search.studyaustralia.gov.au/scholarship/depm-prostate-cancer-research-scholarship/fe66396a1afcba71b34cd8b0955cea4d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'DEPM Prostate Cancer Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'David Shugg Professionalism Scholarship', 'This Scholarship is to honour the important role that David Shugg played in the professionalism of paramedics. Throughout David\'s career, he advanced and embedded professionalism in paramedic training and education in the setting of emergency primary health care. In his legacy this Scholarship aims to support the next generation of leaders in paramedicine.', 'Enrolled in the Bachelor of Paramedicine (Honours) M3707 in the Department of Paramedicine at a Monash campus in Australia.; Have a WAM 80+ (Current students).', 'Up to AUD $10000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/david-shugg-professionalism-scholarship-6270', 'https://search.studyaustralia.gov.au/scholarship/david-shugg-professionalism-scholarship/cb417d592e48a97d5937be68527e52c5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'David Shugg Professionalism Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Department of Economics Honours Merit Scholarship', 'This scholarship is awarded to high achieving students who enter into the Bachelor of Commerce (Honours) or the Bachelor of Economics (Honours) course.', 'You must meet the following criteria:; A commencing student, enrolling full-time in economics or jointly in economics and econometrics in the Bachelor of Commerce (Honours) degree or Bachelor of Economics (Honours) degree at the Monash Clayton campus.', 'Up to AUD $10000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/department-of-economics-honours-merit-scholarship-6111', 'https://search.studyaustralia.gov.au/scholarship/department-of-economics-honours-merit-scholarship/4dcc09127e9a658ee845c32fdd0af67a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Department of Economics Honours Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Department of Marketing Honours Scholarship', 'The Marketing Honours Scholarship recognises outstanding academic achievement and supports high-performing students entering the Bachelor of Commerce (Honours) program majoring in Marketing at Monash University. This scholarship provides financial support to full-time students, awarded on the basis of academic excellence in their previous degree. It aims to encourage and assist talented students in pursuing advanced studies and research in marketing. The scholarship reflects the department\'s commitment to fostering academic excellence and preparing graduates for success in research, industry, and academia.', 'You must meet the following criteria:; Commencing student enrolled in the Bachelor of Commerce (Honours) majoring in Marketing  at a Monash Campus in Australia.; Recipients must achieve a minimum of WAM 75 in their previous degree.', 'Up to AUD $6000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/department-of-marketing-honours-scholarship-6288', 'https://search.studyaustralia.gov.au/scholarship/department-of-marketing-honours-scholarship/9999dd5617e2917e595a905119755f8f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Department of Marketing Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Econometrics Honours Memorial Scholarship', 'These prestigious scholarships are awarded in memory of the tragic events that took place during October 2002 in the Department Econometrics and Business Statistics, and its honours students. A major fundraising campaign was launched by the Econometrics and Business Statistics Department and its alumni, and this, along with contributions from many others, has enabled the faculty to offer these scholarships.', 'An Australian citizen. A New Zealand citizen. Australian permanent resident. Australian humanitarian visa holder. An International student.', 'Up to AUD $15000 — $15,000 for one year only (48 credit points of study).', 'Undergraduate / VET', 'Economics', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/econometrics-honours-memorial-scholarship-5586', 'https://search.studyaustralia.gov.au/scholarship/econometrics-honours-memorial-scholarship/f1cfa00faf74adbbe13177868e74a364', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Econometrics Honours Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Engineering Accommodation Scholarship', 'Elevate your Engineering Experience with our Accommodation Scholarship! Immerse yourself in a vibrant, supportive community of students while receiving financial support for your housing needs. Choose from a range of comfortable accommodation options, allowing you to focus on your studies', 'A commencing student enrolled or intending to enrol in an undergraduate or postgraduate degree in the Faculty of Engineering at a Monash campus in Australia.; Must satisfy entry into an Engineering undergraduate or postgraduate program.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-accommodation-scholarship-6238', 'https://search.studyaustralia.gov.au/scholarship/engineering-accommodation-scholarship/1d8470f63c820f27dba3fd3edc2fc74f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Engineering Accommodation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Engineering Industry Teams Scholarship', 'Industry Teams is a supervised industry project where a team of students work collaboratively with Monash University and/or an industry partner to address a defined project need. Based primarily at the Monash Innovation Labs, each project involves a team comprising an academic supervisor, an industry supervisor, and the student members. This initiative provides students with the opportunity to apply independent thinking and problem-solving skills to develop or enhance products, methods, or services. Projects may be self-contained or form part of a larger innovation initiative.', 'You must meet the following criteria:; Current student enrolled in an undergraduate or Master\'s degree at a Monash campus in Australia.; Must be a member of a Monash Student Teams Initiative.; Conduct an interview with the industry partner.', 'Up to AUD $4500 — $4,500 per student paid over 6 months only ($2,250 paid over 2 consecutive quarters).', 'Postgraduate', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-industry-teams-scholarship-6279', 'https://search.studyaustralia.gov.au/scholarship/engineering-industry-teams-scholarship/0c530c58329a41b394cde0b11e14e608', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Engineering Industry Teams Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Engineering International High Achievers Scholarship', 'The Engineering International High Achievers Scholarship is introduced to recognise high achieving international students.', 'You must be studying as one of the following:; Undergraduate - A commencing student enrolling in a single undergraduate degree offered by the Faculty of Engineering.; Students must have an ATAR or International equivalent of 95+.; Students must have an ATAR or International equivalent of 95+.\r\nPostgraduate - A commencing student enrolling in a postgraduate degree offered by the Faculty of Engineering.; Students must have achieved a minimum WAM of 75 in their undergraduate degree.', 'Undergraduate - $15,000 per 48 credit points, paid towards your tuition fees, up to four years.; Postgraduate - $15,000 per 48 credit points, paid towards your tuition fees.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-international-high-achievers-scholarship-6204', 'https://search.studyaustralia.gov.au/scholarship/engineering-international-high-achievers-scholarship/28e6424450902f7a00fd56b6941e9fc1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Engineering International High Achievers Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Engineering Masters Pathway Scholarship', 'A scholarship for high-achieving Year 12 students intending to enrol in the Bachelor of Engineering (Honours) and Master of Engineering pathway program. Up to 10 scholarships valued at up to $30,000 are available each year.', 'You must meet the following criteria:; A commencing undergraduate student intending to enrol in the Bachelor of Engineering (Honours) single degree and Master of Engineering pathway program at a Monash campus in Australia; Currently studying Australian Year 12 or IB, and; Must achieved a minimum ATAR score of 98.00.', 'Up to AUD $6000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-masters-pathway-6056A', 'https://search.studyaustralia.gov.au/scholarship/engineering-masters-pathway-scholarship/776ba2c1bfa1ba6351022bc4963ef156', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Engineering Masters Pathway Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Eric Dubsky Memorial Engineering Leadership Scholarship', 'Eric Dubsky was an electrical engineer who immigrated to Australia from Nazi occupied Austria shortly before the outbreak of World War II in 1939. Initially with his father and then as chairman and managing director he developed a small manufacturer Vulcan Electrics Pty Ltd into one of the top 100 companies in Australia - Vulcan Industries Australia Ltd. Vulcan produced a range of innovative domestic and commercial products and had 2000 employees. He employed engineering students as trainees with the company, many of whom became leaders with Vulcan and other engineering companies. This award continues his legacy by providing young engineers with the opportunity to develop into future leaders of Australian industry.', 'Applicants must: Be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student; Enrolled in any single or double undergraduate degree in the Faculty of Engineering at a Monash campus in Australia.; Have completed a minimum of 48 credit points in their Engineering degree.', 'Up to AUD $30000 — $10,000 per annum for a maximum of three years.', 'Undergraduate / VET', 'Engineering and technology', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/eric-dubsky-memorial-5719', 'https://search.studyaustralia.gov.au/scholarship/eric-dubsky-memorial-engineering-leadership-scholarship/16d33327b344d7a93bb4569bd41c8d29', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Eric Dubsky Memorial Engineering Leadership Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Faculty of IT International Merit Scholarship', 'This scholarship is for international students committed to studying at the Faculty of Information Technology at Monash. It aims to attract and reward high achieving international students from India, Sri Lanka and Bangladesh to the faculty. This scholarship serves dual purposes: it recognises excellence in achievement of our international students, whilst enriching our community by fostering diversity.', 'An International student. Must be enrolled to commence in, or hold an offer for one of the 3 listed IT single degree courses. You must be a citizen of and currently studying in India, Sri Lanka or Bangladesh. You must be completing your final year (equivalent Australian Year 12) offshore. International students currently studying Australian Year 12 onshore (in Australia) may be eligible for the Sir John Monash Scholarship for Excellence. ATAR score (or international equivalent) of 90+ for local A-Level / IB / CBSE awards.', '20% off tuition fees paid for the duration of the course.', 'Postgraduate, Undergraduate / VET', 'Computing and information technology', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/faculty-of-it-international-merit-scholarship-6232', 'https://search.studyaustralia.gov.au/scholarship/faculty-of-it-international-merit-scholarship/fb112d9c2007f2d40d97a18cf29eee9d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Faculty of IT International Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Finance Honours Grant', 'This scholarship supports academically outstanding students undertaking the Bachelor of Commerce (Honours) majoring in Finance.', 'You must meet the following criteria:; Commencing full-time in the Bachelor of Commerce (Honours) (B3701) degree majoring in finance at a Monash University campus in Australia.', 'Up to AUD $6000 — $6000 one-off payment.', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/finance-honours-scholarship-6128', 'https://search.studyaustralia.gov.au/scholarship/finance-honours-grant/0805ff42dde870cd03f949278cc4aa20', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Finance Honours Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Freemasons John Dann Music Scholarship', 'The Freemasons John Dann Music Scholarship was established to support talented students within the Sir Zelman Cowen School of Music and Performance at Monash University.', 'You must meet the following criteria:; Commencing or continuing undergraduate student enrolled or intending to enrol in an undergraduate degree in the Sir Zelman Cowen School of Music in the Faculty of Arts at a Monash campus in Australia.; Experiencing financial hardship.', 'Up to AUD $6000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/freemasons-john-dann-music-scholarship-6226', 'https://search.studyaustralia.gov.au/scholarship/freemasons-john-dann-music-scholarship/03187fcc726310bf4effc17ac7bd9cc5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Freemasons John Dann Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ian Little Honours Scholarship', 'A scholarship for students intending to pursue an economics honours degree at Monash Business School: Bachelor of Commerce (Honours) or Bachelor of Economics (Honours). Based on academic achievement, you will be awarded a $15,000 scholarship if selected. No application is necessary. All students who apply for the course will be automatically assessed.', 'An Australian citizen.; A New Zealand citizen. ; Australian permanent resident. ; Australian humanitarian visa holder. ; An International student.', 'Up to AUD $15000 — $15,000 paid for one year only.', 'Undergraduate / VET', 'Business and management, Economics', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/ian-little-honours-scholarship-5769', 'https://search.studyaustralia.gov.au/scholarship/ian-little-honours-scholarship/88b27291f1e30b8fc46cf931c1315802', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ian Little Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Information Technology Industry-Based Learning Placement Grant', 'This grant is awarded to high achieving students in the Faculty of Information Technology who undertake a 22 week placement with an industry partner. The grants provide support to the recipients as they benefit from the industry-based experience gained from the placements.', 'An Australian citizen. \r\nA New Zealand citizen. \r\nAustralian permanent resident. \r\nAustralian humanitarian visa holder. \r\nAn International student.', 'Up to AUD $19000 — $19,000; 22 week placement with one of the industry partners of the Faculty of Information Technology.', 'Postgraduate', 'Computing and information technology', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/information-technology-ibl-placement-grant-5607', 'https://search.studyaustralia.gov.au/scholarship/information-technology-industry-based-learning-placement-grant/c2555d01f62bade39339997977151e4a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Information Technology Industry-Based Learning Placement Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Klaus Abbink Honours Scholarship', 'This scholarship is awarded in memory of Klaus Abbink, a Professor in Economics at Monash and a Director of The Monash Laboratory for Experimental Economics (MonLEE). Professor Abbink was regarded as a great supervisor and teacher for his students, always passing on his exceptional critical thinking and research principles. He was very patient and provided consistent care and equal effort for everyone that crossed his path.', 'A student commencing a Bachelor of Commerce (Honours) or Bachelor of Economics (Honours) in the Monash Business School at a Monash campus in Australia.; WAM 80+ (Direct entry International students)', 'Up to AUD $15000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/klaus-abbink-honours-scholarship-6241', 'https://search.studyaustralia.gov.au/scholarship/klaus-abbink-honours-scholarship/4b9403abb45e443db2b08f25b43781c8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Klaus Abbink Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'MD-PhD Industry Leaders Scholarship (for returning MD-PhD students)', 'This scholarship is awarded to Monash University medical students who have demonstrated a commitment to becoming a clinician scientist by undertaking the Monash University intercalated MD-PhD pathway. The successful recipients must have been enrolled in their PhD through one of the Schools that is supporting this Scholarship*, and must have submitted their PhD thesis and returned to complete the final year of the Monash University medical degree.', 'You must meet the following criteria:; Current student enrolled in and commenced the final year (Year 5/D) of the Clayton BMedSc/MD degree (M6011 or M6018) in the Faculty of Medicine, Nursing and Health Sciences as a Monash Campus in Australia.; You must have completed BMedSc(Hons) M3701 and achieved an 80 WAM or above.; You must have undertaken the MD-PhD pathway at Monash University through one of the MNHS Schools supporting this Scholarship* AND submitted their PhD thesis for examination.', '$15,000 to be paid to students who submit their PhD thesis before the FY32 census date in the year that they return to their BMedSc/MD degree.; $7,500 to be paid to students who submit their PhD thesis between the FY32 census date and the Semester 2', 'Postgraduate', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/md-phd-industry-leaders-scholarship-for-returning-md-phd-students-6271', 'https://search.studyaustralia.gov.au/scholarship/md-phd-industry-leaders-scholarship-for-returning-md-phd-students/8d4012e53e0bdb4961c3fa1a40382705', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'MD-PhD Industry Leaders Scholarship (for returning MD-PhD students)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Master of Applied Econometrics PHD Pathway Scholarship', 'Are you passionate about econometric model building, estimation and forecasting for economic decision-making ? Elevate your career in economics with the Master of Applied Econometrics (with PhD pathway) scholarship. This prestigious opportunity is designed for aspiring professionals who seek to deepen their skills in econometrics and make a real impact in academia, industry, or public policy. Our scholarship offers financial support to exceptional candidates, allowing you to focus on gaining expertise in advanced econometric techniques, data modelling, and statistical analysis. The Master of Applied Econometrics program combines rigorous coursework with hands-on experience, equipping you with the tools to tackle complex economic and financial issues, and contribute to the policy making process.', 'You must meet the following criteria:; Commencing or continuing student enrolled in the Master of Applied Econometrics (PHD pathway) in the Department of Econometrics & Business Statistics in the Faculty of Business and Economics at the Monash Clayton campus.; WAM 80+ (Direct entry International students).', 'Up to AUD $15000', 'Postgraduate', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/master-of-applied-econometrics-phd-pathway-scholarship-6269', 'https://search.studyaustralia.gov.au/scholarship/master-of-applied-econometrics-phd-pathway-scholarship/1170085d6e389b4aed8ad34a8b6429fb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Master of Applied Econometrics PHD Pathway Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Master of Commerce Scholarship', 'The Master of Commerce is a research-oriented programme preparing students for a PhD and an academic career. Offered as part of an Integrated PhD program, the MCom may be completed in one or two years, depending on the specialisation and the student\'s prior studies. The MCom provides advanced coursework relevant to the specialisation to provide a thorough academic grounding in the skills and knowledge required to undertake original research. Upon successful completion of the MCom degree,  students who perform at the required standard and demonstrate strong research capability will progress to the PhD (3 years). The MCom is the perfect pathway to doctoral studies for students who aim to pursue an academic career.', 'You must meet the following criteria:; A current full-time Monash student or an applicant seeking to enrol full-time, in the Master of Commerce degree; You are not eligible for this scholarship if you are, or become, employed on a continuing basis or a fixed term contract for 3 months or greater.', 'Tuition fees paid, plus an allowance of $37,145 (the equivalent to the 2026 PhD stipend rate).', 'Postgraduate', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/master-of-commerce-scholarship-6161', 'https://search.studyaustralia.gov.au/scholarship/master-of-commerce-scholarship/aa1b727d7f5409312853cc1cf6622b2a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Master of Commerce Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Maxwell King PhD Scholarship', 'The Maxwell King Scholarship (MKS) is named after Professor Maxwell King, who has made an outstanding contribution to graduate research at Monash University, including eight years as Pro Vice-Chancellor (Research and Research Training). This prestigious scholarship is available to help support a student undertaking a PhD with living costs whilst studying at Monash.', 'An Australian citizen. A New Zealand citizen. Australian permanent resident. Australian humanitarian visa holder. An International student.', 'Up to AUD $52352', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/maxwell-king-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/maxwell-king-phd-scholarship/92bc4599377c09e7b7f7d3c7dcfeeb44', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Maxwell King PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Medicine and Artificial Intelligence Honours Scholarship', 'The Monash Interdisciplinary Research Academy of Medical AI (MIRAMA) is a collaborative Honours initiative that brings together expertise from the Faculty of Medicine, Nursing and Health Sciences (FMNHS), the Faculty of Information Technology (FIT), and the Faculty of Pharmacy and Pharmaceutical Sciences (FPPS). Designed for high-achieving students, MIRAMA provides a unique opportunity to undertake interdisciplinary research at the intersection of health, medicine, and artificial intelligence. Through this initiative, Honours students will engage in innovative research projects that combine biomedical science, clinical and health research, artificial intelligence, data science, and digital technologies to address some of the most pressing challenges in healthcare. Projects may explore areas such as disease mechanisms, diagnostics, therapeutics, precision medicine, healthcare delivery, and emerging digital health solutions.', 'You must meet the following criteria:; Commencing student enrolled in one of the following programs and undertaking a project from the MIRAMA program:; Faculty of Medicine, Nursing and Health Sciences (FMNHS); Bachelor of Health Sciences (Honours); Bachelor of Biomedical Science (Honours); Bachelor of Medical Science (Honours) (BMedSci (Hons)); Faculty of Information Technology (FIT); Bachelor of Computer Science (Honours); Bachelor of Computer Science (Advanced); Faculty of Pharmacy and Pharmaceutical Sciences (FPPS); Bachelor of Pharmacy (Honours); WAM 70+', 'Up to AUD $6000 — $6000 per 48 credit points of study for one year honours only.', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/medicine-and-artificial-intelligence-honours-scholarship-6301', 'https://search.studyaustralia.gov.au/scholarship/medicine-and-artificial-intelligence-honours-scholarship/84932b02ebc153f51a33ad9d84462e55', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Medicine and Artificial Intelligence Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Medicine, Nursing and Health Sciences Equity Travel Grant', 'This scholarship is available to one student enrolled in the Bachelor of Medicine and Bachelor of Surgery (MBBS) and one student enrolled in another degree in the Faculty of Medicine, Nursing and Health Sciences. It is awarded on the basis of achievement and need to students who are undertaking an elective placement in a seriously disadvantaged Australian community or developing country.', 'You must meet the following criteria:; Current undergraduate student enrolled full-time in the Faculty of Medicine, Nursing and Health Sciences* at a Monash campus in Australia.; Undertaking a clinical placement in a seriously disadvantage Australian community.', 'Up to AUD $2000 — $2000 one-off payment.', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/medicine-nursing-and-health-sciences-equity-travel-grant-5647', 'https://search.studyaustralia.gov.au/scholarship/medicine-nursing-and-health-sciences-equity-travel-grant/becfa3a1a463ae1d9c5dbb1351a2d813', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Medicine, Nursing and Health Sciences Equity Travel Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Microbiology in Water Engineering Scholarship', 'The Microbiology in Water Engineering scholarship be introduced to encourage students to begin thinking about the interdisciplinary of planetary health and in particular health related water microbiology. The scholarship will support students who are interested in the disciplines of environmental engineering (in particular, water engineering) and public health protection (in particular microbiology or epidemiology).', 'You must meet the following criteria:; A continuing Monash University undergraduate student either:; studying in their fourth year of their Bachelors of Civil or Environmental Engineering having studied or provide evidence of studying any fourth year water course (e.g. CIV4261, or CIV4281, etc.); studying a Masters of Engineering majoring in water, or; intends to or is enrolled in MIC 3990; intends to or is enrolled in honours in microbiology at Monash University.; Must be achieving a minimum 80% Weighted Average Mark', 'Up to AUD $5000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/microbiology-in-water-engineering-scholarship-6142', 'https://search.studyaustralia.gov.au/scholarship/microbiology-in-water-engineering-scholarship/25a5b7fa450695ddb4ba4eee733746b4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Microbiology in Water Engineering Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Academy of Performing Arts Orchestral Scholarship', 'The Monash Academy of Performing Arts Orchestral Scholarship intends to support and develop the student cohort of Monash Academy Orchestra.', 'You must meet the following criteria:; A commencing undergraduate student enrolled, or intending to enrol, full-time in the Bachelor of Music degree, or double degree, at a Monash campus in Australia.', 'Up to AUD $3000 — $3000 for one year only (48 credit points of study)', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-academy-of-performing-arts-orchestral-scholarship-6137', 'https://search.studyaustralia.gov.au/scholarship/monash-academy-of-performing-arts-orchestral-scholarship/e0e8e4e46a7ff1b6ee8a5b501b5bb3b0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Academy of Performing Arts Orchestral Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Graduate Impact 2030 Scholarship', 'These scholarships are awarded to students whose research aligns with one of the University Global Challenges (e.g. Thriving Communities, Climate Change and Geopolitical Security) as outlined in Impact 2030. The scholarship is available to support students with living costs whilst studying at a Monash campus in Australia.', 'You must meet the following criteria:; have submitted a scholarship application in the current year; undertaking research which aligns with one of the University Global Challenges (e.g. Thriving Communities, Climate Change and Geopolitical Security) as outlined in Impact 2030; meet Monash\'s competitive scholarship selection process requirements; meet Monash English language proficiency requirements.', 'Up to AUD $53608', 'Postgraduate', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-graduate-impact-2030-scholarship', 'https://search.studyaustralia.gov.au/scholarship/monash-graduate-impact-2030-scholarship/cfa08f43d88705c72ea8694952c68d19', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Graduate Impact 2030 Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Graduate Scholarship', 'Monash Graduate Scholarships (MGS) are provided by Monash University to support domestic and international students undertaking Research Doctorate and Research Masters degrees. A MGS is available to help support students with living costs whilst studying at Monash.', 'Applicant must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student', 'Up to AUD $36063 — $35,013 p.a (2024 rate)', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-graduate-scholarship-mgs', 'https://search.studyaustralia.gov.au/scholarship/monash-graduate-scholarship/62c7b002e2d4acfbf9f6cc5e76d9a785', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Graduate Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Humanitarian Scholarship', 'Are you an asylum seeker on a bridging visa? If you are a high-achieving student with the ambition to change your future through undergraduate study at Monash University, you may be eligible for the Monash Humanitarian Scholarship. You will receive 100% international student funding for the Monash undergraduate degree of your choice plus a yearly allowance of $6000. Monash has increased the number of these scholarships available thanks to the generous donations from Alumni and supporters of the University through the Achieving Potential fund.', 'You must meet the following criteria:; A person who is in Australia and currently on:; Temporary Humanitarian Stay visa (Subclass 449); Temporary Protection visa (Subclass 785); Temporary Humanitarian Concern visa (Subclass 786); Safe Haven Enterprise visa (Subclass 790); Bridging visa A (Subclass 010) or Bridging visa E (Subclass 050 and 051) (inactive visas included) AND have applied for a Permanent Protection visa; A commencing or continuing international student enrolled or intending to enrol in:; an undergraduate degree at a Monash University campus in Australia; a Monash University Foundation Year or Monash University Diploma through Monash College; Have achieved a minimum ATAR of 70.00, OR for current students a minimum weighted average mark (WAM) of 60, OR equivalent academic achievement.', 'Full course fees plus up to $30,000 allowance; An allowance of $6000 per year (48 credit points of study) until the minimum credit points for your undergraduate degree are completed.', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-humanitarian-scholarship-7004', 'https://search.studyaustralia.gov.au/scholarship/monash-humanitarian-scholarship/908c401e5eba11489fe72ca1ba010b3d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Humanitarian Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash International Leadership Scholarship', 'International students from all countries who have received an undergraduate course offer from Monash will automatically be considered for the Monash International Leadership Scholarship. As a scholarship recipient you will receive a 100% tuition sponsorship for the duration of your degree, and the opportunity to develop learning and leadership skills as an ambassador for Monash University.', 'You must meet the following criteria:; You must have received a full Monash course offer with no conditions; You must intend to enrol full-time in an undergraduate degree at a Monash campus in Australia; You are not eligible for this scholarship if you are:; a current Monash student.; studying an Australian Year 12. You may be eligible for the Sir John Monash Scholarship for Excellence.; are commencing in the Bachelor of Medical Science and Doctor of Medicine (MD).; in Monash Pathway programs (e.g. Monash College and Monash University Foundation Year).; transferring from another Monash campus or applying to Monash from another Australian University.', '100% course fees paid until the minimum number of points for your degree are completed (excludes OSHC, accommodation and living costs).', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-international-leadership-scholarship-5571Z', 'https://search.studyaustralia.gov.au/scholarship/monash-international-leadership-scholarship/f5ea101da8b40a1fd67a091bdad187f9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash International Leadership Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash International Merit Scholarship', 'International students from all countries who have received an undergraduate course offer from Monash will automatically be considered for the Monash International Merit Scholarship. As a scholarship recipient, you will receive $15,000 per annum for the duration of your degree.', 'You must meet the following criteria:; You must have received a full Monash course offer with no conditions; You must intend to enrol full-time in an undergraduate degree at a Monash campus in Australia; You are not eligible for this scholarship if you are:; a current Monash student; studying an Australian Year 12. You may be eligible for the Sir John Monash Scholarship for Excellence.; commencing in the Bachelor of Medical Science and Doctor of Medicine (MD).; in Monash Pathway programs (e.g. Monash College and Monash University Foundation Year).; transferring from another Monash campus or applying to Monash from another Australian University.', '$15,000 per annum (48 credit points of study) paid per year until the minimum number of points for your degree is completed (For scholarships awarded from 2026).; $10,000 per annum (48 credit points of study) paid per year until the minimum number of', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/international-merit-5770', 'https://search.studyaustralia.gov.au/scholarship/monash-international-merit-scholarship/9c276c60e8a0795f3dfabc35b7eca0ef', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash International Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash International Tuition Scholarship (MITS)', 'Monash International Tuition Scholarships (MITS) are provided by Monash University to support international students undertaking Research Doctorate and Research Masters degrees. A MITS covers the course tuition fees that would otherwise be payable by the student.', 'Applicants must: be An International student; meet Monash\'s competitive scholarship selection process requirements, AND; meet Monashs English language proficiency requirements.', 'Monash International Tuition Scholarship covers the cost of:; course tuition fees AND; a single Overseas Student Health Cover (OSHC) policy.', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/international-tuition-scholarship', 'https://search.studyaustralia.gov.au/scholarship/monash-international-tuition-scholarship-mits/10f63f3a634befc4fad139777daa4c5b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash International Tuition Scholarship (MITS)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Jazz Music Scholarship', 'A $6000 award for outstanding Monash music students specialising in jazz. This scholarship is established from funds received from an anonymous donor.', 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student; A music performance student enrolled in an undergraduate degree in the Sir Zelman Cowen School of Music and Performance.; Specialising in jazz.', 'Up to AUD $6000 — $6000 per annum (48 credit points of study) paid for a maximum of one year only.', 'Undergraduate / VET, Postgraduate', 'Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-jazz-music-scholarship-5680', 'https://search.studyaustralia.gov.au/scholarship/monash-jazz-music-scholarship/06b3d6658dba5d416d30f046987d490d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Jazz Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Mauritius Award', 'The Monash Mauritius Award provides support to new international students at Monash University, Australia.', 'You must meet the following criteria:; A new commencing student undertaking an undergraduate or postgraduate degree.; You must meet academic entry requirements and have a full offer letter to study at a Monash campus in Australia.; You are applying from Mauritius.; If you are in receipt of other scholarships or sponsorships that pay part or all of your fees you are not eligible for this scholarship.; If you have already accepted a Monash study grant and choose to accept this scholarship, the study grant will no longer be valid.', '15% or 20% tuition fee reduction applied annually for the duration of your program for up to 3 years (144 credit points).', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-mauritius-award-6308', 'https://search.studyaustralia.gov.au/scholarship/monash-mauritius-award/8f8d47f1ad71ef7d3ed46d481842401b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Mauritius Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Peer Mentoring Leaders Scholarship', 'The Peer Mentoring Leaders Scholarship is awarded to Monash Peer Mentoring Coordinators each year in recognition of their service and leadership in the peer mentoring community. Peer Mentoring Coordinators work closely with the Faculty and Portfolio of the Deputy Vice-Chancellor (Education) to manage key aspects of the program, and ensure that it meets the needs of mentors and mentees. Peer Mentoring Coordinators are involved in shaping the Peer Mentoring program and help build engagement within the Peer Mentoring community.', 'You must meet the following criteria:; A continuing coursework student enrolled in an undergraduate or postgraduate degree at a Monash campus in Australia.; Leadership potential and your willingness to share your time, skills and experiences with Peer Mentors and incoming first-year undergraduate students.; Be selected as Monash Peer Mentoring Coordinator.', 'Up to AUD $6000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-peer-mentoring-leaders-scholarship-7104', 'https://search.studyaustralia.gov.au/scholarship/monash-peer-mentoring-leaders-scholarship/487e08ef0f870d4448dcde119f5a505d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Peer Mentoring Leaders Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Philippines Award', 'The Monash Philippines Award provides support to new international students at Monash University, Australia.', 'You must meet the following criteria:; A new commencing student undertaking an undergraduate or postgraduate degree; You must meet academic entry requirements and have a full offer letter to study at a Monash campus in Australia.; You are applying from the Philippines.; If you are in receipt of other scholarships or sponsorships that pay part or all of your fees you are not eligible for this scholarship.; If you have already accepted a Monash study grant and choose to accept this scholarship, the study grant will no longer be valid.', '15% or 20% Tuition fee reduction', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-philippines-award-6306', 'https://search.studyaustralia.gov.au/scholarship/monash-philippines-award/054d46f5c7f2dfcf0024922e3f0ae638', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Philippines Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash School Award', 'The Monash School Award is awarded to the highest achieving commencing students', 'You must meet the following criteria:; Current offshore final-year high school students studying an international qualification who intend to enrol in an undergraduate degree at a Monash University campus in Australia.; Students in receipt of other scholarships or sponsorships that pay part or all of their fees are not eligible for this scholarship.; If you have already accepted a Monash study grant and choose to accept this scholarship, the study grant will no longer be valid.', 'Up to AUD $36000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-award-6208', 'https://search.studyaustralia.gov.au/scholarship/monash-school-award/270c7dee3943b7087d9f84989afe7908', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash School Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Thailand Award', 'The Monash Thailand Award provides support to new international students at Monash University, Australia.', 'You must meet the following criteria:; A new commencing student undertaking an undergraduate or postgraduate degree; You must meet academic entry requirements and have a full offer letter to study at a Monash campus in Australia.; You are applying from Thailand.; You are applying from Thailand.\r\nIf you are in receipt of other scholarships or sponsorships that pay part or all of your fees you are not eligible for this scholarship.; If you have already accepted a Monash study grant and choose to accept this scholarship, the study grant will no longer be valid.', '15% or 20% tuition fee reduction applied annually for the duration of your program for up to 3 years (144 credit points).', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-thailand-award-6307', 'https://search.studyaustralia.gov.au/scholarship/monash-thailand-award/a5dbd1ce033391824bc644c7d3a09ff4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Thailand Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash University-Vietnam Government PhD Scholarship', 'This joint scholarship program supports high-achieving Vietnamese candidates to undertake a PhD at Monash University. Applicants can elect to study at a Monash campus in Australia or be based at a Vietnamese University, jointly supervised as an external offshore candidate. The program aims to address Vietnam\'s future industry and workforce needs, prioritising key research areas such as digital technologies, physics, biotechnologies and energy & environment.', 'You must meet the following criteria:; a citizen or permanent resident of Vietnam at the time of your application; meet Monash\'s competitive scholarship selection process requirements; meet Monash English language proficiency requirements.', 'Varies - see benefits', 'Postgraduate', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-university-vietnam-government-phd-scholarship-project-89', 'https://search.studyaustralia.gov.au/scholarship/monash-university-vietnam-government-phd-scholarship/7d4f82677a5209439ad21402c5a169a6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash University-Vietnam Government PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash Yoshida Grant', 'The Monash Yoshida Grant was established to support a research trip to Japan for students undertaking honours in Japanese or Asian Studies.', 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student; Current undergraduate student enrolled in an honours degree in Japanese studies or Asian studies in the School of Languages, Cultures and Linguistics in the Faculty of Arts at a Monash campus in Australia.; Conducting research in Japan as part of the honours degree.', 'Up to AUD $6000 — $6000 one-off payment.', 'Undergraduate / VET', 'Humanities and social sciences, Languages', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-yoshida-grant-5659A', 'https://search.studyaustralia.gov.au/scholarship/monash-yoshida-grant/3af62e6abed23da2c74621938d63f66e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash Yoshida Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Monash-Pratt Musician Performance Scholarship', 'A scholarship for commencing or continuing music performance students, awarded for academic merit and outstanding musical performance.', 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student; Music performance student enrolled in an undergraduate degree in the Sir Zelman Cowen School of Music and Performance at a Monash campus in Australia.; Playing a specialised instrument as determined by the Sir Zelman Cowen School of Music and Performance.', 'Up to AUD $6000 — $6000 for one year only (48 credit points of study).', 'Postgraduate, Undergraduate / VET', 'Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-pratt-musician-performance-scholarship-5591', 'https://search.studyaustralia.gov.au/scholarship/monash-pratt-musician-performance-scholarship/a195ca90f14e4fc73660ded9fb932498', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Monash-Pratt Musician Performance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Nicholas Auden International Study Scholarship', 'This scholarship assists outstanding JD or Bachelor of Laws students to undertake an international pathway programs. The scholarship was introduced in 2014, as part of the Faculty\'s 50th anniversary celebrations.', 'You must meet the following criteria:; A continuing student enrolled full-time in either the Bachelor of Laws (LLB) (including double degrees) or the Monash Juris Doctor (JD), at a Monash campus in Australia.; Have completed all compulsory units and have only up to four elective units to complete in the Monash LLB or JD degree prior to the start of the UK academic year for which the scholarship is sought.; Be accepted into (although this acceptance may be conditional on completion of the Monash LLB or JD units to the pathway stage of the program) and enrol in one of the following approved international pathway programs:; Bachelor of Civil Law or Masters in Law and Finance at the University of Oxford (open to Monash JD students only); Master of Law or Masters Degree in Corporate Law at the University of Cambridge (open to Monash LLB and JD students); Master of Laws at the Dickson Poon School of Law, King’s College London', 'Up to AUD $10000 — $10,000 paid in one instalment for one year only. To be used only for travel and living expenses and course fees for the relevant pathway program being undertaken by the recipient.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/nicholas-auden-international-study-scholarship-5804', 'https://search.studyaustralia.gov.au/scholarship/nicholas-auden-international-study-scholarship/75926012efa2f69994eb747455c0b65b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Nicholas Auden International Study Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Pharmacy and Pharmaceutical Science International Merit Scholarship', 'This scholarship is for international students committed to studying Pharmacy or Pharmaceutical Science at Monash. It aims to attract and reward high achieving international students to the faculty.', 'You must meet the following criteria:; Commencing international student at a Monash Campus in Australia, in one of the below courses:; P2001 Bachelor of Pharmaceutical Science or P3002 Bachelor of Pharmaceutical Science Advanced (Honours); P6005** Master of Pharmaceutical Science; P6006 Master of Global Medicines Development; P6007 Pharmacy (Honours) Scholars Program/Doctor of Pharmacy', '50% of tuition fees paid per year until the minimum credit points for your degree are completed (awarded to the highest achieving student in each of the four course groups nominated).; 25% of tuition fees paid per year until the minimum credit points', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/pharmacy-international-merit-scholarship-5745', 'https://search.studyaustralia.gov.au/scholarship/pharmacy-and-pharmaceutical-science-international-merit-scholarship/55dbd648f66991b4ba6f879fb06836d6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Pharmacy and Pharmaceutical Science International Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Raydon Graduate Research Scholarships', 'These prestigious top up scholarships are available to help support graduate research students studying in relevant Humanities and Social Sciences study areas with living costs whilst studying at a Monash campus in Australia. The Raydon Scholarships are awarded in addition to a RTP Stipend or Monash Graduate Scholarship.', 'You must meet the following criteria:; have submitted a scholarship application in the current year; be undertaking research in the study areas and faculties listed below; meet Monash\'s competitive scholarship selection process requirements; meet Monash English language proficiency requirements.', 'Up to AUD $23837 — Raydon scholarships provide a living allowance top up (stipend).', 'Postgraduate', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/raydon-scholarship', 'https://search.studyaustralia.gov.au/scholarship/raydon-graduate-research-scholarships/27f14fab9b712bcc17503a8ee4a50cce', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Raydon Graduate Research Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research Training Program (RTP) Stipend', 'Research Training Program (RTP) Scholarships are provided by the Australian Government to support both domestic and international students undertaking Research Doctorate and Research Masters degrees. As part of this program, a RTP Stipend (living allowance) is available to help support domestic and international students with living costs whilst studying at Monash.', 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student', 'AUD $36063/year — The RTP Stipend provides: a living allowance (stipend), and; a relocation allowance, if eligible.', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/research-training-program-scholarship', 'https://search.studyaustralia.gov.au/scholarship/research-training-program-rtp-stipend/a691136009df231c40daa1165874ec05', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research Training Program (RTP) Stipend') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Resident Advisor Scholarship', 'This scholarship recognises the commitment to the residential community made by volunteer Resident Advisors, who live in Monash University Accommodation.', 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student', 'Up to AUD $6139 — Up to $6139', 'Postgraduate, Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/mrs-residential-advisor-scholarship-5692', 'https://search.studyaustralia.gov.au/scholarship/resident-advisor-scholarship/4667fc5cce3096f10a4ec9e530d3e786', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Resident Advisor Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Sir James McNeill Postgraduate Research Scholarship', 'The Sir James McNeill Postgraduate Research Scholarship (SJMN) is funded by a private trust and was established in memory of the late Sir James McNeill, who had a long association with Monash University. This prestigious scholarship is available for research that is both environmentally responsible and socially beneficial and helps support a graduate research student with living costs whilst studying at Monash.', 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student', 'AUD $52352/year', 'Postgraduate', 'Engineering and technology, Medicine, Sciences, Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/sir-james-mcneill-postgraduate-research-scholarship', 'https://search.studyaustralia.gov.au/scholarship/sir-james-mcneill-postgraduate-research-scholarship/81882447b252e1206c74acee276d4dbd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Sir James McNeill Postgraduate Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Sir John Monash Scholarships for Excellence', 'This scholarship is offered to the 10 highest-achieving international students studying Australian Year 12 or International Baccalaureate in Australia. If you have an ATAR of 98.00+ or equivalent, you will be automatically considered for this scholarship when you apply for a Monash undergraduate degree through VTAC.', 'Applicants must: An International student; Current Year 12 or International Baccalaureate in Australia; Intending to enrol in an undergraduate degree at a Monash campus in Australia.', 'Up to AUD $40000 — $10,000 per annum (48 credit points of study), up to a maximum of four years.', 'Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/Sir-John-Monash-Scholarships-for-Excellence-7200', 'https://search.studyaustralia.gov.au/scholarship/sir-john-monash-scholarships-for-excellence/6b759eaf690bfecebb37f8dbeadb6af3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Sir John Monash Scholarships for Excellence') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Skilled Industry Placement Scholarship', '-', 'You must meet the following criteria:; Enrolled in BRM5022 Biotechnology work-integrated learning.', 'Up to AUD $14300 — $14,300 paid in three instalments.; 24 week placement with one of the host sites in the SKILLED clinical trials internships program.', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/skilled-industry-placement-6166', 'https://search.studyaustralia.gov.au/scholarship/skilled-industry-placement-scholarship/417dffe591e56c64c8836341788f53b9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Skilled Industry Placement Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Summer and Winter Vacation Research Scholarship Program', 'Summer and winter research scholarships are run over the summer and winter breaks. If you’re interested in a research career or furthering your studies through an honours program, this is a great opportunity to get ahead over the holidays.', 'All conditions must be met: Australian or New Zealand citizen, holder of an Australian permanent resident or permanent humanitarian visa, or an international student; Currently enrolled as an undergraduate or graduate (coursework) student with a registered Australian or New Zealand provider of higher education; Normally have completed at least the second year of an undergraduate degree; Not a full-time, continuing employee of Monash University; Students enrolled in their final semester are not eligible to apply.', 'The value varies', 'Undergraduate / VET, Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/summer-winter', 'https://search.studyaustralia.gov.au/scholarship/summer-and-winter-vacation-research-scholarship-program/a4664aea66bd175ea74827decfebdc01', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Summer and Winter Vacation Research Scholarship Program') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'TNE Engineering Achievement Scholarship', 'Are you a high-achieving student from a partner university looking to pursue engineering excellence at Monash University? At Monash, we believe in recognising talent from around the world and fostering global connections in engineering education. That\'s why we\'re proud to offer this scholarship to exceptional students like you who are ready to embark on a transformative academic journey. With the TNE Engineering Achievement Scholarship, you\'ll not only receive financial support but also join a community of like-minded scholars dedicated to pushing the boundaries of engineering innovation. Whether you\'re interested in civil, mechanical, electrical, materials, chemical, or any other branch of engineering, this scholarship is your gateway to success.', 'You must meet the following criteria:; A commencing student enrolled in one of the Bachelor of Engineering programs in the Faculty of Engineering at a Monash Campus in Australia.; ATAR 90+', 'Up to AUD $6000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/tne-engineering-achievement-scholarship-6251', 'https://search.studyaustralia.gov.au/scholarship/tne-engineering-achievement-scholarship/be21cd7a9ec3f51d1f56d1b396c0a7c0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'TNE Engineering Achievement Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Team Monash Elite Student Performer Grant', 'The Team Monash Elite Student Performer Grant is designed to support talented students studying at Monash to represent the University in the areas of Sport, Performing Arts and related disciplines. This grant aims to assist students who perform at a National level or higher. Students must represent the University in a Monash Club/Society or at the Inter-University (Varsity) competitions and activities.', 'Applicants must: be Australian or New Zealand citizens, Australian permanent residents, permanent humanitarian visa holders or international students; Commencing or continuing undergraduate or postgraduate student enrolled at a Monash campus, including Monash College.; Involved in a non-professional sport, performing arts or similar, as recognised by Team Monash.', 'Up to AUD $1000 — $100 to $1000 one-off payment and/or a Monash Sport gym membership.', 'Postgraduate, Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/team-monash-elite-student-performer-grant-5609', 'https://search.studyaustralia.gov.au/scholarship/team-monash-elite-student-performer-grant/e786ac6e19aebd7eae05fc798840cd7f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Team Monash Elite Student Performer Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Koto Dream Scholarship', 'The Koto Dream Scholarship is designed to support outstanding Know One, Teaching One (KOTO) alumni who demonstrate strong academic potential, leadership capacity, and a clear commitment to social impact, enabling them to pursue undergraduate studies at Monash University overseas. This scholarship reflects Monash University\'s commitment to equity, access to education, and global social impact, while empowering first-generation learners from disadvantaged backgrounds to become future changemakers in their communities.', 'You must meet the following criteria:; An alumni of Know One, Teaching One (KOTO).; Commencing student intending to enrol full-time in an undergraduate degree at a Monash campus in Australia; Must be enrolled in one of the following areas:; Business, Management, and Economics; Communication, Media, and Social Sciences; Sustainability, Development Studies, or related disciplines', '100% tuition sponsorship for course duration (maximum of three years)', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/the-koto-dream-scholarship-6291', 'https://search.studyaustralia.gov.au/scholarship/the-koto-dream-scholarship/8090da59569ccb6f5f1cd9ea0b0c23d5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Koto Dream Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UEC Excellence Award', 'The UEC Excellence Award is awarded by Monash to three of the highest achieving commencing students from the Unified Examination Certificate (UEC) schools network in Malaysia. It underscores our commitment to seek out, reward and support students who want to change the world for the better.', 'You must meet the following criteria:; Commencing student enrolled or intending to enrol in a single or double undergraduate degree at a Monash campus in Australia.', 'Up to AUD $30000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/uec-excellence-award-6275', 'https://search.studyaustralia.gov.au/scholarship/uec-excellence-award/fcf5e27137c91c805e81be0e6545cf4e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UEC Excellence Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Verrocchi Charity Fund Pharmacy Prato Scholarship', 'The scholarship provides support to students in the Faculty of Pharmacy and Pharmaceutical Sciences undertaking an international immersion through the Monash Global Campus Intensive program in Prato. This program builds the cultural competence and global perspectives needed to deliver inclusive healthcare.', 'You must meet the following criteria:; Current student enrolled in one of the following courses at a Monash campus in Australia:; P3001 Bachelor of Pharmacy (Honours); P6001 Bachelor of Pharmacy (Honours) and Master of Pharmacy; Approved to participate in Monash Global Campus Intensives (MGCI) in Italy for PHR5052 and are:; Domestic student experiencing financial hardship or are Indigenous Australian; Domestic or International student with minimum Weighted Average Mark of 80%. (Preference will be given to students in the Dean’s Scholars Program).', 'Up to AUD $6000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/verrocchi-charity-fund-pharmacy-prato-scholarship', 'https://search.studyaustralia.gov.au/scholarship/verrocchi-charity-fund-pharmacy-prato-scholarship/6c6ccb3d8014f3573b5c71354e104f0e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Verrocchi Charity Fund Pharmacy Prato Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Vice Chancellor\'s ASEAN Award', 'The Vice-Chancellor\'s ASEAN Award supports high-achieving undergraduate students to study at Monash, reinforcing our deep commitment and connection to the region - socially, economically and culturally. The program is designed to ease the full cost of study for international students - combining tuition support, travel and relocation assistance, visa fee coverage, and other services into one bundled award.', 'You must meet the following criteria:; Commencing student intending to enrol full-time in an undergraduate degree at a Monash campus in Australia.; You must be from one of 10 ASEAN member countries: Brunei, Cambodia, Indonesia, Laos, Malaysia, Myanmar, the Philippines, Singapore, Thailand and Vietnam.', '20% tuition fees paid up to 3 years.', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/vice-chancellors-asean-award-6280', 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-asean-award/4e56d127055559ed2079efc83867e7ae', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Vice Chancellor\'s ASEAN Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Vice-Chancellor ASEAN Award for Onshore School Leavers', 'The Monash Vice Chancellor ASEAN Onshore School Leavers award for International Students celebrates high-achieving international students with nationalities from ASEAN countries enrolling in an undergraduate (coursework) degree at a Monash campus in Australia.', 'You must meet the following criteria:; Commencing student enrolled in an undergraduate degree* at a Monash campus in Australia.; ATAR of 97 and above.; You must be from an ASEAN country.; You must have received a Monash course offer.', 'Up to AUD $76719 — 20% tuition fees paid per annum for up to 3 years', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/vice-chancellor-asean-award-for-onshore-school-leavers-6286', 'https://search.studyaustralia.gov.au/scholarship/vice-chancellor-asean-award-for-onshore-school-leavers/0de72f9b5cf5ad6dc89b94c9b8f259ee', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Vice-Chancellor ASEAN Award for Onshore School Leavers') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Vice-Chancellor International School Leaver Award', 'The Monash Vice Chancellor School Leavers Award for International Students celebrates high-achieving international students enrolling in an undergraduate (coursework) degree at a Monash campus in Australia.', 'You must meet the following criteria:; Commencing student enrolled in an undergraduate degree at a Monash campus in Australia.; ATAR of 83 and above to be considered; You must have received a Monash course offer.', 'Up to AUD $15000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/vice-chancellor-international-school-leaver-award-6287AB', 'https://search.studyaustralia.gov.au/scholarship/vice-chancellor-international-school-leaver-award/750db2fb001eb3798879e83a0bcd1489', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Vice-Chancellor International School Leaver Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Wilson Transformer Company Engineering Leadership Scholarship', 'This scholarship is awarded to a high-achieving student who is currently enrolled in third year of an electrical and computer systems engineering degree in the Faculty of Engineering.', 'You must meet the following criteria:; Currently enrolled in an engineering degree in the Faculty of Engineering at a Monash campus in Australia', 'Up to AUD $20000', 'Undergraduate / VET', NULL, 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/wilson-transformer-company-scholarship-5817B', 'https://search.studyaustralia.gov.au/scholarship/wilson-transformer-company-engineering-leadership-scholarship/395f3d1570e0963592b5b4b581ad273e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00008C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Wilson Transformer Company Engineering Leadership Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australian Government Research Training Program (RTP) Scholarships', 'The Australian Government Research Training Program (RTP) stipends are provided to support the general living costs of both domestic and overseas students undertaking research doctorate degrees.', 'Please contact Bond University for further information.', 'The Australian Government Research Training Program (RTP) stipends are provided to support the general living costs of both domestic and overseas students undertaking research doctorate degrees.', 'Postgraduate, Undergraduate / VET', NULL, 'https://bond.edu.au/scholarship/australian-government-research-training-program-rtp-scholarship', 'https://search.studyaustralia.gov.au/scholarship/australian-government-research-training-program-rtp-scholarships/0ad9d3d5489dd6d6222f520cac3e7ad3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian Government Research Training Program (RTP) Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bond Business School Postgraduate Bursaries', 'The Bond Business School Postgraduate Bursaries were designed to provide financial assistance to new postgraduate students enrolling in programs within the Bond Business School. Bursaries are provided to those who can demonstrate their positive contribution to their community.', 'Please contact Bond University for further information.', 'As a Bond Business School Postgraduate Bursary recipient, you will be awarded with a cash payment of $4,200 to help with your living expenses while you study at Bond University (paid in two equal instalments).As a Postgraduate Bursary applicant, you', 'Postgraduate', 'Accounting, Business and management', 'https://bond.edu.au/scholarship/bond-business-school-postgraduate-bursaries', 'https://search.studyaustralia.gov.au/scholarship/bond-business-school-postgraduate-bursaries/3e6986bb6abf71a68dd10c3faa61904a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bond Business School Postgraduate Bursaries') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bond University Canadian Juris Doctor 25th Anniversary Scholarship', 'Bond University has proudly been training aspiring Canadian lawyers for 25 years. Since 2001, graduates have gone on to establish successful careers as legal practitioners and professionals across Canada and all over the world. To celebrate 25 years of Bond\'s Juris Doctor in Canada, we are launching the Bond University Canadian Juris Doctor 25th Anniversary Scholarship. Valued at 25% tuition remission, all Canadian students who submit an application for Bond\'s Juris Doctor, to commence in any semester between September 2025 and September 2027, will be assessed for the scholarship. The scholarship is a celebration of 25 years of history, and an investment in the future of Canadian lawyers. Earn your law degree on Australia\'s Gold Coast, at a university with strong links to Canada, a dedicated Canadian Law Program, and a truly global network.', 'To be eligible to apply for this scholarship, you must:; Be a Canadian citizen currently residing in Canada.; Have achieved predetermined academic merit in your undergraduate studies.; Meet the standard entry requirements for the Bond Juris Doctor.; May have previously completed a Bond academic or English program.', 'Valued at 25% tuition remission, all Canadian students who submit an application for Bond’s Juris Doctor, to commence in any semester between September 2025 and September 2027', 'Postgraduate', NULL, 'https://bond.edu.au/scholarship/bond-university-canadian-juris-doctor-25th-anniversary-scholarship', 'https://search.studyaustralia.gov.au/scholarship/bond-university-canadian-juris-doctor-25th-anniversary-scholarship/3d7e47e5c9ad001284c9f4008b48465c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bond University Canadian Juris Doctor 25th Anniversary Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bond University College (BUC) Academic Excellence Scholarship', 'Each semester, the Bond University College (BUC) Academic Excellence Scholarship recognises and rewards an outstanding student from the Bond University College Foundation Program (CRICOS 063151G) who has achieved exceptional academic results. The scholarship is open to international students enrolled in the Bond University College Foundation Program. Full eligibility criteria are listed below. The scholarship is awarded automatically, following an internal eligibility review conducted by Bond University College to identify the top-performing student each semester. No application is required.  Recipients receive a 25% tuition fee reduction for the duration of their undergraduate degree at Bond University, supporting a smooth and successful progression from the Foundation Program into further study.', 'To be eligible for the Bond University College (BUC) Academic Excellence Scholarship, you must:; Have completed the Bond University College Foundation Program as the top-performing student in their cohort.; Achieve a minimum Cumulative Percentage Average (CPA) of 85%.; Be transitioning into an undergraduate program at Bond University and hold a current offer for undergraduate study.', 'Provides a 25% tuition fee reduction for the duration of the recipient’s undergraduate degree at Bond University.', 'Undergraduate / VET', NULL, 'https://bond.edu.au/scholarship/bond-university-college-buc-academic-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/bond-university-college-buc-academic-excellence-scholarship/8602ae9d42fc7f787d6f3a52bd978a7b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bond University College (BUC) Academic Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bond University Postgraduate Research Scholarship', 'Bond University values its higher degree research student cohort and provides a substantial level of direct financial support to many students. Bond University allocates funds to support the financial costs of fee offset (waiver) and living stipends. A limited number of scholarships are available to domestic and overseas doctoral students who wish to continue their education through a Higher Degree Research (HDR) PhD program.  The Bond University Postgraduate Research Scholarship (BUPRS) is awarded through a competitive application process.  The Bond University HDR Scholarships Committee meets biannually to award fee waivers and living stipends based on a merit based selection process.  Students cannot apply if they are receiving an equivalent award or scholarship from the Commonwealth designed to offset HDR fees.', 'Please contact Bond University for further information.', 'See scholarship details', 'Postgraduate', NULL, 'https://bond.edu.au/scholarship/bond-university-postgraduate-research-scholarship', 'https://search.studyaustralia.gov.au/scholarship/bond-university-postgraduate-research-scholarship/d69cb51097774b390ec5a4489ea4b201', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bond University Postgraduate Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Excellence Scholarship', 'Excellence Scholarships are awarded to those who demonstrate high academic achievement, as well as leadership skills and community involvement. As an Excellence Scholar, you will be awarded with 50% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students), and will commence at Bond in either the January, May or September semester.', 'To be eligible to apply for this scholarship, you must:; Be one of the following:; an Australian or New Zealand citizen, or an Australian permanent resident currently completing or completed* Year 12 (or equivalent) inside or outside of Australia ; an Australian permanent resident completing or completed high school outside Australia; an international student completing or completed* Year 12 (or equivalent) in Australia and; Achieve a minimum of ATAR 92.00 or IB Diploma 34; Hold a demonstrated record of leadership, initiative and service to your school and/or community.; Meet the standard entry requirements for your chosen program of study.', 'Provides 50% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students).', 'Postgraduate, Undergraduate / VET', NULL, 'https://bond.edu.au/scholarship/excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/excellence-scholarship/04b0d84e6a11e7f83ad8c48c0a1e0de9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Stand Out Scholarship', 'Bond International Stand Out Scholarships provide tuition remission scholarships to standout students applying to study at an undergraduate or postgraduate level. International Stand Out Scholarships are awarded on the basis of academic merit, and are a testament to Bond University’s commitment to stand out international students.', 'Please contact Bond University for further information.', 'See scholarship details', 'Undergraduate / VET', 'Architecture, Built environment, Business and management, Communications, Tourism and hospitality, Humanities and social sciences, Law, Sport and leisure, Psychology, Sciences, Creative arts', 'https://bond.edu.au/scholarship/international-stand-out-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-stand-out-scholarship/366bce0d75dfb35a4fca71876b33e74c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Stand Out Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Undergraduate Excellence Scholarship', 'Bond International Undergraduate Excellence Scholarships provide tuition remission scholarships to high academic achievers, applying to study a bachelor’s degree.International Undergraduate Excellence Scholarships are awarded on the basis of academic merit, and are a testament to Bond University’s commitment to quality and outstanding international students.', 'Please contact Bond University for further information.', 'See scholarship details', 'Undergraduate / VET', 'Architecture, Built environment, Business and management, Communications, Health services and support, Tourism and hospitality, Humanities and social sciences, Law, Sport and leisure, Psychology, Sciences, Creative arts', 'https://bond.edu.au/scholarship/international-undergraduate-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-undergraduate-excellence-scholarship/77ce577a013d7ef213f046d81fc38e1b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Undergraduate Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Leadership Scholarship', 'Our Leadership Scholarships aim to recognise current Year 12 students who have outstanding leadership experience and community involvement with a partial-fee tuition remission scholarship. Leadership Scholarships are awarded to students who demonstrate high academic achievement, as well as outstanding leadership skills and community achievements. As a Leadership Scholar, you will be awarded with 25% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students), and can commence at Bond in either the January, May or September semester.', 'To be eligible for this scholarship, you must:; Be an Australian or New Zealand citizen, or an Australian permanent resident currently completing Year 12 (or equivalent) inside or outside of Australia OR An Australian or an Australian permanent resident completing high school outside Australia OR International students completing Year 12 (or equivalent) in Australia.; Achieve a minimum of ATAR 84.00 or IB Diploma 30.; Hold outstanding leadership, community and extra-curricular achievements, both at school and within the community.  You will be asked to provide evidence of all achievements as supporting documents in your scholarship application.; Meet the standard entry requirements for your chosen program of study.', 'Provides 25% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students).', 'Undergraduate / VET', NULL, 'https://bond.edu.au/scholarship/leadership-scholarship', 'https://search.studyaustralia.gov.au/scholarship/leadership-scholarship/2c3d0dc08136cca301fa24fde822c2b1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Leadership Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Transformer Scholarship', 'The Transformer is a co-curricular program that enable students to innovatively tackle real-world problems that matter. It attracts motivated, self-directed individuals who want to work in collaborative, interdisciplinary teams on challenging projects that typically span multiple semesters. The nature and scope of these projects are limited only by the passions and interests of the participants. Although highly motived and self-directed, Transformer participants are supported throughout the program by dedicated Bond academics and staff, industry experts, mentors, state-of-the-art facilities and other essential resources. The Transformer Scholarship is awarded to those with high potential to affect real change through participation in the Transformer program. As a Transformer Scholar, you will be awarded up to 50% tuition remission for any undergraduate degree including approved combined programs up to 320 credit points (excluding the Bond Medical Program), or postgraduate degree (excluding research degrees) and will commence your study in the following January semester. As a Transformer Scholar you will also actively participate in and complete the Transformer program during your studies at Bond.', 'To be eligible to apply for this scholarship, you must:; Have strong leadership skills, community involvement and demonstrated potential to affect change; Have had extensive involvement in extracurricular activities; Meet the entry requirements for your chosen program of study and commence in the following January semester.', 'Provides 50% tuition remission for any undergraduate degree including approved combined programs up to 320 credit points (excluding the Bond Medical Program), or postgraduate degree (excluding research degrees).', 'Postgraduate, Undergraduate / VET', NULL, 'https://bond.edu.au/scholarship/transformer-scholarship', 'https://search.studyaustralia.gov.au/scholarship/transformer-scholarship/6cd63fc716f51561b68ab9a2d965d31d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00017B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Transformer Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'IB Diploma', 'Scholarships available for RMSC students in year 11 from 2022', 'Roma Mitchell Secondary College seeks aspirational young women and men with a diversity of interests, abilities, backgrounds and a natural curiosity of the world. The College invites prospective and current students to apply for Scholarships to undertake the International Baccalaureate program.Roma Mitchell Secondary College will offer fully funded Scholarships to those students who have a demonstrated ability and who embody the RMSC values of excellence, respect and diversity within an overall commitment to contribute to our community. Scholarships will be awarded to students based on academic achievement and a commitment to complete all the requirements of the International Baccalaureate program.Special consideration will be given to all or any of the following factors:Social and cultural diversity; Ability in demonstrating resilience;Financial need.', 'AUD $1500/year — AUD $1500 cost is for the 2 year Diploma. The cost covers student subject and registration fees which are paid to the IBO', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/ib-diploma/3006f5822ee407b8a9608c894608a13e', 'https://search.studyaustralia.gov.au/scholarship/ib-diploma/3006f5822ee407b8a9608c894608a13e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00018A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'IB Diploma') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Regional bursary for TAFE international students', 'Your adventure awaits! Enjoy long stretches of perfect coastline in the mid west, forests and mountains in the south west, or tropical deserts and sandy beaches in the north. The WA Regional TAFE International Student Bursary gives international students a unique experience of life in beautiful regions of WA, while receiving high quality education and training.', 'To be eligible for application and bursary payments, students must:; be a genuine international student intending to study on a subclass 500 visa. Must provide proof to TIWA Admissions of either:; 1) student visa grant; 2) student visa application; commence in 2026; maintain a continuous enrolment over at least one year in a valid regional course pathway; maintain ongoing residency in the nominated regional location for the duration of your bursary period; meet academic and English language requirements prior to commencement of each course; understand the bursary will be paid to awarded students in one of two ways, either as:; two payments ($2,500 each semester, with the first payment approximately six weeks after the start of first semester); one payment ($5,000 in second semester); meet financial requirements and obligations for the course without needing or relying on the bursary for tuition fees, resource fees, and/or material fees.', 'Up to AUD $5000', 'Undergraduate / VET', NULL, 'https://www.tafeinternational.wa.edu.au/tafe-courses/regional-bursary-tafe-international-students?', 'https://search.studyaustralia.gov.au/scholarship/regional-bursary-for-tafe-international-students/c1c324b016877c57778c21562aed0d16', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00020G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Regional bursary for TAFE international students') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'A.G. McCready Memorial Scholarship', 'Established in 1996 by Mrs I.C. McCready in memory of her late husband Alfred Glen McCready, who was admitted to the degree of Bachelor of Arts with First Class Honours in Classics and awarded the University Medal for outstanding merit in 1940 and who lectured in Classics with The University of Queensland, 1946-49. The scholarship is maintained by the income of the fund established by a gift of $30,000 from Mrs I.C. McCready, Mr W.K. Lam and Dr L.L. Chan.', 'Applicants must: have completed the requirements for the Bachelor of Arts program at UQ; are enrolled either full-time or part-time, in an postgraduate BA honours program in Classical Languages at UQ.', 'Equal to the annual income from the fund', 'Undergraduate / VET, Postgraduate', 'Humanities and social sciences', 'https://scholarships.uq.edu.au/scholarship/ag-mccready-memorial-scholarship', 'https://search.studyaustralia.gov.au/scholarship/ag-mccready-memorial-scholarship/27ebdf998171132b0d4c133511d58400', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'A.G. McCready Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alumni Pride Scholarship', 'Established in 2024 through a gift from Alumni Friends, Professor Heather Zwicker and collective donors under the Queensland Commitment scheme and maintained by income generated from an underlying endowment fund. Alumni Friends of The University of Queensland dates back to 1967, when UQ sponsored the formation of an association to foster relationships with UQ alumni.', 'Youre eligible if you: are or will be enrolled in an Approved Program; can demonstrate and provide documentary evidence of financial hardship; identify as a member of the LGBTQIA+ community and; have not previously held the Scholarship.', 'Up to AUD $4500 — $4,500 (limited to the annual income from the fund)', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/alumni-pride-scholarship', 'https://search.studyaustralia.gov.au/scholarship/alumni-pride-scholarship/b33d8efc5edc0eac217cfd8771388f21', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alumni Pride Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Archibald Scholarship', 'This scholarship was founded in 1911 by an initial gift of $1,000 from the beneficiaries in the estate of the late Honourable John Archibald, MLC.', 'Applicants must: the Bachelor of Economics (Honours) (as a commencing student); the Bachelor of Advanced Finance and Economics (Honours) with an economics major (and completed 48 units); have achieved a Grade Point Average of at least 6.5 across these undergraduate economics courses; do not hold another scholarship that is considered similar.', 'Up to AUD $10000 — The scholarship is valued at $10,000 for 1 year.', 'Undergraduate / VET', 'Business and management, Economics', 'https://scholarships.uq.edu.au/scholarship/archibald-scholarship', 'https://search.studyaustralia.gov.au/scholarship/archibald-scholarship/6c9a264bdb0c74bd7aedb2d703defe16', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Archibald Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Au Family Scholarship', 'Established in 2025 through an absolute gift from the Au Family.', 'You\'re eligible if you:; are enrolled in any program at UQ in the year of the award; can demonstrate financial hardship by providing documentary evidence.', 'Up to AUD $6300', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/au-family-scholarship', 'https://search.studyaustralia.gov.au/scholarship/au-family-scholarship/c7efe9381a9887ddbd4f5fe872e60fb4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Au Family Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Barbara Hebden Music Bursary', 'This scholarship was established in 2016 by an endowed bequest from the estate of UQ alumna and music critic, Barbara Jean Hebden OAM (BA 1952).', 'will be enrolled full-time in the first year of the Bachelor of Music (Honours).', 'Equal to the annual income from the fund.', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/barbara-hebden-music-bursary', 'https://search.studyaustralia.gov.au/scholarship/barbara-hebden-music-bursary/4b942c0a078b5a46c4c9500548379d48', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Barbara Hebden Music Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Business Scholarship for Chinese Students', 'Established in 2013 by the Chin Family Trust.', 'You\'re eligible if you are:; an international student; a citizen of the People\'s Republic of China; enrolled full-time in any undergraduate or postgraduate coursework program approved by the UQ Business School.', 'Up to AUD $1000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/business-scholarship-chinese-students', 'https://search.studyaustralia.gov.au/scholarship/business-scholarship-for-chinese-students/be9eb18703b5f365bb69d9ce0e706d16', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Business Scholarship for Chinese Students') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Business School Honours Tuition Fee Reduction Scholarship', 'The purpose of this scholarship is to attract and encourage high-achieving students to the Business School Honours program.', 'You\'re eligible if you:; are a domestic or international student; do not already have external sponsorship for the program (i.e. other scholarships, private sponsor)', 'Up to AUD $10000', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/business-school-honours-tuition-fee-reduction-scholarship', 'https://search.studyaustralia.gov.au/scholarship/business-school-honours-tuition-fee-reduction-scholarship/a94045f96fa1ac4b9afedb685331844e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Business School Honours Tuition Fee Reduction Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Business School Master of Business Analytics - Women in STEM Scholarship', 'The Postgraduate Coursework Master’s Scholarship was established to encourage and support high performing women to undertake postgraduate study related to digital transformation, thus retaining and improving the representation of women in the STEM workforce.', 'You\'re eligible if you:; intend to commence the Master of Business Analytics program during the 2027 academic year; are a female student; provide a personal statement as outlined in \'How to apply\'; provide a CV.', 'Up to AUD $5000', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/scholarship/business-school-master-business-analytics-women-stem-scholarship', 'https://search.studyaustralia.gov.au/scholarship/business-school-master-of-business-analytics-women-in-stem-scholarship/43170c7caa63936b34be578120c3819c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Business School Master of Business Analytics - Women in STEM Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'CONACYT Mexican Scholarship Program', 'The CONACYT Mexican Scholarship aims to provide Mexican citizens with funding to support studies overseas at the point of admission or while they are undertaking studies abroad to enhance their skills in areas of Science, Technology and Innovation and contribute back to Mexico and form linkages with global partner institutions.', 'be a citizen of Mexico; have applied for a Masters or PhD program at UQ; satisfy the general and specific requirements and been awarded the CONACYT scholarship; meet the academic requirements for entry to UQ and been offered a place in the program; commence full-time enrolment as an onshore international student at UQ.', 'Partially funded tuition fees, living allowance; Master maximum 2 years, PhD maximum 4 years', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/scholarship/conacyt-mexican-scholarship-program', 'https://search.studyaustralia.gov.au/scholarship/conacyt-mexican-scholarship-program/1a2d54af5e9fa9008f94a833ad5d5876', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'CONACYT Mexican Scholarship Program') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'CSC-UQ PhD Scholarship (China Scholarship Council)', 'Successful applicants who are offered a place in the University\'s PhD program and are supported by their School will also receive a Tuition Fee Scholarship (for up to four years) that covers your PhD tuition fees, along with a living allowance top up to the standard UQ RTP stipend rate.', 'To apply for this scholarship, you must:; be a citizen and permanent resident of the People’s Republic of China; be eligible to receive an Australian Student Visa; satisfy the selection criteria set by the CSC; satisfy UQ\'s admissions entry requirement and be offered a place in the PhD program; meet the University\'s English proficiency requirement; have a financial commitment for your proposed advisor to top up the CSC living stipend to UQ\'s minimum rate for the duration of your program.', 'Living allowance, health insurance in Australia, one return airfare from China to Australia, your Australian Student Visa application fees, and a UQ tuition fee scholarship', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/csc', 'https://search.studyaustralia.gov.au/scholarship/csc-uq-phd-scholarship-china-scholarship-council/e91bed66071a2584809adbb85d52a73b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'CSC-UQ PhD Scholarship (China Scholarship Council)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Calboonya Legacy Information Technology and Computer Science Scholarship', 'Established in 2019 this scholarship is maintained by a gift from a UQ Bachelor of Computer Science (1979) alumni husband and wife, who in recognition of the encouragement they received to pursue their education would like to leave a legacy for students who may not otherwise have the opportunity to study in the areas of computer science and information technology at UQ.', 'You\'re eligible if you:; are a commencing student or a prior recipient of this scholarship; can demonstrate financial need; do not hold a scholarship that the Associate Dean considers to be similar.', 'Up to AUD $4500', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/calboonya-legacy-information-technology-and-computer-science-scholarship', 'https://search.studyaustralia.gov.au/scholarship/calboonya-legacy-information-technology-and-computer-science-scholarship/c3cb1ec2882d72f8df98bd49a146b06f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Calboonya Legacy Information Technology and Computer Science Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Florence Davey Pianoforte Scholarship', 'This Scholarship was first established in 1983 and was funded by donations in excess of $50,000 from Miss Florence M. Davey. The Scholarship fund continues to be maintained by UQ on trust. Miss Florence M. Davey, Associate, Licentiate and Fellow of Trinity College of Music, London, taught music until the age of 90 and was dedicated to the pursuit of excellence in piano performance.', 'You\'re eligible if you:; will be enrolled full-time in the first year of the Bachelor of Music or a dual program that includes the Bachelor of Music.', 'AUD $10000/year', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/florence-davey-pianoforte-scholarship', 'https://search.studyaustralia.gov.au/scholarship/florence-davey-pianoforte-scholarship/9d88a2e71fbde7edb604da4b18c13b77', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Florence Davey Pianoforte Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Graduate School Scholarships (UQGSS) - includes Research Training Program (RTP)', 'These scholarships include a living stipend to support you as you complete a research project for your Doctor of Philosophy, Master of Philosophy or a research-focused professional doctorate at UQ.', 'nominated by an enrolling school or institute at UQ; assessed by the Graduate School as meeting all conditions for admission to the higher degree by research program.; not be receiving a living allowance award, or scholarship providing a benefit greater than 75% of the RTP Scholarship living allowance rate to undertake the higher degree by research program', 'AUD $35000/year — 3.5 years with the possibility of 1 extension in line with UQ and RTP Scholarship Policy', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/scholarship/graduate-school-scholarships-uqgss-%E2%80%93-includes-rtp', 'https://search.studyaustralia.gov.au/scholarship/graduate-school-scholarships-uqgss-includes-research-training-program-rtp/f5df9f90bf0ba0d0645d46fa67a90dc4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Graduate School Scholarships (UQGSS) - includes Research Training Program (RTP)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Howard and Gladys Sleath Scholarship', 'Established in 1998 following Howard Sleath\'s bequest of 50% of his estate to the University of Queensland. Mr Howard Sleath was well-known to instrumentalists throughout Australia for the excellence of his craftsmanship and skill as a maker of stringed instruments. Mr Sleath gave the State of Queensland a string quartet of instruments to be kept under the supervision of the Head of the School of Music. The instruments were first demonstrated by the Mayne String Quartet at a concert to inaugurate the Howard Sleath Quartet of Instruments in 1974.', 'Applicants must: will be enrolled full-time in the first year of the Bachelor of Music (Honours).', 'Up to AUD $10000 — Equal to the annual income from the fund.', 'Undergraduate / VET', 'Creative arts', 'https://scholarships.uq.edu.au/scholarship/howard-f-and-gladys-sleath-scholarship', 'https://search.studyaustralia.gov.au/scholarship/howard-and-gladys-sleath-scholarship/f1e632e427db4cdefa35389622f67837', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Howard and Gladys Sleath Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International House Global Residency Scholarship', 'Established in 2024 by a gift from International House at The University of Queensland.', 'You\'re eligible if you are or will be:; an international student in accordance with the University’s Fee Policy in the year of the award; enrolled full-time in an Approved Program in the year of the award; a resident at International House in the year of the award.', 'Up to AUD $28000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/international-house-global-residency-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-house-global-residency-scholarship/47241767968f4d1f83e5d430f3b22144', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International House Global Residency Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Scholarship', 'This scholarship was established in 2020 under the Create Change Match Initiative and is maintained by the income generated from an endowment fund established by a donation from Suan Yeo.', 'You\'re eligible if you:; are an international student in accordance with the University\'s Student Fees Policy; can demonstrate temporary and unexpected financial hardship; are enrolled full-time in any undergraduate program in the year of the award; have not received assistance from the Financial Hardship Assistance Scheme for the year of award; have not been awarded another scholarship, bursary or grant that the Chair considers similar.', 'Limited to the annual income from the fund.', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/international-student-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarship/f8d6bb558656d4b792355dad6232732f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'MBA Student Scholarship - International', '-', 'You\'re eligible if you:; are offered a place in MBA program or GCBA articulation pathway to the MBA; are an international student.', 'See scholarship details', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/scholarship/mba-student-scholarship-international', 'https://search.studyaustralia.gov.au/scholarship/mba-student-scholarship-international/cac7afb08ccc93e809cfaac7da62dacf', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'MBA Student Scholarship - International') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Mary Alison Miles Munro Scholarships', 'The scholarship was founded in 1936 by gifts of $1,500, $1,000, and $1,000 from Mr Simon Edwin Munro, Mrs Helena Mary Whitehouse, and Mrs Jessie Hamon respectively, in memory of Mrs Mary Alison Miles Munro.', 'Applicants must: are commencing the second year of a program, including a dual program, administered by the Faculty of Humanities and Social Sciences; have completed at least one modern foreign language course in semester 1 and semester 2 in the year immediately prior; have passed at least 8 units for other courses (if full-time) or at least 4 units for other courses (if part-time), in the year immediately prior to the year the scholarship is awarded.', 'Up to AUD $300 — The scholarship is valued at $300 for 1 year.', 'Undergraduate / VET', 'Languages', 'https://scholarships.uq.edu.au/scholarship/mary-alison-miles-munro-scholarships', 'https://search.studyaustralia.gov.au/scholarship/mary-alison-miles-munro-scholarships/3060e98d14a33ab5069418a86e8407f8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Mary Alison Miles Munro Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Master of Business Analytics Financial Hardship Scholarship', 'Established in 2022 by UQ Business School to encourage and support students in the Graduate Certificate in Business Analytics and Master of Business Analytics programs.', 'You\'re eligible if you:; are enrolled or intend to enrol in the Graduate Certificate in Business Analytics or Master of Business Analytics, in the semester of the award; can provide documentary evidence of financial hardship; do not hold a scholarship that the Head considers to be similar; submit an application to the Head, by the closing date', 'Up to AUD $5000', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/scholarship/master-business-analytics-financial-hardship-scholarship', 'https://search.studyaustralia.gov.au/scholarship/master-of-business-analytics-financial-hardship-scholarship/fcdeb4b05a19d787237af5d49435dd58', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Master of Business Analytics Financial Hardship Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Master of Finance and Investment Management Outstanding Women Scholarship', '-', 'You\'re eligible if you:; are a female; intend to commence or have commenced in the Master of Finance and Investment Management program during the 2027 academic year.', 'Up to AUD $10000', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/scholarship/master-finance-and-investment-management-outstanding-women-scholarship', 'https://search.studyaustralia.gov.au/scholarship/master-of-finance-and-investment-management-outstanding-women-scholarship/7e56e985efe0285cbd52022e57214b71', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Master of Finance and Investment Management Outstanding Women Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Paula and Tony Kinnane Music Scholarship', 'The scholarship was established in 2016 and is maintained by the income of a perpetual endowment fund from a bequest to The University of Queensland under the will of Paula Ruth Kinnane, who graduated from The University of Queensland in 1991 with a Bachelor of Arts degree.', 'You\'re eligible if you:; will be enrolled full-time in the first year of the Bachelor of Music or a dual program that includes the Bachelor of Music.', 'AUD $10000/year', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/paula-and-tony-kinnane-music-scholarship', 'https://search.studyaustralia.gov.au/scholarship/paula-and-tony-kinnane-music-scholarship/f170ee0b21518c6fdff9bce9356f22b2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Paula and Tony Kinnane Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Project 89-UQ Scholarship', 'Project 89 is a Vietnamese Government initiative that builds capacity and academic expertise among Vietnamese university lecturers and senior leaders. The Australian Government supports the delivery of this initiative.', 'You will be eligible for this scholarship if you:; are a citizen of Vietnam; satisfy the selection criteria set by Vietnam government scholarship (Project 89); satisfy UQ\'s admissions entry requirement and be offered a place in the PhD program; meet the University\'s English proficiency requirement.', 'Living allowance, health insurance in Australia, one return airfare from Vietnam to Australia, and tuition fees', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/scholarship/project-89-uq-scholarship', 'https://search.studyaustralia.gov.au/scholarship/project-89-uq-scholarship/4ee95a68bbe7db4e6fd4f529e1c6ff59', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Project 89-UQ Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Qin Sirong and Yin Hongxiu Scholarship', 'The purpose of the scholarship is to encourage and support Chinese students who enrol in a Masters postgraduate coursework program of up to 32 units offered by the Faculty of Business, Economics and Law at the University of Queensland.', 'You\'re eligible if you:; completes the scholarship application form by the due date; has submitted an application to study an Approved Program at UQ; \r\nis an international student in accordance with The University\'s Fee Policy; is a citizen of China; is not in receipt of another UQ scholarship.', 'See scholarship details', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/scholarship/qin-sirong-and-yin-hongxiu-scholarship', 'https://search.studyaustralia.gov.au/scholarship/qin-sirong-and-yin-hongxiu-scholarship/5ad748636e7885818aa3a729fd1af9a1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Qin Sirong and Yin Hongxiu Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research project scholarship', 'This scholarship supports you to complete a higher degree by research while focusing on a specific project.', 'You\'re eligible if you meet:; the entry requirements for the relevant program:; Doctor of Philosophy (PhD) program; Master of Philosophy (MPhil) program; any specific requirements of the project.', 'AUD $39220/year', 'Postgraduate', NULL, 'https://scholarships.uq.edu.au/scholarship/research-project-scholarship', 'https://search.studyaustralia.gov.au/scholarship/research-project-scholarship/1f7fa12f35919b4485d2e38f60c13808', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research project scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Robert and Mary MacMillan Bursary', 'Established in 1972 by a bequest of the sum of $20,000 under the will of the late Robert Edward Leslie Macmillan, Fitter and Turner of Brisbane, who died in September 1970.', 'Applicants must: can demonstrate financial hardship; are enrolled full-time in the Bachelor of Engineering (Honours) or Bachelor of Engineering (Honours)/ Master of Engineering or dual engineering program; have completed between 28 - 44 units towards the Approved Program; are not less than 23-years-old in the year the bursary is awarded.', 'One half of annual income from endowment', 'Undergraduate / VET', 'Engineering and technology', 'https://scholarships.uq.edu.au/scholarship/robert-and-mary-macmillan-bursary', 'https://search.studyaustralia.gov.au/scholarship/robert-and-mary-macmillan-bursary/e164260ca552a1cf78726114a34940f0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Robert and Mary MacMillan Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Kym Broadhurst Bursary for the Visually Impaired', 'This scholarship was established in 2000 and is maintained by gifts from the family of Kym Broadhurst, to encourage excellence in undergraduate or postgraduate study for visually impaired students.', 'You\'re eligible if you:; are visually impaired (corrected vision must be less than 6:60); enrolled in an undergraduate or postgraduate program', 'Currently held in tenure until 2028.', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/kym-broadhurst-bursary-visually-impaired', 'https://search.studyaustralia.gov.au/scholarship/the-kym-broadhurst-bursary-for-the-visually-impaired/4dfb5e036799a167b0c4214b472e2195', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Kym Broadhurst Bursary for the Visually Impaired') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Neil Brice Memorial Fund', 'This scholarship was established in 1974 with a fund of $5,200 raised by public subscription in memory of Neil Mather Brice, DSc, who at the time of his death was Professor of Electrical Engineering at Cornell University, New York, USA.', 'You\'re eligible if you:; have the academic ability to complete your chosen program; can demonstrate financial need.', 'Up to AUD $1000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/neil-brice-memorial-fund', 'https://search.studyaustralia.gov.au/scholarship/the-neil-brice-memorial-fund/437da675f69e7bef70e469a7080480bf', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Neil Brice Memorial Fund') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ English Language Scholarship', '-', 'You\'re eligible if you:; are an international student.; And you:; have applied to study full-time at UQ commencing in 2027 or 2028 in a coursework program, and are being considered for a package offer that includes Bridging English at UQ College.; have met the academic requirements for admission to UQ but need to meet the English Language Proficiency requirements.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-english-language-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uq-english-language-scholarship/72aa71f123ced5a1633306051be7d45c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ English Language Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ Excellence Scholarship', 'UQ Excellence Scholarship is part of the UQ Academic Scholarship program. This scholarship was established in 2008 and is maintained by funds from The University of Queensland and donors.', 'You\'re eligible if you:; achieve a minimum unadjusted ATAR of 99.00 (or equivalent); complete Year 12 in 2026 or 2025 (if you\'re on a gap year).', 'Up to AUD $6000', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uq-excellence-scholarship/313366b7fda6224a099b7f2ba61bdaa6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ Faculty International Scholarship', '-', 'UQ offers faculty-specific international scholarships across all study areas:; Faculty of Business, Economics and Law International Scholarship; Faculty of Science International Scholarship; Faculty of Health, Medicine and Behavioural Sciences International Scholarship; Faculty of Engineering, Architecture and Information Technology International Scholarship; Faculty of Humanities, Arts and Social Sciences International Scholarship', '10% reduction in tuition fees per semester', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-faculty-international-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uq-faculty-international-scholarship/a8cefadcd8d2f069943b66d7c3339003', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ Faculty International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ Firebirds Scholarship', 'This scholarship was established in 2019 and is maintained through annual funding from Queensland Firebirds and UQ Marketing and Communications.', 'You\'re eligible if you:; are a Commencing Student; are or will be enrolled full-time in an undergraduate program; can demonstrate financial hardship by providing documentary evidence; can demonstrate that you have played netball for school or a club, or contributed to the sport of netball through coaching or volunteering within the two year period prior to the year of the award.', 'Up to AUD $5000', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-firebirds-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uq-firebirds-scholarship/0345f6cf4403da0b9156cffc906c7790', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ Firebirds Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ International Excellence Scholarship', 'If you are eligible, we will notify you that youre offered this scholarship together with your letter of offer to study at UQ. In this notification, we will let you know what date you have to accept the scholarship by. If youre awarded the scholarship, the 25% tuition fee reduction will be applied prior to the tuition fees due date each semester.', 'Youre eligible if you: are an international student.; have received an unconditional offer to study full-time at UQ commencing Semester 1 or 2, 2025 in an eligible program.; have satisfied the program entry rank and English language proficiency requirements.; have achieved a competitive score as determined by the University among the pool of offer holders for programs in their commencement semester.; will enrol full-time.', '25% reduction in tuition fees per semester', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-international-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uq-international-excellence-scholarship/a16b45772e886725d731a46c10d7ef23', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ International Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ International High Achievers Scholarship', '-', 'You\'re eligible if you:; are an international student.; And you:; have applied to study full-time at UQ commencing in 2027 in an eligible program.; have satisfied all the conditions of the program offer.; have satisfied the program entry rank and English language proficiency requirements.; have achieved a competitive score as determined by the University among the pool of offer holders for programs in their commencement semester.', '20% reduction in tuition fees per semester', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-international-high-achievers-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uq-international-high-achievers-scholarship/1cea5ad6c9d8a8e963ed201d639332ff', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ International High Achievers Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ LGBTQIA+ Scholarship', 'This scholarship was established in 2013 and maintained by gifts from donors including UQ staff, alumni and friends.', 'You\'re eligible if you:; identify as a member of the LGBTQIA+ community; are or will be enrolled in an Approved Program in the semester of the award; can demonstrate financial hardship by providing documentary evidence; can demonstrate commitment to the LGBTQIA+ community; have not previously received the scholarship.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-lgbtqia-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uq-lgbtqia-scholarship/549ec1350ed90d20add9c4fec76bd39f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ LGBTQIA+ Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ Lifelong Learner: reduced fees for UQ alumni', '-', 'You\'re eligible if you:; are an international student.; And you:; have completed a Bachelor level degree or higher at The University of Queensland (at least 16 units) or at least 16 units of a Study Abroad program.; have applied to study full-time at UQ commencing in 2027 in an eligible program.; have satisfied the program entry rank and English language proficiency requirements (if required).; have satisfied all the conditions of the program offer.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-lifelong-learner-reduced-fees-uq-alumni', 'https://search.studyaustralia.gov.au/scholarship/uq-lifelong-learner-reduced-fees-for-uq-alumni/747ebce73eaf61735196b82d5ea07985', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ Lifelong Learner: reduced fees for UQ alumni') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ Refugee and Humanitarian Scholarship', 'The UQ Refugee and Humanitarian Scholarship is funded by The University of Queensland (UQ). Established in 2021, this Scholarship offers students from refugee or asylum seeker backgrounds the opportunity to pursue higher education in any desired discipline at UQ.', 'You\'re eligible if you:; are or will be enrolled in an undergraduate or postgraduate coursework program at UQ; hold one of the following Australian visas:; Temporary Protection Visa (subclass 785), Safe Haven Enterprise Visa (subclass 790), Temporary Humanitarian Concern Visa (subclass 786), Temporary Humanitarian Stay Visa (subclass 449); any other similar visa from time to time that the Australian government might enact for people from refugee or asylum seeker backgrounds; Bridging Visa E (subclass 050) or Bridging Visa A (subclass 010) if you have applied for any of the above-mentioned visas.; have not received the Scholarship previously for the same level of study; do not hold another similar scholarship; can demonstrate financial hardship by providing documentary evidence.', '100% tuition fee waiver, plus $29,000 annual living stipend', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-refugee-and-humanitarian-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uq-refugee-and-humanitarian-scholarship/a03cb0f1a4818f2257bdb03315996801', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ Refugee and Humanitarian Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UQ Vice-Chancellor\'s Scholarship', 'UQ Vice-Chancellor\'s Scholarship is part of the UQ Academic Scholarship program. The scholarship was established in 2009 and is maintained by funds from The University of Queensland and donors.', 'You\'re eligible if you:; achieve a minimum unadjusted ATAR of 99.90 (or equivalent); complete Year 12 in 2026 or 2025 (if you’re on a gap year).', 'Up to AUD $60000', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/uq-vice-chancellors-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uq-vice-chancellors-scholarship/a2185a8479b16679337e82d56716d8cd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UQ Vice-Chancellor\'s Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'University of Queensland and St Leo\'s College Music Achievement Scholarship', 'The scholarship was established in 2009 for the purpose of encouraging meritorious students who are enrolled in studies in music and are residents of St Leo\'s College. The scholarship is maintained by an annual gift from The University of Queensland in the form of a contribution to the residential fees payable by such a student (or students) and an annual gift from St Leo\'s College in the form of a reduction in those fees.', 'You\'re eligible if you\'re:; enrolled full-time in the Bachelor of Music or a dual program that includes the Bachelor of Music or a program that includes a Music Course in each semester for the year; a resident at St Leo\'s College.', 'Up to AUD $6000', 'Undergraduate / VET', NULL, 'https://scholarships.uq.edu.au/scholarship/university-queensland-and-st-leos-college-music-achievement-scholarship', 'https://search.studyaustralia.gov.au/scholarship/university-of-queensland-and-st-leos-college-music-achievement-scholarship/e0c9ce9b479c04309f01ca23fb005168', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00025B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'University of Queensland and St Leo\'s College Music Achievement Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'AR Davis Postgraduate Research Memorial Scholarship', 'This scholarship aims to assist PhD students in Chinese Studies and Japanese Studies.', 'You must:; be enrolled in a PhD in Chinese Studies or Japanese Studies within the School of Languages and Cultures.', 'Up to AUD $5000', 'Postgraduate', NULL, 'https://www.sydney.edu.au/scholarships/b/ar-davis-postgraduate-research-memorial-scholarship.html', 'https://search.studyaustralia.gov.au/scholarship/ar-davis-postgraduate-research-memorial-scholarship/e5b60a43172edc21a76da5225013ed38', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'AR Davis Postgraduate Research Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Agnes Campbell Research Scholarship', 'USYD RTP rate stipend scholarships towards living expenses for a PhD student undertaking research in chemistry, with preference for organic chemistry.', 'You must:; be a domestic or international student; have an unconditional offer of admission or be enrolled in a full-time PhD at the Faculty of Science; be willing to research involving organic chemistry; hold an honours degree (first class or second class upper) or a masters degree in a related field with a substantial research component', 'AUD $41753/year — $41,753 p.a. (up to 3.5 years)', 'Postgraduate', NULL, 'https://www.sydney.edu.au/scholarships/d/agnes-campbell-research-scholarship.html', 'https://search.studyaustralia.gov.au/scholarship/agnes-campbell-research-scholarship/5a554b200894fe2c8c164740edf4913e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Agnes Campbell Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Edna Briggs Scholarship in Physics', 'This scholarship aims to support students undertaking studies in physics at the University of Sydney.', 'Enrolled full-time in second year in an undergraduate Science degree; Enrolled in at least 12 credit points of 2000 level Physics units of study; Achieved the highest average mark 12 credit points of Physics units', 'Up to $4,500 for one year', 'Undergraduate / VET', NULL, 'https://www.sydney.edu.au/scholarships/d/edna-briggs-scholarship-in-physics.html', 'https://search.studyaustralia.gov.au/scholarship/edna-briggs-scholarship-in-physics/ca8ca55fbe817bcf54f40636186443ac', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Edna Briggs Scholarship in Physics') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Elvita Eveline Clough Cancer Research Scholarship', 'Stipend scholarship to support PhD students within the Faculty of Medicine and Health.', 'You must:; have an unconditional offer of admission or be currently enrolled to study full-time in a PhD within the Faculty of Medicine and Health at the University of Sydney; not have completed more than four (full-time equivalent) research periods of candidature at the time of application; conduct research in prevention, early detection or more effective treatment of breast cancer; not hold or have been offered another Higher Degree by Research primary stipend scholarship administered by the University of Sydney at the time of application.', 'The Scholarship will provide a stipend allowance equivalent to the University of Sydney Research Training Program (RTP) Stipend rate (indexed on 1 January each year) up to 3.5 years, subject to satisfactory academic performance.', 'Postgraduate', NULL, 'https://www.sydney.edu.au/scholarships/c/elvita-eveline-clough-cancer-research-scholarship.html', 'https://search.studyaustralia.gov.au/scholarship/elvita-eveline-clough-cancer-research-scholarship/36d9be9677c50c80644ffa229c5c40bf', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Elvita Eveline Clough Cancer Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Emilie M Schweitzer Scholarship in French and Germanic Studies', 'A French and Francophone Studies and Germanic Studies scholarship that supports high-achieving students.', 'You must:; be currently enrolled in 4000-level units of study within the Faculty of Arts and Social Sciences in one of the following:; Bachelor of Arts (Languages), Bachelor of Arts and Bachelor of Advanced Studies, Bachelor of Arts and Bachelor of Advanced Studies (Languages), Bachelor of Arts (Honours) OR; have completed a Bachelor of Arts with a major in French and Francophone Studies or in Germanic Studies at the University of Sydney or another University and having an unconditional offer of admission and subsequently enrol in 4000-level units of study within the Faculty of Arts and Social Sciences in one of the following:; Bachelor of Arts (Honours), Bachelor of Advanced Studies (Honours).; be majoring in French and Francophone Studies or in Germanic Studies.; have received an average of 70% in six units of study in French and Francophone Studies or in Germanic Studies.', 'Up to AUD $20000', 'Undergraduate / VET', NULL, 'https://www.sydney.edu.au/scholarships/b/honours-scholarship-french-francophone-studies-germanic-studies.html', 'https://search.studyaustralia.gov.au/scholarship/emilie-m-schweitzer-scholarship-in-french-and-germanic-studies/33d5b43171e3b6e3971b1f6970a19a73', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Emilie M Schweitzer Scholarship in French and Germanic Studies') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'George Harris Scholarships (Chemistry)', 'A $400 scholarship for a PhD student within School of Chemistry who have contributed to the teaching activities.', 'You must:; be enrolled in a PhD within the School of Chemistry; have completed 2 years (full-time equivalent) of their PhD and have contributed to the teaching activities of the School.', 'Up to AUD $400 — This scholarship is valued at $400 and is paid as a lump sum payment upon award.', 'Postgraduate', NULL, 'https://www.sydney.edu.au/scholarships/d/george-harris-scholarships--chemistry-.html', 'https://search.studyaustralia.gov.au/scholarship/george-harris-scholarships-chemistry/915ceeb2e59b5fa757436434e5f2376c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'George Harris Scholarships (Chemistry)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Henry Bertie and Florence Mabel Gritton Research Scholarships', 'A University of Sydney RTP rate scholarship to support a student willing to undertake research at the University of Sydney.', 'You must:; be a domestic or international student; have an unconditional offer of admission or be enrolled in a full-time in a PhD at the University of Sydney; be willing to conduct research in the area of chemistry in relation to industry and agriculture, including chemistry connected with electrical engineering, metallurgical chemistry and chemistry in its application to mining and the winning and treatment of minerals and natural products of the soil; hold an honours degree (first class or second class upper) or a master\'s degree in a related field with a substantial research component or equivalent.', 'This scholarship will provide an annual stipend allowance equivalent to the University of Sydney RTP rate (indexed on 1 January each year) for up to three years and six months, subject to satisfactory academic performance', 'Postgraduate', NULL, 'https://www.sydney.edu.au/scholarships/d/henry-bertie-and-florence-mabel-gritton-research-scholarships.html', 'https://search.studyaustralia.gov.au/scholarship/henry-bertie-and-florence-mabel-gritton-research-scholarships/0986e11a2d627bb8bc816969f16a70ac', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Henry Bertie and Florence Mabel Gritton Research Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Henry Langley Scholarship', 'Stipend scholarship to support postgraduate research in the Faculty of Medicine and Health.', 'You must:; have an unconditional offer of admission or be currently enrolled to study full-time in a PhD within the Faculty of Medicine and Health at the University of Sydney; conduct research in treatment of rheumatoid arthritis; not have completed more than four (full-time equivalent) research periods of candidature at the time of application\r\n; not hold or have been offered another Higher Degree by Research primary stipend scholarship administered by the University of Sydney at the time of application.', 'The Scholarship will provide a stipend allowance equivalent to the University of Sydney Research Training Program (RTP) Stipend rate (indexed on 1 January each year) up to 3.5 years, subject to satisfactory academic performance.', 'Postgraduate', NULL, 'https://www.sydney.edu.au/scholarships/c/henry-langley.html', 'https://search.studyaustralia.gov.au/scholarship/henry-langley-scholarship/48b9c3a1334aa9ecb481807986045dde', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Henry Langley Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'James Millner Scholarship in Pharmacy', 'A stipend allowance awarded to a PhD student conducting research in pharmacy at the Faculty of Medicine and Health, University of Sydney.', 'You must:; Have an unconditional offer of admission or be currently enrolled to study full-time in a PhD within the Faculty of Medicine and Health at the University of Sydney; not have completed more than four (full-time equivalent) research periods of candidature at the time of application; conduct research in pharmacy; not hold or have been offered another Higher Degree by Research primary stipend scholarship administered by the University of Sydney at the time of application.', 'USYD RTP rate p.a. (up to 3.5 years)', 'Postgraduate', NULL, 'https://www.sydney.edu.au/scholarships/c/james-millner-scholarship-in-pharmacy.html', 'https://search.studyaustralia.gov.au/scholarship/james-millner-scholarship-in-pharmacy/b8307578311c4933efe6a4e0e6878ff2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'James Millner Scholarship in Pharmacy') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Sydney Global Mobility Joint PhD Travel Scholarship', 'A $5000 scholarship to assist students to complete the offshore component of their Joint PhD Program.', 'be a domestic or international student; be enrolled in a joint PhD program at the University of Sydney, where the University of Sydney is the your home institution; be enrolled at one of University of Sydney’s active international partners as the host institution; have a fully executed individual Student Agreement; have completed their annual progress evaluation and have received a meets/exceeds at your most recent progress review; only apply to Sydney Global Mobility for this scholarship once your offshore component of your Joint PhD Program has been confirmed; not have previously received this scholarship; not be under examination are not eligible.', 'Up to AUD $5000 — This scholarship will provide a one-off payment of $AUD 5000 for one year.', 'Postgraduate', NULL, 'https://www.sydney.edu.au/scholarships/e/sydney-global-mobility-joint-phd-travel-scholarship.html', 'https://search.studyaustralia.gov.au/scholarship/sydney-global-mobility-joint-phd-travel-scholarship/cc783859ac63e1b5b56899b46b045485', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Sydney Global Mobility Joint PhD Travel Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Sydney International Student Award', 'The Sydney International Student Award celebrates our diverse and talented community of international students. We want to help motivated applicants to achieve their personal and academic goals, by supporting their study at the University of Sydney.', 'be an international student; hold citizenship in one of the countries or regions listed below; receive admission into a full-time undergraduate coursework or postgraduate coursework degree, commencing in 2025; not be an Australian or New Zealand citizen, or a permanent resident of Australia; not have already started a degree at the University of Sydney at the time that you apply for the award. However, you are eligible if you are completing a degree here and are applying for the award with a second degree.', 'Recipients will be awarded a University contribution of 20 percent of their tuition fee for the duration of their course.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.sydney.edu.au/study/fees-and-loans/scholarships/sydney-international-student-award.html', 'https://search.studyaustralia.gov.au/scholarship/sydney-international-student-award/434ab565bdb8b19c491b498a190d5bd0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00026A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Sydney International Student Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'TAFE SA INT Scholarships', 'TAFE SA 2026 International Scholarship Programs are designed to support international students and enhance access to high‑quality vocational education and training in South Australia.\r\n\r\nThe 2026 scholarships recognise academic commitment and support students at different stages of their study journey, including those undertaking longer‑term programs and those relocating to commence shorter courses.\r\n\r\nInternational Scholarships:\r\nValue: $2,000 per student\r\nBenefit: Provided as a credit towards tuition fees\r\nPayment structure: Two instalments of $1,000 applied in the second and fourth semesters of study\r\nEligibility: Brand new international students commencing their studies before 30 June 2027, with a total study duration of two (2) years or more.\r\n\r\nRelocation Assistance Scholarship\r\nValue: $500 per student\r\nBenefit: Paid as a direct payment to assist with relocation costs\r\nEligibility: Brand new international students commencing before 30 June 2027, with a total study duration of less than two (2) years.\r\nPayment timing: Can be claimed post‑commencement.\r\n\r\nCheck the website for the Scholarships full Terms and Conditions and a list of other available options.', 'Please Contact TAFESA for more information about Eligibility.', 'full tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.tafesa.edu.au/international/before-starting/int-scholarships', 'https://search.studyaustralia.gov.au/scholarship/tafe-sa-int-scholarships/d746b80d30bad02158ca90faf5ba9ddb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00092B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'TAFE SA INT Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'AGSM Emerging Female Leaders Scholarship', 'The AGSM Emerging Female Leaders Scholarship will enable high potential female leaders to complete a world-class MBA.', 'This scholarship is open to domestic and international female candidates who are in the first five years of their career and receive an offer of admission to the AGSM Full-Time MBA program.', 'Minimum of two scholarships are available per year.', 'Postgraduate', NULL, 'http://www.business.unsw.edu.au/agsm/scholarships-prizes/mba-full-time-scholarships', 'https://search.studyaustralia.gov.au/scholarship/agsm-emerging-female-leaders-scholarship/d8e09b3b8a185bddc625ead16b4aa9bc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'AGSM Emerging Female Leaders Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'AGSM Excellence Scholarship', 'The AGSM Excellence Scholarship will give MBA candidates who have a proven track record of academic and professional excellence an opportunity to participate in AGSM’s Full-Time MBA program.', 'This scholarship is open to all applicants who receive an offer of admission to AGSM’s Full-Time MBA program.', 'Minimum of six scholarships available.\r\n\r\nFull and partial tuition fee waivers are available for eligible candidates.', 'Postgraduate', NULL, 'http://www.business.unsw.edu.au/agsm/scholarships-prizes/mba-full-time-scholarships', 'https://search.studyaustralia.gov.au/scholarship/agsm-excellence-scholarship/55653087dba05e89695ac3c4d65b08ca', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'AGSM Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'AGSM Global Reach Scholarship', 'The AGSM Global Reach Scholarship gives exceptional students from diverse international backgrounds access to AGSM’s Full-Time MBA program located in Sydney.', 'These scholarships are open to international MBA candidates who have received an offer of admission to the AGSM Full-Time MBA program.', 'Minimum of six scholarships available, with one recipient per country. These scholarships may be awarded in any admissions round.\r\n\r\nFull and partial tuition fee waivers are available for eligible candidates.', 'Postgraduate', NULL, 'http://www.business.unsw.edu.au/agsm/scholarships-prizes/mba-full-time-scholarships', 'https://search.studyaustralia.gov.au/scholarship/agsm-global-reach-scholarship/4476ed23e181c5cdb51e6425ac5f2903', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'AGSM Global Reach Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australia\'s Global University Award (PUCA1026)', 'Australia\'s Global University Award (PUCA1026)', 'Be an international student; and \r\nBe commencing full-time study on campus in a UNSW undergraduate or postgraduate coursework degree program (excluding UNSW Online and UNSW Canberra); and \r\nHave received an offer of admission* into an eligible program for Term 3 2025 by 11.59PM AEST Tuesday, 15 July 2025. \r\nOffers of admission must be one of the following:\r\nUndergraduate or postgraduate Letter of Offer (unconditional), \r\nUndergraduate or postgraduate Conditional English Package Offer (UEEC) - students must be enrolled in the UNSW Institute of Languages and successfully complete the program prior to commencing in Term 3 2025.', '$10,000 for one year. Payment will be made directly towards tuition fees in the second term of the first year of study.', 'Undergraduate / VET', NULL, 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', 'https://search.studyaustralia.gov.au/scholarship/australias-global-university-award-puca1026/92ab8eb4577b1d2d7d1d1546b645b6d3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia\'s Global University Award (PUCA1026)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Scientia Coursework Scholarship (PUCA1025)', 'International Scientia Coursework Scholarship (PUCA1025)', 'Be an International Student; and\r\nBe commencing full-time study on campus in a UNSW undergraduate or postgraduate coursework program (excluding UNSW Online and UNSW Canberra); and\r\nHave received an offer of admission* into an eligible program for Term 3 2025 by Tuesday, 15 July 2025.\r\n* Offers of admission must be one of the following:\r\nUndergraduate or postgraduate Letter of Offer (unconditional); or\r\nUndergraduate or postgraduate Conditional English Package Offer (UEEC) - students must be enrolled in the UNSW Institute of Languages and successfully complete the program prior to commencing in Term 3 2025.', 'Offer 1: Full tuition fee scholarship paid directly towards tuition fees for the minimum duration of program\r\nOffer 2: $20,000 per annum paid directly towards tuition fees for the minimum duration of program', 'Undergraduate / VET', NULL, 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', 'https://search.studyaustralia.gov.au/scholarship/international-scientia-coursework-scholarship-puca1025/056c4abb2770fb21dd120aed47a6faac', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Scientia Coursework Scholarship (PUCA1025)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Award', 'The International Student Award has been established to assist students from low income and developing countries to access education at a highly ranked Australian university. It is available to eligible new students commencing in 2025 and 2026 and provides a 15% contribution towards tuition fees for the duration of program.', 'Be an International Student; and\r\nBe a citizen of an eligible country; and\r\nBe commencing full-time study as a new student on campus^ in a UNSW Diploma, UNSW undergraduate or postgraduate coursework program (excluding programs offered by AGSM, UNSW Online, UNSW Canberra, UNSW Foundation Programs, Transition Program Online, any program taught in the Hexamester calendar, or Study Abroad students); and\r\nHave applied and received an offer of admission* into a UNSW undergraduate or postgraduate degree program; and\r\nNot be a current student of UNSW (exceptions made for those who have completed an undergraduate program at UNSW and are commencing a postgraduate program).', 'Provides a 15% contribution directly towards tuition fees.', 'Undergraduate / VET', NULL, 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', 'https://search.studyaustralia.gov.au/scholarship/international-student-award/599436be57d56e56bf3ec9cdcfdfff50', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Lee Whitmont Award in Marketing', 'The purpose of the Scholarship is to support current UNSW students undertaking an undergraduate degree in marketing.', 'Be undertaking full-time study in the third year of the Bachelor of Commerce (Marketing) program at the UNSW Business School', 'Up to AUD $5000 — The scholarship is valued at $4,000 for 1 year.', 'Undergraduate / VET', 'Business and management', 'http://www.scholarships.unsw.edu.au/scholarships/id/142', 'https://search.studyaustralia.gov.au/scholarship/lee-whitmont-award-in-marketing/f63359d3b3d51a1877a11839283b2d25', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Lee Whitmont Award in Marketing') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Lily and Dr Ben K.C. Chng Scholarship (UGCE1129)', 'The purpose of the Scholarship is to support and encourage students from Singapore to undertake full-time undergraduate study at UNSW Arts, Design and Architectures’ School of Built Environment.', 'Be an International Student and hold a Singapore citizenship. \r\nBe commencing a UNSW undergraduate coursework degree program offered through the Faculty of Arts, Design and Architecture\'s School of Built Environment. \r\nHold a diploma or equivalent course of at least 2 years credit from one of the following institutions: Nanyang Polytechnic, Ngee Ann Polytechnic, Singapore Polytechnic, Temasek Polytechnic, Republic Polytechnic.\r\nMust have received an offer of admission* into an eligible program for Term 3 2025 by Tuesday 15 July 2025*\r\nOffers of admission must be one of the following:\r\nUndergraduate Letter of Offer (unconditional)\r\nUndergraduate Conditional English Package Offer (UEEC) - students must be enrolled in the UNSW Institute of Languages and successfully complete the program prior to commencing in Term 3 2025.', '$5,000 per annum payable for normal minimum duration of degree towards tuition fees.', 'Undergraduate / VET', NULL, 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', 'https://search.studyaustralia.gov.au/scholarship/lily-and-dr-ben-kc-chng-scholarship-ugce1129/691c6861c32a9729cc068c84a285fed4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Lily and Dr Ben K.C. Chng Scholarship (UGCE1129)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Summer Vacation Research Scholarship', 'Put your summer holidays to good use with a six-week Summer Vacation Research Scholarship. You’ll gain valuable research experience working with our renowned supervisors to participate in a research project. If you’re a talented undergraduate science student enrolled in your second year or above, it’s an opportunity worth applying for.', 'You must be currently enrolled in second-year or above of an undergraduate program in the Faculty of Science or a science-related discipline at UNSW or another Australian university. You must be able to be engaged in a project on a full-time basis (35 hours/week for six weeks during normal working hours unless advised otherwise by the supervisor). Projects must focus on research-based activities (administration tasks are not regarded as research) and should be completed by the end of February. Each successful candidate can hold only ONE such scholarship at a time. Students who were previously awarded a UNSW Science Vacation Research Scholarship are not eligible to apply.', 'Each scholarship is $3800 for a six-week research project.', 'Undergraduate / VET', 'Sciences', 'https://www.unsw.edu.au/science/student-life-resources/student-opportunities/research-integrated-learning/summer-vacation-research-scholarships', 'https://search.studyaustralia.gov.au/scholarship/summer-vacation-research-scholarship/a548200d8a3e6d1cba092dd58e1e58ec', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Summer Vacation Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UNSW Law & Justice International Award (PUCA1028)', 'The UNSW Law & Justice International Award has been established to encourage high quality international students to join UNSW Law programs (LLB, JD or LLM)', 'Be an International Student; and\r\nBe commencing in any UNSW Law & Justice undergraduate/postgraduate coursework degree program (LLB, JD or LLM programs)\r\nMust have received an offer of admission into an eligible program for Term 3 2025 by Tuesday, 15 July 2025. Offers of admission must be one of the following:\r\nUndergraduate or Postgraduate Letter of Offer (unconditional)\r\nUndergraduate or Postgraduate Conditional English Package Offer (UEEC) - students must be enrolled in the UNSW Institute of Languages and successfully complete the program prior to commencing in Term 3 2025.', '$10,000 paid directly towards tuition fees for 1 year.', 'Undergraduate / VET', NULL, 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', 'https://search.studyaustralia.gov.au/scholarship/unsw-law-justice-international-award-puca1028/b5713e13725a7999a1fc8901d69abf19', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UNSW Law & Justice International Award (PUCA1028)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UNSW Master of Laws International Scholarship (PGCA1107)', 'UNSW Master of Laws International Scholarship (PGCA1107)', 'Be an international student; and \r\nHave undertaken an undergraduate qualification from a member school of the Law School Global League or an approved UNSW partner institution; and \r\nBe commencing full-time study in the UNSW Master of Laws program offered by the Faculty of Law & Justice; and \r\nHave received an offer of admission* into an eligible program for Term 3 2025 by Tuesday, 15 July, 2025*.  \r\n* Offers of admission must be one of the following:\r\nPostgraduate Letter of Offer (unconditional).', '$20,000 for one year. Payment will be made directly towards tuition fees.', 'Postgraduate', NULL, 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', 'https://search.studyaustralia.gov.au/scholarship/unsw-master-of-laws-international-scholarship-pgca1107/393bab7b66410e3bf6477226425486e8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00098G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UNSW Master of Laws International Scholarship (PGCA1107)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UTS Academic Merit International Scholarship', 'To support commencing international students who wish to undertake an undergraduate or postgraduate coursework program at UTS in Sydney.', 'Remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); Meet all admission requirements for the selected UTS undergraduate (including Honours programs) or postgraduate coursework program; Commence full-time and on campus (Sydney)', '20% of UTS Tuition Fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.uts.edu.au/scholarship/uts-academic-merit-international-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uts-academic-merit-international-scholarship/398cff14fd96edcc76808322fbaab8ad', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00099F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UTS Academic Merit International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UTS Academic Merit International Scholarship – South Asia', 'To support commencing international students from South Asia who wish to undertake an undergraduate or postgraduate coursework program at UTS in Sydney.', 'Remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); Be a citizen of a country in the South Asia region (Bangladesh, India, Nepal, Pakistan or Sri Lanka); Meet all admission requirements for the selected UTS undergraduate (including Honours programs) or postgraduate coursework program; Commence full-time and on campus (Sydney)', '15% of UTS Tuition Fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.uts.edu.au/scholarship/uts-academic-merit-international-scholarship-south-asia', 'https://search.studyaustralia.gov.au/scholarship/uts-academic-merit-international-scholarship-south-asia/46e9b4acceb96525472e7a6094b60606', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00099F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UTS Academic Merit International Scholarship – South Asia') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UTS Chinese Undergraduate Tuition Fee Scholarship', 'This Scholarship was established to support commencing international students from P.R. China to enroll in an undergraduate coursework program at UTS in Sydney.', 'Remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); Be a citizen from P.R. China; Commence full-time studies and on campus[1] at UTS in 2024 or 2025; Meet UTS admission criteria for the selected undergraduate coursework program', '20% off UTS tuition fees', 'Undergraduate / VET', NULL, 'https://www.uts.edu.au/scholarship/uts-chinese-undergraduate-tuition-fee-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uts-chinese-undergraduate-tuition-fee-scholarship/dacd085d4643cf8ecf7b73cb5fcbf9ac', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00099F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UTS Chinese Undergraduate Tuition Fee Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UTS Onshore Postgraduate International Scholarship', 'The purpose of the UTS Onshore Postgraduate International Scholarship is to attract commencing international students already in Australia to enroll in a postgraduate coursework program at UTS.', 'Must remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); Must be a citizen from a country in the South Asia, South East Asia or Africa region; Must have completed a recognised Australian tertiary qualification at a Bachelor degree level or higher; Must meet all admission criteria for the selected Master by coursework program; Must be commencing studies at UTS full-time and on campus', '25% of UTS tuition fees', 'Undergraduate / VET', NULL, 'https://www.uts.edu.au/scholarship/uts-onshore-postgraduate-international-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uts-onshore-postgraduate-international-scholarship/99fc253e60a4d4c84102aa447f31f027', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00099F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UTS Onshore Postgraduate International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UTS Study Abroad Excellence Scholarship', 'UTS offers merit-based Study Abroad Excellence Scholarship for commencing Study Abroad students. Selection is based on academic excellence in the most recently completed tertiary qualification recognized by UTS for entry in the Study Abroad program. A separate application is not required.', 'Future international students intending to commence and enrol in 18-24 credit points and undertake a study abroad program in Autumn and Spring sessions.\r\nSelection process', 'Up to AUD $2000 — $1,000 - $2,000; Duration 1 Session', 'Undergraduate / VET, Postgraduate', NULL, 'https://www.uts.edu.au/scholarship/uts-study-abroad-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uts-study-abroad-excellence-scholarship/83e1b32aed68eed9fb5aa66f3f4bd7a8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00099F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UTS Study Abroad Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Country Scholarship', 'Please Contact University of Wollongong Australia for more information.', 'Students who meet the above citizenship requirements at the time of application will automatically receive the UOW Country scholarship when they choose to study a coursework degree at the University of Wollongong commencing in 2025 and beyond.; Students can only receive one (1) UOW scholarship, sponsorship or bursary for the same course.; Students course transferring will no longer be eligible for the scholarship.', '20% tuition fee reduction for the minimum duration of an eligible course', 'Undergraduate / VET', NULL, 'https://www.uow.edu.au/study/scholarships/international/country-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/country-scholarship/08d5d38bb77e1e9fe54f8d2e7b9063c8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00102E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Country Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'India Scholarship', 'Please Contact University of Wollongong Australia for more information.', 'Students who are citizens of India at the time of application will automatically receive the India Scholarship when they choose to study a coursework degree at the University of Wollongong commencing in 2025 and beyond.; Students can only receive one (1) UOW scholarship, sponsorship or bursary for the same course.; Students course transferring will no longer be eligible for the scholarship.', '10% tuition fee reduction for the minimum duration of an eligible course', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.uow.edu.au/india/support/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/india-scholarship/39fef0227fad1ed48f8583d58ddf54ef', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00102E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'India Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UOW Offshore Transfer Discount', 'Please Contact University of Wollongong Australia for more information.', 'Please Contact University of Wollongong Australia for more information.', '30% tuition fee reduction for the minimum duration of degree', 'Undergraduate / VET', NULL, 'https://www.uow.edu.au/study/scholarships/international/uow-offshore-transfer-discount/', 'https://search.studyaustralia.gov.au/scholarship/uow-offshore-transfer-discount/94623dfd3653e22c6d28b77dab35ffb3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00102E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UOW Offshore Transfer Discount') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UOW Postgraduate Academic Excellence Scholarship', 'Please Contact University of Wollongong Australia for more information.', 'Please Contact University of Wollongong Australia for more information.', '30% tuition fee reduction for the minimum duration of an eligible course', 'Undergraduate / VET', NULL, 'https://www.uow.edu.au/study/scholarships/international/postgraduate-academic-excellence-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/uow-postgraduate-academic-excellence-scholarship/80537baba5851257457d63555ab39fc9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00102E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UOW Postgraduate Academic Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'University Excellence Scholarship', 'Please Contact University of Wollongong Australia for more information.', 'Please Contact University of Wollongong Australia for more information.', '30% tuition fee reduction for the minimum duration of an eligible course', 'Undergraduate / VET', NULL, 'https://www.uow.edu.au/study/scholarships/international/university-excellence-scholarships/', 'https://search.studyaustralia.gov.au/scholarship/university-excellence-scholarship/0b6a309f926cd1e420c1cd8f84b8c861', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00102E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'University Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 Accommodation Bursary', 'Recipients of the Accommodation Bursary will receive a discounted weekly rental rate equivalent to 50% of the standard published rental fee for eligible on-campus accommodation. The bursary is applicable for two consecutive semesters (in-semester periods only). Acceptance of the bursary constitutes a commitment to reside in university accommodation for the full duration of two semesters.', 'To be eligible for the bursary, you must:; be a new international student who will begin their studies with Federation University in Australia in Semester 2 2026; have Confirmation of Enrolment (COE) issued by Federation University; be enrolling in an eligible course (excluding OS exchange and Study Abroad); be studying at Federation University Australia in Ballarat, Gippsland, Berwick or; Melbourne City Campus; not be in receipt of a Destination Australia scholarship; be in receipt of an offer letter than includes an accommodation bursary', 'Recipients of the Accommodation Bursary will receive a discounted weekly rental rate equivalent to 50% of the standard published rental fee for eligible on-campus accommodation.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/accommodation-bursary/', 'https://search.studyaustralia.gov.au/scholarship/2026-accommodation-bursary/8b6d77781c2fd8dc15409971bb37838a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 Accommodation Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 Early Bird Bursary', 'Accept an offer from Federation and pay the deposit as listed on your offer by the given date to receive a one-off bursary in your second year of study.', 'To be eligible for the bursary, applicants must:; be a fee-paying international student (not a study abroad, exchange or online student); be enrolling as a commencing student in an eligible intake period; be eligible to study in Australia with a valid visa', 'This bursary is awarded as a tuition fee discount in your third semester of study.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/early-bird-bursary/', 'https://search.studyaustralia.gov.au/scholarship/2026-early-bird-bursary/c1c94b7b8b3ca8b892c766efc9215800', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 Early Bird Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 Federation Merit Scholarship', 'This scholarship is awarded in instalments with the first instalment awarded to successful recipients at the time of offer. Ongoing scholarship instalments will be allocated to awardee\'s student fee account prior to the following census date and on confirmation of meeting ongoing GPA requirements.', 'To be eligible for the scholarship, applicants must:; be an international student (not a study abroad, exchange or online student); be enrolling as a commencing student in 2026; be eligible to study in Australia with a valid visa; meet the additional terms and conditions as set out below.', 'The scholarship covers 20% of the tuition fees and is initially awarded for a period of two semesters.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/federation-merit-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2026-federation-merit-scholarship/ae8fa045c2daed8ca063c984af227809', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 Federation Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 Federation Pathways Scholarship', 'Federation University Australia is pleased to offer a Pathways Scholarship to international students who commence in a Federation University pathway course in 2026.', 'To be eligible for the scholarship, applicants must be: a prospective international student; enrolling as a commencing student in 2026; eligible to study in Australia with a valid visa; enrolling in an eligible pathway course.', 'The Federation Pathways Scholarship is equivalent to 20% of the annual tuition fees of a pathway course such as Foundation or Higher Education Diploma.', 'Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/federation-pathways-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2026-federation-pathways-scholarship/1e1d3dbce847366759e2c169b9fc10ae', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 Federation Pathways Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 Federation Pathways Scholarship', 'By studying a pathway course, such as a Higher Education Diploma, you may receive a percentage off your tuition fee. Get rewarded for boosting your skills and confidence as you prepare for undergraduate study.', 'To be eligible for the scholarship, applicants must be:; an international student (not a study abroad, exchange or online student); enrolling as a commencing student in 2026; eligible to study in Australia with a valid visa; enrolling in an eligible pathway course', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/federation-pathways-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2026-federation-pathways-scholarship/bda48bee40c3bb572341df3a9d2f024d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 Federation Pathways Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 Paid Placement Support Guarantee', 'Federation provides support for international students who have mandatory placement units but are not doing Co-op courses. With a minimum payment for the placement hours required in their course - up to $10,000 for undergraduates and $5,000 for postgraduates, these payments  will be distributed in instalments  throughout your study.', 'To be eligible for the scholarship, students must:; be a commencing international student (not a study abroad, exchange or online student) in 2025 or 2026; be enrolled in an eligible coursework course that requires mandatory placement; enrol in the mandatory placement units; be eligible to study in Australia with a valid visa; meet the additional terms and conditions as set out below.', 'Up to AUD $10000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/placement-support-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2026-paid-placement-support-guarantee/5a5248d64550a9d6ddd3e40fd73999d7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 Paid Placement Support Guarantee') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 Partner Scholarship', 'The Partner Scholarship is designed to support international students who transfer from Federation partner offshore locations to Australia to complete their studies or begin a new degree. Recipients will get a 20% tuition fee discount.', 'To be eligible for the scholarship, applicants must:; be an international student transferring from a Federation offshore delivery partner or an international student who has completed XCore units with Employability.; be eligible to study in Australia with a valid visa; have completed (or be in the process of completing) an approved Federation University course or a non-award short course that is formally recognised for credit towards a Federation University degree at an approved Federation University offshore partner institution; be enrolling onshore at a Federation University Australian campus to complete the same course or commence a new eligible Federation University course.', 'This scholarship is awarded in instalments, with the first instalment awarded to successful recipients at the time of offer. Ongoing scholarship instalments will be allocated to awardee’s student fee account prior to census date each semester.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/partner-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2026-partner-scholarship/04625496d46f4edeca854a639137e5c2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 Partner Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 Stanford Advanced Materials College Scholarship', 'As a trusted supplier of advanced materials for industries such as aerospace, technology, healthcare, and energy, Stanford Advanced Materials (SAM) has long been focused on the industrial applications and development trends of rare metals. To explore the potential of rare metals fully, we invite outstanding students to join us in discussing their applications and future directions. We are also proud to announce the establishment of the 2025 College Scholarship by Stanford Advanced Materials to support students who demonstrate excellence in this field.', 'Open to high school, undergraduate, and graduate students worldwide. Submissions are only accepted in English, Spanish, German, French, Italian, and Japanese.; Submissions must focus on the industrial applications and development trends of rare metals.; Projects with originality, technical feasibility, and potential impact on the industrial development of rare metals are strongly encouraged.; Submissions generated using artificial intelligence (AI) are prohibited and will be disqualified.', 'Up to AUD $1000', 'Secondary schooling, Postgraduate, Undergraduate / VET', NULL, 'https://www.samaterials.com/stanford-advanced-materials-college-scholarship.html?utm_source=EDM&utm_medium=scholarship', 'https://search.studyaustralia.gov.au/scholarship/2026-stanford-advanced-materials-college-scholarship/6486bbd84acd943fa0a83514beca1504', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 Stanford Advanced Materials College Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2027 Accommodation Bursary', 'This scholarship is offered to support international students who choose to live in Federation\'s on-campus accommodation in Victoria. Students will receive 50% off the cost of weekly rent for their first year, and 25% off standard accommodation rates for the second year. Subject to availability. Additional fees may apply.', 'Prospective international students will automatically be assessed for an Accommodation Bursary at the time they receive an offer to study at the University. No additional application is required.', 'Up to AUD $7278 — New international students joining the FedLiving community at our Mt Helen and Berwick campuses may be eligible for up to $1,000 per semester (for a maximum of two semesters, subject to $550 acceptance fee).', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/2027-accommodation-bursary/', 'https://search.studyaustralia.gov.au/scholarship/2027-accommodation-bursary/ee965bf650252b4eb28add7d86f4404e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2027 Accommodation Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2027 Global Achiever Scholarship', 'This tuition fee scholarship provides eligible international students 15% off annual tuition fees for the duration of their course. This scholarship cannot be combined with other tuition fee scholarships.', 'To be eligible for the scholarship, applicants must: be an international student (not a study abroad, exchange or online student), be enrolling as a commencing student in 2027, be enrolling in an undergraduate or postgraduate coursework degree at Federation University Australia, be eligible to study in Australia with a valid visa, meet the additional terms and conditions as set out below, and not be in receipt of any other merit-based and/or tuition fee scholarships.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/2027-global-achiever-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2027-global-achiever-scholarship/1a36d036343caa5a6ef1e0ca499ed469', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2027 Global Achiever Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2027 Global Merit Scholarship', 'International students may receive 25% off their annual tuition fees for the duration of their course, based on academic merit. Achieve an average of 75% or equivalent in previous studies to be eligible.', 'To be eligible for this scholarship, applicants must: be an international student (not a study abroad, exchange or online student), be enrolling as a commencing student in 2027, be enrolling in an undergraduate or postgraduate coursework degree at Federation University Australia, be eligible to study in Australia with a valid visa, and meet the additional terms and conditions as set out below.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/2027-global-merit-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2027-global-merit-scholarship/33fbd9803832fb9e965845ef7f4dcbef', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2027 Global Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2027 Paid Placement Support Guarantee', 'This scholarship supports international students who have mandatory placement units but are not doing Co-op courses. Students receive $10,000 (undergraduate) or $5,000 (postgraduate) in instalments to support them while completing their placement.', 'To be eligible for this scholarship, students must: be a commencing international student, be enrolled in an eligible coursework course that requires mandatory placements, enrol in mandatory placement units, be eligible to study in Australia with a valid visa, and meet the additional terms and conditions set out on the scholarship webpage.', 'Up to AUD $10000', 'Postgraduate, Undergraduate / VET', 'Education and training, Health services and support, Nursing, Social work', 'https://www.federation.edu.au/study/scholarships/details/international/2027-placement-support-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2027-paid-placement-support-guarantee/d96c5a236c5b65a6094e8b41139befd9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2027 Paid Placement Support Guarantee') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2027 Partner Scholarship', 'This scholarship supports international students who transfer from an offshore Federation partner provider to one of our campuses in Victoria. Whether continuing their studies in Australia or start a new course, recipients will receive 20% off annual tuition fees for the duration.', 'To be eligible for the scholarship, applicants must: be an international student transferring from a Federation offshore delivery partner or an international student who has completed XCore units with Employability.Life, be eligible to study in Australia with a valid visa, have completed (or be in the process of completing) an approved Federation University course or a non-award short course that is formally recognised for credit towards a Federation University degree at an approved Federation University offshore partner institution, be enrolling onshore at a Federation University Australian campus to complete the same course or commence a new eligible Federation University course.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/2027-partner-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2027-partner-scholarship/fc4ef372b65e31251d910d51447a6520', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2027 Partner Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bridging the distance: Using sport technology to enhance high-performance pathways for rural athletes', 'Overarching Aim of the PhD:Athletes from regional and rural Australia face significant barriers in accessing high-performance sport pathways, including limited access to coaching, sport science support, and elite competition environments. Advances in sport technology (e.g., wearable sensors, remote coaching platforms, performance analytics) offer an opportunity to overcome these geographic constraints.This PhD project will design, implement, and evaluate technology-enabled athlete development models to support regional athletes in achieving high-performance outcomes without the need for relocation.', 'To be eligible for the project, you must:; be eligible for a PhD; willing to undertake full-time study', 'Up to AUD $50000', 'Postgraduate', NULL, 'https://www.federation.edu.au/study/scholarships/details/research/bridging-the-distance-using-sport-technology-to-enhance-high-performance-pathways-for-rural-athletes/', 'https://search.studyaustralia.gov.au/scholarship/bridging-the-distance-using-sport-technology-to-enhance-high-performance-pathways-for-rural-athletes/06b0787828a51c61a4477cd64189cbd0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bridging the distance: Using sport technology to enhance high-performance pathways for rural athletes') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Foundation for Rural and Regional Renewal: Diversity in Regional Telehealth Bursaries', 'The Foundation for Rural & Regional Renewal is the only national foundation specifically focused on ensuring the social and economic strength of Australia\'s remote, rural and regional communities. We understand the big picture, and the fine grain, and collaborate to address real needs, at scale. Our unique model connects common purposes and investment with locally prioritised needs, often reaching some of the smallest communities. We amplify this support into longer-term capability, momentum and resilience. Harnessing goodwill to ensure the long-term vitality of remote, rural and regional Australia.', 'Please Contact Federation University for more information about Eligibility', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/foundation-scholarships/foundation-for-rural-and-regional-renewal-diversity-in-regional-telehealth-bursaries2/', 'https://search.studyaustralia.gov.au/scholarship/foundation-for-rural-and-regional-renewal-diversity-in-regional-telehealth-bursaries/08619451a60b57e07e096f00eead6a91', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Foundation for Rural and Regional Renewal: Diversity in Regional Telehealth Bursaries') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Vice-Chancellor\'s Award (Semester 1 2027)', 'The Vice-Chancellor\'s Award is a 50% tuition fee scholarship that recognises and supports outstanding academic achievers from specific regions of Asia.', 'To be considered for this scholarship, applicants must:; be a commencing international student; be enrolling into a bachelor or masters course in 2027; be a citizen of South Asia, Southeast Asia or China; have achieved an average mark of 90% or equivalent in prior studies that are the basis of admission. Federation University reserves the right to assess and determine the equivalency and validity of all academic results and GPA calculations in accordance with its own grading and admissions framework\r\nbe eligible to study in Australia with a valid visa; submit a separate scholarship application and participate in an interview process; meet the additional terms and conditions as set out below.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.federation.edu.au/study/scholarships/details/international/vice-chancellors-award-semester-1-2027/', 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-award-semester-1-2027/f544becafadefa35876a1f09186b3836', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00103D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Vice-Chancellor\'s Award (Semester 1 2027)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Excellence Scholarship', 'The International Excellence Scholarship 2026 has been established to attract high-performing students to study at the University of Newcastle. This scholarship acknowledges applicants with a strong academic background and provides an ongoing incentive for continued academic achievement. Scholarships will be awarded to applicants who receive an offer to study in an eligible program and who commence study with the University in 2026 and beyond.', 'To be eligible to apply for this scholarship, you will need to:; Be an International student.; Be commencing study in an eligible CRICOS-registered undergraduate or postgraduate coursework degree program at the University.; Not be the beneficiary of a separate University scholarship unless prior approval for special dispensation has been obtained from the university.; Be able to meet the financial obligations of a full fee-paying international student specified by the Australian Government. Evidence of this ability must be provided if requested by the university.', '20% of gross annual international tuition fee', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.newcastle.edu.au/scholarships/UNI_053', 'https://search.studyaustralia.gov.au/scholarship/international-excellence-scholarship/8d93cf0c6a83646161fe2ddbaa43a522', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00109J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Natural History Illustration Scholarship', 'This is a donor funded scholarship established from a bequest from the late Margaret Senior to recognize excellence in an Illustration major for a University of Newcastle student. The scholarship will be awarded in March to the student who completed their first year the year prior, with the highest marks in Visual Communication Design with an Illustration major.', 'Applicants must: Be completing your first year of the Visual Communication Design program with an Illustration major with University of Newcastle.; Be enrolled full-time.; Not be the recipient of another University of Newcastle donor-funded or sponsored scholarship concurrently.', 'Up to AUD $10000 — This scholarship provides a total benefit of $10,000 for one year. Payment will be made in instalments of $5000 in Semester 1 and 2', 'Undergraduate / VET', 'Education and training, Creative arts', 'http://www.newcastle.edu.au/scholarships/EXT_099', 'https://search.studyaustralia.gov.au/scholarship/natural-history-illustration-scholarship/992338e605095b9bbee3f61c1eee0dc4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00109J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Natural History Illustration Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australia Awards Scholarship', 'Swinburne has been involved in the Australia Awards scholarship program for over 15 years. Currently, there are more than 30 Australia Award students enrolled at the university. The Australia Awards are scholarships funded by the Australian Government that aim to promote knowledge, education links and enduring ties between Australia and its neighbours. They provide opportunities for people from eligible countries to undertake full time undergraduate, postgraduate or TAFE study at Swinburne.', 'Please contact Swinburne University of Technology for further information.', 'Australia Awards scholarships are comprehensive and include a number of different benefits and entitlements.\r\n\r\nA full list of entitlements can be found at the Australia Awards website or Australia Awards Scholarship Policy Handbook.\r\n\r\nKey entitleme', 'Undergraduate / VET', NULL, 'https://www.swinburne.edu.au/study/options/scholarships/338/australia-awards-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarship/f2c66707ab626febfdffd327e7bad9be', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00111D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Aviation Women\'s Association Scholarship', 'The International Aviation Womens Association (IAWA) is a non-profit association with members in 38 countries, representing 257 major companies and aviation authorities. IAWA is dedicated to promoting the advancement of women in the aviation and aerospace industries.', 'Be an International student, an Australian citizen, a New Zealand Citizen, an Australian permanent resident or holder of a permanent humanitarian visa. Be a female student studying full time in an aviation undergraduate or post graduate course. Submit a personal statement of no more than 500 words outlining your interest and passion for aviation and financial need for the scholarship Submit a referee report outlining leadership quality and community participation.', 'The scholarship is valued at US$5,000 and a free scholar membership for one year only.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.swinburne.edu.au/study/options/scholarships/385/international-aviation-womens-association--iawa--scholarship/', 'https://search.studyaustralia.gov.au/scholarship/international-aviation-womens-association-scholarship/372bb6ce1a6579a3e52f7fac1c4507c7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00111D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Aviation Women\'s Association Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Judith Kinnear Student Travel Scholarship 2027', 'The Judith Kinnear Student Travel Scholarship supports a postgraduate student in a Masters degree (by Research) or Doctorate degree (PhD) within Swinburne\'s School of Engineering or School of Science, Computing and Emerging Technologies. Named after Dr Judith Kinnear, a Swinburne alum who became the first woman to lead a New Zealand university, the scholarship honours her pioneering career in higher education.', 'Applicants must be:; a continuing second year and above Swinburne student in Semester 1, 2027; enrolled full-time in a Masters (by Research) or PhD in the School of Science, Computing and Emerging Technologies or School of Engineering.', 'Up to AUD $5000', 'Postgraduate', NULL, 'https://www.swinburne.edu.au/courses/scholarships/judith-kinnear-student-travel-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/judith-kinnear-student-travel-scholarship-2027/1b6e7ed540397f37ce1e46d52218ed69', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00111D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Judith Kinnear Student Travel Scholarship 2027') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research Training Program Stipend - RTP Stipend', 'Research Training Program (RTP) Stipend scholarships are awarded to candidates of exceptional research potential, enrolled in a Higher Degree by Research (HDR) course of study, to assist with general living costs. These scholarships are available to both future and current students enrolled in or applying for a Doctor of Philosophy (PhD) or Professional Doctorate course at Swinburne.', 'Please refer to the Swinburne Research Stipend Scholarship webpage.', 'Up to AUD $35499', 'Postgraduate', NULL, 'https://www.swinburne.edu.au/study/options/scholarships/214/research-training-program-stipend---rtps/', 'https://search.studyaustralia.gov.au/scholarship/research-training-program-stipend-rtp-stipend/a3bfae0c6338f2105d6f5cbc64196b3f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00111D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research Training Program Stipend - RTP Stipend') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Stanley Liebich Memorial Scholarship 2027', 'The Stanley Liebich Memorial Scholarship was first established in December 1940, in memory of the late Stanley Ormond Crossley Liebich. This scholarship supports a student from a disadvantaged background enrolled in the Bachelor of Engineering (Honours) degree, who progressed from the Associate Degree in Engineering OR Advanced Diploma of Engineering Technology.', 'Applicants must:; have progressed from the Associate Degree in Engineering OR Advanced Diploma of Engineering Technology prior to Bachelor of Engineering course.', 'Up to AUD $7500', 'Undergraduate / VET', NULL, 'https://www.swinburne.edu.au/courses/scholarships/stanley-liebich-memorial-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/stanley-liebich-memorial-scholarship-2027/cacdf08a6d28eaf16212ac1869ab1339', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00111D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Stanley Liebich Memorial Scholarship 2027') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Steve Ashton Scholarship for the Architectural Profession (SASAP) 2026', 'The Steve Ashton Scholarship for the Architectural Profession (SASAP) honours Steve Ashton, co-founder of Ashton Raggatt McDougall (ARM Architecture). As a career architect, Steve undertook a Graduate Diploma of Business Administration at Swinburne to upskill with what he needed to help operate his business at a high-level and work on prominent urban design projects of the highest architectural quality.', 'Please contact Swinburne University of Technology for further information.', 'Up to AUD $30000 — The scholarship is worth up to $30,000 per annum for full-time enrolled recipients for the standard full-time duration of the program, and up to $15,000 per annum for part-time enrolled recipients for the standard part-time. Paymen', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.swinburne.edu.au/study/options/scholarships/519/steve-ashton-scholarship-for-the-architectural-profession--sasap--2025/', 'https://search.studyaustralia.gov.au/scholarship/steve-ashton-scholarship-for-the-architectural-profession-sasap-2026/5e70cd389010b29be9b117278f7d67bc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00111D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Steve Ashton Scholarship for the Architectural Profession (SASAP) 2026') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Swinburne Research Stipend Scholarships', 'Swinburne Research Stipend (SRS) scholarships are awarded to candidates of exceptional research potential undertaking doctoral studies.  The awards are provided to assist with general living costs.   Successful scholarship applicants are automatically awarded a RTP Fees-Offset (Domestic) Scholarship (domestic students) or a Tuition Fee Scholarship (international students) which covers tuition fees for up to four years.', 'Doctor of Philosophy (PhD), Professional Doctorate', 'Up to AUD $35000', 'Postgraduate', NULL, 'https://www.swinburne.edu.au/study/options/scholarships/510/swinburne-research-scholarships/', 'https://search.studyaustralia.gov.au/scholarship/swinburne-research-stipend-scholarships/86afae5be41cded99eb58719f6c6f091', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00111D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Swinburne Research Stipend Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Swinburne University Postgraduate Research Award', 'SUPRAs are awarded to students of exceptional research potential undertaking doctoral studies. The awards are provided to assist with general living costs. Tuition fees are also covered by the award. SUPRA scholarships are available to both future and current students enrolled in or applying for a Doctor of Philosophy (PhD) or Professional Doctorate course at Swinburne.', 'meet the entry requirements for a PhD or Professional Doctorate as set out for their proposed program at Swinburne; hold a Bachelor Degree with First Class Honours (or equivalent); propose a research project that aligns with a Swinburne Research Strategy and Ecosystem area; would not be receiving another stipend scholarship to support their general living costs while undertaking their course of study if that stipend is greater than 75 per cent of that student’s RTP Stipend or SUPRA scholarship stipend rate.', 'Up to AUD $35500', 'Postgraduate', NULL, 'https://www.swinburne.edu.au/study/options/scholarships/221/swinburne-university-postgraduate-research-award/', 'https://search.studyaustralia.gov.au/scholarship/swinburne-university-postgraduate-research-award/f8a39949da8e2614241d8e439e3995c1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00111D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Swinburne University Postgraduate Research Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Tuition Fee Scholarship', 'For prospective international research students.', 'Please contact Swinburne University of Technology for further information.', 'Covers the cost of research tuition fees up to a maximum of four years full-time equivalent for doctoral students and two years for research masters.', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.swinburne.edu.au/study/options/scholarships/223/tuition-fee-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/tuition-fee-scholarship/1fe6fa5e5c3f1b98a3cfa6f4d7a8f6e4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00111D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Tuition Fee Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'AI Enabled Geothermal Utilisation for Sustainable Buildings', 'Supporting a PhD candidate as part of the REACH Trailblazer Program to initiate and conduct research in AI-enhanced optimisation of geothermal building systems.', 'To be eligible you must:; meet Deakin\'s PhD entry requirements; enrol full time; hold an honours degree (first class) or an equivalent standard masters degree with substantial research component.', 'AUD $45550/year — a stipend of $45,550 per annum tax exempt (2025 rate); a relocation allowance of $500–1,500 (for single to family) for students moving from interstate; contribution to research purposes including travel of $1,500 per annum for three', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/phd-scholarship-ai-enabled-geothermal-systems-in-buildings', 'https://search.studyaustralia.gov.au/scholarship/ai-enabled-geothermal-utilisation-for-sustainable-buildings/899437a209258ca98e7c5d5e6f1c1b63', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'AI Enabled Geothermal Utilisation for Sustainable Buildings') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'AI-enabled battery health management systems', 'Supporting a PhD candidate to research and develop artificial intelligence (AI)-based monitoring and estimation models for battery maintenance in Australian heavy industries.', 'To be eligible you must:; meet Deakin\'s PhD entry requirements; enrol full time; hold an honours degree (first class) or an equivalent standard masters degree with substantial research component.', 'AUD $45550/year — a stipend of $45,550 per annum tax exempt (2025 rate); a relocation allowance of $500–1,500 (for single to family) for students moving from interstate; contribution to research purposes including travel: $1,500 per annum for three y', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/hdr-scholarship-AI-enabled-battery-health-management-systems', 'https://search.studyaustralia.gov.au/scholarship/ai-enabled-battery-health-management-systems/eb06cf4eae76a8c8c9994f92dc77d0d9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'AI-enabled battery health management systems') LIMIT 1;
