INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Consolidating intelligence data to identify victims of child sexual abuse', 'Supporting a PhD candidate to improve police identification of children at risk of sexual exploitation.', 'To be eligible you must:; meet Deakin\'s PhD entry requirements; enrol full time; hold an honours degree (first class) or an equivalent standard masters degree with a substantial research component', 'AUD $37450/year — a stipend of $37,450 per annum tax exempt (2026 rate); a relocation allowance of $500-1,500 (for single to family) for students moving from interstate', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/phd-scholarship-child-abuse-victim-identification-through-intelligence', 'https://search.studyaustralia.gov.au/scholarship/consolidating-intelligence-data-to-identify-victims-of-child-sexual-abuse/2b427bc3e990de3b25a8c34648a3eb09', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Consolidating intelligence data to identify victims of child sexual abuse') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin College Foundation Pathway Scholarship', 'Please contact Deakin University for further information.', 'Please contact Deakin University for further information.', '10% off the Bachelor degree tuition fees if the graduating Foundation student achieves a WAM of 60-64.99%.\r\n15% off the Bachelor degree tuition fees if the graduating Foundation student achieves a WAM of 65% or higher.', 'Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-college-foundation-pathway-scholarship', 'https://search.studyaustralia.gov.au/scholarship/deakin-college-foundation-pathway-scholarship/3dad686ae77dd0205f013eb042cba122', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin College Foundation Pathway Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin Global Health Leaders Scholarship', 'Please contact Deakin University for further information.', 'Please contact Deakin University for further information.', 'This scholarship of 20% of the total indicative tuition fee stated on your offer letter is available for the normal duration of the course.*', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-global-health-leaders-scholarship', 'https://search.studyaustralia.gov.au/scholarship/deakin-global-health-leaders-scholarship/0a960f668df6940879cb22e6509d8ed3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin Global Health Leaders Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin International 20% Merit Scholarship', 'Recognising high-achieving international students applying for undergraduate or postgraduate degrees at Deakin.', 'To be eligible you must:; be a new international student enrolling in a Deakin degree; meet the entry requirements for your program, including English language requirements; Undergraduate degree: have achieved at least a 65% average (or equivalent) in previous studies.; Postgraduate degree: Have achieved at least a 65% average (or equivalent) in previous studies. Applicants who are citizens of India and residing in India are eligible with a minimum 60% average (or equivalent).', '20% of your total tuition fees (as stated on your offer letter)', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-international-20-merit-scholarship', 'https://search.studyaustralia.gov.au/scholarship/deakin-international-20-merit-scholarship/3f17ae0c0cdcdb9605e3e9a0d546c065', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin International 20% Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin International Scholarship', 'Contact Deakin University for more information', 'Please contact Deakin University for further information.', '25% of your student contributions (tuition fees)*', 'Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship', 'https://search.studyaustralia.gov.au/scholarship/deakin-international-scholarship/a83ee380210e909f5113ac7c1e7ae29d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin International Scholarship for Excellence', 'Supporting international students who demonstrate excellence in academic performance.', 'meet the minimum academic requirements outlined below:; Undergraduate degree: have achieved at least a 75% average (or equivalent) in previous studies.; Postgraduate degree: have achieved at least a 80% average (or equivalent) in previous studies. Applicants who are citizens of India, Nepal, Bangladesh, Mauritius, Myanmar and Bhutan are eligible with a minimum 75% average (or equivalent).', '25% of your total tuition fees (stated on your offer letter)', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-international-scholarship-for-excellence', 'https://search.studyaustralia.gov.au/scholarship/deakin-international-scholarship-for-excellence/b7ad8a8e8fe079ed4e96e7bbb02989e5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin International Scholarship for Excellence') LIMIT 1;
