INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin STEM Scholarship', 'Contact Deakin Universisty for more information', 'Please contact Deakin University for further information.', '20% of your student contributions (tuition fees).', 'Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-stem-scholarship', 'https://search.studyaustralia.gov.au/scholarship/deakin-stem-scholarship/dab5e28f52a26e322439c0c69987085f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin STEM Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin Sanctuary Scholarships', 'Supporting students from asylum-seeking or refugee backgrounds residing in Australia to access higher education and succeed at Deakin.', 'Ensure you meet all criteria before submitting an application. To be eligible for this scholarship, you must be:; be an international student who holds one of the following visas:; Temporary Protection visa (Subclass 785); Safe Haven Enterprise visa (Subclass 790); Temporary Humanitarian Stay visa (Subclass 449); Temporary Humanitarian Concern visa (Subclass 786); Bridging visa A (Subclass 010) or Bridging visa E (Subclass 050 or 051); meet the entry requirements for an undergraduate or postgraduate coursework degree at Deakin; commence full-time study in Trimester/Semester 1, 2027 (you must apply for a course and receive an offer before we can assess your scholarship application); not be a current or past recipient of the Deakin Sanctuary Scholarship.', '100% of your total tuition fees.; $6000 cash payment per year ($750 per credit point).', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-sanctuary-scholarships', 'https://search.studyaustralia.gov.au/scholarship/deakin-sanctuary-scholarships/2090fa5248e784ca752a71edd03fc082', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin Sanctuary Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin Vice-Chancellor’s International Scholarship', 'This scholarship is open to all students commencing studies. It is recommended that scholarship applications be submitted at least one month prior to commencing your studies at Deakin.', 'Please contact Deakin University for further information.', 'All of your tuition fees or 50% of your tuition fees.*', 'Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-vice-chancellors-international-scholarship', 'https://search.studyaustralia.gov.au/scholarship/deakin-vice-chancellors-international-scholarship/9b375940e6fecf7fd64bae8bf2a8894a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin Vice-Chancellor’s International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin Warrnambool Residential International Scholarships', 'Please contact Deakin University for further information.', 'Please contact Deakin University for further information.', '50% of your accommodation costs with Deakin Residences Warrnambool (approximately between $4000 - $4500 per year).', 'Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-warrnambool-residential-international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/deakin-warrnambool-residential-international-scholarships/ed91fedbe1fefc6b45cf6becce6e0fac', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin Warrnambool Residential International Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin alumni discount', 'Contact Deakin Universisty for more information', 'Please contact Deakin University for further information.', '10% reduction per unit on your enrolment fees on your postgraduate award course at Deakin University.', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/alumni-discount', 'https://search.studyaustralia.gov.au/scholarship/deakin-alumni-discount/ef32fd15ab5d8ae30e16b8f34e9ff1c8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin alumni discount') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin-Bayreuth Cotutelle - Product design engineering for sports', 'Supporting a PhD candidate to advance research in personalised product design and engineering for sports in Australia (Deakin University) and Germany (University of Bayreuth).', 'To be eligible you must:; be either a domestic or international candidate. Domestic includes candidates with Australian Citizenship, Australian Permanent Residency or New Zealand Citizenship; meet the PhD entry requirements of both Deakin University and University of Bayreuth, including H1 or H1 equivalence and English language proficiency criteria; enrol full time; be able to physically locate to both University of Bayreuth (Germany) and Deakin University (Australia).', 'AUD $37450/year — a stipend of $37,450 per annum tax exempt (2026 rate); at least 12 months of the total period of the program at University of Bayreuth.', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-bayreuth-cotutelle-product-design-engineering-for-sports', 'https://search.studyaustralia.gov.au/scholarship/deakin-bayreuth-cotutelle-product-design-engineering-for-sports/364e1110be23df2f20398b6488b43109', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin-Bayreuth Cotutelle - Product design engineering for sports') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin-Bayreuth Cotutelle - Shape-changing fiber-based architectures via nonplanar additive manufacturing', 'Supporting a PhD candidate to research shape-changing fiber-based architectures via nonplanar additive manufacturing in Australia (Deakin University) and Germany (University of Bayreuth).', 'To be eligible you must:; be either a domestic or international candidate. Domestic includes candidates with Australian Citizenship, Australian Permanent Residency or New Zealand Citizenship; meet the PhD entry requirements of both Deakin University and University of Bayreuth, including H1 or H1 equivalence and English language proficiency criteria; enrol full time; be able to physically locate to both University of Bayreuth (Germany) and Deakin University (Australia).', 'AUD $37450/year — a stipend of $37,450 per annum tax exempt (2026 rate); at least 12 months of the total period of the program at University of Bayreuth.', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-bayreuth-cotutelle-shape-changing-fiber-based-architectures', 'https://search.studyaustralia.gov.au/scholarship/deakin-bayreuth-cotutelle-shape-changing-fiber-based-architectures-via-nonplanar-additive-manufacturing/ff28a02530c0c83bba4564b140afb9fc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin-Bayreuth Cotutelle - Shape-changing fiber-based architectures via nonplanar additive manufacturing') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin-Bayreuth Cotutelle - exploring sodium-ion battery electrode architectures', 'Supporting a PhD candidate to research sodium-ion battery electrode architectures incorporating novel functional binder formulations in Australia (Deakin University) and Germany (University of Bayreuth).', 'To be eligible you must:; be either a domestic or international candidate. Domestic includes candidates with Australian Citizenship, Australian Permanent Residency or New Zealand Citizenship; meet the PhD entry requirements of both Deakin University and University of Bayreuth, including H1 or H1 equivalence and English language proficiency criteria; enrol full time; be able to physically locate to both University of Bayreuth (Germany) and Deakin University (Australia).', 'AUD $35550/year — a stipend of $35,550 per annum tax exempt (2025 rate); at least 12 months of the total period of the program at University of Bayreuth.', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/deakin-bayreuth-cotutelle-exploring-sodium-ion-battery-electrode-architectures', 'https://search.studyaustralia.gov.au/scholarship/deakin-bayreuth-cotutelle-exploring-sodium-ion-battery-electrode-architectures/c9b44ac1ba4839629cf189cb1ba3dacf', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin-Bayreuth Cotutelle - exploring sodium-ion battery electrode architectures') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin-Coventry Cotutelle: Health risks from microplastic exposure', 'Supporting a PhD candidate to research health risks related to microplastics between Australia (Deakin University) and the United Kingdom (Coventry University). Deakin is the lead institution.', 'To be eligible you must:; be a domestic or international candidate. Domestic includes candidates with Australian Citizenship, Australian Permanent Residency or New Zealand Citizenship; meet the PhD entry requirements of both Deakin University and Coventry University, including equivalence and English language proficiency criteria; enrol full time; be able to physically locate to both Coventry University (United Kingdom) and Deakin University (Australia).', 'AUD $37450/year — a stipend of $37,450 per annum tax exempt (2026 rate); a relocation allowance of $500–1,500 (for single to family) for students moving from interstate.; at least 12 months of the total period of the program at Coventry University.;', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/coventry-deakin-cotutelle-health-risks-from-microplastic-exposure', 'https://search.studyaustralia.gov.au/scholarship/deakin-coventry-cotutelle-health-risks-from-microplastic-exposure/8c684f447a24b06f4cd30ec0269035af', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin-Coventry Cotutelle: Health risks from microplastic exposure') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin-Coventry Cotutelle: Microplastics and chemical additives from polyethylene terephthalate packaging', 'Supporting a PhD candidate to research health risks related to microplastics and chemical additives from packaging between Australia (Deakin University) and the United Kingdom (Coventry University). Coventry is the lead institution.', 'To be eligible you must:; be a domestic or international candidate. Domestic includes candidates with Australian Citizenship, Australian Permanent Residency or New Zealand Citizenship; meet the PhD entry requirements of both Deakin University and Coventry University, including equivalence and English language proficiency criteria; enrol full time; be able to physically locate to both Coventry University (United Kingdom) and Deakin University (Australia).', 'See scholarship details', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/coventry-deakin-cotutelle-microplastics-and-chemical-additives-exposure-in-packaging', 'https://search.studyaustralia.gov.au/scholarship/deakin-coventry-cotutelle-microplastics-and-chemical-additives-from-polyethylene-terephthalate-packaging/b31424fc80ce2afce538feaf7d4d324a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin-Coventry Cotutelle: Microplastics and chemical additives from polyethylene terephthalate packaging') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Determining actual crop water use for maximising the Water Circular Economy (WCE) in high value irrigated almonds', 'Supporting a PhD candidate in enhancing water circular economy in irrigated almond production systems.', 'To be eligible you must:; meet Deakin\'s PhD entry requirements; enrol full time; hold an honours degree (first class) or an equivalent standard masters degree with a substantial research component', 'AUD $37450/year', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/hdr-scholarship-crop-water-use-water-circular-ecomony-almonds', 'https://search.studyaustralia.gov.au/scholarship/determining-actual-crop-water-use-for-maximising-the-water-circular-economy-wce-in-high-value-irrigated-almonds/0e4cacd6c76da6aaaefb4804b52c21df', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Determining actual crop water use for maximising the Water Circular Economy (WCE) in high value irrigated almonds') LIMIT 1;
