INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Purification of silk proteins for next generation protein-based materials', 'Supporting a PhD candidate to develop a new method to purify silk proteins using liquid chromatography.', 'To be eligible you must:; meet Deakin\'s PhD entry requirements; enrol full time; hold an honour\'s degree (first class) or an equivalent standard master\'s degree with a substantial research component', 'AUD $37450/year', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/phd-scholarship-next-generation-protein-based-materials', 'https://search.studyaustralia.gov.au/scholarship/purification-of-silk-proteins-for-next-generation-protein-based-materials/2dd03fb3720593f6464c0d5a1fcb6d10', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Purification of silk proteins for next generation protein-based materials') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research Training Program    Scholarship (RTP)  / Deakin University Postgraduate Research  Scholarship (DUPR)', 'RTP scholarships are funded by the Australian Government, while DUPR scholarships are funded by Deakin. Both are available to domestic and international candidates. Only top-ranked applicants will be offered an RTP.', 'To be eligible for an RTP Stipend, RTP Fees Offset, RTP Allowance or DUPRS an applicant must be a domestic or international student enrolled in a graduate research course of study at Deakin University.; To be eligible for an RTP Fees Offset an applicant must not be receiving an equivalent award or scholarship from the Commonwealth designed to offset graduate research fees.', 'See scholarship details', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/rtp-and-duprs', 'https://search.studyaustralia.gov.au/scholarship/research-training-program-scholarship-rtp-deakin-university-postgraduate-research-scholarship-dupr/7b144cf6f8ae5b861c339f0d008e617c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research Training Program    Scholarship (RTP)  / Deakin University Postgraduate Research  Scholarship (DUPR)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Upscaling seagrass restoration in Victoria', 'Supporting two PhD candidates as part of the REACH Trailblazer Program to initiate and conduct research in upscaling seagrass restoration in Victoria to support the national emissions target.', 'To be eligible you must:; meet Deakin\'s PhD entry requirements; enrol full time; hold an honours degree (first class) or an equivalent standard masters degree with substantial research component.', 'AUD $45550/year — a stipend of $45,550 per annum tax exempt (2025 rate); a relocation allowance of $500–1,500 (for single to family) for students moving from interstate; contribution to research purposes including travel of $1,500 per annum for three', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/hdr-scholarship-upscaling-seagrass-restoration-in-victoria', 'https://search.studyaustralia.gov.au/scholarship/upscaling-seagrass-restoration-in-victoria/d2cc5e7e85f03417f0eba3a12ebb6596', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Upscaling seagrass restoration in Victoria') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Vietnam Scholarship', 'Contact Deakin Universisty for more information', 'Please Contact Deakin University for more information.', '20% of the student contributions (tuition fees)', 'Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/vietnam-scholarship', 'https://search.studyaustralia.gov.au/scholarship/vietnam-scholarship/0caf1060a69c61d80038a98ceb6c12ff', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Vietnam Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Warrnambool Campus International Bursary', 'Contact Deakin University for more information', 'Please contact Deakin University for further information.', '20% of the student contributions (tuition fees)', 'Undergraduate / VET', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/warrnambool-campus-international-bursary', 'https://search.studyaustralia.gov.au/scholarship/warrnambool-campus-international-bursary/644f4106ac145528997d91479413ab2c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Warrnambool Campus International Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Youth futures after mobility', 'Supporting a PhD candidate to undertake a research project as part of a new Australian Research Council funded Discovery Project: Youth Futures after Mobility (YFAM).', 'To be eligible you must:; meet Deakin\'s PhD entry requirements; be enrolling full time and hold an honours degree (first class) or an equivalent standard master\'s degree with a substantial research component.', 'AUD $37450/year — stipend of $37,450 per annum tax exempt (2026 rate); stipend of $37,450 per annum tax exempt (2026 rate)', 'Postgraduate', NULL, 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship/phd-scholarship-youth-futures', 'https://search.studyaustralia.gov.au/scholarship/youth-futures-after-mobility/c59818dab77a88c417df1dfeae615400', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00113B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Youth futures after mobility') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alumni scholarships', 'The Flinders University Alumni Scholarship rewards eligible international graduates of the Universitys undergraduate and postgraduate programs with a 20% full duration scholarship to study another undergraduate or postgraduate degree at Flinders.', 'Available to alumni of Flinders University only; Full fee-paying international students (citizens of Australia and New Zealand and Australian Permanent Residents or other permanent visa holders are ineligible to apply).; Open to international students of any nationality; Available to applicants of an eligible course as outlined in the Terms and Conditions; Students must meet the entry requirements outline for the scholarship in addition to meeting standard entry requirements including English language requirements, any topic pre-requisites or work experience; Continuing eligibility requires students to maintain a GPA of 4.0 and a full time load of study', '20% full duration scholarship to study another undergraduate or postgraduate degree at Flinders', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.flinders.edu.au/international/apply/scholarships/alumni', 'https://search.studyaustralia.gov.au/scholarship/alumni-scholarships/c7cc3eb1bb94174fc945337f7c08129d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00114A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alumni scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'LATAM English Excellence Scholarship  English for Academic Purposes (EAP)', '-', 'Available to new students only commencing in 2026 and 2027.; Available only to full fee-paying international students from Latin America; There is no separate scholarship application process for the English for Academic Purposes Scholarships. Applications for English for Academic Purposes will automatically be assessed for scholarship eligibility and eligible applicants will be notified within their Letter of Offer to the course. Eligible applicants simply need to return the course Acceptance Form and the LATAM English Excellence Scholarship Acceptance Form for the scholarship to be awarded.', '30% reduction in tuition fees.; Scholarship value is the percentage reduction specified above.', 'Undergraduate / VET', NULL, 'https://www.flinders.edu.au/content/dam/documents/study/international/flinders-university-academy/english-studies-express-scholarship-terms-and-conditions-2026.pdf', 'https://search.studyaustralia.gov.au/scholarship/latam-english-excellence-scholarship-english-for-academic-purposes-eap/8e09d10fe8d31448e3dfcca154d3129f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00114A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'LATAM English Excellence Scholarship  English for Academic Purposes (EAP)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Early Bird Acceptance Grant - International Students', 'International students applying for an undergraduate or postgraduate course to study at La Trobe University can be rewarded a bonus grant for completing their admission process early. Recipients will automatically be eligible to receive an Early Bird Acceptance Grant of 5% of the first-year tuition fees.', 'Be a citizen of a country other than Australia or New Zealand and be applying to study in 2026/2027.; Be a newly offered international student from 1st April 2026.; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored).; Commence their studies at any of the La Trobe University Victorian campuses or Sydney Campus in 2026/2027.; Meet all entry requirements and commence their studies at any of our LTU campuses in Australia.; Students who receive a Conditional Confirmation of Enrolment (COE) will be considered eligible for the grant.; This grant is not available to La Trobe College Australia (LTCA) packaged students (ELICOS, Foundation, and Diploma).; All students who accept up until the deadline, including those who have already accepted, will be eligible for this grant.', 'Up to AUD $2000 — 5% of the First year Tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/early-bird-acceptance-grant-international-students', 'https://search.studyaustralia.gov.au/scholarship/early-bird-acceptance-grant-international-students/941de33c000219cfb9d766c4cc5f30c4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Early Bird Acceptance Grant - International Students') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Graduate Research PhD Project Scholarships', 'La Trobe University is offering a number of graduate research scholarship packages consisting of a generous stipend, tuition fee scholarship, and allowances to support outstanding graduate researchers applying for a PhD project. Apply now to join our vibrant research community.', 'To be eligible to apply for this scholarship, applicants must:; contact the primary supervisor listed against the project, and receive their invitation to submit a full application; meet the entrance requirements for the PhD', 'AUD $36000/year', 'Postgraduate', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/graduate-research-phd-project-scholarships2', 'https://search.studyaustralia.gov.au/scholarship/graduate-research-phd-project-scholarships/901e20d32d4f2dec6deb276acbaa874d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Graduate Research PhD Project Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'La Trobe Analytics and Insights Scholarship - 30%', 'Data is shaping our future, as industries everywhere rely on expert data analysts to make smarter decisions. With a degree in analytics, you\'ll learn to approach complex problems, spot trends, and turn numbers into meaningful insights. From business and healthcare to sports and finance, data drives it all-making this a career path that\'s in high demand. At La Trobe University, with access to world-class teaching and industry connections, you\'ll learn from leading researchers at our Centre for Data Analytics and Cognition (CDAC) and engage with global partners like SAS, Microsoft, PwC, and IBM. You\'ll also have the opportunity to apply for voluntary internships, gaining hands-on experience with top organisations.', 'To be eligible to apply for this scholarship, applicants must:; Be a new, international student commencing their course on the intake mentioned on their offer letter.; Be a citizen or permanent resident of a country other than Australia or New Zealand; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored); Be eligible for direct entry to the programs.; Meet all course academic and English entry requirements and commence their studies at any of the LTU Victorian and Sydney campuses in 2026/7.; Eligible students will have the scholarship applied to their offer letter, no application required.; All students must have passed the Genuine Student assessment, including financial checks, before they can be considered for this scholarship.; The scholarship may not be deferred to future intakes/years. If the recipient is unable to secure a student visa for that intake, the scholarship offer may be revoked.; Recipients are required to maintain full-time enrolment for the campus in their offer letter and demonstrate satisfactory academic progress throughout their studies.; Please refer to the Offer Letter for full terms and conditions.; Recipients will be required to participate in the International Scholarship Program events during their studies in Australia.; This scholarship can be combined with the Early Acceptance Grant to form a discount on first-year tuition fees. This is subject to all conditions being met for both offers.', '30% reduction in course fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-analytics-and-insights-scholarship-30', 'https://search.studyaustralia.gov.au/scholarship/la-trobe-analytics-and-insights-scholarship-30/b60dd39d37ecb61c7ac270c70d20b47d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'La Trobe Analytics and Insights Scholarship - 30%') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'La Trobe Analytics and Insights Scholarship - 50% and 100%', 'Data is shaping our future, as industries everywhere rely on expert data analysts to make smarter decisions. With a degree in analytics, you\'ll learn to approach complex problems, spot trends, and turn numbers into meaningful insights. From business and healthcare to sports and finance, data drives it all-making this a career path that\'s in high demand. At La Trobe University, with access to world-class teaching and industry connections, you\'ll learn from leading researchers at our Centre for Data Analytics and Cognition (CDAC) and engage with global partners like SAS, Microsoft, PwC, and IBM. You\'ll also have the opportunity to apply for voluntary internships, gaining hands-on experience with top organisations.', 'To be eligible to apply for this scholarship, applicants must:; Be a citizen of a country other than Australia or New Zealand.; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored).; Be applying for direct entry into one of the courses listed above. Other students are not eligible.; Commence their studies at any of the La Trobe University campuses in 2026/7.; Meet the University\'s English language requirements and all other conditions stated on the Offer Letter.; Obtain an offer letter before selection for the scholarship. Exceptions must be approved by La Trobe University. All students must have passed Genuine Student assessment, including financial checks before they can be considered for this scholarship.', 'A reduction of 50 or 100% off the total course tuition fee', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-analytics-and-insights-scholarship-50-and-100', 'https://search.studyaustralia.gov.au/scholarship/la-trobe-analytics-and-insights-scholarship-50-and-100/ab7c24d0e70f8ff2f89c34ba94c1604a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'La Trobe Analytics and Insights Scholarship - 50% and 100%') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'La Trobe Artificial Intelligence Scholarship - 30%', 'La Trobe University has a bold ambition to transform research, education, and student experience by applying an \'AI-first\' approach, supported by a new partnership with Microsoft Australia and New Zealand and leading cyber security provider CyberCX. Artificial intelligence is one of the most transformative fields in technology today. Revolutionising industries from healthcare to finance, AI is offering solutions to complex problems and creating new possibilities. At La Trobe, our students gain essential skills in programming, data analysis, and machine learning, equipping them to shape the future of technology. As AI continues to evolve, so will the strong demand for artificial intelligence professionals in the public and private sectors, including opportunities in digital healthcare, smart manufacturing, smart cities, sustainable energy infrastructure, precision agriculture and more.', 'To be eligible to apply for this scholarship, applicants must:; Be a new, international student commencing their course on the intake mentioned on their offer letter.; Be a citizen or permanent resident of a country other than Australia or New Zealand; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored); Be eligible for direct entry to the programs.; Meet all course academic and English entry requirements and commence their studies at any of the LTU Victorian and Sydney campuses in 2026 or 2027.; Eligible students will have the scholarship applied to their offer letter, no application required.; All students must have passed the Genuine Student assessment, including financial checks, before they can be considered for this scholarship.; The scholarship may not be deferred to future intakes/years. If the recipient is unable to secure a student visa for that intake, the scholarship offer may be revoked.; Recipients are required to maintain full-time enrolment for the campus in their offer letter and demonstrate satisfactory academic progress throughout their studies.; Please refer to the Offer Letter for full terms and conditions.; Recipients will be required to participate in the International Scholarship Program events during their studies in Australia.; This scholarship can be combined with the Early Acceptance Grant to form a discount on first-year tuition fees. This is subject to all conditions being met for both offers.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-artificial-intelligence-scholarship-30', 'https://search.studyaustralia.gov.au/scholarship/la-trobe-artificial-intelligence-scholarship-30/54641bb172e9eea398f517e3a0bd0b90', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'La Trobe Artificial Intelligence Scholarship - 30%') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'La Trobe Artificial Intelligence Scholarship - 50% and 100%', 'La Trobe University has a bold ambition to transform research, education, and student support by applying an \'AI-first\' approach, supported by a new partnership with Microsoft Australia and New Zealand and leading cyber security provider CyberCX. Artificial intelligence is one of the most transformative fields in technology today. Revolutionising industries from healthcare to finance, AI is offering solutions to complex problems and creating new possibilities. At La Trobe, our students gain essential skills in programming, data analysis, and machine learning, equipping them to shape the future of technology. As AI continues to evolve, so will the strong demand for artificial intelligence professionals in the public and private sectors, including opportunities in digital healthcare, smart manufacturing, smart cities, sustainable energy infrastructure, precision agriculture and more.', 'To be eligible to apply for this scholarship, applicants must:; Be a citizen of a country other than Australia or New Zealand.; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored).; Be applying for direct entry into one of the courses listed above. Other students are not eligible.; Commence their studies at any of the La Trobe University campuses in 2026 or 2027.; Meet the University\'s English language requirements and all other conditions stated on the Offer Letter.; Obtain an offer letter before selection for the scholarship. Exceptions must be approved by La Trobe University. All students must have passed Genuine Student assessment, including financial checks before they can be considered for this scholarship.', 'A reduction of either 50% or 100% off the total course tuition fee.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-artificial-intelligence-scholarship-50-and-100', 'https://search.studyaustralia.gov.au/scholarship/la-trobe-artificial-intelligence-scholarship-50-and-100/6c87299033aab7d272bc19c58291fddd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'La Trobe Artificial Intelligence Scholarship - 50% and 100%') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'La Trobe Flexible Research Scholarship (Flex) - Candidates With Disabilities', 'In order to maximize opportunities for students with disabilities to study higher degrees by research, La Trobe University is offering the Flexible Research Scholarship to eligible applicants with disabilities, who already hold a Research Training Program (RTP) stipend or a La Trobe University Graduate Research Scholarship (LTGRS) stipend. This scholarship provides individually tailored support, providing a longer period of time for completion of a graduate research degree and payment of a stipend, extended periods of leave of absence, and provide access to additional funding for research related costs associated with having a disability.', 'currently be receiving a Research Training Program (RTP) stipend or a La Trobe University Graduate Research Scholarship (LTGRS) stipend, or have accepted an offer of RTP or LTGRS, and have a disability that is attributable to one or more intellectual, cognitive, neurological, sensory, or physical impairments or to one or more impairments attributable to a psychiatric condition; and the impairment or impairments are, or are likely to be, permanent; and (b) the impairment or impairments result in substantially reduced functional capacity to undertake, or psychosocial functioning in undertaking, one or more of the following.', 'Up to AUD $36000 — Up to 18 month extension to RTP or LTGRS stipend for doctoral candidates and up to 8 month extension for research masters candidates', 'Postgraduate', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-flexible-research-scholarship-flex-candidates-with-disabilities', 'https://search.studyaustralia.gov.au/scholarship/la-trobe-flexible-research-scholarship-flex-candidates-with-disabilities/a3abd641af7c3a05e631571893e6a762', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'La Trobe Flexible Research Scholarship (Flex) - Candidates With Disabilities') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'La Trobe Health Innovation Scholarship - 30%', 'Join a university that\'s in the top 150 Worldwide for Public Health. La Trobe leads in future-focused healthcare with our digital health courses. Students can gain valuable expertise in specialisms such as Big Data analytics, virtual healthcare, Internet of Medical Things (IoMT), cybersecurity, and artificial intelligence. Students get the chance to work on real-world projects with industry partners to graduate job ready whilst gaining an in-demand skill set to design, implement and manage digital health solutions that meet the evolving healthcare needs of individuals and communities.', 'To be eligible to apply for this scholarship, applicants must:; Be a new, international student commencing their course on the intake mentioned on their offer letter.; Be a citizen or permanent resident of a country other than Australia or New Zealand; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored); Be eligible for direct entry to the programs.; Meet all course academic and English entry requirements and commence their studies at any of the LTU Victorian and Sydney campuses in 2026 and 2027.; Eligible students will have the scholarship applied to their offer letter, no application required.; All students must have passed the Genuine Student assessment, including financial checks, before they can be considered for this scholarship.; The scholarship may not be deferred to future intakes/years. If the recipient is unable to secure a student visa for that intake, the scholarship offer may be revoked.; Recipients are required to maintain full-time enrolment for the campus in their offer letter and demonstrate satisfactory academic progress throughout their studies.; Please refer to the Offer Letter for full terms and conditions.; Recipients will be required to participate in the International Scholarship Program events during their studies in Australia.; This scholarship can be combined with the Early Acceptance Grant to form a discount on first-year tuition fees. This is subject to all conditions being met for both offers.', '30% reduction in course fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-health-innovation-scholarship-30', 'https://search.studyaustralia.gov.au/scholarship/la-trobe-health-innovation-scholarship-30/d7064ef859ebef05cbe60f4dd9227ed9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'La Trobe Health Innovation Scholarship - 30%') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'La Trobe High Achiever Scholarship', 'La Trobe University values academic excellence. High-achieving international students considering applying for an undergraduate or postgraduate course will be automatically considered for this scholarship. The La Trobe High Achiever Scholarship rewards high achieving International students. This scholarship is worth between 15% to 25% off the annual tuition fees for the duration of studies.', 'Be a citizen of a country other than Australia or New Zealand and be applying to start an undergraduate or postgraduate coursework program.; Be a new international student commencing their course for any future 2026/2027 intake.', 'Up to 25% reduction in course fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-high-achiever-scholarship', 'https://search.studyaustralia.gov.au/scholarship/la-trobe-high-achiever-scholarship/28c2450782780ad9631aceb2df8ec590', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'La Trobe High Achiever Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'La Trobe Humanitarian Scholarship', 'La Trobe University recognises the important contribution that people from refugee and asylum seeker backgrounds make to the Australian community.', 'Please contact La Trobe University for more information about Eligibility', '100% of tuition fees and $5000 per annum cost-of-living scholarship.', 'Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-humanitarian-scholarship', 'https://search.studyaustralia.gov.au/scholarship/la-trobe-humanitarian-scholarship/20de624aea50da17289927eb517a8f30', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'La Trobe Humanitarian Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'La Trobe Vice Chancellor Scholarship', 'At La Trobe, we recognize and support future leaders who are driven to make a difference. The Vice Chancellor Scholarship is our most prestigious scholarship, awarded to individuals who have excelled not only in their studies but also in extracurricular activities, sports, and community engagement - those who go beyond academics to create real change. This highly competitive scholarship offers either 50% or 100% tuition fee reduction. Through this scholarship, recipients will become part of a vibrant, innovative, and globally connected university, and will be a part of the La Trobe University student ambassador program, where they can develop the skills and networks to shape the future.', 'Be a citizen of a country other than Australia or New Zealand.; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored).; Be applying for direct entry into one of the eligible courses. Other students are not eligible.; Commence their studies at any of the La Trobe University Victorian campuses in 2026 or 2027.; Meet the University\'s English language requirements and all other conditions stated on the Offer Letter.; Obtain an offer letter before selection for the scholarship. Exceptions must be approved by La Trobe University. All students must have passed Genuine Student assessment, including financial checks before they can be considered for this scholarship.', 'A reduction of either 50% or 100% off the total course tuition fee.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-vice-chancellor-scholarship', 'https://search.studyaustralia.gov.au/scholarship/la-trobe-vice-chancellor-scholarship/f8384e7eb2ebd35a48f52666b32da611', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'La Trobe Vice Chancellor Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Placement Travel Bursary', 'The Office of the Provost is offering support to help students undertaking placement with the costs involved in travelling long distances and finding suitable accommodation.', 'To be eligible to apply for this scholarship, applicants must:; Be currently enrolled in an undergraduate or entry-level to practice course at a La Trobe University Campus. Note: partner institution enrolled students are not eligible for this payment.; Be enrolled in a placement subject and commencing an internship/work placement during one of the above assessment periods. PLEASE NOTE: The placement needs to have commenced during one of the three assessment periods but it does not have to be completed in that period.; Undertaking a placement in a location 120 kms (one way) or more from your semester/term address. Ensure that your semester/term address is current in StudentOnline and InPlace.; Undertaking a single placement greater than 10 days duration and lodged in InPlace at the time of applying. Length of placement is based on subject requirements and does not include make up days. (1 day is considered 8 hours); Not have received any other University-provided funding support related to placements in the 2026 academic year. This does not include the Commonwealth Prac Payment (CPP), which is a living stipend administered by the University on behalf of the Commonwealth Government.', 'Up to AUD $1365', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/placement-travel-bursary', 'https://search.studyaustralia.gov.au/scholarship/placement-travel-bursary/07179264499d5636ebc6f7f7ac0c353c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Placement Travel Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Wominjeka - Study Abroad Scholarship', 'Embark on a transformative journey with La Trobe University\'s Study Abroad Scholarship. Wominjeka - meaning "Welcome" and "Come With Purpose" in Woiwurrung, the language of the Wurundjeri people - reflects the spirit of La Trobe and the values we uphold. Guided by this ethos, our scholarships support students from La Trobe\'s partner universities and agents, making global learning more accessible to those who might not otherwise afford it. Rooted in a commitment to social justice, our study abroad program offers transformative experiences - including deep engagement with First Nations knowledge and perspectives.', 'Be applying through a La Trobe international partner university or authorised agent.; Be willing to take part in a short, non-credit bearing First Nations activity offered by La Trobe, or enrol in an approved credit bearing First Nations unit or be nominated by your home university or education agent as a student from an equity or underrepresented background.; Be applying and eligible for the La Trobe study abroad program (one or two semesters).; Commence their studies at any of the La Trobe University Victorian campuses in either Semester 2 2026, Semester 1 or 2 2027.', 'A reduction of 25% off the total course tuition fee', 'Undergraduate / VET', NULL, 'https://www.latrobe.edu.au/study/scholarships/other/wominjeka-study-abroad-scholarship', 'https://search.studyaustralia.gov.au/scholarship/wominjeka-study-abroad-scholarship/ae3b0a5f031365442163480f555c71eb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00115M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Wominjeka - Study Abroad Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'A G Whitlam International Undergraduate Merit Scholarship', 'The A G Whitlam International Undergraduate Merit Scholarship is offered to talented international students who are enrolling in the Bachelor of Commerce.', 'To be considered for this scholarship, you must: A citizen from one of the designated countries (for Semester 1: Sri Lanka and Bangladesh; for Semester 2: India, Vietnam and Bangladesh), meet the entry requirements for the Bachelor of Commerce.', 'Up to 50% fee remission for the duration of the Bachelor of Commerce (up to 300 points).', 'Undergraduate / VET', 'Business and management', 'http://scholarships.unimelb.edu.au/awards/ag-whitlam-international-undergraduate-merit-scholarship', 'https://search.studyaustralia.gov.au/scholarship/a-g-whitlam-international-undergraduate-merit-scholarship/7b0c41f8a507cc12b5637202a9fb0f67', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'A G Whitlam International Undergraduate Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ann and Peter Law Scholarship for Cello', 'The Ann and Peter Law Scholarship for Cello is offered to students enrolled in a Bachelor of Music specialising in Cello who are experiencing financial need.', 'To be considered, you must be enrolled in the Bachelor of Music and specialising in Cello.', 'Up to AUD $7600', 'Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/ann-and-peter-law-scholarship-for-cello', 'https://search.studyaustralia.gov.au/scholarship/ann-and-peter-law-scholarship-for-cello/81ddb5322825f5b95f89317264ad03f7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ann and Peter Law Scholarship for Cello') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australian Government Research Training Program Scholarships (RTP)', 'The Research Training Program Scholarship is supported by the Australian Commonwealth Government and the University of Melbourne, and offered to high-achieving domestic and international research students.', 'To be considered for the Research Training Program Scholarship, you must have applied for and meet the entry requirements for a graduate research degree or be enrolled in a graduate research degree at the University of Melbourne.', 'See scholarship details', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://scholarships.unimelb.edu.au/awards/research-training-program-scholarship', 'https://search.studyaustralia.gov.au/scholarship/australian-government-research-training-program-scholarships-rtp/288effe179d931e65560b9d30742a7e6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian Government Research Training Program Scholarships (RTP)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australian Industrial Relations Commission (AIRC) Centennial Prize', 'The Australian Industrial Relations Commission Centennial Prize was established in 2006 and is offered to students with the best essay or thesis in the field of Industrial Relations or Labour History.', 'To be considered for this prize, you must:; Be enrolled in an undergraduate or graduate degree in the Faculty of Business and Economics or the Faculty of Arts; Be undertaking a specialisation or an individual subject related to the field of Industrial Relations or Labour History.', 'Up to AUD $1000 — At least $1000.', 'Postgraduate, Undergraduate / VET', 'Economics', 'https://scholarships.unimelb.edu.au/awards/airc-centennial-prize', 'https://search.studyaustralia.gov.au/scholarship/australian-industrial-relations-commission-airc-centennial-prize/e85badd3c8b6c51507bb520bf5c40480', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian Industrial Relations Commission (AIRC) Centennial Prize') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bachelor of Commerce Global Scholarship', 'The Commerce Global Scholarships is offered to high-achieving students from countries deemed to be under-represented in the Bachelor of Commerce.', 'To be considered for the Research Training Program Scholarship, you must have applied for and meet the entry requirements for a graduate research degree or be enrolled in a graduate research degree at the University of Melbourne.', 'The scholarship provides 20% fee sponsorship for the duration of the course (300 credit points).', 'Undergraduate / VET', 'Business and management', 'https://scholarships.unimelb.edu.au/awards/bachelor-of-commerce-global-scholarship', 'https://search.studyaustralia.gov.au/scholarship/bachelor-of-commerce-global-scholarship/247cbcf1b11dd5bc5c8de903ca4651c9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bachelor of Commerce Global Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Brian Entwisle Scholarship', 'The Brian Entwisle Scholarship was established with a gift from Brian Roger Entwisle and is awarded to students who are enrolled in the Doctor of Medicine and are experiencing disadvantaged circumstances. Preference is given to students who have a disability and/or medical condition and/or are from a regional or remote area of Australia.', 'To be considered for this scholarship, you must be enrolled in the Doctor of Medicine.', 'Up to AUD $48000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/brian-entwisle-scholarship', 'https://search.studyaustralia.gov.au/scholarship/brian-entwisle-scholarship/c66e7d39713c035ca883596248869524', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Brian Entwisle Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'C S Soper and Joan Rydon Scholarship', 'The C. S. Soper and Joan Rydon Scholarship was established in memory of Emeritus Professor Charles Samuel Soper, and is offered to talented Honours students studying Economics who are specialising in economic theory or mathematical economics.', 'To be considered for this scholarship, you must be commencing the Bachelor of Commerce (Honours) in Economics specialising in economic theory or mathematical economics.', 'Up to AUD $7500 — This scholarship provides a one-off payment of approximately $7500 (depending on the available income from the gift).', 'Undergraduate / VET', 'Economics', 'http://scholarships.unimelb.edu.au/awards/cs-soper-and-joan-rydon-scholarship', 'https://search.studyaustralia.gov.au/scholarship/c-s-soper-and-joan-rydon-scholarship/5fb8a072871fef3e7f951224f244e89d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'C S Soper and Joan Rydon Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Califole Melbourne Medical School Scholarship', 'The Califole Melbourne Medical School Scholarship is offer to students who are enrolled in the Doctor of Medicine, have completed their secondary schooling in a state or territory government school, and are experiencing financial disadvantage. Preference is given to students who are from a regional or remote area of Australia.', 'To be considered for this scholarship, you must:; Be enrolled in the first year of the Doctor of Medicine; Have completed secondary schooling in a state or territory government school.', 'Up to AUD $60000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/califole-melbourne-medical-school-scholarship', 'https://search.studyaustralia.gov.au/scholarship/califole-melbourne-medical-school-scholarship/fc36a66ae9c8f57e92fe72b64ffceeb8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Califole Melbourne Medical School Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Cassidy Scholarship', 'The Cassidy Scholarship is offered to talented undergraduate or graduate students studying Music, Theatre, Production or Music Theatre.', 'To be considered for this scholarship, you must:; Be enrolled in an undergraduate or graduate course in Music (Jazz and Improvisation or Interactive Composition), Theatre, Production or Music Theatre in the Faculty of Fine Arts and Music\r\nMusic Theatre will only consider 2nd year undergraduates. All other participating disciplines will select from any year level.', 'Up to AUD $6000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/cassidy-bequest-scholarship', 'https://search.studyaustralia.gov.au/scholarship/cassidy-scholarship/e04d3bb3483328deb23a48bc8244675f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Cassidy Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Cbus Super Mavis Robertson Scholarship', 'The Cbus Super Mavis Robertson Scholarship is offered to Bachelor of Commerce students who are experiencing disadvantaged circumstances. Preference is given to female students.', 'To be considered for this scholarship, you must:; Be completing at least 100 points of the Bachelor of Commerce (at the time of application); Be enrolling in the second year of the Bachelor of Commerce', 'Up to AUD $26000', 'Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/cbus-super-mavis-robertson', 'https://search.studyaustralia.gov.au/scholarship/cbus-super-mavis-robertson-scholarship/a9e451c0bca2a71837ec58511872e1ea', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Cbus Super Mavis Robertson Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Commerce Undergraduate International Partner Scholarships', 'The Commerce Undergraduate International Partner Scholarship is offered to international students who are enrolling in the Bachelor of Commerce and have studied with our partner institutions.', 'To be considered for this scholarship, you must have applied and meet the entry requirements for the Bachelor of Commerce and have attended one of the following international partner institutions: Trinity College Foundation Studies (Australia), Universitas Gadjah Mada or Universitas Indonesia (Indonesia), HELP University, Taylor’s College or Sunway College (Malasyia), Markham College (Peru), Nanyang Polytechnic, Ngee Ann Polytechnic, Singapore Polytechnic, or Temasek Polytechnic, (Singapore)', '50% fee sponsorship for the duration of the Bachelor of Commerce (up to 300 points).', 'Undergraduate / VET', 'Accounting, Business and management, Economics', 'http://scholarships.unimelb.edu.au/awards/international-undergraduate-partner-scholarships', 'https://search.studyaustralia.gov.au/scholarship/commerce-undergraduate-international-partner-scholarships/389c3005bac1cefc4f0e310d0a3f7d83', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Commerce Undergraduate International Partner Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Computing and Information Systems PhD Scholarship', 'The Computing and Information Systems PhD Scholarship is offered to high achieving graduates of the University of Melbourne Master of Computer Science who are enrolling in the Doctor of Philosophy - Engineering and Information Technology in Computing and Information Systems.', 'To be considered for this scholarship, you must:; Have applied for and met requirements for the Doctor of Philosophy - Engineering and Information Technology in Computing and Information Systems; Have graduated from the University of Melbourne with a Master of Computer Science.', 'Up to AUD $70000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/computing-and-information-systems-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/computing-and-information-systems-phd-scholarship/2a890f1e758cf687bc38c30cc4eef68b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Computing and Information Systems PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'David Ashton Scholarship', 'The David Ashton Scholarship is supported by the Melbourne Botany Foundation and is offered to high-achieving graduate researchers who are enrolled in the Doctor of Philosophy in the Faculty of Science and undertaking research in the field of Botany.', 'To be considered for this scholarship, you must:; Be enrolled in the Doctor of Philosophy in the Faculty of Science and be undertaking research in Botany in the School of Biosciences (or its successor); Have achieved academic results at Honours 2A level or above (or equivalent).', 'Up to AUD $6000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/david-ashton-scholarship', 'https://search.studyaustralia.gov.au/scholarship/david-ashton-scholarship/f2bbbd0e9772f0e60349d05c988a7ebd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'David Ashton Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'David Ashton Travel Award', 'The David Ashton Travel Award was established with a gift from David Hungerford Ashton to the University of Melbourne Botany Foundation and is awarded to students who are enrolled in the Bachelor of Science (Degree with Honours) or a graduate coursework or research degree with the Faculty of Science, and who are undertaking travel for the purpose of fieldwork in the field of Plant Ecology.', 'To be considered for this award, you must be enrolled in a bachelor degree with honours, a graduate coursework or graduate research degree with the Faculty of Science and undertaking research in the field of Plant Ecology.', 'Up to AUD $2500', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/david-ashton-travel-award', 'https://search.studyaustralia.gov.au/scholarship/david-ashton-travel-award/49603eb56e76ce1d26fa3e811d250170', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'David Ashton Travel Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Dr Phillip Law Music Scholarship', 'The Dr Phillip Law Music Scholarship is offered to students who exhibit the greatest excellence in innovative performance and commitment in the Improvisation major.', 'Be enrolled in either the Bachelor of Music (Jazz and Improvisation), Bachelor of Music (Interactive Composition), Bachelor of Music (Honours), Master of Music (Research) or Doctor of Philosophy - Fine Arts and Music specialising in Jazz and Improvisation or Interactive Composition.', 'Up to AUD $6000', 'Undergraduate / VET, Postgraduate', 'Creative arts', 'https://scholarships.unimelb.edu.au/awards/dr-phillip-law-music-scholarship', 'https://search.studyaustralia.gov.au/scholarship/dr-phillip-law-music-scholarship/938394637bee40a672e584e275ea41e9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Dr Phillip Law Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Eliza McCauley Award', 'The Eliza McCauley Award is offered students who achieved the highest mark for the subject Health Care in Context.', 'Please contact University of Melbourne for further information.', 'This award provides a one-off payment of $200.', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/eliza-mccauley-award', 'https://search.studyaustralia.gov.au/scholarship/eliza-mccauley-award/18bc648401694cb542704a7c6d5a8959', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Eliza McCauley Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ethel McLennan Award', 'The Ethel McLennan Award was established with a gift from the University of Melbourne School of Botany Foundation in memory of the late Dr Ethel McLennan and is offered to talented students or graduate researchers enrolled in a graduate research degree in the field of Botany in recognition of their excellent academic achievement.', 'To be considered for this award, you must:; Be enrolled in the Master of Philosophy -  Science or Doctor of Philosophy - Science (or their successors) and be undertaking research in the field of Botany; Have met requirements for confirmation of your candidature.', 'Up to AUD $3500', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/ethel-mclennan-award', 'https://search.studyaustralia.gov.au/scholarship/ethel-mclennan-award/d576a27bb4d2185f2719e994bf880bae', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ethel McLennan Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'FMAA First Year High Achiever Award', 'The FMAA First Year High Achiever Award is supported by the Financial Management Association of Australia and is offered to high-achieving students from the Faculty of Business and Economics at the University of Melbourne.', 'To be considered for this award, you must:; Be completing your first year of the Bachelor of Commerce in 2026 with the intention to commence your second year in 2027; Have a minimum WAM of 80% in your tertiary studies; Have completed or are enrolled in a total of at least 75 credit points in first year; Be able to demonstrate: Leadership experience, Participation in activities or organisations involving the Faculty of Business & Economics or the University of Melbourne, or, Participation in activities or organisations to engage with industry and/or professional organisations.', 'Up to AUD $2500 — $2,500 to contribute to your educational expenses. Professional mentoring with a representative from Macquarie Group, the FMAA\'s Gold and Founding Sponsor', 'Undergraduate / VET', 'Business and management', 'https://scholarships.unimelb.edu.au/awards/fmaa-first-year-high-achiever-award', 'https://search.studyaustralia.gov.au/scholarship/fmaa-first-year-high-achiever-award/a11656fffc85d7fa5f18a51caa4ad83a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'FMAA First Year High Achiever Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'GAM Scott Research Award', 'The GAM Scott Research Award was established with a gift from friends and associates of George Anderson MacDonald Scott and is offered to students or graduate researchers enrolled in a research degree in Botany in the areas of bryophytes or plant ecology who are undertaking field work. Preference will be given to research work involving bryophytes.', 'To be considered for this award, you must:; Be enrolled in Honours or PhD in the field of Botany in the School of Bioscience; Be undertaking research that involves field work the area of bryophytes or plant ecology.', 'Up to AUD $7000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/g-a-m-scott-research-fund', 'https://search.studyaustralia.gov.au/scholarship/gam-scott-research-award/3ab62f1b105998ce755c455e538af334', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'GAM Scott Research Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'George Hicks Awards', 'This scholarship is for graduating postgraduate students specialising in art.', 'Please contact University of Melbourne for further information.', 'A single payment of approximately $2000.', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/george-hicks-awards', 'https://search.studyaustralia.gov.au/scholarship/george-hicks-awards/02cce79528c0b6c165af3e33076fc45c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'George Hicks Awards') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Grace Ella Fraser Fund', 'The Grace Ella Fraser Fund is offered to undergraduate cello students at the Melbourne Conservatorium of Music who have outstanding talent and are in financial need.', 'To be considered for this scholarship, you must be enrolled in the Bachelor of Music specialising in Cello.', 'Up to AUD $7300', 'Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/grace-ella-fraser-fund', 'https://search.studyaustralia.gov.au/scholarship/grace-ella-fraser-fund/b18f226f81c621658567188274c98391', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Grace Ella Fraser Fund') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Grathelms Piano Award', 'The Grathelms Piano Award was established with a gift from Neil McGrath and is offered to talented students enrolled in the Bachelor of Music (Performance) or Master of Music (Music Performance) specialising in Piano who are experiencing immediate disadvantaged circumstances. Preference is given to students who are commencing the penultimate or final year of their degree.', 'To be considered for this award, you must:; Be enrolled in the Bachelor of Music (Performance) or Master of Music (Music Performance) (or their successors) and specialising in Piano.', 'Up to AUD $10000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/grathelms-piano-award', 'https://search.studyaustralia.gov.au/scholarship/grathelms-piano-award/2bb5d725db2b3b1934d910be7e8cd3d2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Grathelms Piano Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Gretna Weste Plant Pathology & Mycology Scholarship', 'The Gretna Weste Plant Pathology & Mycology Scholarship is awarded to talented students who are engaged in honours or graduate research in the field of plant pathology or mycology in the University of Melbourne School of BioSciences.', 'To be considered for this scholarship, you must be enrolled in honours or graduate research in the field of plant pathology or mycology, in the School of BioSciences.', 'Up to AUD $2000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/gretna-weste-plant-pathology-and-mycology-scholarship', 'https://search.studyaustralia.gov.au/scholarship/gretna-weste-plant-pathology-mycology-scholarship/36afc4f3f26080f5179eb30da4773cd4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Gretna Weste Plant Pathology & Mycology Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Harry Hains Master of Film and Television Scholarship', 'The Harry Hains Master of Film and Television Scholarship supports students enrolled in the Master of Film and Television who are in financial need.', 'To be considered for this scholarship, you must be enrolled in or have received an offer to study the Master of Film and Television.', 'Up to AUD $40000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/harry-hains-master-of-film-and-television-scholarship', 'https://search.studyaustralia.gov.au/scholarship/harry-hains-master-of-film-and-television-scholarship/9ee09014fa47bb455439e550a48be22d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Harry Hains Master of Film and Television Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Harry Hains Memorial Film Bursary', 'The Harry Hains Memorial Film Bursary was established with a gift from the Portland House Foundation and is offered to students who are enrolled in the Film and Television discipline and require financial support with their film or screen project.', 'To be considered for this bursary, you must be enrolled in the final year of the Bachelor of Fine Arts (Film and Television) or Bachelor of Fine Arts Honours (Film and Television) or any year of the Master of Film and Television.', 'Up to AUD $5000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/harry-hains-memorial-film-bursary', 'https://search.studyaustralia.gov.au/scholarship/harry-hains-memorial-film-bursary/a42423447f5e2d983daac702540b56c8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Harry Hains Memorial Film Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Harry Hains Memorial Theatre Bursaries', 'The Harry Hains Memorial Theatre Bursaries were established with a gift from the Helen and David Hains Foundation and are awarded to students who are enrolled with the Victorian College of the Arts in a degree in a field of theatre and are experiencing financial disadvantage.', 'To be considered for this bursary, you must be enrolled in one of the Bachelor of Fine Arts (Theatre), Bachelor of Fine Arts (Acting), Bachelor of Fine Arts Honours (Theatre), Bachelor of Fine Arts Honours (Acting), Master of Theatre (Dramaturgy), Master of Theatre (Directing) or Master of Theatre (Writing) in the year for which the bursary is awarded.', 'Up to AUD $5000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/harry-hains-memorial-theatre-bursaries', 'https://search.studyaustralia.gov.au/scholarship/harry-hains-memorial-theatre-bursaries/53000e0bbab2bd6906dd376ed097571d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Harry Hains Memorial Theatre Bursaries') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ivy May Pendelbury Scholarship', 'The Ivy May Pendlebury Bursary is offered to students and graduate researchers who are enrolled in a coursework or research degree at the Melbourne Conservatorium of Music, are members of the Church of England, and are experiencing financial disadvantage.', 'Applicants must: be enrolled in an undergraduate or graduate studies at the Melbourne Conservatorium of Music; demonstrate financial need; and be members of the Anglican Church. Selection is based on previous results (VCE or tertiary).', 'Up to AUD $10000', 'Undergraduate / VET', 'Creative arts', 'https://scholarships.unimelb.edu.au/awards/ivy-may-pendelbury-scholarships', 'https://search.studyaustralia.gov.au/scholarship/ivy-may-pendelbury-scholarship/eacc6a81f60797d2ef6b07a0b0044bfe', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ivy May Pendelbury Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'John S Turner Postgraduate Scholarship', 'The John S Turner Postgraduate Scholarship is supported by the School of Botany Foundation and is offered to graduate researchers who are enrolled in the Doctor of Philosophy (Science) and undertaking research in the field of plant physiology, plant ecology or conservation plant biology.', 'To be considered for this scholarship, you must:; Be enrolled in the Doctor of Philosophy in the discipline of Botany within the School of BioSciences; Undertaking research in the field of plant physiology, plant ecology or conservation plant biology', 'Up to AUD $4900', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/john-s-turner-postgraduate-scholarship', 'https://search.studyaustralia.gov.au/scholarship/john-s-turner-postgraduate-scholarship/7bb2f1c83cd2c1b59571194b726bc138', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'John S Turner Postgraduate Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'John and Eric Smyth Travelling Scholarship (Alumni)', '​​The John and Eric Smyth Travelling Scholarship was established with a gift from John Smyth and is offered to graduates of the University of Melbourne who can enrich the teaching profession and the work of the Faculty of Education by study overseas.​', 'To be considered for this ​award​, you must:; Be under 30 years of age at the time of submitting their application; Be planning to undertake a period of study or research overseas in the field of education', 'Up to AUD $100000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/john-and-eric-smyth-travelling-scholarship', 'https://search.studyaustralia.gov.au/scholarship/john-and-eric-smyth-travelling-scholarship-alumni/4c2b954ae894fc1909d64650a75cb798', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'John and Eric Smyth Travelling Scholarship (Alumni)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Jubilee Scholarship', 'The Jubilee Scholarship was established with a gift from an anonymous donor and is awarded to students who are enrolled in the third or fourth year of the Doctor of Medicine and are experiencing immediate financial disadvantage. Preference is given to students who are allocated to the Western Clinical School.', 'To be considered for this scholarship, you must:; Be enrolled in the Doctor of Medicine; Have completed at least 200 credit points of study.', 'Up to AUD $6000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/jubilee-scholarship', 'https://search.studyaustralia.gov.au/scholarship/jubilee-scholarship/c6481fbba1291024ec88e6e284082b99', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Jubilee Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Kate Flowers Scholarship', 'This scholarship supports students who have completed at least one year of full-time study of violin, viola or cello who have an ambition to make music their career. Shortlisted applicants are invited to submit a recording of their playing and attend an online interview.', 'To be considered for this scholarship, you must:; have completed at least one year of full-time study of violin, viola or cello; intend to make music your career', 'Up to AUD $10000 — The scholarship is valued at $10,000 for 1 year.', 'Undergraduate / VET', 'Creative arts', 'https://scholarships.unimelb.edu.au/awards/kate-flowers-memorial-scholarship', 'https://search.studyaustralia.gov.au/scholarship/kate-flowers-scholarship/39043d59917dc8f2307f4edbbc88c908', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Kate Flowers Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Lewis Prize', 'The Lewis Prize was estabilshed by the late James Monaham Lewis, whose main interest in dental science was in the specialty of periodontics.', 'Please contact University of Melbourne for further information.', '$150', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/lewis-prize', 'https://search.studyaustralia.gov.au/scholarship/lewis-prize/84b083359188c3bd42f56e28403789e6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Lewis Prize') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Lionel Gell Screen Production Bursary', 'The Lionel Gell Screen Production Bursary was established with a gift from the Lionel Gell Foundation and is offered to students who are producing high-quality, industry-standard graduation films as part of their final year of a degree in Film and Television and are experiencing financial need. Preference is given to high-achieving students.', 'To be considered for this bursary, you must be enrolled in the final year of the Bachelor of Fine Arts (Film and Television), Bachelor of Fine Arts (Degree with Honours) (Film and Television) or Master of Film and Television (either year).', 'Up to AUD $3500', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/lionel-gell-screen-production-bursary#main-content', 'https://search.studyaustralia.gov.au/scholarship/lionel-gell-screen-production-bursary/76efe1444b98803b784d0ff922d0e56f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Lionel Gell Screen Production Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'MDHS Scholarship Fund - Professional Graduate Scholarships', 'The MDHS Scholarship Fund - Professional Graduate Scholarships commenced in 2010 from donations within and outside the University by an appeal form, to support scholarships for students in medicine, dentistry and health sciences at The University of Melbourne.', 'Open to full-time students enrolled in the Doctor of Dental Surgery or Doctor of Medicine who have successfully completed 200 credit points and who are experiencing financial hardship.', 'Up to AUD $12000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/professional-graduate-scholarships', 'https://search.studyaustralia.gov.au/scholarship/mdhs-scholarship-fund-professional-graduate-scholarships/04020d722184eaf6c6c53ee08b47bdf9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'MDHS Scholarship Fund - Professional Graduate Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Mabel Kent Scholarship', 'The Mabel Kent Scholarship was established with a gift from Mabel Kent and is offered to students in financial need who are enrolled in a Doctor of Medicine course or studying Music (with a preference for singing).', 'To be considered for this scholarship, you must: Be enrolled in the Doctor of Medicine course or studying Music (with a preference for voice) at the University of Melbourne, Provide evidence of financial need.', 'Up to AUD $1500 — The scholarship provides a one-off payment of approximately $1,500 (depending on the income from the gift).', 'Undergraduate / VET', 'Medicine', 'https://scholarships.unimelb.edu.au/awards/mabel-kent-scholarship', 'https://search.studyaustralia.gov.au/scholarship/mabel-kent-scholarship/155b97aaecd6c443f877edd8eb970b77', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Mabel Kent Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Major Bartlett University Scholarships', 'The Major Bartlett University Scholarships was established by the late James Charles Bartlett, and is offered to microbiology students to assist with travel costs for conferences.', 'To be considered for this award, you must:; Be a current full time student enrolled in a Research Higher Degree (MPhil and PhD), Honours (BH-BMED or BH-SCI), or Master of Biomedical Science (MC-BMEDSC) through the Department of Microbiology and Immunology.; Use the scholarship in the same year it is awarded. If the applicant is unable to attend the conference, then the scholarship will be withdrawn.; Only apply for one conference at a time.', 'Up to AUD $200', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/major-bartlett-university', 'https://search.studyaustralia.gov.au/scholarship/major-bartlett-university-scholarships/a6ad487709cb3ad2c52b630ad462cf79', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Major Bartlett University Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Maureen Brunt Scholarship', 'The Maureen Brunt scholarship is offered to talented graduates of economics and who are undertaking study in an overseas university for a postgraduate degree or diploma in economics or in a field with a major component of economics.', 'To be considered for this scholarship, you must:; Have completed, or be completing, a degree in Economics at the University of Melbourne in 2026. This includes: BCom students who are majoring in Economics, BCom Honours students who are majoring in Economics, Master of Economics or Master of Commerce (Economics) students, PhD Economics students; Be intending to undertake study in Economics, or in a field with a major component of Economics, at an overseas university for a postgraduate coursework or research degree or diploma.; Have a letter of offer from an overseas institution to commence a postgraduate coursework or research degree in Economics or in a field with a major component of Economics.', 'Up to AUD $6000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/maureen-brunt-scholarship', 'https://search.studyaustralia.gov.au/scholarship/maureen-brunt-scholarship/3a63bacba85fe5452f4f69968c2c134e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Maureen Brunt Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Megan Klemm Postgraduate Research Award', 'The Megan Klemm Postgraduate Research Award is supported by the Melbourne Botany Foundation and is offered to graduate researchers who are enrolled in the Doctor of Philosophy in the field of Botany.', 'To be considered for this award, you must be enrolled in the Doctor of Philosophy in the field of Botany within the School of BioSciences.', 'Up to AUD $5000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/megan-klemm-postgraduate-research-award', 'https://search.studyaustralia.gov.au/scholarship/megan-klemm-postgraduate-research-award/b6d9ad8eecc761e623a3684daed4e7f5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Megan Klemm Postgraduate Research Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Melbourne International Undergraduate Scholarship', 'The Melbourne International Undergraduate Scholarship is offered to high-achieving students who are enrolling in a bachelor degree and are citizens of countries where international educational opportunities are limited by financial disadvantage.', 'To be considered for this scholarship, you must: Be a citizen of a country with a Gross Domestic Product per capita of US$10,000 or less based on data published by the World Bank. For the complete list of countries, see: Eligible countries. Have applied for and meet the entry requirements for an Overseas Fee place in a bachelor degree. Have completed secondary school outside Australia or a foundation program in Australia. Not have previously undertaken tertiary studies (excluding extension studies completed as part of a year 12 program).', 'This scholarship provides a 25 per cent fee sponsorship for the duration of the course.', 'Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://scholarships.unimelb.edu.au/awards/melbourne-international-undergraduate-scholarship', 'https://search.studyaustralia.gov.au/scholarship/melbourne-international-undergraduate-scholarship/dc080564845e75c8586f677c13a12a60', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Melbourne International Undergraduate Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Melbourne Mobility Excellence Awards', 'The Mobility Excellence Awards is a suite of scholarships offered to students with outstanding academic and personal qualities who are undertaking overseas study as part of their coursework degree.', 'To be considered for these awards, students must:; Be enrolled at the University of Melbourne in either an undergraduate degree or a graduate coursework degree; Intend to undertake approved overseas study of 12 weeks or more (Exchange or Study Abroad) as part of your course within 12 months of the closing date; Have achieved a Course Weighted Average of at least 80 in your current course', 'Up to AUD $8000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/melbourne-mobility-excellence-awards', 'https://search.studyaustralia.gov.au/scholarship/melbourne-mobility-excellence-awards/57ddbfe0b4926f862c7d0bff9631799c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Melbourne Mobility Excellence Awards') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Melbourne Research Scholarship', 'This scholarship is offered to high-achieving domestic and international students who are enrolling in a graduate research degree.', 'To be considered for this scholarship, you must: have applied for and meet the entry requirements for a graduate research degree at the University of Melbourne, or be currently enrolled in a graduate research degree at the University of Melbourne', '100% fee remission and up to $135,000', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://scholarships.unimelb.edu.au/awards/melbourne-research-scholarship', 'https://search.studyaustralia.gov.au/scholarship/melbourne-research-scholarship/58d1b453716d19e518082edd330b294e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Melbourne Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Nancy Lewis Scholarship', 'The Nancy Lewis Scholarship was established by Dr. Anne Brooks in commemoration of their mother, Dr Nancy Lewis and is offered to high achieving Doctor of Medicine students who experience disadvantaged circumstances.', 'To be considered for this scholarship, you must be enrolled in the Doctor of Medicine.', 'Up to AUD $5000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/nancy-lewis-scholarship', 'https://search.studyaustralia.gov.au/scholarship/nancy-lewis-scholarship/38cf73a9c5aa3fa6ce36dacedd333619', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Nancy Lewis Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Newman College Scholarships', 'Newman College awards financial aid in the form of scholarships and bursaries to around 75% of residents.', '-', 'Up to AUD $10000 — There are multiple accommodation fee scholarships available for varying amounts, up to $10,000 per annum. For information about eligibility, selection and application requirements, refer to Newman College Scholarships.', 'Postgraduate, Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://scholarships.unimelb.edu.au/awards/newman-college-scholarships', 'https://search.studyaustralia.gov.au/scholarship/newman-college-scholarships/bbcb9dd9f57a378cd66d51f853b2af56', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Newman College Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Orloff Family Charitable Trust Scholarship for Dance', 'This award is for third-year Bachelor of Fine Arts (Dance) students demonstrating the most outstanding talent.', 'To be considered for this award, you must be enrolled as an undergraduate student in Dance (third year) in the Faculty of Fine Arts and Music, showing outstanding talent.', 'Up to AUD $3500 — A one-off payment of approximately $3500.', 'Postgraduate, Undergraduate / VET', 'Creative arts', 'https://scholarships.unimelb.edu.au/awards/orloff-family-charitable-trust-scholarship-dance', 'https://search.studyaustralia.gov.au/scholarship/orloff-family-charitable-trust-scholarship-for-dance/29709a6fc7723421eacf47d6fa98ac50', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Orloff Family Charitable Trust Scholarship for Dance') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ormond College Frank Raleigh Scholarship', 'The scholarship is tenable at Ormond College, the University of Melbourne.', 'Applications are open to students from any year. Selection is based on academic excellence and financial need.', 'Up to AUD $3000 — The scholarship provides up to $3,000 towards residential fees.', 'Postgraduate, Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://ormond.unimelb.edu.au/alumni-friends/scholarships', 'https://search.studyaustralia.gov.au/scholarship/ormond-college-frank-raleigh-scholarship/29ca9e889dc958b49b8c4a8656171733', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ormond College Frank Raleigh Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ormond College Scholarships', 'Ormond College offers financial assistance to support students who face economic barriers impacting on their ability to reside at the College.The financial assistance program is made possible through the generosity of alumni and the Ormond community.', 'Please contact University of Melbourne for further information.', 'There are multiple accommodation fee scholarships available for varying amounts, from $5,000 to $36,000 per annum.', 'Undergraduate / VET, Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/ormond-college-scholarships', 'https://search.studyaustralia.gov.au/scholarship/ormond-college-scholarships/c4dfde0daaec8f29a9126b0e5423942a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ormond College Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Peter McMullin Centre on Statelessness PhD Scholarship', 'The Peter McMullin Centre on Statelessness (PMCS) welcomes applications from suitably qualified scholars for a place in the Melbourne Law School’s (MLS) PhD program for commencement in 2025. The successful candidate will be working under a supervisory team which will include PMCS academic staff, MLS academic staff affiliated with the Centre, and/or a co-supervisor from another University of Melbourne faculty if appropriate.', 'Applicants must be eligible for acceptance by the University of Melbourne into a PhD program. This scholarship is conditional upon acceptance into the PhD program at the Melbourne Law School, and the applicants need to meet the entry requirements of the Law School PhD program which can be found here. Applicants must also: have not completed a PhD previously. Be able to commence their PhD in 2025   – with a preferred start date in February 2025.', 'Up to AUD $122400 — Scholarship recipients undertaking a doctoral degree at the Peter McMullin Centre on Statelessness will be awarded: Full fee offset for up to four years. An annual stipend of AUD $38,500 (tax free) (2025 full-time study rate). The', 'Postgraduate', NULL, 'https://law.unimelb.edu.au/centres/statelessness/research/graduate-research/phd-scholarships', 'https://search.studyaustralia.gov.au/scholarship/peter-mcmullin-centre-on-statelessness-phd-scholarship/ad6fb5db3579a93c96814b686ab8f022', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Peter McMullin Centre on Statelessness PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Professor David Penington Scholarship', 'The Professor David Penington Scholarship was established with a gift from David Penington AC and is awarded to students who are enrolled in the Doctor of Medicine and are experiencing immediate financial disadvantage.', 'To be considered for this scholarship, you must be enrolled in the Doctor of Medicine.', 'Up to AUD $40000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/professor-david-penington-scholarship', 'https://search.studyaustralia.gov.au/scholarship/professor-david-penington-scholarship/a9aa6bb55856cfbf55792ee9304dc3c2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Professor David Penington Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RD Phillips Bursary', 'The RD Phillips Bursary was established with a gift from Royal Daniel Phillips and is awarded to students who are enrolled in the Doctor of Medicine and are experiencing immediate financial disadvantage.', 'To be considered for this bursary, you must be enrolled in the Doctor of Medicine.', 'Up to AUD $24000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/rd-phillips-bursary', 'https://search.studyaustralia.gov.au/scholarship/rd-phillips-bursary/3092abe2b5f937eab2b8f35e1bf3e338', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RD Phillips Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ron Rosanove Award', 'The Ron Rosanove Award was established by Dr Ron Rosanove and Mrs Elizabeth Rosanove, and is awarded to medical students enrolled at the Melbourne Medical School who are faced with financial difficulties that would prevent them from continuing their studies.', 'To be considered for this bursary, you must be enrolled in the Doctor of Medicine.', 'Up to AUD $10000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/ron-rosanove-award', 'https://search.studyaustralia.gov.au/scholarship/ron-rosanove-award/02466712c5375c7e36f6e4290c71daf3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ron Rosanove Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'SAF Music Provident Fund', 'This scholarship supports students enrolled in the Bachelor of Music Jazz and Improvisation or Bachelor of Music Interactive Composition with loans and grants for purposes associated with their music studies. Students can only receive SAF funds once during their candidacy.', 'To be considered for this scholarship, you must be an enrolled undergraduate student enrolled in the University of Melbourne Conservatorium of Music in either the Jazz and Improvisation or Interactive Composition disciplines.', 'Up to AUD $250', 'Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/saf-music-provident-fund', 'https://search.studyaustralia.gov.au/scholarship/saf-music-provident-fund/25117a18d3afac9bbb9d3d6e666b93e8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'SAF Music Provident Fund') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Samuel Crawcour Bursaries', 'The Samuel Crawcour Bursaries was established by the late Samuel Crawcour and is offered to medicine students who experience disadvantaged circumstances.', 'To be considered for this bursary, you must:; Be enrolled in the Doctor of Medicine; Demonstrate financial hardship', 'Up to AUD $10000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/samuel-crawcour-bursaries', 'https://search.studyaustralia.gov.au/scholarship/samuel-crawcour-bursaries/a80ea64c85617560913861abee49c798', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Samuel Crawcour Bursaries') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Sheppard M Lowe Scholarship', 'The Sheppard M Lowe Scholarship, established by the late Sheppard Millar Lowe, supports students undertaking a graduate research degree in the field of diabetes mellitus, and is worth approximately $16,000.', 'To be considered for this scholarship, you must: be an outstanding graduate research applicant, or a currently enrolled graduate researcher, of the Faculty of Medicine, Dentistry and Health Sciences, be undertaking research in the field of diabetes mellitus, satisfy the Faculty\'s entry requirements for PhD.', 'A fortnightly allowance for up to 1 year, totalling approximately $16,000.', 'Postgraduate', 'Medicine', 'https://scholarships.unimelb.edu.au/awards/sheppard-m-lowe-scholarship', 'https://search.studyaustralia.gov.au/scholarship/sheppard-m-lowe-scholarship/1ea112c29174a0ea06a79f78ee499155', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Sheppard M Lowe Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Sophie Ducker Postgraduate Scholarship', 'The Sophie Ducker Postgraduate Scholarship was established with a gift from friends and associates of Dr Sophie Charlotte Ducker and is offered to students who are enrolling or are enrolled in the Doctor of Philosophy in the field of Botany and undertaking research in Australian flora.', 'To be considered for this scholarship, students must:; Be enrolled in the Doctor of Philosophy in the discipline of Botany within the School of BioSciences; Undertaking research in the field of Australian flora; Not have received the Sophie Ducker Postgraduate Scholarship for a second year.', 'Up to AUD $4200', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/sophie-ducker-postgraduate-scholarship', 'https://search.studyaustralia.gov.au/scholarship/sophie-ducker-postgraduate-scholarship/4ccd5ecdf83f41113577007651b535bf', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Sophie Ducker Postgraduate Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'State Music Camp Victoria Award', 'The State Music Camp Victoria Award was established with a gift from the State Music Camp Victoria Limited and is offered to students who attended the camp and demonstrated a high standard of musicality and potential to further develop their conducting skills.', 'To be considered for this award, you must be enrolled as a Master of Music (Performance Teaching) or PhD student in Music (specialising in conducting) in the Faculty of Fine Arts and Music.', 'Up to AUD $9400', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/state-music-camp-victoria-award', 'https://search.studyaustralia.gov.au/scholarship/state-music-camp-victoria-award/399b61ae1b2ab5729943ebc80df7d8a9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'State Music Camp Victoria Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Stawell Scholarship', 'The Stawell Scholarship has been established to support Graduate Researchers within the field of Engineering in the Faculty of Engineering and Information Technology with a project of a proposal that will enhance their research outcomes.', 'be enrolled in a research higher degree within the field of Engineering in the Faculty of Engineering and Information Technology; be post-confirmation', 'Up to AUD $6600', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/stawell-scholarship', 'https://search.studyaustralia.gov.au/scholarship/stawell-scholarship/082308df6d9ea0127a24507ecddeaa44', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Stawell Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Suzanne and Geoffrey Dawson Scholarship', 'The scholarship is awarded to a high-achieving student enrolled in the Professional Learning Capstone as part of a Master of Teaching, and pursuing research in the field of education, the outcome of which is likely to enhance the advancement of social justice in educational settings and provide equality of access to improved facilitation of learning, in identified communities.', 'To be considered for this scholarship, you must:; Be enrolled in a Professional Learning Capstone subject as part of a Master of Teaching program; Be pursuing research in the field of education through the Professional Learning Capstone, the outcome of which is likely to enhance the advancement of social justice in educational settings and provide equality of access to improved facilitation of learning, in identified communities.', 'Up to AUD $6000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/suzanne-and-geoffrey-dawson-scholarship', 'https://search.studyaustralia.gov.au/scholarship/suzanne-and-geoffrey-dawson-scholarship/3bc78adb8bc36d203e34f71b922069e2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Suzanne and Geoffrey Dawson Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Warren Clark Agricultural Research Scholarship', 'The Warren Clark Agricultural Research Scholarship was established with a gift from Warren Clark and is offered to students who are enrolled in the Doctor of Philosophy – Science in Agricultural Sciences and are experiencing financial need.', 'Be enrolled in the Doctor of Philosophy (Science) (or its successor); Be undertaking research in the field of Agricultural Science; Have met the requirements for confirmation of your candidature.', 'Up to AUD $5000', 'Postgraduate', NULL, 'https://scholarships.unimelb.edu.au/awards/warren-clark-agricultural-research-scholarship', 'https://search.studyaustralia.gov.au/scholarship/warren-clark-agricultural-research-scholarship/a0add46eb76d4f56184d5852e69b7470', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Warren Clark Agricultural Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Wilfred Prest Travelling Fellowship', 'The Wilfred Prest Travelling Fellowship is open to students or graduates of the Faculty of Business and Economics who will undertake postgraduate studies in the field of Economics at an overseas university or research institution.', 'To be considered for this fellowship, you must:; be completing a degree in the Faculty of Business and Economics (Bachelor, Honours, Master or PhD) in 2026 specialising in Economics or have previously completed a degree from FBE specialising in Economics (Bachelor, Honours, Master or PhD); be undertaking or intending to undertake postgraduate studies in Economics at an overseas university or research institution in 2027.; be no more than 27 years of age at the time of the award', 'Up to AUD $16000 — Each fellowship is paid in two equal instalments: the first upon acceptance of the scholarship and evidence of full-time enrolment at the overseas university or research institution, and the second upon evidence of continued full-t', 'Postgraduate', 'Economics', 'https://scholarships.unimelb.edu.au/awards/wilfred-prest-travelling-fellowship', 'https://search.studyaustralia.gov.au/scholarship/wilfred-prest-travelling-fellowship/69f79b0ca139be60c622e30687383798', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Wilfred Prest Travelling Fellowship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'William Bardsley Award', 'The William Bardsley Award is offered to students who are enrolled in the Bachelor of Music or Master of Music specialising in violin performance and are experiencing financial need.', 'To be considered, you must be enrolled in either the Bachelor of Music or Master of Music (or their successors) specialising in violin performance.', 'Up to AUD $800', 'Undergraduate / VET', NULL, 'https://scholarships.unimelb.edu.au/awards/w-bardsley-award', 'https://search.studyaustralia.gov.au/scholarship/william-bardsley-award/7d59f051f5a89b43409a153a8980a219', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00116K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'William Bardsley Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australia Awards Scholarships', 'Australia Awards Scholarships are long-term awards administered by the Australian Department of Foreign Affairs and Trade that aim to contribute to the development needs of Australia\'s partner countries in line with bilateral and regional agreements.\r\n\r\nThe Scholarships provide opportunities for people from developing countries, particularly those countries located in the Indo-Pacific region, to undertake full time undergraduate or postgraduate study at participating Australian institutions. Since 1997, James Cook University has provided quality academic and personal support to over many hundreds of Australia Awards Scholarship students from more than 40 countries.\r\n\r\nAustralia Awards Scholarships are offered for the minimum period necessary for the individual to complete the academic program specified by the Australian higher education institution, including any preparatory training and generally cover tuition fees, air travel, and allowances to cover accommodation expenses, text books, study materials and basic living expenses.', 'Please contact James Cook University (JCU) for further information.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.jcu.edu.au/international-students/scholarships-and-financial-aid/australia-awards-scholarships', 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarships/51eb9820e1460f50a3e7fb9216c01fe0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00117J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Excellence Scholarship', 'The JCU International Excellence Scholarship provides a 25% tuition fee reduction throughout the entire duration of approved full degree study programs, provided recipients maintain a strong GPA each semester.\r\n\r\nScholarship eligibility is automatically assessed during the JCU admissions process. Eligible candidates will receive an offer for their program of study and the International Excellence Scholarship concurrently.', 'Please contact James Cook University (JCU) for further information.', '25% off tuition fee', 'Undergraduate / VET', NULL, 'https://www.jcu.edu.au/scholarships/search/international-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-excellence-scholarship/83ebdbdb6eb9cce0c94f63152a528998', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00117J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Robert Logan Memorial Grant', 'Established in 1975 from a bequest from the estate of the late Dr Robert Logan, Senior Lecturer in Biochemistry at the University from 1968 to 1973, the income derived from the bequest maintains the awards.', 'The Robert Logan Memorial Grant shall be open to candidates who:; are full time or part time Honours or postgraduate students in the discipline of Biochemistry at James Cook University and; have not previously received this grant during their current course of study.', 'AUD $14000/year — The value of the travelling and research grant will be determined by the Selection Committee (up to $14,000 annually). The grant will provide assistance to honours and post-graduate students in The Academy conducting research in the', 'Postgraduate', NULL, 'https://www.jcu.edu.au/scholarships/search/robert-logan-memorial-grant', 'https://search.studyaustralia.gov.au/scholarship/robert-logan-memorial-grant/844b85973c6fa96f213729c9cdf392e7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00117J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Robert Logan Memorial Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Tom and Dorothy Cook Scholarships in Public Health and Tropical Medicine', 'The original Cook family migrated from England to Australia in 1837. 75 years later Tom\'s father purchased land in Mackay and in 1915 built a family home, which is currently known as Greenmount Homestead. In 1950 Tom Cook wed Dorothy Drysdale, a successful businesswoman, owning and running a ladies\' fashion and beauty shop in Brisbane. Tom and Dorothy settled at the Mackay residence, where they lived for most of their 31-year marriage. The passing of Tom and Dorothy in 1981 and 1995 respectively ended eighty years of the Cook family residing at Greenmount.  In 1984, Dorothy gifted the homestead to the Mackay Regional Council. Dorothy left a final gift to the community of Mackay in the form of a research scholarship at James Cook University. These scholarships are offered to higher degree research students to undertake a Master of Philosophy or Doctor of Philosophy in the field of public health, laboratory and clinical investigation of population health in Tropical Northern Australia.', 'The Tom and Dorothy Cook scholarships in Public Health and Tropical Medicine will be open to competition among candidates who:; Are commencing, or in the process of applying for, a Master of Philosophy (MPhil) or Doctor of Philosophy (PhD) at JCU; Have a primary or secondary supervisor based in JCU’s Discipline of Public Health; Have a research project related to public health, laboratory and clinical investigations of population health; An significant element of the research project focusses on the Mackay and central Queensland region and; Meet JCU\'s admission requirements for MPhil or PhD degree.', 'Up to AUD $117250', 'Postgraduate', NULL, 'https://www.jcu.edu.au/scholarships/search/tom-and-dorothy-cook-scholarships-in-tropical-health', 'https://search.studyaustralia.gov.au/scholarship/tom-and-dorothy-cook-scholarships-in-public-health-and-tropical-medicine/800dbb48474d353f52ce17fac4fed414', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00117J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Tom and Dorothy Cook Scholarships in Public Health and Tropical Medicine') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ACTION Trust Scholarship', 'The ANU Fenner School of Environment and Society (FSES) within the ANU College of Systems and Society and the ANU Research School of Earth Sciences (RSES) within the ANU College of Science and Medicine may offer a number of awards known as the Action Trust Scholarship. The objective of the Award is to support students undertaking an honours project that advances knowledge and practice in areas relating to the interest of the ACTION Trust and/or to the environment and sustainability.', 'The scholarship is available to a commencing or continuing ANU student who:; is a domestic or international student;  receives an offer of admission or is currently enrolled in an eligible honours program at either the ANU Fenner School of Environment and Society or the ANU Research School of Earth Sciences; has an overall career GPA of 5.0 or higher.', 'AUD $5000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/action-trust-scholarship', 'https://search.studyaustralia.gov.au/scholarship/action-trust-scholarship/3285f99b1341f5385ca98a404d349d6a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ACTION Trust Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU College of Arts & Social Sciences Honours Scholarship', 'Each year the College of Arts and Social Sciences may offer up to 10 College of Arts and Social Sciences Honours Scholarship with the aim of recruiting high calibre students into the Colleges Honours programs.', 'The award is available each year to a prospective or current ANU student who is enrolled in a full-time Honours program offered by the College, or receives an offer of admission to a full-time Honours program offered by the College.', 'AUD $5000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-college-arts-social-sciences-honours-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anu-college-of-arts-social-sciences-honours-scholarship/d0ba227992e70b8f5278aa775c8dff86', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU College of Arts & Social Sciences Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU College of Arts and Social Sciences Academic Excellence Masters Scholarship', 'Each year the ANU College of Arts and Social Sciences (the College) may offer up to 10 awards known as the ANU College of Arts and Social Sciences Academic Excellence Masters Scholarship (the Award). The award is available to international students who have been offered admission to a Master or Master Advanced program by the College.\r\nThe objective of the Award is to support, enable and encourage international students to undertake studies in the arts, humanities or social sciences at the ANU College of Arts and Social Sciences. Funding for this Award has been provided by ANU College of Arts and Social Sciences.', 'is an international student; is a citizen of one of the countries published on the scholarships webpage (as updated annually); receives an offer of admission to a Master or Master Advanced program (excluding the Master of Studies/Master of Studies Advanced) at the ANU College of Arts and Social Sciences.', 'AUD $20000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-college-arts-and-social-sciences-academic-excellence-masters', 'https://search.studyaustralia.gov.au/scholarship/anu-college-of-arts-and-social-sciences-academic-excellence-masters-scholarship/cc8253befee5a5d578f8e289821a9e25', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU College of Arts and Social Sciences Academic Excellence Masters Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU College of Law International Partners Scholarship', 'Each year the ANU College of Law may offer a number of awards known as the ANU College of Law International Partners Scholarship with the aim of attracting and supporting top quality international postgraduate students to the ANU College of Law.', 'is an International student; has applied for admission to the Master of Laws (LLM) program at the ANU College of Law; has achieved a minimum GPA of 5.0 out of 7.0 (or equivalent) in their relevant undergraduate degree; has graduated from a law program or will have graduated by the time of taking up the scholarship from one of the following Universities:; Peking University - Beijing, China; University of Tokyo - Japan; has been shortlisted by one of the above Universities.', '100% fee waiver of tuition for one year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-college-law-international-partners-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anu-college-of-law-international-partners-scholarship/b9e2efdebcae612e80e6cd0ed8cbec07', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU College of Law International Partners Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU Fenner School of Environment & Society PhD Scholarship', 'Each year the ANU Fenner School of Environment and Society, in the ANU College of Science, may offer one or more awards known as the Fenner School of Environment & Society PhD Scholarship. The objective of the award is to attract the highest calibre international and domestic students to pursue postgraduate research for a PhD degree within the Fenner School. Funding for this award is provided by the Fenner School.', 'either a domestic or an international student; enrolling full-time in a program of study for the degree of Doctor of Philosophy, in the Fenner School of Environment & Society, at the Australian National University.', 'AUD $34000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-fenner-school-environment-society-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anu-fenner-school-of-environment-society-phd-scholarship/ecd8a275f8b45398de1391f4e5cad6c2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU Fenner School of Environment & Society PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU HDR Fee Merit Scholarship', 'Each year the Australian National University offers the ANU HDR Fee Merit Scholarship (concurrently with the ANU University Research Scholarship) to support high achieving international HDR students who are conducting research which aligns with the strategic directions of the University.', 'is an international student enrolling in an accredited HDR course of study at the University; has also been awarded an ANU University Research Scholarship; has achieved a minimum of Honours 1 (H1) or H1 equivalent in their prior studies.', 'Covers International Student Fees (ISF) and full OSHC, including family cover (for students on a Student Visa Subclass 500 only)', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-hdr-fee-merit-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anu-hdr-fee-merit-scholarship/053447c50cae21bc66c98ad58de8895c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU HDR Fee Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU HDR Supplementary Scholarship', 'A Supplementary scholarship may be awarded to a student to top up a HDR base stipend scholarship offered by the ANU to assist with living costs or research expenses.', 'Students enrolled in a research program who hold a base stipend scholarship.', 'Scholarship value : Variable', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-hdr-supplementary-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anu-hdr-supplementary-scholarship/1e864b6fb6c1562826d8bb5026e07447', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU HDR Supplementary Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU International Achievement Award', 'The Australian National University (ANU) (\'the University\') may offer a number of awards known as the ANU International Achievement Award (\'the Award\'). The objective of the Award is to attract a diverse range of academically capable overseas students to enrol in undergraduate and postgraduate coursework programs offered by the University.', 'The Award is available to an ANU student who:; is an international student; is a new commencing student or a continuing student who has received an offer of admission to a higher AQF level of studies; holds residential status in a country that is not listed as eligible for the ANU Vice-Chancellor’s International Achievement award as detailed on the ANU Scholarships website; meets the minimum academic entry requirements', '20%, 25% or 50% off tuition fees for up to 4 years.', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-international-achievement-award', 'https://search.studyaustralia.gov.au/scholarship/anu-international-achievement-award/51e736583aea338650fdb4b1eb765852', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU International Achievement Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU Law Careers and Employability Travel Grant', 'Each year the ANU College of Law, Governance and Policy may offer a number of awards known as the ANU Law Careers and Employability Travel Grant. The objective of the Award is to financially support College students when undertaking an ANU College of Law, Governance and Policy Careers and Employability program or initiative. Funding for this Award has been provided by the ANU College of Law, Governance and Policy.', 'The Award is available each year to a continuing ANU student who (at the time of application):; is a domestic or international student; Bachelor of Laws (Honours) as a single or Flexible Double Degree (FDD Law); Juris Doctor; Master of Laws; Master of International Law and Diplomacy; Master of Financial Management and Law; etc', 'AUD $4000/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-law-careers-and-employability-travel-grant', 'https://search.studyaustralia.gov.au/scholarship/anu-law-careers-and-employability-travel-grant/6a4a8c1b4b46028f438b15247b39e2c1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU Law Careers and Employability Travel Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU Master of Philosophy Scholarship', 'This is a stipend scholarship offered by ANU Colleges to Master of Philosophy (MPhil) candidates. It is normal for recipients to undertake study on a full-time basis, however, in accordance with strict criteria, the scholarship can be awarded for part-time study for Domestic candidates only. International scholars must undertake study on a full-time basis.', 'are domestic or international students; have applied for admission to a Master of Philosophy (MPhil) program; have a Bachelor degree with first-class honours (some Colleges may consider students with upper second-class honours), or a Master degree with a research component or equivalent from a recognised university.', 'AUD $36652/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-master-philosophy-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anu-master-of-philosophy-scholarship/e4fc01949c99bab880329f88f25234b2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU Master of Philosophy Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU PhD Scholarship', 'This is a stipend scholarship offered by ANU Colleges to Higher Degree by Research candidates. It is normal for recipients to undertake study on a full-time basis, however, in accordance with strict criteria, the scholarship can be awarded for part-time study for Domestic candidates only. International scholars must undertake study on a full-time basis.', 'are domestic or international students; have applied for admission to a PhD or Professional Doctorate by Research program; have a Bachelor degree with first-class honours (some Colleges may consider students with upper second-class honours), or a Master degree with a research component or equivalent from a recognized university.', 'AUD $36652/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anu-phd-scholarship/ed903fe76353475031888e5a213ebaec', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU Project 89 PhD Scholarship', 'Project 89 is an initiative of the Vietnamese government which aims to build capacity and academic training for Vietnamese university lecturers and executives. Its implementation is supported by the Australian government.', 'Continuation based on academic performance', 'AUD $39069/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-project-89-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anu-project-89-phd-scholarship/b65034f01de8706474bf2c8773dfb11b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU Project 89 PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU Vice-Chancellor\'s International Achievement Award', 'The Australian National University (ANU) (\'the University\') may offer a number of awards known as the ANU Vice-Chancellor\'s International Achievement Award (\'the Award\').\r\nThe objective of the Award is to attract a diverse range of academically capable overseas students to enrol in undergraduate and postgraduate coursework programs offered by the University.  Funding for this Award is provided by the Australian National University.', 'The Award is available to an ANU student who:; is an international student; is a new commencing student or a continuing student who has received an offer of admission to a higher AQF level of studies; holds residential status in one of the following Countries or Regions:; China (including Taiwan, Hong Kong SAR and Macau SAR); Japan; Mongolia; The Democratic People\'s Republic of Korea', '20% off your first-year tuition fees.', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-vice-chancellors-international-achievement-award', 'https://search.studyaustralia.gov.au/scholarship/anu-vice-chancellors-international-achievement-award/d95e76f144fad05183a8ebfb888d502e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU Vice-Chancellor\'s International Achievement Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'ANU-CSC Scholarship', 'The China Scholarship Council (CSC) is a non-profit institution affiliated with the People\'s Republic of China (PRC) Ministry of Education. CSC is responsible for the organization, management and provision of financial resources for Chinese citizens studying abroad, and to international students studying in China. CSC and ANU have established the China Scholarship Council - Australian National University Joint Funding Program to provide research opportunities to high quality research students and scholars from the PRC.\r\nThrough this program, selected PRC students may be offered an ANU-CSC Postgraduate (PhD) Scholarship for a maximum of 48 months. Visiting scholars, postdoctoral fellows and PhD students from the PRC may also be provided funding to conduct research at ANU for a maximum of one or two years.', 'Be a citizen and permanent resident of the PRC at the time of application; Meet all ANU admissions entry requirements including the English proficiency requirement, and receive either an unconditional offer of a place in an ANU PhD program, or an offer conditional on completion of their current program; Be selected by their ANU College or Research School for an HDR Fee Remission Merit Scholarship; Be eligible to receive an Australian student visa; Return to China at the end of the period of study; Satisfy other selection criteria set out by the China Scholarship Council.', 'Full tuition and stipend', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anu-csc-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anu-csc-scholarship/0885c2b0c69f709a1f6a33c44eedfc9d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ANU-CSC Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alan and Helen Ross Forestry Education Scholarship', 'The Fenner School of Environment & Society may offer an award known as the Alan and Helen Ross Forestry Education Scholarship. The objective of the Award is to support a Papua New Guinea (PNG) citizen with interests and experience in PNG forests and forestry to study a graduate coursework program in forests. Funding for this Award has been provided by the Alan and Helen Ross Forestry Education Scholarship Trust. The Trust honours the life and work of Alan and Helen Ross, longtime residents of PNG who were deeply committed to its future. Alan was a highly respected figure in forestry in PNG, mentoring many of his PNG colleagues.', 'The Award is available  to a commencing ANU student who:; is an international student visa holder with PNG citizenship; holds an undergraduate qualification in forestry or a related discipline; or, in exceptional cases, does not hold such a qualification but possesses equivalent extensive professional experience in forestry; receives an offer of admission to one of the following programs: Master of Forests; Graduate Diploma in Science; Graduate Certificate in Forests', 'Up to AUD $100000', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/alan-and-helen-ross-forestry-education-scholarship', 'https://search.studyaustralia.gov.au/scholarship/alan-and-helen-ross-forestry-education-scholarship/f592658ec411c575e38945d8cd1be42e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alan and Helen Ross Forestry Education Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alex Rodgers Travel Grant', 'Each year the Research School of Astronomy & Astrophysics (RSAA) may offer approximately two awards known as the Alex Rodgers Travel Grant (the Award). Funding for this Award has been made possible due to an endowment from Mrs Ruth Rodgers in memory of her late husband Professor Alexander Rodgers. Professor Rodgers was a distinguished academic in the field of stellar astronomy and globular clusters, serving as School Director from 1987 to 1992. Professor Rodgers most significant contribution to the field was his involvement in the MACHO project, an international search for dark matter. The objective of the Award is to assist a student currently enrolled in the Doctor of Philosophy in Astronomy & Astrophysics to travel abroad to attend scientific meetings and/or to work with astronomers at another institution on some chosen research project of direct relevance to the thesis work being undertaken.', 'Full-time current RSAA PhD student. A successful applicant is ineligible to apply again. Australian and New Zealand citizens; Permanent residents of Australia; International students.', 'Up to AUD $5000', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/alex-rodgers-travel-grant', 'https://search.studyaustralia.gov.au/scholarship/alex-rodgers-travel-grant/898d36dc5370faa5992925510361d621', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alex Rodgers Travel Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alexander McTaggart Honours Scholarship', 'Each year, the John Curtin School of Medical Research (JCSMR) within the ANU College of Science and Medicine at the Australian National University (ANU) may offer an award known as the Alexander McTaggart Memorial Scholarship.  The objective of the Award is to support a student undertaking their Honours project at the John Curtin School of Medical Research, with the research to be conducted in a field related to cancer research and allied subjects.  Funding for this Award has been provided in the memory of its donor, Mr Alexander McTaggart.', 'The scholarship is available to an applicant:; who is an international or domestic student; who is enrolled in an Honours year at the John Curtin School of Medical Research; whose Honours project is related to cancer research and allied fields.', 'AUD $10000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/alexander-mctaggart-honours-scholarship', 'https://search.studyaustralia.gov.au/scholarship/alexander-mctaggart-honours-scholarship/eb3ec6dd7146767e1aa264422a47197e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alexander McTaggart Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'American Australian Association Veterans\' Fund', 'The American Australian Association (AAA) established its Veterans\' Fund in 2017 to provide much needed financial support and assistance to Australian and American honorably discharged post-9/11 military veterans to pursue study in each other\'s countries respectively. With more than 40 veteran scholars and alumni and US $1.5 million awarded to date, the AAA is committed to investing in the future of veterans by supporting educational opportunities which build new skills and create prosperous post-military careers.', 'Please Contact ANU for more information about Eligibility.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/american-australian-association-veterans-fund', 'https://search.studyaustralia.gov.au/scholarship/american-australian-association-veterans-fund/c897a3af92900b6813763df86b1034d4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'American Australian Association Veterans\' Fund') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Anjeli Nathan Memorial Scholarship', 'This Scholarship is offered by the ANU College of Science and commemorates the life of Anjeli Nathan, a brilliant student who, tragically, was killed doing the field research she loved. The scholarship may be used to assist the student either to undertake the Honours Program or to gain fieldwork experience after the successful completion of the degree with Honours.', 'an outstanding applicant who has been accepted to study behavioural ecology or conservation biology for an Honours Program within The Australian National University; an outstanding applicant who is within 12 months, as at the closing date, of having completed the degree of Bachelor of Science with Honours at The Australian National University.; Projects involving long-term captivity, killing or surgery on animals will not be considered.; Preference will be given to applicants based or co-supervised in the Division of Ecology, Evolution and Genetics during their Honours year.', 'AUD $7000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/anjeli-nathan-memorial-scholarship', 'https://search.studyaustralia.gov.au/scholarship/anjeli-nathan-memorial-scholarship/bcbba1e6e9a917747a872c91c41ae86f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Anjeli Nathan Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australian Government Research Training Program (RTP) Stipend Scholarship', 'Each year the Commonwealth Department of Education and Training provides funding to Universities to award scholarships to domestic and international students undertaking Higher Degree Research programs. ANU currently conducts two annual central scholarship rounds which includes the RTP, the University Research Scholarship and a few other centrally managed scholarships.', 'Continuation based on academic performance', 'AUD $40475/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/australian-government-research-training-program-rtp-stipend', 'https://search.studyaustralia.gov.au/scholarship/australian-government-research-training-program-rtp-stipend-scholarship/359f56e62eeff08e6f57c9bb302c1a27', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian Government Research Training Program (RTP) Stipend Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Baume HDR Travel Grant', 'This award is available to a HDR student studying at the National Centre for Epidemiology and Population Health (NCEPH) to assist with travel to a national or international conference, in pursuit of their academic goals.', 'The Award will be available each year to a continuing domestic or international HDR student who is enrolled in a program of study at NCEPH for the degree of Doctor of Philosophy or Master of Philosophy. Students who have previously received the award are not eligible to apply again, except in exceptional circumstances.', 'AUD $1500/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/baume-hdr-travel-grant', 'https://search.studyaustralia.gov.au/scholarship/baume-hdr-travel-grant/9e5a20986b5edbbc09823f5f52777e55', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Baume HDR Travel Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ben Williams Student Support Grant', 'This Grant is offered by the Research School of Physics in the ANU College of Science. The Grant will aid students who are experiencing special difficulties and require financial assistance to continue and/or to complete their studies.', 'is an international or domestic student; is experiencing special difficulties and require financial assistance to continue and/or to complete their studies. Such cases as, but not exclusively related to, mental illness, disability, extended sickness or family issues are examples of those that may qualify for assistance; is enrolled in either an undergraduate or postgraduate program offered by the Research School of Physics, such as Honours program in Physics, Bachelor of Philosophy (majoring in Physics), Bachelor of Science (majoring in Physics), Master of Nuclear Science, Master of Photonics, Master of Philosophy (specialising in Physics) and Doctor of Philosophy (specialising in Physics).', '$14,000 per annum which maybe shared among multiple recipients', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/ben-williams-student-support-grant', 'https://search.studyaustralia.gov.au/scholarship/ben-williams-student-support-grant/9e794529879ddc33e57b1b2be91100a1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ben Williams Student Support Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bhati Family India Travel Grant', 'This annual grant is offered by the College of Asia and the Pacific but open to students of all Colleges at the Australian National University. It is funded in perpetuity by the Bhati Family Endowment to foster regional interconnectedness and encourage talented students to build mutually beneficial relationships between Australia and India. The grant will assist current ANU students from any discipline who need to travel to India for their research. The aim of the grant is to help create a better understanding and knowledge of Australia in India and/or a better understanding and knowledge of India in Australia.', 'The recipient must be enrolled and remain enrolled at ANU while the travel is being undertaken; Travel to India is vital for research and output of research will contribute to the aim of the grant.; The applicant has obtained approval of his/ her supervisor and has established a link with an institution in India.; For details on these and additional selection criteria, see section 5 of the Conditions of Award (see reference document). https://d3gu8jtw4r0om.cloudfront.net/files/2024-03/Bhati%20Family%20India%20Travel%20Grant%20-%20Revised%20CoA%20for%202018%20-%20Final.pdf', 'AUD $3500/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/bhati-family-india-travel-grant', 'https://search.studyaustralia.gov.au/scholarship/bhati-family-india-travel-grant/7b5ccd5e8d3d40a32f4e8d1a7ce972d9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bhati Family India Travel Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bok Honours Year Scholarship in Astrophysics', 'Each year, the Research School of Astronomy and Astrophysics (RSAA) in the ANU College of Science may offer an award known as the Bok Honours Year Scholarship in Astrophysics. The objective of the award is to support students with an outstanding academic record to undertake their Honours year in Astronomy and Astrophysics with the Research School of Astronomy and Astrophysics in the ANU College of Science. The Scholarship is offered in honour of the late Professor Bart J. Bok, a former Director of the Mount Stromlo and Siding Spring Observatories from 1957 to 1966 and Professor of Astronomy at the Australian National University.', 'is a domestic or international student; is enrolled/enrolling in the Astronomy and Astrophysics Honours Year within the Research School of Astronomy and Astrophysics in the ANU College of Science.', 'AUD $5000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/bok-honours-year-scholarship-astrophysics', 'https://search.studyaustralia.gov.au/scholarship/bok-honours-year-scholarship-in-astrophysics/e03aa27ed12a34c8e48c175508efeeb3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bok Honours Year Scholarship in Astrophysics') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Brynrefail Honours Grant for Classical Studies', 'Each year, the School of Literature, Languages and Linguistics, ANU College of Arts and Social Sciences (\'the School\') may offer an award/s known as the Brynrefail Honours Grant for Classical Studies (\'the Award\'). The objective of the Award is to support Honours students in Classical Studies, including the study of Ancient Greek and Latin, and to inspire them to undertake additional research and study in this field. Funding for this Award has been provided by the Lord Mayor\'s Charitable Foundation, one of Australia\'s leading philanthropic organisations.', 'The Award is available each year to a commencing or continuing ANU student who:; is a domestic or international student; receives an offer of admission to an Honours program in the field of Classical Studies at the College of Arts and Social Sciences.', 'AUD $3000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/brynrefail-honours-grant-classical-studies', 'https://search.studyaustralia.gov.au/scholarship/brynrefail-honours-grant-for-classical-studies/71f2d1440cd73d4d1a806922bce7842d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Brynrefail Honours Grant for Classical Studies') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Centre for Critical Resources for the Future (CCRF)', 'The Centre in Critical Resources for the Future (CCRF) are offering TWO PhD scholarships in partnership with the Australian National University (ANU). These opportunities are ideal for highly motivated graduates interested in: Partitioning of REE and CM between crystals melts, and fluids and in situ XAS studies of metal transport. (led by Andrew Berry); Experimental investigations of the magmatic-hydrothermal transition in carbonatites and the factors controlling REE and CM enrichment. (Led by Prof Greg Yaxley)', 'Have applied for admission to the PhD program with the Research School of Earth Science; Have a Bachelor degree with first-class honours, or a Master degree with a research component, or equivalent from a recognised University.', 'AUD $36652/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/centre-critical-resources-future-ccrf', 'https://search.studyaustralia.gov.au/scholarship/centre-for-critical-resources-for-the-future-ccrf/2ec88c7099b3aa0e90bb63ab513b3eae', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Centre for Critical Resources for the Future (CCRF)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Centre of Excellence for the Weather of the 21st Century Research Grant', 'Each year, the Research School of Earth Sciences (RSES) within the College of Science and Medicine and Fenner School of Environment and Society (FSES) within the College of Systems and Society may offer a number of awards known as the Centre of Excellence for the Weather of the 21st Century Research Grant. The objective of the Award is to encourage students to undertake a research project in climate, weather, or related fields. Funding for this Award has been provided by ARC Centre of Excellence for the Weather of the 21st Century.', 'The Award is available each year to a commencing or continuing ANU student who:; is a domestic student or international student; receives an offer of admission to an Honours program offered by RSES/FSES; has a career GPA of 6 or higher.', 'AUD $7500/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/centre-excellence-weather-21st-century-research-grant', 'https://search.studyaustralia.gov.au/scholarship/centre-of-excellence-for-the-weather-of-the-21st-century-research-grant/15f7b2343bb62c1cb193c936cf280ce9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Centre of Excellence for the Weather of the 21st Century Research Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Chappell and White PhD Scholarship', 'Once every three years the Research School of Earth Sciences may offer a PhD scholarship known as the Chappell and White PhD Scholarship (the Award). The objective of the Award is to support high achieving domestic and international PhD students who are conducting research in the areas of petrology and ore petrology. Funding for this Award has been provided by Professor Bruce Chappell and Professor Allan White. Professor Bruce Chappells career at ANU spanned more than 30 years, from 1960 to 1997. In 1967 he graduated with an ANU PhD and was awarded an ANU DSC in 1990. His sustained research contributions were recognised with many international awards including election to Fellowship of the Australian Academy of Science. Professor Allan White was a member of the Geology Department at ANU from 1960 to 1971. He was an undergraduate student of the famous Australian geologist and Antarctic explorer, Professor Sir Douglas Mawson. White left ANU to establish the Department of Geology at La Trobe University.', 'a domestic and/or international student; enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy in Earth Sciences and are conducting research in the areas of petrology and ore petrology at the University; holds a Bachelor degree with first-class honours, or a Master degree with a research component or equivalent from a recognized university.', 'AUD $34000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/chappell-and-white-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/chappell-and-white-phd-scholarship/489462620ae9328c44267de6029f022c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Chappell and White PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Chris Heyde & Joe Gani Scholarship', 'Professor Chris Heyde and Professor Joe Gani were well known and well regarded amongst their colleagues for their substantial contribution to many areas of Probability, Statistics and Stochastic Analysis during their lifetime.  To honour their memory, the Chris Heyde & Joe Gani Scholarship has been established at the ANU to enable students to study and expand research into these fields. The Scholarships are funded by the interest on contributions from friends, colleagues, family and the ANU Endowment for Excellence.  Two Scholarships will be offered annually subject to funds beings available.', 'a domestic and/or international student; enrolled in a program of study leading to the award of a PhD; undertaking research in areas of probability, statistical science or stochastic analysis.', 'AUD $5000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/chris-heyde-joe-gani-scholarship', 'https://search.studyaustralia.gov.au/scholarship/chris-heyde-joe-gani-scholarship/c2d3df04317cc1c0a67b5d6efb4fe340', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Chris Heyde & Joe Gani Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Clark Davis Ivins Memorial Travel Grant', 'The Clark Davis Ivins Memorial Endowment in 2014 by the family of Private Clark Davis Ivins, an Australian soldier who died during World War II. He was just 24-years-old when he died of wounds received at the Battle of Milne Bay in Papua New Guinea in 1942.  His life may have been a short one, but the part he played in the Battle of Milne Bay, a battle that was the first Japanese defeat on land in the Pacific War, is one that certainly made a difference to the lives of many Australians, both young and old, today.  To commemorate the 75th Anniversary of the Battle of Milne Bay in 2017, the Endowment was expanded to offer the Clark Davis Ivins Memorial Travel Grant.', 'a domestic or international student; enrolled in a Bachelor of International Security Studies; participating in a Global Learning Program offered by the ANU', 'Variable once off payment. The value of the award is stated in your letter of offer. The award will be paid in a single instalment prior to the recipients travel departure, unless otherwise stated in the letter of offer.', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/clark-davis-ivins-memorial-travel-grant', 'https://search.studyaustralia.gov.au/scholarship/clark-davis-ivins-memorial-travel-grant/e60e8780cdddb68ad3b798b9033ad621', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Clark Davis Ivins Memorial Travel Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin PhD Scholarship', 'Funding for this Award has been provided by the John Anthony Deakin Endowment.', 'Domestic or International; Prospective or continuing; Enrolled or enrolling in a program of study for the degree of Doctor of Philosophy at the Australian National University; Has been awarded a Bachelor degree with first class honours, or a Master degree with a research component, or equivalent from a recognised University', 'AUD $36652/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/deakin-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/deakin-phd-scholarship/bb815be91fcdf32fa1b22717b810736b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Dean\'s International Science Excellence Scholarship', 'The Deans International Science Excellence Scholarship is jointly offered by ANU College of Science and ANU College of Health & Medicine. It is a prestigious scholarship awarded to the very best international students from the Colleges institutional partners.', 'an international student. Dependents of the staff of diplomatic or consular missions are also eligible; undertaking undergraduate or postgraduate studies at an institute which has an articulation agreement with the Colleges. Click here for the list of the Colleges articulation partners; enrolling at ANU for the first time in an undergraduate or postgraduate coursework program in the Colleges.', 'AUD $5000/year — Once-off payment for full value', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/deans-international-science-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/deans-international-science-excellence-scholarship/5cbc11b28fb63a93bfb68b5652ba03f7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Dean\'s International Science Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Dewar Milne Prize in Immunology', 'Each year the John Curtin School of Medical Research (JCSMR) in the ANU College of Health and Medicine may offer an award known as the Dewar Milne Prize in Immunology.\r\nFunding for this Award has been provided by John Dewar Milne, a graduate of the ANU. The objective of the prize is to acknowledge a high-achieving research candidate who has carried out the most significant piece of research during their doctoral candidature, whilst enrolled in a PhD program based in the College of Health and Medicine.', 'The Award is available each year to a person who was awarded the degree of Doctor of Philosophy in the previous year for research conducted at JCSMR in the field of immunology.', 'AUD $2000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/dewar-milne-prize-immunology', 'https://search.studyaustralia.gov.au/scholarship/dewar-milne-prize-in-immunology/c4a66aa41c8e4ec192c72cc3003398ab', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Dewar Milne Prize in Immunology') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Digital Agriculture PhD Scholarship', 'ANU-CSIRO Digital Agriculture PhD Scholarship provides funding to support outstanding candidates to pursue a PhD program at ANU, where the focus of their research is on a collaborative project between CSIRO and ANU in the field of information science relevant to agriculture. Funding for this award has been provided by CSIRO’s Data61 - Australia\' leading data innovation group. Their mission is to create Australia’s data driven future by building the world’s leading data-focused research and innovation powerhouse.', 'The Award will be available to a prospective domestic or international candidate who:; is enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy in the field of Information Science relevant to the Agriculture domain, based in the either the ANU College of Science and Medicine or the ANU College of Systems and Society; will be undertaking research for CSIRO / ANU projects under a Collaboration Agreement; has demonstrated First class honours (H1), or equivalence; have signed a Student Agreement with CSIRO, unless otherwise agreed in writing with CSIRO; must not be in full-time employment.', '$39,069 per annum and $15,000 per annum supplementary scholarship', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/digital-agriculture-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/digital-agriculture-phd-scholarship/a4be1ecbd4444d708482a192a31692ce', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Digital Agriculture PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Director’s Scholarships for Academic Excellence', 'Directors Scholarship for Academic Excellence is offered by ANU College of Science to the very best international students from the ANU - SDU Joint Science College (JSC) at Shandong University, Weihai, China. The scholarship rewards high quality, top-performing students from JSC who come to study at ANU.', 'is an International student; is currently enrolled in the ANU-SDU Joint Science College at Shandong University, Weihai; receives an offer of admission to a vertical double degree combination of undergraduate and postgraduate coursework programs offered by the ANU College of Science; has not received the Award previously.', 'AUD $7500/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/directors-scholarships-academic-excellence', 'https://search.studyaustralia.gov.au/scholarship/directors-scholarships-for-academic-excellence/97f902f83bc460e7ae2b34b992afb00d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Director’s Scholarships for Academic Excellence') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Doherty PhD Supplementary Scholarship', 'Each year the John Curtin School of Medical Research in the ANU College of Health and Medicine may offer an award known as the Doherty PhD Supplementary Scholarship with the aim to attract students of high calibre, with clinical qualifications, to pursue postgraduate studies at the JCSMR involving a clinical research project, in order to facilitate interaction between basic biomedical science and clinical research. The award was established in honour of Professor Peter Doherty, who shared the Nobel Prize for Physiology or Medicine with Professor Rolf Zinkernagel in 1996, for work done at JCSMR.', 'is awarded and continues to hold an Australian Government Research Training Program (AGRTP) Stipend Scholarship, or a similar living expenses PhD scholarship; is enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy at the John Curtin School of Medical Research; holds an Australian Bachelor Honours degree with First Class Honours or equivalent,and has research publications and/or relevant research experience.', 'AUD $10000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/doherty-phd-supplementary-scholarship', 'https://search.studyaustralia.gov.au/scholarship/doherty-phd-supplementary-scholarship/ee98e1be37edae439add32a51dfcc49b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Doherty PhD Supplementary Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Doherty Scholarship', 'This scholarship is offered by the John Curtin School of Medical Research (JCSMR). The Doherty Scholarship (Clinical) is to attract students of high calibre with clinical qualifications to pursue graduate research involving a clinical research project for a PhD degree at the JCSMR.', 'Students of high calibre with clinical qualifications. Preference given to Australian or New Zealand Citizens and Permanent Residents of Australia however International students will also be considered.', 'AUD $34000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/doherty-scholarship', 'https://search.studyaustralia.gov.au/scholarship/doherty-scholarship/e87c4a44ec17259f943e5832e66c2855', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Doherty Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Dr Matthew Valetich Honours Scholarship in Geoscience', 'Each year, the Research School of Earth Sciences within the ANU College of Science and Medicine may offer an award known as the Dr Matthew Valetich Honours Scholarship in Geoscience. The objective of the Award is to provide financial assistance to a student undertaking their honours year in geoscience.  Funding for this Award has been provided by Anglo American Exploration (Australia) Pty Limited in honour of Dr Matthew Valetich, a PhD graduate of the Research School of Earth Sciences.', 'The Award is available each year to a commencing or continuing ANU student who:; is a domestic or international student; receives an offer of admission to a Bachelor of Science (Honours), Bachelor of Philosophy (Honours), or Bachelor of Science (Advanced) (Honours) program within the ANU College of Science and Medicine; is enrolled in an Honours research project based in the Research School of Earth Sciences (RSES). Supervision by staff from other ANU research schools within the ANU College of Science and Medicine is permitted and encouraged; can demonstrate financial hardship that may impact their ability to commence, continue, or complete their studies.', 'AUD $9000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/dr-matthew-valetich-honours-scholarship-geoscience', 'https://search.studyaustralia.gov.au/scholarship/dr-matthew-valetich-honours-scholarship-in-geoscience/01c3c32524e8d98cbc52adfda59eb6d9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Dr Matthew Valetich Honours Scholarship in Geoscience') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ellison Scholarship', 'The Ellison Institute of Technology (EIT), funded by Larry Ellison, is committed to advancing technology to solve some of humanity’s most serious problems. They are now launching a unique scholarship programme to invite the global technology innovators and leaders of the future to join their mission. EIT will fully fund undergraduate or graduate study at the University of Oxford.', 'Please Contact ANU for more information about Eligibility', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/ellison-scholarship', 'https://search.studyaustralia.gov.au/scholarship/ellison-scholarship/754de292244a46424e5d8cea1f7a8d9c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ellison Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Emergency Accommodation Bursary', 'The Emergency Accommodation Bursary is designed to assist students who are currently enrolled at the ANU as an award-status student, and are experiencing unexpected financial difficulty in meeting their accommodation costs. Assistance is not ongoing and the bursary is not designed for pre-arrival costs or as a method of income. Funds are granted subject to eligibility. Applications are assessed and awarded at the discretion of the Bursary Review Committee. The Committee will determine the amount of any bursary granted from an assessment of the students need and the availability of funds. The Emergency Accommodation Bursary can provide up to 52 weeks of financial support over the course of your current level of study at the ANU. If living on campus, bursary funds will be paid directly to a student\'s residential account.', 'is a domestic or international student; is enrolled in an undergraduate, honours or postgraduate degree offered by the University; is enrolled in at least one course (if a coursework student) or at least 24 units (if a higher degree research student) during the period; has not received the Award for 52 weeks during their current level of study; if residing in an on-campus residence, does not have any serious breaches of their Occupancy Agreement recorded; can demonstrate a change in personal circumstances that has affected their ability to meet financial obligations; can demonstrate financial hardship.', 'Scholarship Value : Variable', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/emergency-accommodation-bursary', 'https://search.studyaustralia.gov.au/scholarship/emergency-accommodation-bursary/f291a1d1225791c1ff7218bc9b953a5a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Emergency Accommodation Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Florence McKenzie Chair', 'Each year the School of Cybernetics in the ANU College of Engineering and Computer Science (College) may offer up to 10 awards known as the FMK Supplementary Scholarship (Award). Funding for this Award has been provided by the Florence Violet McKenzie Chair. The Australian National University (ANU) College of Engineering and Computer Science is embarking on an ambitious agenda to reimagine engineering and computing to launch our society into the middle of the 21st Century. We are bringing non-traditional skills to engineering and computing to put people in the centre of delivering solutions to global challenges.', 'Have received a statement of support from the SOCY cohort PhD program convenor; are enrolled full-time in the cohort program of study for the degree of Doctor of Philosophy at SOCY at the ANU; have been awarded, and continue to hold, an ANU approved PhD base stipend scholarship; have agreed to assign the ownership of any Student Material (as defined in the Student Assignment and Confidentiality Deed (Deed)) including any Intellectual Property embodied in the Student Material to the University, in accordance with the terms of the Deed between the recipient and the University. The recipient is encouraged to seek independent advice before signing the Deed and accepting this Award, for example via the ANU Postgraduate & Research Students\' Association (PARSA).', 'AUD $20908/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/florence-mckenzie-chair', 'https://search.studyaustralia.gov.au/scholarship/florence-mckenzie-chair/1c273c9c470780d035057b0755a1f6c3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Florence McKenzie Chair') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Future Crops Centre Scholarship', 'The ARC Training Centre for Future Crops is working directly with industry and the community to train the next generation of research and industry leaders to deliver impactful projects with real-world implications for food security. Students in plant science and communication in science will have opportunities to engage with industry partners and communities on projects to improve the yield and nutritional value of the crops that underpin the energy and protein content of the human diet. Together, the Centre will build future R&D capabilities in the Agrifood sector to drive growth, productivity and competitiveness for the benefit of agriculture and global food security. These scholarships will enable students to pursue a PhD program conducting research that is either a core project within the Centre, or closely aligns with the strategic directions of the Centre, based in the College of Science.', 'is enrolling full-time in a program of study for the degree of Doctor of Philosophy, based in the ANU College of Science; has been awarded a first-class honours or equivalent; is undertaking one of the core Centre PhD research projects, or a project approved by the Centre Executive.', 'AUD $34938/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/future-crops-centre-scholarship', 'https://search.studyaustralia.gov.au/scholarship/future-crops-centre-scholarship/7b7331b3755082e4fe412af87cadc11b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Future Crops Centre Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Geoff Mercer Award', 'An Award has been established and named in honour of Dr. Geoff Mercer, a highly regarded Professor at the National Centre of Epidemiology and Population Health (NCEPH) in the Research School of Population Health (RSPH), who passed away suddenly in April 2014 at the peak of his career. This Award will continue Geoff\'s legacy of mentoring and support of students, by funding a grant for postgraduate RSPH students to undertake an activity in pursuit of their academic goals, including travel to a national or international conference. Given Geoffs commitment to applying mathematics to population health, especially infectious disease problems, students undertaking research in that area are particularly encouraged to apply.', 'The Award shall be awarded each year to the student who, enrolled in the Research School of Population Health, has completed an application for funding support that is judged by the Selection Committee to be the most likely to enhance the pursuit of the applicant\'s academic goals.', 'See scholarship details', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/geoff-mercer-award', 'https://search.studyaustralia.gov.au/scholarship/geoff-mercer-award/45c9cc8577527edeb508a5a3d483522d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Geoff Mercer Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Global Power Generation Australia Scholarship in The Hydrogen Economy', 'The purpose of this scholarship is to support students enrolled in the Master of Energy Change (Advanced) program and undertaking a research project in the field of the hydrogen economy.', 'Applicants must be enrolled in: the Master of Energy Change (Advanced) program or the Master of Energy Change program and eligible for transfer to the Master of Energy Change (Advanced ); Applicants must have a suitable supervisor and meet conditions for enrolling into  SCNC8021 Science Research Project (24 units over 2 semesters).; The research project approved by the supervisor must be in the field of the Hydrogen Economy; Applicants must have achieved at least 70% average in the coursework component of the program.', 'AUD $10000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/global-power-generation-australia-scholarship-hydrogen-economy', 'https://search.studyaustralia.gov.au/scholarship/global-power-generation-australia-scholarship-in-the-hydrogen-economy/520a7ccb4b4327b5f51b820f35fe77a1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Global Power Generation Australia Scholarship in The Hydrogen Economy') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Grace Groom Memorial Scholarship', 'The Grace Groom Memorial Scholarship has been established from a donation by the Mental Health Australia Ltd in memory of Grace Groom. The purpose of the Scholarship is to provide financial support to international or domestic postgraduate students enrolled in study and research relating to mental health issues. Applicants may be enrolled in any research program within the ANU College of Health and Medicine (CHM). Their research program should have meaningful and real application to the daily lives of people with a mental illness and/or the people who care for them.', 'be enrolled in a graduate research program offered within the ANU College of Health and Medicine; be already undertaking study in a mental health related field.', 'See scholarship details', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/grace-groom-memorial-scholarship', 'https://search.studyaustralia.gov.au/scholarship/grace-groom-memorial-scholarship/30f95576c8bf69516517751b5dc2929c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Grace Groom Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'HDR Fee Remission Merit Scholarship', 'ANU Colleges may offer Fee Remission Merit Scholarships to eligible International students.', 'be enrolled in a postgraduate research program; be an International student; have been ranked as part of a competitive scholarship process for another ANU or external scholarship.', 'Full tuition', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/hdr-fee-remission-merit-scholarship', 'https://search.studyaustralia.gov.au/scholarship/hdr-fee-remission-merit-scholarship/f0214097422bc5e1d692d4da343129d5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'HDR Fee Remission Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Helen Winslade Honours Scholarship in Cancer Research', 'Each year, the Division of Genome Sciences and Cancer at the John Curtin School of Medical Research (JCSMR) within the ANU College of Science and Medicine may offer an award known as the Helen Winslade Honours Scholarship in Cancer Research.  The objective of the Award is to support high-achieving students undertaking the Honours Year of their undergraduate degree, who are conducting research projects focused on cancer.  Funding for this Award has been provided by Mr Michael Winslade and family in memory of Mrs Helen C. Winslade, an ANU alumna.', 'The scholarship is available to an applicant:; who is an International or domestic student; who is enrolled in an Honours year at the John Curtin School of Medical Research; whose Honours project is related to cancer research.; whose primary supervisor is a member of the Division of Genome Sciences and Cancer.', 'AUD $10000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/helen-winslade-honours-scholarship-cancer-research', 'https://search.studyaustralia.gov.au/scholarship/helen-winslade-honours-scholarship-in-cancer-research/66d39a5a144553e22d1b62f30852689d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Helen Winslade Honours Scholarship in Cancer Research') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ian McDougall Honours Scholarship', 'The Research School of Earth Sciences (RSES) within the ANU College of Science and Medicine may offer a number of awards known as the Ian McDougall Honours Scholarship. The objective of the Award is to support an Honours student in Geochronology in the RSES. Funding for this Award is provided by Professor Ian McDougall, who has been described as "one of Australia\'s most internationally distinguished earth scientists" and was awarded the Centenary Medal in 2001.', 'The Award is available to a commencing or continuing ANU student who:; is a domestic or international student; receives an offer of admission to an Honours program offered by the Research School of Earth Sciences within the ANU College of Science and Medicine; is undertaking a research project in the field of geochronology.', 'AUD $8000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/ian-mcdougall-honours-scholarship', 'https://search.studyaustralia.gov.au/scholarship/ian-mcdougall-honours-scholarship/74db721cd70dff7587020da648f6284d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ian McDougall Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'JCSMR Gender Equity Fund', 'Each year the John Curtin School of Medical Research (the JCSMR) in the ANU College of Health & Medicine may offer funding of up to $10,000 from the JCSMR Gender Equity Fund. Funding has been provided by a generous initial donation by Professor Carola Vinuesa and continues with the support of Richard Miller and the School, as funding permits. The objective of this Fund is to provide funding for an early or mid-career researcher or domestic or international PhD student who is experiencing significant career disruption resulting from the birth of a child, or the primary care of a child, which limits or prevents their career progression and research activities in the John Curtin School of Medical Research.', 'a female-identifying researcher at the JCSMR who holds a current academic appointment at level A-C and intends to return to a career in research; a continuing domestic or international female-identifying student who is enrolled in a program of study for the degree of Doctor of Philosophy, based in the John Curtin School of Medical Research (the JCSMR) and, in relation to the birth or care of a child,; is experiencing a period of significant career disruption (generally at least 12 weeks) or expects to do so within the next 6 months; within the last 12 months, has applied for or returned from a period of career disruption (generally at least 12 weeks).', 'AUD $10000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/jcsmr-gender-equity-fund', 'https://search.studyaustralia.gov.au/scholarship/jcsmr-gender-equity-fund/73f35e5e333e36767b40b86ede2c2f49', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'JCSMR Gender Equity Fund') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Jamie Mackie Southeast Asia Travel Grant', 'Each year the ANU College of Asia and the Pacific (the College) may offer an award known as the Jamie Mackie Southeast Asia Travel Grant (the Award). The objective of the Award is to assist students to undertake research or study where they will benefit from travel to Southeast Asia. The aim of the Award is to promote Australias engagement with Southeast Asia and/or Southeast Asias engagement with Australia. Funding for this Award has been provided by friends, family and colleagues in memory of the late Emeritus Professor Jamie Mackie, scholar, mentor, advocate and pioneer in our collective understanding of Indonesia and Southeast Asia. The endowment promotes Jamies lifelong passions: Indonesia and Southeast Asia, Australias engagement in our region and racial respect and tolerance.', 'is a domestic or international student; is undertaking an undergraduate or postgraduate coursework program at the College; is enrolled in a mobility course at the College; is intending to travel to Southeast Asia for the purpose of furthering their understanding of the region; can demonstrate that their travel will contribute to a better understanding and knowledge of any aspect of Australia in Southeast Asia, or any aspect of Southeast Asia in Australia.', 'Up to AUD $5000', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/jamie-mackie-southeast-asia-travel-grant', 'https://search.studyaustralia.gov.au/scholarship/jamie-mackie-southeast-asia-travel-grant/e7640ebf69ecfb92699418e228d9f3a2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Jamie Mackie Southeast Asia Travel Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Jan Anderson ANU-NTU HDR Supplementary Scholarship', 'Each year the Research School of Biology may offer an award known as the Research School of Biology Jan Anderson ANU-NTU HDR Supplementary Scholarship.  The award is to provide financial support for students currently enrolled in a RSB HDR program and travelling to Nanyang Technical University (NTU, Singapore) to undertake the joint research and help them develop their scientific and professional skills.', 'a domestic or international student; enrolled or enrolling full-time in a Doctor of Philosophy study program within the RSB; Undertaking a research project that suitably demonstrates collaboration with one or more researchers at Nanyang Technological University (NTU); has been awarded, and has accepted, an ANU HDR base stipend scholarship.', 'AUD $7000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/jan-anderson-anu-ntu-hdr-supplementary-scholarship', 'https://search.studyaustralia.gov.au/scholarship/jan-anderson-anu-ntu-hdr-supplementary-scholarship/84edc611068f4248b107f467b1c6dbfb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Jan Anderson ANU-NTU HDR Supplementary Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Jason Passioura Bursary', 'The Jason Passioura Bursary honours its namesake who passed away in 2022 after battling Glioblastoma Multiforme (GBM) brain cancer for 16 months. Jason was a valued member of the NCEPH community who showed enthusiasm for his work and demonstrated exceptional commitment to data accuracy and ensuring that evidence-based research was undertaken with a focus on improving the quality of source data. This Bursary recognises Jasons outstanding contribution to research, in particular Jasons achievements in using spatial analysis to inform suicide prevention research; work carried out at the NCEPH as a collaboration between GRAPHC (the National Centre for Geographic Resources & Analysis in Primary Health Care) and the Black Dog Institute. Funding for this Award has been provided by NCEPH. The Jason Passioura Bursary will continue Jasons legacy, by each year funding one or more students or researchers (academic Level A or B or professional staff) to undertake activity in pursuit of their research goals. The Bursary is intended to support the use of high-quality data in research. Given Jasons commitment to spatial analyses especially regarding suicide prevention, applications that relate to these areas will be considered favourably.', 'The Award is available each year to a continuing domestic or international ANU student (honours, postgraduate or HDR) who is enrolled in a program of study at NCEPH; and/or an ECR (Level A or B); and/or a professional staff member with suitable experience working at NCEPH.', 'AUD $1500/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/jason-passioura-bursary', 'https://search.studyaustralia.gov.au/scholarship/jason-passioura-bursary/183ad9e04a0c970f86e8efcb8f6b9b33', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Jason Passioura Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Joyce Fildes Honours Scholarship in Medical Science', 'Each year, the John Curtin School of Medical Research (JCSMR) within the ANU College of Science and Medicine may offer a number of awards known as the Joyce Fildes Honours Scholarship in Medical Science.  The objective of the Award is to support students undertaking their Honours project, with research conducted in any area of medical science.  Funding for this Award has been provided in memory of its donor, Dr Joyce Fildes, a former staff member of the John Curtin School of Medical Research.', 'The scholarship is available to an applicant:; who is an International or domestic student; who is enrolled in an Honours year at the John Curtin School of Medical Research; whose Honours project is in any field of biomedical research conducted at the John Curtin School of Medical Research.', 'AUD $10000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/joyce-fildes-honours-scholarship-medical-science', 'https://search.studyaustralia.gov.au/scholarship/joyce-fildes-honours-scholarship-in-medical-science/a48294b7daa61f5da93cbb6bd087189b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Joyce Fildes Honours Scholarship in Medical Science') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Kloeden Foundation Forestry Grant', 'The Kloeden Foundation Forestry Grant supports undergraduate and postgraduate domestic and international students with a bona fide interest in developing a career in forestry and plantation management.', 'is a domestic or international student; has completed a minimum of 72 units of studies in their undergraduate program; is a commencing or continuing postgraduate student; is enrolled/enrolling in one of the following programs:; Bachelor of Environment of Sustainability or Bachelor of Environment of Sustainability (Advanced) (Honours); Bachelor of Science or Bachelor of Science (Advanced) (Honours); Master of Forestry or Master of Forestry (Advanced); Master of Environment or Master of Environment (Advanced)', 'AUD $5000/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/kloeden-foundation-forestry-grant', 'https://search.studyaustralia.gov.au/scholarship/kloeden-foundation-forestry-grant/e2007f74b82dc48c30e3a044bff6f84c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Kloeden Foundation Forestry Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Korten Prize', 'Each year the Centre for Mental Health Research (CMHR) of the National Centre for Epidemiology and Population Health (NCEPH) in the ANU College of Health and Medicine may offer an award known as the Korten Prize. Funding for this Award has been provided by the Centre for Mental Health Research in memory of Mrs Ailsa Korten who worked as a research officer in CMHR between 1986 and 2005. Ailsa Korten published over 120 research papers during this period. The objective of the prize is to acknowledge a high-achieving research candidate who has written the best research paper in the year of the award, whilst enrolled in a PhD program based in the College of Health and Medicine.', 'is enrolled in a program of study for the degree of Doctor of Philosophy in the field of Mental Health Research, with their Primary Supervisor based in the National Centre for Epidemiology and Population Health (NCEPH) of the ANU College of Health and Medicine (CHM); has published, or had a paper accepted for publication in the year of the award.', 'AUD $1000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/korten-prize', 'https://search.studyaustralia.gov.au/scholarship/korten-prize/9901b48ab065b6c4b958f7f21c199f32', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Korten Prize') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Leonard and Margaret Doman Undergraduate Scholarship for Flute', 'This scholarship is offered by the ANU College of Arts and Social Sciences.', 'Selection is made on the basis of applicants meeting the eligibility criteria. Other factors, such as interview at time of audition, may be taken into consideration.', 'AUD $5000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/leonard-margaret-doman-undergraduate-scholarship-flute', 'https://search.studyaustralia.gov.au/scholarship/leonard-and-margaret-doman-undergraduate-scholarship-for-flute/2cca2838097ee5f8add0f395d184b5f0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Leonard and Margaret Doman Undergraduate Scholarship for Flute') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Master of Science (Advanced) in Astronomy and Astrophysics Scholarship', 'Each year the Research School of Astronomy and Astrophysics (the School) may offer an award known as the Master of Science (Advanced) in Astronomy and Astrophysics Scholarship (the award). The objective of the award is to support an outstanding domestic or international student to enable them to pursue the Master of Science (Advanced) in Astronomy and Astrophysics, offered by the Research School of Astronomy and Astrophysics in the ANU College of Science. Funding for this award has been provided by the Research School of Astronomy and Astrophysics.', 'is a domestic or international student; is currently enrolled in the Master of Science (Advanced) in Astronomy and Astrophysics; has completed at least 48 units of the Master of Science (Advanced) in Astronomy and Astrophysics degree program with a minimum Weighted Average Mark (WAM) of 80%; is not receiving Commonwealth support for this degree program.', 'Up to AUD $20000', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/master-science-advanced-astronomy-and-astrophysics-scholarship', 'https://search.studyaustralia.gov.au/scholarship/master-of-science-advanced-in-astronomy-and-astrophysics-scholarship/7de8e3bd0e4eef9ee2714dbfb1c2a0c2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Master of Science (Advanced) in Astronomy and Astrophysics Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Mervyn & Katalin Paterson Fellowship', 'This scholarship is offered by the ANU College of Science.', 'Students enrolled full-time in a graduate research program in the Research School of Earth Sciences. Must have been enrolled in their research program for a minimum of 6 months.; Selection basis: The Committee shall select for the Scholarship a person who, in the opinion of the Committee, is at the stage in their Program where their research would be greatly enhanced by their attending a major international conference and visiting an overseas institution.', 'AUD $7500/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/mervyn-katalin-paterson-fellowship', 'https://search.studyaustralia.gov.au/scholarship/mervyn-katalin-paterson-fellowship/ff6e04b0f5d2a943ba43216c6346fb9a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Mervyn & Katalin Paterson Fellowship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Olin J Eggen Research Award', 'The Research School of Astronomy and Astrophysics (RSAA) offers the Olin J Eggen Research Award to up to 3 outstanding international students commencing in the PhD program at RSAA. Funding for this Award is made possible by an endowment setup to commemorate the contributions of the late Professor Olin J Eggen. Professor Eggen, a native of Wisconsin, USA, was Director of Mt Stromlo Observatory from 1966 through 1977, a period that saw considerable growth and with it the foundation of the high international regard in which the Observatory (now the Research School of Astronomy & Astrophysics) is held. The objective of the Award is to support outstanding international students to enable them to pursue a Doctor of Philosophy (PhD) program in Astronomy & Astrophysics based in the Research School of Astronomy & Astrophysics.', 'is enrolling full-time in a program of study for the degree of Doctor of Philosophy in Astronomy & Astrophysics based in the Research School of Astronomy & Astrophysics; and is and remains an international student; has a demonstrated track record of significant research that contributes to the field of Astronomy & Astrophysics.', 'AUD $2500/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/olin-j-eggen-research-award', 'https://search.studyaustralia.gov.au/scholarship/olin-j-eggen-research-award/e2fabf845cad95de850b3734cf441176', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Olin J Eggen Research Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Pacific Institute PhD Fieldwork Grant', 'Each year the ANU College of Asia and the Pacific (the College) may offer a number of awards known as the Pacific Institute PhD Grant for research (the Award). Funding for this Award has been provided by the Pacific Institute Endowment. The Pacific Institute recognizes the achievements of Jim Davidson, Professor of the Research School of Pacific and Asian Studies, Sir Peter Buck, distinguished Maori Historian, and Senator John Knight who established a Pacific Fellowship Fund. The objective of the Award is to advance the higher education of Pacific Islanders and research on Pacific-related topics by providing support for an outstanding domestic or international candidate.', 'is enrolling full-time in a program of study for the degree of Doctor of Philosophy in the ANU College of Asia and the Pacific; is of Pacific Islander Heritage; is conducting fieldwork in a Pacific studies related area', 'AUD $5000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/pacific-institute-phd-fieldwork-grant', 'https://search.studyaustralia.gov.au/scholarship/pacific-institute-phd-fieldwork-grant/de71a811d3d2fe7735c23ba24719c555', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Pacific Institute PhD Fieldwork Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Pacific Institute PhD Grant for Research', 'Each year the ANU College of Asia and the Pacific (the College) may offer a number of awards known as the Pacific Institute PhD Grant for research (the Award). Funding for this Award has been provided by the Pacific Institute Endowment. The Pacific Institute recognizes the achievements of Jim Davidson, Professor of the Research School of Pacific and Asian Studies, Sir Peter Buck, distinguished Maori Historian, and Senator John Knight who established a Pacific Fellowship Fund. The objective of the Award is to advance the higher education of Pacific Islanders and research on Pacific-related topics by providing support for an outstanding domestic or international candidate.', 'is enrolling full-time in a program of study for the degree of Doctor of Philosophy in the ANU College of Asia and the Pacific; is of Pacific Islander Heritage.', 'Up to AUD $10000', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/pacific-institute-phd-grant-research', 'https://search.studyaustralia.gov.au/scholarship/pacific-institute-phd-grant-for-research/df48c874121903c7f5e39b8554dbac52', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Pacific Institute PhD Grant for Research') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Paul Bunyan Memorial Scholarship in Medical Sciences', 'Each year, the John Curtin School of Medical Research (JCSMR) within the ANU College of Science and Medicine may offer a number of awards known as the Paul Bunyan Memorial Scholarship in Medical Sciences. \r\n\r\nThe objective of the Award is to support students undertaking their Honours project, with research to be conducted in medical science, preferably in a field related to cancer research.\r\n\r\nFunding for this Award has been provided by Mr and Mrs Bunyan, in memory of their son, Paul.', 'The scholarship is available to an applicant:;who is an International or domestic student; who is enrolled in an Honours year at the John Curtin School of Medical Research; whose Honours project is preferably related to cancer research.', 'AUD $10000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/paul-bunyan-memorial-scholarship-medical-sciences', 'https://search.studyaustralia.gov.au/scholarship/paul-bunyan-memorial-scholarship-in-medical-sciences/68264d8256f1e68ad1efcd1a12795d87', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Paul Bunyan Memorial Scholarship in Medical Sciences') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Peter Gage Memorial Supplementary Scholarship in Membrane Physiology', 'The Peter Gage Supplementary Scholarship in Membrane Physiology is named in honour of Professor Peter William Gage, in recognition of his having been one of Australias leaders in membrane physiology, biophysics and neuroscience. Peter influenced and encouraged a great many research students, postdoctoral fellows and senior colleagues in their scientific careers. The objective of the Award is to encourage outstanding domestic or international candidates to pursue a Doctor of Philosophy (PhD) program in the field of medical sciences, based in the JCSMR.', 'is enrolled or will be enrolling full-time in a program of study for the degree of Doctor of Philosophy, based in the John Curtin School of Medical Research; has completed qualifications comparable to the educational level of an Australian Bachelor first class Honours degree, or has demonstrated research experience to a standard equivalent to an ANU first class Honours; has been awarded, and continues to hold, an approved ANU HDR base stipend scholarship at the minimum AGRTP base rate.', 'AUD $10000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/peter-gage-memorial-supplementary-scholarship-membrane-physiology', 'https://search.studyaustralia.gov.au/scholarship/peter-gage-memorial-supplementary-scholarship-in-membrane-physiology/37ab3b8d333b6dbb37569c257560fe55', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Peter Gage Memorial Supplementary Scholarship in Membrane Physiology') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Peter McGregor HDR Supplementary Scholarship', 'The objective of the award is to reward excellence in research in the Research School of Astronomy & Astrophysics instrumentation program or excellence in research that has a substantial instrumentation component, and to encourage outstanding students to pursue PhD degree programs in astronomy and astrophysics at the ANU with a special emphasis on instrumentation development.', 'The award is available each year to a new or continuing student who is enrolled in the PhD program at the Research School of Astronomy & Astrophysics and is working on a project in astronomy and astrophysics that incorporates instrumentation development or innovative use of instrumentation.  The student must also have completed all required milestones to the satisfaction of the Delegated Authority.', 'AUD $6000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/peter-mcgregor-hdr-supplementary-scholarship', 'https://search.studyaustralia.gov.au/scholarship/peter-mcgregor-hdr-supplementary-scholarship/ddbc5985e9ea6b33d73edfe7540159c7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Peter McGregor HDR Supplementary Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'PhB Science Scholarship', 'Each year, the ANU College of Science and Medicine may offer a number of awards known as the PhB Science Scholarship.  The objective of the Award is to provide support to PhB Science students from disadvantaged backgrounds and/or to assist PhB Science students with relocation costs to support their move to Canberra.  Funding for this Award has been provided by the ANU College of Science and Medicine.', 'The Award is available each year to a commencing ANU student who:; (a) is a domestic or international student; (b) receives an offer of admission to the Bachelor of Philosophy (Honours) - Science; (c) is commencing their first undergraduate degree.', 'AUD $6500/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/phb-science-scholarship', 'https://search.studyaustralia.gov.au/scholarship/phb-science-scholarship/3d4202adeaafe2e7424009c1527451d1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'PhB Science Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RSAA Supplementary Scholarships', 'Research School of Astronomy and Astrophysics', 'This supplementary scholarship is extended to all Research School of Astronomy & Astrophysics PhD students, excluding those receiving an ARC Laureate Scholarship.; Eligible programs: Phd', 'AUD $5000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/rsaa-supplementary-scholarships', 'https://search.studyaustralia.gov.au/scholarship/rsaa-supplementary-scholarships/d5d9be063c8dfe81599417db5476edf9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RSAA Supplementary Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RSE Bob Gregory Honours in Economics Scholarship for International Students', 'Each year the Research School of Economics (the School) in the ANU College of Business and Economics (the College) may offer an award known as the Research School of Economics Bob Gregory Honours in Economics Scholarship for International Students (the award). The objective of the Award is to attract high achieving international students to enrol in an Honours in Economics program offered by the Research School of Economics. Funding for this award has been provided by the Research School of Economics.', 'is an international student; is currently completing, or has completed in the past 12 months, an undergraduate degree in Economics at an Australian university or recognised overseas institution; has accepted an offer of admission in the one-year Bachelor of Economics (Honours) program offered at the ANU College of Business and Economics; has accepted an offer of admission in the final year of the Honours in Economics program of the Bachelor of Finance, Economics and Statistics, offered at the College.', 'AUD $10000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/rse-bob-gregory-honours-economics-scholarship-international-students', 'https://search.studyaustralia.gov.au/scholarship/rse-bob-gregory-honours-in-economics-scholarship-for-international-students/60ca85ad1f6ec7797a9b907378e562e6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RSE Bob Gregory Honours in Economics Scholarship for International Students') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RSES Opportunity Scholarship', 'Each year the Research School of Earth Sciences (the School) may offer a number of awards known as the Earth Sciences Opportunity Scholarship (the Award). The objective of the Award is to provide financial assistance to students enrolled in an Earth Sciences degree program to allow them to commence, continue and/or complete their studies.Funding for this Award has been provided by various donors.', 'is a domestic or international student; is enrolled in or has completed EMSC1006 or EMSC1008 (undergraduate applicants); is enrolled in an undergraduate or postgraduate coursework program offered by the Research School of Earth Sciences; can demonstrate financial need.', 'Scholarship Value: Variable', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/rses-opportunity-scholarship', 'https://search.studyaustralia.gov.au/scholarship/rses-opportunity-scholarship/c4c0922de50f72718da7a2b03cb2a050', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RSES Opportunity Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RSSS Director’s Award for Higher Degree Research', 'The award is a top-up to the Australian Government Research Training Program (AGRTP) Stipend Scholarship (previously the Australian Postgraduate Award), for the top-ranked Higher Degree Research applicant enrolling full-time in a program of study for the degree of Doctor of Philosophy in the Research School of Social Sciences.', 'a domestic or international student; enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy in the Research School of Social Sciences at the Australian National University; has been awarded an AGRTP Stipend Scholarship.', 'AUD $20000/year — The amount will not exceed 75% of the AGRTP, so the amount will vary based on the value of the AGRTP.', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/rsss-directors-award-higher-degree-research', 'https://search.studyaustralia.gov.au/scholarship/rsss-directors-award-for-higher-degree-research/0e597fb71cc76ef548682a735ee575ad', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RSSS Director’s Award for Higher Degree Research') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Replacing Animals in Medical Research Honours Scholarship', 'This scholarship is to assist students enrolled in a one year Honours program, undertaking research utilising non-animal alternative methods to replace the use of animals or animal products in medical research.', 'is a domestic or international student; receives an offer of admission to an honours specialisation in the ANU College of Science or the ANU College of Health and Medicine; is undertaking research utilising non-animal alternative methods to replace the use of animals or animal products in medical research.', 'AUD $15000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/replacing-animals-medical-research-honours-scholarship', 'https://search.studyaustralia.gov.au/scholarship/replacing-animals-in-medical-research-honours-scholarship/680266e7c9c8d73dea1d60d5634b5bad', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Replacing Animals in Medical Research Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research School of Accounting Pre-Master Training Program Scholarship', 'Each year the Research School of Accounting within the ANU College of Business and Economics may offer a number of awards known as the Research School of Accounting Pre-Master Training Program Scholarship (the Award). The objective of the Award is to continue the long-standing partnership and successful pre-masters agreement between ANU and selected Partners. Funding for this Award has been provided by the Research School of Accounting.', 'is an international student; is completing, or has completed a recognised Pre-Master Training Program at a home institution; is enrolled in, or has received an offer of admission to the Master of Accounting (4 semesters), or the Master of Professional Accounting (3 semesters).', '25% Tuition Fee waiver', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-accounting-pre-master-training-program-scholarship', 'https://search.studyaustralia.gov.au/scholarship/research-school-of-accounting-pre-master-training-program-scholarship/d4d5a69320d71ae20aa45aeaf770f4f1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research School of Accounting Pre-Master Training Program Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research School of Biology International PhD Scholarship', 'Each year the ANU Research School of Biology (RSB) may offer one or more scholarships known as the Research School of Biology International PhD Scholarship to attract the highest calibre international students to pursue a PhD degree within the school.', 'an International student; enrolling full-time in a program of study for the degree of Doctor of Philosophy at ANU in RSB.', 'AUD $36652/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-biology-international-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/research-school-of-biology-international-phd-scholarship/937c872c3e8143301f674cd485222add', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research School of Biology International PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research School of Chemistry Honours Scholarship', 'This scholarship is to assist students enrolled in the Honours Year of an undergraduate degree offered by the ANU College of Science, specialising in Chemistry', 'is a domestic or international student; receives an offer of admission to Honours in Science, specialising in Chemistry; obtains a GPA of 6.00 or above out of 7.00 across 48 units of Chemistry or cognate courses', 'AUD $5000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-chemistry-honours-scholarship', 'https://search.studyaustralia.gov.au/scholarship/research-school-of-chemistry-honours-scholarship/d504bcf22139a171ad3f9601adbfa71e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research School of Chemistry Honours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research School of Finance, Actuarial Studies and Statistics Foundation Scholarship', 'Each year the Research School of Finance, Actuarial Studies and Statistics (RSFAS) within the ANU College of Business and Economics may offer a number of awards known as the Research School of Finance, Actuarial Studies and Statistics Foundation Scholarship (the Award). The objective of the Award is to continue the long-standing partnership and successful Foundation agreement between the ANU and selected partners. Funding for this Award has been provided by RSFAS.', 'is an international student; is enrolled in or has received an offer of admission to one of the following programs:; Bachelor of Actuarial Studies or; Bachelor of Finance or; Bachelor of Statistics', '10% of international student fee', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-finance-actuarial-studies-and-statistics-foundation', 'https://search.studyaustralia.gov.au/scholarship/research-school-of-finance-actuarial-studies-and-statistics-foundation-scholarship/76dc4bb3cacbd3628d48250aab9c506a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research School of Finance, Actuarial Studies and Statistics Foundation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research School of Finance, Actuarial Studies and Statistics Pre-Master Training Program Scholarship', 'Each year the Research School of Finance, Actuarial Studies and Statistics (RFSAS) within the ANU College of Business and Economics may offer a number of awards known as the Research School of Finance, Actuarial Studies and Statistics Pre-Master Training Program Scholarship (the Award). The objective of the Award is to continue the long-standing partnership and successful pre-masters agreement between ANU and selected Partners. Funding for this Award has been provided by RFSAS.', 'is an international student; is completing or has completed a recognised Pre-Master Training Program at a home institution; is enrolled in or has received an offer of admission to one of the following programs:; Master of Finance (4 semesters); Master of Actuarial Studies (4 semesters); Master of Financial Management (2 semesters); Master of Statistics (4 semesters); Master of Applied Finance (3 semesters); Master of Actuarial Practice (5 semesters)', '25% of international student fee', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-finance-actuarial-studies-and-statistics-pre-master', 'https://search.studyaustralia.gov.au/scholarship/research-school-of-finance-actuarial-studies-and-statistics-pre-master-training-program-scholarship/f2a3ed0009d08b75e1b9a3bebf253ebd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research School of Finance, Actuarial Studies and Statistics Pre-Master Training Program Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research Training Program (RTP) International Fee Offset Scholarship', 'Each year the Commonwealth Department of Education and Training provides funding to Universities to award scholarships to International students undertaking Higher Degree Research programs under the Australian Government Research Training Program (RTP).  Note the duration of this scholarship has been updated from 3 years to 3.5 years following the VCs announcement relating to scholarship changes in effect from 1.10.2022.  Candidates now no longer have to apply to extend this scholarship from 3 years to 3.5 years.', 'The Commonwealth Scholarship Guidelines (Research) 2017 set the basis for the conditions of award and outline the basic eligibility requirements for this scholarship.; The ANU has established an RTP Policy & Procedure which outlines the standards, processes and conditions for this scholarship.  These documents are available from the reference document section of this page.; Candidates are ranked and scholarships are awarded based on a competitive ranking process, to the top ranked candidates, subject to evidence they meet merit-based selection criteria, and subject to confirmation of a qualified supervisor, space and resources being available, in an area of research that is aligned with ANU research strategy.', 'Full Tuition fees for 3.5 years', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/research-training-program-rtp-international-fee-offset-scholarship', 'https://search.studyaustralia.gov.au/scholarship/research-training-program-rtp-international-fee-offset-scholarship/0ade3a1a62278cc92222ba7f7c416989', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research Training Program (RTP) International Fee Offset Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ross Taylor PhD Supplementary Scholarship in Geochemistry', 'Each year the Research School of Earth Sciences may offer an award known as the Ross Taylor PhD Supplementary Scholarship in Geochemistry. Funding for this Award has been provided by generous donations from associates of Ross Taylor, and matching School funds. Professor Taylor has made an outstanding contribution in geochemistry and as a pioneer of lunar science. His work spans the moon, the Earths continental crust, island arc rocks and beyond. Fifty years ago, the Canberra scientist Professor Ross Taylor made one of the big discoveries about the nature of the moon. Professor Taylor was chosen by NASA as the best person to analyze the first moon rocks brought back by Apollo 11. The launchpad for Taylors success was the environment of excellence at ANU, which included an almost identical lab to NASA. Taylors involvement with the moon was not his only contribution to science. Apart from many academic awards, he was elected as a Foreign Associate of the US National Academy of Sciences in 1994 and he was appointed a Companion of the Order of Australia in 2008.', 'a domestic or international student; enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy in Earth Sciences at the ANU.', 'AUD $8000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/ross-taylor-phd-supplementary-scholarship-geochemistry', 'https://search.studyaustralia.gov.au/scholarship/ross-taylor-phd-supplementary-scholarship-in-geochemistry/b90d01f5d3293d8fc73c39f3f7881694', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ross Taylor PhD Supplementary Scholarship in Geochemistry') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ruth Daroesman Graduate Study Grant', 'Each year the ANU College of Asia and the Pacific (the College) in conjunction with the ANU Indonesia Project may offer an award known as the Ruth Daroesman Graduate Study Grant (the Award). The objective of the Award is to support a graduate or higher degree research (HDR) student in their research associated with Indonesia. Funding for this Award has been provided by the Ruth Daroesman Endowment.', 'is a domestic or international student; is enrolled in a postgraduate coursework or higher degree research program in the College; is undertaking study or research related to Indonesia and that is relevant to their degree program.', 'AUD $6000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/ruth-daroesman-graduate-study-grant', 'https://search.studyaustralia.gov.au/scholarship/ruth-daroesman-graduate-study-grant/55c0d5187a4c29f20bd162972f3ec6d3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ruth Daroesman Graduate Study Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Scholarship in Regolith Science', 'Each year the Research School of Earth Sciences (the School) may offer two awards known as the Scholarship in Regolith Science (the Award). The objective of the Award is to support regolith-related research, especially important for Australian environments. Funding for this Award has been provided through an endowment established in 2008 by the Cooperative Research Centre for Landscape Environments and Mineral Exploration - a joint - venture including the Australian National University (ANU).', 'is a domestic or international student; is enrolled or will enrol in one of the following programs:; Bachelor of Science (Honours); Bachelor of Science (Advanced) (Honours); Bachelor of Philosophy (Honours); Master of Earth Sciences (Advanced); is undertaking a research project that is consistent with the broad field of regolith science. Projects can include laboratory and/or field and/or modelling studies.', 'AUD $5000/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/scholarship-regolith-science', 'https://search.studyaustralia.gov.au/scholarship/scholarship-in-regolith-science/64ffb8cef767caa23a2972696137b1b1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Scholarship in Regolith Science') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'School of Cybernetics Scholarship', 'The objective of the Award is to support students who are undertaking the School of Cybernetics Masters of Applied Cybernetics. The Award aims to help build the recipients leadership skills in technology, business and community areas, and to develop a mentoring relationship with prominent professionals in the private and public sectors.', 'is a domestic student or international student; receives an offer of admission to or is enrolled in the Master of Applied Cybernetics.', 'AUD $34000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/school-cybernetics-scholarship', 'https://search.studyaustralia.gov.au/scholarship/school-of-cybernetics-scholarship/4bb1b180f241acb4f8b04d873c5cb27a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'School of Cybernetics Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Schwarzman Scholarship', 'Schwarzman Scholars is an unparalleled graduate program for the next generation of young leaders, anchored in a fully-funded 10-month Masters Degree in Global Affairs at Beijings Tsinghua University. The experience encompasses unique opportunities in and outside the classroom, including extensive leadership training, a network of senior mentors, opportunities to engage in high-level interactions with Chinese leaders and visiting speakers, optional internships, career development, and travel seminars around China. Scholars will learn from world-class faculty and guest speakers about the Chinas importance on the global stage through a rigorous and dynamic core curriculum. Schwarzman Scholars prepares young leaders for a globally interconnected future and for careers in which they will join a growing alumni network of leaders who are working to build mutual understanding between China and the rest of the world.  Students spend a year immersed in an international community of thinkers, innovators and senior leaders in business, politics and society. In an environment of intellectual engagement, professional development and cultural exchange, they learn from one another and pursue their academic disciplines while building their leadership capacities. This experience will expand students understanding of the world and create a growing network of global leaders that will build strong ties between China and the rest of the world.', 'Undergraduate degree or first degree from an accredited college or university or its equivalent.; Age Requirement.; English language proficiency.', 'Tuition, Room & Board, Stipend & more', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/schwarzman-scholarship', 'https://search.studyaustralia.gov.au/scholarship/schwarzman-scholarship/7250d6c4385e092be7332d87eb1264a6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Schwarzman Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Shen-su Sun PhD Supplementary Scholarship', 'The Shen-su Sun PhD Supplementary Scholarship is offered by the Research School of Earth Sciences (RSES), in the ANU College of Science, to outstanding Chinese PhD Candidates who have been awarded a scholarship by the Chinese Scholarship Council. It is aimed at attracting the highest quality Chinese PhD Candidates to the RSES.', 'All successful ANU-CSC Scholarship recipients who enrol with RSES will be considered for this Award.', 'AUD $10000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/shen-su-sun-phd-supplementary-scholarship', 'https://search.studyaustralia.gov.au/scholarship/shen-su-sun-phd-supplementary-scholarship/65a51b77a7af615a6853609bb12c3457', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Shen-su Sun PhD Supplementary Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Shine-Dalgarno Centre PhD Scholarship', 'In 2024, the Shine-Dalgarno Centre for RNA Innovation, John Curtin School of Medical Research (JCSMR), ANU College of Health and Medicine offers one full scholarship known as the Shine-Dalgarno PhD Scholarship (the Award)', 'Have demonstrated H1 or H1 equivalence; Are enrolling in a full-time program (with exceptions for special circumstances to be part-time) of study for the degree of Doctor of Philosophy at the ANU in the subject area of RNA biology, with supervision from a member of the Shine-Dalgarno Centre for RNA Innovation (SDCRI).', 'AUD $36652/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/shine-dalgarno-centre-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/shine-dalgarno-centre-phd-scholarship/9303cebfc9615820dd21dda245e9066e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Shine-Dalgarno Centre PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Shine-Dalgarno Centre PhD Supplementary Scholarship', 'Each year the Shine-Dalgarno Centre for RNA Innovation, John Curtin School of Medical Research (JCSMR), ANU College of Health and Medicine may offer up to ten awards known as the Shine-Dalgarno PhD Supplementary Scholarship (the Award).', 'A domestic or international candidate; Is a recipient of an ANU approved HDR base stipend scholarship; is enrolled in a full-time program of study for the degree of Doctor of Philosophy in the subject area of RNA biology, with supervision from a member of the Shine-Dalgarno Centre for RNA Innovation (SDCRI).', 'AUD $10000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/shine-dalgarno-centre-phd-supplementary-scholarship', 'https://search.studyaustralia.gov.au/scholarship/shine-dalgarno-centre-phd-supplementary-scholarship/83b9559c31886d6060cabe38fd4da7f5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Shine-Dalgarno Centre PhD Supplementary Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Stephen & Helen Wurm PhD Scholarship in Asia-Pacific Linguistics', 'Each year the School of Culture History and Language (CHL), in the ANU College of Asia and the Pacific (CAP), may offer an award known as the Stephen and Helen Wurm PhD Scholarship in Asia-Pacific Linguistics. This Award provides funding for an outstanding domestic or international student, to enable them to pursue a PhD program in Linguistics, based in the CHL, and study a lesser-described Asia-Pacific language, or languages.', 'Continuation based on academic performance; 6 month extension available.', 'AUD $39069/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/stephen-helen-wurm-phd-scholarship-asia-pacific-linguistics', 'https://search.studyaustralia.gov.au/scholarship/stephen-helen-wurm-phd-scholarship-in-asia-pacific-linguistics/a21cee760952d9db6b8c4310057491ac', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Stephen & Helen Wurm PhD Scholarship in Asia-Pacific Linguistics') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Taiwan Australian National University Scholarship', 'In 2023, ANU re-signed an agreement with the Department of International and Cross-Strait Education of the Ministry of Education of the Republic of China (Taiwan) (hereunder referred to as "DICE") to continue the Taiwan Australian National University Scholarship until 2028. The scholarship program commenced in 2013 and provides tuition fees and stipends for up to 5 Taiwanese students per year to undertake PhD studies at ANU over the course of the five year agreement. The scholarships will be jointly funded by ANU and DICE.', 'Continuation based on academic performance; 6 month extension available.', 'AUD $39069/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/taiwan-australian-national-university-scholarship', 'https://search.studyaustralia.gov.au/scholarship/taiwan-australian-national-university-scholarship/d54c5649a2b2b8fa571b7f0b80741296', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Taiwan Australian National University Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Taiyang and Loong PhD Supplementary Scholarship', 'Each year the John Curtin School of Medical Research (JCSMR), ANU College of Health and Medicine may offer up to six awards known as the Taiyang and Loong PhD Supplementary Scholarship (the Award). The objective/s of the Award are to encourage interest in computational biology, accelerate knowledge and skill development and cultivate an entrepreneurial research and learning environment for PhD students.', 'A domestic and/or international student; Have obtained first-class Honours, or equivalent in the field of computer science or a related discipline; Enrolling full-time in a program of study for the degree of Doctor of Philosophy at the ANU in the subject area of computational biology, with the John Curtin School of Medical Research; A recipient of an ANU approved HDR base stipend scholarship; Candidates must demonstrate keen interest in developing new computer science tools and applications that directly address real-world biomedical problems. PhD projects will focus on specific biological questions, with defined potential industry partners and computational areas.', 'AUD $10000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/taiyang-and-loong-phd-supplementary-scholarship', 'https://search.studyaustralia.gov.au/scholarship/taiyang-and-loong-phd-supplementary-scholarship/4ae0ac5b0b41c7fa9948ab5559d25343', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Taiyang and Loong PhD Supplementary Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Talo Computational Biology Talent Accelerator Innovator Grant', 'Each year the John Curtin School of Medical Research, ANU College of Health and Medicine (JCSMR) may offer awards known as the Taiyang and Loong Innovator Grant (the Award) offered as part of the Talo Computational Biology Talent Accelerator Program. The objectives of the Award are to support PhD candidates and early-career researchers (up to five years post-PhD) for projects requiring proof-of-concept evidence of a new, promising computational technology. Funding for this Award has been provided by Taiyang Zhang and Loong Wang through the JCSMR Talo Computational Biology Talent Accelerator program.', 'The Award/s will be made available each year (subject to availability) to a continuing ANU PhD candidate or early-career researcher (up to five years post-PhD) undertaking a research project at JCSMR or in collaboration with a JCSMR research group.', 'AUD $10000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/talo-computational-biology-talent-accelerator-innovator-grant', 'https://search.studyaustralia.gov.au/scholarship/talo-computational-biology-talent-accelerator-innovator-grant/e166221b07201512a6fc8e8cbe467647', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Talo Computational Biology Talent Accelerator Innovator Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Talo Computational Biology Talent Accelerator Program Travel Grant', 'Each year the John Curtin School of Medical Research (JCSMR) (the School) in the ANU College of Health and Medicine(theCollege) may offer up to six awards known as the Talo Computational Biology Talent Accelerator Program Travel Grant (the Award). Funding for this Award has been provided by Taiyang Zhang and Loong Wang through the JCSMR Talo Computational Biology Talent Accelerator program. The objective of the Award is to fund short-term research placements in industry and external academic institutions to enable recipients engaged in computational biology affiliated with JCSMR to develop further research and translational expertise relevant to their field of study.', 'The Award is available each year to a continuing domestic or international ANU PhD student or Early Career Researcher (up to five years post-PhD) carrying out computational biology research affiliated with JCSMR.; Travel or research must be undertaken in the year the Award is granted.', 'AUD $10000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/talo-computational-biology-talent-accelerator-program-travel-grant', 'https://search.studyaustralia.gov.au/scholarship/talo-computational-biology-talent-accelerator-program-travel-grant/126efe767907affe5dfc78553b241f9e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Talo Computational Biology Talent Accelerator Program Travel Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Bill Hickson & Engineers Australia Scholarship for the Master of Applied Cybernetics', 'The objective of the Award is to support and provide funding for a domestic or international candidate with financial need who is eligible for membership of the Institution of Engineers Australia to enable them to pursue a Master\'s program in Cybernetics at the School.', 'is a domestic student or international student; receives an offer of admission to the Master of Applied Cybernetics, College of Engineering, Computing and Cybernetics; is eligible for membership to the Institution for Engineers Australia.', 'AUD $34000/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/bill-hickson-engineers-australia-scholarship-master-applied', 'https://search.studyaustralia.gov.au/scholarship/the-bill-hickson-engineers-australia-scholarship-for-the-master-of-applied-cybernetics/c66d3b72e253c0b0f6835a0aa2cfaf4d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Bill Hickson & Engineers Australia Scholarship for the Master of Applied Cybernetics') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Boswell Technologies Grant for Space Exploration, Moon and Mars', 'This award is intended to aid coursework students undertaking research in the area of Space Exploration, Moon and Mars. Funding is provided by the Boswell Technologies Endowment fund, established by Prof Roderick Boswell. The award could be used towards travel, acquiring of equipment or collaboration activities.', 'a domestic and/or international student; enrolled full or part-time; be enrolled in a postgraduate or undergraduate program in the College of Science; undertaking a research project related to space exploration, moon and Mars.', 'AUD $4000/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/boswell-technologies-grant-space-exploration-moon-and-mars', 'https://search.studyaustralia.gov.au/scholarship/the-boswell-technologies-grant-for-space-exploration-moon-and-mars/00d573eec7f3526e16f81ffa76991c86', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Boswell Technologies Grant for Space Exploration, Moon and Mars') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Boswell Technologies HDR Award for Space Exploration, Moon and Mars', 'This award is intended to aid higher degree research students undertaking research in the area of Space Exploration, Moon and Mars.\r\n\r\nFunding is provided by the Boswell Technologies Endowment fund, established by Prof Roderick Boswell.\r\n\r\nThe award could be used towards travel, acquiring of equipment or collaboration activities.', 'a domestic and/or international student; enrolled full or part-time; be enrolled in a Higher Degree Research program, (and in exceptional cases an undergraduate program) in the College of Science; undertaking a research project related to Space Exploration, Moon and Mars.', 'AUD $4002/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/boswell-technologies-hdr-award-space-exploration-moon-and-mars', 'https://search.studyaustralia.gov.au/scholarship/the-boswell-technologies-hdr-award-for-space-exploration-moon-and-mars/653bf1532610cf95651d0a41441f283e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Boswell Technologies HDR Award for Space Exploration, Moon and Mars') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Elephant in the Study: Working Latin Literature for the Enslaved PhD Scholarship', 'Applications are invited for a PhD scholarship in Latin literature and/or Roman slavery. The scholarship is supported by the Australian National University (ANU) and is part of an Australian Research Council (ARC) Future Fellowship.   The Elephant in the Study: Working Latin Literature for the Enslaved is an ARC supported inquiry into the role and significance of enslaved co-authors in the production of Latin literature between approximately 100 BCE and 100 CE. The project will examine the implications of enslaved collaboration for the form, content and reception of classical Latin literature, and probe how such collaboration changes our notion of the histories of literature, authorship, and slavery.', 'Continuation based on academic performance; 6 month extension available.', 'AUD $40475/year', 'Postgraduate', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/elephant-study-working-latin-literature-enslaved-phd-scholarship-0', 'https://search.studyaustralia.gov.au/scholarship/the-elephant-in-the-study-working-latin-literature-for-the-enslaved-phd-scholarship/51fcd5a2afd5d803e00d4b00206d5e01', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Elephant in the Study: Working Latin Literature for the Enslaved PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Friends of the ANU Classics Museum Grant for Collection Research', 'Each year the School of Literature, Languages and Linguistics may offer an award known as The Friends of the ANU Classics Museum Grant for Collection Research.  The objective of the Award is to support Honours and Master\'s students in one of the eligible specialisations listed below whose thesis research will include the study of objects in the collection of the ANU Classics Museum, especially their provenance and collection history.', 'The Award is available each year to a commencing or continuing ANU student who:; is a domestic or international student; receives an offer of admission to an Honours program or a Master’s program at the ANU College of Arts and Social Sciences in one of the following fields:; Classical Studies; Archaeology; Anthropology; Art History and Theory; History; Middle Eastern and Central Asian Studies; Museums and Collections; Museum Education and Heritage Interpretation; Intangible Cultural Heritage; any other field deemed relevant by the Selection Committee; will conduct research on the provenance and/or collection history of objects in the ANU Classics Museum.', 'AUD $2000/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/friends-anu-classics-museum-grant-collection-research', 'https://search.studyaustralia.gov.au/scholarship/the-friends-of-the-anu-classics-museum-grant-for-collection-research/d83f5ed529b9a98c2a38f3864b638a02', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Friends of the ANU Classics Museum Grant for Collection Research') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Friends of the ANU Classics Museum Honours Grant in Classical Studies', 'Each year, the School of Literature, Languages and Linguistics within the ANU College of Arts and Social Sciences may offer an award known as The Friends of the ANU Classics Museum Honours Grant in Classical Studies. The objective of the Award is to support Honours students in Classical Studies whose thesis research will include the study of objects in the collection of the ANU Classics Museum. Funding for this Award has been provided by The Friends of the ANU Classics Museum, established in 1985 to promote the interests of the Museum and to encourage interest in Ancient Greece and Rome in the wider community.', 'The Award is available each year to a commencing or continuing ANU student who: ; is a domestic or international student; receives an offer of admission to an Honours program in the field of Classical Studies at the ANU College of Arts and Social Sciences; will study objects in the collection of the ANU Classics Museum as part of their thesis research.', 'AUD $2000/year', 'Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/friends-anu-classics-museum-honours-grant-classical-studies', 'https://search.studyaustralia.gov.au/scholarship/the-friends-of-the-anu-classics-museum-honours-grant-in-classical-studies/c424eb1a0465fef48ff4d2684df2df40', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Friends of the ANU Classics Museum Honours Grant in Classical Studies') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Knight-Hennessy Scholars program', 'Knight-Hennessy Scholars cultivates and supports a multidisciplinary and multicultural community of graduate students from across Stanford University, and delivers engaging experiences that prepare graduates to be visionary, courageous, and collaborative leaders who address complex challenges facing the world. Scholars participate in up to three years of programming that complements their graduate studies and prepares them to take on leadership roles in academia, industry, government, nonprofits, and the community at large.', 'Please Contact ANU for more information about Eligibility', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://study.anu.edu.au/scholarships/find-scholarship/knight-hennessy-scholars-program', 'https://search.studyaustralia.gov.au/scholarship/the-knight-hennessy-scholars-program/9a36eb520ad82eba80c7d7b3ae277aa7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00120C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Knight-Hennessy Scholars program') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Merit Scholarship for Africa', 'This scholarship supports outstanding students from African countries to pursue their academic goals at RMIT University in Melbourne, Australia.', 'In order to qualify for this scholarship you must:; be a citizen of countries in Africa; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; achieve Australian equivalent grade GPA of 2.5 or 70% average or ATAR 75 in your qualifying qualification at the time of application; hold a full or conditional offer letter commencing in 2026 or later in Vocational Education, Associate Degree*, Bachelor’s degree*, Graduate Certificate, Graduate Diploma or Masters by Coursework program; not be an existing RMIT University student (existing ELICOS or Foundation Studies may qualify and will be notified after Foundation Studies completion).', 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible program(s)* as outlined in your offer letter.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/academic-merit-scholarship-africa', 'https://search.studyaustralia.gov.au/scholarship/academic-merit-scholarship-for-africa/d6a2a3a3f3c753cbedfe7cb4a0857a17', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Merit Scholarship for Africa') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Merit Scholarship for South East Asia', 'This scholarship supports outstanding students from Brunei Darussalam, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Timor-Leste or Vietnam to pursue their academic goals at RMIT University in Melbourne, Australia.', 'In order to qualify for this scholarship you must:; be a citizen of Brunei Darussalam, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Timor-Leste or Vietnam; be applying offshore from Brunei Darussalam, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Timor-Leste or Vietnam (RMIT Vietnam students who completed cross-campus studies and immediately apply for the same qualification (course) in Melbourne campus are not eligible); be an international student holding a valid student visa or plan to apply for a student visa prior to the course commencement; achieve Australian equivalent grade GPA of 2.5 or 70% average or ATAR 75 in your qualifying qualification at the time of application; hold a full or conditional offer letter to commence studies in Vocational Education, Associate Degree*, Bachelor’s degree*, Graduate Certificate, Graduate Diploma or Masters by Coursework degree; not be an existing RMIT University student (existing ELICOS or Foundation Studies may be qualified and will be notified after Foundation Studies completion).', 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible course(s)* as outlined in your offer letter.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/academic-merit-scholarship-southeast-asia#overview', 'https://search.studyaustralia.gov.au/scholarship/academic-merit-scholarship-for-south-east-asia/c4ebbacce3c2c99cc8e6c57414bed5b6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Merit Scholarship for South East Asia') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'COBL Academic Merit Scholarships for Vietnam', 'This scholarship provides financial assistance to outstanding students from Vietnam.', 'In order to qualify for this scholarship you must:; be a citizen of Vietnam and be applying offshore from Vietnam (RMIT Vietnam students who completed cross-campus studies and immediately apply for the same qualification (program) in Melbourne campus are not eligible); be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; achieve Australian equivalent grade GPA of 3.0 or 75% average in your qualifying qualification at the time of application; hold a full or conditional offer letter to commence studies in Bachelor’s degree, Graduate Certificate, Graduate Diploma or Masters by Coursework programs offered by: School of Accounting, Information Systems and Supply Chain, School of Economics, Finance and Marketing, School of Management; not be an existing RMIT University student (existing ELICOS or Foundation Studies may be qualified and will be notified after Foundation Studies completion).', '25% tuition fee reduction for the eligible program(s) duration outlined on your offer letter.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/cobl-academic-merit-scholarships-for-vietnam#overview', 'https://search.studyaustralia.gov.au/scholarship/cobl-academic-merit-scholarships-for-vietnam/2b3803b7ff25e436eb7936867ddc405f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'COBL Academic Merit Scholarships for Vietnam') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'College of Design and Social Context Student Bursary', 'This bursary provides financial assistance to international students studying in the College of Design and Social Context (DSC).', 'In order to qualify for this scholarship you must:; be an international student holding a valid student visa or plan to apply for a student visa prior to the commencement of your degree; have existing offer letter (full or conditional offer) and be a commencing student in:; Semester 2 2026 intake in any College of Design and Social Context course (excluding Master by Research or PhD); Semester 3 2026 intake for Master of Project Management, Master of Energy Efficient and Sustainable Building; achieve Australian equivalent grade GPA of 2.0 or 60% average or ATAR 60 in your qualifying qualification at the time of application; not be an existing RMIT student (including RMIT Vietnam students); not be receiving another RMIT-funded scholarship or external sponsorship covering tuition fees', 'Up to AUD $5000 — The total value of the bursary is a AU$5,000, one-off payment towards future tuition fees to be paid after the first census date into student\'s university account.', 'Postgraduate', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/college-of-design-and-social-context-student-bursary#overview', 'https://search.studyaustralia.gov.au/scholarship/college-of-design-and-social-context-student-bursary/a4f0b0c43be03f6b561534343be3bb84', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'College of Design and Social Context Student Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'English to Foundation Studies/Fast Track Pathway Bursary', 'If you plan to study an English language pathway to either an RMIT Foundation Studies or Fast Track program in 2027, you may qualify for our English to Foundation Studies/Fast Track Pathway Bursary.', 'In order to qualify for this scholarship you must:; be studying Academic English and plan to progress to an RMIT Foundation Studies or Fast Track program in 2027; be an offshore offshore students from one of the following regions:; China: Mainland and Hong Kong SAR; South-East Asia: Myanmar, Malaysia, the Philippines and Indonesia', '10% of the tuition fee for Academic English.', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/english-pathway-bursary#overview', 'https://search.studyaustralia.gov.au/scholarship/english-to-foundation-studiesfast-track-pathway-bursary/7575029365164d1de7815f7c105845db', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'English to Foundation Studies/Fast Track Pathway Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'External Scholarships (Sponsorship)', 'RMIT welcomes students who have scholarship funded by their home government (sponsored students). RMIT currently has over 800 sponsored students. They are enrolled in a wide range programs in all study levels. Prospective sponsored students need to make their own enquiries about scholarship opportunities available within their home country or about potential sponsorship opportunities (such as funding from your employer to study in RMIT).', 'Please contact RMIT for further information via isscholarships@rmit.edu.au.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/external-scholarships-sponsorship/217a3888b1c86f6fdf4076e50f839a01', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'External Scholarships (Sponsorship)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'FUNED - RMIT Scholarship', 'If you are an international student from Mexico applying for a Masters by Coursework program at RMIT University, you may be eligible for this jointly funded scholarship by RMIT and the Mexican Foundation for Education, Technology and Science (FUNED).', 'In order to qualify for this scholarship you must:; be a citizen of Mexico; have applied for a Masters by Coursework at RMIT; satisfy the general and specific requirements of the FUNED credit scholarship; meet the academic requirements for entry to RMIT and have been given an unconditional offer of a place in the program; have been awarded the FUNED credit scholarship; be commencing full time enrolment as an international student at RMIT in Melbourne.', 'Up to AUD $12000 — RMIT UP Academic English Bursary for Latin American students if you are required to study ELICOS; tuition fee support by RMIT to the value of 25% of the tuition fees for Masters by Coursework program for a maximum of two years.', 'Postgraduate', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/funed-rmit-scholarship#overview', 'https://search.studyaustralia.gov.au/scholarship/funed-rmit-scholarship/d5f28687a45f8e471ca15ff3f7ccf446', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'FUNED - RMIT Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Fast Track University Pathway Academic Scholarship', 'This scholarship provides financial assistance to high achieving Fast Track University Pathway international students.', 'In order to qualify for this scholarship you must:; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; have existing offer letter (full or conditional offer) and be a commencing student in Semester 2 2027 intake in any stream of Fast Track University Pathways program', 'Up to AUD $5000 — The total value of the scholarship is a AU$5,000, one-off payment towards future tuition fees to be paid after the first census date into student\'s university account.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/fast-track-university-pathway-academic-scholarships', 'https://search.studyaustralia.gov.au/scholarship/fast-track-university-pathway-academic-scholarship/56375cbc569ed634d3d9a4e8d5269a1d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Fast Track University Pathway Academic Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Foundation Academic Scholarships', 'This scholarship provides financial assistance to high achieving Foundation Studies international students.', 'In order to qualify for this scholarship you must:; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; have existing offer letter (full or conditional offer) and be commencing student in either Semester 1 or Semester 2 2027 intake in any stream of Foundation Studies program', 'Up to AUD $5000 — The total value of the scholarship is AU$5,000, one-off payment towards future tuition fee to be paid after the first census date into student\'s university account.', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/foundation-academic-scholarships', 'https://search.studyaustralia.gov.au/scholarship/foundation-academic-scholarships/799e1e8b4fcb86d16b89d9c20b95755f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Foundation Academic Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Future Leaders Scholarship', 'Provides students from India and the subcontinent with a 20% tuition fee reduction for eligible Bachelor and Masters programs that have received an offer from 2026.', 'In order to qualify for this scholarship you must:; be a citizen of India, Sri Lanka, Bangladesh, Bhutan, Nepal or Pakistan (including dual citizenship holding one of these country\'s passport); be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; have an offer letter to commence from 2026 intakes onwards in one of the following programs at RMIT: Bachelor degree, Masters by Coursework; not be an existing student who commence in another program within the same study level', 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible program(s)* as outlined in your offer letter.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/future-leaders-scholarship', 'https://search.studyaustralia.gov.au/scholarship/future-leaders-scholarship/b5c7348d68d65c7feaaa58c6da528204', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Future Leaders Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Gavin Teague Memorial Scholarship', 'For students enrolled in the Bachelor of Fine Arts program who can demonstrate artistic merit and circumstances which impact their study worth up to $1,300.', 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident or an international student who has resided in Australia for at least two years; be enrolling full-time in Semester 1 and 2 in your second or third year of the Bachelor of Fine Arts (BP201) at RMIT in 2027; be able to demonstrate circumstance(s) that impact your ability to study, or be from an RMIT priority group.', 'Up to AUD $1300', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/coursework/gavin-teague', 'https://search.studyaustralia.gov.au/scholarship/gavin-teague-memorial-scholarship/00bb801d06053d9be644b22c11010734', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Gavin Teague Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Medibank Excellence Scholarship', 'The Medibank Excellence Scholarship is available to international students studying Australian Year 12 or International Baccalaureate in Australia. In addition to receiving AU$12,000 successful applicants will have the opportunity to attend Medibank workshops, participate in event-coordination for Medibank on Open Day, meet recent graduates working at Medibank, and be involved in a customer focus group.', 'In order to qualify for this scholarship, you must:; be applying from Australia; be a current year 12 student in Australia graduating in 2026; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; submit your application via VTAC and receive an offer from RMIT for an Associate degree or Undergraduate degree; not be an existing RMIT student.', 'Up to AUD $12000 — The total value of the scholarship is AU$12,000, to be paid to recipient\'s Australian bank account in AU$6,000 installments after the census date of each semester of the first year.', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/medibank-excellence-scholarship#overview', 'https://search.studyaustralia.gov.au/scholarship/medibank-excellence-scholarship/bda799bcfae582af445fda7a51dec7bb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Medibank Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Medibank High Achiever International Scholarship', 'This scholarship, valued at AU$20,000, is available to international students studying Australian Year 12 or International Baccalaureate in Australia.', 'In order to qualify for this scholarship, you must:; be applying from Australia; be a current year 12 student in Australia graduating in 2026; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; submit your application via VTAC and receive an offer from RMIT for an Associate degree or Undergraduate degree; not be an existing RMIT student.', 'Up to AUD $20000 — The total value of the scholarship is AU$20,000, to be paid to recipient\'s Australian bank account in AU$10,000 installments after the census date of each semester of the first year.', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/medibank-high-achiever-international-scholarship#overview', 'https://search.studyaustralia.gov.au/scholarship/medibank-high-achiever-international-scholarship/9b727152663ae97c96185362ffea0e9d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Medibank High Achiever International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Pathway Scholarship for China', 'This scholarship supports students from China to study a Bachelor program at RMIT University in Melbourne, Australia.', 'In order to qualify for this scholarship you must:; be a citizen of the People\'s Republic of China (including Hong Kong SAR and Macau SAR); be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; hold a Bachelor* offer commencing in 2026 or later that is packaged with ELICOS, Foundation Studies or Fast Track University Pathway, a Vocational Education (VE), or Associate Degree program. Students who have a packaged offer and are currently enrolled or recently completed a pathway program(s) will be eligible.; not be an existing RMIT University student studying a Bachelor program', 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible Bachelor program(s) as outlined in your offer letter.', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/pathway-scholarship', 'https://search.studyaustralia.gov.au/scholarship/pathway-scholarship-for-china/29a20b3e33c9cf077ecae8e3491b0da9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Pathway Scholarship for China') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT David Phillips Memorial Scholarship', 'For students enrolled full-time in the ELICOS English for Academic Purposes (EAP) Program who can demonstrate hardship; worth $5,000.', 'Applicants must: have been born overseas; have recently migrated to Australia; be from a non-English speaking background; have an Australian bank account; be enrolling full-time in RMIT English Worldwide’s ELICOS Academic English Program EL000 with the course start date typically at the end of August in the year of award. See website for full criteria.', 'Up to AUD $5000 — This scholarship provides $5,000 as a one-off payment. A short student report must be completed before payment is made to the successful recipient.', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/coursework/david-phillips', 'https://search.studyaustralia.gov.au/scholarship/rmit-david-phillips-memorial-scholarship/d2ec6bbb95a42533d1bc38a55330b012', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT David Phillips Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT English Language Bursary for Latin American Students', 'For 2025 and 2026 commencement: 35% of the total program fee for an ELICOS program (you pay $355 per week after the discount)', 'be a citizen of Latin America countries; applying from Australia or overseas; enrol in an English for Academic Purposes program at RMIT University Pathways (RMIT UP) commencing in 2025 or 2026; be a commencing RMIT UP student (including extending your program in Australia).For further information contact RMIT via isscholarships@rmit.edu.au', '35% of the total program fee for an ELICOS program (you pay $338 per week after the discount)', 'Undergraduate / VET', 'Languages', 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-english-bursary-for-latin-american-students', 'https://search.studyaustralia.gov.au/scholarship/rmit-english-language-bursary-for-latin-american-students/475b48e53aeac5761f333d81f6e302ae', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT English Language Bursary for Latin American Students') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT John Bush Memorial Scholarship', 'For Thailand born students studying full-time in an undergraduate or postgraduate by coursework program who can demonstrate circumstances which impact their study; worth up to $10,000.', 'Applicants must: have been born in Thailand; be an Australian or New Zealand citizen, Australian permanent resident or permanent humanitarian visa holder, asylum seeker or an international student; be enrolling full-time in an associate or bachelor degree, a graduate certificate, graduate diploma or a masters by coursework program at RMIT University; be able to demonstrate circumstance/s which impact your ability to study or be from an under-represented background such as current/former refugee; be residing in Australia. See website for full eligibility criteria.', 'Up to AUD $30000 — This scholarship provides up to $10,000 for one year ($5,000 per semester).', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/coursework/bush', 'https://search.studyaustralia.gov.au/scholarship/rmit-john-bush-memorial-scholarship/3a785f30cc5138b5f234712fe4577486', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT John Bush Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT MAI Foundation Scholarship', 'For commencing first-year students who are passionate about business, law or construction/project development, and who can demonstrate circumstances which impact their study; worth up to $50,000.', 'Applications must: be an Australian citizen, Australian permanent resident, permanent humanitarian visa holder or international student visa holder; commencing first year in a Bachelor of Business, Bachelor of Business Professional, Bachelor of Commerce, Bachelor of Laws, Bachelor of Property Development, Investment and Valuation (Honours) or a Bachelor of Construction Management (Honours); be able to demonstrate circumstance/s which impact your ability to study or be from an under-represented background such as a current/former refugee. Visit website for full eligibility criteria.', 'Up to AUD $50000 — The scholarship provides $10,000 per year for the standard duration of program.', 'Undergraduate / VET', 'Built environment, Business and management, Law', 'https://www.rmit.edu.au/scholarships/coursework/mai-foundation', 'https://search.studyaustralia.gov.au/scholarship/rmit-mai-foundation-scholarship/ae3c50f1e28f2f8c5490f3d6ad0ceb30', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT MAI Foundation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT UP Academic English Bursary for Asia', 'If you are a citizen of Cambodia, Japan, Laos, South Korea, Taiwan, Thailand or Vietnam this bursary provides a tuition fee discount on your Academic English course.', 'In order to qualify for this scholarship you must:; be a citizen of Cambodia, Japan, Laos, South Korea, Taiwan, Thailand or Vietnam; applying from Australia or overseas; enrol in an Academic English course at RMIT University Pathways (RMIT UP) commencing in 2026 or 2027 for 10 weeks or more; not be the recipient of any other English Language scholarship (including external scholarships); be a commencing RMIT UP student (including extending your program in Australia).', '10% of the total program fee in 2026 study period for an Academic English course (you pay $491 per week after the discount); 20% of the total program fee in 2027 study period for an Academic English course (you pay $452 per week after the discount)', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-english-bursary-for-asia#overview', 'https://search.studyaustralia.gov.au/scholarship/rmit-up-academic-english-bursary-for-asia/e23775d1b6c08ef32f6529c7f3b749e6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT UP Academic English Bursary for Asia') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT UP Academic English Bursary for Latin America, Spain and Türkiye', 'If you are a citizen of a Latin American country, Spain or Türkiye this bursary provides a tuition fee discount on your Academic English course.', 'In order to qualify for this scholarship you must:; be a citizen of Latin America countries, Spain or Türkiye; applying from Australia or overseas; enrol in an Academic English course at RMIT University Pathways (RMIT UP) commencing in 2026 or 2027; be a commencing RMIT UP student (including extending your program in Australia).', '35% of the total program fee for an Academic English course (you pay $355 per week after the discount); 40% of the total program fee for an Academic English course (you pay $339 per week after the discount)', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-english-bursary-for-latin-american-students#overview', 'https://search.studyaustralia.gov.au/scholarship/rmit-up-academic-english-bursary-for-latin-america-spain-and-turkiye/6011ba21b73e30f5349c92358cc8381e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT UP Academic English Bursary for Latin America, Spain and Türkiye') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT UP General English Bursary for Asia', 'If you are a citizen of Japan, South Korea, Taiwan or Thailand this bursary provides a tuition fee discount on your General English language course.', 'In order to qualify for this scholarship you must:; be citizen of Japan, South Korea, Taiwan or Thailand; be applying from Australia or overseas; enrol in a General English course at RMIT University Pathways (RMIT UP) commencing in 2026 or 2027 for 10 weeks or more; not be the recipient of any other English Language scholarship (including external scholarships); be a commencing RMIT UP student (including extending your course in Australia).', 'For 2026 commencement: 20% of the total fee in 2026 study period for the General English course., You pay $436 per week after the discount. For 2027 commencement: 20% of the total fee in 2027 study period for the General English course., You pay $452', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-general-english-bursary-for-asia', 'https://search.studyaustralia.gov.au/scholarship/rmit-up-general-english-bursary-for-asia/3ed9fa68865a1b3041c913ade5d2c8ae', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT UP General English Bursary for Asia') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT UP General English Bursary for Latin America, Europe and Türkiye', 'If you are a citizen of a Latin American country, the European Union (EU) or Türkiye, this bursary provides a tuition fee discount on your General English language course.', 'In order to qualify for this scholarship you must:; be a citizen of Latin America countries, the EU or Türkiye; applying from Australia or overseas; enrol in a General English course at RMIT University Pathways (RMIT UP) commencing in 2026 or 2027; be a commencing RMIT UP student (including extending your course in Australia).', '40% of the total course fee', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-general-english-bursary-latin-america-eu-turkey#overview', 'https://search.studyaustralia.gov.au/scholarship/rmit-up-general-english-bursary-for-latin-america-europe-and-turkiye/b21d4d74998ae78f626de5efedba8ff3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT UP General English Bursary for Latin America, Europe and Türkiye') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT UP IELTS Preparation Bursary for Asia', 'If you are a citizen of Japan, South Korea, Taiwan or Thailand this bursary provides a tuition fee discount on your IELTS Preparation course.', 'In order to qualify for this scholarship you must:; be citizen of Japan, South Korea, Taiwan or Thailand; be applying from Australia or overseas; enrol in an IELTS Preparation course at RMIT University Pathways (RMIT UP) commencing in 2026 or 2027 for 10 weeks or more; not be the recipient of any other English Language scholarship (including external scholarships); be a commencing RMIT UP student (including extending your course in Australia).', '20% of the total course fee', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-ielts-preparation-bursary-for-asia', 'https://search.studyaustralia.gov.au/scholarship/rmit-up-ielts-preparation-bursary-for-asia/643e49136cbf30d23ef41c1dc83ba85b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT UP IELTS Preparation Bursary for Asia') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT UP IELTS Preparation Bursary for Latin America, Europe and Türkiye', 'If you are a citizen of a Latin American country, the European Union (EU) or Türkiye, this bursary provides a tuition fee discount on your IELTS Preparation course.', 'In order to qualify for this scholarship you must:; be a citizen of Latin America countries, the EU or Türkiye; applying from Australia or overseas; enrol in an IELTS Preparation course at RMIT University Pathways (RMIT UP) commencing in 2026 or 2027; be a commencing RMIT UP student (including extending your program in Australia).', '40% of the total course fee', 'Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-ielts-preparation-bursary-latin-america-eu-turkey', 'https://search.studyaustralia.gov.au/scholarship/rmit-up-ielts-preparation-bursary-for-latin-america-europe-and-turkiye/6180b3b9f9e67cfc668a287c92bade13', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT UP IELTS Preparation Bursary for Latin America, Europe and Türkiye') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT University Top-up Scholarship for Vietnam Government (Project 89)', 'This top-up scholarship program is available to talented Vietnamese students aims to address Vietnam\'s future industry and workforce needs, prioritising key research areas such as digital technologies, physics, biotechnologies and energy & environment.', 'In order to qualify for this scholarship you must:; be a citizen of Vietnam; have an offer for a PhD program at RMIT; be nominated to receive the Vietnam government scholarship (Project 89); commence full-time enrolment as an onshore international student at RMIT in Melbourne', 'a tuition fee scholarship of up to $25,000 USD; a stipend scholarship of $1,120 USD per month; an international return airfare and travel allowances; Overseas Student Health Cover (OSHC) for the time spent in Australia (up to $1,000 USD per year).', 'Postgraduate', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/vietnam-government-project-89-rmit-scholarship#overview', 'https://search.studyaustralia.gov.au/scholarship/rmit-university-top-up-scholarship-for-vietnam-government-project-89/a94967c86db3e1c7d38995242b6601e1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT University Top-up Scholarship for Vietnam Government (Project 89)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'RMIT Vietnam Alumni Postgraduate Scholarship', 'This scholarship is awarded to RMIT Vietnam alumni who will commence Master by Coursework program at RMIT Australia.', 'In order to qualify for this scholarship you must:; be alumni who completed a degree at an RMIT Vietnam campus. This can include:; an undergraduate degree or postgraduate degree (including those who undertake exchange for up to 1 year in RMIT Melbourne campuses); packaged RMIT Vietnam Undergraduate and RMIT Melbourne Postgraduate offer holders; have an offer letter and enrol in one of Masters by Coursework program at RMIT Australia.', '10% tuition fee reduction for the program duration outlined on your offer letter.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-vietnam-alumni-postgraduate-scholarship#overview', 'https://search.studyaustralia.gov.au/scholarship/rmit-vietnam-alumni-postgraduate-scholarship/f932be51645d920b03c37898ca03674b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT Vietnam Alumni Postgraduate Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Sallie Mae private student loans', 'Sallie Mae Student Loans can be used for tuition fees and material fees associated with your course.', 'The availability of the Sallie Mae loan is dependant on the course, campus and study load you select.', 'The loan amount you can apply for is capped by the ‘cost of attendance’, which is calculated by RMIT. The cost of attendance includes tuition fees and living expenses for an academic year. The loan amount is distributed in two equal payments, paid ou', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/us-financial-aid', 'https://search.studyaustralia.gov.au/scholarship/sallie-mae-private-student-loans/7154dff7fe8d896ddd5014841222a498', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Sallie Mae private student loans') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'School of Art Honours Travelling Grant', 'For art honours students who can demonstrate outstanding academic achievement; worth up to $4,000.', 'To be eligible for this grant you must:; be enrolled full-time in Semester 1 and 2 in 2026, in either the:; Bachelor of Arts (Fine Art) (Honours) (BH052); Bachelor of Arts (Photography) (Honours) (BH125); have achieved high distinction or distinction grades during Semester 1 2026; be undertaking travel related to your art/studio practice; submit your own original art works with your application', 'Up to AUD $4000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/coursework/school-art-travel', 'https://search.studyaustralia.gov.au/scholarship/school-of-art-honours-travelling-grant/1014804555fd213fd8719f8ab5092156', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'School of Art Honours Travelling Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'School of Education Academic Merit Scholarship for China', 'This scholarship supports outstanding students from China to pursue their academic goals in education or teaching discipline at RMIT University in Melbourne, Australia.', 'In order to qualify for this scholarship you must:; be a citizen of the People’s Republic of China (including Hong Kong SAR and Macau SAR); be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; achieve Australian equivalent grade GPA of 2.5 or 70% average or ATAR 75 in your qualifying qualification at the time of application; hold a full or conditional offer letter in one of the eligible programs: Bachelor of Education, Master of Teaching Practice (Primary Education), Master of Teaching Practice (Secondary Education); not be an existing RMIT University student studying one of the eligible programs.', 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible program(s) as outlined in your offer letter.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.rmit.edu.au/scholarships/international-scholarships/school-of-education-academic-merit-scholarship#overview', 'https://search.studyaustralia.gov.au/scholarship/school-of-education-academic-merit-scholarship-for-china/582d3047521e1078e71bb993a1623764', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'School of Education Academic Merit Scholarship for China') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 VU Sydney & Brisbane Global Diversity Scholarship', 'The 2026 VU Sydney and VU Brisbane Diversity Scholarship provides an additional 10% tuition fee reduction for students enrolling in our undergraduate, postgraduate, and higher education diploma programs in IT and Business. This 10% reduction is offered on top of the 2026 VU Sydney and Brisbane International Scholarship, which provides a 22.5% tuition fee discount. This scholarship is available to international students (both offshore and onshore) from designated diverse regions who commence their studies at VU Sydney or VU Brisbane in 2026.', 'The scholarship is available all international students commencing an undergraduate or postgraduate courses (including ELSIS EAP packages) at VU Sydney or VU Brisbane who is a citizen of one of the following regions/ countries.', '10% reduction of the course tuition fee the duration of the course. (Applied in addition to the 22.5% VU Sydney and Brisbane 2026 International Scholarship)', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', 'https://search.studyaustralia.gov.au/scholarship/2026-vu-sydney-brisbane-global-diversity-scholarship/b7fd495dbbf2ea0f5f15159d3f66ae7f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 VU Sydney & Brisbane Global Diversity Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australia Awards Scholarships', 'Australia Awards scholarships are long-term development awards, offered by the Australian Government and administered by the Department of Foreign Affairs and Trade (DFAT). They aim to contribute to the long-term development needs of Australia\'s partner countries.', 'Citizen of a participating country, all study levels, Please Contact Victoria University for more information.', 'Tuition fees, living allowance, Overseas Student Health Cover and academic support.', 'Undergraduate / VET', NULL, 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarships/19bf9630a38d6462cbd0b9a888376bef', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Early Childhood Education International Scholarship (2025)', 'The 2025 Early Childhood Education International Scholarship supports new international students who plan to commence an Early Childhood Education course in 2025. \r\n\r\nDo not miss this incredible opportunity to get a world-class qualification from a globally ranked university!', 'All new international students commencing a course in Early Childhood Education at VU Sydney or Brisbane in 2025 are eligible for the scholarship.', '-Graduate Diploma in Early Childhood Education (EGEC): 20% tuition fee reduction for the entire standard duration of eligible courses (calculated from the date of commencement to the course end date in the letter of offer). – Only applicable for Febr', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', 'https://search.studyaustralia.gov.au/scholarship/early-childhood-education-international-scholarship-2025/58c7f915169bf8c2bf1f1aa70fbf0c7b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Early Childhood Education International Scholarship (2025)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'STEM Accommodation Scholarship', 'Enjoy a stress-free start to your studies and save up to $15,500 with the unique STEM Accommodation Scholarship at Victoria University (VU).  Our exciting merit-based scholarship offers eligible international students free accommodation at UniLodge Victoria University for up to your entire first year of study. Scholarships will be awarded to select offshore international applicants for science, engineering and information technology degrees offered at VU Melbourne, particularly at our Footscray Park Campus, the main hub of our STEM-related courses. Limited scholarships are available for the July and September intakes in 2025, as well as February 2026. Eligibility is assessed on merit, based on previous academic results. With scholarships awarded on a first-come, first-served basis to eligible students, apply now for the best chance of success!', 'In order to be eligible for this scholarship, you must be an international student applying to VU from outside Australia and meet the entry requirements for one of the following STEM-related course:; Bachelor of Architectural Design; Bachelor of Biomedical Science; Bachelor of Biomedical and Exercise Science; Bachelor of Construction Management (Honours); Bachelor of Cyber Security; Bachelor of Data Science; Bachelor of Dermal Sciences; Bachelor of Information Technology; Bachelor of Information Technology (Professional); Bachelor of Engineering (Honours) (Civil Engineering); Bachelor of Engineering (Honours) (Electrical and Electronic Engineering); Bachelor of Engineering (Honours) (Mechanical Engineering); Bachelor of Exercise Science (Clinical Practice); Bachelor of Exercise Science (Sport Practice); Bachelor of Health Science; Bachelor of Sport Science; Bachelor of Sport Science (Human Movement) / Bachelor of Sport Management; Bachelor of Sport Science (Human Movement) / Bachelor of Psychological Studies; Master of Applied Information Technology; Master of Clinical Exercise Science and Rehabilitation; Master of Construction Management; Master of Project Management; Priority will be given to applicants with a strong academic background. Limited scholarships are available for Semester 2, Block 1 (July), 2025, Semester 2, Block 3 (September), 2025, and Semester 1, Block 1 (February), 2026, so apply as soon as you can; We strongly encourage applications from female students as part of our commitment to closing the gender gap in STEM. Please note: you must be over 18 years old when you start your VU studies in order to be eligible for this scholarship.', 'Successful undergraduate applicants will receive one year (52 weeks) of free accommodation at UniLodge VU, valued at $15,548. / Successful postgraduate applicants will receive six months (26 weeks) of free accommodation at UniLodge VU, valued at $8,5', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/stem-accommodation-scholarship/0748f0863d6b0ae158cf0aee70028610', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'STEM Accommodation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'VU Block Model International Scholarship', 'At Victoria University (VU), were committed to supporting your success. Our unique VU Block Model® International Scholarship offers all eligible international students up to 30% off tuition fees for the entire first year. Study well and youll have the chance to keep or increase the scholarship for the full duration of your course. VU is a world-class university, renowned for our inclusive environment, industry connections and innovative approach to education. Our award-winning VU Block Model teaching method will allow you to achieve your best, studying one or two subjects at a time in small, interactive classes.', 'New international students commencing a foundation, higher education diploma, undergraduate or postgraduate (coursework) course with VU Melbourne in 2025 are eligible for the scholarship. You must also meet the course entry requirements. English courses, VET and Research courses are not eligible for this scholarship. Sponsored students are not eligible for the scholarship.To be eligible to continue receiving the scholarship in subsequent years, you will need to complete 96 credit points each year and achieve the following WAM:50% WAM: 10% scholarship70% WAM: 20% scholarship80% WAM: 30% scholarshipThe value of the VU Block Model® International Scholarship will vary for students in certain circumstances. Please see the Eligibility Exceptions section below for further information', 'Up to 30% off your first year tuition fees – based on merit. Study well and youll have the chance to keep or increase the scholarship for the full duration of your course.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships/vu-block-model-international-scholarship', 'https://search.studyaustralia.gov.au/scholarship/vu-block-model-international-scholarship/f9b97fcda6a91a6a47fa7331a978ab5c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'VU Block Model International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'VU Global Research Scholarship', 'At Victoria University (VU), we’re committed to empowering the next generation of research leaders. Our exciting new VU Global Research Scholarship offers eligible international students 20% off tuition fees for the entire duration of a masters by research degree. With state-of-the-art facilities and an outstanding research profile, VU is the ideal place to commence your research career. You’ll benefit from expert supervision, comprehensive support and a vibrant academic community. Our world-class researchers are proud of the positive impact their work has locally, nationally and globally. Choose from our tailored masters degrees, designed for students with different levels of research experience, and join our welcoming team to achieve your academic ambitions.', 'Please contact Victoria University for more information about Eligibility Criteria.', 'The VU Global Research Scholarship is valued at 20% off tuition fees for the entire duration of your masters by research degree at Victoria University.', 'Postgraduate', NULL, 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/vu-global-research-scholarship/b854afc113728b62f9328bf623d08b1f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'VU Global Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'VU Sydney & Brisbane 2026 International Scholarship', 'The VU Sydney & Brisbane 2026 International Scholarship provides students with up to a 22.5% reduction in tuition fees. Students commencing our undergraduate, postgraduate and higher education diploma programs are eligible for this scholarship. The Scholarship is open to all international onshore and offshore students who are commencing with VU Sydney and Brisbane in 2026 and who meet the entry requirements.', 'All new students commencing an undergraduate or postgraduate (coursework) course (including ELSIS EAP packages) with VU Sydney in 2025 are eligible. Please refer to terms and conditions below.', '22.5% off the course tuition fees for the full course duration.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', 'https://search.studyaustralia.gov.au/scholarship/vu-sydney-brisbane-2026-international-scholarship/c42394de7a9075a6e908163f63c0e469', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'VU Sydney & Brisbane 2026 International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alumni 10% Fee Tuition Discount', 'Ready to return to Murdoch to achieve your postgraduate degree? As an alumnus you\'re an important part of our community, so to help support your study goals we\'re offering a 10% reduction in postgraduate fees on eligible courses.', 'Please Contact Murdoch University for more information.', '10% tuition fee deduction', 'Postgraduate', NULL, 'https://www.murdoch.edu.au/study/scholarship/alumni-10-fee-tuition-discount', 'https://search.studyaustralia.gov.au/scholarship/alumni-10-fee-tuition-discount/81c9da54a7b3d00892101f5130e774c5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alumni 10% Fee Tuition Discount') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alumni 25% Fee Tuition Discount', 'Have you recently joined our alumni community and are ready to start postgraduate study? To help support your goals, we’re offering a 25% reduction in postgraduate fees if you’ve finished your undergraduate or Masters level degree in the past 12 months and are transitioning into an eligible postgraduate course (excludes Honours) in the next available teaching period.​', 'Please Contact Murdoch University for more information.', '25% tuition fee deduction', 'Postgraduate', NULL, 'https://www.murdoch.edu.au/study/scholarship/alumni-25-fee-tuition-discount', 'https://search.studyaustralia.gov.au/scholarship/alumni-25-fee-tuition-discount/73716f1cba8becfb38dd6c2b9bcba70f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alumni 25% Fee Tuition Discount') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Futures Scholarship - 2026', 'Murdoch is offering a 25% fee reduction scholarship for International students enrolled in eligible courses commencing in 2026.', 'You are eligible to receive this scholarship if you meet all the following requirements:; you are an international, full-fee-paying student.; you are starting studies at one of Murdoch’s Western Australian campuses in 2026.; you are starting studies for an eligible Murdoch coursework degree set out below.; you are not receiving any other Murdoch scholarship.; you are not subject to any of the exceptions set out below.', '25% tuition fee reduction', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.murdoch.edu.au/study/scholarship/international-futures-scholarship---2026', 'https://search.studyaustralia.gov.au/scholarship/international-futures-scholarship-2026/aa13fbdff8ba191c52a9893bffaebb18', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Futures Scholarship - 2026') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Futures Scholarship - 2027', 'Murdoch is offering a 20% fee reduction scholarship for International students enrolled in eligible courses commencing in 2027.', 'You are eligible to receive this scholarship if you meet all the following requirements:; you are an international, full-fee-paying student.; you are starting studies at one of Murdoch’s Western Australian campuses in 2027.; you are starting studies for an eligible Murdoch coursework degree set out below.; you are not receiving any other Murdoch scholarship.; you are not subject to any of the exceptions set out below.', '20% tuition fee reduction', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.murdoch.edu.au/study/scholarship/international-futures-scholarship---2027-new', 'https://search.studyaustralia.gov.au/scholarship/international-futures-scholarship-2027/5f61e9050bc7aa135151004a939675fb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Futures Scholarship - 2027') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Welcome Scholarship 2026', 'Murdoch is offering a 20% fee reduction scholarship for international students from eligible countries, commencing in 2026.', 'You are eligible to receive this scholarship if you meet all the following requirements:; you are an international, full fee paying student; you are starting studies at one of Murdoch\'s Western Australian campuses in 2026', '20% tuition fee reduction', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.murdoch.edu.au/study/scholarship/international-welcome-scholarship-2026', 'https://search.studyaustralia.gov.au/scholarship/international-welcome-scholarship-2026/7efecf581c78848d030015416d4aade3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Welcome Scholarship 2026') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Welcome Scholarship 2027', 'Murdoch is offering a 15% fee reduction scholarship for international students from eligible countries, commencing in 2027.', 'You are eligible to receive this scholarship if you meet all the following requirements:; you are an international, full fee paying student; you are starting studies at one of Murdoch\'s Western Australian campuses in 2027; you are starting studies for an eligible Murdoch coursework degree set out below; you are a citizen of one of the eligible countries set out below; you are not receiving any other Murdoch scholarship; you are not subject to any of the exceptions set out below.', '15% tuition fee reduction', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.murdoch.edu.au/study/scholarship/international-welcome-scholarship-2027-new', 'https://search.studyaustralia.gov.au/scholarship/international-welcome-scholarship-2027/7a50b1523de35ff524c0017580ed2686', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Welcome Scholarship 2027') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Welcome Scholarship 2028', 'Murdoch is offering a 15% fee reduction scholarship for international students from eligible countries, commencing in 2028.', 'You are eligible to receive this scholarship if you meet all the following requirements:; you are an international, full fee paying student; you are starting studies at one of Murdoch\'s Western Australian campuses in 2028; you are starting studies for an eligible Murdoch coursework degree set out below; you are a citizen of one of the eligible countries set out below; you are not receiving any other Murdoch scholarship.', '15% tuition fee reduction', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.murdoch.edu.au/study/scholarship/international-welcome-scholarship-2028-new', 'https://search.studyaustralia.gov.au/scholarship/international-welcome-scholarship-2028/7ae57c2ee4893b4ca4b7f21f88cd76e9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Welcome Scholarship 2028') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Len Cullen Veterinary Anaesthesia 2027 Award', 'The Award primarily supports travel costs to attend a conference or meeting where papers and/or seminars relevant to veterinary anaesthesia and / or analgesia are presented, which ultimately, will be helpful for examination preparation.', 'Must be a resident or registrar employed by Murdoch University learning in the subject disciplines of veterinary Anaesthesia and / or analgesia.; Must travel in the following academic year; Must not have been in receipt of this award previously', 'Up to AUD $2500', 'Postgraduate', NULL, 'https://www.murdoch.edu.au/study/scholarship/len-cullen-veterinary-anaesthesia-2027-award', 'https://search.studyaustralia.gov.au/scholarship/len-cullen-veterinary-anaesthesia-2027-award/fa4f6edaea96d5798ef91f7f5a747937', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Len Cullen Veterinary Anaesthesia 2027 Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Murdoch University 30% Scholarship for Mauritian Laureate Additional Scholarship Scheme', 'Murdoch is offering a 30% fee reduction scholarship for international students who have been awarded the Mauritian Laureate Additional Scholarship Scheme by the Mauritian Ministry of Education, Tertiary Education, Science and Technology.', 'You are eligible to receive the above scholarship if you meet all the following requirements:; you are an international, full-fee-paying student.; you are starting studies at one of Murdoch’s Western Australian campuses from 2025 onwards.; you are starting studies for an eligible Murdoch coursework degree set out below.; you have been awarded scholarship under the Mauritian Laureate Additional Scholarship Scheme by the Mauritian Ministry of Education, Tertiary Education, Science and Technology.; you are not a fully sponsored student by the Government of Mauritius - students who receive full sponsorship covering all expenses (university tuition fees, flights, accommodation and living allowance).; you are not receiving any other Murdoch scholarship.', '30% discount', 'Undergraduate / VET', NULL, 'https://www.murdoch.edu.au/study/scholarship/murdoch-university-30--scholarship-for-mauritian-laureate-additional-scholarship-scheme', 'https://search.studyaustralia.gov.au/scholarship/murdoch-university-30-scholarship-for-mauritian-laureate-additional-scholarship-scheme/73a7449228b45c1829c3ed51ab2294b8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Murdoch University 30% Scholarship for Mauritian Laureate Additional Scholarship Scheme') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research Training Program Stipends (International students)', 'The Graduate Research Office is pleased to announce that the 2025 scholarship round opens in July 2025. Scholarships are awarded on academic merit, research experience and/or potential.', 'Applicants must be full time and meet the admission requirements of the required HDR degree to be eligible (first or upper second-class Honours degree, Masters degree by research, or equivalent).; Applicants must possess a First Class Honours degree, H2A (or equivalent) or a Masters with a significant thesis component.', 'AUD $37000/year', 'Postgraduate', NULL, 'https://www.murdoch.edu.au/study/scholarship/research-training-program-stipends-(international-students)', 'https://search.studyaustralia.gov.au/scholarship/research-training-program-stipends-international-students/2fafcec05ab9fbe87b09e7524e313fe9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research Training Program Stipends (International students)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'TNE Transfer Scholarship 2026', 'Murdoch is offering a 25% fee reduction scholarship for TNE Students following your transfer from Murdoch Singapore, Murdoch Dubai or Murdoch Malaysia to one of Murdoch’s Western Australian campuses (Local Campus), and commencing studies at the Local Campus.', 'You are eligible to receive this scholarship if you meet all the following requirements:; you are a student transferring your studies from Murdoch Singapore, Murdoch Dubai or Murdoch Malaysia to one of Murdoch’s Western Australian campuses (Local Campus), and commencing studies at the Local Campus in 2026; you will be studying an eligible course at the Local Campus; you do not fall within any of the exclusions', '25% tuition fee reduction', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.murdoch.edu.au/study/scholarship/tne-transfer-scholarship-2026', 'https://search.studyaustralia.gov.au/scholarship/tne-transfer-scholarship-2026/1ece19983305389bc9315c57bd202c01', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00125J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'TNE Transfer Scholarship 2026') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Buru Energy Scholarship for Women in Petroleum Geoscience', 'Buru Energy Limited have donated the sum funds to The University of Western Australia (the University) to provide scholarships to support female students undertaking research and studies in petroleum geoscience.', 'female; enrolled or eligible to enrol in either; an honours course in geology or; a masters by thesis and coursework degree course in geoscience or petroleum geoscience and; undertaking research and studies in the field of petroleum geoscience.', 'Up to AUD $10000 — Value$10,000.00', 'Postgraduate, Undergraduate / VET', 'Sciences', 'https://www.uwa.edu.au/study/scholarship-listing/buru-energy-scholarship-for-women-in-petroleum-geoscience-f512241', 'https://search.studyaustralia.gov.au/scholarship/buru-energy-scholarship-for-women-in-petroleum-geoscience/9bd709079f0b3dcea5ba793fcfdd30cf', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Buru Energy Scholarship for Women in Petroleum Geoscience') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Friends of UWA Albany Verna Rowbotham Scholarship', 'Verna Rowbotham has bequeathed funds to The University of Australia (the University) to provide a scholarship to assist and encourage a high-achieving student to continue their undergraduate studies with a major in Environmental Science, Conservation Biology, Marine Science or Geographical Sciences at the UWA Albany campus. Verna, a UWA alumna, maintained a lifelong association with UWA, firstly through the work of her father Professor Alexander Ross, the founding professor in physics and mathematics, and then through her own support and life membership of the Friends of the UWA Albany Centre.', 'Please Contact The University of Western Australia for more information about Eligibilty.', 'Up to AUD $5000 — Value$5,000.00', 'Undergraduate / VET', 'Environmental studies, Sciences', 'https://www.uwa.edu.au/study/scholarship-listing/friends-of-uwa-albany-verna-rowbotham-scholarship-f826601', 'https://search.studyaustralia.gov.au/scholarship/friends-of-uwa-albany-verna-rowbotham-scholarship/0aa91196685d53a7fe0f8b29065e7d26', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Friends of UWA Albany Verna Rowbotham Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Fully Funded Scholarship For a PhD Project in Integrative Geophysics', 'We are looking to recruit up to three PhD students through the recently awarded Industry Fellowship for the Integrative geophysics Under cover: getting images of the Unknown Unknown project, supported by the Australia Research Council, the University of Western Australia (UWA), the Geological Survey of Western Australia (GSWA), and the Commonwealth Scientific and Industrial Research Organisation (CSIRO). The goal of the project is to develop and extend new algorithms for integrating geophysical and geological data in undercover exploration scenarios at different scales, with applications to idealised and real-world data from Western Australia provided by GSWA. The methods to be investigated include geometrical (geophysical) inversion, trans-dimensional inversion, multi-physics integration, the integration of geophysical inversion with geological modelling.', 'Skills in geophysics/physics, and/or numerical geology, and capability to code are essential.; Willingness to learn is a requirement. The capability to work in a team and independently and to take initiative will be appreciated.', 'AUD $37000/year', 'Postgraduate', NULL, 'https://researchdegrees.uwa.edu.au/scholarships/17z09z/fully-funded-scholarship-for-a-phd-project-in-integrative-geophysics', 'https://search.studyaustralia.gov.au/scholarship/fully-funded-scholarship-for-a-phd-project-in-integrative-geophysics/ef872235d94264f938c75a0415f71749', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Fully Funded Scholarship For a PhD Project in Integrative Geophysics') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Global Excellence Scholarship', 'The Global Excellence Scholarship is an annual tuition fee discount for the normal full-time duration of the awardee’s course as specified in their letter of offer. The value of the scholarship is determined by the applicant’s equivalent Australian Tertiary Admission Rank (ATAR) or UWA weighted average mark (WAM).', 'Please contact The University of Western Australia (UWA) for further information.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.uwa.edu.au/study/international-students/fees-and-scholarships/uwa-funded-scholarships/global-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/global-excellence-scholarship/fe653755ce0d2d5075b82783823e953f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Global Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'High Precision Rotation Sensor', 'Ground rotation sensors have wide applications, such as precision instrumentation, environment monitoring, and rotational seismology, as well as for improving the sensitivities of gravitation wave detectors.  Currently available rotation sensors have issues of either low sensitivities or too fragile/too large to be used in the field. At UWA we are developing a compact, and robust with a high sensitivity rotation sensor using many innovative technologies.  This PhD project is to build, characterize and field test the rotation sensor.', 'Honours or Master\'s degree in Mechanical Engineering or Experimental Physics.; Meet the UWA PhD entrance requirements with adequate English.; Have a high academic achievement in the coursework.; Demonstrated research capabilities through high quality research thesis and/or published peer-reviewed journal papers.', 'Stipend scholarship / 	Tuition fee scholarship', 'Postgraduate', NULL, 'https://researchdegrees.uwa.edu.au/scholarships/17z0x3/high-precision-rotation-sensor', 'https://search.studyaustralia.gov.au/scholarship/high-precision-rotation-sensor/1a4e56e45303955b0e9e76ed04fd63b9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'High Precision Rotation Sensor') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Industry PhD Scholarship - Digital Finance CRC', 'Are you ready to be at the forefront of the next big leap in global finance? Digital finance is changing the game by using cutting-edge blockchain technology and digital distributed ledgers to turn real-world assets into secure, tradeable digital tokens. This breakthrough is opening new markets, driving efficiency, reducing costs and creating a more inclusive financial system worldwide. Our industry PhD scholarships are now open to students passionate about researching in the rapidly evolving world of digital finance. If youre ready to make an impact, we want to hear from you.', 'Candidates interested in researching the technological, financial and/or legal innovations required to enable the global transition to financial markets 3.0.', 'AUD $70000/year — Other allowance : AUD $10,000 total / 	Research allowance: 	AUD $4,500', 'Postgraduate', NULL, 'https://researchdegrees.uwa.edu.au/scholarships/1905zx/industry-phd-scholarship-digital-finance-crc', 'https://search.studyaustralia.gov.au/scholarship/industry-phd-scholarship-digital-finance-crc/da6645736feee784b12d1506ce71d184', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Industry PhD Scholarship - Digital Finance CRC') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Industry PhD Top-up Scholarship - Digital Finance CRC', 'Digital finance is a technological toolkit incorporating blockchain technology and other digital distributed ledgers that transforms real-world assets into digital tokens that can be traded seamlessly and securely across borders, time zones, asset classes and individuals. It will open new markets, and make existing markets more functional, less costly and more efficient, and has the potential to create a more inclusive and fair financial system.', 'Our top-up scholarships are available to PhD students researching any of the following disciplines:; applied finance (eg Automated Market Makers, pricing, estimating gains from tokenisation); law (eg compliance, regulation, legislation, policy implications of the digital finance transformation and smart contracts); computer and data science (eg blockchain, digital distributed ledgers, market manipulation and fraud detection, security, data management, machine learning, LLM).', 'AUD $15000/year', 'Postgraduate', NULL, 'https://researchdegrees.uwa.edu.au/scholarships/190601/industry-phd-top-up-scholarship-digital-finance-crc', 'https://search.studyaustralia.gov.au/scholarship/industry-phd-top-up-scholarship-digital-finance-crc/aabb27d636dd0b3323387b8432f451e0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Industry PhD Top-up Scholarship - Digital Finance CRC') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Award', 'https://www.uwa.edu.au/study/international-students/international-student-award', 'Please contact The University of Western Australia (UWA) for further information.', 'Up to AUD $20000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.uwa.edu.au/study/scholarship-listing/uwa-international-student-award-f221201', 'https://search.studyaustralia.gov.au/scholarship/international-student-award/75e0695bafd19056a81934b5cf38b71a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UWA ASEAN SCHOLARSHIP', 'The University of Western Australia (\'the University\') provides fee discount scholarships to encourage and assist students from eligible countries to pursue an undergraduate or postgraduate qualification at the University.', 'To be eligible to be considered for the scholarship, candidates must-; (a) be an international student from: Brunei Darussalam, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Vietnam, Timor-Leste; have applied to commence an eligible postgraduate degree;  have not discontinued an equivalent level course, with an immediate break in enrolment after discontinuation.', 'See scholarship details', 'Postgraduate', NULL, 'https://www.uwa.edu.au/study/scholarship-listing/uwa-asean-scholarship-f191752', 'https://search.studyaustralia.gov.au/scholarship/uwa-asean-scholarship/d1a35831d953a9741e903d83c71777d9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UWA ASEAN SCHOLARSHIP') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UWA GLOBAL EXCELLENCE SCHOLARSHIP', 'The University of Western Australia (\'the University\') provides a fee discount scholarship to encourage and assist eligible high-achieving international students to commence and pursue an undergraduate or postgraduate qualification at the University.', 'To be eligible to be considered for the scholarship, applicants must; be an International Student; have received an offer for an eligible undergraduate or postgraduate course at The University of Western Australia; have achieved an equivalent ATAR of at least 85 if commencing undergraduate study or have achieved an equivalent WAM of at least 65 if commencing postgraduate study; have not discontinued an equivalent level course, with an immediate break in enrolment after discontinuation.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.uwa.edu.au/study/scholarship-listing/uwa-global-excellence-scholarship-f1917561', 'https://search.studyaustralia.gov.au/scholarship/uwa-global-excellence-scholarship/0753d2c03240f997e696e8d16a2eeea5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UWA GLOBAL EXCELLENCE SCHOLARSHIP') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UWA SINGAPORE POLYTECHNIC SCHOLARSHIP', 'The University of Western Australia (\'the University\') provides fee discount scholarship to encourage and assist eligible high-achieving international students from Singapore Polytechnic institutions to commence and pursue an undergraduate qualification at the University.', 'To be eligible to be considered for the scholarship, candidates must; Be an international student; Be commencing one of the following courses at UWA: Bachelor of Business, Bachelor of Commerce, Bachelor of Engineering (Honours), Bachelor of Biomedical Science, Bachelor of Science; have not commenced or discontinued an equivalent level course at the University; have completed a Polytechnic Diploma program at one of the following polytechnic institutions in Singapore: Nanyang Polytechnic, Ngee Ann Polytechnic, Republic Polytechnic, Singapore Polytechnic, Temasek Polytechnic', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.uwa.edu.au/study/scholarship-listing/uwa-singapore-polytechnic-scholarship-f269491', 'https://search.studyaustralia.gov.au/scholarship/uwa-singapore-polytechnic-scholarship/b92ed1cb45b34926e8026e58d175d720', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00126G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UWA SINGAPORE POLYTECHNIC SCHOLARSHIP') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Senior School Bursary', NULL, 'For entry into Years 10 and 11. Awarded for a commitment to studies and a positive involvement in co-curricular activities and community service.', 'Half or full remission of tuition fees for the duration of enrolment.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/senior-school-bursary/11563c88a5180f164be7e0f5b405a602', 'https://search.studyaustralia.gov.au/scholarship/senior-school-bursary/11563c88a5180f164be7e0f5b405a602', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00131M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Senior School Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Year 7 Academic Excellence Scholarship', NULL, 'For entry into Year 7. Awarded for academic excellence. Based on examination results.', 'Partial or full remission of tuition fees for the duration of the enrolment.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/year-7-academic-excellence-scholarship/8ca9371a1ae580e5846cad90348e2dd3', 'https://search.studyaustralia.gov.au/scholarship/year-7-academic-excellence-scholarship/8ca9371a1ae580e5846cad90348e2dd3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00131M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Year 7 Academic Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', NULL, 'For entry into Years 4 to 10. Selection is based on academic merit and takes into account: Completion of Edutest testing held at the School (see School website for dates); Review of school reports', 'Partial remission of tuition fees. Tenure and number awarded varies.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/629bf0e99c12d74bfed4a960b1d29358', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/629bf0e99c12d74bfed4a960b1d29358', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00132K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence Scholarship', NULL, 'For entry into Years 7 to 10. Selection is based on all-round talent and takes into account some or all of the following:\r\nA combination of high academic, sporting, performing arts and community service achievements.', 'Partial remission of tuition fees. Tenure and number awarded varies.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship/13c9b23053d7203e026c5364c87b2151', 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship/13c9b23053d7203e026c5364c87b2151', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00132K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'St Andrew\'s Choir Scholarship', NULL, 'Applicants must meet the following criteria:\r\n A willingness to be a member of the St Andrew’s Choir\r\n; A willingness to be fully involved in the Choir from the beginning of Term 1 until Christmas Day each year.\r\n Selection is based on the following criteria:\r\nThe results of a 20-minute audition\r\n; A 40-minute music aptitude test\r\n; Ability to sight read; Previous music and school reports\r\n;Interview', '75% tuition fee remission', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/st-andrews-choir-scholarship/31217adb7572f67382a6c701beb09f12', 'https://search.studyaustralia.gov.au/scholarship/st-andrews-choir-scholarship/31217adb7572f67382a6c701beb09f12', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00132K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'St Andrew\'s Choir Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Mirams Scholarship', 'The Mirams Scholarship was established in the 1970s by Mary Ida Mirams in memory of her son, James Herbert Mirams, an Old Boy of the School, who tragically lost his life in World War One at the age of 25.\r\n\r\nThe Mirams Scholarship is awarded to an Old Boy who, after completing his secondary schooling at BGS, goes on to study an engineering degree at Melbourne University.', 'Applicants for this scholarship must be Old Boys of the School who are enrolled in an engineering degree at Melbourne University.', 'All scholarships are at the discretion of the Headmaster; this scholarship covers a percentage of the Melbourne University tuition fees and is awarded at the end of each year of study, usually two years.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/the-mirams-scholarship/7c7917ea6ef7decd36800b6c3b3f76c8', 'https://search.studyaustralia.gov.au/scholarship/the-mirams-scholarship/7c7917ea6ef7decd36800b6c3b3f76c8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00132K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Mirams Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', NULL, 'Available for entry into Year 7, 10 and 11.\r\nBased on scholarship exam results.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/582d10800651e6483e13b745e87417c2', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/582d10800651e6483e13b745e87417c2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00135G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
