INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarships (Primary)', 'Academic Scholarships based on performance on an examination, and following an interview with the relevant Head of Campus, will be awarded to begin at either Malvern Campus or Wheelers Hill Campus. Applications should be submitted online and a fee of $115 is required. The Primary examination will be held at Wheelers Hill Campus on Saturday 13 February, 2021. Caulfield Grammar School uses ACER scholarship tests.', 'Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter. Opening Date :Applications for entry in 2023 will open in early December 2021.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-primary/4f67754246bda847c7581f084cc1dcd7', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-primary/4f67754246bda847c7581f084cc1dcd7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarships (Primary)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarships - Wheelers Hill and Caulfield Campuses', 'Academic scholarships are based on performance on an examination, and following an interview, will be awarded to begin at either Caulfield Campus or Wheelers Hill Campus in Year 7 and Years 9 to 11. Applications should be submitted online and a fee of $115 is required.', 'For entry into Years 7, 9, 10 and 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-wheelers-hill-and-caulfield-campuses/b2e938955df7d67c2e3cc42c9d0525ba', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-wheelers-hill-and-caulfield-campuses/b2e938955df7d67c2e3cc42c9d0525ba', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarships - Wheelers Hill and Caulfield Campuses') LIMIT 1;
