INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Caulfield Grammarians\' Association Scholarship', 'The Caulfield Grammarians’ Association (CGA) offers Scholarships awarded to children of past students for entry into Year 7 and Years 9 – 11 at either Caulfield Campus or Wheelers Hill Campus. \r\n\r\nCGA scholarships are awarded through the General Excellence applications process. The Caulfield Grammarians’ Association is proud to be a strong supporter of the School’s Scholarship program which acknowledges the ongoing partnerships between past, current and future Grammarians.', 'For entry into Years 7, 9, 10, 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/caulfield-grammarians-association-scholarship/713245815016369ec3faa2e304348091', 'https://search.studyaustralia.gov.au/scholarship/caulfield-grammarians-association-scholarship/713245815016369ec3faa2e304348091', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Caulfield Grammarians\' Association Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Caulfield Grammarians\' Association Scholarships', 'The Caulfield Grammarians’ Association (CGA) offers Scholarships awarded to children of past students for entry into Year 7 and Years 9 – 11 at either Caulfield Campus or Wheelers Hill Campus. CGA scholarships are awarded through the General Excellence applications process. The Caulfield Grammarians’ Association is proud to be a strong supporter of the School’s Scholarship program which acknowledges the ongoing partnerships between past, current and future Grammarians.', 'For entry into Years 7, 9, 10, 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/caulfield-grammarians-association-scholarships/1126b214797e75f7c065e2ba97bbb320', 'https://search.studyaustralia.gov.au/scholarship/caulfield-grammarians-association-scholarships/1126b214797e75f7c065e2ba97bbb320', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Caulfield Grammarians\' Association Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Dance Scholarships', 'Dance Scholarships are available for entry into Year 10 or 11 at either Caulfield Campus or Wheelers Hill Campus.\r\n\r\nApplicants should demonstrate exceptional Dance Technique and Performance skills. Successful candidates will enjoy state-of-the-art facilities and be expected to be involved in two performances each year and also provide leadership within the field of Performing Arts.\r\n\r\nIn accepting a scholarship offer, students must complete VCE Dance Units 1/2 in Year 11 and Units 3/4 in Year 12 as part of their VCE Course.', 'For Years 10, 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/dance-scholarships/ca6a00921008b3f233db7a3a682399d4', 'https://search.studyaustralia.gov.au/scholarship/dance-scholarships/ca6a00921008b3f233db7a3a682399d4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Dance Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence Scholarships', 'General Excellence Scholarships will be awarded to begin at either Caulfield Campus or Wheelers Hill Campus in Year 7 and Years 9 – 11. Typically a 50 percent concession, General Excellence Scholarships offer part remission of tuition fees; offers will take into account parent’s financial means.These scholarships are awarded to students who are able to demonstrate excellence and achievement in the following fields: AcademicLeadership and ServiceThe Arts (Performing Arts and/or Visual Arts) Sport (students must be competing in teams at a State/National Level). Applicants will need to provide information on levels of achievement in each field and must demonstrate excellence in at least three fields. Scholarships are awarded following an interview with senior staff.', 'For Years 7, 9, 10, 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarships/d6cd424c87c5ec09f68bd638244e5bb1', 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarships/d6cd424c87c5ec09f68bd638244e5bb1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence Scholarships', 'General Excellence Scholarships will be awarded to begin at either Caulfield Campus or Wheelers Hill Campus in Year 7 and Years 9 – 11. Typically a 50 percent concession, General Excellence Scholarships offer part remission of tuition fees; offers will take into account parent’s financial means.These scholarships are awarded to students who are able to demonstrate excellence and achievement in the following fields: AcademicLeadership and ServiceThe Arts (Performing Arts and/or Visual Arts) Sport (students must be competing in teams at a State/National Level). Applicants will need to provide information on levels of achievement in each field and must demonstrate excellence in at least three fields. Scholarships are awarded following an interview with senior staff.', 'For entry into Years 7, 9, 10, 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarships/71c1f8c4f541a18e0992b1c6aa4fd5dc', 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarships/71c1f8c4f541a18e0992b1c6aa4fd5dc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music (Instrumental) Scholarships', 'An innovative program offers students excellent opportunities in solo and ensemble performance. Our School’s various bands, orchestras, ensembles and choirs perform at regular concerts and assemblies, eisteddfods, festivals and productions. Music auditions will commence in early February, and all applicants will be notified at the conclusion of the audition process. Results of Scholarships are confidential and are not released by the School. Please do not send copies of your child’s School Reports to Caulfield Grammar School. This information will be requested from short-listed candidates at the time of interview.', 'For entry into Year 7, 9, 10. Awarded for outstanding musical ability. Based on an audition and an interview. For Year 7 entry: AMEB Grade 8 Pianoforte, AMEB Grade 7 Violin, AMEB Grade 6 for other instruments. For Years 9 and 10 entry AMEB AMusA Pianoforte, AMEB Grade 8 Violin, AMEB Grade 7 for other instruments.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-scholarships/1650fd3443b78dd49d93fa1e9ab7f619', 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-scholarships/1650fd3443b78dd49d93fa1e9ab7f619', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music (Instrumental) Scholarships') LIMIT 1;
