INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Instrumental Scholarships (Primary)', 'For Year 5 in 2022, Music Scholarships are available to students who demonstrate outstanding musical ability to begin at Malvern Campus or Wheelers Hill Campus. All applications should be submitted online. Please do not send copies of your child’s School Reports to Caulfield Grammar School. This information will be requested from short-listed candidates at the time of interview. Auditions will commence in early February and all applicants will be notified at the conclusion of the audition process. Selections are based on the information contained in the application and will be arranged with short-listed applicants after the close of all applications.', 'For Year 5 entry: AMEB Grade 7 Pianoforte, AMEB Grade 6 Violin, AMEB Grade 5 for other instruments. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-scholarships-primary/98170b53834187c2f2c623bfe3b96eea', 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-scholarships-primary/98170b53834187c2f2c623bfe3b96eea', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Instrumental Scholarships (Primary)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Instrumental Scholarships (Primary)', 'For Year 5 in 2022, Music Scholarships are available to students who demonstrate outstanding musical ability to begin at Malvern Campus or Wheelers Hill Campus. All applications should be submitted online. Please do not send copies of your child’s School Reports to Caulfield Grammar School. This information will be requested from short-listed candidates at the time of interview.', 'For Year 5 entry: AMEB Grade 7 Pianoforte, AMEB Grade 6 Violin, AMEB Grade 5 for other instruments.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-scholarships-primary/868186e2eeee1c48fef694aa35177e12', 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-scholarships-primary/868186e2eeee1c48fef694aa35177e12', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Instrumental Scholarships (Primary)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Theatre Scholarships', 'Theatre Scholarships are available for entry into Year 10 or11 at either Caulfield Campus or Wheelers Hill Campus. Applicants should demonstrate exceptional performance skills.\r\n\r\nSuccessful candidates will enjoy state-of-the-art facilities and be expected to be involved in a minimum of two performances each year and also provide leadership within the field of Performing Arts.\r\n\r\nIn accepting a scholarship offer, students must complete VCE Theatre Units 1/2 in Year 11 and Units 3/4 in Year 12 as part of their VCE Course.', 'For entry into Years 10 and 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/theatre-scholarships/77f8236d5b6752a89b7c6cd88afaa2fb', 'https://search.studyaustralia.gov.au/scholarship/theatre-scholarships/77f8236d5b6752a89b7c6cd88afaa2fb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Theatre Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Theatre Scholarships', 'Theatre Scholarships are available for entry into Year 10 or11 at either Caulfield Campus or Wheelers Hill Campus. Applicants should demonstrate exceptional performance skills.\r\n\r\nSuccessful candidates will enjoy state-of-the-art facilities and be expected to be involved in a minimum of two performances each year and also provide leadership within the field of Performing Arts.\r\n\r\nIn accepting a scholarship offer, students must complete VCE Theatre Units 1/2 in Year 11 and Units 3/4 in Year 12 as part of their VCE Course.', 'For entry into Years 10 and 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/theatre-scholarships/4b678f776de5c688e2e0e08645c88c63', 'https://search.studyaustralia.gov.au/scholarship/theatre-scholarships/4b678f776de5c688e2e0e08645c88c63', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Theatre Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Visual Arts Scholarships', 'Visual Arts Scholarships are available for entry in Year 10 or 11 at either Caulfield Campus or Wheelers Hill Campus.\r\n\r\nSuccessful students will be expected to demonstrate outstanding abilities in both the practical and theoretical aspects of the Visual Arts, and be actively involved in the broader Visual Arts programs as a role model for others.\r\n\r\nIn accepting a scholarship offer, students must complete VCE Studies in Visual Arts at both Units 1/2 and Units 3/4 levels.', 'For entry into Years 10 and 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/visual-arts-scholarships/e173896c79ae1e3b241f011680fca741', 'https://search.studyaustralia.gov.au/scholarship/visual-arts-scholarships/e173896c79ae1e3b241f011680fca741', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Visual Arts Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Visual Arts Scholarships', 'Visual Arts Scholarships are available for entry in Year 10 or 11 at either Caulfield Campus or Wheelers Hill Campus.\r\n\r\nSuccessful students will be expected to demonstrate outstanding abilities in both the practical and theoretical aspects of the Visual Arts, and be actively involved in the broader Visual Arts programs as a role model for others.\r\n\r\nIn accepting a scholarship offer, students must complete VCE Studies in Visual Arts at both Units 1/2 and Units 3/4 levels.', 'For entry into Years 10 and 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/visual-arts-scholarships/62e40f946995b96c5dabf23b9e794836', 'https://search.studyaustralia.gov.au/scholarship/visual-arts-scholarships/62e40f946995b96c5dabf23b9e794836', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Visual Arts Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'W.S. Morcom Rural Boarding Scholarship at Caulfield Campus', 'W.S. Morcom Rural Boarding Scholarships will be awarded for entry in Years 9 to 11 at the Caulfield Campus.These scholarships will be awarded to students who are able to demonstrate achievement in several fields of endeavour who will therefore contribute strongly to the boarding community: Academic Leadership and Service, The Arts (Performing Arts and/or Visual Arts) Sport (students should be competing at a representative / regional / State / National level). In addition to part remission of tuition fees, these scholarships will provide some assistance to parents in meeting the cost associated with boarding. Applicants who have submitted an application for a General Excellence scholarship but are unsuccessful will have their applications considered for the W.S. Morcom scholarships. There is no need to complete a second application form.', 'For entry into Years 9, 10, 11 as boarders. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/ws-morcom-rural-boarding-scholarship-at-caulfield-campus/aa2dbacb1870803743cb95884ac43bbd', 'https://search.studyaustralia.gov.au/scholarship/ws-morcom-rural-boarding-scholarship-at-caulfield-campus/aa2dbacb1870803743cb95884ac43bbd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00136F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'W.S. Morcom Rural Boarding Scholarship at Caulfield Campus') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence Scholarship (Academic)', NULL, 'Scholarships for General Excellence (Academic) are offered to new and current students entering years 5, 7, 8 and 9 who demonstrate outstanding academic ability.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship-academic/16fb2090745a395387ebb5d7f312765c', 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship-academic/16fb2090745a395387ebb5d7f312765c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00138D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence Scholarship (Academic)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence Scholarship (Co-curricular)', NULL, 'Scholarships for General Excellence (Co-curricular) are offered to new and current students entering Years 7, 8 and 9 who demonstrate outstanding achievement, commitment and potential in one or more areas.\r\n\r\nScholarships are awarded on the basis of achievement as evidenced in an online application (including supporting documentation and optional video), the results of a scholarship examination and interview.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship-co-curricular/153eac840f346ec96c9dff078e873259', 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship-co-curricular/153eac840f346ec96c9dff078e873259', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00138D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence Scholarship (Co-curricular)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence Scholarship (Music)', NULL, 'Scholarships for General Excellence (Music) are offered to new and current students entering Years 5, 7, 8 and 9 who demonstrate outstanding musical ability and achievement in music (instrumental/choral) within and/or beyond the context of school.\r\n\r\nScholarships are awarded on the basis of an audition, an online application (including supporting documentation and optional video), the results of a scholarship examination and interview.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship-music/9a7ded410be7164a34f76b6048d740aa', 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship-music/9a7ded410be7164a34f76b6048d740aa', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00138D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence Scholarship (Music)') LIMIT 1;
