INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Kent Higher Education Bursary for International Students', 'A limited offering for international students who are enrolling into Kent’s higher education Bachelor degree courses. Students must have applied through authorised Kent Agents at both the Sydney and Melbourne campuses.', 'All Bursaries are awarded at the discretion of Kent to:; Applicants who undertake a full-time study load of a Kent undergraduate higher education \r\ndegree (subject to unit availability).; Applicants who enrol in cross institutional or non-awards units.; Applicants who come to Kent as direct applicants or applicants from approved Kent Agents.; Applicants who study on either the Sydney or Melbourne campuses, or via online class delivery.', 'Up to AUD $300 — The bursary awards applicants with a $300 per unit reduction in tuition fees for the first 24 units enrolled.', 'Postgraduate, Undergraduate / VET', NULL, 'https://kent.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/kent-higher-education-bursary-for-international-students/21dd025f1314512f7fb0dc70d001fbf1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00161E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Kent Higher Education Bursary for International Students') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Kent International Student Scholarship', 'A scholarship for international students who are commencing a full-time undergraduate Higher Education course. Students must have achieved sound academic standing and results in their previous studies.', 'Prospective international students from the following countries and regions are eligible to apply for the International Student Scholarship; Europe; New Zealand; North America (Canada, Caribbean, Central America, Mexico, United States of America); South America (Argentina, Bolivia, Brazil, Chile, Colombia, Ecuador, Falkland Islands (United Kingdom), French Guiana (France), Guyana, Paraguay, Peru, Suriname, Uruguay and Venezuela)', 'The scholarship is a 30% reduction in tuition fees for the duration of their course. Each scholarship application is assessed on a case-by-case basis with final selection by the Chief Executive Officer.', 'Postgraduate, Undergraduate / VET', NULL, 'https://kent.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/kent-international-student-scholarship/1af68f97f7ec9eb9e909875fa59a0189', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00161E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Kent International Student Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australia Awards', 'Prestigious international scholarships and fellowships funded by the Australian Government offering the next generation of global leaders an opportunity to undertake study, research and professional development and provides funding and contacts for International students and organisational representatives to study in Australia.', 'Please refer to the University of Canberra\'s website for details.', 'Various', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.canberra.edu.au/scholarship/australia-awards.html', 'https://search.studyaustralia.gov.au/scholarship/australia-awards/23aab1c6409712f4f42e5269c7be0933', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00212K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Jade Finance 2026 Academic Scholarship', 'Awarded to a student who demonstrates exceptional insight into the current Australian financial and economic environment', 'Please Contact University of Canberra for more information about Eligibility.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.canberra.edu.au/scholarship/jade-finance-2026-academic.html', 'https://search.studyaustralia.gov.au/scholarship/jade-finance-2026-academic-scholarship/1126e872863299453c534174e1159ae4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00212K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Jade Finance 2026 Academic Scholarship') LIMIT 1;
