INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UC Alumni Scholarships', 'Awarded to UC Alumni applying to study a course at UC, subject to meeting the UC and PG qualifying criteria.All applicants are assessed for a scholarship at the time of application to the course at UC. No further application is required. Scholarships are granted on a first-come-first-served basis until filled. Students are advised to accept the scholarship as soon as possible in order to avoid disappointment. Scholarships are limited and may be withdrawn if capacity is reached. The scholarship is valid only for the intake and course specified and will be confirmed once all conditions are met, your offer is accepted, and required payments are completed. The University reserves the right to withdraw or rescind the scholarship offer in exceptional circumstances.Diplomatic students not eligible.', 'Please refer to the University of Canberra\'s website for details', '10% & 30% off Tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.canberra.edu.au/scholarship/uc-alumni-scholarships.html', 'https://search.studyaustralia.gov.au/scholarship/uc-alumni-scholarships/7285fe9dea79be1a2b3217264f5dba37', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00212K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UC Alumni Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UC High Achievers Scholarships', 'Awarded to commencing international students applying to study a course at UC, subject to meeting the UC and PG qualifying criteria. All applicants are assessed for a scholarship at the time of application to the course at UC. No further application is required. Scholarships are granted on a first-come-first-served basis until filled. Students are advised to accept the scholarship as soon as possible in order to avoid disappointment. Scholarships are limited and may be withdrawn if capacity is reached. The scholarship is valid only for the intake and course specified and will be confirmed once all conditions are met, your offer is accepted, and required payments are completed. The University reserves the right to withdraw or rescind the scholarship offer in exceptional circumstances. Diplomatic students not eligible.', 'Please refer to the University of Canberra\'s website for details', '20% off Tuition Fees', 'Undergraduate / VET, Postgraduate', NULL, 'https://www.canberra.edu.au/scholarship/uc-high-achievers-scholarships.html', 'https://search.studyaustralia.gov.au/scholarship/uc-high-achievers-scholarships/6b4c9b51473740f9c89137b6e27d3cb1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00212K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UC High Achievers Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UC International Partners Scholarships', 'Awarded to students transferring to Bruce campus from UC\'s institutional partners located outside Australia, subject to meeting the UG and PG qualifying criteria.All applicants are assessed for a scholarship at the time of application to the course at UC. No further application is required. Scholarships are granted on a first-come-first-served basis until filled. Students are advised to accept the scholarship as soon as possible in order to avoid disappointment. Scholarships are limited and may be withdrawn if capacity is reached. The scholarship is valid only for the intake and course specified and will be confirmed once all conditions are met, your offer is accepted, and required payments are completed. The University reserves the right to withdraw or rescind the scholarship offer in exceptional circumstances. This scholarship will be applied to students receiving an articulation offer or offer with credit from an articulation partner. Where a student packages a Bachelor and Masters degree, the scholarship will apply to both the Bachelor and Masters coursesNote: Diplomatic students are not eligible.', 'Please refer to the University of Canberra\'s website for details', '10% and 30% off Tuition Fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.canberra.edu.au/scholarship/uc-international-partnership.html', 'https://search.studyaustralia.gov.au/scholarship/uc-international-partners-scholarships/134ffbc977b1881d86c57520f7882c98', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00212K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UC International Partners Scholarships') LIMIT 1;
