INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UC-Bhutan Excellence Scholarships', 'Awarded to commencing international students applying to study a course at UC, subject to meeting the UC and PG qualifying criteria.All applicants are assessed for a scholarship at the time of application to the course at UC. No further application is required. Scholarships are granted on a first-come-first-served basis until filled. Students are advised to accept the scholarship as soon as possible in order to avoid disappointment. Scholarships are limited and may be withdrawn if capacity is reached. The scholarship is valid only for the intake and course specified and will be confirmed once all conditions are met, your offer is accepted, and required payments are completed. The University reserves the right to withdraw or rescind the scholarship offer in exceptional circumstances.Diplomatic students not eligible.', 'Please refer to the University of Canberra\'s website for details', '30% off Tuition Fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.canberra.edu.au/scholarship/uc-bhutan-excellence.html', 'https://search.studyaustralia.gov.au/scholarship/uc-bhutan-excellence-scholarships/006e2649776497323119cb38119d8bce', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00212K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UC-Bhutan Excellence Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'A smart CPR feedback device for cardiac arrest (PhD scholarship)', 'This PhD project focuses on developing the first-ever closed-loop cardiopulmonary resuscitation (CPR) feedback device. The device uses non-invasive sensors to measure blood oxygenation in the brain and tells the CPR provider how to adjust their compression depth, rate, and release to improve patient outcomes. The student will have the opportunity to work with a range of engineers, doctors, and paramedics and will help to develop this prototype into an ambulance-ready device, ready for deployment in large-scale clinical trials.', 'You need to meet the entry requirements for QUT\'s Doctor of Philosophy, including any English language requirements.; Enrol as a full-time, internal student.; Have a background in electrical, mechatronic, or biomedical engineering, expertise in biosensors or optics. Should be comfortable being hands-on. Requires experience in circuit design and microcontroller programming.', 'AUD $33637/year', 'Postgraduate', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/a-smart-cpr-feedback-device-for-cardiac-arrest-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/a-smart-cpr-feedback-device-for-cardiac-arrest-phd-scholarship/0b6b29fc7a416b77c32a6bfb937838a0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'A smart CPR feedback device for cardiac arrest (PhD scholarship)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australia Awards Scholarship', 'As an Australia Awards student you need to attend a five-week Introductory Academic Program (IAP). It’s a chance for you to get help with enrolment, learning skills, language expectations and our technology and teaching systems. You will receive program information to your student email.', '-', 'See scholarship details', 'Postgraduate, Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/australia-awards-scholarship', 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarship/c91bd86d2c6d99745facf696367dc009', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australian South Sea Islander Community Foundation Scholarship', 'The Australian South Sea Islander Community Foundation was established by the Queensland Government in 2001 as a perpetual fund to provide scholarships to Australian South Sea Islander undergraduate students.', 'an Australian South Sea Islander who is a direct descendant of the South Sea Islanders who were brought into Queensland between 1863 and 1904 and worked as indentured labourers, not have previously completed an undergraduate degree at any university, be intending to enrol or are currently enrolled in an undergraduate program (either part time or full time) at QUT, from a low-income background, experiencing financial hardship, enrolled in or applying for an undergraduate course, personal medical conditions, disabilities, dependants with special needs.', 'You will receive an Australian South Sea Islander Community Foundation Scholarship. The value and number of scholarships will vary annually depending on funding. These scholarships are subject to annual funding.', 'Undergraduate / VET', NULL, 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/australian-south-sea-islander-community-foundation-scholarship', 'https://search.studyaustralia.gov.au/scholarship/australian-south-sea-islander-community-foundation-scholarship/8d3162228bfef1e724bf31c3eea1d690', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian South Sea Islander Community Foundation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bachelor of Arts Impact Scholarship', 'The Bachelor of Arts Impact Scholarship is awarded to high-achieving school leavers and eligible gap year students starting our Bachelor of Arts degree. This scholarship is targeted at high achievers to enable their continued success at QUT through financial support, peer support, mentoring and networking opportunities.', 'You must:; demonstrate exceptional academic excellence in school studies, based on your adjusted Australian Tertiary Admissions Rank (ATAR) or adjusted selection rank for International Baccalaureate (IB); be graduating Year 12 in 2026, or have graduated Year 12 in 2025, and are applying through the Queensland Tertiary Admissions Centre (QTAC) to QUT for the first time; nominate QUT\'s Bachelor of Arts as your first preference on your QTAC application at the time of the main December and January admission offer rounds and receive an offer in the first preference; be starting a university undergraduate degree for the first time in 2027; have not undertaken/commenced any tertiary study, other than studies in special university programs designed for secondary school students', 'Up to AUD $15000', 'Undergraduate / VET', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/bachelor-of-arts-impact-scholarship', 'https://search.studyaustralia.gov.au/scholarship/bachelor-of-arts-impact-scholarship/04c21ed2e6bb871c753cd5c97aa29181', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bachelor of Arts Impact Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'China Scholarship Council Scholarship', 'A scholarship for future research students studying in any faculty.', 'You must:; meet the China Scholarship Council requirements, as outlined on the China Scholarship Council website (in Mandarin); apply for and be admitted to a PhD, research masters or professional doctorate at QUT; To apply for this scholarship, you must meet the entry requirements for a Doctor of Philosophy (PhD), Master of Philosophy, or professional doctorate at QUT, including any English language requirements for international students.\r\n\r\nYou must:; meet the China Scholarship Council requirements, as outlined on the China Scholarship Council website (in Mandarin); apply for and be admitted to a PhD, research masters or professional doctorate at QUT; To apply for this scholarship, you must meet the entry requirements for a Doctor of Philosophy (PhD), Master of Philosophy, or professional doctorate at QUT, including any English language requirements for international students.', 'a tuition fee waiver for the duration of your course, which is normally 1.5 years for masters students and 3 years for doctoral students.', 'Postgraduate', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/china-scholarship-council', 'https://search.studyaustralia.gov.au/scholarship/china-scholarship-council-scholarship/cbc16bf079d440444fdcc8f796911f37', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'China Scholarship Council Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Clayton Adam Florence Wilson Award for Biomechanics and Spine Research', 'The Clayton Adam Florence Wilson Award is available to promote spine research at QUT, and honours the stellar contribution to scientific innovation in spine research made by our former Research Director, Professor Clayton Adam. Clayton joined QUT in 1999 and dedicated his work to helping children with spinal disorders, and to improving treatment outcomes for patients who undergo spinal surgery. He brought together a dedicated team of researchers, scientists, engineers, surgeons and industry partners to perform cutting edge research aimed at minimising risks and improving spinal surgery results for patients. Clayton’s leadership of the research program resulted in QUT receiving a substantial bequest from a donor impressed by his work: the Florence Wilson Bequest. In 2015, Clayton was diagnosed with a terminal illness yet continued his active research during treatment until early 2018. Sadly, his health battle ended in March 2018, but his dedication and contribution to biomechanics and spinal research will long be remembered and admired.', 'You must have experience in biomechanics and/or spine research. Further eligibility criteria will be provided following successful acceptance of your application.', 'See scholarship details', 'Postgraduate', 'Computing and information technology, Engineering and technology, Health services and support, Humanities and social sciences, Mathematics, Sciences', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/CAFW-Award', 'https://search.studyaustralia.gov.au/scholarship/clayton-adam-florence-wilson-award-for-biomechanics-and-spine-research/d945ac0fc1f41fced0575e8b5704dc96', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Clayton Adam Florence Wilson Award for Biomechanics and Spine Research') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Data61 PhD Scholarship', 'At CSIRO\'s Data61, we aim to develop top-quality doctoral students who will prosper in careers in Australia’s data-skilled workforce. Our PhD scholarship program provides opportunities for outstanding postgraduate students with demonstrated academic and research excellence to further their careers at one of Australia’s most trusted organisations.\r\n\r\nWe offer a diverse, inclusive and flexible working environment where our people are supported and empowered to come up with digital and data solutions with impact.\r\n\r\nYou’ll work closely with your supervisors and teams on research projects that are aligned to our strategic goals. Our scholarships are awarded in partnership with Australian universities, so you’ll receive support and guidance from university supervisors alongside some of the country’s leading data and digital science experts.', 'domestic and international students who currently live in Australia, \r\ninternational students overseas at the time of application, who hold a visa to study in Australia, \r\nhold a first-class honours (H1) Bachelor’s degree or equivalent in the relevant research area (completed or near completion), \r\nhave applied for admission to a PhD program at an Australian university or have completed less than 12 months study in a PhD program at an Australian university at the start of the scholarship’s commencement period, \r\nhave a university supervisor who confirms they are willing and able to supervise you listed in your application, as Data61 does not organise your academic supervisor, \r\nnot already hold a PhD degree, \r\nbe ready to commence within the specific time and period noted in the advertisement.', 'a full scholarship which includes a base stipend at the Australian Government Research Training (RTP) Program base rate supplemented with a top-up scholarship of $10,000 per annum. Data61 PhD scholarships have a maximum term of 3 years and 6 months.', 'Postgraduate', 'Built environment, Computing and information technology, Engineering and technology, Mathematics, Sciences', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/data61-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/data61-phd-scholarship/e18d26a8362937016e062999ef29aa34', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Data61 PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Dynamic soft matter materials PhD scholarship', 'As the successful applicant you will complete your PhD in the field of organic photochemistry for advanced reprogrammable material design.Based in our Science and Engineering Faculty, you will also spend time at our research hub at the Karlsruhe Institute of Technology (KIT) in Germany.', 'fulfil our PhD admission criteria, including English language requirements (an IELTS score of 6.5 or above if English is not your first language).', 'a minimum of $30,000 per year, for 3 yearsa QUT tuition fee sponsorship (for international students).', 'Postgraduate', 'Mathematics, Sciences', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/dynamic-soft-matter-materials-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/dynamic-soft-matter-materials-phd-scholarship/663db6124f3eb4f6d8511f1e8ec2d239', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Dynamic soft matter materials PhD scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Equity Work Integrated Learning (WIL) Bursaries', 'If you\'re completing a work integrated learning (WIL) placement and experiencing financial hardship, you may be eligible for a bursary of up to $750.', 'currently enrolled as a student, struggling financially, undertaking a work integrated learning (WIL) placement, unable to meet the costs of placement.', 'Up to AUD $1000 — bursary of $300, $500, $750 or $1000 based on your demonstrated need.', 'Postgraduate, Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/equity-work-integrated-learning-wil-bursaries', 'https://search.studyaustralia.gov.au/scholarship/equity-work-integrated-learning-wil-bursaries/49629bcecc57af26ba15ca0a063a6630', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Equity Work Integrated Learning (WIL) Bursaries') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Equity scholarships scheme', 'The QUT Equity Scholarships Scheme is an application-based scheme offered to students who experience financial difficulty. It is funded by significant contributions from the Learning Potential Fund. The scholarships and bursaries are offered to commencing or continuing domestic and international students.', 'You must be from a low-income background, and experiencing financial hardship. We also take personal hardship into consideration when assessing applications. This includes personal medical conditions, disabilities and dependants with special needs.', 'Up to AUD $4200', 'Postgraduate, Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/equity-scholarships-scheme', 'https://search.studyaustralia.gov.au/scholarship/equity-scholarships-scheme/53b646db0a38d87929e99fc755b2469b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Equity scholarships scheme') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Merit Scholarship', 'A high achievement scholarship for future international undergraduate and postgraduate students.', 'Meet the academic entry requirements, meet minimum English language entry requirements for the degree program. If you complete a QUT pathway program for the purpose of satisfying QUT English language requirements, you may be eligible for this scholarship once you start your degree program, receive an admission offer letter into one of the eligible courses offered by participating faculties.', 'a scholarship to cover 25% of your tuition fees for your first two semesters (one year) of study at QUT, provided you meet the minimum academic standards.', 'Postgraduate, Undergraduate / VET', 'Built environment, Computing and information technology, Engineering and technology, Mathematics, Sciences', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/international-merit-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-merit-scholarship/834f5a383770ab75e9d4ad02cc79375a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Talent Scholarship', 'A new scholarship for 2026 that covers tuition fees, with eligibility based on your prior academic achievements.', 'You must:; meet the academic entry requirements; have an eligible nationality; meet minimum English language entry requirements for the course; be commencing the course for the first time; receive an admission offer letter into one of the eligible courses.', 'You\'ll receive an ongoing scholarship to cover 20% of your tuition fees per semester of study at QUT', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/international-talent-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-talent-scholarship/461afe36373be72657bc184811ea79e1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Talent Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Investigation on Bubble Dynamics Under Electric Fields in Water Electrolysis Process', 'We are seeking a PhD candidate to investigate gas bubble dynamics under the influence of electric fields, with a particular focus on applications in electrochemical hydrogen production. The project will examine the physical mechanisms governing bubble generation, growth, detachment, coalescence, and transport near electrode surfaces, with the aim of improving bubble removal and enhancing the efficiency of water electrolysis systems.', 'Completion of a Bachelor (Honours) or Master by Research degree in mechanical engineering, electrical engineering, chemical engineering, applied mathematics, applied physics or related disciplines', 'AUD $37010/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/investigation-on-bubble-dynamics-under-electric-fields-in-water-electrolysis-process', 'https://search.studyaustralia.gov.au/scholarship/investigation-on-bubble-dynamics-under-electric-fields-in-water-electrolysis-process/a60cc9ee661e96ba2b80bef2375ffebf', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Investigation on Bubble Dynamics Under Electric Fields in Water Electrolysis Process') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'QUT College English Language Concession', 'A tuition fee concession for commencing students from selected countries to study English for Academic Purposes or IELTS Advanced Program at QUT College.', 'A tuition fee concession for commencing students from selected countries to study General English or English for Academic Purposes at QUT International College. These concessions are available for prospective students from Colombia and Latin America, Hong Kong, India, Japan, Korea, Sri Lanka, Taiwan, Thailand and Vietnam.', 'A reduction of 25% from the tuition fee of your English for Academic Purposes (EAP) and IELTS Advanced programs at QUT College.', 'Postgraduate, Undergraduate / VET', 'Languages', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-college-english-language-concession', 'https://search.studyaustralia.gov.au/scholarship/qut-college-english-language-concession/f3886f22ee4e66ab67c405f39021117b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT College English Language Concession') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'QUT College Merit Scholarship', 'This scholarship is sponsored by QUT College. It is available to international students who have demonstrated academic achievement or can demonstrate how they intend to commit to success in their future studies.', 'Your eligibility will depend on your secondary school results.\r\n\r\nIf you are eligible for an International Merit Scholarship for your degree course, you are also eligible for the College Merit Scholarship.', 'A scholarship to cover 25% of the tuition fees for the first semester of your Diploma or Foundation program at QUT International College. An invitation to a Pathway Scholarship ceremony, certificate of recognition, and access to extra-curricular prof', 'Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-international-college-pathway-scholarship', 'https://search.studyaustralia.gov.au/scholarship/qut-college-merit-scholarship/119c6423cfe25e0776520252337f9b72', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT College Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'QUT Excellence Scholarship (Academic)', 'The QUT Excellence Scholarship is our premier offering for high achievers. We award more than 130 scholarships annually, worth more than $3.5 million.In addition to the financial support, the program helps you to make the most of your QUT experience through extra development opportunities, which build your leadership skills and professional networks.', 'an Australian or New Zealand citizena permanent resident, a holder of a permanent humanitarian visa, an international student studying the Australian Year 12 curriculum, either in Australia or overseas.be starting university for the first time in 2025, be graduating Year 12 in 2024, or have graduated Year 12 in 2023 and have had no more than one gap year since graduating, have achieved a minimum unadjusted Australian Tertiary Admissions Rank (ATAR) of 98.00 or equivalent to be considered for the scholarship, noting it is a competitive process and not all applicants on an unadjusted ATAR of 98.00 or above will be made an offer, have placed QUT as your first preference on your QTAC application at the time of the main December and main January admissions offer roundsreceive a QUT offer in your first preference.', 'Up to AUD $30000 — scholarships valued at $30,000 each for study in any discipline, scholarships valued at $30,000 each for courses in the Faculty of Science and Faculty of Engineering only.', 'Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Creative arts', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/excellence-scholarship-academic', 'https://search.studyaustralia.gov.au/scholarship/qut-excellence-scholarship-academic/681083bc23ea5cc6ae00e5b7d63072b9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT Excellence Scholarship (Academic)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'QUT Postgraduate Research Award (QUTPRA)', 'We are building research excellence by supporting students of exceptional research potential with QUTPRAs. The number of QUTPRAs offered varies from year to year.', 'New applicants to QUT research degrees need to: meet QUT’s admission criteria for a research degree, which includes meeting QUT’s English language requirements, not be in receipt of another living allowance scholarship to undertake the research degree.\r\nCurrent QUT research students need to have consumed less than the below equivalent full-time study load (EFTSL) to apply: less than 1 year EFTSL for enrolled research doctorate students, less than 6 months EFTSL for enrolled research masters students', 'A living allowance for three years, indexed annually ($27,596 in 2019). The scholarship is tax exempt for full-time students, and can be used to support living costs.', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-postgraduate-research-award-qutpra', 'https://search.studyaustralia.gov.au/scholarship/qut-postgraduate-research-award-qutpra/d6c913e04e2d91bedf6935fb82f0abfb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT Postgraduate Research Award (QUTPRA)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'QUT and GoStralia! PhD Scholarship', 'Four scholarships are available for German applicants wishing to study in Science or Engineering', 'You must also meet QUT\'s Doctor of Philosophy Academic Entry requirements, and be applying to complete your degree in either QUT\'s Faculty of Science or Faculty of Engineering.', 'AUD $33637/year', 'Postgraduate', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-and-gostralia!-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/qut-and-gostralia-phd-scholarship/9017c9a93df484d2d1b60076603a3b0e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT and GoStralia! PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'QUT-CSIRO PhD Scholarship in Deep Learning for Hyperspectral Image Classification', 'Hyperspectral imaging is one of the rapidly growing domains in remote sensing primarily due to the breadth of applications on a variety of areas, from plant disease detection to object tracking. For example, hyperspectral imaging provides an opportunity to develop fast and non-invasive methods of detecting plant diseases and potentially discriminating between different disease types (e.g. virus, fungus, bacteria) before the human eye can see them. The principal aim of this PhD research program is to develop methods to improve the hyperspectral image classification using deep learning techniques. The developed systems will be evaluated on their ability to detect plant diseases and potentially discriminating between different disease types using the hyperspectral imaging dataset which has been already collected by CSIRO.', 'You must: meet QUT’s PhD admission criteria (Degree in Electrical Engineering and/or Computer Science with first class honours). We would like you to have: sound knowledge of machine learning, computer vision and image processing, strong programming skills.', 'A scholarship between $37,000 and $40,000 per year for 3 years (consisting of a base stipend of $27,000 and a top-up between $10,000 and $13,000) with a possible extension of 6 months. Up to $5,000 per year for project costs (to be agreed between CSI', 'Postgraduate', 'Computing and information technology, Mathematics, Sciences', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-csiro-phd-scholarship-in-deep-learning-for-hyperspectral-image-classification', 'https://search.studyaustralia.gov.au/scholarship/qut-csiro-phd-scholarship-in-deep-learning-for-hyperspectral-image-classification/32630098caf9d4da3a62dcaf80274225', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT-CSIRO PhD Scholarship in Deep Learning for Hyperspectral Image Classification') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research Training Program (RTP) Stipend Scholarship', 'A scholarship for future postgraduate research students in any faculty.', 'New applicants to QUT research degrees need to:; meet QUT\'s admission criteria for a research degree, which includes meeting QUT\'s English language requirements at the time of application; not be in receipt of another living allowance scholarship to undertake the research degree.', 'AUD $38310/year', 'Postgraduate', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/research-training-program-stipend', 'https://search.studyaustralia.gov.au/scholarship/research-training-program-rtp-stipend-scholarship/b007b0a25e142822f7e05d986057c98a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research Training Program (RTP) Stipend Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Shaping the future of mobility in rural and remote regions (PhD scholarship)', 'Headquartered at the Queensland University of Technology (QUT), AVR3 is a pioneering research hub dedicated to advancing automated vehicle (AV) technologies specifically tailored for the unique challenges of rural, regional, and remote Australian roads. AVR3 fosters a collaborative network of experts from multiple academic partners (including QUT, the University of Sydney, UTS, UWA, Deakin, and Swinburne), and industry leaders such as Ford Australia, Seeing Machines, RACQ, The Department of Transport and Main Roads, National Transport Commission, Transport For NSW, and end users in agriculture, mining, and defense.', 'You need to meet the entry requirements for a QUT research degree, including any English language requirements.; Enrol as a full time, internal student (unless approval for part-time and/or external study is obtained).; Have an Honours or Master\'s degree (or equivalent) in one of these areas:\r\nEngineering, Computer Science, Human Factors, Psychology, Data Science, Robotics, or a related policy/business discipline.; Have familiarity with empirical research methods, experimental design, or technical modelling relevant to your field.; Having a demonstrated publication record or potential in peer-reviewed conferences or journals is highly advantageous.', 'AUD $41555/year — You\'ll receive a stipend of $41,555 per annum for a maximum duration of 3.5 years while undertaking a QUT PhD (1.75 years for MPhil). The duration includes an extension of up to 6 months (PhD) or 3 months (MPhil) if approved for you', 'Postgraduate', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/shaping-the-future-of-mobility-in-rural-and-remote-regions-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/shaping-the-future-of-mobility-in-rural-and-remote-regions-phd-scholarship/db2f4c39bdadeee874d2ea9ea22ecb6e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Shaping the future of mobility in rural and remote regions (PhD scholarship)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'System-Level Multiphase Flow and Bubble Transport for Efficient Electrochemical Hydrogen Production', 'We are seeking a PhD candidate to investigate system-level multiphase flow processes in electrochemical hydrogen production. The project will focus on how operating conditions, porous transport layers, electrode properties, and gas bubble transport influence hydrogen and oxygen generation in water electrolysis systems. Efficient removal of gas bubbles is critical to the performance of electrochemical hydrogen production devices. Bubbles generated during water electrolysis can block active reaction sites, increase electrical resistance, disturb liquid flow and mass transport, and reduce overall production efficiency. At the system level, these effects are governed by coupled interactions between electrochemical operation, multiphase flow, porous media transport, surface wettability, temperature, and flow conditions. This project will investigate these coupled processes to identify practical strategies for improving electrolyser performance.', 'Completion of a Bachelor (Honours) or Master by Research degree in mechanical engineering, electrical engineering, chemical engineering, applied mathematics, applied physics or related disciplines', 'AUD $37010/year', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/system-level-multiphase-flow-and-bubble-transport-for-efficient-electrochemical-hydrogen-production', 'https://search.studyaustralia.gov.au/scholarship/system-level-multiphase-flow-and-bubble-transport-for-efficient-electrochemical-hydrogen-production/26c29746c86de06a35005739ca93f67a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'System-Level Multiphase Flow and Bubble Transport for Efficient Electrochemical Hydrogen Production') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Tuition Fee Sponsorship (TFS) for research students', 'A sponsorship to help international student pay tuition fees.', 'International students who enrol in a QUT research degree and are in receipt of:; a stipend scholarship awarded by QUT; a stipend scholarship funded by an organisation with which QUT has an external agreement to sponsor fees for this student or relevant cohort of students.; Candidates will not be eligible if they receive another tuition fees offset or sponsorship from any source, including QUT.; You cannot apply for a Tuition Fee Sponsorship - your eligibility is reviewed via your application for admission.', 'See scholarship details', 'Postgraduate', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/tuition-fee-sponsorship-tfs-for-research-students', 'https://search.studyaustralia.gov.au/scholarship/tuition-fee-sponsorship-tfs-for-research-students/0508a2146c6b8084b7f5699bc78ef0d4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Tuition Fee Sponsorship (TFS) for research students') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Understand and manipulate quantum geometry in kagome metals (PhD scholarship)', 'This PhD project will investigate quantum geometry-driven electronic transport in kagome lattices as a pathway beyond the scaling limits of conventional silicon electronics. By engineering crystal symmetry and magnetic order through controlled chemical doping, the research aims to tune the quantum metric and realize giant nonlinear Hall effects in transition-metal kagome compounds. High-quality single crystals will be synthesised, fabricated into micro-devices, and studied via physical property measurements to probe quantum-metric responses. This project will deliver fundamental insights into quantum materials and establish a platform for low-power quantum devices.', 'You need to meet the entry requirements for QUT\'s Doctor of Philosophy, including any English language requirements.; enrol as a full-time, internal student (unless approval for part-time and/or external study is obtained); commence your degree by 1 Oct 2026; have an honours or master degree in one of these areas:; physics; theoretical chemistry; materials science and engineering.', 'AUD $40000/year — You\'ll receive a stipend of $40,000 per annum for a maximum duration of 3.5 years while undertaking a QUT PhD. The duration includes an extension of up to six months if approved for your candidature. This is the full-time, tax exemp', 'Postgraduate', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/understand-and-manipulate-quantum-geometry-in-kagome-metals-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/understand-and-manipulate-quantum-geometry-in-kagome-metals-phd-scholarship/4a1edfc5258e221763a24ee4f43121bc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Understand and manipulate quantum geometry in kagome metals (PhD scholarship)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Using Systems Engineering to Model Neuropathic Pain (PhD Scholarship)', 'Neuropathic pain effects "1 in every 10 adults over the age of 30". The treatments available for neuropathic pain can at best be described as having "moderate efficacy". Due to the nature of neuropathic pain, the ability to scientifically study and understand its fundamental causes has been limited to animal models and trials. There are over 27 animal models for neuropathic pain where pain has been induced by macroscopic & microscopic nerve lesions, chemotherapy, viral infections and diabetes mellitus. Looking at clinical studies, the current research process is to propose a model, conduct animal tests and then evaluate whether the original model is consistent with results. This is difficult as it requires humans to evaluate pain in animals which cannot be directly measured. This process is not systematic in the way it comes up with models and has thus resulted in many models of limited effectiveness.', 'You need to meet the entry requirements for a QUT research degree / Doctor of Philosophy / professional doctorate, including any English language requirements.; enrol as a full-time, internal student; have a background in either mechanical or medical engineering.', 'AUD $32500/year', 'Postgraduate', NULL, 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/using-systems-engineering-to-model-neuropathic-pain-phd-scholarship', 'https://search.studyaustralia.gov.au/scholarship/using-systems-engineering-to-model-neuropathic-pain-phd-scholarship/2d267fa6130c6a60c90cff60bf21a72d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Using Systems Engineering to Model Neuropathic Pain (PhD Scholarship)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'VIED PhD Scholarship', 'QUT is working with the Vietnam Ministry of Education and Training (MOET) through the Vietnam International Education Development (VIED) Office.', 'This scholarship is available to eligible Vietnamese postgraduate research students. You must be an international from Vietnam with an offer from QUT, meet all academic requirements, meet English language entry requirements for admission to the QUT course and meet any additional relevant requirements.', 'a full scholarship covering your tuition fees and living expenses for the duration of your three-year PhD.', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/project-911-scholarship', 'https://search.studyaustralia.gov.au/scholarship/vied-phd-scholarship/9731fb149c23f2465f5fc9a9254adfc8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'VIED PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Browse CQUniversity Scholarships', 'We believe a quality education can be for everyone – regardless of background, location, or life circumstances. That’s why we offer a variety of scholarships and bursaries to cater for all student needs. This can include financial support to assist with living expenses, and non-deferrable costs such as textbooks, uniforms, technology, course-specific equipment, travel costs associated with compulsory residential schools and unpaid placement, accommodation, and general living expenses such as rent, groceries and fuel. Whether you’re a commencing student or continuing your studies, receiving a scholarship can help balance your studies and life commitments. A scholarship looks good on your resume and may open the door to industry networks and work experience opportunities.', 'Eligibility requirements vary depending on the scholarship. Please review the specific eligibility criteria for each scholarship you are interested in.', 'See scholarship details', 'Undergraduate / VET, Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.cqu.edu.au/study/prepare/scholarships', 'https://search.studyaustralia.gov.au/scholarship/browse-cquniversity-scholarships/4f95b5a94355ac225ed0f62e30339cf7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00219C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Browse CQUniversity Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'CQUniversity ASEAN Student Scholarship', 'The CQUniversity ASEAN Student Scholarship is a highly competitive scholarship offering 50 per cent off tuition fees for eligible undergraduate, postgraduate coursework and research courses at CQUniversity Australia. This scholarship is limited and awarded to high‑achieving international students who demonstrate strong academic performance, leadership potential and a commitment to making a positive impact in their community or chosen field. Designed to recognise future changemakers from Southeast Asia, this scholarship supports motivated students to access a world‑class Australian education while investing in their long‑term career success.', 'To be eligible for the CQUniversity ASEAN Student Scholarship, you must:; plan to commence your studies in 2026 or 2027; hold citizenship from a Southeast Asian country; have demonstrated outstanding academic achievement, achieving a minimum grade average of 75 per cent or equivalent, as assessed by the University; submit your application from offshore, outside Australia.', '50% off tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1271035/asean-student-scholarship', 'https://search.studyaustralia.gov.au/scholarship/cquniversity-asean-student-scholarship/45d84db1f2761c9fc1f0a5cf5a975428', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00219C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'CQUniversity ASEAN Student Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Indonesia Student Scholarship', 'The Indonesia Student Scholarship supports Indonesian students in pursuing their study ambitions in Australia. By offering 50 per cent off tuition fees, this scholarship helps you focus on what matters most - achieving academic success and building a strong future.', 'To be eligible for the Indonesia Student Scholarship, you must:;hold an Indonesian citizenship; meet the academic and English language proficiency requirements at CQUniversity; submit your application from offshore, outside Australia', '50% off tuition fees // Duration of course', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1273751/indonesia-student-scholarship', 'https://search.studyaustralia.gov.au/scholarship/indonesia-student-scholarship/53866b3fb22cf14773b5b757e21395d1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00219C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Indonesia Student Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Alumni Scholarship', 'The International Alumni Scholarship offers eligible international students the opportunity to continue their academic journey at CQUniversity Australia. Designed to support recent graduates, this scholarship provides a 15 per cent reduction in tuition fees for the duration of the course.', 'To receive the International Alumni Scholarship, you must be an international student who has completed a CQUniversity qualification and commence a new course at CQUniversity within 12 months of your conferral date. You must meet the academic and English language proficiency requirements for your chosen course.', '15 percent reduction in tuition fees for the duration of the course.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1253043/international-alumni-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-alumni-scholarship/45b30657a750ab8cd83f0801c054e7a5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00219C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Alumni Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Merit Scholarship', 'The International Merit Scholarship is available to all new international students who plan to enrol in undergraduate, postgraduate coursework, research, or packaged academic courses at any campus or online.', 'Please Contact CQUniversity Australia for more information.', 'Valued at up to 25% of your course fees, this scholarship recognises strong academic performance and supports students committed to achieving excellence in their studies.', 'Undergraduate / VET', NULL, 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/745776/international-merit-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-merit-scholarship/c1bcce1dc3c90a311746600eb403a0a5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00219C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Live, Earn and Learn Scholarship', 'The Live, Earn and Learn Scholarship is designed specifically for international students who have received an offer to study at our Rockhampton North campus.  Through this scholarship, you can excel academically while building practical experience in Central Queensland. You\'ll receive a 35% accommodation scholarship at Capricornia College (terms and conditions apply), work part-time on campus or in the local community, and immerse yourself in a vibrant campus lifestyle. Availability for 2027 intakes is currently under review. Updates will be published on this page and communicated to eligible future students when available.', 'You must meet the following requirements:; Have applied and received an offer to study at the Rockhampton North campus in an eligible term.; Have applied to live at our on-campus student residence during your study.', '35% of accommodation cost and paid part-time work.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1188590/live-earn-learn-scholarship', 'https://search.studyaustralia.gov.au/scholarship/live-earn-and-learn-scholarship/d98a2d488e6959fe12e8948b5fdb3d6e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00219C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Live, Earn and Learn Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research Training Program (RTP) Stipend Scholarship (Research)', 'RTP Stipend Scholarships are funded by the Australian Government. They provide funding allocated to students to assist with their living costs while undertaking a research higher degree.', 'To be eligible for an RTP Stipend a candidate must not be receiving income from another source to support the candidates general living costs while undertaking their course of study if that income is greater than 75 per cent of the candidate\'s RTP Stipend rate. Income unrelated to the candidates course of study or income received for the candidates course of study but not for the purposes of supporting general living costs is not taken into account.; To be eligible for a RTP Fees Offset a candidate must not be receiving an equivalent award of scholarship from the Commonwealth designed to offset RHD tuition fees.', 'Up to AUD $114000', 'Postgraduate', NULL, 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/745610/research-training-program-rtp-stipend-scholarship', 'https://search.studyaustralia.gov.au/scholarship/research-training-program-rtp-stipend-scholarship-research/8bb271e210abf5102281316d6a2701bb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00219C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research Training Program (RTP) Stipend Scholarship (Research)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Southeast Asia Excellence Scholarship', 'The Southeast Asia Excellence Scholarship offers a 25% course fee reduction to offshore international students from Southeast Asian countries.  It supports greater diversity by encouraging students from the region to pursue their studies in an inclusive, globally engaged environment.', 'To receive the Southeast Asia Excellence Scholarship, you must be an international student and apply from outside Australia. Additionally, you must be a citizen of one of the following Southeast Asian countries: Brunei, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Timor-Leste (East Timor), or Vietnam.', '25% for new students', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1247065/southeast-asia-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/southeast-asia-excellence-scholarship/7889778b06f7c7438cc4d145030756ed', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00219C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Southeast Asia Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australian Government Research Training Program', 'The Commonwealth Governments Research Training Program (RTP) provides funding to universities to support the research training of both domestic and international higher degree research (HDR) candidates. The funding provided through the RTP offers the provision for universities to administer and award a number of stipend scholarships known as Australian Government Research Training Program (RTP) Scholarships. These awards are governed by the Commonwealth Scholarship Guidelines (Research) 2017. Griffith University awards RTP Stipends via a competitive application process to candidates commencing or enrolled in a HDR program. RTP Stipends are provided to assist with candidates general living costs and do not cover program tuition fees. This website sets out the allowances and conditions attached to the RTP Stipend award.', 'be commencing or enrolled in a HDR program (for which RTP support is available) at Griffith University.; not be receiving income from another source to support the candidates general living costs that provides a benefit greater than 75% of the GUPRS stipend rate to undertake the proposed program. Income unrelated to the candidates HDR program, or income received for the candidates HDR program but not for the purposes of supporting general living costs, is not to be taken into account.', 'AUD $35656/year — RTP Stipends are provided to assist with candidates’ general living costs and do not cover program tuition fees.', 'Postgraduate', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.griffith.edu.au/research-study/scholarships/au-gov-research-training-program', 'https://search.studyaustralia.gov.au/scholarship/australian-government-research-training-program/89c369e992f49267872d97838a4c368c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00233E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian Government Research Training Program') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Griffith International Scholarship for Griffith College Diploma to Degree (following completion of a Griffith College diploma)', 'Our Griffith College Diploma to Degree Scholarship rewards outstanding Griffith College Diploma graduates who are articulating into an undergraduate degree program at Griffith University.', 'Please contact Griffith University for further information.', '$3,000', 'Undergraduate / VET', NULL, 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/griffith-college-diploma-degree', 'https://search.studyaustralia.gov.au/scholarship/griffith-international-scholarship-for-griffith-college-diploma-to-degree-following-completion-of-a-griffith-college-diploma/a19bf63ab53a0c420bef6774828ea7a7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00233E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Griffith International Scholarship for Griffith College Diploma to Degree (following completion of a Griffith College diploma)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Academic Merit Scholarship', 'Our International Academic Merit Scholarship recognises international students with strong academic results applying for undergraduate and postgraduate coursework programs at Griffith University.', 'Applicant must be a citizen of a country other than Australia or New Zealand. Have a minimum GPA in previous studies of 4.5 on a 7 point scale or equivalent. Satisfy all academic and English language entry requirements for your chosen undergraduate or postgraduate coursework program. Be a full-time student starting in any trimester in 2026 or 2027. Excludes the following programs: Bachelor of Medical Science, Bachelor of Dental Health Science, Doctor of Medicine, Master of Dentistry, Master of Speech Pathology, MBA and Graduate Diploma of Flight Management (see full list in Terms and Conditions).', '20% of tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/international-academic-merit-scholarship', 'https://search.studyaustralia.gov.au/scholarship/international-academic-merit-scholarship/8365995ba87a8d52f4444e9a523e46d3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00233E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Academic Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'John Willett International Scholarship', 'The founding Vice Chancellor of Griffith University, Professor John Willett (1922 - 1993) is remembered by many people throughout Australia as an academic and organisation builder of insight, innovation and drive. In memory of Professor Willett\'s work in management education, particularly in Asia, a fund was established to provide a scholarship for students from selected countries in Asia within the Griffith Business School, formerly the Graduate School of Management. The John Willett International Scholarship will offer a 50% tuition fee waiver for a maximum period of two years for the selected recipient to complete their Master of Global Development at Griffith. This will provide an opportunity for the recipient to acquire knowledge and skills needed to promote global sustainable development.', 'Please contact Griffith University for further information.', '50% of tuition fees', 'Postgraduate', NULL, 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/john-willett-international-endowed-scholarship', 'https://search.studyaustralia.gov.au/scholarship/john-willett-international-scholarship/b160f2eb575dd92a7a1eb20713ef8ae4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00233E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'John Willett International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Vice Chancellor\'s International Scholarship', 'Our Vice Chancellor\'s International Scholarship rewards exceptional international students applying for undergraduate and postgraduate coursework degree programs at Griffith University.', 'Applicants must: Be a citizen of a country other than Australia or New Zealand; Have a minimum GPA in previous studies of 6.0 or above on a 7 point scale or equivalent; Have received an offer to study at Griffith by the scholarship application closing date; Satisfy all academic and English language entry requirements for your chosen undergraduate or postgraduate coursework program; Be a full-time student starting in 2026 or 2027.', 'Valued at 50% of tuition fees.', 'Postgraduate, Undergraduate / VET', 'Accounting, Architecture, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Creative arts', 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/vice-chancellors-international-scholarship', 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-international-scholarship/2e5d9eba62517e3f72417b98c198a85a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00233E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Vice Chancellor\'s International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Vice-Chancellor\'s Academic Achievement Scholarship', 'Griffith offers these respected scholarships to outstanding students commencing their first-ever undergraduate degree in 2026. The Vice Chancellor\'s Academic Achievement Scholarships will be focused on excellence and will also consider the barriers to education that students have faced.', 'To be eligible, you must: be either: an Australian Citizen or Australian Permanent Humanitarian Visa holder.; an Australian Permanent Resident, New Zealand Citizen or international student who is completing or has completed Years 11 and 12 in Australia.; be a student commencing university for the first time in Trimester 1 2026.; have not undertaken/commenced any tertiary study (bachelor degree or postgraduate degree), with the exception of that undertaken as part of Year 11–12 studies (e.g. Enhanced Studies program, Head Start).; have applied to commence at Griffith University in Trimester 1 2026 through either Queensland Tertiary Admissions Centre (QTAC); Universities Admission Centre (UAC), or via direct entry.; receive an unadjusted ATAR of 95.45 or above (or equivalent rank OP 3 or above, and IB 37 or above). Griffith may use your Educational Disadvantage Assessment score* to adjust your ATAR rank.', 'Up to AUD $15000 — Maximum value of the scholarship is determined by the length of the undergraduate degree for which you are awarded, and is calculated at a rate of $625/10 CP. For example: $15,000 for a single degree (240 CP), $20,000 for a double', 'Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'https://www.griffith.edu.au/scholarships/scholarship-listings/vice-chancellors-academic-achievement-scholarship', 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-academic-achievement-scholarship/76d97f3c27985f7fc003c788692c7cf3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00233E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Vice-Chancellor\'s Academic Achievement Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Incoming Study Abroad International Travel Grant - 2025', 'The University of Southern Queensland will offer grants to non-award international students commencing or continuing their enrolment in the Study Abroad program, in Trimester 1, Trimester 2 or Trimester 3 2025.', 'Applicants must:; Be an international student; Be commencing or continuing their studies in the Study Abroad program (fee paying) at UniSQ in Trimester 1, Trimester 2 or Trimester 3 2025; Be studying on-campus; Be enrolled in a minimum of three study units for each trimester in accordance with the duration of the grant awarded; Be studying the Study Abroad program (fee paying) at UniSQ (not be studying Cross-institutional, Professional Development, Bachelor or Master courses); Have not already been awarded two grants over two trimesters.', 'Up to AUD $2000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.unisq.edu.au/scholarships/unisqi-incoming-study-abroad-international-travel-grant', 'https://search.studyaustralia.gov.au/scholarship/incoming-study-abroad-international-travel-grant-2025/961ed1ebae9e8031d02f0316af6f7e51', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00244B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Incoming Study Abroad International Travel Grant - 2025') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Support Scholarship - 2025', 'In 2025, the University of Southern Queensland (UniSQ) will offer scholarships to new international students studying on-campus, external or online. This scholarship is based on meeting the entry requirements for the program of study and maintaining satisfactory academic performance for duration of study at UniSQ. International students in all areas of award programs undergraduate, postgraduate and research are welcome to apply.', 'Applicants must:; Be an international student; Be enrolled in on-campus, external or online mode; Be a commencing student (i.e. be new to UniSQ) in 2025; meet the academic and English requirements for the UniSQ award program for which they apply; not be in receipt of another UniSQ tuition fee scholarship; not be a sponsored student, unless student is sponsored by an NGO or a government of a low or middle income country; not be studying through an offshore partner.', 'Each scholarship will have a maximum value of 15% of the tuition fees for the duration of the approved award program and will be applied as a 15% reduction of the tuition fees. (Students are responsible for paying the remainder of the fees as per the', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.unisq.edu.au/scholarships/unisq-international-student-support-scholarship-2025', 'https://search.studyaustralia.gov.au/scholarship/international-student-support-scholarship-2025/e5dc6cf372245a8b0fce1d4882c288c9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00244B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Support Scholarship - 2025') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alternative Study Path Scholarship', 'There’s more than one path to university. As an international student in Australia, you may be eligible for the Alternative Study Path Scholarship if you have completed studies onshore, or if you are in Australia and in the process of applying for a student visa. This scholarship covers 15 percent of your total course tuition.', 'As an international student in Australia, you may be eligible if you have completed an onshore English language program, Australian Year 12, a vocational program or six months of higher education study (unless a release from your current registered provider is obtained, or you may be in the process of applying for a Student Visa onshore in Australia).; Postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. Scholarship applicable on tuition fee only and on first attempt subjects only. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study.', '15% of your total tuition costs', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/alternative-study-path-scholarship/368c2664ec5711c69611a4bb473179f7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00246M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alternative Study Path Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Americas & European Health Scholarship', 'Does your passport say you re from Latin America or Europe? If so, you have the chance to take advantage of this scholarship, which gives you 15 percent off your total course tuition when you start studying Health at Think Education.', 'Regional scholarships are provided based on new international students’ passports. Undergraduate and postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. Scholarship applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study.', '15% of your total tuition costs', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/americas-european-health-scholarship/f73ec300f90be6735ac6214c95f2d743', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00246M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Americas & European Health Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Asia & Greater China Health Merit Scholarship', 'If you are from Asia or Greater China and are planning to combine an English language course with one of our Health degrees, you have the opportunity to apply for this regional scholarship. It will cover 20 per cent of your total course tuition.', 'Regional scholarships are provided based on new international students’ passports. Undergraduate students need to display a credit average from high school, and postgraduate students need to display a credit average in a previous degree.; Undergraduate and postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. The scholarship is applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. The scholarship may not be eligible for any course changes during the duration of study.', '20% of your total tuition costs', 'Postgraduate, Undergraduate / VET', NULL, 'https://search.studyaustralia.gov.au/scholarship/asia-greater-china-health-merit-scholarship/5595f4e6d4ce3cb71571fd83ffc0f094', 'https://search.studyaustralia.gov.au/scholarship/asia-greater-china-health-merit-scholarship/5595f4e6d4ce3cb71571fd83ffc0f094', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00246M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Asia & Greater China Health Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Japanese Undergraduate Health Science', 'Do you have a certified passport from Japan? Are you planning to study one of our Diploma or Bachelor of Health Science courses at Think Education? If so, you have the chance to take advantage of a scholarship that will cover 20 percent of your total course tuition.', 'Applicable to new Japanese applicants only, who will be commencing their studies in 2024.; Undergraduate and postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. Scholarship applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study.', '20% of your total tuition costs', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/japanese-undergraduate-health-science/47e9e0dfaba68a6e9d2ef32c6bc81a3e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00246M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Japanese Undergraduate Health Science') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Offshore Online', 'If you re starting your studies offshore and online, you can take advantage of this scholarship, which offers up to 30 percent off your total course tuition (you have to continue studying offshore and online for the whole course).', 'Applicable to full-time undergraduate and postgraduate students studying the full duration of their course offshore. Scholarship applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study.', 'up to 30% of your total tuition costs', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/offshore-online/d750628fce4a7e2155697f03e5b108c4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00246M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Offshore Online') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 ECU Creative Excellence Scholarship', 'The ECU Creative Excellence Scholarship is offered to international students commencing in eligible creative discipline courses at ECU. The scholarship offers a 10 percent reduction in your tuition fees for the duration of your course. The scholarship is open to future international students seeking to enrol at Edith Cowan University in one of the designated undergraduate courses.', 'To be eligible for this scholarship you must:; be an international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen); study onshore at ECU City Campus; not be in receipt of a government scholarship or industry sponsorship; not be in receipt of another ECU scholarship; meet both ECU\'s Academic and English Proficiency entry requirements for the course and commence study onshore at ECU, Western Australia in Semester One, 2026 or Semester Two 2026; be entering into one of the eligible courses', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/2026-ecu-creative-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/2026-ecu-creative-excellence-scholarship/423f95553a7087c2e1c39b1f19289b52', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 ECU Creative Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 ECU Stan Perron Charitable Foundation Top Up Scholarship', 'Edith Cowan University (ECU), in partnership with the Stan Perron Charitable Foundation, is offering top-up scholarships for 2026 to support impactful research in child health. These scholarships are designed to attract motivated and passionate Higher Degree by Research (HDR) candidates who want to improve the health and wellbeing of children and young people in Western Australia.', 'To be eligible, you must:; Undertake research within Childhood Health, adopting The Nest framework to define health holistically. This includes physical, mental, emotional, social, and spiritual dimensions of wellbeing, recognising the interconnected factors that contribute to thriving across the life course.; Be enrolled into a PhD course at ECU.', 'AUD $10000/year', 'Postgraduate', NULL, 'https://www.ecu.edu.au/scholarships/details/2026-ecu-stan-perron-charitable-foundation-top-up-scholarship', 'https://search.studyaustralia.gov.au/scholarship/2026-ecu-stan-perron-charitable-foundation-top-up-scholarship/52ad7937b4b64f0d717038fa3b95d601', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 ECU Stan Perron Charitable Foundation Top Up Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 ECU Study Abroad Bursary', 'This bursary is intended to support travel costs for international non-award students who study at Edith Cowan University for only 1 semester or 1 year in 2026.', 'To be eligible for this bursary you must:; be an international student studying in one of the categories below:; Study Abroad, Student Exchange, Joint Master’s; be studying a minimum 45 credit points in one of the above categories on-campus for the first time commencing in Semester 1, 2026 or Semester 2, 2026; be able to meet mandatory vaccination and travel requirements set by the Australian and Western Australian Governments; have paid $2,000 to the Australian Government for the Student Visa application, lodged on or after 1 July 2025 (and provide evidence when requested); have paid $1,600 to the Australian Government for the Student Visa application, lodged on or after 1 July 2024 (and provide evidence when requested); have had the Student Visa subsequently approved; accept the bursary notification offer within 28 calendar days, for the bursary payment to be made.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/2026-ecu-study-abroad-bursary', 'https://search.studyaustralia.gov.au/scholarship/2026-ecu-study-abroad-bursary/5f35eb197b41cef6288776d788b0ab5d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 ECU Study Abroad Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026-2027 ECU Bachelor of Science (Nursing) C33 Regional Living Allowance Bursary', 'This bursary is to provide new international students commencing at ECU in 2026 or 2027 with a total of $1,000 - $1,500 allowance to support them with living costs, while studying Bachelor of Science (Nursing) C33 on ECU Southwest Campus.', 'To be eligible for this bursary you must:; be a full-fee paying on-campus international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen); be commencing Bachelor of Science (Nursing) C33 at ECU Southwest (Bunbury) Campus in 2026 or 2027; be a new international student commencing Bachelor of Science (Nursing) C33 at ECU Southwest in 2026 or 2027 through direct entry, i.e. not through a pathway packaged program, not an existing ECU student (except ECU Alumni).; not receive a government scholarship or industry sponsorship or ECU full scholarship for your studies.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/2026-2027-ecu-bachelor-of-science-nursing-c33-regional-living-allowance-bursary', 'https://search.studyaustralia.gov.au/scholarship/2026-2027-ecu-bachelor-of-science-nursing-c33-regional-living-allowance-bursary/0cff13b1593fbc50090c8350a7a766c9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026-2027 ECU Bachelor of Science (Nursing) C33 Regional Living Allowance Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Greg Benjamin WAAPA Music Equity Scholarship', 'The Greg Benjamin WAAPA Music Equity Scholarship has been established to support students enrolled in WAAPA\'s Bachelor of Music. The Scholarship is aimed to assist students to complete their course who have a passion for Music and are experiencing financial hardship. The scholarship is valued at $11,000 for 1 year ($5,500 per Semester)', 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, International Student Visa Holder or International Non-Student Visa Holder; be enrolled in the Bachelor of Music or Bachelor of Music Honours course at WAAPA; have and maintain an academic progression status of GREEN; be studying full-time on campus (60 credit points or course equivalent); be able to demonstrate financial hardship; not be in receipt of another scholarship over $5000', 'Up to AUD $11000', 'Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/greg-benjamin-waapa-music-equity-scholarship', 'https://search.studyaustralia.gov.au/scholarship/greg-benjamin-waapa-music-equity-scholarship/7fa9c34ddadf4550def9ec2063b191db', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Greg Benjamin WAAPA Music Equity Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Greg Benjamin WAAPA Music Excellence Scholarship', 'The Greg Benjamin WAPPA Music Excellence Scholarship is awarded to an exceptional Piano student in the jazz or classical discipline. Students enrolled in the Bachelor of Music course in Piano (jazz or classical) will automatically be considered for the Scholarship. The Scholarship is valued at $11,000.', 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, International Student Visa Holder or International Non-Student Visa Holder; be enrolled in W76 - Bachelor of Music - Piano (Jazz or Classical) at WAAPA; have and maintain an academic progression status of GREEN; be studying full-time on campus (60 credit points or course equivalent); not be in receipt of another scholarship over $5000 per annum; not be a previous recipient of the Greg Benjamin Entrance Scholarship.', 'Up to AUD $11000', 'Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/greg-benjamin-waapa-music-excellence-scholarship', 'https://search.studyaustralia.gov.au/scholarship/greg-benjamin-waapa-music-excellence-scholarship/85dd2fd3dd9ee57b53c029139c6f3a95', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Greg Benjamin WAAPA Music Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Lincoln McCashney Memorial Scholarship', 'The Lincoln McCashney Memorial Scholarship is awarded to recognise an Education student who demonstrates the qualities that made the late Lincoln McCashney such an outstanding teacher, educator and mentor to many ECU students, thereby encouraging the development of those qualities and honouring Lincoln\'s contribution to education in WA. The scholarship is valued at up to $5,000 as a one-off payment.', 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, New Zealand citizen or International student; have an academic progression status of GREEN; be enrolled in a Bachelor of Education and be on track to complete a minimum of 360 credit points by end of Semester 2, 2026; be studying a minimum of 30 credit points; have a minimum weighted average mark (WAM) of 60%', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/lincoln-mccashney-memorial-scholarship', 'https://search.studyaustralia.gov.au/scholarship/lincoln-mccashney-memorial-scholarship/1240f5ceb8aba0d18d7f5f42ef764581', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Lincoln McCashney Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'PhD Scholarship - Solvent-Based Direct Lithium Extraction', 'This three-year PhD project, part of the ARC Industrial Transformation Research Hub for Critical Energy Separation Materials (ARC CREST), will develop an innovative and sustainable pathway for lithium recovery by coupling α-spodumene processing with downstream solvent-based direct lithium extraction (DLE). The research will focus on optimising lithium extraction and purification, understanding the effects of feedstock properties and impurities, and integrating the processes into an efficient flowsheet. The project offers multidisciplinary experience in critical mineral processing, hydrometallurgy, solvent extraction, materials characterisation, and process optimisation.', 'This position is open to domestic and international candidates. To be eligible for this scholarship applicants must:; Meet the entry requirements for a PhD at ECU; Hold a Master by Research degree in chemical engineering, metallurgical/extractive metallurgy, chemistry, materials science, or a closely related discipline', 'See scholarship details', 'Postgraduate', NULL, 'https://www.ecu.edu.au/scholarships/details/phd-scholarship-coupling-downstream-solvent-based-direct-lithium-extraction-with-direct-alkaline-digestion-of-spodumene-arc-crest', 'https://search.studyaustralia.gov.au/scholarship/phd-scholarship-solvent-based-direct-lithium-extraction/00ef7fa940dea61c58707ab9e5a9861f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'PhD Scholarship - Solvent-Based Direct Lithium Extraction') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Haselhurst Family Scholarship - Contemporary and Jazz - Vocal', 'The Haselhurst Family Scholarship in Contemporary and Jazz - Vocal has been established to support Bachelor of Music (Contemporary or Jazz Performance) students with a specialisation in Vocal. The scholarship will provide financial support to students who demonstrate a \'need\' that requires financial aid to be able to graduate their course. The scholarship is valued at $7,500 as a one off payment.', 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, New Zealand citizen or International student; have and maintain an academic progression status of GREEN; experiencing financial difficulties; be enrolled full-time (60 credit point minimum requirement) in one of the below courses majoring in either- Contemporary or Jazz Performance with a specialisation in Vocal: Bachelor of Music, Bachelor of Music Honours; previous recipients can reapply.', 'Up to AUD $7500', 'Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/the-haselhurst-scholarship-contemporary-and-jazz-vocal', 'https://search.studyaustralia.gov.au/scholarship/the-haselhurst-family-scholarship-contemporary-and-jazz-vocal/ad6c3a826281adec1e4bb0583757951a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Haselhurst Family Scholarship - Contemporary and Jazz - Vocal') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Haselhurst Family Scholarship in Classical Performance', 'The Haselhurst Family Scholarship in Classical Performance has been established to support Classical Performance students enrolled in WAAPA\'s Bachelor of Music. The scholarship will provide financial support to students who demonstrate a need that requires financial aid to be able to graduate their course. The $10,000 Scholarship is paid as $5000 across 2 semesters.', 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, New Zealand citizen or International student; have and maintain an academic progression status of GREEN; experiencing financial difficulties; be enrolled full-time (60 credit point minimum requirement) in one of the below courses with a major in  - Classical Performance:; Bachelor of Music, Bachelor of Music Honours; previous recipients can reapply', 'Up to AUD $10000', 'Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/the-haselhurst-scholarship', 'https://search.studyaustralia.gov.au/scholarship/the-haselhurst-family-scholarship-in-classical-performance/d797cf8de63e33cff89517bb625c0406', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Haselhurst Family Scholarship in Classical Performance') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Western Australian Premier’s WACE Bursary', 'The Western Australian Premier’s WACE Bursary (the Bursary) provides successful international Western Australian Certificate of Education (WACE) graduates with a total payment of $20,000 towards their living, travel and study expenses. The Bursary is provided to support international WACE graduates who commence undergraduate or tertiary pathway studies in-person at one of Western Australia\'s 5 universities or as part of a packaged pathway course to one of these university.', 'Please contact Edith Cowan University (ECU) for further information.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/the-western-australian-premiers-wace-bursary', 'https://search.studyaustralia.gov.au/scholarship/the-western-australian-premiers-wace-bursary/625a3086c4f23d30e20bc76c498ab223', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00279B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Western Australian Premier’s WACE Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'NTG Operation Thrive Veteran Community Scholarship', 'The NTG Operation Thrive Veteran Community Scholarships aims to provide scholarships for Australian Defence Force veterans, their partners and dependents in alignment with the Operation Thrive campaign. Operation Thrive is a Territory wide initiative to support veterans and their families with transition, employment, education, health, wellbeing, respect and recognition. The initiative was created based on the real-life experiences and insights of veterans and families in the Territory.', 'Ensure that you meet the eligibility criteria of this scholarship before applying.; Must be a current resident of the Northern Territory; Must be enrolled in a Higher Education course at CDU; Must be commencing the course no earlier than semester 2 2026; Must be a Veteran or partner/dependent of a Veteran; Must submit DVA Certified White Card, Gold Card or Defence Common Access Card; or a statutory declaration from the serving member/veteran confirming the partner\'s or dependent\'s relationship to the member', 'Up to AUD $15000 — $2,500 per semester, and an additional $1,200 (one-off) for computer or tools in the first semester', 'Postgraduate', NULL, 'https://stapps.cdu.edu.au/apex/f?p=1000:600', 'https://search.studyaustralia.gov.au/scholarship/ntg-operation-thrive-veteran-community-scholarship/8026b88f6316265874cf82ad7e75b314', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00300K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'NTG Operation Thrive Veteran Community Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 - Larsen Jewellery Scholarship', 'The Larsen Jewellery Scholarship (Scholarship) has been developed by Larsen Jewellery to support and educate young adults wishing to begin a career in jewellery, design or visual arts; or who wish to further their studies in a jewellery, design or visual arts related course.', 'Be either accepted, enrolled or in the process of applying to a relevant course related to design or program at an Australian University or TAFE.', 'Up to AUD $3000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7861', 'https://search.studyaustralia.gov.au/scholarship/2026-larsen-jewellery-scholarship/6c0113bbd69daab6c75128205faa530d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 - Larsen Jewellery Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 - Semester 2 - Curtin On-Campus Accommodation Equity Bursary - Bentley', 'The Curtin On-Campus Accommodation Equity Bursary (the Scholarship) has been established to provide assistance for domestic and international students living in on-campus accommodation at Curtin Bentley who are experiencing financial hardship.', 'Applicants must meet all of the following criteria to be eligible to apply for the Scholarship:; Domestic or international student; Have applied for a place (or currently residing) in one of the following on-campus accommodation residences at Curtin Bentley in a Semester 2, 2026 agreement at the time of application:; St. Catherine\'s College\r\n,Twin Dolphin Hall, Kurrajong Village, Erica Underwood House, Guild House, Vickery House; Have a minimum Course Weighted Average (CWA) of 50 (if applicable) at the time of applying', 'Up to AUD $3000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7885', 'https://search.studyaustralia.gov.au/scholarship/2026-semester-2-curtin-on-campus-accommodation-equity-bursary-bentley/fb339ebd91e8e4bfdd95c53209dc5245', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 - Semester 2 - Curtin On-Campus Accommodation Equity Bursary - Bentley') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 - Semester 2 - Curtin On-Campus Accommodation Equity Bursary - Kalgoorlie', 'The Curtin On-Campus Accommodation Equity Bursary (the Scholarship) has been established to provide assistance for domestic and international students living in on-campus accommodation at Curtin Kalgoorlie who are experiencing financial hardship.', 'Applicants must meet all of the following criteria to be eligible to apply for the Scholarship:; Domestic or international student; Enrolled (minimum 25 credits) in an eligible degree at Curtin in Semester 2, 2026; Have applied for a place (or currently residing) at Agricola, Curtin Kalgoorlie on-campus accommodation in Semester 2, 2026 and/or 2026 annual agreement at the time of application; Have a minimum Course Weighted Average (CWA) of 50 (if applicable) at the time of applying.', 'Up to AUD $2600', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7886', 'https://search.studyaustralia.gov.au/scholarship/2026-semester-2-curtin-on-campus-accommodation-equity-bursary-kalgoorlie/6958e43cce0a1fa57f318d9d5970ada5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 - Semester 2 - Curtin On-Campus Accommodation Equity Bursary - Kalgoorlie') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2027 - Knight Hennessy Scholars Program at Stanford University', 'The Knight-Hennessy Scholars Program supports outstanding graduate students from around the world to pursue an eligible graduate degree at Stanford University in the United States. The program offers scholars the opportunity to join a diverse, multidisciplinary community while participating in leadership development alongside their Stanford studies.', 'To be eligible to apply, applicants must:; have earned, in January 2020 or later, a U.S. bachelor\'s degree or an equivalent qualification from a recognised college or university; apply to, be accepted by and enrol in an eligible full-time Stanford graduate degree program; meet one of the following conditions:; apply separately but concurrently to Knight-Hennessy Scholars and a full-time Stanford graduate degree program, commencing both in the same year; be a current Stanford graduate student applying to add a new full-time Stanford graduate degree program, commencing both Knight-Hennessy Scholars and the new program in the same year; be a current Stanford PhD student in the first year of enrolment, applying to begin Knight-Hennessy Scholars in the second year of PhD enrolment.', 'funding for up to three years of graduate study at Stanford, depending on the length of the degree program; a stipend for living and academic expenses, plus a travel stipend for one annual trip to and from Stanford; leadership development opportuniti', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7996', 'https://search.studyaustralia.gov.au/scholarship/2027-knight-hennessy-scholars-program-at-stanford-university/002f40f37e2b4cfd47337788e2be89b2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2027 - Knight Hennessy Scholars Program at Stanford University') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2027 - Semester 1 - Curtin Humanitarian Scholarship (Future Students)', 'The Curtin Humanitarian Scholarship (Scholarship) has been developed by Curtin University to support Curtin undergraduate and postgraduate students from a refugee-like background who are experiencing financial difficulty in meeting the costs of pursuing higher education.', 'Australian citizen, Australian permanent resident, Australian permanent humanitarian visa holder, New Zealand citizen or an international student with any of the below:;  The applicant has applied for a Protection visa in Australia and is the holder of one of the following visas:; o Bridging visa A (class WA) (Subclass 010); o Bridging visa C (Class WC) (Subclass 030); o Bridging visa E (Class WE) (Subclass 050 or Subclass 051); o Bridging visa R (Class WR) (Subclass 070); the applicant is the holder of one of the following temporary visas:; Temporary (Humanitarian Concern) visa (Class UO) (Subclass786); Temporary Safe Haven visa (Class UJ) (Subclass 449); Temporary Protection visa (Class XD) (Subclass 785); Safe Haven Enterprise visa (Class XE); Higher education Visa (subclass 573)', 'Up to AUD $5000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7943', 'https://search.studyaustralia.gov.au/scholarship/2027-semester-1-curtin-humanitarian-scholarship-future-students/1c720b717ee89ae6dfb1fa9434d6086e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2027 - Semester 1 - Curtin Humanitarian Scholarship (Future Students)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australia Awards Scholarships', 'Australia Awards Scholarship (AAS) are funded by Australian Government to provide higher education opportunities for people from developing countries to study in Australia to build the skills and knowledge to drive change as the next generation of global leaders. These scholarships aim to contribute to the development needs of Australia\'s partner countries in line with bilateral and regional agreements. Scholarships are mainly at postgraduate level however there is a limited number of undergraduate scholarships (country specific). Curtin will work with AAS recipients to equip you with the skills and knowledge you need to drive change and contribute to the economic and social development in your home country and build enduring connections within the community.', 'Please Contact Curtin University for more information', 'Please Contact Curtin University for more information', 'Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=990', 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarships/aeffe1368ecc0d3be7a6f908581c1911', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Curtin Global Future Leaders Scholarship ($10K)', 'Curtin University strives to give international students the opportunity to pursue their ambitions and gain a world-class education through the Curtin Global Future Leader Scholarship. This scholarship provides eligible students a one-off credit of AUD$10,000 against the tuition fee of the course they are undertaking.', 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Will be studying in an eligible Curtin undergraduate degree course, OR a Masters degree by coursework (your Course); Will be studying at a Curtin Western Australian campus (WA Campus) commencing in 2027; Will be studying at least 1.5 years (minimum of 300 credits) (Scholarship term) at the WA Campus; Achieved a Credit level in your academic status with the required Course-Weighted-Average or equivalent scores in your most recent and eligible course of study.; Are not enrolled in one of the following: (1) Not-for-Degree Exchange or Study Abroad program (2) campus transfer from a Curtin global campus (3) a recognised joint program at a Curtin Transnational Partner Location outside Australia; Will not be enrolled in one of the courses excluded from this Scholarship program. The list of Excluded courses is determined by Curtin University and may change without notice.; Are not a recipient of an international scholarship offered by Global Curtin in a previous course of study at Curtin that is incomplete.', 'Up to AUD $10000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7987', 'https://search.studyaustralia.gov.au/scholarship/curtin-global-future-leaders-scholarship-10k/c09137a5e1f93ee8fc7591832426817c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Curtin Global Future Leaders Scholarship ($10K)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Curtin Global Merit Scholarship', 'The Curtin Global Merit scholarship is designed to reward academic performance and empower students to continue their education and further their success in their chosen field. Eligible students will receive 20% off the tuition fee for the duration of the course.', 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Are enrolled in a Curtin undergraduate degree course OR a Master degree by coursework; Will be studying at a Curtin Western Australian campus (WA Campus) commencing in 2027 or 2028; Achieved Distinction status in your academic status with the required Course-Weighted Average or equivalent scores in your most recent and eligible course of study. This is determined by Curtin University and may change without notice; Are not enrolled in one of the following: (1) Not-for-Degree Exchange or Study Abroad program (2) campus transfer from a Curtin global campus (3) a recognised joint program at a Curtin Transnational Partner Location outside Australia; Will not be enrolled in one of the courses excluded from this Scholarship program. The list of Excluded courses is determined by Curtin University and may change without notice.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7986', 'https://search.studyaustralia.gov.au/scholarship/curtin-global-merit-scholarship/7c5d1fe2b1099be574eb603de128876c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Curtin Global Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Curtin Global Talent Scholarship', 'A dedicated scholarship for international students who have commenced their studies at one of Curtin\'s global campuses or in a recognised joint program at Curtin\'s offshore partner location. This scholarship provides eligible students who wish to transfer to the Curtin Western Australian campus for the remaining duration of their degree, with a one-off credit of AUD$10,000 towards their tuition fees.', 'This scholarship is only for:; International, full fee-paying, non-sponsored students of any nationality except Australian; Will be studying either an undergraduate or postgraduate degree by coursework (Course); Will be studying at a Curtin Western Australian campus (WA Campus) commencing in 2027; Will be studying at least one year (minimum of 200 credits) (Scholarship term) at the WA Campus; Are enrolled in one of the following: (1) campus transfer from a Curtin global campus of the same course level (2) a recognised joint program at a Curtin Transnational Partner Location outside Australia (3) Not-for-Degree Exchange or Study Abroad program', 'Up to AUD $10000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7994', 'https://search.studyaustralia.gov.au/scholarship/curtin-global-talent-scholarship/28bec936ceada8b303eee4ddcf385649', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Curtin Global Talent Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Curtin Student Guild Childcare Grant', 'Curtin Student Guild Childcare Grant is a SSAF funded program designed to assist current Curtin students who have demonstrated that financial hardship has prevented access to childcare while attending class, practicums, exams, supervisor meeting etc.', 'Currently enrolled Curtin student (Must provide Confirmation of Enrolment).; Primary carer for a child under the age of 12.; In receipt of a means tested Centrelink benefit or on low income (Must provide 3 months bank statements/transactions).; Have an unexpected need to access childcare services in order to satisfactorily meet the current study commitments.; With the assistance of the Guild’s Financial counsellor, demonstrate financial hardship', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=4051', 'https://search.studyaustralia.gov.au/scholarship/curtin-student-guild-childcare-grant/cc275a393ecb35130543d3f069fb31e0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Curtin Student Guild Childcare Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Curtin University top up scholarship - Vietnam Government PhD Scholarship (Project 89)', 'This Curtin top up scholarship supports high-achieving Vietnamese candidates to undertake a Doctor of Philosophy (PhD) at Curtin University, Perth Western Australia.', 'To be eligible to apply you must:; Be a citizen or permanent resident of Vietnam at the time of your application; Meet Curtin\'s PhD eligibility requirements.; Meet Curtin\'s English language proficiency requirements', 'Up to AUD $100000 — Curtin will provide the below benefits:; Top up living stipend up to the current Curtin PhD stipend rate to support students whilst studying in Australia (Curtin stipend rate is AUD $37,500 per annum in 2025. Curtin PhD Stipends a', 'Postgraduate', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=6612', 'https://search.studyaustralia.gov.au/scholarship/curtin-university-top-up-scholarship-vietnam-government-phd-scholarship-project-89/2bb4674c0cf48d6f53d386fc251e9254', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Curtin University top up scholarship - Vietnam Government PhD Scholarship (Project 89)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Global Scholars Program Scholarship', 'The Global Scholars program offers a global perspective and industry connections while completing a Curtin degree at two of our global campuses.', 'This scholarship is only for:; Students of the Global Scholars Program at Curtin; Are International, fee-paying, non-sponsored students of any nationality except Australian; have successfully completed 200 credits at one of Curtin\'s global campuses within two study periods, in a selected undergraduate degree course (Course) of the Global Scholars Program; Will be studying at least two years in duration (minimum of 400 credits) at the Perth Western Australia (Perth) Campus', 'Up to AUD $15000', 'Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7566', 'https://search.studyaustralia.gov.au/scholarship/global-scholars-program-scholarship/a897bb19dcc52cb1dfea239bcb27f9e8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Global Scholars Program Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'John Curtin Global Excellence Scholarship', 'Through the John Curtin Global Excellence Scholarship, eligible students will receive 40% off the tuition fee for the duration of the course. Curtin University is proud to award this prestigious scholarship to students who have demonstrated exceptional academic performance and a commitment to excellence in their studies.', 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Are enrolled in a Curtin undergraduate degree course OR a Master degree by coursework; Will be studying at a Curtin Western Australian campus (WA Campus) commencing in 2027 or 2028; Achieved a Course-Weighted Average (CWA) of 95% or equivalent scores in your most recent and eligible course of study. This is determined by Curtin University and may change without notice; Are not enrolled in one of the following: (1) Not-for-Degree Exchange or Study Abroad program (2) campus transfer from a Curtin global campus (3) a recognised joint program at a Curtin Transnational Partner Location outside Australia; Will not be enrolled in one of the courses excluded from this Scholarship program. The list of Excluded courses is determined by Curtin University and may change without notice.', 'This scholarship provides eligible students 40% off the tuition fee of the course they are undertaking.', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7985', 'https://search.studyaustralia.gov.au/scholarship/john-curtin-global-excellence-scholarship/7ab822cf002b4ccacc7ea2103c71e19e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'John Curtin Global Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Semester 2 - 2026 - Curtin Global Future Leaders Scholarship', 'Curtin University strives to give international students the opportunity to pursue their ambitions and gain a world-class education through the Curtin Global Future Leader Scholarship. This scholarship provides eligible students a one-off credit of AUD$12,500 against the tuition fee of the course they are undertaking.', 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Are enrolled in a non-quota Curtin undergraduate degree course or Master degree by coursework (Course); Will be studying at a Curtin Western Australian campus (WA Campus) commencing in a study period between May - December 2026; Will be studying at least 1.5 years (minimum of 300 credits) (Scholarship term) at the WA Campus; Achieved a strong Credit level or equivalent Course-Weighted-Average in your most recent and eligible course of study.', 'Up to AUD $12500', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7844', 'https://search.studyaustralia.gov.au/scholarship/semester-2-2026-curtin-global-future-leaders-scholarship/2ca651763e993507b91bc53999c99479', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Semester 2 - 2026 - Curtin Global Future Leaders Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Semester 2 - 2026 - Curtin Global Future Leaders Scholarship ($10K)', 'Curtin University strives to give international students the opportunity to pursue their ambitions and gain a world-class education through the Curtin Global Future Leader Scholarship. This scholarship provides eligible students a one-off credit of AUD$10,000 against the tuition fee of the course they are undertaking.', 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Are enrolled in a non-quota Curtin undergraduate degree course or Master degree by coursework (Course); Will be studying at a Curtin Western Australian campus (WA Campus) commencing in a study period between May - December 2026; Will be studying at least 1.5 years (minimum of 300 credits) (Scholarship term) at the WA Campus; Achieved a minimum Credit level or equivalent Course-Weighted-Average in your most recent and eligible course of study.', 'Up to AUD $10000', 'Postgraduate, Undergraduate / VET', NULL, 'https://scholarships.curtin.edu.au/Scholarship/?id=7856', 'https://search.studyaustralia.gov.au/scholarship/semester-2-2026-curtin-global-future-leaders-scholarship-10k/eb124cff4a1f53ffb4c344cae79c21f7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00301J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Semester 2 - 2026 - Curtin Global Future Leaders Scholarship ($10K)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '$15K Destination Australia Scholarships', 'Destination Australia is an Australian Government initiative, offering amounts of up to $15,000 (AUD) per year to eligible students who wish to study full time and live in regional Australia. Our Destination Australia scholarship program is open to international & domestic students who wish to study Animation, Games, Film, Audio & Music on-campus at SAE Byron Bay in 2024.', 'Applicants are to be domestic or onshore international students wishing to commence study in a Bachelor Program in 2024. NOTE: International students must be residing in Australia with a valid VISA.; Applicants must be a commencing student enrolled full time at the SAE Byron Bay (on-campus study); Scholarships will be prioritized to applicants from underrepresented groups such as low socio−economic status, those who are first in family to tertiary study, those living with a disability and First Nations people.; Must demonstrate and maintain residency in the Northern Rivers Region at the time of commencing study for the duration of the scholarship Northern.; Applicants must meet SAEs published domestic or international entry requirements.', 'Up to AUD $15000', 'Undergraduate / VET', NULL, 'https://sae.edu.au/how-to-apply/international-scholarships/', 'https://search.studyaustralia.gov.au/scholarship/15k-destination-australia-scholarships/ade2ca75bbd538bf8594e03e1603a27e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00312F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '$15K Destination Australia Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Destination Australia Scholarship', 'Destination Australia is an Australian Government initiative, offering amounts of up to $15,000 (AUD) per year to eligible students who wish to study full time and live in regional Australia. Our Destination Australia scholarship program is open to international & domestic students who wish to study Animation, Games, Film, Audio & Music on-campus at SAE Byron Bay in 2024.', 'Applicants are to be domestic or onshore international students wishing to commence study in a Bachelor Program in 2024. NOTE: International students must be residing in Australia with a valid VISA.; Applicants must be a commencing student enrolled full time at the SAE Byron Bay (on-campus study); Scholarships will be prioritized to applicants from underrepresented groups such as low socio−economic status, those who are first in family to tertiary study, those living with a disability and First Nations people.; Must demonstrate and maintain residency in the Northern Rivers Region at the time of commencing study for the duration of the scholarship Northern.; Applicants must meet SAEs published domestic or international entry requirements.', 'Up to AUD $15000', 'Undergraduate / VET', NULL, 'https://sae.edu.au/how-to-apply/domestic-scholarships/', 'https://search.studyaustralia.gov.au/scholarship/destination-australia-scholarship/082d9016f7acd51c7d781de6582a73d9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00312F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Destination Australia Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Old Grammarians Society Bursary', NULL, 'The Old Grammarian Bursary is available to a student for entry into Year 9 and who is the daughter of an Old Grammarian. The Scholarship award is approximately $2500 per annum and will be awarded on the basis of the academic merit, determined from sitting the AAS test and a subsequent interview with the Principal.', 'Contributes towards tuition fees and books for the duration of enrolment.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/old-grammarians-society-bursary/7645f33cfa10f116f9cdb0dccb31f9cd', 'https://search.studyaustralia.gov.au/scholarship/old-grammarians-society-bursary/7645f33cfa10f116f9cdb0dccb31f9cd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00322D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Old Grammarians Society Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', NULL, 'For entry into Years 4 to 11. Based on an exam, application form, school reports and an interview.', 'Covers 30% or 50% of tuition fees for the student\'s remaining period of education, subject to her continuing superior performance and her contribution to the life of the School.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/3836e83996c438a2151e522049181fe1', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/3836e83996c438a2151e522049181fe1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00324B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence Scholarship', NULL, 'For entry into Years 4 to 11 in key areas of Performing Arts, Sport & PE, Science and Visual Arts. Based on an exam, application form, school reports and an interview.', 'Covers 30% or 50% of tuition fees for the student\'s remaining period of education, subject to her continuing superior performance and her contribution to the life of the School.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship/f8b3a5bf81bb39b6de01cd7bfa211d39', 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarship/f8b3a5bf81bb39b6de01cd7bfa211d39', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00324B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music (Instrumental & Voice) Scholarships', NULL, 'For entry into Years 5 to 11. Based on an exam, application form, an audition and an interview. An AMEB level is preferable.', 'Covers 30% or 50% of tuition fees for the student\'s remaining period of education and 100% of music tuition fees for one instrument for the duration of enrolment.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-voice-scholarships/a9e61ae519dfbc6cf846083db1555b41', 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-voice-scholarships/a9e61ae519dfbc6cf846083db1555b41', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00324B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music (Instrumental & Voice) Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'VCE WAVES Scholarship', NULL, 'For entry into Years 10 & 11. Based on an exam, academic record, CV and an interview.', 'Covers 30% or 50% of tuition fees for the duration of the enrolment.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/vce-waves-scholarship/deae24d565c62467774cb54b71146a1c', 'https://search.studyaustralia.gov.au/scholarship/vce-waves-scholarship/deae24d565c62467774cb54b71146a1c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00324B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'VCE WAVES Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Oxley academic scholarships', NULL, 'All current and prospective students applying for a scholarship must sit a scholarship examination (cost: $110*).', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/oxley-academic-scholarships/a39347238fda5b31f26f0e19dcceb573', 'https://search.studyaustralia.gov.au/scholarship/oxley-academic-scholarships/a39347238fda5b31f26f0e19dcceb573', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00331C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Oxley academic scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', NULL, 'The Academic Scholarship provides educational opportunity to students entering Years 5 to 10 with high academic potential and an exceptional academic record.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/c2d0847b613a4e256ae191d85a10bfa7', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/c2d0847b613a4e256ae191d85a10bfa7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00345G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'All Rounder Scholarship', NULL, 'Available to students who are enthusiastic and reliable contributors to all facets of life, the All Rounder Scholarship aims to provide educational opportunity to students who would be considered by their peers to be a visible role model of holistic education.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/all-rounder-scholarship/fc3211810d1b0a52a4131f3763c61b1d', 'https://search.studyaustralia.gov.au/scholarship/all-rounder-scholarship/fc3211810d1b0a52a4131f3763c61b1d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00345G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'All Rounder Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Contributing Citizen Scholarship', 'Our Contributing Citizen Scholarships are awarded to new students who have already demonstrated strong community spirit and a desire to make a difference to the world around them.', 'While demonstrated leadership and community service is a significant factor, we also want our students to develop their life skills across a broad range of competencies, and other areas of strength or passion are well regarded. This may include sport, the performing arts, visual arts or design, science and technology, environmental sustainability, politics, social justice, academia, or other community endeavours.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/contributing-citizen-scholarship/f4e21f23ba668f25a9b5b493f4362a93', 'https://search.studyaustralia.gov.au/scholarship/contributing-citizen-scholarship/f4e21f23ba668f25a9b5b493f4362a93', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00345G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Contributing Citizen Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Head of the School Scholarship', NULL, 'Open to one new male student and one new female student looking to enter the School in Year 7, the Head of the School Scholarship provides educational opportunity to students with proven academic performance and high potential, but who do not have the financial means to experience a St Michael’s education.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/head-of-the-school-scholarship/650c0b412c744f430e56b906abf8c2d0', 'https://search.studyaustralia.gov.au/scholarship/head-of-the-school-scholarship/650c0b412c744f430e56b906abf8c2d0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00345G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Head of the School Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'High Achiever Scholarship', 'High Achiever Scholarships recognise students who have demonstrated outstanding talent in one or more areas of endeavour and who wish to continue to develop those talents. It is expected that students who receive a High Achiever Scholarships will remain committed to nurturing their talents and enriching the School through active participation in School programs.\r\n\r\nThese scholarships are not restricted to academic achievements, and applications are welcomed from new and current students who excel in one or more of the following:  sport, the performing arts – dance, drama, voice or instrumental music, visual arts and design, science and technology.', 'Students who have an outstanding academic record and can demonstrate excellence in two or more areas of endeavour are invited to apply for the High Achiever Scholarship. Areas of endeavour might include a specific academic subject, sport, the arts, design, leadership or community service.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/high-achiever-scholarship/308db076f187e247f3d094a60304d9f4', 'https://search.studyaustralia.gov.au/scholarship/high-achiever-scholarship/308db076f187e247f3d094a60304d9f4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00345G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'High Achiever Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Judith Whitworth Science, Maths and Technology Scholarship for Girls', 'A female student whose area of excellence is Science, Maths and/or Technology may be awarded the Judith Whitworth Science, Maths and Technology Scholarship for girls.', 'The Judith Whitworth Scholarship supports and promotes girls in Mathematics and Science at St Michael’s and beyond. The Whitworth Scholarship encourages young women to not only excel in Maths and Science but also look to a thriving career in the STEM fields.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/judith-whitworth-science-maths-and-technology-scholarship-for-girls/b325c71e4e246b37fff5ed93edf12a36', 'https://search.studyaustralia.gov.au/scholarship/judith-whitworth-science-maths-and-technology-scholarship-for-girls/b325c71e4e246b37fff5ed93edf12a36', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00345G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Judith Whitworth Science, Maths and Technology Scholarship for Girls') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarship', 'Performing Arts and Music are central to life at St Michael\'s Grammar, which is why we offer comprehensive Performing Arts Scholarships and Music Scholarships to attract and support  students with exceptional talent. These Scholarships recognise creativity, ability, and leadership. Scholarships are open to students entering Year 5-11, providing opportunities to grow as artists while experiencing all that St Michael’s has to offer.', 'Providing educational opportunity to talented young musicians entering Years 7 to 9, the Music Scholarship is open to students with a commitment and passion for music and learning an instrument.', 'See scholarship details', 'Secondary schooling', NULL, 'https://www.stmichaels.vic.edu.au/enrolments/scholarships/performing-arts-and-music-scholarships', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/a0baf527c7aa7e06c4fd5f89e4ba81d7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00345G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Gidleigh Scholarship', NULL, 'Through the generous endowment of a former St Michael’s Chaplain and Board member, the Gidleigh Scholarship provides an educational opportunity to a student in Year 10 who, for financial or other reasons, would not ordinarily be able to attend, or continue their studies, at St Michael’s.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/the-gidleigh-scholarship/3812d41ac33a869ce95caf2441d3e99b', 'https://search.studyaustralia.gov.au/scholarship/the-gidleigh-scholarship/3812d41ac33a869ce95caf2441d3e99b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00345G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Gidleigh Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Achievement & Leadership Scholarship', 'Academic Achievement and Leadership Scholarships are awarded on the basis of the student’s results from an independent academic examination, as well as their completed application, NAPLAN results, school reports and accompanying documentation. Students will also need to demonstrate broader involvement and engagement in co- and extra-curricular activities outside the classroom. Academic performance must be maintained throughout the holder’s journey through the School. Shortlisted candidates will attend an interview with the Principal or Vice Principal.', 'Academic Achievement and Leadership Scholarships are awarded on the basis of the student’s results from an independent academic examination, as well as their completed application, NAPLAN results, school reports and accompanying documentation. Students will also need to demonstrate broader involvement and engagement in co- and extra-curricular activities outside the classroom. Academic performance must be maintained throughout the holder’s journey through the School. Shortlisted candidates will attend an interview with the Principal or Vice Principal.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-achievement-leadership-scholarship/25bcaf5aca25ece29d6fc6bf2be40ed6', 'https://search.studyaustralia.gov.au/scholarship/academic-achievement-leadership-scholarship/25bcaf5aca25ece29d6fc6bf2be40ed6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00348E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Achievement & Leadership Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Future Voices (General Excellence) Scholarship', 'Future Voices Scholarships are awarded on the basis of the student’s application which will demonstrate a balance of academic potential and commitment, leadership qualities and involvement, commitment to a range of co-and extra-curricular activities, and willingness to contribute across multiple facets of school life. This may be in the areas of sport, community or public service, environmental responsibility, or other fields of significance. Both leadership and involvement, must be maintained throughout the holder’s journey through the School.\r\n\r\nAll Future Voices applicants are required to sit an independent academic examination and short-listed candidates will attend an interview with the Principal or Vice Principal.', 'Future Voices Scholarships are awarded on the basis of the student’s application which will demonstrate a balance of academic potential and commitment, leadership qualities and involvement, commitment to a range of co-and extra-curricular activities, and willingness to contribute across multiple facets of school life. This may be in the areas of sport, community or public service, environmental responsibility, or other fields of significance. Both leadership and involvement, must be maintained throughout the holder’s journey through the School.\r\n\r\nAll Future Voices applicants are required to sit an independent academic examination and short-listed candidates will attend an interview with the Principal or Vice Principal.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/future-voices-general-excellence-scholarship/06e40213f813792534c5893992407c57', 'https://search.studyaustralia.gov.au/scholarship/future-voices-general-excellence-scholarship/06e40213f813792534c5893992407c57', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00348E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Future Voices (General Excellence) Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarship', 'Music Scholarships are offered on the basis of the student’s music audition as well as the results from the independent academic examination. During the audition students must demonstrate outstanding musical ability. Students are required to play two contrasting pieces on their main instrument and arrange for their own accompanist to attend the audition.\r\n\r\nCommitment to tuition and involvement in ensembles and performance must be maintained throughout the holder’s journey through the school.\r\n\r\nYears 7 and 8 entry\r\n\r\nString and Woodwind instruments must be at Grade 4 AMEB standard or above\r\nBrass instruments must be at Grade 2 AMEB standard or above\r\nYear 9, 10 and 11 entry\r\n\r\nString and Woodwind instruments must be at Grade 5 AMEB standard or above\r\nBrass instruments must be at Grade 3 AMEB standard or above\r\nAuditions will take place at Tintern Grammar', 'Music Scholarships are offered on the basis of the student’s music audition as well as the results from the independent academic examination. During the audition students must demonstrate outstanding musical ability. Students are required to play two contrasting pieces on their main instrument and arrange for their own accompanist to attend the audition.\r\n\r\nCommitment to tuition and involvement in ensembles and performance must be maintained throughout the holder’s journey through the school.\r\n\r\nYears 7 and 8 entry\r\n\r\nString and Woodwind instruments must be at Grade 4 AMEB standard or above\r\nBrass instruments must be at Grade 2 AMEB standard or above\r\nYear 9, 10 and 11 entry\r\n\r\nString and Woodwind instruments must be at Grade 5 AMEB standard or above\r\nBrass instruments must be at Grade 3 AMEB standard or above\r\nAuditions will take place at Tintern Grammar', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/320469dbbaa8559b4624d803c3be9e4d', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/320469dbbaa8559b4624d803c3be9e4d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00348E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Performing Arts Scholarship', 'Performing Arts Scholarships are offered on the basis of the student’s audition in either drama, dance or musical theatre or a combination of these areas as well as the results from the independent academic examination. Students are required to perform two contrasting pieces in their chosen area and arrange an accompanist to attend the audition if required.\r\n\r\nPerforming Arts Applicants will be assessed using a combination of the following selection criteria:\r\n\r\nAbility to demonstrate excellence in drama, dance or musical theatre performance, or a combination of these areas.\r\nPreparedness to fully engage in the life of the School and participate in a range of Performing Arts co-curricular activities.\r\nA commitment to the Performing Arts at Tintern Grammar through academic study in Drama and/or Theatre Studies through to Year 12.\r\nA willingness to uphold the School’s compass values.\r\nAudition Performance of two contrasting pieces that shows ability in the chosen area/s.\r\nPerforming Arts Scholarship auditions will take place at Tintern Grammar', 'Performing Arts Scholarships are offered on the basis of the student’s audition in either drama, dance or musical theatre or a combination of these areas as well as the results from the independent academic examination. Students are required to perform two contrasting pieces in their chosen area and arrange an accompanist to attend the audition if required.\r\n\r\nPerforming Arts Applicants will be assessed using a combination of the following selection criteria:\r\n\r\nAbility to demonstrate excellence in drama, dance or musical theatre performance, or a combination of these areas.\r\nPreparedness to fully engage in the life of the School and participate in a range of Performing Arts co-curricular activities.\r\nA commitment to the Performing Arts at Tintern Grammar through academic study in Drama and/or Theatre Studies through to Year 12.\r\nA willingness to uphold the School’s compass values.\r\nAudition Performance of two contrasting pieces that shows ability in the chosen area/s.\r\nPerforming Arts Scholarship auditions will take place at Tintern Grammar', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/performing-arts-scholarship/8b65b9eebea03f2b9de0edce3b5b4e14', 'https://search.studyaustralia.gov.au/scholarship/performing-arts-scholarship/8b65b9eebea03f2b9de0edce3b5b4e14', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00348E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Performing Arts Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Social Justice Scholarship', 'Social Justice Scholarships will be awarded on the basis of the student’s application which will demonstrate a balance of academic potential and commitment, leadership qualities and involvement, and a commitment to a range of co-and extra-curricular activities. In addition, a willingness to contribute across multiple facets of school life as well as a demonstration of how they have made a positive impact on their local or global communities and a commitment to continue this involvement in leadership, community and social justice activities must be maintained throughout the holder’s journey through the School.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with the Principal and any additional information as required during the application process.\r\n\r\nThis scholarship is aimed at those who would not normally have the financial means to attend Tintern Grammar. These scholarships are means tested and shortlisted candidates will be required to provide financial disclosure upon request.', 'The scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with the Principal and any additional information as required during the application process.\r\n\r\nThis scholarship is aimed at those who would not normally have the financial means to attend Tintern Grammar. These scholarships are means tested and shortlisted candidates will be required to provide financial disclosure upon request.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/social-justice-scholarship/63117d78170d96aa3cef0d1caa0a6c53', 'https://search.studyaustralia.gov.au/scholarship/social-justice-scholarship/63117d78170d96aa3cef0d1caa0a6c53', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00348E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Social Justice Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Dr Sylvia Walton AO Alumni Scholarship', 'This scholarship is awarded to a female child of a past student of the School and is available for students entering Years 7 to 11 in 2024 and is intended for families who would not normally have the financial means to attend Tintern Grammar.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and any additional information as required during the application process. This scholarship is means tested, and shortlisted candidates will be required to provide financial disclosure upon request.', 'This scholarship is awarded to a female child of a past student of the School and is available for students entering Years 7 to 11 in 2024 and is intended for families who would not normally have the financial means to attend Tintern Grammar.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and any additional information as required during the application process. This scholarship is means tested, and shortlisted candidates will be required to provide financial disclosure upon request.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/the-dr-sylvia-walton-ao-alumni-scholarship/97455d37685897b2357310076d7f6fa6', 'https://search.studyaustralia.gov.au/scholarship/the-dr-sylvia-walton-ao-alumni-scholarship/97455d37685897b2357310076d7f6fa6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00348E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Dr Sylvia Walton AO Alumni Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Henry and Jean Speagle Scholarship', 'Henry Speagle joined the Tintern Community some 60 years ago when he was appointed to the School Council by the Archbishop-In-Council. He remained a member of the School Council for nearly 40 years; in the final years of his term he was the Deputy Chairman. Among many contributions, his skill as an historian was put to good use in supporting the production of the School’s centenary history in 1977. Jean stood by Henry’s side on many occasions, supporting and enjoying many formal and celebratory events and activities, particularly those with a musical flavour. In 2001 Henry was inducted as a Life Governor of the School and in further recognition, in 1991, the Science block of classrooms was named in his honour, recognising his enormous contribution to the strength and development of Tintern Grammar. In 2019 the Speagle family was honoured when the building was refurbished and renamed as the Speagle Science Centre. Now in her 95th year, Jean continues to enjoy her connection to the Tintern Community and even though unable to attend in person, keeps up to date with the happenings around the school.The Henry and Jean Speagle Scholarship has been pledged to the school by Henry and Jean and their son. Following Henry’s death in 2020, the Speagle family made an initial gift to the Scholarship Fund. The family will continue to build the corpus for the Scholarship (including through a bequest) until a 50% Scholarship can be awarded in perpetuity to suitable recipients.Applicants must meet all or most of the criteria to be considered for the scholarship.The conditions are:A female student who does not currently attend Tintern GrammarFrom a family who for financial reasons could not otherwise afford the benefit of a Tintern educationA family (or student) who has an affiliation and is a practising member of a recognised Christian denomination, preferably Anglican.The scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and meeting the above criteria. This scholarship is aimed at those who would not normally have the financial means to attend Tintern Grammar and is means tested. Shortlisted candidates will be required to provide financial disclosure upon request.', 'Henry Speagle joined the Tintern Community some 60 years ago when he was appointed to the School Council by the Archbishop-In-Council. He remained a member of the School Council for nearly 40 years; in the final years of his term he was the Deputy Chairman. Among many contributions, his skill as an historian was put to good use in supporting the production of the School’s centenary history in 1977. Jean stood by Henry’s side on many occasions, supporting and enjoying many formal and celebratory events and activities, particularly those with a musical flavour. In 2001 Henry was inducted as a Life Governor of the School and in further recognition, in 1991, the Science block of classrooms was named in his honour, recognising his enormous contribution to the strength and development of Tintern Grammar. In 2019 the Speagle family was honoured when the building was refurbished and renamed as the Speagle Science Centre. Now in her 95th year, Jean continues to enjoy her connection to the Tintern Community and even though unable to attend in person, keeps up to date with the happenings around the school.The Henry and Jean Speagle Scholarship has been pledged to the school by Henry and Jean and their son. Following Henry’s death in 2020, the Speagle family made an initial gift to the Scholarship Fund. The family will continue to build the corpus for the Scholarship (including through a bequest) until a 50% Scholarship can be awarded in perpetuity to suitable recipients.Applicants must meet all or most of the criteria to be considered for the scholarship.The conditions are:A female student who does not currently attend Tintern GrammarFrom a family who for financial reasons could not otherwise afford the benefit of a Tintern educationA family (or student) who has an affiliation and is a practising member of a recognised Christian denomination, preferably Anglican.The scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and meeting the above criteria. This scholarship is aimed at those who would not normally have the financial means to attend Tintern Grammar and is means tested. Shortlisted candidates will be required to provide financial disclosure upon request.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/the-henry-and-jean-speagle-scholarship/468d45807006054650662cfbbb47df19', 'https://search.studyaustralia.gov.au/scholarship/the-henry-and-jean-speagle-scholarship/468d45807006054650662cfbbb47df19', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00348E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Henry and Jean Speagle Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Mike Blood Alumni Scholarship', 'This scholarship is awarded to a male child of a past student of the School and is available for students entering into Years 7 to 11 in 2024 and is intended for families who would not normally have the financial means to attend Tintern Grammar.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and any additional information as required during the application process. This scholarship is means tested, and shortlisted candidates will be required to provide financial disclosure upon request.', 'This scholarship is awarded to a male child of a past student of the School and is available for students entering into Years 7 to 11 in 2024 and is intended for families who would not normally have the financial means to attend Tintern Grammar.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and any additional information as required during the application process. This scholarship is means tested, and shortlisted candidates will be required to provide financial disclosure upon request.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/the-mike-blood-alumni-scholarship/ba9842a173503c74e4cfabdfe5739480', 'https://search.studyaustralia.gov.au/scholarship/the-mike-blood-alumni-scholarship/ba9842a173503c74e4cfabdfe5739480', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00348E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Mike Blood Alumni Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Excellence Scholarships', NULL, 'Entry in Years 3 and 5 in 2021\r\nEntry in Years 4 to 9 in 2022', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-excellence-scholarships/9a860ebcc34602c391a3bbdccff487d6', 'https://search.studyaustralia.gov.au/scholarship/academic-excellence-scholarships/9a860ebcc34602c391a3bbdccff487d6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00349D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Excellence Scholarships') LIMIT 1;
