INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Financial Need Scholarship', NULL, 'Financial need scholarships are available to students who, because of financial circumstances would otherwise be unable to attend The Glennie School.  Students sit the scholarship test and will be assessed on academic performance and general ability.  Documentation certifying the family’s financial circumstances is also required.  This information is treated in confidence.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/financial-need-scholarship/1fb8df52e6643ed8686209817d16766f', 'https://search.studyaustralia.gov.au/scholarship/financial-need-scholarship/1fb8df52e6643ed8686209817d16766f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00496D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Financial Need Scholarship') LIMIT 1;
