INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarship', NULL, 'Preference is given to orchestral instruments, although consideration may be given to pianists and singers of excellence. Must meet minimum AMEB level and have strong academic ability. Based on an audition and an interview.', 'Half remission of tuition fees and full remission of music tuition fees for one instrument either in school tuition or outside tuition.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/b6e0326af5811949ba5f9992c528ebfa', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/b6e0326af5811949ba5f9992c528ebfa', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00577C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', 'Academic Scholarships are awarded to students who demonstrate outstanding academic potential. The scholarships are open to students in Years 6 and 9 in 2023 and will be offered for Years 7 and 10 in 2024. Applicants will sit the ACER Scholarship Examination on Saturday 25 February 2023.', 'Academic Scholarships for students entering Year 7 and Year 10 in 2024 are now open. Testing will take place on Saturday 25 February 2023 using the Academic Scholarship Exam prepared by the Australian Council of Educational Research (ACER). See our website for information on how to register. https://www.concordia.qld.edu.au/enrolment/scholarships', 'The awarding of a scholarship of financial subsidy of each scholarship is determined by the Head of College and the Scholarship Testing Committee. The amount is based on merit and achievement in testing.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/7a2db5ecc5972d90adee7355677eccdc', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/7a2db5ecc5972d90adee7355677eccdc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00581G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '10% Tuition fee discounts', 'A 10% reduction on registered tuition fees will be awarded to University of Tasmania international students who meet the eligibility requirements as outlined in the below bursary or scholarship theme areas.', 'Please contact University of Tasmania for further information.', '10% reduction in registered tuition fees for the duration of the course.', 'Postgraduate', NULL, 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/10-tuition-fee-discounts', 'https://search.studyaustralia.gov.au/scholarship/10-tuition-fee-discounts/6e92e903e350edd34bb9ee7f74a8842c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '10% Tuition fee discounts') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australian Government Research Training Program (RTP) Scholarships', 'Awarded competitively to students of exceptional research potential to assist with living costs while undertaking a Higher Degree by Research. Living Allowance', 'To be eligible for an RTP Stipend a candidate must not be receiving income from another source related to their Higher Degree by Research, to support the candidates general living costs while undertaking their research degree, if that income is greater than 75% of the candidates RTP Stipend rate. Income unrelated to the candidates research degree or income received for the candidates research degree, but not for the purpose of supporting general living costs, will not be taken into account; To be eligible for an RTP Fees Offset a candidate must not be receiving an equivalent award or scholarship from the Commonwealth Government designed to offset tuition fees for their Higher Degree by Research.; In 2025 all domestic applicants will be offered an RTP Fees Offset provided they are not receiving an equivalent award or scholarship from the Commonwealth designed to offset Higher Degree by Research tuition fees.; The scholarship holder is expected to diligently pursue the degree for which they are enrolled. Continued \r\npayment of the scholarship is therefore subject to the scholarship holder making satisfactory academic progress and terminates on the expiry of the scholarship or on submission of the thesis for examination, whichever is the sooner', 'Up to AUD $33511 — PhD: 3.5 years FTE. It is important to be aware that the duration of the scholarship is less than the maximum length of candidature, which is 4 years.; Masters: 2 years FTE.', 'Postgraduate', NULL, 'https://www.utas.edu.au/research/degrees/scholarships-and-fees', 'https://search.studyaustralia.gov.au/scholarship/australian-government-research-training-program-rtp-scholarships/193de31bd851abd2188f7d6fb3495270', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian Government Research Training Program (RTP) Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Early Acceptance Scholarship', 'This scholarship covers 15% of registered tuition fees for the duration of study up to a maximum of four years. Applicants must have an offer for an eligible course commencing in Summer School or Semester one 2026.', 'Please contact University of Tasmania for further information.', '15% reduction in registered tuition fees for the duration of the course.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/early-acceptance-scholarship', 'https://search.studyaustralia.gov.au/scholarship/early-acceptance-scholarship/74a0e4580cf9f67cac610b5cf696f4ff', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Early Acceptance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Feng Chia University Scholarship', 'This scholarship covers 20% of the registered tuition fees for two years of study in the Bachelor of Global Logistics and Maritime Management (P3E) for applicants from International School of Technology and Management (Business), Feng Chia University.', 'Please contact University of Tasmania for further information.', '20% reduction in registered tuition fees for the duration of the course.', 'Undergraduate / VET', NULL, 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/fcu-scholarship', 'https://search.studyaustralia.gov.au/scholarship/feng-chia-university-scholarship/dee62ece0a0bd13c1dc8453416909a21', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Feng Chia University Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Singapore Maritime Academy Scholarship', 'This scholarship covers 20% of registered tuition fees for one year of study in the Bachelor of Global Logistics and Maritime Management (P3E) for applicants from Singapore Maritime Academy.', 'Please contact University of Tasmania for further information.', '20% reduction in registered tuition fees for the duration of the course.', 'Undergraduate / VET', NULL, 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/singapore-maritime-academy-scholarship', 'https://search.studyaustralia.gov.au/scholarship/singapore-maritime-academy-scholarship/9f72a0f849c504586647877108f95e90', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Singapore Maritime Academy Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Tasmania Graduate Research Scholarship (TGRS)', 'Tasmania Graduate Research Scholarships are available across all research disciplines at the University of Tasmania and will be awarded to applicants with demonstrated research ability.', 'Be eligible to enrol in a full-time Masters by Research or Doctoral degree at the University of Tasmania in 2025; Not be receiving equivalent income to support their general living costs from another source related to their proposed research degree (equivalent being defined as greater than 75% of the base stipend rate).', 'Full-time candidates receive a stipend at the rate of AUD$33,511pa non-taxable (2025 rate, indexed annually); Part-time candidates receive a stipend at the rate of AUD$16,756pa taxable (2025 rate, indexed annually).; Scholarship holders may apply for', 'Postgraduate', NULL, 'https://www.utas.edu.au/research/degrees/scholarships-and-fees', 'https://search.studyaustralia.gov.au/scholarship/tasmania-graduate-research-scholarship-tgrs/6683f3cd4462fb9beeb9fa2e81545d0f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Tasmania Graduate Research Scholarship (TGRS)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Tasmanian International Scholarship', 'The Tasmanian International Scholarship is assessed on academic merit and provides eligible commencing international students with a 25% reduction in registered tuition fees for the duration of their course.', 'Please contact University of Tasmania for further information.', '25% reduction in registered tuition fees for the duration of the course.', 'Postgraduate', NULL, 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-international-scholarship', 'https://search.studyaustralia.gov.au/scholarship/tasmanian-international-scholarship/a61333963164da579dffc76150268362', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Tasmanian International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australia Awards Scholarships', 'The Australian Government offers Australia Awards Scholarships through the Department of Foreign Affairs and Trade. The scholarships aim to contribute to the developmental needs of Australia\'s partner countries by providing financial support to study in Australia.', 'Please Contact TAFE NSW International for more information about Eligibility', 'What\'s included?; Full tuition fees, Return air travel, Contribution to Living Expenses (CLE), Introductory Academic Program (IAP), Overseas Student Health Cover (OSHC), Pre-course English (PCE) fees–if deemed necessary.', 'Undergraduate / VET', NULL, 'https://www.tafensw.edu.au/international/apply/scholarships', 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarships/250921b79d7e9a228d330e874f548609', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00591E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Semester 1, 2025 - $500 Vocational course scholarship', 'TAFE NSW is committed to helping you build specialised skills, gain qualifications and achieve your personal and professional goals.', 'Applicants will be assessed on merit by the scholarship panel', '$500 (AUD) credit applied to your vocational course tuition fees', 'Undergraduate / VET', NULL, 'https://www.tafensw.edu.au/international/apply/scholarships', 'https://search.studyaustralia.gov.au/scholarship/semester-1-2025-500-vocational-course-scholarship/f4916e008b41f02a0a0a58b34820a619', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00591E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Semester 1, 2025 - $500 Vocational course scholarship') LIMIT 1;
