INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', NULL, 'For entry into Years 7, 9 and 10. Based on English and Maths exams and an interview. May involve a family means test.', 'Various amounts, but usually half or full remission of tuition fees. May also provide some remission of boarding fees.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/046c6bc0cecbcb4a53530fd2b682d685', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/046c6bc0cecbcb4a53530fd2b682d685', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00624A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Boarding Scholarship', NULL, 'For entry into Year 9. Open to children of families who live in country areas or overseas. Based on English and Maths exams and an interview. May involve a family means test.', 'Covers up to 100 per cent of boarding fees for the duration of enrolment.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/boarding-scholarship/0b6dc14630d87b96fdd9951dcd480db7', 'https://search.studyaustralia.gov.au/scholarship/boarding-scholarship/0b6dc14630d87b96fdd9951dcd480db7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00624A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Boarding Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Means Tested Scholarship', NULL, 'For entry into Years 7 and 9. Open to students who are experiencing financial disadvantage and would otherwise be unable to attend the school. Based on English and Maths exams, school reports, sporting ability, and good character.', 'Covers up to 100 per cent of tuition fees and boarding fees for the duration of enrolment.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/means-tested-scholarship/7e3fa1fd3180dbf461beefd8b2f4e311', 'https://search.studyaustralia.gov.au/scholarship/means-tested-scholarship/7e3fa1fd3180dbf461beefd8b2f4e311', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00624A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Means Tested Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarship (Junior)', NULL, 'For entry into Year 7. Based on English and Maths exams and an audition. Must meet minimum AMEB level.', 'Partial or full remission of tuition fees and covers up to 100 per cent of music tuition fees.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-junior/561078f29c4d2803d101d33c3b19963e', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-junior/561078f29c4d2803d101d33c3b19963e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00624A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarship (Junior)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarship (Senior)', NULL, 'For entry into Years 9-10. Based on English and Maths exams and an audition. Must meet minimum AMEB level.', 'Full remission of music tuition fees. May provide partial or full remission of tuition fees.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-senior/3d8b5d7816e37cbf01e60733a23ea883', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-senior/3d8b5d7816e37cbf01e60733a23ea883', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00624A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarship (Senior)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarships (Years 5-10)', NULL, 'All academic scholarships are based on the results of an ACER examination. It is offered to both new and continuing students.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-years-5-10/2782f70a3dc178f971eb210b92bf59bf', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-years-5-10/2782f70a3dc178f971eb210b92bf59bf', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00629G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarships (Years 5-10)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'All-Rounder Boarding Scholarships (Years 7-11)', NULL, 'Boarding scholarships are offered to new students living in regional or remote areas of Australia who wish to enter Loreto College. The All-Rounder Boarding Scholarship is based on presentation of a portfolio. The applicant will not only provide evidence of a growth mindset with regards to academic success but also demonstrate how they encapsulate the values of a Loreto education through their contribution to their school and broader community in such things as co-curricular activities, leadership and social justice.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/all-rounder-boarding-scholarships-years-7-11/32b8d34e83b83e78b974f445a20d8273', 'https://search.studyaustralia.gov.au/scholarship/all-rounder-boarding-scholarships-years-7-11/32b8d34e83b83e78b974f445a20d8273', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00629G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'All-Rounder Boarding Scholarships (Years 7-11)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'All-Rounder Scholarships (Years 5-11)', NULL, 'The All-Rounder scholarships are offered to new students wishing to enter Loreto College. The All-Rounder Scholarship is based on presentation of a portfolio. The applicant will not only provide evidence of a growth mindset with regards to academic success but also demonstrate how they encapsulate the values of a Loreto education through their contribution to their school and broader community in such things as co-curricular activities, leadership and social justice.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/all-rounder-scholarships-years-5-11/013f287650aae4c0f4ad0c16555eb9bc', 'https://search.studyaustralia.gov.au/scholarship/all-rounder-scholarships-years-5-11/013f287650aae4c0f4ad0c16555eb9bc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00629G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'All-Rounder Scholarships (Years 5-11)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Gonzaga Barry Scholarship (full bursary) for Years 7-11', NULL, 'The Gonzaga Barry Scholarship is offered to new students wishing to enter Loreto College. A maximum of two scholarships will be awarded annually. To be eligible the student must be a daughter, granddaughter, or niece of an Old Scholar from Loreto College Marryatville. The scholarship is means-tested and is directed towards students who would not be able to attend Loreto College due to financial hardship. Students must also meet the all-rounder scholarship criteria. The all-rounder scholarship is based on presentation of a portfolio. The student will not only provide evidence of a growth mindset with regard to academic success but also demonstrate how they encapsulate the values of a Loreto education through their contribution to their schoo', 'Gonzaga Barry ibvm was the foundress of Loreto Education in Australia. Her passion for girls’ education had a significant influence on the development of education across Australia. In order to celebrate Gonzaga Barry’s vision for the education of gi', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/gonzaga-barry-scholarship-full-bursary-for-years-7-11/d83fda061999ee38f9f6b31521c397e2', 'https://search.studyaustralia.gov.au/scholarship/gonzaga-barry-scholarship-full-bursary-for-years-7-11/d83fda061999ee38f9f6b31521c397e2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00629G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Gonzaga Barry Scholarship (full bursary) for Years 7-11') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarship (Years 5-11)', NULL, 'The Music Scholarship is offered to new and continuing students from Years 5-11. The applicant will provide a portfolio with copies of recent school reports and any other documentation that is relevant in promoting the music scholarship application. Students should be able to demonstrate a minimum performance standard of Grade 2 AMEB (or equivalent) on their first instrument or voice. Scholarship are awarded primarily on the basis of an audition. Scholarship holders agree to contribute actively and generously to the co-curricular program and performance activities of the College. Scholarship holders who are involved in other performance groups outside school are expected to give priority to scheduled school co-curricular events if there is', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-years-5-11/9329b7929a94e877566f953789e8d4b7', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-years-5-11/9329b7929a94e877566f953789e8d4b7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00629G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarship (Years 5-11)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2025 International Scholarship', 'We are pleased to announce that the 2025 International Scholarship is now available to AIM students commencing study in 2025.\r\n\r\nTo qualify for a scholarship, you must first complete your AIM enrolment application to study at AIM.', 'To qualify for a scholarship, you must first complete your AIM enrolment application to study at AIM.', 'This scholarship is valued at up to 10% of tuition for the full duration of the course. Students must pass all classes/units to maintain the scholarship.', 'Undergraduate / VET', NULL, 'https://aim.edu.au/how-to-apply/international/international-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/2025-international-scholarship/ba79a682db37a3f88db870169731df4d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00665C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2025 International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Champagnat Trust', NULL, 'The Champagnat Trust has been established to provide assistance to student’s in necessitous circumstances selected on the basis of financial need. The Trust takes its name from the founder of the Marist Brothers, St. Marcellin Champagnat. These bursaries offer half or part thereof of tuition, boarding (where applicable) and compulsory fees for students entering Years 7 to 12. Families applying for fee relief in the form of a bursary are asked to completing a confidential Champagnat Trust Application Form and provide supporting documentation.', 'Please visit our website for more information - https://www.marash.qld.edu.au/bursaries', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/champagnat-trust/fcb6f70d895cd7466262aec3bb91933e', 'https://search.studyaustralia.gov.au/scholarship/champagnat-trust/fcb6f70d895cd7466262aec3bb91933e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00670F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Champagnat Trust') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Global Ministry Bursary', 'The fund supports international students who have been involved in Christian ministry in the Australian context and who are seeking further theological education to equip them for ministry and leadership.   Under God, it is our prayer that this fund will enable many men and women to be trained to be sent into the world to proclaim the gospel.', 'Please Contact Moore Theological College for more information about Eligibility', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://moore.edu.au/bursaries-and-scholarships/global-ministry-bursary/', 'https://search.studyaustralia.gov.au/scholarship/global-ministry-bursary/4768777b14a9ebd9fcd8112bde52c0c5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00682B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Global Ministry Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Bursary', 'The International Student Bursary offers postgraduate and undergraduate bursaries for the growing number of church leaders seeking training at Moore in order to return to their home countries. Increasingly, Moore College is equipping and sending graduates to varied ministries around the world, including overseas and Australian students who commit to global ministries. The majority of international students who join us at Moore return to varied ministries in Asia, Africa, Europe and North America, primarily as preachers or missionaries.', 'Please Contact Moore Theological College', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://moore.edu.au/bursaries-and-scholarships/international-student-award/', 'https://search.studyaustralia.gov.au/scholarship/international-student-bursary/3f1e8e88d103c35ed937fd9c6ce34e67', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00682B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Overseas DBT Bursary', 'The Overseas DBT Bursary program offers an external program in the international student’s home country typically to equip them for an existing ministry. The scholarship provides up to 75% of the fees payable for each successful recipient for the 8 subjects within the Diploma of Biblical Theology. Recipients must be overseas students not resident in Australia, engaging in ministry in their home country, or preparing for a specific ministry role.', 'Please Contact Moore Theological College for more information about Eligibility', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://moore.edu.au/bursaries-and-scholarships/overseas-dbt-bursary/', 'https://search.studyaustralia.gov.au/scholarship/overseas-dbt-bursary/723a69fc81f6bf7d20ce97c1c987aba3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00682B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Overseas DBT Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarships', NULL, 'Awarded as a result of the ACER CSTP test.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships/bd5be5ead7fcd984b0867a6720f64460', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships/bd5be5ead7fcd984b0867a6720f64460', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00713M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ballet & Dance Scholarships', NULL, 'Offered for entry to Year 7. As a result of ACER testing, interview and audition by invitation.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/ballet-dance-scholarships/d9d121b66d2cc67b64b180c3f68d5382', 'https://search.studyaustralia.gov.au/scholarship/ballet-dance-scholarships/d9d121b66d2cc67b64b180c3f68d5382', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00713M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ballet & Dance Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Lucy Hill Means Tested Scholarships', NULL, 'Offered for entry to Year 10. Awarded as a result of the ACER testing, interview, academic records , participation in sport, the arts and contribution to the wider community and outcome of a means tested application.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/lucy-hill-means-tested-scholarships/2c3c476584849db206bb0e489e9e78b5', 'https://search.studyaustralia.gov.au/scholarship/lucy-hill-means-tested-scholarships/2c3c476584849db206bb0e489e9e78b5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00713M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Lucy Hill Means Tested Scholarships') LIMIT 1;
