INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Redlands Foundation Scholarship', NULL, 'For Year 7 2012. Strong academic record and the ability and desire to be involved in the range of extra-curricular activities - Sports, Cultural and Service. Must be Australian residents.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/redlands-foundation-scholarship/feff8cde046c334737aef7f182fc2c15', 'https://search.studyaustralia.gov.au/scholarship/redlands-foundation-scholarship/feff8cde046c334737aef7f182fc2c15', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00713M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Redlands Foundation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Higher Education Scholarships', 'Melbourne Polytechnic’s International Higher EducationScholarships are awarded to suitably qualifiedinternational students to pursue a full-time undergraduateor postgraduate program.10% International Higher', '10% International Higher Education Scholarship` Be a prospective international student for aMelbourne Polytechnic higher education course` Successfully achieved a 65% average (or equivalent) inprevious studies` 10% reduction in tuition fees` Applied across all study periods20% International Higher Education Scholarship` Be a prospective international student for a MelbournePolytechnic higher education course` Successfully achieved a 70% average (or equivalent) inprevious studies` 20% reduction in tuition fees` Applied across all study periods', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://search.studyaustralia.gov.au/scholarship/international-higher-education-scholarships/794fef3e15d4400b235f3fdf2e0ff3c1', 'https://search.studyaustralia.gov.au/scholarship/international-higher-education-scholarships/794fef3e15d4400b235f3fdf2e0ff3c1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00724G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Higher Education Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'NIDA Bursaries', 'A limited number of NIDA bursaries are available through the generosity of donors to NIDA and bequests.', 'Selection is based on financial need.', 'Up to AUD $2500 — The bursaries provide a small contribution to assist with living costs. Contributions usually range from $75 to $150 per fortnight.', 'Postgraduate, Undergraduate / VET', 'Creative arts', 'http://www.nida.edu.au/courses/undergraduate/scholarships', 'https://search.studyaustralia.gov.au/scholarship/nida-bursaries/f8708dfa8697b24898d51f30cd184060', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00756M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'NIDA Bursaries') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarship', 'TAS Music Scholarships are awarded to students with exceptional musical aptitude and interest. Applications are open to students in Year 7 to 11.', 'An audition is conducted by the Director of Music and recipients are selected based on academic and music achievement at the required level.', 'The maximum scholarship value will be 100% remission of current tuition fees. Music Scholarships are offered at the discretion of the Principal for the full period of a student’s time at the school, subject to the recipient demonstrating an outstandi', NULL, NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/5735a2e2d7cb8316fec181cb587b5c60', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/5735a2e2d7cb8316fec181cb587b5c60', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00770B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Aspiring Animators Scholarship', 'The UTS College Aspiring Animator\'s Scholarship is open to eligible international students commencing a Diploma of Animation Production at UTS College from semester 2, 2025 to semester 2, 2026.', 'Applicants must be international students (not Australian citizens, New Zealand citizens, or permanent residents of Australia).; Applicants must meet entry requirements for entry into the diploma, and scholarship eligibility criteria.', 'Up to AUD $8000', 'Undergraduate / VET', NULL, 'https://utscollege.edu.au/au/international-scholarships-aspiring-animators', 'https://search.studyaustralia.gov.au/scholarship/aspiring-animators-scholarship/d4b9eb26606e61aa409e47bd026540f2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Aspiring Animators Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Cambridge International Gateway Scholarship', 'To support international students to succeed in the Cambridge International AS and A Levels program, UTS College is offering the Cambridge International Gateway Scholarship, valued between A$12,000 and A$20,000 in program fee waivers for the two-year program.', 'To be eligible for this scholarship, you must:; be an international student (i.e. not an Australian citizen or New Zealand citizen or a permanent resident of Australia or New Zealand); meet all entry requirements for the UTS College Cambridge International AS and A Levels program; apply for and receive an offer letter (includes conditional offers) to commence the program in January 2026.', 'Up to AUD $20000', 'Postgraduate, Undergraduate / VET', NULL, 'https://utscollege.edu.au/au/programs/cambridge/gateway-scholarship', 'https://search.studyaustralia.gov.au/scholarship/cambridge-international-gateway-scholarship/5ba9208a12ea80134770d42b6348ac34', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Cambridge International Gateway Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Cambridge International Global Scholars Award and Cambridge International Excellence Award', 'We are giving young, high-achieving international students the opportunity to achieve a prestigious scholarship award towards our NEW Cambridge International AS and A Levels program. This is an exceptional opportunity for Year 10 students with a strong academic record, who seek a life-changing educational experience abroad and who are ready to start their journey in 2026!', 'To be eligible for this scholarship, you must:; be an international student (i.e. not an Australian citizen or New Zealand citizen or a permanent resident of Australia or New Zealand) from one of the following listed countries:; Peoples Republic of China; Vietnam, Indonesia, Thailand, Cambodia, Laos, Myanmar, Malaysia, Singapore, The Philippines, Brunei, Taiwan, Hong Kong (SAR), Macau, South Korea, Mongolia, Japan, Nepal or Bangladesh.; meet all entry requirements of the UTS College Cambridge International AS and A Levels program, apply for, and receive an offer letter (includes conditional offers) to commence the program in January 2026; meet the academic requirements for scholarship eligibility. Ask your agent for details.; apply using the scholarship application form; if shortlisted, be available to attend an interview (online or in person) with the Scholarship Selection Committee.', 'The Global Scholar Award: 100% of your first-year tuition fees (value approx. A$39,000). Four available globally.; The Excellence Award: 50% of your first-year tuition fees (value approx. A$19,500). Twelve available globally.', 'Postgraduate, Undergraduate / VET', NULL, 'https://utscollege.edu.au/au/programs/cambridge/scholarship', 'https://search.studyaustralia.gov.au/scholarship/cambridge-international-global-scholars-award-and-cambridge-international-excellence-award/c37c912fc8c69a022b72282d17609c03', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Cambridge International Global Scholars Award and Cambridge International Excellence Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Diploma Scholarship', 'UTS College Diploma Scholarships is open to eligible international students commencing a Diploma at UTS College in 2025 or 2026.', 'Applicants must be international students (these scholarships are not available to Australian citizens, New Zealand citizens, or permanent residents of Australia).; Applicants must meet the entry requirements for entry into a Diploma, and scholarship eligibility criteria.', 'Up to AUD $8000', 'Undergraduate / VET', NULL, 'https://utscollege.edu.au/au/international-scholarships-diploma', 'https://search.studyaustralia.gov.au/scholarship/diploma-scholarship/57c50bb4e46aa8ec13abbb742075a5b0', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Diploma Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'MEDIBANK International Education Scholarship', 'Each semester, the top performing student from the first stage of UTS Foundation Studies and the top performing student from the first stage of any diploma program, will each receive a A$4,000 contribution towards their UTS College tuition fees for the following semester. This amount will be divided if more than two students achieve the same results.', 'Students must have arranged their MEDIBANK OSHC through UTS College.; Students must be currently enrolled at UTS College in either UTS Foundation Studies or a UTS College diploma course.; Students achieved excellent academic performance (and maintained excellent attendance) in the first stage of the above course having undertaken the full study load.; This scholarship is open to international students only.', 'Up to AUD $4000', 'Undergraduate / VET', NULL, 'https://utscollege.edu.au/au/how-to-apply/scholarships/medibank-international-education-scholarship', 'https://search.studyaustralia.gov.au/scholarship/medibank-international-education-scholarship/8a884992051d22348216433c6b8fde6a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'MEDIBANK International Education Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Pathway Scholarship to UTS', 'This scholarship is open to international students and covers 50% of the cost of tuition fees for the duration of the undergraduate program at UTS. Six scholarships are awarded each year, three in each of the UTS Autumn and Spring session intakes.', 'Must be an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); Have completed a UTS College diploma in Sydney, Australia; Achieved an overall grade point average of 6.0 or above in your diploma; Meet the UTS admission criteria for the selected UTS undergraduate degree course; Commence your UTS undergraduate degree that directly articulates from your UTS College diploma in the next available intake', 'This scholarship is open to international students and covers 50% of the cost of tuition fees for the duration of the undergraduate program at UTS.', 'Undergraduate / VET', NULL, 'https://utscollege.edu.au/au/how-to-apply/scholarships/pathway-scholarship-to-uts', 'https://search.studyaustralia.gov.au/scholarship/pathway-scholarship-to-uts/567b528e92246fc367deb9b77ab07d91', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Pathway Scholarship to UTS') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The UTS Academic Merit International Scholarship - South', 'This scholarship is available to international students from Bangladesh, India, Nepal, Pakistan and Sri Lanka completing any UTS College academic program and enrolling in an undergraduate or postgraduate coursework program at UTS in Sydney in 2025 or 2026.', 'To be eligible for the scholarship, an applicant must meet the following:; remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia) and; be a citizen of a country in the South Asia region (Bangladesh, India, Nepal, Pakistan and Sri Lanka) and; meet all admission requirements for the selected UTS undergraduate (including Honours programs) or postgraduate coursework program and; Commence full‐time and on campus (Sydney)', 'UTS 2025 and 2026 intakes: 15% off tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://utscollege.edu.au/au/how-to-apply/scholarships/uts-academic-merit-international-scholarship-south', 'https://search.studyaustralia.gov.au/scholarship/the-uts-academic-merit-international-scholarship-south/ccd653c896df3caf61df6f0a93b9acd8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The UTS Academic Merit International Scholarship - South') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UTS Academic Excellence International Scholarship For international students |  UTS Academic Excellence International Scholarship', 'This scholarship is available to high performing UTS Foundation Studies or Pre-Master’s Program students enrolling in an undergraduate or postgraduate coursework programs respectively at UTS in Sydney in 2025 or 2026.', 'To be eligible for the scholarship, an applicant must meet the following:; remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); and; meet all admission requirements for the selected UTS undergraduate or postgraduate coursework program and; for undergraduate coursework admission, completed an Australian Foundation Studies program and be admitted to UTS based on this qualification or; for postgraduate coursework admission, the most recently completed and UTS recognised tertiary qualification at an Australian Bachelor degree level or higher, and be admitted to UTS based on this qualificatio and; commence full‐time and on campus (Sydney)', 'UTS 2025 and 2026 intakes: 30% off tuition fees.', 'Postgraduate', NULL, 'https://utscollege.edu.au/au/how-to-apply/scholarships/uts-academic-excellence-international-scholarship', 'https://search.studyaustralia.gov.au/scholarship/uts-academic-excellence-international-scholarship-for-international-students-uts-academic-excellence-international-scholarship/74e1e5538567227b7a5006c7b0deaffc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UTS Academic Excellence International Scholarship For international students |  UTS Academic Excellence International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UTS Academic Merit International Scholarship', 'This scholarship is available to international students (except those from Bangladesh, India, Nepal, Pakistan and Sri Lanka) completing any UTS College academic program, and enrolling in an undergraduate or postgraduate coursework program at UTS in Sydney in 2025 or 2026.', 'To be eligible for the scholarship, an applicant must meet the following:; remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia) and; meet all admission requirements for the selected UTS undergraduate (including Honours programs) or postgraduate coursework program; commence full‐time and on campus (Sydney)', 'UTS 2025 intakes: 20% off tuition fees; UTS 2026 intakes: 15% off tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://utscollege.edu.au/au/how-to-apply/scholarships/uts-academic-merit-international-scholarship-south', 'https://search.studyaustralia.gov.au/scholarship/uts-academic-merit-international-scholarship/db84ea5e9266218c15b9fbf15f0bb0b7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UTS Academic Merit International Scholarship') LIMIT 1;
