INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic and Music Excellence Scholarships', NULL, 'Year 6 for Years 7-9; Year 9 for Years 10-12; and Year 10 for Years 11-12', 'Scholarships are awarded following the results of the ACER Scholarship test sat in February in the year of eligibility. There are no set quotas. Scholarships are awarded dependent upon merit.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-and-music-excellence-scholarships/6024e1cdd3dceb0c861363e96d4380ac', 'https://search.studyaustralia.gov.au/scholarship/academic-and-music-excellence-scholarships/6024e1cdd3dceb0c861363e96d4380ac', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00902F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic and Music Excellence Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'China Scholarship Council Research Scholarships', 'The China Scholarship Council Research Scholarship is a collaborative arrangement that provides support to candidates from the People\'s Republic of China to undertake a PhD at Western Sydney University. We encourage applications from candidates in all areas of study across our Schools and Institutes.', 'be a citizen and permanent resident of the People\'s Republic of China at the time of your application; satisfy the Australian Government requirements for a student visa(opens in new window)Opens in a new window for postgraduate research; have applied for admission and meet all admission entry requirements, including English proficiency; have received a conditional or unconditional offer for admission into a PhD program at Western Sydney University; have received a conditional offer for scholarship from Western Sydney University and; satisfy all other eligibility criteria as defined by the China Scholarship Council.', '"Western Sydney University will provide a tuition fee waiver for successful applicants for a maximum period of up to 48 months.\r\n"', 'Postgraduate', NULL, 'https://www.westernsydney.edu.au/schools/grs/scholarships/china_scholarship_council_research_scholarships', 'https://search.studyaustralia.gov.au/scholarship/china-scholarship-council-research-scholarships/a1cec40e9d58deaf18c10f5bc8c5b27d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00917K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'China Scholarship Council Research Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Research Scholarships', 'Western Sydney University supports higher degree research candidates with a range of scholarship opportunities. Research scholarships are released periodically, and each type of scholarship has specific application dates, eligibility criteria and conditions.\n\nThe information below outlines the requirements for our PhD Research Scholarships for Western Sydney University graduates of Masters of Research and Honours programs.', 'Doctor of Philosophy (PhD); Professional Doctorate (DCA, DCR or EdD)', 'Up to AUD $105564', 'Undergraduate / VET, Postgraduate', NULL, 'https://www.westernsydney.edu.au/schools/grs/scholarships/main_round_scholarships', 'https://search.studyaustralia.gov.au/scholarship/research-scholarships/60316806b548599f4f59bbfee791e144', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00917K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Research Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alphacrucis Higher Degree Scholarship', 'This scholarship provides financial support, in the form of a fee subsidy, to students undertaking HDR research at AC. This is a merit-based scholarship for students with a demonstrated record of academic excellence.', 'To be eligible for the Alphacrucis Higher Degree Scholarship, applicants must: be accepted for entry to (or recently enrolled in) an HDR degree at AC; have a record of academic excellence and a demonstrated research potential; recipients must maintain satisfactory progress as a research candidate at AC.', 'See scholarship details', 'Postgraduate', NULL, 'https://www.ac.edu.au/research/higher-degree-research/funding-opportunities/', 'https://search.studyaustralia.gov.au/scholarship/alphacrucis-higher-degree-scholarship/8d3513b5dc559c1b3fd5fa00222ca836', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00958A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alphacrucis Higher Degree Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Financial assistance scholarships', 'Enrolled HDR students facing financial difficulties may be eligible for a financial assistance scholarship, in the form of a fee subsidy. Students can apply at any time during their enrolment, typically for up to 2 semesters of financial support.', 'Enrolled HDR students facing financial difficulties may be eligible for a financial assistance scholarship, in the form of a fee subsidy. Students can apply at any time during their enrolment, typically for up to 2 semesters of financial support.', 'See scholarship details', 'Postgraduate', NULL, 'https://www.ac.edu.au/research/higher-degree-research/funding-opportunities/', 'https://search.studyaustralia.gov.au/scholarship/financial-assistance-scholarships/f42dd58d4cdeff79ab64c8bbc7cae968', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00958A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Financial assistance scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'HDR Travel Grant', 'This grant is available to assist HDR candidates with travel costs (up to $1500) associated with research-related activities that will enhance their thesis.', 'To be eligible to apply for this grant, you must: be currently enrolled in an HDR course; have successfully completed your Confirmation of Candidature milestone; not have submitted for examination; submit evidence of acceptance of your peer-reviewed conference submission, if you are applying to travel to a conference.', 'See scholarship details', 'Postgraduate', NULL, 'https://www.ac.edu.au/research/hdr/funding-opportunities/', 'https://search.studyaustralia.gov.au/scholarship/hdr-travel-grant/ccb60089fcf04a5ed08bd574c8b8bb2f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00958A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'HDR Travel Grant') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Mission Australia Chaplaincy Research Scholarship', 'This scholarship is funded by a partnership between AC and Mission Australia, for qualitative research on community chaplaincy in Australia. The scholarship provides up to $60,000 of financial support for PhD students over 3 years (full-time).', 'To be eligible for the Mission Australia Chaplaincy Research Scholarship, applicants must: be planning to undertake qualitative social research on chaplaincy in Australia; be accepted for entry to (or recently enrolled in) a doctoral degree at AC; recipients must maintain satisfactory progress as a research candidate at AC.', 'AUD $60000/year', 'Postgraduate', NULL, 'https://www.ac.edu.au/research/higher-degree-research/funding-opportunities/', 'https://search.studyaustralia.gov.au/scholarship/mission-australia-chaplaincy-research-scholarship/b0c205d4d4b016c26b3353478eb0fc8a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00958A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Mission Australia Chaplaincy Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Thesis write-up scholarship', 'The purpose of this scholarship is to assist HDR candidates to write-up and submit their theses for examination. Typically the scholarship takes the form of a full tuition subsidy for one semester, for students who are in the final stage of completing their thesis.', 'To be eligible for this scholarship, you need to: be able to demonstrate readiness to complete the thesis for submission within the next semester; have the unqualified support of your principal supervisor that you are close to completing the thesis.', 'See scholarship details', 'Postgraduate', NULL, 'https://www.ac.edu.au/research/hdr/funding-opportunities/', 'https://search.studyaustralia.gov.au/scholarship/thesis-write-up-scholarship/d294e438fbfcb1e3578326de8eb5570c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00958A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Thesis write-up scholarship') LIMIT 1;
