INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'LIFELONG LEARNING BURSARY', 'CHC values lifelong learning and is providing scholarships to selected alumni who have been accepted to commence an eligible CHC course in Semester 1 or Semester 2, 2025.\r\n\r\nThe scholarship is available to domestic students and international students alike.', 'Completion of a CHC Bachelor degree or higher. \r\nAcceptance to commence a CHC postgraduate course in Business, Counselling, Education or Human Services in Semester 1 or Semester 2, 2025. \r\nEnrolment in a full-time study load (international students only)', 'The scholarship is valued at a 10% reduction in the applicable tuition fees for the duration of enrolment in the course (domestic students) or for the standard full-time duration of the course (international students).', 'Undergraduate / VET', NULL, 'https://chc.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/lifelong-learning-bursary/93dee164bf14ce357d66feed9fb81e8a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01016F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'LIFELONG LEARNING BURSARY') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Diploma and Pre-Masters Program International Student Award', 'If you start a Diploma or Pre-Masters Program in 2025 or 2026, you could be eligible to receive a 15% contribution towards your tuition fees, for the duration of your studies at UNSW.', 'Be an International Student; Be a citizen of an eligible country; Be commencing full-time study as a new student on campus in a Diploma or Pre-Masters Program.', '15% contribution towards your tuition fees, for the duration of your studies at UNSW', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.unswcollege.edu.au/content/dam/pdfs/unsw-college/international-student-award-diploma-pre-masters.pdf', 'https://search.studyaustralia.gov.au/scholarship/diploma-and-pre-masters-program-international-student-award/8188f420c3b9e244978f8f6cc1bf1714', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01020K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Diploma and Pre-Masters Program International Student Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Foundation Studies International Student Award', 'If you start a Foundation Studies program from 1 July 2025 or in 2026, you could be eligible to receive a 15% contribution towards your tuition fees, for the duration of your studies at UNSW.', 'Be an International Student; Be a citizen of an eligible country; Must not be a current student of UNSW College', '15% contribution towards your tuition fees, for the duration of your studies at UNSW.', 'Undergraduate / VET', NULL, 'https://www.unswcollege.edu.au/content/dam/pdfs/unsw-college/international-student-award-foundation-studies.pdf', 'https://search.studyaustralia.gov.au/scholarship/foundation-studies-international-student-award/b0d398141b862c7413c6f8ea3eeb16a1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01020K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Foundation Studies International Student Award') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Master of Physiotherapy Scholarship', 'The University of Notre Dame Australia (University) offers the International Master of Physiotherapy Scholarship to provide tuition assistance to international students enrolling in the Master of Physiotherapy program at the University of Notre Dame Australia', 'Be international full fee-paying students commencing a Master of Physiotherapy program for the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission requirements to study the CRICOS registered Master of Physiotherapy where the program is delivered on the University’s Sydney or Fremantle (Perth) Campuses and; Be eligible to apply for a Higher Education Sector Visa (Subclass 500).', 'The value of the Scholarship is $7,500 fee reduction of annual indicative tuition fees for the full duration of the \r\nprogram.', 'Postgraduate', NULL, 'https://www.notredame.edu.au/__data/assets/pdf_file/0037/437698/International-Master-of-Physiotherapy-Scholarship-Conditions.pdf', 'https://search.studyaustralia.gov.au/scholarship/international-master-of-physiotherapy-scholarship/5f3d31c0e51526dd38f0088c4eefed07', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01032F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Master of Physiotherapy Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Notre Dame Australia International Business and Commerce Scholarship', 'The University of Notre Dame Australia (University) offers the International Business and Commerce scholarship to provide tuition assistance to international students enrolling in Undergraduate Business and Commerce programs at the University of Notre Dame Australia.', 'Be international full fee-paying students commencing an undergraduate coursework program, in Business or Commerce for the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission requirements to study in any CRICOS registered undergraduate Business or Commerce degree where the program is delivered on the University’s Sydney or Fremantle (Perth) Campuses and; Be eligible to apply for a Higher Education Sector Visa (Subclass 500)', 'The value of the Scholarship is $10,000 fee reduction of annual indicative tuition fees for the full duration of the program.', 'Undergraduate / VET', NULL, 'https://www.notredame.edu.au/__data/assets/pdf_file/0032/339944/NDA-International-Business-and-Commerce-Undergraduate-Scholarship-T-and-Cs.pdf', 'https://search.studyaustralia.gov.au/scholarship/notre-dame-australia-international-business-and-commerce-scholarship/448e681128dec7e965ded68204b9ed21', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01032F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Notre Dame Australia International Business and Commerce Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Notre Dame Australia International Scholarship Master of Social Work (Qualifying).', 'The University of Notre Dame Australia (University) offers the International Scholarship Master of Social Work \r\n(Qualifying) to provide tuition assistance to international students enrolling in the Master of Social Work \r\n(Qualifying).', 'To be eligible for the Scholarship, students must:; Be international full fee-paying students commencing a Master of Social Work (Qualifying) program \r\nfor the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission \r\nrequirements to study the CRICOS registered Master of Social Work (Qualifying) delivered on the \r\nUniversity\'s Sydney or Fremantle (Perth) Campuses; Be eligible to apply for a Higher Education Sector Visa (Subclass 500).', 'The value of the Scholarship is 20 percent (20%) of annual indicative tuition fees for the full duration of the \r\nprogram. The Scholarship is awarded as a partial tuition fee waiver and does not cover costs such as living \r\nexpenses, accommodation, t', 'Postgraduate', NULL, 'https://www.notredame.edu.au/__data/assets/pdf_file/0039/746976/TCs-Mof-Social-Work-Conditions-2026-updated.pdf', 'https://search.studyaustralia.gov.au/scholarship/notre-dame-australia-international-scholarship-master-of-social-work-qualifying/c0c4e5055084cc3e5e30276bcdab71cf', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01032F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Notre Dame Australia International Scholarship Master of Social Work (Qualifying).') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Notre Dame Australia International Welcome Scholarship (Undergraduate)', 'The University of Notre Dame Australia (University) offers the International Welcome Scholarship to provide tuition assistance to international students enrolling in Undergraduate programs at Notre Dame, excluding the Bachelor of Nursing.', 'Be international full fee-paying students commencing an undergraduate coursework program, excluding the Bachelor of Nursing for the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission requirements to study in any CRICOS registered undergraduate degree where the program is delivered on the University’s Sydney or Fremantle (Perth) Campuses and; Be eligible to apply for a Higher Education Sector Visa (Subclass 500).', 'The value of the Scholarship is 25 percent (25%) of annual indicative tuition fees for the full duration of the program.', 'Undergraduate / VET', NULL, 'https://www.notredame.edu.au/__data/assets/pdf_file/0029/258941/NDA-International-Welcome-Scholarship-Undergraduate-2022-T-and-Cs.pdf', 'https://search.studyaustralia.gov.au/scholarship/notre-dame-australia-international-welcome-scholarship-undergraduate/9a1bb6cd1e3448c938269c7ed793de21', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01032F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Notre Dame Australia International Welcome Scholarship (Undergraduate)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Notre Dame Australia International Welcome Scholarship for Nursing', 'The University of Notre Dame Australia (University) offers the International Welcome Scholarship for Nursing\r\nto provide tuition assistance to international students enrolling in the Bachelor of Nursing program at Notre \r\nDame.', 'Be international full fee-paying students commencing the Bachelor of Nursing program for the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission requirements to study the Bachelor of Nursing CRICOS registered degree delivered on the Universitys Sydney or Fremantle (Perth) Campuses and; Be eligible to apply for a Higher Education Sector Visa (Subclass 500)', 'The value of the Scholarship is 20 percent (20%) of annual indicative tuition fees for the full duration of the \r\nprogram.', 'Undergraduate / VET', NULL, 'https://www.notredame.edu.au/__data/assets/pdf_file/0032/258944/NDA-International-Welcome-Scholarship-Nursing-2022-T-and-Cs.pdf', 'https://search.studyaustralia.gov.au/scholarship/notre-dame-australia-international-welcome-scholarship-for-nursing/9ab1303d015574e08e45b25b6efcb8f2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01032F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Notre Dame Australia International Welcome Scholarship for Nursing') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Notre Dame International Welcome Scholarship (Postgraduate)', 'The University of Notre Dame Australia (University) offers the International Welcome Scholarship to provide tuition assistance to international students enrolling in Postgraduate coursework programs at Notre Dame, with the exception of the Doctor of Medicine, Master of Physiotherapy, and all Graduate Certificates.', 'Be international full fee-paying students commencing an postgraduate coursework program for the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission requirements to study in any CRICOS registered postgraduate degree where the program is delivered on the Universitys Sydney or Fremantle (Perth) Campuses, excluding the Doctor of Medicine and all Graduate Certificates; Be eligible to apply for a Higher Education Sector Visa (Subclass 500).', 'The value of the Scholarship is 20 percent (20%) of annual indicative tuition fees for the full duration of the program.', 'Postgraduate', NULL, 'https://www.notredame.edu.au/__data/assets/pdf_file/0021/437700/Postgraduate-Coursework-conditions.pdf', 'https://search.studyaustralia.gov.au/scholarship/notre-dame-international-welcome-scholarship-postgraduate/da90cfeab521aa972c245690e1821aeb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01032F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Notre Dame International Welcome Scholarship (Postgraduate)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Vice Chancellors Humanitarian Scholarship', 'The purpose of the Scholarship is to assist students holding one of the classes of visa listed in Appendix 1 to commence or continue their studies at the University of Notre Dame Australia, Fremantle and Sydney Campuses.', 'Be from a refugee or asylum seeker background as evidenced by the applicant holding one of the classes of visa listed in Appendix 1 which permits the recipient to undertake tertiary studies in Australia and; Have been offered a place or be enrolled as a student in an undergraduate bachelor\'s program or in the Tertiary Pathway Program at the University of Notre Dame Australia, Fremantle or Sydney Campus.', 'Full fee remission.', 'Undergraduate / VET', NULL, 'https://www.notredame.edu.au/__data/assets/pdf_file/0021/266070/VCs-Humanitarian-Scholarship-Conditions.pdf', 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-humanitarian-scholarship/4eb86ff3527e69acfe0c4f93c4106691', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01032F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Vice Chancellors Humanitarian Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Excellence', NULL, 'Year 7, 9, 11', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-excellence/694768fdc28452a680b73b3bb010843a', 'https://search.studyaustralia.gov.au/scholarship/academic-excellence/694768fdc28452a680b73b3bb010843a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01097M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Excellence') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence', NULL, 'Year 7, 9, 11', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence/04da0be513b6c11b9edbc37e509d8c90', 'https://search.studyaustralia.gov.au/scholarship/general-excellence/04da0be513b6c11b9edbc37e509d8c90', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01097M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Performing Arts Scholarship', NULL, 'Year 7, 9, 11', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/performing-arts-scholarship/9c70d3b8d9b931618d9d905fa5df377c', 'https://search.studyaustralia.gov.au/scholarship/performing-arts-scholarship/9c70d3b8d9b931618d9d905fa5df377c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01097M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Performing Arts Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Access Scholarship (Enrolled Students Only)', 'The Kangan Institute Access Scholarship has been designed to provide opportunities for access to education. The scholarship is available to domestic and international students enrolled in any course at Kangan Institute. It is intended to alleviate financial pressures associated with engagement and the successful completion of the course.', 'Students must be enrolled in any course at Kangan Institute.; To be eligible for the Kangan Institute Access Scholarship, applicants must meet the following criteria and provide supporting documents; Must hold a valid visa (student visa, temporary graduate visa, spouse visa or anyone paying International Fee); Must be an onshore student;  Provide evidence of financial or personal disadvantage. Disadvantage(s) may include; a.   financial difficulty (payslips, bank statements or statutory declaration); b.   experienced delay or interruption to studies due to compassionate reason(s), which may include but death in the immediate family, family violence, homelessness, or at authorised officers’ discretion Evidence – death certificate, eviction notice, personal statement or statutory declaration; Currently enrolled and studying at Kangan Institute and have current outstanding fees.', 'Up to AUD $1000 — Domestic Students: up to $500 per scholarship\r\nInternational Students: up to $1,000 per scholarship', 'Undergraduate / VET', NULL, 'https://www.kangan.edu.au/study-with-us/prospective-students/scholarships/access-scholarship', 'https://search.studyaustralia.gov.au/scholarship/access-scholarship-enrolled-students-only/3bc23eec83ffa60201a7611812d4c695', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01218G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Access Scholarship (Enrolled Students Only)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Access26', 'Please contact Southern Cross University for further information.', 'Please contact Southern Cross University for further information.', 'Up to AUD $26000 — The $26,000 tuition fees will apply to all new and continuing international students in Australia, in all courses with the exception of the Master of Nursing, Bachelor of Veterinary Technology and Bachelor of Veterinary Medicine pl', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.scu.edu.au/study/international-study/access26/', 'https://search.studyaustralia.gov.au/scholarship/access26/a747c733167765a70b78b781f037f0de', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01241G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Access26') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Women\'s Day Scholarship', 'This scholarship will support a current student to continue to achieve outstandingly in her studies. The scholarship will form part of the celebrations of International Women’s Day.\r\n\r\nInternational Women’s Day celebrates and acknowledges the achievements of women globally on 8 March each year.', 'This scholarship will support a current student to continue to achieve outstandingly in her studies. The scholarship will form part of the celebrations of International Women’s Day. International Women’s Day celebrates and acknowledges the achievements of women globally on 8 March each year.', 'Up to AUD $5000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.scu.edu.au/scholarships/international-womens-day-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/international-womens-day-scholarship/7da620117e0069ad51f55ed9f7cc84ae', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01241G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Women\'s Day Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Preparing for Success Pathway Scholarship', 'The Preparing for Success Pathway Scholarship which will assist students transition into their chosen degree. The scholarship supports students through an initial preparatory program (Preparing for Success Program) where the student gains skills required for successful degree studies. Upon successful completion of Preparing for Success Program students will be able to progress onto a bachelor program. A bonus payment will be made upon commencement of study in the student\'s chosen Bachelor degree.', 'Recipients must be:; Commencing Preparing for Success pathway program in 2027; Be offered the Preparing for Success program as an Early Offer; Complete Preparing for Success in 2027; Progress immediately into the first available offering of the packaged Bachelor degree upon completion of the Preparing for Success program', 'Up to AUD $2500', 'Undergraduate / VET', NULL, 'https://www.scu.edu.au/scholarships/preparing-for-success-pathway-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/preparing-for-success-pathway-scholarship/ac8d27d103c06eb6a4a258109f594595', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01241G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Preparing for Success Pathway Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ralph Barclay Braun Memorial Scholarship', 'The Ralph Barclay Braun Memorial Scholarship is awarded to students who have a formal acceptance into the Bachelor of Science with Honours. Students must be based, full-time, at the National Marine Science Centre (NMSC) — and have a supervisor who is based, full-time, at the NMSC. This scholarship will support a student who will be engaged in important research in areas such as Biodiversity, Ecological Interactions, Aquaculture and Sustainable Fisheries. Successful recipients demonstrate outstanding academic achievement in their undergraduate study and are committed to a research career.', 'Enrolled full-time and on-campus at the Southern Cross University’s National Marine Science Centre in the Bachelor of Science with Honours program. Applications should provide a copy of their undergraduate record and must have attained a GPA higher than 5.5 for the last year (or last 8 units if part-time study was undertaken) of their undergraduate degree. Provision of a 100-word statement outlining a passion for marine science research and a commitment to developing a research career path. A one-page (A4) research proposal.', 'Up to AUD $5000 — $5000', 'Undergraduate / VET', NULL, 'https://www.scu.edu.au/scholarships/ralph-barclay-braun-memorial-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/ralph-barclay-braun-memorial-scholarship/8e462b80a07aff5743f74e9284a689a9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01241G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ralph Barclay Braun Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'SCU Rugby Gold Rats Scholarship', 'The University’s Rugby Club, known as the Gold Rats, marked its 50th season in 2019. The club offers scholarships to students studying in a degree at the Lismore campus.', 'Applicants applying for this scholarship must:; Be admitted and enrolled either full-time or part-time in an undergraduate or postgraduate degree at Southern Cross University, Lismore campus; Be a current or new player in the Far North Coast first grade rugby competition, or Women’s competition, for the SCU Rugby Club in the year the scholarship is offered. Scholarship holders must have experience as a representative or first grade, or Women’s rugby player.', 'Up to AUD $3000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.scu.edu.au/scholarships/southern-cross-university-rugby-gold-rats-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/scu-rugby-gold-rats-scholarship/3778705ef1d8bc94f7601315c6a517da', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01241G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'SCU Rugby Gold Rats Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Student Opportunities Fund', 'Southern Cross University is committed to helping provide exceptional students with exceptional opportunities to broaden their professional networks and opportunities. The Southern Cross Student Opportunities Fund will provide students with the opportunity to apply for a scholarship worth up to $7,500 each to help subsidise the cost of travel, accommodation and necessary activities to help them realise their full professional potential.', 'Please note that this scholarship is only available to students who have progressed their opportunity to such a point that its occurrence is almost certain. As such, students may have to purchase tickets or accommodation in advance of being awarded this scholarship, in which case, the scholarship panel will consider the costs already incurred and include that in their deliberations as to the amount granted if successful. The strength of each application will be measured against the above selection criteria. A report will make recommendations to the selection panel, which will be represented by the Office of Engagement, Office of Research, Finance, Governance and other work units where specialist insights may be required.', 'Up to AUD $7500', 'Undergraduate / VET', NULL, 'https://www.scu.edu.au/current-students/opportunities/student-opportunities-fund/', 'https://search.studyaustralia.gov.au/scholarship/student-opportunities-fund/47f113bf4fa5ad1d041d32139240811d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01241G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Student Opportunities Fund') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Vice Chancellor\'s International Diversification Scholarship', 'This scholarship celebrates the diversity of nations with international students attending Southern Cross University.', 'Apply to study an undergraduate or postgraduate coursework degree commencing in 2024 or 2025 (Excludes quota-restricted programs, e.g. Graduate Diploma of Early Childhood and Master of Nursing) at the Gold Coast, Lismore, or Coffs Harbour campus, or online for international students on a non-student visa.  Please note, this scholarship is only applicable to students paying international fees and does not include programs offered online through SCU Ventures, The Hotel School or Keypath Education. Meet the admission entry requirements of the program you have applied for. Assessment of eligibility for this scholarship will be undertaken by the Southern Cross admissions team on application to Southern Cross University. To maintain scholarship eligibility, students must pass all the requirements for all enrolled units in each Term. Students must be meeting the requirements of the program. Students must meet the attendance requirements of their program and visa conditions to remain eligible for the scholarship. Specific countries only are eligible, contact your Regional Manager for more details. Students who are Australian citizens, Australian permanent residents, or New Zealand citizens are not eligible to apply.', '$8,000 maximum fee reduction per year for the duration of your program', 'Postgraduate, Undergraduate / VET', NULL, 'http://www.scu.edu.au/scholarships/international-student-scholarships/vice-chancellors-international-diversification-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-international-diversification-scholarship/cca133370db7c2fbd1fb7ea23531c00d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01241G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Vice Chancellor\'s International Diversification Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2025 and 2026 International Masters Scholarship', 'The International Masters Scholarship 2025 and 2026 is offered to international students from selected countries who are applying for select Master degrees at ECU. The scholarship offers a 20 percent reduction in your tuition fees for the offered duration of your Master course at ECU. The scholarships are open to future international students seeking to enroll at Edith Cowan University in Semester Two, 2025; or Semester One and Two, 2026.', 'Be a citizen of one of the countries identified above; \r\nBe an international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen); \r\nStudy onshore at ECU Joondalup, ECU Mount Lawley, ECU City Campus or ECU South West (Bunbury) Campus; \r\nMeet ECU’s entry requirements for the course and commence study onshore, in an eligible postgraduate degree listed as below at ECU, Western Australia in Semester Two 2025; or Semester One and Two, 2026. \r\nBe commencing your ECU packaged pathway course with an ECU registered pathway partner leading to an eligible postgraduate degree listed as below in 2025 and 2026.', 'See scholarship details', 'Postgraduate', NULL, 'https://www.ecu.edu.au/scholarships/details/2025-international-masters-scholarship', 'https://search.studyaustralia.gov.au/scholarship/2025-and-2026-international-masters-scholarship/f04c5121e639907836592e59c1cc646d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01312J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2025 and 2026 International Masters Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2025 and 2026 International Undergraduate Scholarship', 'The International Undergraduate Scholarship 2025 and 2026 is offered to international students from selected countries who are applying for a Bachelor degree at ECU. The scholarship offers a 20 percent reduction in your tuition fees for the offered duration of your course at ECU. The scholarships are open to future international students seeking to enroll at Edith Cowan University in a Bachelor degree in Semester Two, 2025 ; or Semester One and Two, 2026.', 'be a citizen of one of the countries identified above;\r\nbe an international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen);\r\nstudy onshore at ECU Joondalup, ECU Mount Lawley, ECU City Campus or ECU South West (Bunbury) Campus;\r\nmeet ECU’s entry requirements for the course and commence study onshore at ECU, Western Australia in Semester Two 2025; or Semester One and Two, 2026\r\nbe commencing your ECU packaged pathway course with an ECU registered pathway partner leading to an eligible CRICOS registered undergraduate degree in 2025 and 2026.\r\nstudy in an eligible CRICOS registered undergraduate degree (excluding Bachelor of Arts (Acting) (Y93), Bachelor of Arts (Arts and Cultural Management) (T74), Bachelor of Arts (Dance) (T73), Bachelor of Arts (Music Theatre) (G44), Bachelor of Arts Honours (C34), Bachelor of Counter Terrorism Security and Intelligence (Y14), Bachelor of Education (Early Childhood Studies) (Y42), Bachelor of Education (Primary) (Y41), Bachelor of Education (Secondary) (Y68), Bachelor of Music (W76), Bachelor of Music Honours (K35), Bachelor of Performing Arts (Y97), Bachelor of Performing Arts Honours (W92), Bachelor of Preclinical Foundations of Imaging Science (T78), Bachelor of Science (Cybercrime, Security and Intelligence) (W87), Bachelor of Science (Nursing) (C33), Bachelor of Science (Nursing)/Bachelor of Science (Midwifery) (Y76), Bachelor of Science (Paramedical) (K89)).', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/international-undergraduate-scholarship', 'https://search.studyaustralia.gov.au/scholarship/2025-and-2026-international-undergraduate-scholarship/ae1b4c01a8730e0e9b4d494955748a62', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01312J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2025 and 2026 International Undergraduate Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '2026 ECU City Campus Welcome Bursary', 'A $5,000 bursary available to new international students commencing an undergraduate or master\'s by coursework program at ECU City Campus in Semester One or Two, 2026. Eligible students must maintain full-time enrolment (60 credit points per semester), and meet all terms and conditions. The bursary is paid in two instalments of $2,500 after the census date of each of the first two semesters.', 'Be an international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen); \r\nBe studying an undergraduate or masters by coursework program on-campus for the first time, at ECU City Campus in Semester One, 2026, or Semester Two, 2026 (excluding Bachelor of Science (Nursing) C33 and Master of Nursing (Graduate Entry) J46); \r\nEot be in receipt of a government scholarship or industry sponsorship for your studies; and \r\nEnrolled to study in 60 credit points each Semester or study period in 2026 and remain enrolled in 60 credit points post census date of the commencing semester.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.ecu.edu.au/scholarships/details/2026-ecu-city-campus-welcome-bursary', 'https://search.studyaustralia.gov.au/scholarship/2026-ecu-city-campus-welcome-bursary/e009206c4d6daeea29576bd3198b87e9', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01312J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 ECU City Campus Welcome Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'GDLP First Nations Scholarship', 'The Australian College of Applied Professions (ACAP) and the Law Institute of Victoria (LIV) are committed to creating opportunities for First Nations Victorian law graduates through industry-led learning and genuine connections to the profession.', 'Completed a bachelors degree or higher in Law leading to admission to the legal profession, or No more than two academic subjects to complete in a bachelors degree, or higher in Law, of which neither are Priestley 11 subjects (1) AND Are completing these units while undertaking the PLT course; AND Has received the prior permission of the Admitting Authority (VLAB) to commence the PLT course.', 'See scholarship details', 'Postgraduate', NULL, 'https://www.acap.edu.au/pages/fees-payments/scholarships/fns/', 'https://search.studyaustralia.gov.au/scholarship/gdlp-first-nations-scholarship/eb5473d935cded51756a6c6eb34baec5', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01328A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'GDLP First Nations Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'MBA Scholarship for ACAP Coaching Graduates', 'Available for ACAP’s Graduate Certificate of Applied Coaching Alumni who want to take the next step with our Master of Business Administration (MBA) program. Our MBA is delivered on campus in Perth and offers eligible graduates up to four units of credit, allowing you to fast track your studies and complete fewer units to graduate. ACAP is also offering coaching graduates 15% off the course fee for their MBA program.', 'Completed ACAP\'s Graduate Certificate of Applied Coaching program.', 'ACAP coaching graduates can be eligible for up to 15% off the course fee for their MBA program.', 'Postgraduate', NULL, 'https://www.acap.edu.au/pages/fees-payments/scholarships/mba-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/mba-scholarship-for-acap-coaching-graduates/dbbe15c42b875158ba3e3d21296bed41', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01328A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'MBA Scholarship for ACAP Coaching Graduates') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Memorial Fund Scholarship (VIC/NSW)', 'The Memorial Fund Scholarship (VIC / NSW) was established to commemorate the lives of two William Angliss Institute students from Indonesia, who tragically lost their lives in the 2009 Victorian Bushfires. The Memorial Fund is awarded to international students (continuing) in any study area, based on merit or equity.', 'To be considered for this scholarship, you must:\r\n• Be an international student and hold a valid student visa; and\r\n• Have completed one full semester of full-time studies at William Angliss Institute in the previous semester; and\r\n• Be enrolled and continuing as a full time student in any VET or Faculty of Higher Education courses in any study area at William Angliss Institute (Melbourne or Sydney campus).\r\n• Fall into one of two categories;\r\n- Merit basis\r\n   - Demonstrate academic excellence via results achieved during previous and current studies\r\n- Equity basis\r\n   - Demonstrate financial and/or educational disadvantage. Include evidence that you;\r\n   - Experiencing short-term financial difficulties; or\r\n   - Have a disability, long-term medical illness or mental health condition or\r\n   - Experience difficult circumstances', 'AUD $3000/year — Scholarships of up to $3,000 (AUD) each will be available to students in Semesters 1 and 2. This is awarded to support the students\' skill development, travel, living and other study related tools, resources or/and equipment expenses', 'Undergraduate / VET', NULL, 'https://search.studyaustralia.gov.au/scholarship/the-memorial-fund-scholarship-vicnsw/76859c8983733901273fc1d7b32187f4', 'https://search.studyaustralia.gov.au/scholarship/the-memorial-fund-scholarship-vicnsw/76859c8983733901273fc1d7b32187f4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01505M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Memorial Fund Scholarship (VIC/NSW)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'The Sir William Angliss International Merit Scholarships (VIC/NSW)', 'The International Merit Scholarship is awarded to international students (continuing) in any study area, based on merit.', 'To be considered for this scholarship, you must:\r\n• Be an international student and hold a valid student visa; and\r\n• Have completed one full semester of full-time studies at William Angliss Institute in the previous semester; and\r\n• Be enrolled and continuing as a full time student in any VET or Faculty of Higher Education courses in any study area at William Angliss Institute (Melbourne or Sydney campus).\r\n• Demonstrate academic excellence via results achieved during previous and current studies.', 'Up to AUD $3000 — Scholarships of up to $3,000 (AUD) each will be available to students in Semesters 1 and 2. This is awarded to support the students\' skill development, travel, living and other study related tools, resources or/and equipment expense', 'Postgraduate, Undergraduate / VET', 'Tourism and hospitality', 'https://www.angliss.edu.au/study-with-us/scholarships/the-sir-william-angliss-international-merit-scholarships-vicnsw/', 'https://search.studyaustralia.gov.au/scholarship/the-sir-william-angliss-international-merit-scholarships-vicnsw/a802b9d7e506fe99f2a7b0dc2349bd67', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01505M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'The Sir William Angliss International Merit Scholarships (VIC/NSW)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'MIT Graduate Progression Scholarship', 'The Graduate Progression Scholarship is available to international students who have completed a Bachelor\'s or Master\'s degree at MIT and are commencing a Higher Degree by Research at MIT in 2025. Eligible students will receive a 10% tuition fee reduction each trimester for the duration of their program.', 'Have completed a Bachelor\'s or Master\'s degree at Mit; Be enrolling in a Higher Degree by Research at MIT in 2025', '10% tuition fee reduction per trimester, including the thesis component.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.mit.edu.au/study-with-us/scholarships/graduate-progression-scholarship', 'https://search.studyaustralia.gov.au/scholarship/mit-graduate-progression-scholarship/7baa4cbbb672efe3f10479b79f5055d7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01545C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'MIT Graduate Progression Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Scholarship - Bangladesh, India, Pakistan and Sri Lanka', 'Are you an international student and currently in Bangladesh, India, Pakistan or Sri Lanka? Apply now to study at SIBT and receive a $1,000 scholarship to assist with your start.', 'Please Contact SIBT for more information about Eligibility', 'Up to AUD $1000 — $1,000 off your program fees for international students in Bangladesh, India, Pakistan or Sri Lanka.', 'Undergraduate / VET', NULL, 'https://sibt.nsw.edu.au/essential-information/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarship-bangladesh-india-pakistan-and-sri-lanka/a1303d3041feb0216c6b7c7cda0a3e20', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01576G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Scholarship - Bangladesh, India, Pakistan and Sri Lanka') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Scholarship - China, Japan, South Korea, all countries in Southeast Asia, and Australia', 'This scholarship offer is valid when students apply from China, Japan, South Korea, and all countries in Southeast Asia, and Australia', 'Please Contact SIBT for more information about Eligibility.', 'Up to AUD $3000 — $3,000 off your program fees for international students.', 'Undergraduate / VET', NULL, 'https://sibt.nsw.edu.au/essential-information/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarship-china-japan-south-korea-all-countries-in-southeast-asia-and-australia/9931e140ca40d7b6bbb91a2d116cba7a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01576G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Scholarship - China, Japan, South Korea, all countries in Southeast Asia, and Australia') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Scholarship - Nepal', 'Are you an international student currently in Nepal? Apply now to study at SIBT and receive a $5,000 scholarship to assist with your start.', 'Please Contact SIBT for more information about Eligibility.', 'Up to AUD $5000 — $5,000 off your program fees for international students in Nepal.', 'Undergraduate / VET', NULL, 'https://sibt.nsw.edu.au/essential-information/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarship-nepal/0af8c0c24bdb2e2d72d00fce077bf7da', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01576G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Scholarship - Nepal') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin College International Scholarships', 'Deakin College is committed to helping you achieve your goals by offering tuition fee scholarships to selected international students.', 'Be a citizen of Brunei, Cambodia, China, Hong Kong, Indonesia, Japan, Korea, Laos, Macau, Malaysia, Mongolia, Myanmar, Philippines, Singapore, Taiwan, Thailand, Timor-Leste or Vietnam, residing outside of Australia; or be a citizen of any country, residing onshore in Australia; Enrol as an international student; Commence a Foundation or Diploma program in 2025 or Trimester 1 2026.', 'The scholarship is valued between 10%-20% of your Foundation and/or diploma program tuition fees', 'Undergraduate / VET', NULL, 'https://www.deakincollege.edu.au/how-apply/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/deakin-college-international-scholarships/28794144fc4caa9ef1ae081a5b39189a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01590J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin College International Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Deakin College Loyalty Scholarships', 'Deakin College is committed to helping you achieve your goals by rewarding new international students from Africa with a Deakin College Loyalty Scholarship.', 'To be automatically awarded a Deakin College Loyalty Scholarship, you must:; be a citizen of any country in Africa, residing outside of Australia; enrol as an international student; commence a Foundation or Diploma program in 2025 or Trimester 1 2026.', 'The scholarship is valued at 10% of your Foundation and/or Diploma program tuition fees', 'Undergraduate / VET', NULL, 'https://www.deakincollege.edu.au/how-apply/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/deakin-college-loyalty-scholarships/b98ea4dc77355a693182c99d0c326995', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01590J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Deakin College Loyalty Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Navitas Family Bursaries', '-', 'Family Bursary applies where two or more students from the same family study at a Navitas institution.; The first family member can be studying at a Navitas institution at the same time as the other family members or may have studied at any Navitas institution previously.; The family bursary is granted to the second and subsequent family members who study at a Navitas institution.; This scholarship cannot be awarded in conjunction with any other Navitas scholarships; Recipients must not have previously received a Navitas scholarship or bursary, or had a scholarship or bursary from Navitas withdrawn.', 'The bursary is equivalent to 10% of the tuition fee for up to 8 units of study within one program only with a Navitas member institution. The bursary does not apply to additional units or repeat units that may also be undertaken. It excludes mixed En', 'Undergraduate / VET', NULL, 'https://www.deakincollege.edu.au/how-apply/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/navitas-family-bursaries/21c8524508b59424ed81e0b5ba7bf11a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01590J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Navitas Family Bursaries') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Australia Awards', 'Australia Awards are prestigious international scholarships and fellowships funded by the Australian Government. The Awards offer the next generation of global leaders an opportunity to undertake study, research and professional development.', 'Please Contact University of the Sunshine Coast Australia for more information.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.usc.edu.au/study/life-at-unisc/study-overseas/australia-awards', 'https://search.studyaustralia.gov.au/scholarship/australia-awards/ad1f6c02cb73532f16634a2c099b5dcc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01595D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'English Excellence Scholarship', 'Please Contact University of the Sunshine Coast Australia for more information.', 'Please Contact University of the Sunshine Coast Australia for more information.', 'The English Excellence Scholarship is a 20% tuition fee reduction that is awarded to commencing international students in 2025 who have achieved higher than required results in a recognised English language proficiency test.', 'Undergraduate / VET', NULL, 'https://www.usc.edu.au/international/programs-and-fees/international-scholarships#tab-2025-unisc-international-scholarships-for-new-students_37511', 'https://search.studyaustralia.gov.au/scholarship/english-excellence-scholarship/9b599bd3a934fcfebf8452cef1cf746f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01595D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'English Excellence Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Bright Futures Scholarship', 'The International Bright Futures Scholarship is a 20% tuition fee reduction that is awarded to commencing international students in 2025 who enrol in a newly launched UniSC program (i.e. Bachelor of Education Studies (Early Childhood), Master of Business Intelligence and Analytics and Master of Business Administration / Master of Business Intelligence and Analytics dual degree). The scholarship is calculated per course and will be reflected on your UniSC student account after acceptance and prior to the fees due date of the relevant teaching period to which the scholarship applies. If you are eligible, your offer will automatically include this scholarship.', 'Please Contact University of the Sunshine Coast for more information about Eligibility Criteria', '20% tuition fee reduction', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.usc.edu.au/international/programs-and-fees/international-scholarships#tab-2025-unisc-international-scholarships-for-new-students_98937', 'https://search.studyaustralia.gov.au/scholarship/international-bright-futures-scholarship/4d63b3d03170de99f71e2ed6f048f55a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01595D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Bright Futures Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Scholarship', 'Please Contact University of the Sunshine Coast Australia for more information.', 'Please Contact University of the Sunshine Coast Australia for more information.', 'The International Student Scholarship is a 15% tuition fee reduction offered to commencing international students in 2025.', 'Undergraduate / VET', NULL, 'https://www.usc.edu.au/international/programs-and-fees/international-scholarships#tab-2025-unisc-international-scholarships-for-new-students_37511', 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarship/4aed132be66c6671e4a0790afc74a879', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01595D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'National Centre for Timber Durability and Design Life Scholarship', 'The newly established Australian National Centre for Timber Durability and Design Life is seeking highly motivated students interested in pursuing PhDs in the area of wood deterioration and its prevention. The Centre is based in Brisbane Australia and is a joint venture between the University of the Sunshine Coast (UniSC), the University of Queensland and the Queensland Department of Agriculture and Fisheries (QDAF).', 'Domestic student or International HDR student at UniSC; Bachelors Degree with First Class Honours or equivalent previous study, relevant work experience, research publications, or other research experience; Maintain satisfactory progress; Not hold an equivalent qualification to the one currently being applied for; Not have previously held a Commonwealth-funded postgraduate research scholarship unless it was terminated within six months of the current scholarship’s payments commencing; Not be the recipient of an equivalent award, scholarship, or salary, providing a benefit greater than 75 percent of the RTP rate to undertake a HDR. Income unrelated to the course of study is not to be taken into account.', 'Annual stipend / If the successful recipient is an International student the scholarship will include tuition fees and Overseas Student Health Cover (single cover)', 'Undergraduate / VET', NULL, 'https://www.usc.edu.au/study/scholarships/research-scholarships/national-centre-for-timber-durability-and-design-life-scholarship', 'https://search.studyaustralia.gov.au/scholarship/national-centre-for-timber-durability-and-design-life-scholarship/713d7627bb9a007ce212843cfdd96832', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01595D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'National Centre for Timber Durability and Design Life Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Scholarships', 'To welcome new students to our college and help them kickstart their study adventure in Australia, we are offering an International Student Scholarship* to eligible new students in Trimester 1, 2025. *Terms and conditions apply. See our website for details and/or submit a contact form to confirm your eligibility.', 'To qualify for a scholarship*, students must:  1. Accept their offer by the cut-off date for each trimester  2. Pay all relevant fees  3. Commence study in their accepted intake (no deferrals)  4. Remain enrolled past census date. Scholarships can only be redeemed for their intended purpose and are not transferable or exchangeable in any way. Quotas apply to all scholarships, delays in accepting your offer may affect eligibility.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.griffithcollege.edu.au/how-apply/scholarships/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarships/6cec9bc8d5d1983aefe396a5aed12d3c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01737F' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', 'Academic Scholarships, remitting up to 50% of tuition fees, are offered to students entering Years 7-12. Applicants must demonstrate outstanding academic ability as determined by performance on the scholarship exam, academic reports and interview.To learn more and apply, please visit: https://www.mfac.edu.au/enrolments/scholarships/', 'Academic Scholarships, remitting up to 50% of tuition fees, are offered to students entering Years 7-12. Applicants must demonstrate outstanding academic ability as determined by performance on the scholarship exam, academic reports and interview.To learn more and apply, please visit: https://www.mfac.edu.au/enrolments/scholarships/', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/12b85013783155fa2c81b77323bee9bb', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/12b85013783155fa2c81b77323bee9bb', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01748C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Flinders Foundation Scholarship', 'Matthew Flinders Anglican College is committed to providing a wide range of learning opportunities across all areas of the curriculum and to nurturing individual student’s talents and interests. As part of this commitment, our College offers Academic, General Excellence, Music, Sport and Principal’s Scholarships for students with special talents who, in turn, will make a significant contribution to the life of our College. To learn more and to apply, visit https://www.mfac.edu.au/enrolments/scholarships', 'The Flinders Foundation Scholarship offers 50% remission of tuition fees to a student who does not attend the College but is keen to commence Year 10 or Year 11 at Flinders in Term 1, 2024. The student must exhibit attributes of an outstanding all-round contributor. To learn more about the Flinders Foundation Scholarship, please visit https://www.mfac.edu.au/community/flinders-foundation/flinders-foundation-scholarship/', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/flinders-foundation-scholarship/5f341f006c012dffe6a3f61aeb1fd974', 'https://search.studyaustralia.gov.au/scholarship/flinders-foundation-scholarship/5f341f006c012dffe6a3f61aeb1fd974', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01748C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Flinders Foundation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence', 'Matthew Flinders Anglican College is committed to providing a wide range of learning opportunities across all areas of the curriculum and to nurturing individual student’s talents and interests. As part of this commitment, our College offers Academic, General Excellence, Music, Sport and Principal’s Scholarships for students with special talents who, in turn, will make a significant contribution to the life of our College. To learn more and to apply, visit https://www.mfac.edu.au/enrolments/scholarships', 'General Excellence Scholarships, remitting up to 50% of tuition fees, are offered to students entering Years 7-12. Applicants must demonstrate excellence across three areas: strong academic ability (as opposed to the requirement of outstanding academic ability for an Academic Scholarship, leadership and/or service to the community, and significant achievement in ONE of the following: Music, Sport or The Arts. Applicants are required to sit the scholarship exam and must first apply for the Academic Scholarship.To learn more and apply, please visit: https://www.mfac.edu.au/enrolments/scholarships/', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence/c8de19ba14b4965869d9dde2b45cbd8a', 'https://search.studyaustralia.gov.au/scholarship/general-excellence/c8de19ba14b4965869d9dde2b45cbd8a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01748C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarships', 'Matthew Flinders Anglican College is committed to providing a wide range of learning opportunities across all areas of the curriculum and to nurturing individual student’s talents and interests. As part of this commitment, our College offers Academic, General Excellence, Music, Sport and Principal’s Scholarships for students with special talents who, in turn, will make a significant contribution to the life of our College. To learn more and to apply, visit https://www.mfac.edu.au/enrolments/scholarships', 'Music Scholarships, remitting up to 50% of tuition fees, are offered to students entering Years 7-12. Applicants must demonstrate outstanding musical ability. Scholarships are offered on the basis of an audition and a subsequent interview with the Principal. Applicants are also required to sit the academic testing.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarships/f965bfc0fc1389432b3998cba37652fc', 'https://search.studyaustralia.gov.au/scholarship/music-scholarships/f965bfc0fc1389432b3998cba37652fc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01748C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Principal\'s Scholarship', 'Matthew Flinders Anglican College is committed to providing a wide range of learning opportunities across all areas of the curriculum and to nurturing individual student’s talents and interests. As part of this commitment, our College offers Academic, General Excellence, Music, Sport and Principal’s Scholarships for students with special talents who, in turn, will make a significant contribution to the life of our College. To learn more and to apply, visit https://www.mfac.edu.au/enrolments/scholarships', 'The Principal’s Scholarship, offering full remission of tuition fees, is offered to an outstanding student not currently enrolled at the College. The winner will be selected, at the Principal’s discretion, from the applicants for Academic, General Excellence and Music scholarships categories. Applicants must demonstrate sound academic ability along with outstanding performance in the field of sport (including chess or debating). Applicants are also to show evidence of broad involvement across school life.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/principals-scholarship/62a864677570a79f53b55fd07670b657', 'https://search.studyaustralia.gov.au/scholarship/principals-scholarship/62a864677570a79f53b55fd07670b657', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01748C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Principal\'s Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Offshore Online Scholarships', 'ACPE values the vibrant contribution that students have in the sport industry globally and want to reward you to start your postgraduate studies offshore and online with this scholarship.', 'This scholarship is applicable to new international students undertaking postgraduate studies offshore online for the full duration of their course. Applicants must: meet the entry required for their desired course. Prove your English language proficiency through IELTS scores or other accepted alternatives including Pearson Test of English (PTE) and TOEFL. Maintain a full-time study load, 1 EFTSL over a 12-month study period. \r\nInternational scholarships are only available for first attempt subjects only. Full price is charged on retake for subjects if previously failed. Scholarship are also no deferrable.', '10% off 1 unit fee', 'Postgraduate', NULL, 'https://acpe.edu.au/admissions/scholarships/international-scholarships/', 'https://search.studyaustralia.gov.au/scholarship/offshore-online-scholarships/44aae35725537f97a7dc6d4ad8971b86', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01822J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Offshore Online Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Senior Secondary Scholarship Program', 'Senior Secondary scholarships are available to new students who will be undertaking studies in Year 10, 11 or 12 next year.', 'The value of the scholarship will be determined based on an assessment of the applicant at interview and the family’s financial circumstances. Applicants will be required to complete and submit a financial assessment form.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/senior-secondary-scholarship-program/16320dbbb35db876da472e965052ce1d', 'https://search.studyaustralia.gov.au/scholarship/senior-secondary-scholarship-program/16320dbbb35db876da472e965052ce1d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01958D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Senior Secondary Scholarship Program') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Year 9 Scholarships', 'This scholarship is open to students who are currently in Year 9 or entering Year 9 in the following year.', 'Students must demonstrate a strong commitment to the Christian faith and be interested in a Christian Education to further their faith development and service.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/year-9-scholarships/f2c92d4e093e2433dd803d274c6b4df2', 'https://search.studyaustralia.gov.au/scholarship/year-9-scholarships/f2c92d4e093e2433dd803d274c6b4df2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01958D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Year 9 Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Dr Alan Antcliff AM Memorial Scholarship', 'https://www.sunitafe.edu.au/life-at-sunitafe/scholarships/', 'https://www.sunitafe.edu.au/life-at-sunitafe/scholarships/', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://search.studyaustralia.gov.au/scholarship/dr-alan-antcliff-am-memorial-scholarship/0a6eb388f1f3f9cdffd318922ae874b3', 'https://search.studyaustralia.gov.au/scholarship/dr-alan-antcliff-am-memorial-scholarship/0a6eb388f1f3f9cdffd318922ae874b3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '01985A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Dr Alan Antcliff AM Memorial Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Curtin English Language Program Scholarship', 'In collaboration with Curtin University, Curtin College offers an English Language Program subsidy worth up to AUD$7,008 towards Curtin English courses.', 'You must be an international, full fee-paying, student who has received a conditional offer (subject to meeting English) to study at Curtin. This Scholarship is not available to Australian citizens or Permanent Residents. \r\nYou must be undertaking an English Language Program to meet your English Requirement. \r\nYou must not have met Curtin’s English language requirements for entry into your Mainstream Course and must commence your Mainstream Course at Curtin’s Perth campus in-person or fully online within one year after successfully completing the English Language Program to meet the requirements. \r\nYou must be studying a full-time undergraduate degree, postgraduate degree by coursework or Higher Degree by Research program of at least 1 year and for a minimum of 200 credit points. \r\nYou must pay upfront the fees associated with all your English Language Programs PLUS a AUD$1,000 deposit (the Deposit) at the time you accept the packaged offer contained in your Letter of Offer (different requirements apply to Sponsored students – see further below): \r\nCurtin will credit the AUD$1,000 Deposit AND the Scholarship of up to AUD$7,008 towards your tuition fee account for use in the second semester of your Mainstream course. If you do not continue to the Mainstream Course (whether you chose to withdraw or due to not meeting the English Requirement), the AUD$1,000 Deposit will be non-refundable. \r\nOnce you successfully complete your English course, in order to be admitted into your mainstream course, you are required to pay the full Deposit tuition fee of the mainstream course as indicated on the letter of offer. \r\nYou must progress to your Mainstream Course and maintain your enrolment as an international, full fee-paying, student for at least one semester of your Mainstream Course. If you do not, then the Scholarship will be cancelled and you will not receive the Scholarship either in the form of a credit or refund of the tuition fees for your English Language Program (unless you qualify for any exceptions under the Curtin English Refund Policy). \r\nIf your English Language Program costs less than the Scholarship, you cannot apply the Scholarship to any other international student expense or claim any remaining portion of the Scholarship. The Scholarship will only be applied to tuition, and enrolment fees. \r\nCurtin will not reissue this offer if you have to extend your English Language Program due to unsuccessful English academic progression. If you are unsuccessful in your initial English Language Program, you must pay for any further English courses you choose to study. \r\nYou cannot spend the Scholarship or cash it in for any other purpose. \r\nThis offer will not be extended beyond its prescribed duration or amount unless notified otherwise by Curtin in writing. \r\nThis offer will not be extended beyond its prescribed duration or amount unless notified otherwise by Curtin in writing. \r\nThis offer cannot be transferred to a Curtin campus or partner outside Western Australia, or to another university or educational institution. \r\nCurtin can cancel this offer if you do not accept your Letter of Offer or enrol in your Mainstream Course by the date specified. \r\nIf you are a Sponsored student, different requirements apply', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.curtincollege.edu.au/how-apply/scholarships/english-language/', 'https://search.studyaustralia.gov.au/scholarship/curtin-english-language-program-scholarship/e835c6cd88ea3084f6163cb529c99f4b', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02042G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Curtin English Language Program Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarships', NULL, 'Academic Scholarships for students entering Years 7, 9, 10 and 11 are awarded on the performance of the students in the Scholarship Examination on Monday 11 February 2019 at the school, and congruence of values with the School.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships/da959ba35e6ac6b6dd7a29a48d51fd61', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships/da959ba35e6ac6b6dd7a29a48d51fd61', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02268M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'All-Rounder Scholarships', NULL, 'Three All-Rounder Scholarships for students entering Year 10 and Year 11 are offered to develop students as leaders and responsible citizens in a global community. They are available to students who have demonstrated qualities of leadership at school, in their local community and/or through participation in a variety of co-curricular activities. \r\nThe Dunphy Foundation Sister Philomene Tiernan RSCJ Bursary is available for entry into Years 10 or 11 in 2020. \r\nThe Margaret Kirkpatrick Scholarship will be offered to a student for entry to Years 10 or 11 in 2020. \r\nThe Alison Stephen Scholarship will be offered to a student for entry to Years 10 or 11 in 2020.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/all-rounder-scholarships/fddbf0d63afe18d36e247204f3b5cb16', 'https://search.studyaustralia.gov.au/scholarship/all-rounder-scholarships/fddbf0d63afe18d36e247204f3b5cb16', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02268M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'All-Rounder Scholarships') LIMIT 1;
