INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic scholarships:  Year 4–6, Year 7, Year 11', 'Academic scholarships are offered each year to students entering Years 4 to 6, Year 7 and Year 11. Discounts to tuition fees range from 10% to 100%.', 'Scholarships are awarded dependent upon the results of the ACER Scholarship examination, and an interview with the School Registrar. The School expects all Academic Scholarship holders to display a high standard of achievement and to take a full and constructive role in school life.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-year-4-6-year-7-year-11/1143c0114425d6d16eb0058f1d1d1321', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-year-4-6-year-7-year-11/1143c0114425d6d16eb0058f1d1d1321', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02276M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic scholarships:  Year 4–6, Year 7, Year 11') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music scholarships: Year 4 to  Year 12', 'Music Scholarships are available to students entering Years 4, 5 and/or 6 and Years 7 to 11 to strengthen the already vibrant music program in the school. A St Andrew’s Cathedral School Music Scholarship provides aspiring musicians with the opportunity to work with highly qualified teachers; be provided tuition, musicianship and ensemble activities; and have access to the Andrean family of artists, mentors, classes and concerts.', 'Music scholarships are open to all instruments including: strings (including harp), woodwind, brass, piano (classical or jazz), singing (classical or contemporary), percussion (drum kit and auxiliary percussion) and composition. Scholarships are subject to an application process and shortlisted candidates are invited to audition with the Director of Performing Arts and other panel members, and this will be followed by an interview with the School Registrar.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarships-year-4-to-year-12/398f635407c92c8f716ada58c834fc57', 'https://search.studyaustralia.gov.au/scholarship/music-scholarships-year-4-to-year-12/398f635407c92c8f716ada58c834fc57', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02276M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music scholarships: Year 4 to  Year 12') LIMIT 1;
