INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'HLT54121 Diploma of Nursing Scholarship', 'HLT54121 Diploma of Nursing Scholarship', 'To be eligible to receive a bursary or scholarship with UOW College Australia, the applicant must be a citizen of the stipulated country.; Where a student extends their course after course commencement at UOW College Australia, the tuition fee for the period of the extension will be at the same bursary or scholarship rate. ; The bursary or scholarship can only be used on the course dates as specified in the offer of admission. Where an applicant defers or otherwise changes the course commencement date, the bursary or scholarship will be reassessed and may not be re-offered for that deferred course commencement date. ; This scholarship and bursary scheme supersedes all previous offers.; Scholarship and bursary recipients may be invited to participate in selected marketing initiatives by UOW College Australia and are expected to be willing to engage in these activities.; All fees are in Australian Dollars (AUD) and are dependent on the actual year of commencement and are subject to change without notice and in accordance with approved annual fee increases.', '10% tuition fee waiver for the HLT54121 Diploma of Nursing', 'Undergraduate / VET', NULL, 'https://www.uowcollege.edu.au/support-resources/student-services/fees/international/', 'https://search.studyaustralia.gov.au/scholarship/hlt54121-diploma-of-nursing-scholarship/45df7d53af528bdb3d423ccd5d77b258', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02723D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'HLT54121 Diploma of Nursing Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Academic Course Bursary', '2025-2026 International Academic Course Bursary', 'To be eligible to receive a bursary or scholarship with UOW College Australia, the applicant must be a citizen of the stipulated country.; Where a student extends their course after course commencement at UOW College Australia, the tuition fee for the period of the extension will be at the same bursary or scholarship rate. ; The bursary or scholarship can only be used on the course dates as specified in the offer of admission. Where an applicant defers or otherwise changes the course commencement date, the bursary or scholarship will be reassessed and may not be re-offered for that deferred course commencement date. ; This scholarship and bursary scheme supersedes all previous offers.; Scholarship and bursary recipients may be invited to participate in selected marketing initiatives by UOW College Australia and are expected to be willing to engage in these activities.; All fees are in Australian Dollars (AUD) and are dependent on the actual year of commencement and are subject to change without notice and in accordance with approved annual fee increases.', '20% tuition fee waiver for the minimum duration of an eligible course', 'Undergraduate / VET', NULL, 'https://www.uowcollege.edu.au/support-resources/student-services/fees/international/', 'https://search.studyaustralia.gov.au/scholarship/international-academic-course-bursary/243719ccf543712dc6204f3a60ab0355', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02723D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Academic Course Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UOW College Study Tours Scholarship', 'UOW College Study Tours Scholarship', 'To be eligible to receive a bursary or scholarship with UOW College Australia, the applicant must be a citizen of the stipulated country.; Where a student extends their course after course commencement at UOW College Australia, the tuition fee for the period of the extension will be at the same bursary or scholarship rate. ; The bursary or scholarship can only be used on the course dates as specified in the offer of admission. Where an applicant defers or otherwise changes the course commencement date, the bursary or scholarship will be reassessed and may not be re-offered for that deferred course commencement date. ; This scholarship and bursary scheme supersedes all previous offers.; Scholarship and bursary recipients may be invited to participate in selected marketing initiatives by UOW College Australia and are expected to be willing to engage in these activities.; All fees are in Australian Dollars (AUD) and are dependent on the actual year of commencement and are subject to change without notice and in accordance with approved annual fee increases.', 'Up to AUD $3000 — $3,000 scholarship towards further study at UOW College Australia', 'Undergraduate / VET', NULL, 'https://www.uowcollege.edu.au/support-resources/student-services/fees/international/', 'https://search.studyaustralia.gov.au/scholarship/uow-college-study-tours-scholarship/73855064aabc1c9260b55d65a09b61c2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02723D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UOW College Study Tours Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Avondale Student Research Scholarship', 'These scholarships provide opportunity for students to participate in a program of supervised research. Students can extend their knowledge, develop their analytical and critical thinking, and their communication skills. The scholarship is open to all Avondale students who are enrolled beyond the first year of their course and have a GPA of 5.0 or above.', 'The scholarship holder (scholar) is required to complete 160 hours of research. This may take place in a block of full-time work, or may be negotiated with the project supervisor to take place part-time over a longer period. Research may be conducted on campus (Lake Macquarie or Sydney) or off campus. At the completion of the project, the scholar and their supervisor will give an oral presentation of their research. The supervisor will be responsible for organising a suitable format, time and venue for the presentation in consultation with the scholar.', 'Up to AUD $4000', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.avondale.edu.au/scholarship/avondale-student-research-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/avondale-student-research-scholarship/0e3606346f4219405388b45e1f67b987', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02731D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Avondale Student Research Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Bland Family Scholarship', 'This scholarship is available to any new or returning domestic or international student who enrols in our Bachelor of Business with a major in accounting or in our Master of Business Administration.', 'Please Contact Avondale University for more information.', 'Up to AUD $8700', 'Undergraduate / VET', NULL, 'https://www.avondale.edu.au/scholarship/bland-family-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/bland-family-scholarship/71ee24be18a097c4e1b50ef73bf5ae48', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02731D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bland Family Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Driscoll Pacific Islands Student Scholarship', 'The Driscoll Pacific Islands Student Scholarship has been made possible as a result of the generosity of Linda and William Driscoll, both alumni of Avondale University. They both served for many years in the Pacific Islands. They desired to assist students coming directly from the Pacific Island nations of the South Pacific Division of the Seventh-day Adventist Church to study at Avondale.', 'Please contact Avondale University for further information.', 'The scholarship is worth $7000. The recipient receives $3500 in their first semester and $3500 in their second.', 'Undergraduate / VET', NULL, 'https://www.avondale.edu.au/scholarship/driscoll-pacific-islands-student-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/driscoll-pacific-islands-student-scholarship/dab22effa3d7b0a314fc87db2eefa7f1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02731D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Driscoll Pacific Islands Student Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Scholarship', 'Please contact Avondale University for further information.', 'Please contact Avondale University for further information.', 'The scholarships are worth $8500. Each recipient receives $7000 ($3500 per semester or equivalent) in their first year of study and &1500 ($750 per semester or equivalent) in their second. Avondale will apply the money to each recipient’s general or', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.avondale.edu.au/scholarship/international-student-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarship/65eb13f7028fda419b5a8688dbd34d86', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02731D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'King Family Scholarship', 'The King Family Scholarship encourages students in a degree course who want to sing with vocal ensembles Avondale Singers and The Promise but who are not vocal performance majors to improve their skills through private tuition.', 'Please contact Avondale University for further information.', 'Up to two scholarships valued at $500 per student per semester.', 'Undergraduate / VET', NULL, 'https://www.avondale.edu.au/scholarship/king-family-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/king-family-scholarship/5e5674f420b3562924b68941aa21deca', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02731D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'King Family Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Shields Music Scholarship', 'The merit-based Shields Music Scholarship encourages a new student with a passion for music to grow in confidence as a performer.', 'Please contact Avondale University for further information.', '$2,000 ($1,000 per semester) in the first year. We will apply the money to your tuition account.', 'Undergraduate / VET', NULL, 'https://www.avondale.edu.au/scholarship/shields-music-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/shields-music-scholarship/6f2dfaa065562f4da2d3b56f2344e843', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02731D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Shields Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Young Musician Scholarship', 'This scholarship is available to any new student aged 29 years or younger enrolling with a music major or specialisation in the first year of the Bachelor of Arts or Bachelor of Arts/Bachelor of Teaching course.', 'Please contact Avondale University for further information.', '$2000', 'Undergraduate / VET', NULL, 'https://www.avondale.edu.au/scholarship/young-musician-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/young-musician-scholarship/aba2fa391fdf360d6edb7ca25b4b2a15', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02731D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Young Musician Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Young Scientist Scholarship', 'Avondale University offers the Young Scientist Scholarship to help young adults consider a career as a science teacher or scientist.', 'Please contact Avondale University for further information.', 'The scholarship is worth $2000. The successful applicant receives $1000 per semester in their first year of study. Avondale will apply the money to the recipient\'s tuition account. The money comes from the Young Scientist Scholarship Reserve, which t', 'Undergraduate / VET', NULL, 'https://www.avondale.edu.au/scholarship/young-scientist-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/young-scientist-scholarship/b9ed6607d2a6427ac2a5281af5d583e6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02731D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Young Scientist Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'EQUALS International Institute and the Centre for Equality Scholarship', 'EQUALS International, in partnership with the Centre for Equality, offer a range of scholarships to study VET programs at EQUALS.', 'The scholarship is open to domestic and international students aged at least 18 years of age who are commencing a VET program at EQUALS International.', 'The scholarship covers up to 100 per cent of tuition fees.', 'Undergraduate / VET', 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', 'http://www.equals.net.au/financial-assistance/', 'https://search.studyaustralia.gov.au/scholarship/equals-international-institute-and-the-centre-for-equality-scholarship/437d23cb42e0abaf3cf9cc5d489571cd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02804C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'EQUALS International Institute and the Centre for Equality Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'THE HOSPITALITY EXCELLENCE SCHOLARSHIP', 'Bringing your career dreams to life, ICHM is offering one 50% annual scholarship to Year 12 students around Australia entering the Bachelor of Business (Hospitality Management).', 'For more details contact ICHM', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.ichm.edu.au/future-students/fees-and-payment/scholarships', 'https://search.studyaustralia.gov.au/scholarship/the-hospitality-excellence-scholarship/2e54122b6e994d2bdcd6dd1c44616481', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '02914G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'THE HOSPITALITY EXCELLENCE SCHOLARSHIP') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Past Student\'s Association Uniform Scholarships', NULL, 'connection to St Ursula’s College Toowoomba, either mother, grandmother or aunt is a past student (must provide evidence);\r\nUrsuline Academic and All Rounder Scholarships: These scholarships are based on previous two years school reports, St Ursula’s College Scholarship Examination result and NAPLAN and/or ICAS results and evidence-based high achievement in one or more of the domains as listed above;\r\nsit for the scholarship examination on Saturday 26th October, 2019 at 9am;\r\nscholarships cannot be redeemed for cash or for tuition; and\r\nif the student leaves the College, the uniforms must be returned to the Retail Outlet.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/past-students-association-uniform-scholarships/633d1297bb2d2662184810622c32b86c', 'https://search.studyaustralia.gov.au/scholarship/past-students-association-uniform-scholarships/633d1297bb2d2662184810622c32b86c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03033M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Past Student\'s Association Uniform Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ursuline Academic & All Rounder Scholarships', NULL, 'These scholarships are based on previous two years school reports, St Ursula’s College Scholarship Examination result and NAPLAN and/or ICAS results and evidence-based high achievement in one or more of the following domains:\r\n\r\nFaith Leadership\r\nSchool Leadership\r\nSport\r\nMusic\r\nDance\r\nDrama\r\nArt\r\nLanguages other than English\r\nPublic Speaking/Debating\r\nSTEM Learning\r\nInformation Communication Technology\r\nDigital Design', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/ursuline-academic-all-rounder-scholarships/2b7a015c7b49692e517b4e4e37957750', 'https://search.studyaustralia.gov.au/scholarship/ursuline-academic-all-rounder-scholarships/2b7a015c7b49692e517b4e4e37957750', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03033M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ursuline Academic & All Rounder Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ursuline Academic Honour Scholarships', NULL, 'These scholarships are based on previous two years school reports, St Ursula’s College Scholarship Examination result and NAPLAN and/or ICAS results.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/ursuline-academic-honour-scholarships/5f6437bda0cc93b8521f8ddab24d46f7', 'https://search.studyaustralia.gov.au/scholarship/ursuline-academic-honour-scholarships/5f6437bda0cc93b8521f8ddab24d46f7', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03033M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ursuline Academic Honour Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '20% Early Childhood Education and Care Scholarship', 'Building on ALG’s strong track record in Early Childhood Education and Care, we are excited to announce the introduction of a 20% tuition fee scholarship for new international students starting an ALG Early Childhood Education and Care course in any intake in 2026.', 'This scholarship is open to international students and applies to the full duration of the program (including packaged ALG courses). Eligible courses are:\r\n\r\nCHC30121 Certificate III in Early Childhood Education and Care\r\nCHC50125 Diploma of Early Childhood Education and Care\r\nThis 20% scholarship will help more students access ALG’s high-quality training and support Australia’s growing demand for skilled early childhood educators.\r\n\r\nGraduates of the Diploma of Early Childhood Education and Care may also be eligible for entry into the second year of Ikon’s Bachelor of Early Childhood Education. Eligible applicants may receive course credit for up to 66 credit points.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://search.studyaustralia.gov.au/scholarship/20-early-childhood-education-and-care-scholarship/5d00d5bbc9621ad30cc1642b72ba9234', 'https://search.studyaustralia.gov.au/scholarship/20-early-childhood-education-and-care-scholarship/5d00d5bbc9621ad30cc1642b72ba9234', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03071E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '20% Early Childhood Education and Care Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Murdoch College Scholarships', 'We offer a 20% scholarship for eligible academic pathway programs for students who commence their studies in 2025.', 'Your studies at Murdoch College must commence in 2025; You are an academic pathways student at Murdoch College.; You must not be a recipient of any other College scholarship or grant, or a government-sponsored student for the duration of this College scholarship.', 'We offer a 20% scholarship for eligible academic pathway programs for students who commence their studies in 2025.', 'Undergraduate / VET', NULL, 'https://murdochcollege.edu.au/scholarships.html', 'https://search.studyaustralia.gov.au/scholarship/murdoch-college-scholarships/8de989298ef79903fcace8d7f163128d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03127E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Murdoch College Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'KOI INTERNATIONAL STUDENT SCHOLARSHIP 2025', 'King\'s Own Institute (KOI) is helping individuals around the world to reach their educational and career goals by\r\noffering KOI International Student Scholarships (KISS) to students who can display a record of outstanding\r\nacademic and English merit.', 'Eligibility (Onshore); 1 - You must have a passing record of 100% with your most recent provide; Your previous provider must be a higher education institute or university. Your proposed studies at KOI\r\nmust be of the same AQF level; Eligibility Offshore (Undergraduate); 1 - You must have achieved a Higher Secondary (year 12) result of a minimum 70% or an equivalent CGPA in previous study; 2 - You must have achieved an IELTS / PTE or an equivalent score of overall 6.5 or more; Eligibility Offshore (Postgraduate); 1 - You must have achieved a Bachelor qualification with a minimum of 60% or an equivalent CGPA in previous study; 2 - You must have achieved an IELTS / PTE or an equivalent score of overall 7.0 or more.', 'Up to $500 scholarship per trimester (pro-rated)', 'Postgraduate, Undergraduate / VET', NULL, 'https://koi.edu.au/wp-content/uploads/2025/02/KOI-KISS-Scholarship-2025_20Jan2025.pdf', 'https://search.studyaustralia.gov.au/scholarship/koi-international-student-scholarship-2025/5c3a1f07672d242193fe630180fdd4cc', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03171A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'KOI INTERNATIONAL STUDENT SCHOLARSHIP 2025') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Hsing Yun Education Foundation (HYEF) Scholarship', 'To honour Venerable Master Hsing Yun, HYEF is offering this scholarship to assist high achieving international students to undertake Applied Buddhist Studies and Humanistic Buddhism programs at Nan Tien Institute (NTI). We hope that people with similar visions can contribute to this great initiative.', 'The applicant must have been admitted or been offered admission to one of the following courses at NTI:; Master of Arts (Applied Buddhist Studies); Graduate Diploma of Applied Buddhist Studies; Graduate Certificate in Applied Buddhist Studies; Graduate Certificate in Humanistic Buddhism', 'See scholarship details', 'Postgraduate', NULL, 'https://www.nantien.edu.au/admissions/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/hsing-yun-education-foundation-hyef-scholarship/118d8bf202e91807d9276b782e4c9dda', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03233C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Hsing Yun Education Foundation (HYEF) Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'MIT Graduate Progression Scholarship', 'The Graduate Progression Scholarship is available to international students who have completed a Bachelor\'s or Master\'s degree at MIT and are commencing a Higher Degree by Research at MIT in 2025. Eligible students will receive a 10% tuition fee reduction each trimester for the duration of their program.', 'Have completed a Bachelor\'s or Master\'s degree at Mit; Be enrolling in a Higher Degree by Research at MIT in 2025', '10% tuition fee reduction per trimester, including the thesis component.', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.mit.edu.au/study-with-us/scholarships/graduate-progression-scholarship', 'https://search.studyaustralia.gov.au/scholarship/mit-graduate-progression-scholarship/8caaae6d1980ad759d5f9c47ebfa8d67', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03245K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'MIT Graduate Progression Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', NULL, 'Offered to all students entering Year 7 and prospective students entering Years 9, 10 or 11.  \r\nExams are held.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/b209466d1d024a46bf8be31091cd0b09', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/b209466d1d024a46bf8be31091cd0b09', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03298G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
