INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarship', NULL, 'Music Scholarships are offered to all students entering Year 7 and prospective students entering Years 9, 10 or 11.', 'See scholarship details', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/cce7f638aa7ca688015cbbd237a81a80', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/cce7f638aa7ca688015cbbd237a81a80', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03298G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Foundation and Diploma scholarships', 'La Trobe College Australia offers Foundation and Diploma scholarships to eligible international students.', 'Be a new international student who has not studied at La Trobe College Australia previously; Commence a Foundation or Diploma program in Trimester listed on the original Letter of Offer', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.latrobecollegeaustralia.edu.au/how-apply/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/foundation-and-diploma-scholarships/03597d27e867e596dfe8b503563594cd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03312D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Foundation and Diploma scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Navitas Academic Merit Scholarship', 'The Academic Merit Scholarship is awarded to the student who achieves the most outstanding academic results in their first trimester of studies at Navitas member institution.', 'Be continuing (current) student, enrolled and studying towards a Navitas Diploma, Advanced Diploma or Associate Degree (Australia) UTP Stage II or Associate Degree (Canada), UPP or IUTP (USA), Undergraduate pathway program (UK), University Foundation or Bachelor Degree program (Australia) or Master’s programs (Australia); Be currently studying full-time; Have achieved competencies in all courses across their current program (for which the scholarship is applied for) in the semester prior to being eligible for the scholarship; Not have any outstanding fees on their student account; Not have previously received a Navitas scholarship or bursary, or had a scholarship or bursary from Navitas withdrawn.', 'These scholarships are for one academic semester or part thereof (equivalent to the maximum of up to five academic subjects) for a Navitas Diploma, Advanced Diploma or Associate Degree (Australia), UTP Stage II or Associate Degree (Canada), UPP or IU', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobecollegeaustralia.edu.au/how-apply/scholarships/navitas-academic-merit-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/navitas-academic-merit-scholarship/1cf1d1b652a8b0955638c100fcca736d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03312D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Navitas Academic Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Navitas Family Bursary', 'The bursary is equivalent to 10% of the tuition fee for up to 8 units of study within one program only with a Navitas member institution. The bursary does not apply to additional units or repeat units that may also be undertaken and excludes mixed English options.', 'Family Bursary applies where two or more students from the same family study at a Navitas institution.; The first family member can be studying at a Navitas institution at the same time as the other family members or may have studied at any Navitas institution previously.; The family bursary is granted to the second and subsequent family members who study at a Navitas institution.; Not have previously received a Navitas scholarship (or bursary) or had a scholarship (or bursary) from Navitas withdrawn.', 'The bursary is equivalent to 10% of the tuition fee for up to 8 units of study within one program only with a Navitas member institution. The bursary does not apply to additional units or repeat units that may also be undertaken and excludes mixed En', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.latrobecollegeaustralia.edu.au/how-apply/scholarships/navitas-family-bursary/', 'https://search.studyaustralia.gov.au/scholarship/navitas-family-bursary/ed3da166f84e5f59a4f46780b3fa77a8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03312D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Navitas Family Bursary') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alumni Scholarship', 'We’re committed to supporting our graduates with further opportunities to advance their careers and find work they love. That’s why we offer alumni scholarships to encourage you on your continuing journey through education.', 'To be eligible you need to be a domestic or an international student who completed the postgraduate or undergraduate degree.', '25% off tuition fees', 'Undergraduate / VET, Postgraduate', NULL, 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/alumni-scholarships', 'https://search.studyaustralia.gov.au/scholarship/alumni-scholarship/06b956e293080fecca4bc82ac21a9e03', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alumni Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Alumni Scholarship', 'If you are an Alumni of BMIHMS, Torrens University Australia, Think Education or from a Laureate University you are entitled to a 25% scholarship.', 'For more information, click the \'more information\' button below to find out.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.bluemountains.edu.au/apply/scholarships-available/', 'https://search.studyaustralia.gov.au/scholarship/alumni-scholarship/b76c37fc5d49f71b0fb02d48e7e9af13', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Alumni Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Career Enhancement scholarship', 'Connection to industry is one of our most important philosophies, and we take it very seriously. It’s part of our DNA. If you’re working in a relevant field and want to upgrade your qualifications, we’re here to help with a 15% tuition fee reduction on offer.', 'You must be a new Torrens University Australia student.You must have relevant work experience (at least one year of experience in your field of study) documented in a CV.You should be currently employed in a relevant industry (Design & Creative Technology, Business & Hospitality, Health & Education).You must have 2 x references from your current employer/manager.', '15% off tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/industry-scholarships', 'https://search.studyaustralia.gov.au/scholarship/career-enhancement-scholarship/1c9951c06f8429ba72ea3eb997ec2962', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Career Enhancement scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'English Language Scholarship', 'Value: 10 weeks tuition fee.', 'For those students who would like to improve their English language skills to get the most out of their hospitality management degree, or those who do not initially meet our English Language entry requirements, students can apply for an English Language Scholarship. To find out more, please click the \'more information\' button below.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.bluemountains.edu.au/apply/scholarships-available/', 'https://search.studyaustralia.gov.au/scholarship/english-language-scholarship/dde71f1055262ad4781f6617646cd68c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'English Language Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Graduate Privileged Partner Scholarship', 'You can apply for the GPP scholarship if you are currently employed as a permanent staff of BMIHMS.', 'If you are currently employed as a permanent staff of our BMIHMS, Graduate Privileged Partners program (GPP)', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.bluemountains.edu.au/apply/scholarships-available/', 'https://search.studyaustralia.gov.au/scholarship/graduate-privileged-partner-scholarship/ec8aa87e022ecb9b997d32082ac52078', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Graduate Privileged Partner Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Industry Scholarship', 'This scholarship allows you to develop your career in an industry that you are passionate about.', 'If you are currently employed full-time in hospitality, Tourism or in the Event industry, you can apply for the industry scholarship. For more information, please click the \'more information\' below.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.bluemountains.edu.au/apply/scholarships-available/', 'https://search.studyaustralia.gov.au/scholarship/industry-scholarship/e49dd109799036ff3cd54330408a9de2', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Industry Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Ironwood Pathway Scholarship', 'Have you recently completed your Graduate Diploma of Agribusiness from Ironwood Institute? Join us on the Master of Business Administration Advanced course, and take advantage of 20 per cent scholarship off your total course tuition.', 'Students who complete their Graduate Diploma of Agribusiness from Ironwood Institute can pathway into our MBAA with a 20% Scholarship provided they meet admissions entry requirements.', '20% off tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/ironwood-pathway-scholarship', 'https://search.studyaustralia.gov.au/scholarship/ironwood-pathway-scholarship/9cd9e614768fd7a0a528a8da5aa05478', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Ironwood Pathway Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Kings College Malaysia Scholarship', 'Are you a current student at Kings College Malaysia studying a Business degree, looking to study with Torrens University Australia? You may be eligible for a scholarship of up to 45% off your tuition fees when you study concurrently with Torrens University or transition from Kings College Malaysia to continue your studies at Torrens University Australia.', 'This scholarship is available to students enrolled in a Business course at Kings College Malaysia who are either studying concurrently with Torrens University Australia or transferring from Kings College Malaysia to Torrens University Australia. To be eligible, students must meet Torrens University’s admission entry requirements and provide an offer letter from Kings College Malaysia. A conditional offer and conditional CoE will be issued based on this documentation, and the scholarship will be confirmed once the student commences concurrent study or transfers to Torrens University Australia.', '45% off tuition fees', 'Undergraduate / VET', NULL, 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/kings-college-malaysia-scholarship', 'https://search.studyaustralia.gov.au/scholarship/kings-college-malaysia-scholarship/c4640aa7b8717e02515ad2e0af3aa27c', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Kings College Malaysia Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Motivational scholarship', 'If you\'re a new international students commencing study in 2026 who hold a passport from Africa, Bhutan, Mauritius, Middle East, Philippines, South Asia (including Maldives), East Asia and South East Asia, you may be you may be eligible for this scholarship. It covers up to 25 per cent of your total course tuition.', 'To be considered, students must hold a passport from an eligible country and meet the scholarship requirements. A limited quota applies.', 'Up to 25% off tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/motivational-scholarship', 'https://search.studyaustralia.gov.au/scholarship/motivational-scholarship/8d6679f69636a357308b4f92253447d4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Motivational scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'PEPEA Scholarship', 'Are you a new student from Kenya? Torrens University Australia in partnership with the County Government of Elgeyo Marakwet, is proud to offer a scholarship initiative that expands access to higher education for talented students from disadvantaged backgrounds. This program empowers the next generation of Kenyan leaders and innovators to achieve their academic and professional goals.', 'This scholarship requires students to provide a scholarship letter from the Elgeyo Marakwet County Government, Kenya, and hold a valid passport from an eligible country. It applies to students commencing academic coursework programs (not applicable for English language courses) and applying for a Confirmation of Enrolment (COE). This scholarship is not available to Study Abroad students and cannot be combined with any other scholarships. A limited quota applies.', '50% off tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/pepea-scholarship', 'https://search.studyaustralia.gov.au/scholarship/pepea-scholarship/8ed9cf1eebf8adeef29f5b422ecbc27e', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'PEPEA Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Pearl Pathway Partnership', 'Have you recently completed your Foundation Diploma, Basic Diploma and Advanced Diploma of Fashion Design / Communication Design from Pearl Academy? Join us on one of the Bachelor of Communication Design, Bachelor of Branded Fashion Design, Bachelor of Interior Design (Commercial) or Bachelor of Interior Design (Residential), and take advantage of 30 per cent scholarship off your total course tuition.', 'Students who complete their Foundation Diploma, Basic Diploma and Advanced Diploma of Fashion Design / Communication Design from Pearl Academy can pathway into our Bachelor of Communication Design, Bachelor of Branded Fashion Design, Bachelor of Interior Design (Commercial) and Bachelor of Interior Design (Residential) provided they meet admissions entry requirements.', '30% off tuition fees', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/pearl-pathway-scholarship', 'https://search.studyaustralia.gov.au/scholarship/pearl-pathway-partnership/c0c68fcf46f67d009d8b8eb014495381', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Pearl Pathway Partnership') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Three Pillars Blue Mountains International Hotel Management School Hospitality Scholarship', 'This scholarship is based on a Three-Pillar Approach to learning: Professional and Personal Growth, Practical Skills Development, and Academic Achievement. Its designed to help you graduate well-rounded, worldly, confident and prepared for a rewarding future. This scholarship will cover up to 30 percent of your total course tuition. Its available to new international students enrolling at the Blue Mountains International Hotel Management School in 2025.', 'Undergraduate and postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. Scholarship applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study. Successful applicants will be requested to assist with additional duties during their time as a student. These responsibilities will include, becoming members of the Student Representative Council, undertaking additional student ambassadorial duties and being available for promotional opportunities.', 'Limited 3 pillar scholarships ranging from 10% to 30%', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships', 'https://search.studyaustralia.gov.au/scholarship/three-pillars-blue-mountains-international-hotel-management-school-hospitality-scholarship/444582e94b6376c63d1a5474cf13845f', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Three Pillars Blue Mountains International Hotel Management School Hospitality Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Three Pillars Scholarship', 'Scholarships will be awarded based on our Three Pillar Approach to learning. These three pillars are Professional and Personal Growth, Practical Skills Development, and Academic Achievement - ensure that you graduate well-rounded, worldly, confident and prepared for a rewarding future.', 'Recipients must be new BMIHMS at Torrens University students commencing studies. For more information, please click on \'more information\'', 'Up to AUD $20000', 'Undergraduate / VET', NULL, 'https://www.bluemountains.edu.au/apply/scholarships-available/', 'https://search.studyaustralia.gov.au/scholarship/three-pillars-scholarship/6980b5b2f3ee6dd56620ff48709699d4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Three Pillars Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Val Cook Scholarship', 'Value: Full tuition for the Diploma degree (1 year). The Val Cook Scholarship, named after BMIHMS long term Alumni Ambassador and sponsored by the school`s Alumni board, will grant one student a scholarship (tuition, room and board) for the first year of their Bachelor course (diploma level).', 'Applicants must have 2-5 years of hospitality/ tourism industry experience.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://www.bluemountains.edu.au/apply/scholarships-available/', 'https://search.studyaustralia.gov.au/scholarship/val-cook-scholarship/be6c73b37d507b05f554bc6c78bb88e4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03389E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Val Cook Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Merit Based Scholarship', 'The Scholarship provides tuition assistance to graduating international high school students who have completed studies in commerce, accounting, or business in high school. Applicants must demonstrate a strong commitment to their community and provide evidence of involvement in cocurricular or extracurricular activities throughout high school. This is a merit-based scholarship that recognises applicants with a strong academic background and incentivises them to continue striving for excellence.', 'Be an international student commencing a Bachelor of Business for the first time at Sheridan in Semester 2, 2025 or Semester 1, 2026; Be 17 years of age or over; Apply for direct entry only; Have submitted the Scholarship application form and provided requested evidence by the relevant deadline; Satisfy all entry requirements for an intended course and Sheridan’s admissions process, including the student interview; Have accepted a Letter of Offer & Acceptance issued by Sheridan; Have signed and returned the Scholarship Terms and Conditions to Sheridan by the relevant deadline; Agree the Scholarship is not transferrable; Successfully commence study in the semester and year indicated in the Letter of Offer and Acceptance. If commencement is deferred, the scholarship may be forfeited; Successfully organise his/her Australian Student Visa to be able to arrive in Perth and study faceto-face at Sheridan', 'Recipients will receive a 100% scholarship towards their tuition fees', 'Undergraduate / VET', NULL, 'https://sheridan.edu.au/index.php/component/quix/113-scholarships', 'https://search.studyaustralia.gov.au/scholarship/international-merit-based-scholarship/d3d5078fb631f2fd6034b1c6a12a55ca', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03391M' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Merit Based Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Collarts International Scholarship', 'Scholarships are now available for international students and valid for all international study applications from March 2024! Start your dream course in the creative field while we ease the financial load across your studies-eligible students can receive up to $11,000 AUD for a Bachelor or up to $3,600AUD for a Diploma.', 'Applicants must submit a 300 word statement along with their application explaining why they should be awarded the scholarship; Approved applicants must comply with their visa conditions and obligations as Collarts students; Applicants must meet Collarts entry requirements; Scholarships are limited and awarded at the discretion of the Collarts International Team; Valid for applications received in 2024; Students must pay their fees on time to maintain eligibility; Students must maintain a credit (65%) average or above in their Collarts studies to maintain eligibility.', 'Up to AUD $11000', 'Postgraduate, Undergraduate / VET', NULL, 'https://international.collarts.edu.au/faq#phase-3', 'https://search.studyaustralia.gov.au/scholarship/collarts-international-scholarship/2187f51c2c1f6ebb6e87e039ed84a2c3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03392K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Collarts International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'NCAP Gateway to Global Nursing Scholarship Program.', 'We recognise the challenges that COVID-19 is presenting to our international as well as domestic students who wish to begin their study at IHM. We understand that this is a difficult time for our international students, particularly when it comes to their finances. Hence, through our scholarships along with continuing support to our students to help them advance in their career. A scholarship provides financial assistance during your study. Some scholarships provide a stipend that covers tuition fees, while others provide only partial funding. We understand how important education is to fulfil your potential, and that access to a scholarship can help make that happen.', 'To be eligible for IHM’s NCAP Gateway to Global Nursing Scholarship program an applicant should:; Satisfy the admission criteria for IHM courses; Demonstrate successful completion of a recognised Bachelor of Nursing course / 3 year international diploma of Nursing course with a minimum overall score of 70%; Demonstrate superior leadership and initiative in nursing by completing a 500 word response detailing:; why you should be considered for an IHM NCAP Gateway to Global Nursing Scholarship\r\nwhat have you contributed to the nursing sector in your area(s) of work, and your career plans and educational goals; Include a Letter of Support from your current employer or from the Institute where you completed your undergraduate nursing education.', 'Up to AUD $10000 — Up to 6 months (full-time); Up to 12 months (part-time)', 'Postgraduate', NULL, 'https://ihm.edu.au/scholarship/', 'https://search.studyaustralia.gov.au/scholarship/ncap-gateway-to-global-nursing-scholarship-program/5ee458bbdcb0ebaf8690fd7ad2e9a8d4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03407G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'NCAP Gateway to Global Nursing Scholarship Program.') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General and Academic Excellence Scholarships', 'Oakleigh Grammar offers scholarships to students who are talented, motivated and civic-minded, and who have the potential to make a positive contribution in a leadership and academic capacity, becoming part of our close-knit community. Our scholarships are granted to a handful of talented and passionate students who wish to excel in their learning journey, be it in sport, science, art, music or community.', 'Successful applicants will be curious learners, active sports participants, musically talented or community focused.\r\n\r\nTo apply for a General Excellence Scholarship, a student will have a good academic standard, plus excellence in at least one the following: sport, music, leadership, community service.\r\n\r\nAll scholarship candidates (including current Oakleigh Grammar students) must sit the ACER examination and also provide the following information when lodging their Scholarship Application form with ACER.\r\n\r\nSchool report\r\nNaplan test results (most recent)\r\nCertificates of achievement\r\nSporting ability/achievements\r\nMusic ability/achievements\r\nLeadership achievements and Community Service.\r\nScholarship applicants must include this information with their application, including levels attained.\r\n\r\nStudents applying for scholarships may like to include a reference from a teacher, principal, sporting organisation, church group, community service organisation, etc (though this is not essential).\r\n\r\nInterviews will be held with the Heads of School after the student scholarship exam results have been released.', 'Partial remission of tuition fees for the duration of enrolment.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-and-academic-excellence-scholarships/aa1e24974234e7fb6f8ea997ddc48e65', 'https://search.studyaustralia.gov.au/scholarship/general-and-academic-excellence-scholarships/aa1e24974234e7fb6f8ea997ddc48e65', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03423G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General and Academic Excellence Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', 'The Academic Scholarship recognises high achieving students with a demonstrated track record of academic excellent. Valued at up to 50% of tuition fees, based on the strength of your application.', '1. Demonstrated record of academic excellence, evidenced by test scores, results, or grades from one or more subject areas over time. 2. Demonstrated record of outstanding academic achievement, evidenced by honours/awards accomplished through curricular or extracurricular activities, highlighting talent and dedication.', 'See scholarship details', 'Primary schooling, Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/286fd8ac091b0009f14027a1c9959305', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/286fd8ac091b0009f14027a1c9959305', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03547G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
