INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'International Student Bursary - Brisbane Campus', 'The bursary is open to prospective students and offer holders for a Master of Engineering course at EITs Brisbane campus starting in Semester 2, 2024.', 'Be a new student commencing an on-campus Master of Engineering degree for the August 2024 intake at our Brisbane Campus; Be enrolling into an EIT Higher Education (HE) on-campus program for the first time.', '20% reduction on your Master’s tuition fees (Semester 2, 2024 only).', 'Postgraduate', NULL, 'https://www.eit.edu.au/scholarships/international-student-bursary-brisbane-campus/', 'https://search.studyaustralia.gov.au/scholarship/international-student-bursary-brisbane-campus/d19d1d6e4e581c8fc50d65b5b6a5a4ae', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03567C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Student Bursary - Brisbane Campus') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Human Services Scholarships', 'Ikon is offering a financial scholarship to new international students that commence a Human Services course at Ikon in calendar year 2025 or 2026.', 'Only applicable to international students on a subclass 500 student visa.; Student must be accepted into and commence an applicable course in 2025 or 2026.', 'Applicable tuition fees for any Arts Therapy & Counselling and Psychotherapy course will be reduced by 30% for the duration of the course.\r\nApplicable tuition fees for any Community Services course will be reduced by 25% for the duration of the cours', 'Undergraduate / VET', NULL, 'https://ikon.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/human-services-scholarships/3eb0de71bae89b3c23fa680d63cb9b78', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03581E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Human Services Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Regional Diversity Scholarships', 'Ikon is offering a financial scholarship to new international students from the Latin American, European, Middle Eastern and African regions commencing any Bachelor course with Ikon in calendar year 2025 or 2026.', 'Student must be accepted into and commence an applicable course in 2025 or 2026.', 'Applicable tuition fees for any Arts Therapy & Bachelor of Counselling and Psychotherapy course will be reduced by 35% for the duration of the course.\r\nApplicable tuition fees for any Early Childhood Education & Community Services course will be redu', 'Postgraduate, Undergraduate / VET', NULL, 'https://ikon.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/regional-diversity-scholarships/9a885dd598aa2027551489828b590109', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03581E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Regional Diversity Scholarships') LIMIT 1;
