INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship', 'The Academic Scholarship recognises high achieving students with a demonstrated track record of academic excellent. Valued at up to 50% of tuition fees, based on the strength of your application.', '1. Demonstrated record of academic excellence, evidenced by test scores, results, or grades from one or more subject areas over time. 2. Demonstrated record of outstanding academic achievement, evidenced by honours/awards accomplished through curricular or extracurricular activities, highlighting talent and dedication.', 'See scholarship details', 'Primary schooling, Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/f47441928963dc5433952837f007f86d', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/f47441928963dc5433952837f007f86d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03801J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
