INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarships (International Students Only)', 'A student must be enrolled in full-time study load (4 courses per semester OR 3 courses per semester if enrolled in Graduate Diploma of Business or Master of Business Administration) to be eligible for scholarship. The academic scholarship will be credited towards next semester tuition fee. Scholarship cannot be redeemed in cash. Students must apply and use the academic scholarship within 6 months of receiving the notification of results for a particular semester. The academic scholarship will not be available to students who are in their final semester of studies at CIM. The maximum academic scholarship available to each student is $500 per semester. Academic scholarship is provided in the following amounts: $150 for each course in which a student achieves Distinction (DI); $250 for each course in which a student achieves High Distinction (HD); Total academic scholarship amount is capped at $500 per semester.', 'Contact Canterbury Institute of Management for details.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://ciom.edu.au/apply-for-scholarship/', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-international-students-only/6f00814297b6fa87fd48c78f843840a1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03809A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarships (International Students Only)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Diversity & Success Scholarship', 'Diversity & Success Scholarship 2025 for Onshore and Offshore fees', 'For further information regarding eligibility, please contact the Higher Education Leadership Institute.', 'Up to 37% scholarship off 2025 fees!', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.heli.edu.au/scholarship/', 'https://search.studyaustralia.gov.au/scholarship/diversity-success-scholarship/8a2ab995d0b283c3cb8d00fb1df60135', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03845H' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Diversity & Success Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Future Leaders Scholarship', 'Future Leaders Scholarship for Onshore International Students', 'For further information regarding eligibility, please contact the Higher Education Leadership Institute.', 'Up to 36% scholarship off 2025 fees!', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.heli.edu.au/scholarship/', 'https://search.studyaustralia.gov.au/scholarship/future-leaders-scholarship/f3cc35889c8d5cddbc80bd08e1d705ca', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03845H' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Future Leaders Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Global Achievement Scholarship', 'Global Achievement Scholarship for Offshore International Students', 'For further information regarding eligibility, please contact the Higher Education Leadership Institute.', 'Up to 35% scholarship off 2025 fees!', 'Postgraduate, Undergraduate / VET', NULL, 'https://www.heli.edu.au/scholarship/', 'https://search.studyaustralia.gov.au/scholarship/global-achievement-scholarship/7a0327560a48af26d578130476bff9fd', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03845H' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Global Achievement Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UHE Academic Achievement scholarship', 'Merit based and only available for continuing students, who has completed first year of study with excellent academic results. Scholarship offered for students enrolled in UHE undergraduate programs and will be available for students who have successfully completed their first year of study at UHE. Candidates who hold UHE Academic Excellence (merit-based) Scholarship or UHE Financial Assistance Scholarship will not be eligible for this scholarship.', 'Be an international student enrolled as a full-time student in the semester to which the benefit would apply.; Have achieved an average overall percentage of 80.0% or more, with no individual result below 70.0% in the preceding semester and have no fail grades recorded; Have IELTS (academic) result with an overall score of 6.0 with no band less than 5.5 (for Bachelor students) and overall score of 6.5 with no band less than 6.0 (for Masters students). Documentary evidence of a current (test date within two years of date of application) IELTS certification must accompany the application.; Have completed at least two semesters full-time as per program requirements of the program at UHE.; Have a minimum attendance record of 75% in all scheduled classes.; Each application must be accompanied by a 500-750 words personal statement outlining why receipt of the scholarship is important.; Have made the fee payment for the subsequent semester’s full-time enrolment.; Not be sponsored by other organisations or governments.; Have submitted a completed application form before the application closing date.; Have maintained enrolment in the program in which they commenced.; If a student withdraws from the course, they will forfeit the scholarship.w', 'Up to AUD $1000 — Successful applicants who are awarded a scholarship will receive a fee deduction of equivalent to $1000 of the tuition fee of a program he or she is enrolled for the commencing semester, March, or July. This scholarship is not trans', 'Undergraduate / VET', NULL, 'https://www.uhe.edu.au/scholarships-commendations', 'https://search.studyaustralia.gov.au/scholarship/uhe-academic-achievement-scholarship/02aa67783c44200b31bcb7fbea8b97e6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03848E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UHE Academic Achievement scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UHE Academic Excellence (merit-based) Scholarship', 'This scholarship is merit based and is available for new students who will be commencing in 2025. The UHE Academic Excellence Scholarship (International Students) would benefit international students, who have demonstrated academic excellence to peruse their higher education dreams in Australia. Candidates who hold this scholarship will not be eligible to apply for UHE Academic Achievement Scholarship for high achievers or UHE Financial Assistance Scholarship.', 'Enrolled as a full-time student and be a commencing international student for the semester to which the benefit applies.; Completed Australian Year 12 or equivalent with overall grade average of 70% or more, with no individual result below 65% and have no fail grades recorded; IELTS (academic) result with an overall score of 6.0 with no band less than 5.5. Documentary evidence of a current (test date within two years of date of application) IELTS certification must accompany the application.; Application must be accompanied by a 500-750 words personal statement outlining why receipt of the scholarship in important.; Not be sponsored by organisations or governments.; Have submitted a completed application form before the application closing date.; If a student withdraws from the course, they will forfeit the scholarship.', 'Up to AUD $6000 — Successful applicants who are awarded a scholarship will receive a fee deduction of equivalent to $1000 of the tuition fee of a program he/ she is enrolled for the commencing semester, March, July or November. This scholarship is no', 'Undergraduate / VET', NULL, 'https://www.uhe.edu.au/scholarships-commendations', 'https://search.studyaustralia.gov.au/scholarship/uhe-academic-excellence-merit-based-scholarship/bc5669418c7a8d1b28cc91edcd7cdb03', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03848E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UHE Academic Excellence (merit-based) Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'UHE Financial Assistance Scholarship', 'Awarded to students facing financial hardship in the intention of taking the financial pressure off them. Applicants need to successfully complete first semester of study at UHE. This scholarship will be available for students, who have successfully completed year one of study at UHE. Candidates who hold UHE Academic Excellence (merit-based) Scholarship or UHE Academic Achievement Scholarship for high achievers will not be eligible for this scholarship.', 'Be an international student enrolled as a full-time student in the semester to which the benefit would apply.; Current financial hardship - Student needs to provide sufficient evidence to demonstrate ongoing financial hardship.; Students must study full-time (0.5 EFTSL / 40 credit points) in each semester.; To continue receiving the scholarship into the future semesters, students must maintain a 100% pass rate each semester.; Application must be accompanied by a 500-750 words personal statement outlining the financial hardship he/she is undergoing and why receipt of the scholarship in important.; Not be sponsored by organisations or governments.; Have submitted a completed application form before the application closing date.; If a student withdraws from the course, they will forfeit the scholarship.', 'Successful applicants who are awarded a scholarship will receive a fee deduction of equivalent to $1000 of the tuition fee of a program he or she is enrolled for the commencing semester, March or July. This scholarship is not transferable to another', 'Undergraduate / VET', NULL, 'https://www.uhe.edu.au/scholarships-commendations', 'https://search.studyaustralia.gov.au/scholarship/uhe-financial-assistance-scholarship/f5e11599cce68ab1ef5c79e5fb4ffda6', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03848E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'UHE Financial Assistance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '25% Offshore Scholarship', 'At Sydney Institute of Higher Education (SIHE), we are committed to supporting your academic journey and helping you achieve your educational goals. We offer a range of scholarships to recognise academic excellence, encourage diversity, and make a quality education accessible to deserving students.', 'Please Contact Sydney Institute if Higher Education for more information about Eligibility', 'To encourage diversity and support student with developed English language skills, the scholarship, valued at 25% of tuition fees, is available to commencing students who enrol into any SIHE program for the June 2025 intake.', 'Undergraduate / VET', NULL, 'https://sydneyinstitute.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/25-offshore-scholarship/26df4a34256be32e535346be258694ae', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03866C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '25% Offshore Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, '35% Onshore Scholarship', 'At Sydney Institute of Higher Education (SIHE), we are committed to supporting your academic journey and helping you achieve your educational goals. We offer a range of scholarships to recognize academic excellence, encourage diversity, and make a quality education accessible to deserving students.', 'Please Contact Sydney Institute of Higher Education for more information about Eligibility', 'To support and encourage onshore students with developed English language skills, the scholarship, valued at 35% of tuition fees, is available to commencing students who enrol into any SIHE program for the June 2025 intake.', 'Undergraduate / VET', NULL, 'https://sydneyinstitute.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/35-onshore-scholarship/be446a25d4851978f1109ae0dcd869fe', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03866C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '35% Onshore Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Full-time Scholarships', 'At Sydney Institute of Higher Education (SIHE), we are committed to supporting your academic journey and helping you achieve your educational goals. We offer a range of scholarships to recognise academic excellence, encourage diversity, and make a quality education accessible to deserving students.', 'Please Contact Sydney Institute of Higher Education for more information about Eligibility.', 'AUD $19600/year', 'Undergraduate / VET', 'Business and management', 'https://sydneyinstitute.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/full-time-scholarships/5dc390f08f279cea37b668a38e00e39d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03866C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Full-time Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'EIA Meritorious Scholarship', 'Prospective international Student achieved a higher performance percentage above 75% in a Year 12 equivalent study and demonstrate strong English proficiency with IELTS 6.5 or above overall score (no band score lower than 6.0) or equivalent. EIA offer scholarship to eligible students up to 30% of full tuition fees for the full course duration and will be reviewed each trimester based on student performance.', 'Contact Edvantage Institute Australia Pty Ltd for details.', 'See scholarship details', 'Undergraduate / VET', NULL, 'https://eia.edu.au/fees-scholarships/', 'https://search.studyaustralia.gov.au/scholarship/eia-meritorious-scholarship/ee33e1a537622a1e9364ba25e3212c57', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03879J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'EIA Meritorious Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'APAC International Scholarship', 'The APAC International Scholarship offers a 30% reduction of the course tuition fees and will be awarded as a fee discount from the second trimester of study, conditional on satisfactory completion of the first trimester of study.', 'To be eligible for a scholarship applicants must have successfully passed the audition or portfolio requirements and course application process for one of the three APAC courses:• Bachelor of Screen and Stage (Screen Production)• Bachelor of Screen and Stage (Acting)• Bachelor of Screen and Stage (Song and Dance).', 'See scholarship details', 'Undergraduate / VET', 'Creative arts', 'https://apac.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/apac-international-scholarship/a40fce72f7c2474603b7dc1952a2f26a', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03897G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'APAC International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Global Achievement Scholarship', 'Global Achievement Scholarship', 'Contact ECA Higher Education Institute Pty Ltd for details', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://chs.edu.au/wp-content/uploads/2025/03/Global-Achievement-Scholarship.pdf', 'https://search.studyaustralia.gov.au/scholarship/global-achievement-scholarship/9ac5f40bd333c530349ca1ea4084cfc3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '03932J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Global Achievement Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Integrated English High Diversity Scholarship', 'This scholarship is designed to support international students from eligible countries to enrol in our Integrated English program. Scholarship recipients must choose to study for a minimum of 15 weeks and up to a maximum of 45 weeks.', '- Hold a passport from an eligible country.- Have not received another scholarship, tuition fee reduction or rebate from UQ or UQC.- Have not received a full scholarship/sponsorship from another organisation (partial scholarships/sponsorships will be considered at UQC’s discretion).', '30% reduction in tuition fees and enrolment fee waived.', 'Undergraduate / VET', NULL, 'https://uqcollege.uq.edu.au/scholarships', 'https://search.studyaustralia.gov.au/scholarship/integrated-english-high-diversity-scholarship/23b4d3b4eb7bd645c13b0a97540fdc68', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04039H' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Integrated English High Diversity Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Global Leadership Institute Scholarship', 'To promote excellence in scholarship and learning, Global Leadership Institute will offer scholarships to outstanding students for courses subject to budget constraints.', 'For further information regarding eligibility, please contact the Global Leader Institute.', '35% fee discount', 'Postgraduate', NULL, 'https://gli.edu.au/scholarships/', 'https://search.studyaustralia.gov.au/scholarship/global-leadership-institute-scholarship/78bdc8f45ec641e9cd60a7786e96b975', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04218E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Global Leadership Institute Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Hospitality French & Italian Cuisine Specialist', '$1000 Off', '2 Year Experience in the Industry', 'Up to AUD $1000 — $1000 off on tuition fees', 'Undergraduate / VET', NULL, 'https://www.russellcollege.edu.au', 'https://search.studyaustralia.gov.au/scholarship/hospitality-french-italian-cuisine-specialist/97425d512c56b1dfe489b8e7bfdb8412', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04221K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Hospitality French & Italian Cuisine Specialist') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Adelaide Academic Excellence Scholarship (50%)', 'The Adelaide Academic Excellence Scholarship offers a 50% tuition fee reduction and is a prestigious, highly competitive award with limited places for students with a high distinction average. This scholarship recognises international students commencing undergraduate or postgraduate coursework degrees who have achieved outstanding academic performance in their previous studies.', 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 96 units / 2 years equivalent) after the application of any credit/RPL, or a CRICOS registered master degree (minimum 72 units / 1.5 years equivalent) after the application of any credit/RPL, at Adelaide University; satisfy one of the following in the qualification used as the basis of admission to the Adelaide University degree:; Undergraduate only: applicants with a minimum ATAR of 99 (or international equivalent).; Undergraduate and postgraduate: applicants with a minimum overall Grade Point Average (GPA) of 6.7 (on a 7.0 scale) or comparable score.; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship value, in which case the fee waiver amount will apply.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://adelaide.edu.au/study/scholarships/int/adelaide-academic-excellence-scholarship-50/', 'https://search.studyaustralia.gov.au/scholarship/adelaide-academic-excellence-scholarship-50/9fc72ece7254f4cbc866ef98ea0917df', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04249J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Adelaide Academic Excellence Scholarship (50%)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Adelaide Emerging Leaders Award (25%)', 'The Adelaide Emerging Leaders Award provides a 25% tuition fee reduction for international students starting an undergraduate or postgraduate coursework degree, it is automatically awarded at the time of offer to applicants who have achieved a distinction average and shown leadership qualities through strong academic commitment.', 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 72 units / 1.5 years equivalent) after the application of any credit/RPL, or a CRICOS registered master degree (minimum 48 units / 1 year equivalent) after the application of any credit/RPL, at Adelaide University; satisfy one of the following as the basis of admission to the Adelaide University degree:; Undergraduate only:; A minimum ATAR of 90 for students who have completed the Australian Senior Secondary Certificate of Education (SSCE).; A minimum score of 33 for students who have completed the International Baccalaureate (IB) Diploma; A minimum score of 12 for students who have completed the GCE A levels; A minimum ATAR of 95 (or international equivalent) for any other secondary certificate.; Undergraduate and postgraduate:; A minimum overall Grade Point Average (GPA) of 5.5 (on a 7.0 scale) for a completed award from Adelaide University (or with a comparable score for a qualification completed at an Australian University).; A minimum overall GPA of 6.0 (on a 7.0 scale) or comparable.; A minimum overall GPA of 5.5 (on a 7.0 scale) or equivalent from a program completed at an approved Adelaide University pathway provider.; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship value, in which case the fee waiver amount will apply.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://adelaide.edu.au/study/scholarships/int/adelaide-emerging-leaders-award-25/', 'https://search.studyaustralia.gov.au/scholarship/adelaide-emerging-leaders-award-25/07ecec3064de6ba13f7f7ddd95554c7d', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04249J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Adelaide Emerging Leaders Award (25%)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Adelaide Global Alumni Scholarship (10%)', 'The Adelaide Global Alumni Scholarship offers a 10% tuition fee reduction. This scholarship is automatically assessed and awarded to international students commencing undergraduate or postgraduate coursework degrees who have previously studied at Adelaide University, the University of South Australia or the University of Adelaide.', 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 72 units / 1.5 years equivalent) after the application of any credit / RPL, or a CRICOS registered master degree (minimum 48 units / 1 year equivalent) after the application of any credit / RPL, at Adelaide University; provide verifiable evidence that they have previously completed a degree at Adelaide University or the University of South Australia or the University of Adelaide and / or have completed at least one semester of a Study Abroad Program at one of these institutions; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship value, in which case the fee waiver amount will apply.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://adelaide.edu.au/study/scholarships/int/adelaide-global-alumni-scholarship-10/', 'https://search.studyaustralia.gov.au/scholarship/adelaide-global-alumni-scholarship-10/5a506062117057a6431c4fe5001e7bc1', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04249J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Adelaide Global Alumni Scholarship (10%)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Adelaide Merit Scholarship (15%)', 'The Adelaide Merit Scholarship provides a 15% tuition fee reduction for international students starting an undergraduate or postgraduate coursework degree and is automatically awarded at the time of offer to applicants who have achieved a credit average and shown strong academic commitment. This scholarship supports international students commencing undergraduate or postgraduate coursework degrees who are committed to their academic achievement.', 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 72 units / 1.5 years equivalent) after the application of any credit/RPL, or a CRICOS registered master degree (minimum 48 units / 1 year equivalent) after the application of any credit/RPL, at Adelaide University; satisfy one of the following in the qualification used as the basis of admission to the Adelaide University degree:; Undergraduate only:; A minimum ATAR of 75 for students who have completed the Australian Senior Secondary Certificate of Education (SSCE) (or international equivalent for any other secondary certificate).; Successful completion of a competency-based vocational qualification in Australia with an overall non-graded pass.; Undergraduate and postgraduate:; A minimum overall Grade Point Average (GPA) of 4.5 (on a 7.0 scale) for an award completed at Adelaide University (or with a comparable score for a qualification completed at an Australian University).; A minimum overall Grade Point Average (GPA) of 5.0 (on a 7.0 scale) or comparable.; A minimum overall Grade Point Average (GPA) of 4.5 (on a 7.0 scale) or equivalent from a program completed at an approved Adelaide University pathway provider.; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://adelaide.edu.au/study/scholarships/int/adelaide-merit-scholarship-15/', 'https://search.studyaustralia.gov.au/scholarship/adelaide-merit-scholarship-15/8f14e2897ea65ca82f25f3641b43d3e4', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04249J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Adelaide Merit Scholarship (15%)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Adelaide Partner Award (10%)', 'The Adelaide Partner Award offers a 10% tuition fee reduction and is automatically assessed and awarded to students from an approved Adelaide University partner institution. This scholarship supports international students commencing undergraduate or postgraduate coursework degrees.', 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 72 units / 1.5 years equivalent) after the application of any credit/RPL, or a CRICOS registered master degree (minimum 48 units / 1 year equivalent) after the application of any credit/RPL, at Adelaide University; be admitted to an Adelaide University degree using a qualification (complete or incomplete) from an Approved Partner Institution as the basis of admission in the application; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship value, in which case the fee waiver amount will apply.', 'See scholarship details', 'Postgraduate, Undergraduate / VET', NULL, 'https://adelaide.edu.au/study/scholarships/int/adelaide-partner-award-10/', 'https://search.studyaustralia.gov.au/scholarship/adelaide-partner-award-10/a66415a5626881f2ab3702313f2552a8', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04249J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Adelaide Partner Award (10%)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Academic Scholarship - Year 7', NULL, 'For entry into Year 7. Successful applicants are selected based on a scholorship test, school reports and an interview.', 'Scholarships awarded to commence in Year 7 provide partial remission of tuition fees until the end of Year 12, subject to the student’s continuing superior performance and her ongoing contribution to the life of the School.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship-year-7/ca9bbb3626365b704e3107c80feebdb3', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship-year-7/ca9bbb3626365b704e3107c80feebdb3', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04366D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship - Year 7') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'General Excellence - Years 5, 9, 10, 11', NULL, 'Based on assessment of application, school reports and an interview For Year 5 General Excellence Scholarships applicants are also required to sit a scholarship test.', 'Scholarships awarded to provide partial remission of tuition fees until the end of Year 12, subject to the student’s continuing superior performance and her ongoing contribution to the life of the School.', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/general-excellence-years-5-9-10-11/c31939cea63bb13bd1ae55b6052b4f15', 'https://search.studyaustralia.gov.au/scholarship/general-excellence-years-5-9-10-11/c31939cea63bb13bd1ae55b6052b4f15', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04366D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'General Excellence - Years 5, 9, 10, 11') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'Music Scholarship - Years 7 - 10', NULL, 'Based on assessment of school reports, an interview and audition.', 'Music Scholarships provide partial remission of tuition fees until the end of Year 12, subject to the student’s continuing superior performance and her ongoing contribution to the life of the School. Students who are awarded a Music Scholarship are e', 'Secondary schooling', NULL, 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-years-7-10/a78cd718670a08968c792ed029cf8c09', 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-years-7-10/a78cd718670a08968c792ed029cf8c09', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04366D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Music Scholarship - Years 7 - 10') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `eligibility`, `scholarship_amount`, `level_of_studies`, `field_of_studies`, `website`, `source_url`, `created_at`, `updated_at`) SELECT 1, NULL, pi.`id`, 'EIC Scholarship 2026 (Closing soon)', 'Eligible Students enrolled from September 2026 are eligible to claim $500.00 AU scholarship per semester for ALL COURSE', 'Satisfactory attendance records (>80%)Satisfactory academic records (all units are competence)', '$500.00 AU scholarship per semester for ALL COURSESatisfactory attendance records (>80%)Satisfactory academic records (all units are competence)', 'Undergraduate / VET', 'Business and management, Tourism and hospitality', 'https://www.elevare.edu.au', 'https://search.studyaustralia.gov.au/scholarship/eic-scholarship-2026-closing-soon/437c8f046b6cf045382aecdc6fed4f99', '2026-11-06 02:28:27', '2026-11-06 02:28:27' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '04367C' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'EIC Scholarship 2026 (Closing soon)') LIMIT 1;
