UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'UNE offers eligible commencing international students a bursary in the form of a 20% fee reduction of the published 2025 annual international tuition fees for their first year of study.', sc.`eligibility` = 'Please contact University of New England (UNE) for further information.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.une.edu.au/international/fees-and-scholarships/scholarships-and-other-financial-support/bursaries', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/bursaries/0a7e5cd74e819a4647d1397d7f178bc3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00003G' AND sc.`scholarship_name` = 'Bursaries' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The project is looking at developing research-based models for data analytics using AI and Machine learning techniques in the domains of medical and educational data analytics. These models will assist and facilitate the medical professionals with machine learning modelling-based decision support tools for better patient support through diagnosis, prognosis and monitoring patient conditions. Further education analytics will help in improving learning & teaching and student engagement improvement in higher education settings.', sc.`eligibility` = '-', sc.`scholarship_amount` = 'Up to AUD $129017', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.une.edu.au/scholarships/higher-degree-research-scholarships/machine-learning-modelling-to-analyse-medical-and-educational-data-including-imaging-video-and-text-based-reports.', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/machine-learning-modelling-to-analyse-medical-and-educational-data-including-imaging-video-and-text-based-reports/1d1f38a0bd5df61613ddb0e5223bea55', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00003G' AND sc.`scholarship_name` = 'Machine Learning modelling to analyse medical and educational data including imaging, video and text-based reports.' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Australian agriculture faces growing pressure to quantify, report, and reduce its greenhouse gas (GHG) emissions. Yet the methodological foundations for on-farm GHG accounting remain inconsistent across industry calculators, national inventory methods, and voluntary reporting frameworks. Key unresolved issues, including the treatment of carbon opportunity costs, the permanence of carbon sequestration, the risk of double counting, and the management of reversal risk, create ambiguity for farmers, agribusiness, and policymakers alike, and undermine confidence in emissions reduction claims. This PhD scholarship, funded through the Zero Net Emissions Agriculture CRC (ZNE-Ag CRC), will address these gaps by developing rigorous, nationally consistent guidance for on-farm GHG accounting in Australia. The candidate will focus on land use and carbon sequestration, analysing how methodological choices within accounting frameworks influence incentives for farmers and agribusiness, and how they affect the attribution of emissions reductions across supply chains. The research will be conducted in alignment with international best practice and will seek to harmonise approaches across industry tools, scheme and reporting requirements.', sc.`eligibility` = '-', sc.`scholarship_amount` = 'Up to AUD $132111 — This scholarship supports a PhD candidate to develop nationally consistent, practical guidance for on-farm greenhouse gas accounting in Australian agriculture, as part of the Zero Net Emissions Agriculture CRC. The research will e', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.une.edu.au/scholarships/higher-degree-research-scholarships/zero-net-emissions-agriculture-crc-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/zero-net-emissions-agriculture-crc-scholarship-guidance-for-on-farm-greenhouse-gas-accounting/4e54921f79a8a6efdcaab426bc36a951', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00003G' AND sc.`scholarship_name` = 'Zero Net Emissions Agriculture CRC Scholarship (guidance for on-farm greenhouse gas accounting)' AND sc.`course_id` IS NULL;
