UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A scholarship for students studying the Bachelor of Commerce (Honours) majoring in accounting or finance. Up to $6000 is available for one year only.', sc.`eligibility` = 'An Australian citizen. A New Zealand citizen. Australian permanent resident. Australian humanitarian visa holder. An International student.', sc.`scholarship_amount` = 'Up to AUD $6000 — Up to $6000 is available for one year only.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Accounting', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/accounting-honours-scholarship-5585A', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/accounting-honours-scholarship/ebd2c29fdb777872f618027bb613ad2e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Accounting Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Alfred Research Alliance Honours Scholarship is for students studying an Honours program on the Alfred campus, through the School of Translational Medicine, the School of Public Health and Preventive Medicine, or the Baker or Burnet institutes. Each scholarship is worth $6000: two are for any student enrolled full time in the Bachelor of Biomedical Science or the Bachelor Science Honours program, while the third is reserved for a Bachelor of Medical Science Honours student.', sc.`eligibility` = 'An Australian citizen. ; A New Zealand citizen. ; Australian permanent resident. ; Australian humanitarian visa holder. ; An International student.', sc.`scholarship_amount` = 'Up to AUD $6000 — $6000 per annum (48 credit points of study) for a maximum of one year.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Medicine, Sciences', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/ara-honours-scholarship-5596A', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alfred-research-alliance-honours-scholarship/f449849138b638d2701f18a0e635102d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Alfred Research Alliance Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Amplifying UNCLOUD Honours Scholarship at Monash University is available for an honours student to conduct a research project, together with one of our study partners or stakeholders, addressing an area of need in vaping prevention research among young adults.', sc.`eligibility` = 'Current student enrolled in an Honours program in the Department of General Practice in the School of Public Health and Preventative Medicine at a Monash Campus in Australia.; Have a WAM 65+ (Current students).; Participation in Access Monash Mentoring program or other Monash mentoring programs.', sc.`scholarship_amount` = 'Up to AUD $3000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/amplifying-uncloud-honours-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/amplifying-uncloud-honours-scholarship/b36f18a8f8a2ed1c8023be2d0d4618fd', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Amplifying UNCLOUD Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Arts Coursework Masters Research Grant provides financial support to Arts masters by coursework international students who are completing a pathway to Higher Degree by Research as part of their coursework studies.', sc.`eligibility` = 'You must meet the following criteria:; Current student in a Faculty of Arts Masters by coursework degree at a Monash Campus in Australia.; Have successfully completed APG5084 Designing research and APG5849 Research thesis A.; Enrolment in APG5850 Research thesis B.', sc.`scholarship_amount` = 'Up to AUD $6000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/arts-coursework-masters-research-grant-6293', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/arts-coursework-masters-research-grant/d7976f86b3e6ffb234c04c7de13de74b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Arts Coursework Masters Research Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The DEPM Prostate Cancer Research Scholarship is intended to encourage students to undertake further studies at Honours level in medicine at the Monash Alfred campus in the area of Public Health and Preventive Medicine, focusing principally on improving health outcomes for men diagnosed with prostate cancer.', sc.`eligibility` = 'Australian or New Zealand citizen, holder of an Australian permanent resident visa, permanent humanitarian visa or international student.; Obtain a minimum weighted average mark (WAM) of 70% or above, across undergraduate study in Bachelor of Medical Sciences (Honours) (MED4301 & MED4302), Bachelor of Biomedical Sciences (Honours) (BMS4100 & BMS4200), or the Bachelor of Health Sciences (Honours) (HSC4011, HSC4001 & 4002).; Commencing or continuing in a full-time School of Public Health and Preventive Medicine Honours program at the Monash Alfred campus (Bachelor of Medical Sciences (Honours) (MED4301 & MED4302), Bachelor of Biomedical Sciences (Honours) (BMS4100 & BMS4200), or the Bachelor of Health Sciences (Honours) (HSC4011, HSC4001 & 4002)).', sc.`scholarship_amount` = 'Up to AUD $3000 — $3000 for one year only.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/depm-prostate-cancer-research-scholarship-6063B', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/depm-prostate-cancer-research-scholarship/fe66396a1afcba71b34cd8b0955cea4d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'DEPM Prostate Cancer Research Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This Scholarship is to honour the important role that David Shugg played in the professionalism of paramedics. Throughout David\'s career, he advanced and embedded professionalism in paramedic training and education in the setting of emergency primary health care. In his legacy this Scholarship aims to support the next generation of leaders in paramedicine.', sc.`eligibility` = 'Enrolled in the Bachelor of Paramedicine (Honours) M3707 in the Department of Paramedicine at a Monash campus in Australia.; Have a WAM 80+ (Current students).', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/david-shugg-professionalism-scholarship-6270', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/david-shugg-professionalism-scholarship/cb417d592e48a97d5937be68527e52c5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'David Shugg Professionalism Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is awarded to high achieving students who enter into the Bachelor of Commerce (Honours) or the Bachelor of Economics (Honours) course.', sc.`eligibility` = 'You must meet the following criteria:; A commencing student, enrolling full-time in economics or jointly in economics and econometrics in the Bachelor of Commerce (Honours) degree or Bachelor of Economics (Honours) degree at the Monash Clayton campus.', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/department-of-economics-honours-merit-scholarship-6111', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/department-of-economics-honours-merit-scholarship/4dcc09127e9a658ee845c32fdd0af67a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Department of Economics Honours Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Marketing Honours Scholarship recognises outstanding academic achievement and supports high-performing students entering the Bachelor of Commerce (Honours) program majoring in Marketing at Monash University. This scholarship provides financial support to full-time students, awarded on the basis of academic excellence in their previous degree. It aims to encourage and assist talented students in pursuing advanced studies and research in marketing. The scholarship reflects the department\'s commitment to fostering academic excellence and preparing graduates for success in research, industry, and academia.', sc.`eligibility` = 'You must meet the following criteria:; Commencing student enrolled in the Bachelor of Commerce (Honours) majoring in Marketing  at a Monash Campus in Australia.; Recipients must achieve a minimum of WAM 75 in their previous degree.', sc.`scholarship_amount` = 'Up to AUD $6000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/department-of-marketing-honours-scholarship-6288', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/department-of-marketing-honours-scholarship/9999dd5617e2917e595a905119755f8f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Department of Marketing Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'These prestigious scholarships are awarded in memory of the tragic events that took place during October 2002 in the Department Econometrics and Business Statistics, and its honours students. A major fundraising campaign was launched by the Econometrics and Business Statistics Department and its alumni, and this, along with contributions from many others, has enabled the faculty to offer these scholarships.', sc.`eligibility` = 'An Australian citizen. A New Zealand citizen. Australian permanent resident. Australian humanitarian visa holder. An International student.', sc.`scholarship_amount` = 'Up to AUD $15000 — $15,000 for one year only (48 credit points of study).', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Economics', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/econometrics-honours-memorial-scholarship-5586', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/econometrics-honours-memorial-scholarship/f1cfa00faf74adbbe13177868e74a364', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Econometrics Honours Memorial Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Elevate your Engineering Experience with our Accommodation Scholarship! Immerse yourself in a vibrant, supportive community of students while receiving financial support for your housing needs. Choose from a range of comfortable accommodation options, allowing you to focus on your studies', sc.`eligibility` = 'A commencing student enrolled or intending to enrol in an undergraduate or postgraduate degree in the Faculty of Engineering at a Monash campus in Australia.; Must satisfy entry into an Engineering undergraduate or postgraduate program.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-accommodation-scholarship-6238', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/engineering-accommodation-scholarship/1d8470f63c820f27dba3fd3edc2fc74f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Engineering Accommodation Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Industry Teams is a supervised industry project where a team of students work collaboratively with Monash University and/or an industry partner to address a defined project need. Based primarily at the Monash Innovation Labs, each project involves a team comprising an academic supervisor, an industry supervisor, and the student members. This initiative provides students with the opportunity to apply independent thinking and problem-solving skills to develop or enhance products, methods, or services. Projects may be self-contained or form part of a larger innovation initiative.', sc.`eligibility` = 'You must meet the following criteria:; Current student enrolled in an undergraduate or Master\'s degree at a Monash campus in Australia.; Must be a member of a Monash Student Teams Initiative.; Conduct an interview with the industry partner.', sc.`scholarship_amount` = 'Up to AUD $4500 — $4,500 per student paid over 6 months only ($2,250 paid over 2 consecutive quarters).', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-industry-teams-scholarship-6279', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/engineering-industry-teams-scholarship/0c530c58329a41b394cde0b11e14e608', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Engineering Industry Teams Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Engineering International High Achievers Scholarship is introduced to recognise high achieving international students.', sc.`eligibility` = 'You must be studying as one of the following:; Undergraduate - A commencing student enrolling in a single undergraduate degree offered by the Faculty of Engineering.; Students must have an ATAR or International equivalent of 95+.; Students must have an ATAR or International equivalent of 95+.\r\nPostgraduate - A commencing student enrolling in a postgraduate degree offered by the Faculty of Engineering.; Students must have achieved a minimum WAM of 75 in their undergraduate degree.', sc.`scholarship_amount` = 'Undergraduate - $15,000 per 48 credit points, paid towards your tuition fees, up to four years.; Postgraduate - $15,000 per 48 credit points, paid towards your tuition fees.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-international-high-achievers-scholarship-6204', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/engineering-international-high-achievers-scholarship/28e6424450902f7a00fd56b6941e9fc1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Engineering International High Achievers Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A scholarship for high-achieving Year 12 students intending to enrol in the Bachelor of Engineering (Honours) and Master of Engineering pathway program. Up to 10 scholarships valued at up to $30,000 are available each year.', sc.`eligibility` = 'You must meet the following criteria:; A commencing undergraduate student intending to enrol in the Bachelor of Engineering (Honours) single degree and Master of Engineering pathway program at a Monash campus in Australia; Currently studying Australian Year 12 or IB, and; Must achieved a minimum ATAR score of 98.00.', sc.`scholarship_amount` = 'Up to AUD $6000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/engineering-masters-pathway-6056A', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/engineering-masters-pathway-scholarship/776ba2c1bfa1ba6351022bc4963ef156', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Engineering Masters Pathway Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Eric Dubsky was an electrical engineer who immigrated to Australia from Nazi occupied Austria shortly before the outbreak of World War II in 1939. Initially with his father and then as chairman and managing director he developed a small manufacturer Vulcan Electrics Pty Ltd into one of the top 100 companies in Australia - Vulcan Industries Australia Ltd. Vulcan produced a range of innovative domestic and commercial products and had 2000 employees. He employed engineering students as trainees with the company, many of whom became leaders with Vulcan and other engineering companies. This award continues his legacy by providing young engineers with the opportunity to develop into future leaders of Australian industry.', sc.`eligibility` = 'Applicants must: Be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student; Enrolled in any single or double undergraduate degree in the Faculty of Engineering at a Monash campus in Australia.; Have completed a minimum of 48 credit points in their Engineering degree.', sc.`scholarship_amount` = 'Up to AUD $30000 — $10,000 per annum for a maximum of three years.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Engineering and technology', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/eric-dubsky-memorial-5719', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/eric-dubsky-memorial-engineering-leadership-scholarship/16d33327b344d7a93bb4569bd41c8d29', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Eric Dubsky Memorial Engineering Leadership Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is for international students committed to studying at the Faculty of Information Technology at Monash. It aims to attract and reward high achieving international students from India, Sri Lanka and Bangladesh to the faculty. This scholarship serves dual purposes: it recognises excellence in achievement of our international students, whilst enriching our community by fostering diversity.', sc.`eligibility` = 'An International student. Must be enrolled to commence in, or hold an offer for one of the 3 listed IT single degree courses. You must be a citizen of and currently studying in India, Sri Lanka or Bangladesh. You must be completing your final year (equivalent Australian Year 12) offshore. International students currently studying Australian Year 12 onshore (in Australia) may be eligible for the Sir John Monash Scholarship for Excellence. ATAR score (or international equivalent) of 90+ for local A-Level / IB / CBSE awards.', sc.`scholarship_amount` = '20% off tuition fees paid for the duration of the course.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Computing and information technology', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/faculty-of-it-international-merit-scholarship-6232', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/faculty-of-it-international-merit-scholarship/fb112d9c2007f2d40d97a18cf29eee9d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Faculty of IT International Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship supports academically outstanding students undertaking the Bachelor of Commerce (Honours) majoring in Finance.', sc.`eligibility` = 'You must meet the following criteria:; Commencing full-time in the Bachelor of Commerce (Honours) (B3701) degree majoring in finance at a Monash University campus in Australia.', sc.`scholarship_amount` = 'Up to AUD $6000 — $6000 one-off payment.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/finance-honours-scholarship-6128', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/finance-honours-grant/0805ff42dde870cd03f949278cc4aa20', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Finance Honours Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Freemasons John Dann Music Scholarship was established to support talented students within the Sir Zelman Cowen School of Music and Performance at Monash University.', sc.`eligibility` = 'You must meet the following criteria:; Commencing or continuing undergraduate student enrolled or intending to enrol in an undergraduate degree in the Sir Zelman Cowen School of Music in the Faculty of Arts at a Monash campus in Australia.; Experiencing financial hardship.', sc.`scholarship_amount` = 'Up to AUD $6000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/freemasons-john-dann-music-scholarship-6226', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/freemasons-john-dann-music-scholarship/03187fcc726310bf4effc17ac7bd9cc5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Freemasons John Dann Music Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A scholarship for students intending to pursue an economics honours degree at Monash Business School: Bachelor of Commerce (Honours) or Bachelor of Economics (Honours). Based on academic achievement, you will be awarded a $15,000 scholarship if selected. No application is necessary. All students who apply for the course will be automatically assessed.', sc.`eligibility` = 'An Australian citizen.; A New Zealand citizen. ; Australian permanent resident. ; Australian humanitarian visa holder. ; An International student.', sc.`scholarship_amount` = 'Up to AUD $15000 — $15,000 paid for one year only.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Business and management, Economics', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/ian-little-honours-scholarship-5769', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ian-little-honours-scholarship/88b27291f1e30b8fc46cf931c1315802', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Ian Little Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This grant is awarded to high achieving students in the Faculty of Information Technology who undertake a 22 week placement with an industry partner. The grants provide support to the recipients as they benefit from the industry-based experience gained from the placements.', sc.`eligibility` = 'An Australian citizen. \r\nA New Zealand citizen. \r\nAustralian permanent resident. \r\nAustralian humanitarian visa holder. \r\nAn International student.', sc.`scholarship_amount` = 'Up to AUD $19000 — $19,000; 22 week placement with one of the industry partners of the Faculty of Information Technology.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Computing and information technology', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/information-technology-ibl-placement-grant-5607', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/information-technology-industry-based-learning-placement-grant/c2555d01f62bade39339997977151e4a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Information Technology Industry-Based Learning Placement Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is awarded in memory of Klaus Abbink, a Professor in Economics at Monash and a Director of The Monash Laboratory for Experimental Economics (MonLEE). Professor Abbink was regarded as a great supervisor and teacher for his students, always passing on his exceptional critical thinking and research principles. He was very patient and provided consistent care and equal effort for everyone that crossed his path.', sc.`eligibility` = 'A student commencing a Bachelor of Commerce (Honours) or Bachelor of Economics (Honours) in the Monash Business School at a Monash campus in Australia.; WAM 80+ (Direct entry International students)', sc.`scholarship_amount` = 'Up to AUD $15000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/klaus-abbink-honours-scholarship-6241', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/klaus-abbink-honours-scholarship/4b9403abb45e443db2b08f25b43781c8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Klaus Abbink Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is awarded to Monash University medical students who have demonstrated a commitment to becoming a clinician scientist by undertaking the Monash University intercalated MD-PhD pathway. The successful recipients must have been enrolled in their PhD through one of the Schools that is supporting this Scholarship*, and must have submitted their PhD thesis and returned to complete the final year of the Monash University medical degree.', sc.`eligibility` = 'You must meet the following criteria:; Current student enrolled in and commenced the final year (Year 5/D) of the Clayton BMedSc/MD degree (M6011 or M6018) in the Faculty of Medicine, Nursing and Health Sciences as a Monash Campus in Australia.; You must have completed BMedSc(Hons) M3701 and achieved an 80 WAM or above.; You must have undertaken the MD-PhD pathway at Monash University through one of the MNHS Schools supporting this Scholarship* AND submitted their PhD thesis for examination.', sc.`scholarship_amount` = '$15,000 to be paid to students who submit their PhD thesis before the FY32 census date in the year that they return to their BMedSc/MD degree.; $7,500 to be paid to students who submit their PhD thesis between the FY32 census date and the Semester 2', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/md-phd-industry-leaders-scholarship-for-returning-md-phd-students-6271', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/md-phd-industry-leaders-scholarship-for-returning-md-phd-students/8d4012e53e0bdb4961c3fa1a40382705', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'MD-PhD Industry Leaders Scholarship (for returning MD-PhD students)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Are you passionate about econometric model building, estimation and forecasting for economic decision-making ? Elevate your career in economics with the Master of Applied Econometrics (with PhD pathway) scholarship. This prestigious opportunity is designed for aspiring professionals who seek to deepen their skills in econometrics and make a real impact in academia, industry, or public policy. Our scholarship offers financial support to exceptional candidates, allowing you to focus on gaining expertise in advanced econometric techniques, data modelling, and statistical analysis. The Master of Applied Econometrics program combines rigorous coursework with hands-on experience, equipping you with the tools to tackle complex economic and financial issues, and contribute to the policy making process.', sc.`eligibility` = 'You must meet the following criteria:; Commencing or continuing student enrolled in the Master of Applied Econometrics (PHD pathway) in the Department of Econometrics & Business Statistics in the Faculty of Business and Economics at the Monash Clayton campus.; WAM 80+ (Direct entry International students).', sc.`scholarship_amount` = 'Up to AUD $15000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/master-of-applied-econometrics-phd-pathway-scholarship-6269', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/master-of-applied-econometrics-phd-pathway-scholarship/1170085d6e389b4aed8ad34a8b6429fb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Master of Applied Econometrics PHD Pathway Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Master of Commerce is a research-oriented programme preparing students for a PhD and an academic career. Offered as part of an Integrated PhD program, the MCom may be completed in one or two years, depending on the specialisation and the student\'s prior studies. The MCom provides advanced coursework relevant to the specialisation to provide a thorough academic grounding in the skills and knowledge required to undertake original research. Upon successful completion of the MCom degree,  students who perform at the required standard and demonstrate strong research capability will progress to the PhD (3 years). The MCom is the perfect pathway to doctoral studies for students who aim to pursue an academic career.', sc.`eligibility` = 'You must meet the following criteria:; A current full-time Monash student or an applicant seeking to enrol full-time, in the Master of Commerce degree; You are not eligible for this scholarship if you are, or become, employed on a continuing basis or a fixed term contract for 3 months or greater.', sc.`scholarship_amount` = 'Tuition fees paid, plus an allowance of $37,145 (the equivalent to the 2026 PhD stipend rate).', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/master-of-commerce-scholarship-6161', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/master-of-commerce-scholarship/aa1b727d7f5409312853cc1cf6622b2a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Master of Commerce Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Maxwell King Scholarship (MKS) is named after Professor Maxwell King, who has made an outstanding contribution to graduate research at Monash University, including eight years as Pro Vice-Chancellor (Research and Research Training). This prestigious scholarship is available to help support a student undertaking a PhD with living costs whilst studying at Monash.', sc.`eligibility` = 'An Australian citizen. A New Zealand citizen. Australian permanent resident. Australian humanitarian visa holder. An International student.', sc.`scholarship_amount` = 'Up to AUD $52352', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/maxwell-king-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/maxwell-king-phd-scholarship/92bc4599377c09e7b7f7d3c7dcfeeb44', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Maxwell King PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Monash Interdisciplinary Research Academy of Medical AI (MIRAMA) is a collaborative Honours initiative that brings together expertise from the Faculty of Medicine, Nursing and Health Sciences (FMNHS), the Faculty of Information Technology (FIT), and the Faculty of Pharmacy and Pharmaceutical Sciences (FPPS). Designed for high-achieving students, MIRAMA provides a unique opportunity to undertake interdisciplinary research at the intersection of health, medicine, and artificial intelligence. Through this initiative, Honours students will engage in innovative research projects that combine biomedical science, clinical and health research, artificial intelligence, data science, and digital technologies to address some of the most pressing challenges in healthcare. Projects may explore areas such as disease mechanisms, diagnostics, therapeutics, precision medicine, healthcare delivery, and emerging digital health solutions.', sc.`eligibility` = 'You must meet the following criteria:; Commencing student enrolled in one of the following programs and undertaking a project from the MIRAMA program:; Faculty of Medicine, Nursing and Health Sciences (FMNHS); Bachelor of Health Sciences (Honours); Bachelor of Biomedical Science (Honours); Bachelor of Medical Science (Honours) (BMedSci (Hons)); Faculty of Information Technology (FIT); Bachelor of Computer Science (Honours); Bachelor of Computer Science (Advanced); Faculty of Pharmacy and Pharmaceutical Sciences (FPPS); Bachelor of Pharmacy (Honours); WAM 70+', sc.`scholarship_amount` = 'Up to AUD $6000 — $6000 per 48 credit points of study for one year honours only.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/medicine-and-artificial-intelligence-honours-scholarship-6301', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/medicine-and-artificial-intelligence-honours-scholarship/84932b02ebc153f51a33ad9d84462e55', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Medicine and Artificial Intelligence Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is available to one student enrolled in the Bachelor of Medicine and Bachelor of Surgery (MBBS) and one student enrolled in another degree in the Faculty of Medicine, Nursing and Health Sciences. It is awarded on the basis of achievement and need to students who are undertaking an elective placement in a seriously disadvantaged Australian community or developing country.', sc.`eligibility` = 'You must meet the following criteria:; Current undergraduate student enrolled full-time in the Faculty of Medicine, Nursing and Health Sciences* at a Monash campus in Australia.; Undertaking a clinical placement in a seriously disadvantage Australian community.', sc.`scholarship_amount` = 'Up to AUD $2000 — $2000 one-off payment.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/medicine-nursing-and-health-sciences-equity-travel-grant-5647', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/medicine-nursing-and-health-sciences-equity-travel-grant/becfa3a1a463ae1d9c5dbb1351a2d813', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Medicine, Nursing and Health Sciences Equity Travel Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Microbiology in Water Engineering scholarship be introduced to encourage students to begin thinking about the interdisciplinary of planetary health and in particular health related water microbiology. The scholarship will support students who are interested in the disciplines of environmental engineering (in particular, water engineering) and public health protection (in particular microbiology or epidemiology).', sc.`eligibility` = 'You must meet the following criteria:; A continuing Monash University undergraduate student either:; studying in their fourth year of their Bachelors of Civil or Environmental Engineering having studied or provide evidence of studying any fourth year water course (e.g. CIV4261, or CIV4281, etc.); studying a Masters of Engineering majoring in water, or; intends to or is enrolled in MIC 3990; intends to or is enrolled in honours in microbiology at Monash University.; Must be achieving a minimum 80% Weighted Average Mark', sc.`scholarship_amount` = 'Up to AUD $5000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/microbiology-in-water-engineering-scholarship-6142', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/microbiology-in-water-engineering-scholarship/25a5b7fa450695ddb4ba4eee733746b4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Microbiology in Water Engineering Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Monash Academy of Performing Arts Orchestral Scholarship intends to support and develop the student cohort of Monash Academy Orchestra.', sc.`eligibility` = 'You must meet the following criteria:; A commencing undergraduate student enrolled, or intending to enrol, full-time in the Bachelor of Music degree, or double degree, at a Monash campus in Australia.', sc.`scholarship_amount` = 'Up to AUD $3000 — $3000 for one year only (48 credit points of study)', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-academy-of-performing-arts-orchestral-scholarship-6137', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-academy-of-performing-arts-orchestral-scholarship/e0e8e4e46a7ff1b6ee8a5b501b5bb3b0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash Academy of Performing Arts Orchestral Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'These scholarships are awarded to students whose research aligns with one of the University Global Challenges (e.g. Thriving Communities, Climate Change and Geopolitical Security) as outlined in Impact 2030. The scholarship is available to support students with living costs whilst studying at a Monash campus in Australia.', sc.`eligibility` = 'You must meet the following criteria:; have submitted a scholarship application in the current year; undertaking research which aligns with one of the University Global Challenges (e.g. Thriving Communities, Climate Change and Geopolitical Security) as outlined in Impact 2030; meet Monash\'s competitive scholarship selection process requirements; meet Monash English language proficiency requirements.', sc.`scholarship_amount` = 'Up to AUD $53608', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-graduate-impact-2030-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-graduate-impact-2030-scholarship/cfa08f43d88705c72ea8694952c68d19', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash Graduate Impact 2030 Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Monash Graduate Scholarships (MGS) are provided by Monash University to support domestic and international students undertaking Research Doctorate and Research Masters degrees. A MGS is available to help support students with living costs whilst studying at Monash.', sc.`eligibility` = 'Applicant must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student', sc.`scholarship_amount` = 'Up to AUD $36063 — $35,013 p.a (2024 rate)', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-graduate-scholarship-mgs', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-graduate-scholarship/62c7b002e2d4acfbf9f6cc5e76d9a785', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash Graduate Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Are you an asylum seeker on a bridging visa? If you are a high-achieving student with the ambition to change your future through undergraduate study at Monash University, you may be eligible for the Monash Humanitarian Scholarship. You will receive 100% international student funding for the Monash undergraduate degree of your choice plus a yearly allowance of $6000. Monash has increased the number of these scholarships available thanks to the generous donations from Alumni and supporters of the University through the Achieving Potential fund.', sc.`eligibility` = 'You must meet the following criteria:; A person who is in Australia and currently on:; Temporary Humanitarian Stay visa (Subclass 449); Temporary Protection visa (Subclass 785); Temporary Humanitarian Concern visa (Subclass 786); Safe Haven Enterprise visa (Subclass 790); Bridging visa A (Subclass 010) or Bridging visa E (Subclass 050 and 051) (inactive visas included) AND have applied for a Permanent Protection visa; A commencing or continuing international student enrolled or intending to enrol in:; an undergraduate degree at a Monash University campus in Australia; a Monash University Foundation Year or Monash University Diploma through Monash College; Have achieved a minimum ATAR of 70.00, OR for current students a minimum weighted average mark (WAM) of 60, OR equivalent academic achievement.', sc.`scholarship_amount` = 'Full course fees plus up to $30,000 allowance; An allowance of $6000 per year (48 credit points of study) until the minimum credit points for your undergraduate degree are completed.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-humanitarian-scholarship-7004', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-humanitarian-scholarship/908c401e5eba11489fe72ca1ba010b3d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash Humanitarian Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'International students from all countries who have received an undergraduate course offer from Monash will automatically be considered for the Monash International Leadership Scholarship. As a scholarship recipient you will receive a 100% tuition sponsorship for the duration of your degree, and the opportunity to develop learning and leadership skills as an ambassador for Monash University.', sc.`eligibility` = 'You must meet the following criteria:; You must have received a full Monash course offer with no conditions; You must intend to enrol full-time in an undergraduate degree at a Monash campus in Australia; You are not eligible for this scholarship if you are:; a current Monash student.; studying an Australian Year 12. You may be eligible for the Sir John Monash Scholarship for Excellence.; are commencing in the Bachelor of Medical Science and Doctor of Medicine (MD).; in Monash Pathway programs (e.g. Monash College and Monash University Foundation Year).; transferring from another Monash campus or applying to Monash from another Australian University.', sc.`scholarship_amount` = '100% course fees paid until the minimum number of points for your degree are completed (excludes OSHC, accommodation and living costs).', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-international-leadership-scholarship-5571Z', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-international-leadership-scholarship/f5ea101da8b40a1fd67a091bdad187f9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash International Leadership Scholarship' AND sc.`course_id` IS NULL;
