UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Monash International Tuition Scholarships (MITS) are provided by Monash University to support international students undertaking Research Doctorate and Research Masters degrees. A MITS covers the course tuition fees that would otherwise be payable by the student.', sc.`eligibility` = 'Applicants must: be An International student; meet Monash\'s competitive scholarship selection process requirements, AND; meet Monashs English language proficiency requirements.', sc.`scholarship_amount` = 'Monash International Tuition Scholarship covers the cost of:; course tuition fees AND; a single Overseas Student Health Cover (OSHC) policy.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/international-tuition-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-international-tuition-scholarship-mits/10f63f3a634befc4fad139777daa4c5b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash International Tuition Scholarship (MITS)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A $6000 award for outstanding Monash music students specialising in jazz. This scholarship is established from funds received from an anonymous donor.', sc.`eligibility` = 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student; A music performance student enrolled in an undergraduate degree in the Sir Zelman Cowen School of Music and Performance.; Specialising in jazz.', sc.`scholarship_amount` = 'Up to AUD $6000 — $6000 per annum (48 credit points of study) paid for a maximum of one year only.', sc.`level_of_studies` = 'Undergraduate / VET, Postgraduate', sc.`field_of_studies` = 'Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-jazz-music-scholarship-5680', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-jazz-music-scholarship/06b3d6658dba5d416d30f046987d490d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash Jazz Music Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Monash Mauritius Award provides support to new international students at Monash University, Australia.', sc.`eligibility` = 'You must meet the following criteria:; A new commencing student undertaking an undergraduate or postgraduate degree.; You must meet academic entry requirements and have a full offer letter to study at a Monash campus in Australia.; You are applying from Mauritius.; If you are in receipt of other scholarships or sponsorships that pay part or all of your fees you are not eligible for this scholarship.; If you have already accepted a Monash study grant and choose to accept this scholarship, the study grant will no longer be valid.', sc.`scholarship_amount` = '15% or 20% tuition fee reduction applied annually for the duration of your program for up to 3 years (144 credit points).', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-mauritius-award-6308', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-mauritius-award/8f8d47f1ad71ef7d3ed46d481842401b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash Mauritius Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Peer Mentoring Leaders Scholarship is awarded to Monash Peer Mentoring Coordinators each year in recognition of their service and leadership in the peer mentoring community. Peer Mentoring Coordinators work closely with the Faculty and Portfolio of the Deputy Vice-Chancellor (Education) to manage key aspects of the program, and ensure that it meets the needs of mentors and mentees. Peer Mentoring Coordinators are involved in shaping the Peer Mentoring program and help build engagement within the Peer Mentoring community.', sc.`eligibility` = 'You must meet the following criteria:; A continuing coursework student enrolled in an undergraduate or postgraduate degree at a Monash campus in Australia.; Leadership potential and your willingness to share your time, skills and experiences with Peer Mentors and incoming first-year undergraduate students.; Be selected as Monash Peer Mentoring Coordinator.', sc.`scholarship_amount` = 'Up to AUD $6000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-peer-mentoring-leaders-scholarship-7104', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-peer-mentoring-leaders-scholarship/487e08ef0f870d4448dcde119f5a505d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash Peer Mentoring Leaders Scholarship' AND sc.`course_id` IS NULL;
