UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Monash School Award is awarded to the highest achieving commencing students', sc.`eligibility` = 'You must meet the following criteria:; Current offshore final-year high school students studying an international qualification who intend to enrol in an undergraduate degree at a Monash University campus in Australia.; Students in receipt of other scholarships or sponsorships that pay part or all of their fees are not eligible for this scholarship.; If you have already accepted a Monash study grant and choose to accept this scholarship, the study grant will no longer be valid.', sc.`scholarship_amount` = 'Up to AUD $36000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-award-6208', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-school-award/270c7dee3943b7087d9f84989afe7908', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash School Award' AND sc.`course_id` IS NULL;
