UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This joint scholarship program supports high-achieving Vietnamese candidates to undertake a PhD at Monash University. Applicants can elect to study at a Monash campus in Australia or be based at a Vietnamese University, jointly supervised as an external offshore candidate. The program aims to address Vietnam\'s future industry and workforce needs, prioritising key research areas such as digital technologies, physics, biotechnologies and energy & environment.', sc.`eligibility` = 'You must meet the following criteria:; a citizen or permanent resident of Vietnam at the time of your application; meet Monash\'s competitive scholarship selection process requirements; meet Monash English language proficiency requirements.', sc.`scholarship_amount` = 'Varies - see benefits', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-university-vietnam-government-phd-scholarship-project-89', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-university-vietnam-government-phd-scholarship/7d4f82677a5209439ad21402c5a169a6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash University-Vietnam Government PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Monash Yoshida Grant was established to support a research trip to Japan for students undertaking honours in Japanese or Asian Studies.', sc.`eligibility` = 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student; Current undergraduate student enrolled in an honours degree in Japanese studies or Asian studies in the School of Languages, Cultures and Linguistics in the Faculty of Arts at a Monash campus in Australia.; Conducting research in Japan as part of the honours degree.', sc.`scholarship_amount` = 'Up to AUD $6000 — $6000 one-off payment.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Humanities and social sciences, Languages', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-yoshida-grant-5659A', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-yoshida-grant/3af62e6abed23da2c74621938d63f66e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash Yoshida Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A scholarship for commencing or continuing music performance students, awarded for academic merit and outstanding musical performance.', sc.`eligibility` = 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student; Music performance student enrolled in an undergraduate degree in the Sir Zelman Cowen School of Music and Performance at a Monash campus in Australia.; Playing a specialised instrument as determined by the Sir Zelman Cowen School of Music and Performance.', sc.`scholarship_amount` = 'Up to AUD $6000 — $6000 for one year only (48 credit points of study).', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/monash-pratt-musician-performance-scholarship-5591', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/monash-pratt-musician-performance-scholarship/a195ca90f14e4fc73660ded9fb932498', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Monash-Pratt Musician Performance Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship assists outstanding JD or Bachelor of Laws students to undertake an international pathway programs. The scholarship was introduced in 2014, as part of the Faculty\'s 50th anniversary celebrations.', sc.`eligibility` = 'You must meet the following criteria:; A continuing student enrolled full-time in either the Bachelor of Laws (LLB) (including double degrees) or the Monash Juris Doctor (JD), at a Monash campus in Australia.; Have completed all compulsory units and have only up to four elective units to complete in the Monash LLB or JD degree prior to the start of the UK academic year for which the scholarship is sought.; Be accepted into (although this acceptance may be conditional on completion of the Monash LLB or JD units to the pathway stage of the program) and enrol in one of the following approved international pathway programs:; Bachelor of Civil Law or Masters in Law and Finance at the University of Oxford (open to Monash JD students only); Master of Law or Masters Degree in Corporate Law at the University of Cambridge (open to Monash LLB and JD students); Master of Laws at the Dickson Poon School of Law, King’s College London', sc.`scholarship_amount` = 'Up to AUD $10000 — $10,000 paid in one instalment for one year only. To be used only for travel and living expenses and course fees for the relevant pathway program being undertaken by the recipient.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/nicholas-auden-international-study-scholarship-5804', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/nicholas-auden-international-study-scholarship/75926012efa2f69994eb747455c0b65b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Nicholas Auden International Study Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is for international students committed to studying Pharmacy or Pharmaceutical Science at Monash. It aims to attract and reward high achieving international students to the faculty.', sc.`eligibility` = 'You must meet the following criteria:; Commencing international student at a Monash Campus in Australia, in one of the below courses:; P2001 Bachelor of Pharmaceutical Science or P3002 Bachelor of Pharmaceutical Science Advanced (Honours); P6005** Master of Pharmaceutical Science; P6006 Master of Global Medicines Development; P6007 Pharmacy (Honours) Scholars Program/Doctor of Pharmacy', sc.`scholarship_amount` = '50% of tuition fees paid per year until the minimum credit points for your degree are completed (awarded to the highest achieving student in each of the four course groups nominated).; 25% of tuition fees paid per year until the minimum credit points', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/pharmacy-international-merit-scholarship-5745', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/pharmacy-and-pharmaceutical-science-international-merit-scholarship/55dbd648f66991b4ba6f879fb06836d6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Pharmacy and Pharmaceutical Science International Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'These prestigious top up scholarships are available to help support graduate research students studying in relevant Humanities and Social Sciences study areas with living costs whilst studying at a Monash campus in Australia. The Raydon Scholarships are awarded in addition to a RTP Stipend or Monash Graduate Scholarship.', sc.`eligibility` = 'You must meet the following criteria:; have submitted a scholarship application in the current year; be undertaking research in the study areas and faculties listed below; meet Monash\'s competitive scholarship selection process requirements; meet Monash English language proficiency requirements.', sc.`scholarship_amount` = 'Up to AUD $23837 — Raydon scholarships provide a living allowance top up (stipend).', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/raydon-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/raydon-graduate-research-scholarships/27f14fab9b712bcc17503a8ee4a50cce', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Raydon Graduate Research Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Research Training Program (RTP) Scholarships are provided by the Australian Government to support both domestic and international students undertaking Research Doctorate and Research Masters degrees. As part of this program, a RTP Stipend (living allowance) is available to help support domestic and international students with living costs whilst studying at Monash.', sc.`eligibility` = 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student', sc.`scholarship_amount` = 'AUD $36063/year — The RTP Stipend provides: a living allowance (stipend), and; a relocation allowance, if eligible.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/research-training-program-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-training-program-rtp-stipend/a691136009df231c40daa1165874ec05', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Research Training Program (RTP) Stipend' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship recognises the commitment to the residential community made by volunteer Resident Advisors, who live in Monash University Accommodation.', sc.`eligibility` = 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student', sc.`scholarship_amount` = 'Up to AUD $6139 — Up to $6139', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/mrs-residential-advisor-scholarship-5692', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/resident-advisor-scholarship/4667fc5cce3096f10a4ec9e530d3e786', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Resident Advisor Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Sir James McNeill Postgraduate Research Scholarship (SJMN) is funded by a private trust and was established in memory of the late Sir James McNeill, who had a long association with Monash University. This prestigious scholarship is available for research that is both environmentally responsible and socially beneficial and helps support a graduate research student with living costs whilst studying at Monash.', sc.`eligibility` = 'Applicants must: be An Australian citizen; A New Zealand citizen; Australian permanent resident; Australian humanitarian visa holder; An International student', sc.`scholarship_amount` = 'AUD $52352/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Engineering and technology, Medicine, Sciences, Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/sir-james-mcneill-postgraduate-research-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/sir-james-mcneill-postgraduate-research-scholarship/81882447b252e1206c74acee276d4dbd', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Sir James McNeill Postgraduate Research Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is offered to the 10 highest-achieving international students studying Australian Year 12 or International Baccalaureate in Australia. If you have an ATAR of 98.00+ or equivalent, you will be automatically considered for this scholarship when you apply for a Monash undergraduate degree through VTAC.', sc.`eligibility` = 'Applicants must: An International student; Current Year 12 or International Baccalaureate in Australia; Intending to enrol in an undergraduate degree at a Monash campus in Australia.', sc.`scholarship_amount` = 'Up to AUD $40000 — $10,000 per annum (48 credit points of study), up to a maximum of four years.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/Sir-John-Monash-Scholarships-for-Excellence-7200', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/sir-john-monash-scholarships-for-excellence/6b759eaf690bfecebb37f8dbeadb6af3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Sir John Monash Scholarships for Excellence' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = '-', sc.`eligibility` = 'You must meet the following criteria:; Enrolled in BRM5022 Biotechnology work-integrated learning.', sc.`scholarship_amount` = 'Up to AUD $14300 — $14,300 paid in three instalments.; 24 week placement with one of the host sites in the SKILLED clinical trials internships program.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/skilled-industry-placement-6166', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/skilled-industry-placement-scholarship/417dffe591e56c64c8836341788f53b9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Skilled Industry Placement Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Summer and winter research scholarships are run over the summer and winter breaks. If you’re interested in a research career or furthering your studies through an honours program, this is a great opportunity to get ahead over the holidays.', sc.`eligibility` = 'All conditions must be met: Australian or New Zealand citizen, holder of an Australian permanent resident or permanent humanitarian visa, or an international student; Currently enrolled as an undergraduate or graduate (coursework) student with a registered Australian or New Zealand provider of higher education; Normally have completed at least the second year of an undergraduate degree; Not a full-time, continuing employee of Monash University; Students enrolled in their final semester are not eligible to apply.', sc.`scholarship_amount` = 'The value varies', sc.`level_of_studies` = 'Undergraduate / VET, Postgraduate', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/summer-winter', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/summer-and-winter-vacation-research-scholarship-program/a4664aea66bd175ea74827decfebdc01', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Summer and Winter Vacation Research Scholarship Program' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Are you a high-achieving student from a partner university looking to pursue engineering excellence at Monash University? At Monash, we believe in recognising talent from around the world and fostering global connections in engineering education. That\'s why we\'re proud to offer this scholarship to exceptional students like you who are ready to embark on a transformative academic journey. With the TNE Engineering Achievement Scholarship, you\'ll not only receive financial support but also join a community of like-minded scholars dedicated to pushing the boundaries of engineering innovation. Whether you\'re interested in civil, mechanical, electrical, materials, chemical, or any other branch of engineering, this scholarship is your gateway to success.', sc.`eligibility` = 'You must meet the following criteria:; A commencing student enrolled in one of the Bachelor of Engineering programs in the Faculty of Engineering at a Monash Campus in Australia.; ATAR 90+', sc.`scholarship_amount` = 'Up to AUD $6000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/tne-engineering-achievement-scholarship-6251', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/tne-engineering-achievement-scholarship/be21cd7a9ec3f51d1f56d1b396c0a7c0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'TNE Engineering Achievement Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Team Monash Elite Student Performer Grant is designed to support talented students studying at Monash to represent the University in the areas of Sport, Performing Arts and related disciplines. This grant aims to assist students who perform at a National level or higher. Students must represent the University in a Monash Club/Society or at the Inter-University (Varsity) competitions and activities.', sc.`eligibility` = 'Applicants must: be Australian or New Zealand citizens, Australian permanent residents, permanent humanitarian visa holders or international students; Commencing or continuing undergraduate or postgraduate student enrolled at a Monash campus, including Monash College.; Involved in a non-professional sport, performing arts or similar, as recognised by Team Monash.', sc.`scholarship_amount` = 'Up to AUD $1000 — $100 to $1000 one-off payment and/or a Monash Sport gym membership.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/team-monash-elite-student-performer-grant-5609', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/team-monash-elite-student-performer-grant/e786ac6e19aebd7eae05fc798840cd7f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Team Monash Elite Student Performer Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Koto Dream Scholarship is designed to support outstanding Know One, Teaching One (KOTO) alumni who demonstrate strong academic potential, leadership capacity, and a clear commitment to social impact, enabling them to pursue undergraduate studies at Monash University overseas. This scholarship reflects Monash University\'s commitment to equity, access to education, and global social impact, while empowering first-generation learners from disadvantaged backgrounds to become future changemakers in their communities.', sc.`eligibility` = 'You must meet the following criteria:; An alumni of Know One, Teaching One (KOTO).; Commencing student intending to enrol full-time in an undergraduate degree at a Monash campus in Australia; Must be enrolled in one of the following areas:; Business, Management, and Economics; Communication, Media, and Social Sciences; Sustainability, Development Studies, or related disciplines', sc.`scholarship_amount` = '100% tuition sponsorship for course duration (maximum of three years)', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/the-koto-dream-scholarship-6291', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-koto-dream-scholarship/8090da59569ccb6f5f1cd9ea0b0c23d5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'The Koto Dream Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The UEC Excellence Award is awarded by Monash to three of the highest achieving commencing students from the Unified Examination Certificate (UEC) schools network in Malaysia. It underscores our commitment to seek out, reward and support students who want to change the world for the better.', sc.`eligibility` = 'You must meet the following criteria:; Commencing student enrolled or intending to enrol in a single or double undergraduate degree at a Monash campus in Australia.', sc.`scholarship_amount` = 'Up to AUD $30000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/uec-excellence-award-6275', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uec-excellence-award/fcf5e27137c91c805e81be0e6545cf4e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'UEC Excellence Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The scholarship provides support to students in the Faculty of Pharmacy and Pharmaceutical Sciences undertaking an international immersion through the Monash Global Campus Intensive program in Prato. This program builds the cultural competence and global perspectives needed to deliver inclusive healthcare.', sc.`eligibility` = 'You must meet the following criteria:; Current student enrolled in one of the following courses at a Monash campus in Australia:; P3001 Bachelor of Pharmacy (Honours); P6001 Bachelor of Pharmacy (Honours) and Master of Pharmacy; Approved to participate in Monash Global Campus Intensives (MGCI) in Italy for PHR5052 and are:; Domestic student experiencing financial hardship or are Indigenous Australian; Domestic or International student with minimum Weighted Average Mark of 80%. (Preference will be given to students in the Dean’s Scholars Program).', sc.`scholarship_amount` = 'Up to AUD $6000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/verrocchi-charity-fund-pharmacy-prato-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/verrocchi-charity-fund-pharmacy-prato-scholarship/6c6ccb3d8014f3573b5c71354e104f0e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Verrocchi Charity Fund Pharmacy Prato Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Vice-Chancellor\'s ASEAN Award supports high-achieving undergraduate students to study at Monash, reinforcing our deep commitment and connection to the region - socially, economically and culturally. The program is designed to ease the full cost of study for international students - combining tuition support, travel and relocation assistance, visa fee coverage, and other services into one bundled award.', sc.`eligibility` = 'You must meet the following criteria:; Commencing student intending to enrol full-time in an undergraduate degree at a Monash campus in Australia.; You must be from one of 10 ASEAN member countries: Brunei, Cambodia, Indonesia, Laos, Malaysia, Myanmar, the Philippines, Singapore, Thailand and Vietnam.', sc.`scholarship_amount` = '20% tuition fees paid up to 3 years.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/vice-chancellors-asean-award-6280', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-asean-award/4e56d127055559ed2079efc83867e7ae', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Vice Chancellor\'s ASEAN Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Monash Vice Chancellor ASEAN Onshore School Leavers award for International Students celebrates high-achieving international students with nationalities from ASEAN countries enrolling in an undergraduate (coursework) degree at a Monash campus in Australia.', sc.`eligibility` = 'You must meet the following criteria:; Commencing student enrolled in an undergraduate degree* at a Monash campus in Australia.; ATAR of 97 and above.; You must be from an ASEAN country.; You must have received a Monash course offer.', sc.`scholarship_amount` = 'Up to AUD $76719 — 20% tuition fees paid per annum for up to 3 years', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/vice-chancellor-asean-award-for-onshore-school-leavers-6286', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vice-chancellor-asean-award-for-onshore-school-leavers/0de72f9b5cf5ad6dc89b94c9b8f259ee', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Vice-Chancellor ASEAN Award for Onshore School Leavers' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Monash Vice Chancellor School Leavers Award for International Students celebrates high-achieving international students enrolling in an undergraduate (coursework) degree at a Monash campus in Australia.', sc.`eligibility` = 'You must meet the following criteria:; Commencing student enrolled in an undergraduate degree at a Monash campus in Australia.; ATAR of 83 and above to be considered; You must have received a Monash course offer.', sc.`scholarship_amount` = 'Up to AUD $15000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/vice-chancellor-international-school-leaver-award-6287AB', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vice-chancellor-international-school-leaver-award/750db2fb001eb3798879e83a0bcd1489', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Vice-Chancellor International School Leaver Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is awarded to a high-achieving student who is currently enrolled in third year of an electrical and computer systems engineering degree in the Faculty of Engineering.', sc.`eligibility` = 'You must meet the following criteria:; Currently enrolled in an engineering degree in the Faculty of Engineering at a Monash campus in Australia', sc.`scholarship_amount` = 'Up to AUD $20000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.monash.edu/study/fees-scholarships/scholarships/find-a-scholarship/wilson-transformer-company-scholarship-5817B', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/wilson-transformer-company-engineering-leadership-scholarship/395f3d1570e0963592b5b4b581ad273e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00008C' AND sc.`scholarship_name` = 'Wilson Transformer Company Engineering Leadership Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Australian Government Research Training Program (RTP) stipends are provided to support the general living costs of both domestic and overseas students undertaking research doctorate degrees.', sc.`eligibility` = 'Please contact Bond University for further information.', sc.`scholarship_amount` = 'The Australian Government Research Training Program (RTP) stipends are provided to support the general living costs of both domestic and overseas students undertaking research doctorate degrees.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://bond.edu.au/scholarship/australian-government-research-training-program-rtp-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australian-government-research-training-program-rtp-scholarships/0ad9d3d5489dd6d6222f520cac3e7ad3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'Australian Government Research Training Program (RTP) Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Bond Business School Postgraduate Bursaries were designed to provide financial assistance to new postgraduate students enrolling in programs within the Bond Business School. Bursaries are provided to those who can demonstrate their positive contribution to their community.', sc.`eligibility` = 'Please contact Bond University for further information.', sc.`scholarship_amount` = 'As a Bond Business School Postgraduate Bursary recipient, you will be awarded with a cash payment of $4,200 to help with your living expenses while you study at Bond University (paid in two equal instalments).As a Postgraduate Bursary applicant, you', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Accounting, Business and management', sc.`website` = 'https://bond.edu.au/scholarship/bond-business-school-postgraduate-bursaries', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/bond-business-school-postgraduate-bursaries/3e6986bb6abf71a68dd10c3faa61904a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'Bond Business School Postgraduate Bursaries' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Bond University has proudly been training aspiring Canadian lawyers for 25 years. Since 2001, graduates have gone on to establish successful careers as legal practitioners and professionals across Canada and all over the world. To celebrate 25 years of Bond\'s Juris Doctor in Canada, we are launching the Bond University Canadian Juris Doctor 25th Anniversary Scholarship. Valued at 25% tuition remission, all Canadian students who submit an application for Bond\'s Juris Doctor, to commence in any semester between September 2025 and September 2027, will be assessed for the scholarship. The scholarship is a celebration of 25 years of history, and an investment in the future of Canadian lawyers. Earn your law degree on Australia\'s Gold Coast, at a university with strong links to Canada, a dedicated Canadian Law Program, and a truly global network.', sc.`eligibility` = 'To be eligible to apply for this scholarship, you must:; Be a Canadian citizen currently residing in Canada.; Have achieved predetermined academic merit in your undergraduate studies.; Meet the standard entry requirements for the Bond Juris Doctor.; May have previously completed a Bond academic or English program.', sc.`scholarship_amount` = 'Valued at 25% tuition remission, all Canadian students who submit an application for Bond’s Juris Doctor, to commence in any semester between September 2025 and September 2027', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://bond.edu.au/scholarship/bond-university-canadian-juris-doctor-25th-anniversary-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/bond-university-canadian-juris-doctor-25th-anniversary-scholarship/3d7e47e5c9ad001284c9f4008b48465c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'Bond University Canadian Juris Doctor 25th Anniversary Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each semester, the Bond University College (BUC) Academic Excellence Scholarship recognises and rewards an outstanding student from the Bond University College Foundation Program (CRICOS 063151G) who has achieved exceptional academic results. The scholarship is open to international students enrolled in the Bond University College Foundation Program. Full eligibility criteria are listed below. The scholarship is awarded automatically, following an internal eligibility review conducted by Bond University College to identify the top-performing student each semester. No application is required.  Recipients receive a 25% tuition fee reduction for the duration of their undergraduate degree at Bond University, supporting a smooth and successful progression from the Foundation Program into further study.', sc.`eligibility` = 'To be eligible for the Bond University College (BUC) Academic Excellence Scholarship, you must:; Have completed the Bond University College Foundation Program as the top-performing student in their cohort.; Achieve a minimum Cumulative Percentage Average (CPA) of 85%.; Be transitioning into an undergraduate program at Bond University and hold a current offer for undergraduate study.', sc.`scholarship_amount` = 'Provides a 25% tuition fee reduction for the duration of the recipient’s undergraduate degree at Bond University.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://bond.edu.au/scholarship/bond-university-college-buc-academic-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/bond-university-college-buc-academic-excellence-scholarship/8602ae9d42fc7f787d6f3a52bd978a7b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'Bond University College (BUC) Academic Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Bond University values its higher degree research student cohort and provides a substantial level of direct financial support to many students. Bond University allocates funds to support the financial costs of fee offset (waiver) and living stipends. A limited number of scholarships are available to domestic and overseas doctoral students who wish to continue their education through a Higher Degree Research (HDR) PhD program.  The Bond University Postgraduate Research Scholarship (BUPRS) is awarded through a competitive application process.  The Bond University HDR Scholarships Committee meets biannually to award fee waivers and living stipends based on a merit based selection process.  Students cannot apply if they are receiving an equivalent award or scholarship from the Commonwealth designed to offset HDR fees.', sc.`eligibility` = 'Please contact Bond University for further information.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://bond.edu.au/scholarship/bond-university-postgraduate-research-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/bond-university-postgraduate-research-scholarship/d69cb51097774b390ec5a4489ea4b201', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'Bond University Postgraduate Research Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Excellence Scholarships are awarded to those who demonstrate high academic achievement, as well as leadership skills and community involvement. As an Excellence Scholar, you will be awarded with 50% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students), and will commence at Bond in either the January, May or September semester.', sc.`eligibility` = 'To be eligible to apply for this scholarship, you must:; Be one of the following:; an Australian or New Zealand citizen, or an Australian permanent resident currently completing or completed* Year 12 (or equivalent) inside or outside of Australia ; an Australian permanent resident completing or completed high school outside Australia; an international student completing or completed* Year 12 (or equivalent) in Australia and; Achieve a minimum of ATAR 92.00 or IB Diploma 34; Hold a demonstrated record of leadership, initiative and service to your school and/or community.; Meet the standard entry requirements for your chosen program of study.', sc.`scholarship_amount` = 'Provides 50% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students).', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://bond.edu.au/scholarship/excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/excellence-scholarship/04b0d84e6a11e7f83ad8c48c0a1e0de9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Bond International Stand Out Scholarships provide tuition remission scholarships to standout students applying to study at an undergraduate or postgraduate level. International Stand Out Scholarships are awarded on the basis of academic merit, and are a testament to Bond University’s commitment to stand out international students.', sc.`eligibility` = 'Please contact Bond University for further information.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Architecture, Built environment, Business and management, Communications, Tourism and hospitality, Humanities and social sciences, Law, Sport and leisure, Psychology, Sciences, Creative arts', sc.`website` = 'https://bond.edu.au/scholarship/international-stand-out-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-stand-out-scholarship/366bce0d75dfb35a4fca71876b33e74c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'International Stand Out Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Bond International Undergraduate Excellence Scholarships provide tuition remission scholarships to high academic achievers, applying to study a bachelor’s degree.International Undergraduate Excellence Scholarships are awarded on the basis of academic merit, and are a testament to Bond University’s commitment to quality and outstanding international students.', sc.`eligibility` = 'Please contact Bond University for further information.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Architecture, Built environment, Business and management, Communications, Health services and support, Tourism and hospitality, Humanities and social sciences, Law, Sport and leisure, Psychology, Sciences, Creative arts', sc.`website` = 'https://bond.edu.au/scholarship/international-undergraduate-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-undergraduate-excellence-scholarship/77ce577a013d7ef213f046d81fc38e1b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'International Undergraduate Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Our Leadership Scholarships aim to recognise current Year 12 students who have outstanding leadership experience and community involvement with a partial-fee tuition remission scholarship. Leadership Scholarships are awarded to students who demonstrate high academic achievement, as well as outstanding leadership skills and community achievements. As a Leadership Scholar, you will be awarded with 25% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students), and can commence at Bond in either the January, May or September semester.', sc.`eligibility` = 'To be eligible for this scholarship, you must:; Be an Australian or New Zealand citizen, or an Australian permanent resident currently completing Year 12 (or equivalent) inside or outside of Australia OR An Australian or an Australian permanent resident completing high school outside Australia OR International students completing Year 12 (or equivalent) in Australia.; Achieve a minimum of ATAR 84.00 or IB Diploma 30.; Hold outstanding leadership, community and extra-curricular achievements, both at school and within the community.  You will be asked to provide evidence of all achievements as supporting documents in your scholarship application.; Meet the standard entry requirements for your chosen program of study.', sc.`scholarship_amount` = 'Provides 25% tuition remission for any single or approved combined undergraduate degree (excluding the Bond Medical Program and Diploma entry students).', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://bond.edu.au/scholarship/leadership-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/leadership-scholarship/2c3d0dc08136cca301fa24fde822c2b1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'Leadership Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Transformer is a co-curricular program that enable students to innovatively tackle real-world problems that matter. It attracts motivated, self-directed individuals who want to work in collaborative, interdisciplinary teams on challenging projects that typically span multiple semesters. The nature and scope of these projects are limited only by the passions and interests of the participants. Although highly motived and self-directed, Transformer participants are supported throughout the program by dedicated Bond academics and staff, industry experts, mentors, state-of-the-art facilities and other essential resources. The Transformer Scholarship is awarded to those with high potential to affect real change through participation in the Transformer program. As a Transformer Scholar, you will be awarded up to 50% tuition remission for any undergraduate degree including approved combined programs up to 320 credit points (excluding the Bond Medical Program), or postgraduate degree (excluding research degrees) and will commence your study in the following January semester. As a Transformer Scholar you will also actively participate in and complete the Transformer program during your studies at Bond.', sc.`eligibility` = 'To be eligible to apply for this scholarship, you must:; Have strong leadership skills, community involvement and demonstrated potential to affect change; Have had extensive involvement in extracurricular activities; Meet the entry requirements for your chosen program of study and commence in the following January semester.', sc.`scholarship_amount` = 'Provides 50% tuition remission for any undergraduate degree including approved combined programs up to 320 credit points (excluding the Bond Medical Program), or postgraduate degree (excluding research degrees).', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://bond.edu.au/scholarship/transformer-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/transformer-scholarship/6cd63fc716f51561b68ab9a2d965d31d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00017B' AND sc.`scholarship_name` = 'Transformer Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Scholarships available for RMSC students in year 11 from 2022', sc.`eligibility` = 'Roma Mitchell Secondary College seeks aspirational young women and men with a diversity of interests, abilities, backgrounds and a natural curiosity of the world. The College invites prospective and current students to apply for Scholarships to undertake the International Baccalaureate program.Roma Mitchell Secondary College will offer fully funded Scholarships to those students who have a demonstrated ability and who embody the RMSC values of excellence, respect and diversity within an overall commitment to contribute to our community. Scholarships will be awarded to students based on academic achievement and a commitment to complete all the requirements of the International Baccalaureate program.Special consideration will be given to all or any of the following factors:Social and cultural diversity; Ability in demonstrating resilience;Financial need.', sc.`scholarship_amount` = 'AUD $1500/year — AUD $1500 cost is for the 2 year Diploma. The cost covers student subject and registration fees which are paid to the IBO', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/ib-diploma/3006f5822ee407b8a9608c894608a13e', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ib-diploma/3006f5822ee407b8a9608c894608a13e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00018A' AND sc.`scholarship_name` = 'IB Diploma' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Your adventure awaits! Enjoy long stretches of perfect coastline in the mid west, forests and mountains in the south west, or tropical deserts and sandy beaches in the north. The WA Regional TAFE International Student Bursary gives international students a unique experience of life in beautiful regions of WA, while receiving high quality education and training.', sc.`eligibility` = 'To be eligible for application and bursary payments, students must:; be a genuine international student intending to study on a subclass 500 visa. Must provide proof to TIWA Admissions of either:; 1) student visa grant; 2) student visa application; commence in 2026; maintain a continuous enrolment over at least one year in a valid regional course pathway; maintain ongoing residency in the nominated regional location for the duration of your bursary period; meet academic and English language requirements prior to commencement of each course; understand the bursary will be paid to awarded students in one of two ways, either as:; two payments ($2,500 each semester, with the first payment approximately six weeks after the start of first semester); one payment ($5,000 in second semester); meet financial requirements and obligations for the course without needing or relying on the bursary for tuition fees, resource fees, and/or material fees.', sc.`scholarship_amount` = 'Up to AUD $5000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.tafeinternational.wa.edu.au/tafe-courses/regional-bursary-tafe-international-students?', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/regional-bursary-for-tafe-international-students/c1c324b016877c57778c21562aed0d16', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00020G' AND sc.`scholarship_name` = 'Regional bursary for TAFE international students' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Established in 1996 by Mrs I.C. McCready in memory of her late husband Alfred Glen McCready, who was admitted to the degree of Bachelor of Arts with First Class Honours in Classics and awarded the University Medal for outstanding merit in 1940 and who lectured in Classics with The University of Queensland, 1946-49. The scholarship is maintained by the income of the fund established by a gift of $30,000 from Mrs I.C. McCready, Mr W.K. Lam and Dr L.L. Chan.', sc.`eligibility` = 'Applicants must: have completed the requirements for the Bachelor of Arts program at UQ; are enrolled either full-time or part-time, in an postgraduate BA honours program in Classical Languages at UQ.', sc.`scholarship_amount` = 'Equal to the annual income from the fund', sc.`level_of_studies` = 'Undergraduate / VET, Postgraduate', sc.`field_of_studies` = 'Humanities and social sciences', sc.`website` = 'https://scholarships.uq.edu.au/scholarship/ag-mccready-memorial-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ag-mccready-memorial-scholarship/27ebdf998171132b0d4c133511d58400', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'A.G. McCready Memorial Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Established in 2024 through a gift from Alumni Friends, Professor Heather Zwicker and collective donors under the Queensland Commitment scheme and maintained by income generated from an underlying endowment fund. Alumni Friends of The University of Queensland dates back to 1967, when UQ sponsored the formation of an association to foster relationships with UQ alumni.', sc.`eligibility` = 'Youre eligible if you: are or will be enrolled in an Approved Program; can demonstrate and provide documentary evidence of financial hardship; identify as a member of the LGBTQIA+ community and; have not previously held the Scholarship.', sc.`scholarship_amount` = 'Up to AUD $4500 — $4,500 (limited to the annual income from the fund)', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/alumni-pride-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alumni-pride-scholarship/b33d8efc5edc0eac217cfd8771388f21', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Alumni Pride Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship was founded in 1911 by an initial gift of $1,000 from the beneficiaries in the estate of the late Honourable John Archibald, MLC.', sc.`eligibility` = 'Applicants must: the Bachelor of Economics (Honours) (as a commencing student); the Bachelor of Advanced Finance and Economics (Honours) with an economics major (and completed 48 units); have achieved a Grade Point Average of at least 6.5 across these undergraduate economics courses; do not hold another scholarship that is considered similar.', sc.`scholarship_amount` = 'Up to AUD $10000 — The scholarship is valued at $10,000 for 1 year.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Business and management, Economics', sc.`website` = 'https://scholarships.uq.edu.au/scholarship/archibald-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/archibald-scholarship/6c9a264bdb0c74bd7aedb2d703defe16', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Archibald Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Established in 2025 through an absolute gift from the Au Family.', sc.`eligibility` = 'You\'re eligible if you:; are enrolled in any program at UQ in the year of the award; can demonstrate financial hardship by providing documentary evidence.', sc.`scholarship_amount` = 'Up to AUD $6300', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/au-family-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/au-family-scholarship/c7efe9381a9887ddbd4f5fe872e60fb4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Au Family Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship was established in 2016 by an endowed bequest from the estate of UQ alumna and music critic, Barbara Jean Hebden OAM (BA 1952).', sc.`eligibility` = 'will be enrolled full-time in the first year of the Bachelor of Music (Honours).', sc.`scholarship_amount` = 'Equal to the annual income from the fund.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/barbara-hebden-music-bursary', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/barbara-hebden-music-bursary/4b942c0a078b5a46c4c9500548379d48', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Barbara Hebden Music Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Established in 2013 by the Chin Family Trust.', sc.`eligibility` = 'You\'re eligible if you are:; an international student; a citizen of the People\'s Republic of China; enrolled full-time in any undergraduate or postgraduate coursework program approved by the UQ Business School.', sc.`scholarship_amount` = 'Up to AUD $1000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/business-scholarship-chinese-students', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/business-scholarship-for-chinese-students/be9eb18703b5f365bb69d9ce0e706d16', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Business Scholarship for Chinese Students' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The purpose of this scholarship is to attract and encourage high-achieving students to the Business School Honours program.', sc.`eligibility` = 'You\'re eligible if you:; are a domestic or international student; do not already have external sponsorship for the program (i.e. other scholarships, private sponsor)', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/business-school-honours-tuition-fee-reduction-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/business-school-honours-tuition-fee-reduction-scholarship/a94045f96fa1ac4b9afedb685331844e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Business School Honours Tuition Fee Reduction Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Postgraduate Coursework Master’s Scholarship was established to encourage and support high performing women to undertake postgraduate study related to digital transformation, thus retaining and improving the representation of women in the STEM workforce.', sc.`eligibility` = 'You\'re eligible if you:; intend to commence the Master of Business Analytics program during the 2027 academic year; are a female student; provide a personal statement as outlined in \'How to apply\'; provide a CV.', sc.`scholarship_amount` = 'Up to AUD $5000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/business-school-master-business-analytics-women-stem-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/business-school-master-of-business-analytics-women-in-stem-scholarship/43170c7caa63936b34be578120c3819c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Business School Master of Business Analytics - Women in STEM Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The CONACYT Mexican Scholarship aims to provide Mexican citizens with funding to support studies overseas at the point of admission or while they are undertaking studies abroad to enhance their skills in areas of Science, Technology and Innovation and contribute back to Mexico and form linkages with global partner institutions.', sc.`eligibility` = 'be a citizen of Mexico; have applied for a Masters or PhD program at UQ; satisfy the general and specific requirements and been awarded the CONACYT scholarship; meet the academic requirements for entry to UQ and been offered a place in the program; commence full-time enrolment as an onshore international student at UQ.', sc.`scholarship_amount` = 'Partially funded tuition fees, living allowance; Master maximum 2 years, PhD maximum 4 years', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/conacyt-mexican-scholarship-program', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/conacyt-mexican-scholarship-program/1a2d54af5e9fa9008f94a833ad5d5876', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'CONACYT Mexican Scholarship Program' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Successful applicants who are offered a place in the University\'s PhD program and are supported by their School will also receive a Tuition Fee Scholarship (for up to four years) that covers your PhD tuition fees, along with a living allowance top up to the standard UQ RTP stipend rate.', sc.`eligibility` = 'To apply for this scholarship, you must:; be a citizen and permanent resident of the People’s Republic of China; be eligible to receive an Australian Student Visa; satisfy the selection criteria set by the CSC; satisfy UQ\'s admissions entry requirement and be offered a place in the PhD program; meet the University\'s English proficiency requirement; have a financial commitment for your proposed advisor to top up the CSC living stipend to UQ\'s minimum rate for the duration of your program.', sc.`scholarship_amount` = 'Living allowance, health insurance in Australia, one return airfare from China to Australia, your Australian Student Visa application fees, and a UQ tuition fee scholarship', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/csc', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/csc-uq-phd-scholarship-china-scholarship-council/e91bed66071a2584809adbb85d52a73b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'CSC-UQ PhD Scholarship (China Scholarship Council)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Established in 2019 this scholarship is maintained by a gift from a UQ Bachelor of Computer Science (1979) alumni husband and wife, who in recognition of the encouragement they received to pursue their education would like to leave a legacy for students who may not otherwise have the opportunity to study in the areas of computer science and information technology at UQ.', sc.`eligibility` = 'You\'re eligible if you:; are a commencing student or a prior recipient of this scholarship; can demonstrate financial need; do not hold a scholarship that the Associate Dean considers to be similar.', sc.`scholarship_amount` = 'Up to AUD $4500', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/calboonya-legacy-information-technology-and-computer-science-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/calboonya-legacy-information-technology-and-computer-science-scholarship/c3cb1ec2882d72f8df98bd49a146b06f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Calboonya Legacy Information Technology and Computer Science Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This Scholarship was first established in 1983 and was funded by donations in excess of $50,000 from Miss Florence M. Davey. The Scholarship fund continues to be maintained by UQ on trust. Miss Florence M. Davey, Associate, Licentiate and Fellow of Trinity College of Music, London, taught music until the age of 90 and was dedicated to the pursuit of excellence in piano performance.', sc.`eligibility` = 'You\'re eligible if you:; will be enrolled full-time in the first year of the Bachelor of Music or a dual program that includes the Bachelor of Music.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/florence-davey-pianoforte-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/florence-davey-pianoforte-scholarship/9d88a2e71fbde7edb604da4b18c13b77', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Florence Davey Pianoforte Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'These scholarships include a living stipend to support you as you complete a research project for your Doctor of Philosophy, Master of Philosophy or a research-focused professional doctorate at UQ.', sc.`eligibility` = 'nominated by an enrolling school or institute at UQ; assessed by the Graduate School as meeting all conditions for admission to the higher degree by research program.; not be receiving a living allowance award, or scholarship providing a benefit greater than 75% of the RTP Scholarship living allowance rate to undertake the higher degree by research program', sc.`scholarship_amount` = 'AUD $35000/year — 3.5 years with the possibility of 1 extension in line with UQ and RTP Scholarship Policy', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/graduate-school-scholarships-uqgss-%E2%80%93-includes-rtp', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/graduate-school-scholarships-uqgss-includes-research-training-program-rtp/f5df9f90bf0ba0d0645d46fa67a90dc4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Graduate School Scholarships (UQGSS) - includes Research Training Program (RTP)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Established in 1998 following Howard Sleath\'s bequest of 50% of his estate to the University of Queensland. Mr Howard Sleath was well-known to instrumentalists throughout Australia for the excellence of his craftsmanship and skill as a maker of stringed instruments. Mr Sleath gave the State of Queensland a string quartet of instruments to be kept under the supervision of the Head of the School of Music. The instruments were first demonstrated by the Mayne String Quartet at a concert to inaugurate the Howard Sleath Quartet of Instruments in 1974.', sc.`eligibility` = 'Applicants must: will be enrolled full-time in the first year of the Bachelor of Music (Honours).', sc.`scholarship_amount` = 'Up to AUD $10000 — Equal to the annual income from the fund.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Creative arts', sc.`website` = 'https://scholarships.uq.edu.au/scholarship/howard-f-and-gladys-sleath-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/howard-and-gladys-sleath-scholarship/f1e632e427db4cdefa35389622f67837', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Howard and Gladys Sleath Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Established in 2024 by a gift from International House at The University of Queensland.', sc.`eligibility` = 'You\'re eligible if you are or will be:; an international student in accordance with the University’s Fee Policy in the year of the award; enrolled full-time in an Approved Program in the year of the award; a resident at International House in the year of the award.', sc.`scholarship_amount` = 'Up to AUD $28000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/international-house-global-residency-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-house-global-residency-scholarship/47241767968f4d1f83e5d430f3b22144', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'International House Global Residency Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship was established in 2020 under the Create Change Match Initiative and is maintained by the income generated from an endowment fund established by a donation from Suan Yeo.', sc.`eligibility` = 'You\'re eligible if you:; are an international student in accordance with the University\'s Student Fees Policy; can demonstrate temporary and unexpected financial hardship; are enrolled full-time in any undergraduate program in the year of the award; have not received assistance from the Financial Hardship Assistance Scheme for the year of award; have not been awarded another scholarship, bursary or grant that the Chair considers similar.', sc.`scholarship_amount` = 'Limited to the annual income from the fund.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/international-student-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarship/f8d6bb558656d4b792355dad6232732f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'International Student Scholarship' AND sc.`course_id` IS NULL;
