UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The scholarship was founded in 1936 by gifts of $1,500, $1,000, and $1,000 from Mr Simon Edwin Munro, Mrs Helena Mary Whitehouse, and Mrs Jessie Hamon respectively, in memory of Mrs Mary Alison Miles Munro.', sc.`eligibility` = 'Applicants must: are commencing the second year of a program, including a dual program, administered by the Faculty of Humanities and Social Sciences; have completed at least one modern foreign language course in semester 1 and semester 2 in the year immediately prior; have passed at least 8 units for other courses (if full-time) or at least 4 units for other courses (if part-time), in the year immediately prior to the year the scholarship is awarded.', sc.`scholarship_amount` = 'Up to AUD $300 — The scholarship is valued at $300 for 1 year.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Languages', sc.`website` = 'https://scholarships.uq.edu.au/scholarship/mary-alison-miles-munro-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/mary-alison-miles-munro-scholarships/3060e98d14a33ab5069418a86e8407f8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'Mary Alison Miles Munro Scholarships' AND sc.`course_id` IS NULL;
