UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you are eligible, we will notify you that youre offered this scholarship together with your letter of offer to study at UQ. In this notification, we will let you know what date you have to accept the scholarship by. If youre awarded the scholarship, the 25% tuition fee reduction will be applied prior to the tuition fees due date each semester.', sc.`eligibility` = 'Youre eligible if you: are an international student.; have received an unconditional offer to study full-time at UQ commencing Semester 1 or 2, 2025 in an eligible program.; have satisfied the program entry rank and English language proficiency requirements.; have achieved a competitive score as determined by the University among the pool of offer holders for programs in their commencement semester.; will enrol full-time.', sc.`scholarship_amount` = '25% reduction in tuition fees per semester', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/uq-international-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uq-international-excellence-scholarship/a16b45772e886725d731a46c10d7ef23', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'UQ International Excellence Scholarship' AND sc.`course_id` IS NULL;
