UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship was established in 2013 and maintained by gifts from donors including UQ staff, alumni and friends.', sc.`eligibility` = 'You\'re eligible if you:; identify as a member of the LGBTQIA+ community; are or will be enrolled in an Approved Program in the semester of the award; can demonstrate financial hardship by providing documentary evidence; can demonstrate commitment to the LGBTQIA+ community; have not previously received the scholarship.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/uq-lgbtqia-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uq-lgbtqia-scholarship/549ec1350ed90d20add9c4fec76bd39f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'UQ LGBTQIA+ Scholarship' AND sc.`course_id` IS NULL;
