UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The UQ Refugee and Humanitarian Scholarship is funded by The University of Queensland (UQ). Established in 2021, this Scholarship offers students from refugee or asylum seeker backgrounds the opportunity to pursue higher education in any desired discipline at UQ.', sc.`eligibility` = 'You\'re eligible if you:; are or will be enrolled in an undergraduate or postgraduate coursework program at UQ; hold one of the following Australian visas:; Temporary Protection Visa (subclass 785), Safe Haven Enterprise Visa (subclass 790), Temporary Humanitarian Concern Visa (subclass 786), Temporary Humanitarian Stay Visa (subclass 449); any other similar visa from time to time that the Australian government might enact for people from refugee or asylum seeker backgrounds; Bridging Visa E (subclass 050) or Bridging Visa A (subclass 010) if you have applied for any of the above-mentioned visas.; have not received the Scholarship previously for the same level of study; do not hold another similar scholarship; can demonstrate financial hardship by providing documentary evidence.', sc.`scholarship_amount` = '100% tuition fee waiver, plus $29,000 annual living stipend', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/uq-refugee-and-humanitarian-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uq-refugee-and-humanitarian-scholarship/a03cb0f1a4818f2257bdb03315996801', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'UQ Refugee and Humanitarian Scholarship' AND sc.`course_id` IS NULL;
