UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The scholarship was established in 2009 for the purpose of encouraging meritorious students who are enrolled in studies in music and are residents of St Leo\'s College. The scholarship is maintained by an annual gift from The University of Queensland in the form of a contribution to the residential fees payable by such a student (or students) and an annual gift from St Leo\'s College in the form of a reduction in those fees.', sc.`eligibility` = 'You\'re eligible if you\'re:; enrolled full-time in the Bachelor of Music or a dual program that includes the Bachelor of Music or a program that includes a Music Course in each semester for the year; a resident at St Leo\'s College.', sc.`scholarship_amount` = 'Up to AUD $6000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.uq.edu.au/scholarship/university-queensland-and-st-leos-college-music-achievement-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/university-of-queensland-and-st-leos-college-music-achievement-scholarship/e0c9ce9b479c04309f01ca23fb005168', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00025B' AND sc.`scholarship_name` = 'University of Queensland and St Leo\'s College Music Achievement Scholarship' AND sc.`course_id` IS NULL;
