UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Stipend scholarship to support PhD students within the Faculty of Medicine and Health.', sc.`eligibility` = 'You must:; have an unconditional offer of admission or be currently enrolled to study full-time in a PhD within the Faculty of Medicine and Health at the University of Sydney; not have completed more than four (full-time equivalent) research periods of candidature at the time of application; conduct research in prevention, early detection or more effective treatment of breast cancer; not hold or have been offered another Higher Degree by Research primary stipend scholarship administered by the University of Sydney at the time of application.', sc.`scholarship_amount` = 'The Scholarship will provide a stipend allowance equivalent to the University of Sydney Research Training Program (RTP) Stipend rate (indexed on 1 January each year) up to 3.5 years, subject to satisfactory academic performance.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.sydney.edu.au/scholarships/c/elvita-eveline-clough-cancer-research-scholarship.html', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/elvita-eveline-clough-cancer-research-scholarship/36d9be9677c50c80644ffa229c5c40bf', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00026A' AND sc.`scholarship_name` = 'Elvita Eveline Clough Cancer Research Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A French and Francophone Studies and Germanic Studies scholarship that supports high-achieving students.', sc.`eligibility` = 'You must:; be currently enrolled in 4000-level units of study within the Faculty of Arts and Social Sciences in one of the following:; Bachelor of Arts (Languages), Bachelor of Arts and Bachelor of Advanced Studies, Bachelor of Arts and Bachelor of Advanced Studies (Languages), Bachelor of Arts (Honours) OR; have completed a Bachelor of Arts with a major in French and Francophone Studies or in Germanic Studies at the University of Sydney or another University and having an unconditional offer of admission and subsequently enrol in 4000-level units of study within the Faculty of Arts and Social Sciences in one of the following:; Bachelor of Arts (Honours), Bachelor of Advanced Studies (Honours).; be majoring in French and Francophone Studies or in Germanic Studies.; have received an average of 70% in six units of study in French and Francophone Studies or in Germanic Studies.', sc.`scholarship_amount` = 'Up to AUD $20000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.sydney.edu.au/scholarships/b/honours-scholarship-french-francophone-studies-germanic-studies.html', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/emilie-m-schweitzer-scholarship-in-french-and-germanic-studies/33d5b43171e3b6e3971b1f6970a19a73', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00026A' AND sc.`scholarship_name` = 'Emilie M Schweitzer Scholarship in French and Germanic Studies' AND sc.`course_id` IS NULL;
