UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A University of Sydney RTP rate scholarship to support a student willing to undertake research at the University of Sydney.', sc.`eligibility` = 'You must:; be a domestic or international student; have an unconditional offer of admission or be enrolled in a full-time in a PhD at the University of Sydney; be willing to conduct research in the area of chemistry in relation to industry and agriculture, including chemistry connected with electrical engineering, metallurgical chemistry and chemistry in its application to mining and the winning and treatment of minerals and natural products of the soil; hold an honours degree (first class or second class upper) or a master\'s degree in a related field with a substantial research component or equivalent.', sc.`scholarship_amount` = 'This scholarship will provide an annual stipend allowance equivalent to the University of Sydney RTP rate (indexed on 1 January each year) for up to three years and six months, subject to satisfactory academic performance', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.sydney.edu.au/scholarships/d/henry-bertie-and-florence-mabel-gritton-research-scholarships.html', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/henry-bertie-and-florence-mabel-gritton-research-scholarships/0986e11a2d627bb8bc816969f16a70ac', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00026A' AND sc.`scholarship_name` = 'Henry Bertie and Florence Mabel Gritton Research Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Stipend scholarship to support postgraduate research in the Faculty of Medicine and Health.', sc.`eligibility` = 'You must:; have an unconditional offer of admission or be currently enrolled to study full-time in a PhD within the Faculty of Medicine and Health at the University of Sydney; conduct research in treatment of rheumatoid arthritis; not have completed more than four (full-time equivalent) research periods of candidature at the time of application\r\n; not hold or have been offered another Higher Degree by Research primary stipend scholarship administered by the University of Sydney at the time of application.', sc.`scholarship_amount` = 'The Scholarship will provide a stipend allowance equivalent to the University of Sydney Research Training Program (RTP) Stipend rate (indexed on 1 January each year) up to 3.5 years, subject to satisfactory academic performance.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.sydney.edu.au/scholarships/c/henry-langley.html', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/henry-langley-scholarship/48b9c3a1334aa9ecb481807986045dde', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00026A' AND sc.`scholarship_name` = 'Henry Langley Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A stipend allowance awarded to a PhD student conducting research in pharmacy at the Faculty of Medicine and Health, University of Sydney.', sc.`eligibility` = 'You must:; Have an unconditional offer of admission or be currently enrolled to study full-time in a PhD within the Faculty of Medicine and Health at the University of Sydney; not have completed more than four (full-time equivalent) research periods of candidature at the time of application; conduct research in pharmacy; not hold or have been offered another Higher Degree by Research primary stipend scholarship administered by the University of Sydney at the time of application.', sc.`scholarship_amount` = 'USYD RTP rate p.a. (up to 3.5 years)', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.sydney.edu.au/scholarships/c/james-millner-scholarship-in-pharmacy.html', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/james-millner-scholarship-in-pharmacy/b8307578311c4933efe6a4e0e6878ff2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00026A' AND sc.`scholarship_name` = 'James Millner Scholarship in Pharmacy' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A $5000 scholarship to assist students to complete the offshore component of their Joint PhD Program.', sc.`eligibility` = 'be a domestic or international student; be enrolled in a joint PhD program at the University of Sydney, where the University of Sydney is the your home institution; be enrolled at one of University of Sydney’s active international partners as the host institution; have a fully executed individual Student Agreement; have completed their annual progress evaluation and have received a meets/exceeds at your most recent progress review; only apply to Sydney Global Mobility for this scholarship once your offshore component of your Joint PhD Program has been confirmed; not have previously received this scholarship; not be under examination are not eligible.', sc.`scholarship_amount` = 'Up to AUD $5000 — This scholarship will provide a one-off payment of $AUD 5000 for one year.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.sydney.edu.au/scholarships/e/sydney-global-mobility-joint-phd-travel-scholarship.html', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/sydney-global-mobility-joint-phd-travel-scholarship/cc783859ac63e1b5b56899b46b045485', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00026A' AND sc.`scholarship_name` = 'Sydney Global Mobility Joint PhD Travel Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Sydney International Student Award celebrates our diverse and talented community of international students. We want to help motivated applicants to achieve their personal and academic goals, by supporting their study at the University of Sydney.', sc.`eligibility` = 'be an international student; hold citizenship in one of the countries or regions listed below; receive admission into a full-time undergraduate coursework or postgraduate coursework degree, commencing in 2025; not be an Australian or New Zealand citizen, or a permanent resident of Australia; not have already started a degree at the University of Sydney at the time that you apply for the award. However, you are eligible if you are completing a degree here and are applying for the award with a second degree.', sc.`scholarship_amount` = 'Recipients will be awarded a University contribution of 20 percent of their tuition fee for the duration of their course.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.sydney.edu.au/study/fees-and-loans/scholarships/sydney-international-student-award.html', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/sydney-international-student-award/434ab565bdb8b19c491b498a190d5bd0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00026A' AND sc.`scholarship_name` = 'Sydney International Student Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'TAFE SA 2026 International Scholarship Programs are designed to support international students and enhance access to high‑quality vocational education and training in South Australia.\r\n\r\nThe 2026 scholarships recognise academic commitment and support students at different stages of their study journey, including those undertaking longer‑term programs and those relocating to commence shorter courses.\r\n\r\nInternational Scholarships:\r\nValue: $2,000 per student\r\nBenefit: Provided as a credit towards tuition fees\r\nPayment structure: Two instalments of $1,000 applied in the second and fourth semesters of study\r\nEligibility: Brand new international students commencing their studies before 30 June 2027, with a total study duration of two (2) years or more.\r\n\r\nRelocation Assistance Scholarship\r\nValue: $500 per student\r\nBenefit: Paid as a direct payment to assist with relocation costs\r\nEligibility: Brand new international students commencing before 30 June 2027, with a total study duration of less than two (2) years.\r\nPayment timing: Can be claimed post‑commencement.\r\n\r\nCheck the website for the Scholarships full Terms and Conditions and a list of other available options.', sc.`eligibility` = 'Please Contact TAFESA for more information about Eligibility.', sc.`scholarship_amount` = 'full tuition fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.tafesa.edu.au/international/before-starting/int-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/tafe-sa-int-scholarships/d746b80d30bad02158ca90faf5ba9ddb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00092B' AND sc.`scholarship_name` = 'TAFE SA INT Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The AGSM Emerging Female Leaders Scholarship will enable high potential female leaders to complete a world-class MBA.', sc.`eligibility` = 'This scholarship is open to domestic and international female candidates who are in the first five years of their career and receive an offer of admission to the AGSM Full-Time MBA program.', sc.`scholarship_amount` = 'Minimum of two scholarships are available per year.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'http://www.business.unsw.edu.au/agsm/scholarships-prizes/mba-full-time-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/agsm-emerging-female-leaders-scholarship/d8e09b3b8a185bddc625ead16b4aa9bc', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'AGSM Emerging Female Leaders Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The AGSM Excellence Scholarship will give MBA candidates who have a proven track record of academic and professional excellence an opportunity to participate in AGSM’s Full-Time MBA program.', sc.`eligibility` = 'This scholarship is open to all applicants who receive an offer of admission to AGSM’s Full-Time MBA program.', sc.`scholarship_amount` = 'Minimum of six scholarships available.\r\n\r\nFull and partial tuition fee waivers are available for eligible candidates.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'http://www.business.unsw.edu.au/agsm/scholarships-prizes/mba-full-time-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/agsm-excellence-scholarship/55653087dba05e89695ac3c4d65b08ca', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'AGSM Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The AGSM Global Reach Scholarship gives exceptional students from diverse international backgrounds access to AGSM’s Full-Time MBA program located in Sydney.', sc.`eligibility` = 'These scholarships are open to international MBA candidates who have received an offer of admission to the AGSM Full-Time MBA program.', sc.`scholarship_amount` = 'Minimum of six scholarships available, with one recipient per country. These scholarships may be awarded in any admissions round.\r\n\r\nFull and partial tuition fee waivers are available for eligible candidates.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'http://www.business.unsw.edu.au/agsm/scholarships-prizes/mba-full-time-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/agsm-global-reach-scholarship/4476ed23e181c5cdb51e6425ac5f2903', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'AGSM Global Reach Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Australia\'s Global University Award (PUCA1026)', sc.`eligibility` = 'Be an international student; and \r\nBe commencing full-time study on campus in a UNSW undergraduate or postgraduate coursework degree program (excluding UNSW Online and UNSW Canberra); and \r\nHave received an offer of admission* into an eligible program for Term 3 2025 by 11.59PM AEST Tuesday, 15 July 2025. \r\nOffers of admission must be one of the following:\r\nUndergraduate or postgraduate Letter of Offer (unconditional), \r\nUndergraduate or postgraduate Conditional English Package Offer (UEEC) - students must be enrolled in the UNSW Institute of Languages and successfully complete the program prior to commencing in Term 3 2025.', sc.`scholarship_amount` = '$10,000 for one year. Payment will be made directly towards tuition fees in the second term of the first year of study.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australias-global-university-award-puca1026/92ab8eb4577b1d2d7d1d1546b645b6d3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'Australia\'s Global University Award (PUCA1026)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'International Scientia Coursework Scholarship (PUCA1025)', sc.`eligibility` = 'Be an International Student; and\r\nBe commencing full-time study on campus in a UNSW undergraduate or postgraduate coursework program (excluding UNSW Online and UNSW Canberra); and\r\nHave received an offer of admission* into an eligible program for Term 3 2025 by Tuesday, 15 July 2025.\r\n* Offers of admission must be one of the following:\r\nUndergraduate or postgraduate Letter of Offer (unconditional); or\r\nUndergraduate or postgraduate Conditional English Package Offer (UEEC) - students must be enrolled in the UNSW Institute of Languages and successfully complete the program prior to commencing in Term 3 2025.', sc.`scholarship_amount` = 'Offer 1: Full tuition fee scholarship paid directly towards tuition fees for the minimum duration of program\r\nOffer 2: $20,000 per annum paid directly towards tuition fees for the minimum duration of program', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-scientia-coursework-scholarship-puca1025/056c4abb2770fb21dd120aed47a6faac', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'International Scientia Coursework Scholarship (PUCA1025)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Student Award has been established to assist students from low income and developing countries to access education at a highly ranked Australian university. It is available to eligible new students commencing in 2025 and 2026 and provides a 15% contribution towards tuition fees for the duration of program.', sc.`eligibility` = 'Be an International Student; and\r\nBe a citizen of an eligible country; and\r\nBe commencing full-time study as a new student on campus^ in a UNSW Diploma, UNSW undergraduate or postgraduate coursework program (excluding programs offered by AGSM, UNSW Online, UNSW Canberra, UNSW Foundation Programs, Transition Program Online, any program taught in the Hexamester calendar, or Study Abroad students); and\r\nHave applied and received an offer of admission* into a UNSW undergraduate or postgraduate degree program; and\r\nNot be a current student of UNSW (exceptions made for those who have completed an undergraduate program at UNSW and are commencing a postgraduate program).', sc.`scholarship_amount` = 'Provides a 15% contribution directly towards tuition fees.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-student-award/599436be57d56e56bf3ec9cdcfdfff50', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'International Student Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The purpose of the Scholarship is to support current UNSW students undertaking an undergraduate degree in marketing.', sc.`eligibility` = 'Be undertaking full-time study in the third year of the Bachelor of Commerce (Marketing) program at the UNSW Business School', sc.`scholarship_amount` = 'Up to AUD $5000 — The scholarship is valued at $4,000 for 1 year.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Business and management', sc.`website` = 'http://www.scholarships.unsw.edu.au/scholarships/id/142', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/lee-whitmont-award-in-marketing/f63359d3b3d51a1877a11839283b2d25', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'Lee Whitmont Award in Marketing' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The purpose of the Scholarship is to support and encourage students from Singapore to undertake full-time undergraduate study at UNSW Arts, Design and Architectures’ School of Built Environment.', sc.`eligibility` = 'Be an International Student and hold a Singapore citizenship. \r\nBe commencing a UNSW undergraduate coursework degree program offered through the Faculty of Arts, Design and Architecture\'s School of Built Environment. \r\nHold a diploma or equivalent course of at least 2 years credit from one of the following institutions: Nanyang Polytechnic, Ngee Ann Polytechnic, Singapore Polytechnic, Temasek Polytechnic, Republic Polytechnic.\r\nMust have received an offer of admission* into an eligible program for Term 3 2025 by Tuesday 15 July 2025*\r\nOffers of admission must be one of the following:\r\nUndergraduate Letter of Offer (unconditional)\r\nUndergraduate Conditional English Package Offer (UEEC) - students must be enrolled in the UNSW Institute of Languages and successfully complete the program prior to commencing in Term 3 2025.', sc.`scholarship_amount` = '$5,000 per annum payable for normal minimum duration of degree towards tuition fees.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/lily-and-dr-ben-kc-chng-scholarship-ugce1129/691c6861c32a9729cc068c84a285fed4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'Lily and Dr Ben K.C. Chng Scholarship (UGCE1129)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Put your summer holidays to good use with a six-week Summer Vacation Research Scholarship. You’ll gain valuable research experience working with our renowned supervisors to participate in a research project. If you’re a talented undergraduate science student enrolled in your second year or above, it’s an opportunity worth applying for.', sc.`eligibility` = 'You must be currently enrolled in second-year or above of an undergraduate program in the Faculty of Science or a science-related discipline at UNSW or another Australian university. You must be able to be engaged in a project on a full-time basis (35 hours/week for six weeks during normal working hours unless advised otherwise by the supervisor). Projects must focus on research-based activities (administration tasks are not regarded as research) and should be completed by the end of February. Each successful candidate can hold only ONE such scholarship at a time. Students who were previously awarded a UNSW Science Vacation Research Scholarship are not eligible to apply.', sc.`scholarship_amount` = 'Each scholarship is $3800 for a six-week research project.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Sciences', sc.`website` = 'https://www.unsw.edu.au/science/student-life-resources/student-opportunities/research-integrated-learning/summer-vacation-research-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/summer-vacation-research-scholarship/a548200d8a3e6d1cba092dd58e1e58ec', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'Summer Vacation Research Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The UNSW Law & Justice International Award has been established to encourage high quality international students to join UNSW Law programs (LLB, JD or LLM)', sc.`eligibility` = 'Be an International Student; and\r\nBe commencing in any UNSW Law & Justice undergraduate/postgraduate coursework degree program (LLB, JD or LLM programs)\r\nMust have received an offer of admission into an eligible program for Term 3 2025 by Tuesday, 15 July 2025. Offers of admission must be one of the following:\r\nUndergraduate or Postgraduate Letter of Offer (unconditional)\r\nUndergraduate or Postgraduate Conditional English Package Offer (UEEC) - students must be enrolled in the UNSW Institute of Languages and successfully complete the program prior to commencing in Term 3 2025.', sc.`scholarship_amount` = '$10,000 paid directly towards tuition fees for 1 year.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/unsw-law-justice-international-award-puca1028/b5713e13725a7999a1fc8901d69abf19', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'UNSW Law & Justice International Award (PUCA1028)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'UNSW Master of Laws International Scholarship (PGCA1107)', sc.`eligibility` = 'Be an international student; and \r\nHave undertaken an undergraduate qualification from a member school of the Law School Global League or an approved UNSW partner institution; and \r\nBe commencing full-time study in the UNSW Master of Laws program offered by the Faculty of Law & Justice; and \r\nHave received an offer of admission* into an eligible program for Term 3 2025 by Tuesday, 15 July, 2025*.  \r\n* Offers of admission must be one of the following:\r\nPostgraduate Letter of Offer (unconditional).', sc.`scholarship_amount` = '$20,000 for one year. Payment will be made directly towards tuition fees.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scholarships.unsw.edu.au/unsw-scholarships-international-students-commencing-term-3-2025', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/unsw-master-of-laws-international-scholarship-pgca1107/393bab7b66410e3bf6477226425486e8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00098G' AND sc.`scholarship_name` = 'UNSW Master of Laws International Scholarship (PGCA1107)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'To support commencing international students who wish to undertake an undergraduate or postgraduate coursework program at UTS in Sydney.', sc.`eligibility` = 'Remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); Meet all admission requirements for the selected UTS undergraduate (including Honours programs) or postgraduate coursework program; Commence full-time and on campus (Sydney)', sc.`scholarship_amount` = '20% of UTS Tuition Fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uts.edu.au/scholarship/uts-academic-merit-international-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uts-academic-merit-international-scholarship/398cff14fd96edcc76808322fbaab8ad', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00099F' AND sc.`scholarship_name` = 'UTS Academic Merit International Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'To support commencing international students from South Asia who wish to undertake an undergraduate or postgraduate coursework program at UTS in Sydney.', sc.`eligibility` = 'Remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); Be a citizen of a country in the South Asia region (Bangladesh, India, Nepal, Pakistan or Sri Lanka); Meet all admission requirements for the selected UTS undergraduate (including Honours programs) or postgraduate coursework program; Commence full-time and on campus (Sydney)', sc.`scholarship_amount` = '15% of UTS Tuition Fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uts.edu.au/scholarship/uts-academic-merit-international-scholarship-south-asia', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uts-academic-merit-international-scholarship-south-asia/46e9b4acceb96525472e7a6094b60606', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00099F' AND sc.`scholarship_name` = 'UTS Academic Merit International Scholarship – South Asia' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This Scholarship was established to support commencing international students from P.R. China to enroll in an undergraduate coursework program at UTS in Sydney.', sc.`eligibility` = 'Remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); Be a citizen from P.R. China; Commence full-time studies and on campus[1] at UTS in 2024 or 2025; Meet UTS admission criteria for the selected undergraduate coursework program', sc.`scholarship_amount` = '20% off UTS tuition fees', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uts.edu.au/scholarship/uts-chinese-undergraduate-tuition-fee-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uts-chinese-undergraduate-tuition-fee-scholarship/dacd085d4643cf8ecf7b73cb5fcbf9ac', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00099F' AND sc.`scholarship_name` = 'UTS Chinese Undergraduate Tuition Fee Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The purpose of the UTS Onshore Postgraduate International Scholarship is to attract commencing international students already in Australia to enroll in a postgraduate coursework program at UTS.', sc.`eligibility` = 'Must remain an international student (not an Australian citizen, New Zealand citizen or permanent resident of Australia); Must be a citizen from a country in the South Asia, South East Asia or Africa region; Must have completed a recognised Australian tertiary qualification at a Bachelor degree level or higher; Must meet all admission criteria for the selected Master by coursework program; Must be commencing studies at UTS full-time and on campus', sc.`scholarship_amount` = '25% of UTS tuition fees', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uts.edu.au/scholarship/uts-onshore-postgraduate-international-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uts-onshore-postgraduate-international-scholarship/99fc253e60a4d4c84102aa447f31f027', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00099F' AND sc.`scholarship_name` = 'UTS Onshore Postgraduate International Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'UTS offers merit-based Study Abroad Excellence Scholarship for commencing Study Abroad students. Selection is based on academic excellence in the most recently completed tertiary qualification recognized by UTS for entry in the Study Abroad program. A separate application is not required.', sc.`eligibility` = 'Future international students intending to commence and enrol in 18-24 credit points and undertake a study abroad program in Autumn and Spring sessions.\r\nSelection process', sc.`scholarship_amount` = 'Up to AUD $2000 — $1,000 - $2,000; Duration 1 Session', sc.`level_of_studies` = 'Undergraduate / VET, Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uts.edu.au/scholarship/uts-study-abroad-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uts-study-abroad-excellence-scholarship/83e1b32aed68eed9fb5aa66f3f4bd7a8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00099F' AND sc.`scholarship_name` = 'UTS Study Abroad Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Please Contact University of Wollongong Australia for more information.', sc.`eligibility` = 'Students who meet the above citizenship requirements at the time of application will automatically receive the UOW Country scholarship when they choose to study a coursework degree at the University of Wollongong commencing in 2025 and beyond.; Students can only receive one (1) UOW scholarship, sponsorship or bursary for the same course.; Students course transferring will no longer be eligible for the scholarship.', sc.`scholarship_amount` = '20% tuition fee reduction for the minimum duration of an eligible course', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uow.edu.au/study/scholarships/international/country-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/country-scholarship/08d5d38bb77e1e9fe54f8d2e7b9063c8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00102E' AND sc.`scholarship_name` = 'Country Scholarship' AND sc.`course_id` IS NULL;
