UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Recipients of the Accommodation Bursary will receive a discounted weekly rental rate equivalent to 50% of the standard published rental fee for eligible on-campus accommodation. The bursary is applicable for two consecutive semesters (in-semester periods only). Acceptance of the bursary constitutes a commitment to reside in university accommodation for the full duration of two semesters.', sc.`eligibility` = 'To be eligible for the bursary, you must:; be a new international student who will begin their studies with Federation University in Australia in Semester 2 2026; have Confirmation of Enrolment (COE) issued by Federation University; be enrolling in an eligible course (excluding OS exchange and Study Abroad); be studying at Federation University Australia in Ballarat, Gippsland, Berwick or; Melbourne City Campus; not be in receipt of a Destination Australia scholarship; be in receipt of an offer letter than includes an accommodation bursary', sc.`scholarship_amount` = 'Recipients of the Accommodation Bursary will receive a discounted weekly rental rate equivalent to 50% of the standard published rental fee for eligible on-campus accommodation.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/accommodation-bursary/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-accommodation-bursary/8b6d77781c2fd8dc15409971bb37838a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2026 Accommodation Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Accept an offer from Federation and pay the deposit as listed on your offer by the given date to receive a one-off bursary in your second year of study.', sc.`eligibility` = 'To be eligible for the bursary, applicants must:; be a fee-paying international student (not a study abroad, exchange or online student); be enrolling as a commencing student in an eligible intake period; be eligible to study in Australia with a valid visa', sc.`scholarship_amount` = 'This bursary is awarded as a tuition fee discount in your third semester of study.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/early-bird-bursary/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-early-bird-bursary/c1c94b7b8b3ca8b892c766efc9215800', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2026 Early Bird Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is awarded in instalments with the first instalment awarded to successful recipients at the time of offer. Ongoing scholarship instalments will be allocated to awardee\'s student fee account prior to the following census date and on confirmation of meeting ongoing GPA requirements.', sc.`eligibility` = 'To be eligible for the scholarship, applicants must:; be an international student (not a study abroad, exchange or online student); be enrolling as a commencing student in 2026; be eligible to study in Australia with a valid visa; meet the additional terms and conditions as set out below.', sc.`scholarship_amount` = 'The scholarship covers 20% of the tuition fees and is initially awarded for a period of two semesters.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/federation-merit-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-federation-merit-scholarship/ae8fa045c2daed8ca063c984af227809', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2026 Federation Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Federation University Australia is pleased to offer a Pathways Scholarship to international students who commence in a Federation University pathway course in 2026.', sc.`eligibility` = 'To be eligible for the scholarship, applicants must be: a prospective international student; enrolling as a commencing student in 2026; eligible to study in Australia with a valid visa; enrolling in an eligible pathway course.', sc.`scholarship_amount` = 'The Federation Pathways Scholarship is equivalent to 20% of the annual tuition fees of a pathway course such as Foundation or Higher Education Diploma.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/federation-pathways-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-federation-pathways-scholarship/1e1d3dbce847366759e2c169b9fc10ae', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2026 Federation Pathways Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'By studying a pathway course, such as a Higher Education Diploma, you may receive a percentage off your tuition fee. Get rewarded for boosting your skills and confidence as you prepare for undergraduate study.', sc.`eligibility` = 'To be eligible for the scholarship, applicants must be:; an international student (not a study abroad, exchange or online student); enrolling as a commencing student in 2026; eligible to study in Australia with a valid visa; enrolling in an eligible pathway course', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/federation-pathways-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-federation-pathways-scholarship/bda48bee40c3bb572341df3a9d2f024d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2026 Federation Pathways Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Federation provides support for international students who have mandatory placement units but are not doing Co-op courses. With a minimum payment for the placement hours required in their course - up to $10,000 for undergraduates and $5,000 for postgraduates, these payments  will be distributed in instalments  throughout your study.', sc.`eligibility` = 'To be eligible for the scholarship, students must:; be a commencing international student (not a study abroad, exchange or online student) in 2025 or 2026; be enrolled in an eligible coursework course that requires mandatory placement; enrol in the mandatory placement units; be eligible to study in Australia with a valid visa; meet the additional terms and conditions as set out below.', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/placement-support-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-paid-placement-support-guarantee/5a5248d64550a9d6ddd3e40fd73999d7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2026 Paid Placement Support Guarantee' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Partner Scholarship is designed to support international students who transfer from Federation partner offshore locations to Australia to complete their studies or begin a new degree. Recipients will get a 20% tuition fee discount.', sc.`eligibility` = 'To be eligible for the scholarship, applicants must:; be an international student transferring from a Federation offshore delivery partner or an international student who has completed XCore units with Employability.; be eligible to study in Australia with a valid visa; have completed (or be in the process of completing) an approved Federation University course or a non-award short course that is formally recognised for credit towards a Federation University degree at an approved Federation University offshore partner institution; be enrolling onshore at a Federation University Australian campus to complete the same course or commence a new eligible Federation University course.', sc.`scholarship_amount` = 'This scholarship is awarded in instalments, with the first instalment awarded to successful recipients at the time of offer. Ongoing scholarship instalments will be allocated to awardee’s student fee account prior to census date each semester.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/partner-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-partner-scholarship/04625496d46f4edeca854a639137e5c2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2026 Partner Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'As a trusted supplier of advanced materials for industries such as aerospace, technology, healthcare, and energy, Stanford Advanced Materials (SAM) has long been focused on the industrial applications and development trends of rare metals. To explore the potential of rare metals fully, we invite outstanding students to join us in discussing their applications and future directions. We are also proud to announce the establishment of the 2025 College Scholarship by Stanford Advanced Materials to support students who demonstrate excellence in this field.', sc.`eligibility` = 'Open to high school, undergraduate, and graduate students worldwide. Submissions are only accepted in English, Spanish, German, French, Italian, and Japanese.; Submissions must focus on the industrial applications and development trends of rare metals.; Projects with originality, technical feasibility, and potential impact on the industrial development of rare metals are strongly encouraged.; Submissions generated using artificial intelligence (AI) are prohibited and will be disqualified.', sc.`scholarship_amount` = 'Up to AUD $1000', sc.`level_of_studies` = 'Secondary schooling, Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.samaterials.com/stanford-advanced-materials-college-scholarship.html?utm_source=EDM&utm_medium=scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-stanford-advanced-materials-college-scholarship/6486bbd84acd943fa0a83514beca1504', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2026 Stanford Advanced Materials College Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is offered to support international students who choose to live in Federation\'s on-campus accommodation in Victoria. Students will receive 50% off the cost of weekly rent for their first year, and 25% off standard accommodation rates for the second year. Subject to availability. Additional fees may apply.', sc.`eligibility` = 'Prospective international students will automatically be assessed for an Accommodation Bursary at the time they receive an offer to study at the University. No additional application is required.', sc.`scholarship_amount` = 'Up to AUD $7278 — New international students joining the FedLiving community at our Mt Helen and Berwick campuses may be eligible for up to $1,000 per semester (for a maximum of two semesters, subject to $550 acceptance fee).', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/2027-accommodation-bursary/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2027-accommodation-bursary/ee965bf650252b4eb28add7d86f4404e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2027 Accommodation Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This tuition fee scholarship provides eligible international students 15% off annual tuition fees for the duration of their course. This scholarship cannot be combined with other tuition fee scholarships.', sc.`eligibility` = 'To be eligible for the scholarship, applicants must: be an international student (not a study abroad, exchange or online student), be enrolling as a commencing student in 2027, be enrolling in an undergraduate or postgraduate coursework degree at Federation University Australia, be eligible to study in Australia with a valid visa, meet the additional terms and conditions as set out below, and not be in receipt of any other merit-based and/or tuition fee scholarships.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/2027-global-achiever-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2027-global-achiever-scholarship/1a36d036343caa5a6ef1e0ca499ed469', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2027 Global Achiever Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'International students may receive 25% off their annual tuition fees for the duration of their course, based on academic merit. Achieve an average of 75% or equivalent in previous studies to be eligible.', sc.`eligibility` = 'To be eligible for this scholarship, applicants must: be an international student (not a study abroad, exchange or online student), be enrolling as a commencing student in 2027, be enrolling in an undergraduate or postgraduate coursework degree at Federation University Australia, be eligible to study in Australia with a valid visa, and meet the additional terms and conditions as set out below.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/2027-global-merit-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2027-global-merit-scholarship/33fbd9803832fb9e965845ef7f4dcbef', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2027 Global Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship supports international students who have mandatory placement units but are not doing Co-op courses. Students receive $10,000 (undergraduate) or $5,000 (postgraduate) in instalments to support them while completing their placement.', sc.`eligibility` = 'To be eligible for this scholarship, students must: be a commencing international student, be enrolled in an eligible coursework course that requires mandatory placements, enrol in mandatory placement units, be eligible to study in Australia with a valid visa, and meet the additional terms and conditions set out on the scholarship webpage.', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Education and training, Health services and support, Nursing, Social work', sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/2027-placement-support-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2027-paid-placement-support-guarantee/d96c5a236c5b65a6094e8b41139befd9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2027 Paid Placement Support Guarantee' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship supports international students who transfer from an offshore Federation partner provider to one of our campuses in Victoria. Whether continuing their studies in Australia or start a new course, recipients will receive 20% off annual tuition fees for the duration.', sc.`eligibility` = 'To be eligible for the scholarship, applicants must: be an international student transferring from a Federation offshore delivery partner or an international student who has completed XCore units with Employability.Life, be eligible to study in Australia with a valid visa, have completed (or be in the process of completing) an approved Federation University course or a non-award short course that is formally recognised for credit towards a Federation University degree at an approved Federation University offshore partner institution, be enrolling onshore at a Federation University Australian campus to complete the same course or commence a new eligible Federation University course.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/2027-partner-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2027-partner-scholarship/fc4ef372b65e31251d910d51447a6520', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = '2027 Partner Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Overarching Aim of the PhD:Athletes from regional and rural Australia face significant barriers in accessing high-performance sport pathways, including limited access to coaching, sport science support, and elite competition environments. Advances in sport technology (e.g., wearable sensors, remote coaching platforms, performance analytics) offer an opportunity to overcome these geographic constraints.This PhD project will design, implement, and evaluate technology-enabled athlete development models to support regional athletes in achieving high-performance outcomes without the need for relocation.', sc.`eligibility` = 'To be eligible for the project, you must:; be eligible for a PhD; willing to undertake full-time study', sc.`scholarship_amount` = 'Up to AUD $50000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/research/bridging-the-distance-using-sport-technology-to-enhance-high-performance-pathways-for-rural-athletes/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/bridging-the-distance-using-sport-technology-to-enhance-high-performance-pathways-for-rural-athletes/06b0787828a51c61a4477cd64189cbd0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = 'Bridging the distance: Using sport technology to enhance high-performance pathways for rural athletes' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Foundation for Rural & Regional Renewal is the only national foundation specifically focused on ensuring the social and economic strength of Australia\'s remote, rural and regional communities. We understand the big picture, and the fine grain, and collaborate to address real needs, at scale. Our unique model connects common purposes and investment with locally prioritised needs, often reaching some of the smallest communities. We amplify this support into longer-term capability, momentum and resilience. Harnessing goodwill to ensure the long-term vitality of remote, rural and regional Australia.', sc.`eligibility` = 'Please Contact Federation University for more information about Eligibility', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/foundation-scholarships/foundation-for-rural-and-regional-renewal-diversity-in-regional-telehealth-bursaries2/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/foundation-for-rural-and-regional-renewal-diversity-in-regional-telehealth-bursaries/08619451a60b57e07e096f00eead6a91', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = 'Foundation for Rural and Regional Renewal: Diversity in Regional Telehealth Bursaries' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Vice-Chancellor\'s Award is a 50% tuition fee scholarship that recognises and supports outstanding academic achievers from specific regions of Asia.', sc.`eligibility` = 'To be considered for this scholarship, applicants must:; be a commencing international student; be enrolling into a bachelor or masters course in 2027; be a citizen of South Asia, Southeast Asia or China; have achieved an average mark of 90% or equivalent in prior studies that are the basis of admission. Federation University reserves the right to assess and determine the equivalency and validity of all academic results and GPA calculations in accordance with its own grading and admissions framework\r\nbe eligible to study in Australia with a valid visa; submit a separate scholarship application and participate in an interview process; meet the additional terms and conditions as set out below.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.federation.edu.au/study/scholarships/details/international/vice-chancellors-award-semester-1-2027/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-award-semester-1-2027/f544becafadefa35876a1f09186b3836', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00103D' AND sc.`scholarship_name` = 'Vice-Chancellor\'s Award (Semester 1 2027)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Excellence Scholarship 2026 has been established to attract high-performing students to study at the University of Newcastle. This scholarship acknowledges applicants with a strong academic background and provides an ongoing incentive for continued academic achievement. Scholarships will be awarded to applicants who receive an offer to study in an eligible program and who commence study with the University in 2026 and beyond.', sc.`eligibility` = 'To be eligible to apply for this scholarship, you will need to:; Be an International student.; Be commencing study in an eligible CRICOS-registered undergraduate or postgraduate coursework degree program at the University.; Not be the beneficiary of a separate University scholarship unless prior approval for special dispensation has been obtained from the university.; Be able to meet the financial obligations of a full fee-paying international student specified by the Australian Government. Evidence of this ability must be provided if requested by the university.', sc.`scholarship_amount` = '20% of gross annual international tuition fee', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.newcastle.edu.au/scholarships/UNI_053', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-excellence-scholarship/8d93cf0c6a83646161fe2ddbaa43a522', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00109J' AND sc.`scholarship_name` = 'International Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This is a donor funded scholarship established from a bequest from the late Margaret Senior to recognize excellence in an Illustration major for a University of Newcastle student. The scholarship will be awarded in March to the student who completed their first year the year prior, with the highest marks in Visual Communication Design with an Illustration major.', sc.`eligibility` = 'Applicants must: Be completing your first year of the Visual Communication Design program with an Illustration major with University of Newcastle.; Be enrolled full-time.; Not be the recipient of another University of Newcastle donor-funded or sponsored scholarship concurrently.', sc.`scholarship_amount` = 'Up to AUD $10000 — This scholarship provides a total benefit of $10,000 for one year. Payment will be made in instalments of $5000 in Semester 1 and 2', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Education and training, Creative arts', sc.`website` = 'http://www.newcastle.edu.au/scholarships/EXT_099', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/natural-history-illustration-scholarship/992338e605095b9bbee3f61c1eee0dc4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00109J' AND sc.`scholarship_name` = 'Natural History Illustration Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Swinburne has been involved in the Australia Awards scholarship program for over 15 years. Currently, there are more than 30 Australia Award students enrolled at the university. The Australia Awards are scholarships funded by the Australian Government that aim to promote knowledge, education links and enduring ties between Australia and its neighbours. They provide opportunities for people from eligible countries to undertake full time undergraduate, postgraduate or TAFE study at Swinburne.', sc.`eligibility` = 'Please contact Swinburne University of Technology for further information.', sc.`scholarship_amount` = 'Australia Awards scholarships are comprehensive and include a number of different benefits and entitlements.\r\n\r\nA full list of entitlements can be found at the Australia Awards website or Australia Awards Scholarship Policy Handbook.\r\n\r\nKey entitleme', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.swinburne.edu.au/study/options/scholarships/338/australia-awards-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarship/f2c66707ab626febfdffd327e7bad9be', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00111D' AND sc.`scholarship_name` = 'Australia Awards Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Aviation Womens Association (IAWA) is a non-profit association with members in 38 countries, representing 257 major companies and aviation authorities. IAWA is dedicated to promoting the advancement of women in the aviation and aerospace industries.', sc.`eligibility` = 'Be an International student, an Australian citizen, a New Zealand Citizen, an Australian permanent resident or holder of a permanent humanitarian visa. Be a female student studying full time in an aviation undergraduate or post graduate course. Submit a personal statement of no more than 500 words outlining your interest and passion for aviation and financial need for the scholarship Submit a referee report outlining leadership quality and community participation.', sc.`scholarship_amount` = 'The scholarship is valued at US$5,000 and a free scholar membership for one year only.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.swinburne.edu.au/study/options/scholarships/385/international-aviation-womens-association--iawa--scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-aviation-womens-association-scholarship/372bb6ce1a6579a3e52f7fac1c4507c7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00111D' AND sc.`scholarship_name` = 'International Aviation Women\'s Association Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Judith Kinnear Student Travel Scholarship supports a postgraduate student in a Masters degree (by Research) or Doctorate degree (PhD) within Swinburne\'s School of Engineering or School of Science, Computing and Emerging Technologies. Named after Dr Judith Kinnear, a Swinburne alum who became the first woman to lead a New Zealand university, the scholarship honours her pioneering career in higher education.', sc.`eligibility` = 'Applicants must be:; a continuing second year and above Swinburne student in Semester 1, 2027; enrolled full-time in a Masters (by Research) or PhD in the School of Science, Computing and Emerging Technologies or School of Engineering.', sc.`scholarship_amount` = 'Up to AUD $5000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.swinburne.edu.au/courses/scholarships/judith-kinnear-student-travel-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/judith-kinnear-student-travel-scholarship-2027/1b6e7ed540397f37ce1e46d52218ed69', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00111D' AND sc.`scholarship_name` = 'Judith Kinnear Student Travel Scholarship 2027' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Research Training Program (RTP) Stipend scholarships are awarded to candidates of exceptional research potential, enrolled in a Higher Degree by Research (HDR) course of study, to assist with general living costs. These scholarships are available to both future and current students enrolled in or applying for a Doctor of Philosophy (PhD) or Professional Doctorate course at Swinburne.', sc.`eligibility` = 'Please refer to the Swinburne Research Stipend Scholarship webpage.', sc.`scholarship_amount` = 'Up to AUD $35499', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.swinburne.edu.au/study/options/scholarships/214/research-training-program-stipend---rtps/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-training-program-stipend-rtp-stipend/a3bfae0c6338f2105d6f5cbc64196b3f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00111D' AND sc.`scholarship_name` = 'Research Training Program Stipend - RTP Stipend' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Stanley Liebich Memorial Scholarship was first established in December 1940, in memory of the late Stanley Ormond Crossley Liebich. This scholarship supports a student from a disadvantaged background enrolled in the Bachelor of Engineering (Honours) degree, who progressed from the Associate Degree in Engineering OR Advanced Diploma of Engineering Technology.', sc.`eligibility` = 'Applicants must:; have progressed from the Associate Degree in Engineering OR Advanced Diploma of Engineering Technology prior to Bachelor of Engineering course.', sc.`scholarship_amount` = 'Up to AUD $7500', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.swinburne.edu.au/courses/scholarships/stanley-liebich-memorial-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/stanley-liebich-memorial-scholarship-2027/cacdf08a6d28eaf16212ac1869ab1339', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00111D' AND sc.`scholarship_name` = 'Stanley Liebich Memorial Scholarship 2027' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Steve Ashton Scholarship for the Architectural Profession (SASAP) honours Steve Ashton, co-founder of Ashton Raggatt McDougall (ARM Architecture). As a career architect, Steve undertook a Graduate Diploma of Business Administration at Swinburne to upskill with what he needed to help operate his business at a high-level and work on prominent urban design projects of the highest architectural quality.', sc.`eligibility` = 'Please contact Swinburne University of Technology for further information.', sc.`scholarship_amount` = 'Up to AUD $30000 — The scholarship is worth up to $30,000 per annum for full-time enrolled recipients for the standard full-time duration of the program, and up to $15,000 per annum for part-time enrolled recipients for the standard part-time. Paymen', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.swinburne.edu.au/study/options/scholarships/519/steve-ashton-scholarship-for-the-architectural-profession--sasap--2025/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/steve-ashton-scholarship-for-the-architectural-profession-sasap-2026/5e70cd389010b29be9b117278f7d67bc', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00111D' AND sc.`scholarship_name` = 'Steve Ashton Scholarship for the Architectural Profession (SASAP) 2026' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Swinburne Research Stipend (SRS) scholarships are awarded to candidates of exceptional research potential undertaking doctoral studies.  The awards are provided to assist with general living costs.   Successful scholarship applicants are automatically awarded a RTP Fees-Offset (Domestic) Scholarship (domestic students) or a Tuition Fee Scholarship (international students) which covers tuition fees for up to four years.', sc.`eligibility` = 'Doctor of Philosophy (PhD), Professional Doctorate', sc.`scholarship_amount` = 'Up to AUD $35000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.swinburne.edu.au/study/options/scholarships/510/swinburne-research-scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/swinburne-research-stipend-scholarships/86afae5be41cded99eb58719f6c6f091', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00111D' AND sc.`scholarship_name` = 'Swinburne Research Stipend Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'SUPRAs are awarded to students of exceptional research potential undertaking doctoral studies. The awards are provided to assist with general living costs. Tuition fees are also covered by the award. SUPRA scholarships are available to both future and current students enrolled in or applying for a Doctor of Philosophy (PhD) or Professional Doctorate course at Swinburne.', sc.`eligibility` = 'meet the entry requirements for a PhD or Professional Doctorate as set out for their proposed program at Swinburne; hold a Bachelor Degree with First Class Honours (or equivalent); propose a research project that aligns with a Swinburne Research Strategy and Ecosystem area; would not be receiving another stipend scholarship to support their general living costs while undertaking their course of study if that stipend is greater than 75 per cent of that student’s RTP Stipend or SUPRA scholarship stipend rate.', sc.`scholarship_amount` = 'Up to AUD $35500', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.swinburne.edu.au/study/options/scholarships/221/swinburne-university-postgraduate-research-award/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/swinburne-university-postgraduate-research-award/f8a39949da8e2614241d8e439e3995c1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00111D' AND sc.`scholarship_name` = 'Swinburne University Postgraduate Research Award' AND sc.`course_id` IS NULL;
