UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Flinders University Alumni Scholarship rewards eligible international graduates of the Universitys undergraduate and postgraduate programs with a 20% full duration scholarship to study another undergraduate or postgraduate degree at Flinders.', sc.`eligibility` = 'Available to alumni of Flinders University only; Full fee-paying international students (citizens of Australia and New Zealand and Australian Permanent Residents or other permanent visa holders are ineligible to apply).; Open to international students of any nationality; Available to applicants of an eligible course as outlined in the Terms and Conditions; Students must meet the entry requirements outline for the scholarship in addition to meeting standard entry requirements including English language requirements, any topic pre-requisites or work experience; Continuing eligibility requires students to maintain a GPA of 4.0 and a full time load of study', sc.`scholarship_amount` = '20% full duration scholarship to study another undergraduate or postgraduate degree at Flinders', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.flinders.edu.au/international/apply/scholarships/alumni', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alumni-scholarships/c7cc3eb1bb94174fc945337f7c08129d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00114A' AND sc.`scholarship_name` = 'Alumni scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = '-', sc.`eligibility` = 'Available to new students only commencing in 2026 and 2027.; Available only to full fee-paying international students from Latin America; There is no separate scholarship application process for the English for Academic Purposes Scholarships. Applications for English for Academic Purposes will automatically be assessed for scholarship eligibility and eligible applicants will be notified within their Letter of Offer to the course. Eligible applicants simply need to return the course Acceptance Form and the LATAM English Excellence Scholarship Acceptance Form for the scholarship to be awarded.', sc.`scholarship_amount` = '30% reduction in tuition fees.; Scholarship value is the percentage reduction specified above.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.flinders.edu.au/content/dam/documents/study/international/flinders-university-academy/english-studies-express-scholarship-terms-and-conditions-2026.pdf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/latam-english-excellence-scholarship-english-for-academic-purposes-eap/8e09d10fe8d31448e3dfcca154d3129f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00114A' AND sc.`scholarship_name` = 'LATAM English Excellence Scholarship  English for Academic Purposes (EAP)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'International students applying for an undergraduate or postgraduate course to study at La Trobe University can be rewarded a bonus grant for completing their admission process early. Recipients will automatically be eligible to receive an Early Bird Acceptance Grant of 5% of the first-year tuition fees.', sc.`eligibility` = 'Be a citizen of a country other than Australia or New Zealand and be applying to study in 2026/2027.; Be a newly offered international student from 1st April 2026.; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored).; Commence their studies at any of the La Trobe University Victorian campuses or Sydney Campus in 2026/2027.; Meet all entry requirements and commence their studies at any of our LTU campuses in Australia.; Students who receive a Conditional Confirmation of Enrolment (COE) will be considered eligible for the grant.; This grant is not available to La Trobe College Australia (LTCA) packaged students (ELICOS, Foundation, and Diploma).; All students who accept up until the deadline, including those who have already accepted, will be eligible for this grant.', sc.`scholarship_amount` = 'Up to AUD $2000 — 5% of the First year Tuition fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/early-bird-acceptance-grant-international-students', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/early-bird-acceptance-grant-international-students/941de33c000219cfb9d766c4cc5f30c4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'Early Bird Acceptance Grant - International Students' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'La Trobe University is offering a number of graduate research scholarship packages consisting of a generous stipend, tuition fee scholarship, and allowances to support outstanding graduate researchers applying for a PhD project. Apply now to join our vibrant research community.', sc.`eligibility` = 'To be eligible to apply for this scholarship, applicants must:; contact the primary supervisor listed against the project, and receive their invitation to submit a full application; meet the entrance requirements for the PhD', sc.`scholarship_amount` = 'AUD $36000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/graduate-research-phd-project-scholarships2', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/graduate-research-phd-project-scholarships/901e20d32d4f2dec6deb276acbaa874d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'Graduate Research PhD Project Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Data is shaping our future, as industries everywhere rely on expert data analysts to make smarter decisions. With a degree in analytics, you\'ll learn to approach complex problems, spot trends, and turn numbers into meaningful insights. From business and healthcare to sports and finance, data drives it all-making this a career path that\'s in high demand. At La Trobe University, with access to world-class teaching and industry connections, you\'ll learn from leading researchers at our Centre for Data Analytics and Cognition (CDAC) and engage with global partners like SAS, Microsoft, PwC, and IBM. You\'ll also have the opportunity to apply for voluntary internships, gaining hands-on experience with top organisations.', sc.`eligibility` = 'To be eligible to apply for this scholarship, applicants must:; Be a new, international student commencing their course on the intake mentioned on their offer letter.; Be a citizen or permanent resident of a country other than Australia or New Zealand; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored); Be eligible for direct entry to the programs.; Meet all course academic and English entry requirements and commence their studies at any of the LTU Victorian and Sydney campuses in 2026/7.; Eligible students will have the scholarship applied to their offer letter, no application required.; All students must have passed the Genuine Student assessment, including financial checks, before they can be considered for this scholarship.; The scholarship may not be deferred to future intakes/years. If the recipient is unable to secure a student visa for that intake, the scholarship offer may be revoked.; Recipients are required to maintain full-time enrolment for the campus in their offer letter and demonstrate satisfactory academic progress throughout their studies.; Please refer to the Offer Letter for full terms and conditions.; Recipients will be required to participate in the International Scholarship Program events during their studies in Australia.; This scholarship can be combined with the Early Acceptance Grant to form a discount on first-year tuition fees. This is subject to all conditions being met for both offers.', sc.`scholarship_amount` = '30% reduction in course fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-analytics-and-insights-scholarship-30', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/la-trobe-analytics-and-insights-scholarship-30/b60dd39d37ecb61c7ac270c70d20b47d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'La Trobe Analytics and Insights Scholarship - 30%' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Data is shaping our future, as industries everywhere rely on expert data analysts to make smarter decisions. With a degree in analytics, you\'ll learn to approach complex problems, spot trends, and turn numbers into meaningful insights. From business and healthcare to sports and finance, data drives it all-making this a career path that\'s in high demand. At La Trobe University, with access to world-class teaching and industry connections, you\'ll learn from leading researchers at our Centre for Data Analytics and Cognition (CDAC) and engage with global partners like SAS, Microsoft, PwC, and IBM. You\'ll also have the opportunity to apply for voluntary internships, gaining hands-on experience with top organisations.', sc.`eligibility` = 'To be eligible to apply for this scholarship, applicants must:; Be a citizen of a country other than Australia or New Zealand.; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored).; Be applying for direct entry into one of the courses listed above. Other students are not eligible.; Commence their studies at any of the La Trobe University campuses in 2026/7.; Meet the University\'s English language requirements and all other conditions stated on the Offer Letter.; Obtain an offer letter before selection for the scholarship. Exceptions must be approved by La Trobe University. All students must have passed Genuine Student assessment, including financial checks before they can be considered for this scholarship.', sc.`scholarship_amount` = 'A reduction of 50 or 100% off the total course tuition fee', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-analytics-and-insights-scholarship-50-and-100', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/la-trobe-analytics-and-insights-scholarship-50-and-100/ab7c24d0e70f8ff2f89c34ba94c1604a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'La Trobe Analytics and Insights Scholarship - 50% and 100%' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'La Trobe University has a bold ambition to transform research, education, and student experience by applying an \'AI-first\' approach, supported by a new partnership with Microsoft Australia and New Zealand and leading cyber security provider CyberCX. Artificial intelligence is one of the most transformative fields in technology today. Revolutionising industries from healthcare to finance, AI is offering solutions to complex problems and creating new possibilities. At La Trobe, our students gain essential skills in programming, data analysis, and machine learning, equipping them to shape the future of technology. As AI continues to evolve, so will the strong demand for artificial intelligence professionals in the public and private sectors, including opportunities in digital healthcare, smart manufacturing, smart cities, sustainable energy infrastructure, precision agriculture and more.', sc.`eligibility` = 'To be eligible to apply for this scholarship, applicants must:; Be a new, international student commencing their course on the intake mentioned on their offer letter.; Be a citizen or permanent resident of a country other than Australia or New Zealand; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored); Be eligible for direct entry to the programs.; Meet all course academic and English entry requirements and commence their studies at any of the LTU Victorian and Sydney campuses in 2026 or 2027.; Eligible students will have the scholarship applied to their offer letter, no application required.; All students must have passed the Genuine Student assessment, including financial checks, before they can be considered for this scholarship.; The scholarship may not be deferred to future intakes/years. If the recipient is unable to secure a student visa for that intake, the scholarship offer may be revoked.; Recipients are required to maintain full-time enrolment for the campus in their offer letter and demonstrate satisfactory academic progress throughout their studies.; Please refer to the Offer Letter for full terms and conditions.; Recipients will be required to participate in the International Scholarship Program events during their studies in Australia.; This scholarship can be combined with the Early Acceptance Grant to form a discount on first-year tuition fees. This is subject to all conditions being met for both offers.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-artificial-intelligence-scholarship-30', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/la-trobe-artificial-intelligence-scholarship-30/54641bb172e9eea398f517e3a0bd0b90', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'La Trobe Artificial Intelligence Scholarship - 30%' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'La Trobe University has a bold ambition to transform research, education, and student support by applying an \'AI-first\' approach, supported by a new partnership with Microsoft Australia and New Zealand and leading cyber security provider CyberCX. Artificial intelligence is one of the most transformative fields in technology today. Revolutionising industries from healthcare to finance, AI is offering solutions to complex problems and creating new possibilities. At La Trobe, our students gain essential skills in programming, data analysis, and machine learning, equipping them to shape the future of technology. As AI continues to evolve, so will the strong demand for artificial intelligence professionals in the public and private sectors, including opportunities in digital healthcare, smart manufacturing, smart cities, sustainable energy infrastructure, precision agriculture and more.', sc.`eligibility` = 'To be eligible to apply for this scholarship, applicants must:; Be a citizen of a country other than Australia or New Zealand.; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored).; Be applying for direct entry into one of the courses listed above. Other students are not eligible.; Commence their studies at any of the La Trobe University campuses in 2026 or 2027.; Meet the University\'s English language requirements and all other conditions stated on the Offer Letter.; Obtain an offer letter before selection for the scholarship. Exceptions must be approved by La Trobe University. All students must have passed Genuine Student assessment, including financial checks before they can be considered for this scholarship.', sc.`scholarship_amount` = 'A reduction of either 50% or 100% off the total course tuition fee.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-artificial-intelligence-scholarship-50-and-100', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/la-trobe-artificial-intelligence-scholarship-50-and-100/6c87299033aab7d272bc19c58291fddd', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'La Trobe Artificial Intelligence Scholarship - 50% and 100%' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'In order to maximize opportunities for students with disabilities to study higher degrees by research, La Trobe University is offering the Flexible Research Scholarship to eligible applicants with disabilities, who already hold a Research Training Program (RTP) stipend or a La Trobe University Graduate Research Scholarship (LTGRS) stipend. This scholarship provides individually tailored support, providing a longer period of time for completion of a graduate research degree and payment of a stipend, extended periods of leave of absence, and provide access to additional funding for research related costs associated with having a disability.', sc.`eligibility` = 'currently be receiving a Research Training Program (RTP) stipend or a La Trobe University Graduate Research Scholarship (LTGRS) stipend, or have accepted an offer of RTP or LTGRS, and have a disability that is attributable to one or more intellectual, cognitive, neurological, sensory, or physical impairments or to one or more impairments attributable to a psychiatric condition; and the impairment or impairments are, or are likely to be, permanent; and (b) the impairment or impairments result in substantially reduced functional capacity to undertake, or psychosocial functioning in undertaking, one or more of the following.', sc.`scholarship_amount` = 'Up to AUD $36000 — Up to 18 month extension to RTP or LTGRS stipend for doctoral candidates and up to 8 month extension for research masters candidates', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-flexible-research-scholarship-flex-candidates-with-disabilities', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/la-trobe-flexible-research-scholarship-flex-candidates-with-disabilities/a3abd641af7c3a05e631571893e6a762', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'La Trobe Flexible Research Scholarship (Flex) - Candidates With Disabilities' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Join a university that\'s in the top 150 Worldwide for Public Health. La Trobe leads in future-focused healthcare with our digital health courses. Students can gain valuable expertise in specialisms such as Big Data analytics, virtual healthcare, Internet of Medical Things (IoMT), cybersecurity, and artificial intelligence. Students get the chance to work on real-world projects with industry partners to graduate job ready whilst gaining an in-demand skill set to design, implement and manage digital health solutions that meet the evolving healthcare needs of individuals and communities.', sc.`eligibility` = 'To be eligible to apply for this scholarship, applicants must:; Be a new, international student commencing their course on the intake mentioned on their offer letter.; Be a citizen or permanent resident of a country other than Australia or New Zealand; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored); Be eligible for direct entry to the programs.; Meet all course academic and English entry requirements and commence their studies at any of the LTU Victorian and Sydney campuses in 2026 and 2027.; Eligible students will have the scholarship applied to their offer letter, no application required.; All students must have passed the Genuine Student assessment, including financial checks, before they can be considered for this scholarship.; The scholarship may not be deferred to future intakes/years. If the recipient is unable to secure a student visa for that intake, the scholarship offer may be revoked.; Recipients are required to maintain full-time enrolment for the campus in their offer letter and demonstrate satisfactory academic progress throughout their studies.; Please refer to the Offer Letter for full terms and conditions.; Recipients will be required to participate in the International Scholarship Program events during their studies in Australia.; This scholarship can be combined with the Early Acceptance Grant to form a discount on first-year tuition fees. This is subject to all conditions being met for both offers.', sc.`scholarship_amount` = '30% reduction in course fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-health-innovation-scholarship-30', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/la-trobe-health-innovation-scholarship-30/d7064ef859ebef05cbe60f4dd9227ed9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'La Trobe Health Innovation Scholarship - 30%' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'La Trobe University values academic excellence. High-achieving international students considering applying for an undergraduate or postgraduate course will be automatically considered for this scholarship. The La Trobe High Achiever Scholarship rewards high achieving International students. This scholarship is worth between 15% to 25% off the annual tuition fees for the duration of studies.', sc.`eligibility` = 'Be a citizen of a country other than Australia or New Zealand and be applying to start an undergraduate or postgraduate coursework program.; Be a new international student commencing their course for any future 2026/2027 intake.', sc.`scholarship_amount` = 'Up to 25% reduction in course fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-high-achiever-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/la-trobe-high-achiever-scholarship/28c2450782780ad9631aceb2df8ec590', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'La Trobe High Achiever Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'La Trobe University recognises the important contribution that people from refugee and asylum seeker backgrounds make to the Australian community.', sc.`eligibility` = 'Please contact La Trobe University for more information about Eligibility', sc.`scholarship_amount` = '100% of tuition fees and $5000 per annum cost-of-living scholarship.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-humanitarian-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/la-trobe-humanitarian-scholarship/20de624aea50da17289927eb517a8f30', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'La Trobe Humanitarian Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'At La Trobe, we recognize and support future leaders who are driven to make a difference. The Vice Chancellor Scholarship is our most prestigious scholarship, awarded to individuals who have excelled not only in their studies but also in extracurricular activities, sports, and community engagement - those who go beyond academics to create real change. This highly competitive scholarship offers either 50% or 100% tuition fee reduction. Through this scholarship, recipients will become part of a vibrant, innovative, and globally connected university, and will be a part of the La Trobe University student ambassador program, where they can develop the skills and networks to shape the future.', sc.`eligibility` = 'Be a citizen of a country other than Australia or New Zealand.; Not be a humanitarian or other permanent visa holder.; Be a full fee-paying student (non-sponsored).; Be applying for direct entry into one of the eligible courses. Other students are not eligible.; Commence their studies at any of the La Trobe University Victorian campuses in 2026 or 2027.; Meet the University\'s English language requirements and all other conditions stated on the Offer Letter.; Obtain an offer letter before selection for the scholarship. Exceptions must be approved by La Trobe University. All students must have passed Genuine Student assessment, including financial checks before they can be considered for this scholarship.', sc.`scholarship_amount` = 'A reduction of either 50% or 100% off the total course tuition fee.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/la-trobe-vice-chancellor-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/la-trobe-vice-chancellor-scholarship/f8384e7eb2ebd35a48f52666b32da611', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'La Trobe Vice Chancellor Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Office of the Provost is offering support to help students undertaking placement with the costs involved in travelling long distances and finding suitable accommodation.', sc.`eligibility` = 'To be eligible to apply for this scholarship, applicants must:; Be currently enrolled in an undergraduate or entry-level to practice course at a La Trobe University Campus. Note: partner institution enrolled students are not eligible for this payment.; Be enrolled in a placement subject and commencing an internship/work placement during one of the above assessment periods. PLEASE NOTE: The placement needs to have commenced during one of the three assessment periods but it does not have to be completed in that period.; Undertaking a placement in a location 120 kms (one way) or more from your semester/term address. Ensure that your semester/term address is current in StudentOnline and InPlace.; Undertaking a single placement greater than 10 days duration and lodged in InPlace at the time of applying. Length of placement is based on subject requirements and does not include make up days. (1 day is considered 8 hours); Not have received any other University-provided funding support related to placements in the 2026 academic year. This does not include the Commonwealth Prac Payment (CPP), which is a living stipend administered by the University on behalf of the Commonwealth Government.', sc.`scholarship_amount` = 'Up to AUD $1365', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/placement-travel-bursary', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/placement-travel-bursary/07179264499d5636ebc6f7f7ac0c353c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'Placement Travel Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Embark on a transformative journey with La Trobe University\'s Study Abroad Scholarship. Wominjeka - meaning "Welcome" and "Come With Purpose" in Woiwurrung, the language of the Wurundjeri people - reflects the spirit of La Trobe and the values we uphold. Guided by this ethos, our scholarships support students from La Trobe\'s partner universities and agents, making global learning more accessible to those who might not otherwise afford it. Rooted in a commitment to social justice, our study abroad program offers transformative experiences - including deep engagement with First Nations knowledge and perspectives.', sc.`eligibility` = 'Be applying through a La Trobe international partner university or authorised agent.; Be willing to take part in a short, non-credit bearing First Nations activity offered by La Trobe, or enrol in an approved credit bearing First Nations unit or be nominated by your home university or education agent as a student from an equity or underrepresented background.; Be applying and eligible for the La Trobe study abroad program (one or two semesters).; Commence their studies at any of the La Trobe University Victorian campuses in either Semester 2 2026, Semester 1 or 2 2027.', sc.`scholarship_amount` = 'A reduction of 25% off the total course tuition fee', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobe.edu.au/study/scholarships/other/wominjeka-study-abroad-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/wominjeka-study-abroad-scholarship/ae3b0a5f031365442163480f555c71eb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00115M' AND sc.`scholarship_name` = 'Wominjeka - Study Abroad Scholarship' AND sc.`course_id` IS NULL;
