UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Mabel Kent Scholarship was established with a gift from Mabel Kent and is offered to students in financial need who are enrolled in a Doctor of Medicine course or studying Music (with a preference for singing).', sc.`eligibility` = 'To be considered for this scholarship, you must: Be enrolled in the Doctor of Medicine course or studying Music (with a preference for voice) at the University of Melbourne, Provide evidence of financial need.', sc.`scholarship_amount` = 'Up to AUD $1500 — The scholarship provides a one-off payment of approximately $1,500 (depending on the income from the gift).', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Medicine', sc.`website` = 'https://scholarships.unimelb.edu.au/awards/mabel-kent-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/mabel-kent-scholarship/155b97aaecd6c443f877edd8eb970b77', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00116K' AND sc.`scholarship_name` = 'Mabel Kent Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Major Bartlett University Scholarships was established by the late James Charles Bartlett, and is offered to microbiology students to assist with travel costs for conferences.', sc.`eligibility` = 'To be considered for this award, you must:; Be a current full time student enrolled in a Research Higher Degree (MPhil and PhD), Honours (BH-BMED or BH-SCI), or Master of Biomedical Science (MC-BMEDSC) through the Department of Microbiology and Immunology.; Use the scholarship in the same year it is awarded. If the applicant is unable to attend the conference, then the scholarship will be withdrawn.; Only apply for one conference at a time.', sc.`scholarship_amount` = 'Up to AUD $200', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.unimelb.edu.au/awards/major-bartlett-university', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/major-bartlett-university-scholarships/a6ad487709cb3ad2c52b630ad462cf79', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00116K' AND sc.`scholarship_name` = 'Major Bartlett University Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Maureen Brunt scholarship is offered to talented graduates of economics and who are undertaking study in an overseas university for a postgraduate degree or diploma in economics or in a field with a major component of economics.', sc.`eligibility` = 'To be considered for this scholarship, you must:; Have completed, or be completing, a degree in Economics at the University of Melbourne in 2026. This includes: BCom students who are majoring in Economics, BCom Honours students who are majoring in Economics, Master of Economics or Master of Commerce (Economics) students, PhD Economics students; Be intending to undertake study in Economics, or in a field with a major component of Economics, at an overseas university for a postgraduate coursework or research degree or diploma.; Have a letter of offer from an overseas institution to commence a postgraduate coursework or research degree in Economics or in a field with a major component of Economics.', sc.`scholarship_amount` = 'Up to AUD $6000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.unimelb.edu.au/awards/maureen-brunt-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/maureen-brunt-scholarship/3a63bacba85fe5452f4f69968c2c134e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00116K' AND sc.`scholarship_name` = 'Maureen Brunt Scholarship' AND sc.`course_id` IS NULL;
