UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Melbourne International Undergraduate Scholarship is offered to high-achieving students who are enrolling in a bachelor degree and are citizens of countries where international educational opportunities are limited by financial disadvantage.', sc.`eligibility` = 'To be considered for this scholarship, you must: Be a citizen of a country with a Gross Domestic Product per capita of US$10,000 or less based on data published by the World Bank. For the complete list of countries, see: Eligible countries. Have applied for and meet the entry requirements for an Overseas Fee place in a bachelor degree. Have completed secondary school outside Australia or a foundation program in Australia. Not have previously undertaken tertiary studies (excluding extension studies completed as part of a year 12 program).', sc.`scholarship_amount` = 'This scholarship provides a 25 per cent fee sponsorship for the duration of the course.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://scholarships.unimelb.edu.au/awards/melbourne-international-undergraduate-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/melbourne-international-undergraduate-scholarship/dc080564845e75c8586f677c13a12a60', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00116K' AND sc.`scholarship_name` = 'Melbourne International Undergraduate Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Mobility Excellence Awards is a suite of scholarships offered to students with outstanding academic and personal qualities who are undertaking overseas study as part of their coursework degree.', sc.`eligibility` = 'To be considered for these awards, students must:; Be enrolled at the University of Melbourne in either an undergraduate degree or a graduate coursework degree; Intend to undertake approved overseas study of 12 weeks or more (Exchange or Study Abroad) as part of your course within 12 months of the closing date; Have achieved a Course Weighted Average of at least 80 in your current course', sc.`scholarship_amount` = 'Up to AUD $8000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.unimelb.edu.au/awards/melbourne-mobility-excellence-awards', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/melbourne-mobility-excellence-awards/57ddbfe0b4926f862c7d0bff9631799c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00116K' AND sc.`scholarship_name` = 'Melbourne Mobility Excellence Awards' AND sc.`course_id` IS NULL;
