UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Peter McMullin Centre on Statelessness (PMCS) welcomes applications from suitably qualified scholars for a place in the Melbourne Law School’s (MLS) PhD program for commencement in 2025. The successful candidate will be working under a supervisory team which will include PMCS academic staff, MLS academic staff affiliated with the Centre, and/or a co-supervisor from another University of Melbourne faculty if appropriate.', sc.`eligibility` = 'Applicants must be eligible for acceptance by the University of Melbourne into a PhD program. This scholarship is conditional upon acceptance into the PhD program at the Melbourne Law School, and the applicants need to meet the entry requirements of the Law School PhD program which can be found here. Applicants must also: have not completed a PhD previously. Be able to commence their PhD in 2025   – with a preferred start date in February 2025.', sc.`scholarship_amount` = 'Up to AUD $122400 — Scholarship recipients undertaking a doctoral degree at the Peter McMullin Centre on Statelessness will be awarded: Full fee offset for up to four years. An annual stipend of AUD $38,500 (tax free) (2025 full-time study rate). The', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://law.unimelb.edu.au/centres/statelessness/research/graduate-research/phd-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/peter-mcmullin-centre-on-statelessness-phd-scholarship/ad6fb5db3579a93c96814b686ab8f022', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00116K' AND sc.`scholarship_name` = 'Peter McMullin Centre on Statelessness PhD Scholarship' AND sc.`course_id` IS NULL;
