UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Warren Clark Agricultural Research Scholarship was established with a gift from Warren Clark and is offered to students who are enrolled in the Doctor of Philosophy – Science in Agricultural Sciences and are experiencing financial need.', sc.`eligibility` = 'Be enrolled in the Doctor of Philosophy (Science) (or its successor); Be undertaking research in the field of Agricultural Science; Have met the requirements for confirmation of your candidature.', sc.`scholarship_amount` = 'Up to AUD $5000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.unimelb.edu.au/awards/warren-clark-agricultural-research-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/warren-clark-agricultural-research-scholarship/a0add46eb76d4f56184d5852e69b7470', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00116K' AND sc.`scholarship_name` = 'Warren Clark Agricultural Research Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Wilfred Prest Travelling Fellowship is open to students or graduates of the Faculty of Business and Economics who will undertake postgraduate studies in the field of Economics at an overseas university or research institution.', sc.`eligibility` = 'To be considered for this fellowship, you must:; be completing a degree in the Faculty of Business and Economics (Bachelor, Honours, Master or PhD) in 2026 specialising in Economics or have previously completed a degree from FBE specialising in Economics (Bachelor, Honours, Master or PhD); be undertaking or intending to undertake postgraduate studies in Economics at an overseas university or research institution in 2027.; be no more than 27 years of age at the time of the award', sc.`scholarship_amount` = 'Up to AUD $16000 — Each fellowship is paid in two equal instalments: the first upon acceptance of the scholarship and evidence of full-time enrolment at the overseas university or research institution, and the second upon evidence of continued full-t', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Economics', sc.`website` = 'https://scholarships.unimelb.edu.au/awards/wilfred-prest-travelling-fellowship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/wilfred-prest-travelling-fellowship/69f79b0ca139be60c622e30687383798', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00116K' AND sc.`scholarship_name` = 'Wilfred Prest Travelling Fellowship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The William Bardsley Award is offered to students who are enrolled in the Bachelor of Music or Master of Music specialising in violin performance and are experiencing financial need.', sc.`eligibility` = 'To be considered, you must be enrolled in either the Bachelor of Music or Master of Music (or their successors) specialising in violin performance.', sc.`scholarship_amount` = 'Up to AUD $800', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.unimelb.edu.au/awards/w-bardsley-award', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/william-bardsley-award/7d59f051f5a89b43409a153a8980a219', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00116K' AND sc.`scholarship_name` = 'William Bardsley Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Australia Awards Scholarships are long-term awards administered by the Australian Department of Foreign Affairs and Trade that aim to contribute to the development needs of Australia\'s partner countries in line with bilateral and regional agreements.\r\n\r\nThe Scholarships provide opportunities for people from developing countries, particularly those countries located in the Indo-Pacific region, to undertake full time undergraduate or postgraduate study at participating Australian institutions. Since 1997, James Cook University has provided quality academic and personal support to over many hundreds of Australia Awards Scholarship students from more than 40 countries.\r\n\r\nAustralia Awards Scholarships are offered for the minimum period necessary for the individual to complete the academic program specified by the Australian higher education institution, including any preparatory training and generally cover tuition fees, air travel, and allowances to cover accommodation expenses, text books, study materials and basic living expenses.', sc.`eligibility` = 'Please contact James Cook University (JCU) for further information.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.jcu.edu.au/international-students/scholarships-and-financial-aid/australia-awards-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarships/51eb9820e1460f50a3e7fb9216c01fe0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00117J' AND sc.`scholarship_name` = 'Australia Awards Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The JCU International Excellence Scholarship provides a 25% tuition fee reduction throughout the entire duration of approved full degree study programs, provided recipients maintain a strong GPA each semester.\r\n\r\nScholarship eligibility is automatically assessed during the JCU admissions process. Eligible candidates will receive an offer for their program of study and the International Excellence Scholarship concurrently.', sc.`eligibility` = 'Please contact James Cook University (JCU) for further information.', sc.`scholarship_amount` = '25% off tuition fee', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.jcu.edu.au/scholarships/search/international-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-excellence-scholarship/83ebdbdb6eb9cce0c94f63152a528998', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00117J' AND sc.`scholarship_name` = 'International Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Established in 1975 from a bequest from the estate of the late Dr Robert Logan, Senior Lecturer in Biochemistry at the University from 1968 to 1973, the income derived from the bequest maintains the awards.', sc.`eligibility` = 'The Robert Logan Memorial Grant shall be open to candidates who:; are full time or part time Honours or postgraduate students in the discipline of Biochemistry at James Cook University and; have not previously received this grant during their current course of study.', sc.`scholarship_amount` = 'AUD $14000/year — The value of the travelling and research grant will be determined by the Selection Committee (up to $14,000 annually). The grant will provide assistance to honours and post-graduate students in The Academy conducting research in the', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.jcu.edu.au/scholarships/search/robert-logan-memorial-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/robert-logan-memorial-grant/844b85973c6fa96f213729c9cdf392e7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00117J' AND sc.`scholarship_name` = 'Robert Logan Memorial Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The original Cook family migrated from England to Australia in 1837. 75 years later Tom\'s father purchased land in Mackay and in 1915 built a family home, which is currently known as Greenmount Homestead. In 1950 Tom Cook wed Dorothy Drysdale, a successful businesswoman, owning and running a ladies\' fashion and beauty shop in Brisbane. Tom and Dorothy settled at the Mackay residence, where they lived for most of their 31-year marriage. The passing of Tom and Dorothy in 1981 and 1995 respectively ended eighty years of the Cook family residing at Greenmount.  In 1984, Dorothy gifted the homestead to the Mackay Regional Council. Dorothy left a final gift to the community of Mackay in the form of a research scholarship at James Cook University. These scholarships are offered to higher degree research students to undertake a Master of Philosophy or Doctor of Philosophy in the field of public health, laboratory and clinical investigation of population health in Tropical Northern Australia.', sc.`eligibility` = 'The Tom and Dorothy Cook scholarships in Public Health and Tropical Medicine will be open to competition among candidates who:; Are commencing, or in the process of applying for, a Master of Philosophy (MPhil) or Doctor of Philosophy (PhD) at JCU; Have a primary or secondary supervisor based in JCU’s Discipline of Public Health; Have a research project related to public health, laboratory and clinical investigations of population health; An significant element of the research project focusses on the Mackay and central Queensland region and; Meet JCU\'s admission requirements for MPhil or PhD degree.', sc.`scholarship_amount` = 'Up to AUD $117250', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.jcu.edu.au/scholarships/search/tom-and-dorothy-cook-scholarships-in-tropical-health', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/tom-and-dorothy-cook-scholarships-in-public-health-and-tropical-medicine/800dbb48474d353f52ce17fac4fed414', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00117J' AND sc.`scholarship_name` = 'Tom and Dorothy Cook Scholarships in Public Health and Tropical Medicine' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The ANU Fenner School of Environment and Society (FSES) within the ANU College of Systems and Society and the ANU Research School of Earth Sciences (RSES) within the ANU College of Science and Medicine may offer a number of awards known as the Action Trust Scholarship. The objective of the Award is to support students undertaking an honours project that advances knowledge and practice in areas relating to the interest of the ACTION Trust and/or to the environment and sustainability.', sc.`eligibility` = 'The scholarship is available to a commencing or continuing ANU student who:; is a domestic or international student;  receives an offer of admission or is currently enrolled in an eligible honours program at either the ANU Fenner School of Environment and Society or the ANU Research School of Earth Sciences; has an overall career GPA of 5.0 or higher.', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/action-trust-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/action-trust-scholarship/3285f99b1341f5385ca98a404d349d6a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ACTION Trust Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the College of Arts and Social Sciences may offer up to 10 College of Arts and Social Sciences Honours Scholarship with the aim of recruiting high calibre students into the Colleges Honours programs.', sc.`eligibility` = 'The award is available each year to a prospective or current ANU student who is enrolled in a full-time Honours program offered by the College, or receives an offer of admission to a full-time Honours program offered by the College.', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-college-arts-social-sciences-honours-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-college-of-arts-social-sciences-honours-scholarship/d0ba227992e70b8f5278aa775c8dff86', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU College of Arts & Social Sciences Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the ANU College of Arts and Social Sciences (the College) may offer up to 10 awards known as the ANU College of Arts and Social Sciences Academic Excellence Masters Scholarship (the Award). The award is available to international students who have been offered admission to a Master or Master Advanced program by the College.\r\nThe objective of the Award is to support, enable and encourage international students to undertake studies in the arts, humanities or social sciences at the ANU College of Arts and Social Sciences. Funding for this Award has been provided by ANU College of Arts and Social Sciences.', sc.`eligibility` = 'is an international student; is a citizen of one of the countries published on the scholarships webpage (as updated annually); receives an offer of admission to a Master or Master Advanced program (excluding the Master of Studies/Master of Studies Advanced) at the ANU College of Arts and Social Sciences.', sc.`scholarship_amount` = 'AUD $20000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-college-arts-and-social-sciences-academic-excellence-masters', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-college-of-arts-and-social-sciences-academic-excellence-masters-scholarship/cc8253befee5a5d578f8e289821a9e25', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU College of Arts and Social Sciences Academic Excellence Masters Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the ANU College of Law may offer a number of awards known as the ANU College of Law International Partners Scholarship with the aim of attracting and supporting top quality international postgraduate students to the ANU College of Law.', sc.`eligibility` = 'is an International student; has applied for admission to the Master of Laws (LLM) program at the ANU College of Law; has achieved a minimum GPA of 5.0 out of 7.0 (or equivalent) in their relevant undergraduate degree; has graduated from a law program or will have graduated by the time of taking up the scholarship from one of the following Universities:; Peking University - Beijing, China; University of Tokyo - Japan; has been shortlisted by one of the above Universities.', sc.`scholarship_amount` = '100% fee waiver of tuition for one year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-college-law-international-partners-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-college-of-law-international-partners-scholarship/b9e2efdebcae612e80e6cd0ed8cbec07', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU College of Law International Partners Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the ANU Fenner School of Environment and Society, in the ANU College of Science, may offer one or more awards known as the Fenner School of Environment & Society PhD Scholarship. The objective of the award is to attract the highest calibre international and domestic students to pursue postgraduate research for a PhD degree within the Fenner School. Funding for this award is provided by the Fenner School.', sc.`eligibility` = 'either a domestic or an international student; enrolling full-time in a program of study for the degree of Doctor of Philosophy, in the Fenner School of Environment & Society, at the Australian National University.', sc.`scholarship_amount` = 'AUD $34000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-fenner-school-environment-society-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-fenner-school-of-environment-society-phd-scholarship/ecd8a275f8b45398de1391f4e5cad6c2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU Fenner School of Environment & Society PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Australian National University offers the ANU HDR Fee Merit Scholarship (concurrently with the ANU University Research Scholarship) to support high achieving international HDR students who are conducting research which aligns with the strategic directions of the University.', sc.`eligibility` = 'is an international student enrolling in an accredited HDR course of study at the University; has also been awarded an ANU University Research Scholarship; has achieved a minimum of Honours 1 (H1) or H1 equivalent in their prior studies.', sc.`scholarship_amount` = 'Covers International Student Fees (ISF) and full OSHC, including family cover (for students on a Student Visa Subclass 500 only)', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-hdr-fee-merit-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-hdr-fee-merit-scholarship/053447c50cae21bc66c98ad58de8895c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU HDR Fee Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A Supplementary scholarship may be awarded to a student to top up a HDR base stipend scholarship offered by the ANU to assist with living costs or research expenses.', sc.`eligibility` = 'Students enrolled in a research program who hold a base stipend scholarship.', sc.`scholarship_amount` = 'Scholarship value : Variable', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-hdr-supplementary-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-hdr-supplementary-scholarship/1e864b6fb6c1562826d8bb5026e07447', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU HDR Supplementary Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Australian National University (ANU) (\'the University\') may offer a number of awards known as the ANU International Achievement Award (\'the Award\'). The objective of the Award is to attract a diverse range of academically capable overseas students to enrol in undergraduate and postgraduate coursework programs offered by the University.', sc.`eligibility` = 'The Award is available to an ANU student who:; is an international student; is a new commencing student or a continuing student who has received an offer of admission to a higher AQF level of studies; holds residential status in a country that is not listed as eligible for the ANU Vice-Chancellor’s International Achievement award as detailed on the ANU Scholarships website; meets the minimum academic entry requirements', sc.`scholarship_amount` = '20%, 25% or 50% off tuition fees for up to 4 years.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-international-achievement-award', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-international-achievement-award/51e736583aea338650fdb4b1eb765852', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU International Achievement Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the ANU College of Law, Governance and Policy may offer a number of awards known as the ANU Law Careers and Employability Travel Grant. The objective of the Award is to financially support College students when undertaking an ANU College of Law, Governance and Policy Careers and Employability program or initiative. Funding for this Award has been provided by the ANU College of Law, Governance and Policy.', sc.`eligibility` = 'The Award is available each year to a continuing ANU student who (at the time of application):; is a domestic or international student; Bachelor of Laws (Honours) as a single or Flexible Double Degree (FDD Law); Juris Doctor; Master of Laws; Master of International Law and Diplomacy; Master of Financial Management and Law; etc', sc.`scholarship_amount` = 'AUD $4000/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-law-careers-and-employability-travel-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-law-careers-and-employability-travel-grant/6a4a8c1b4b46028f438b15247b39e2c1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU Law Careers and Employability Travel Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This is a stipend scholarship offered by ANU Colleges to Master of Philosophy (MPhil) candidates. It is normal for recipients to undertake study on a full-time basis, however, in accordance with strict criteria, the scholarship can be awarded for part-time study for Domestic candidates only. International scholars must undertake study on a full-time basis.', sc.`eligibility` = 'are domestic or international students; have applied for admission to a Master of Philosophy (MPhil) program; have a Bachelor degree with first-class honours (some Colleges may consider students with upper second-class honours), or a Master degree with a research component or equivalent from a recognised university.', sc.`scholarship_amount` = 'AUD $36652/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-master-philosophy-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-master-of-philosophy-scholarship/e4fc01949c99bab880329f88f25234b2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU Master of Philosophy Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This is a stipend scholarship offered by ANU Colleges to Higher Degree by Research candidates. It is normal for recipients to undertake study on a full-time basis, however, in accordance with strict criteria, the scholarship can be awarded for part-time study for Domestic candidates only. International scholars must undertake study on a full-time basis.', sc.`eligibility` = 'are domestic or international students; have applied for admission to a PhD or Professional Doctorate by Research program; have a Bachelor degree with first-class honours (some Colleges may consider students with upper second-class honours), or a Master degree with a research component or equivalent from a recognized university.', sc.`scholarship_amount` = 'AUD $36652/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-phd-scholarship/ed903fe76353475031888e5a213ebaec', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Project 89 is an initiative of the Vietnamese government which aims to build capacity and academic training for Vietnamese university lecturers and executives. Its implementation is supported by the Australian government.', sc.`eligibility` = 'Continuation based on academic performance', sc.`scholarship_amount` = 'AUD $39069/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-project-89-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-project-89-phd-scholarship/b65034f01de8706474bf2c8773dfb11b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU Project 89 PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Australian National University (ANU) (\'the University\') may offer a number of awards known as the ANU Vice-Chancellor\'s International Achievement Award (\'the Award\').\r\nThe objective of the Award is to attract a diverse range of academically capable overseas students to enrol in undergraduate and postgraduate coursework programs offered by the University.  Funding for this Award is provided by the Australian National University.', sc.`eligibility` = 'The Award is available to an ANU student who:; is an international student; is a new commencing student or a continuing student who has received an offer of admission to a higher AQF level of studies; holds residential status in one of the following Countries or Regions:; China (including Taiwan, Hong Kong SAR and Macau SAR); Japan; Mongolia; The Democratic People\'s Republic of Korea', sc.`scholarship_amount` = '20% off your first-year tuition fees.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-vice-chancellors-international-achievement-award', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-vice-chancellors-international-achievement-award/d95e76f144fad05183a8ebfb888d502e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU Vice-Chancellor\'s International Achievement Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The China Scholarship Council (CSC) is a non-profit institution affiliated with the People\'s Republic of China (PRC) Ministry of Education. CSC is responsible for the organization, management and provision of financial resources for Chinese citizens studying abroad, and to international students studying in China. CSC and ANU have established the China Scholarship Council - Australian National University Joint Funding Program to provide research opportunities to high quality research students and scholars from the PRC.\r\nThrough this program, selected PRC students may be offered an ANU-CSC Postgraduate (PhD) Scholarship for a maximum of 48 months. Visiting scholars, postdoctoral fellows and PhD students from the PRC may also be provided funding to conduct research at ANU for a maximum of one or two years.', sc.`eligibility` = 'Be a citizen and permanent resident of the PRC at the time of application; Meet all ANU admissions entry requirements including the English proficiency requirement, and receive either an unconditional offer of a place in an ANU PhD program, or an offer conditional on completion of their current program; Be selected by their ANU College or Research School for an HDR Fee Remission Merit Scholarship; Be eligible to receive an Australian student visa; Return to China at the end of the period of study; Satisfy other selection criteria set out by the China Scholarship Council.', sc.`scholarship_amount` = 'Full tuition and stipend', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anu-csc-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anu-csc-scholarship/0885c2b0c69f709a1f6a33c44eedfc9d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'ANU-CSC Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Fenner School of Environment & Society may offer an award known as the Alan and Helen Ross Forestry Education Scholarship. The objective of the Award is to support a Papua New Guinea (PNG) citizen with interests and experience in PNG forests and forestry to study a graduate coursework program in forests. Funding for this Award has been provided by the Alan and Helen Ross Forestry Education Scholarship Trust. The Trust honours the life and work of Alan and Helen Ross, longtime residents of PNG who were deeply committed to its future. Alan was a highly respected figure in forestry in PNG, mentoring many of his PNG colleagues.', sc.`eligibility` = 'The Award is available  to a commencing ANU student who:; is an international student visa holder with PNG citizenship; holds an undergraduate qualification in forestry or a related discipline; or, in exceptional cases, does not hold such a qualification but possesses equivalent extensive professional experience in forestry; receives an offer of admission to one of the following programs: Master of Forests; Graduate Diploma in Science; Graduate Certificate in Forests', sc.`scholarship_amount` = 'Up to AUD $100000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/alan-and-helen-ross-forestry-education-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alan-and-helen-ross-forestry-education-scholarship/f592658ec411c575e38945d8cd1be42e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Alan and Helen Ross Forestry Education Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Astronomy & Astrophysics (RSAA) may offer approximately two awards known as the Alex Rodgers Travel Grant (the Award). Funding for this Award has been made possible due to an endowment from Mrs Ruth Rodgers in memory of her late husband Professor Alexander Rodgers. Professor Rodgers was a distinguished academic in the field of stellar astronomy and globular clusters, serving as School Director from 1987 to 1992. Professor Rodgers most significant contribution to the field was his involvement in the MACHO project, an international search for dark matter. The objective of the Award is to assist a student currently enrolled in the Doctor of Philosophy in Astronomy & Astrophysics to travel abroad to attend scientific meetings and/or to work with astronomers at another institution on some chosen research project of direct relevance to the thesis work being undertaken.', sc.`eligibility` = 'Full-time current RSAA PhD student. A successful applicant is ineligible to apply again. Australian and New Zealand citizens; Permanent residents of Australia; International students.', sc.`scholarship_amount` = 'Up to AUD $5000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/alex-rodgers-travel-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alex-rodgers-travel-grant/898d36dc5370faa5992925510361d621', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Alex Rodgers Travel Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the John Curtin School of Medical Research (JCSMR) within the ANU College of Science and Medicine at the Australian National University (ANU) may offer an award known as the Alexander McTaggart Memorial Scholarship.  The objective of the Award is to support a student undertaking their Honours project at the John Curtin School of Medical Research, with the research to be conducted in a field related to cancer research and allied subjects.  Funding for this Award has been provided in the memory of its donor, Mr Alexander McTaggart.', sc.`eligibility` = 'The scholarship is available to an applicant:; who is an international or domestic student; who is enrolled in an Honours year at the John Curtin School of Medical Research; whose Honours project is related to cancer research and allied fields.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/alexander-mctaggart-honours-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alexander-mctaggart-honours-scholarship/eb3ec6dd7146767e1aa264422a47197e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Alexander McTaggart Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The American Australian Association (AAA) established its Veterans\' Fund in 2017 to provide much needed financial support and assistance to Australian and American honorably discharged post-9/11 military veterans to pursue study in each other\'s countries respectively. With more than 40 veteran scholars and alumni and US $1.5 million awarded to date, the AAA is committed to investing in the future of veterans by supporting educational opportunities which build new skills and create prosperous post-military careers.', sc.`eligibility` = 'Please Contact ANU for more information about Eligibility.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/american-australian-association-veterans-fund', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/american-australian-association-veterans-fund/c897a3af92900b6813763df86b1034d4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'American Australian Association Veterans\' Fund' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This Scholarship is offered by the ANU College of Science and commemorates the life of Anjeli Nathan, a brilliant student who, tragically, was killed doing the field research she loved. The scholarship may be used to assist the student either to undertake the Honours Program or to gain fieldwork experience after the successful completion of the degree with Honours.', sc.`eligibility` = 'an outstanding applicant who has been accepted to study behavioural ecology or conservation biology for an Honours Program within The Australian National University; an outstanding applicant who is within 12 months, as at the closing date, of having completed the degree of Bachelor of Science with Honours at The Australian National University.; Projects involving long-term captivity, killing or surgery on animals will not be considered.; Preference will be given to applicants based or co-supervised in the Division of Ecology, Evolution and Genetics during their Honours year.', sc.`scholarship_amount` = 'AUD $7000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/anjeli-nathan-memorial-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/anjeli-nathan-memorial-scholarship/bcbba1e6e9a917747a872c91c41ae86f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Anjeli Nathan Memorial Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Commonwealth Department of Education and Training provides funding to Universities to award scholarships to domestic and international students undertaking Higher Degree Research programs. ANU currently conducts two annual central scholarship rounds which includes the RTP, the University Research Scholarship and a few other centrally managed scholarships.', sc.`eligibility` = 'Continuation based on academic performance', sc.`scholarship_amount` = 'AUD $40475/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/australian-government-research-training-program-rtp-stipend', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australian-government-research-training-program-rtp-stipend-scholarship/359f56e62eeff08e6f57c9bb302c1a27', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Australian Government Research Training Program (RTP) Stipend Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This award is available to a HDR student studying at the National Centre for Epidemiology and Population Health (NCEPH) to assist with travel to a national or international conference, in pursuit of their academic goals.', sc.`eligibility` = 'The Award will be available each year to a continuing domestic or international HDR student who is enrolled in a program of study at NCEPH for the degree of Doctor of Philosophy or Master of Philosophy. Students who have previously received the award are not eligible to apply again, except in exceptional circumstances.', sc.`scholarship_amount` = 'AUD $1500/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/baume-hdr-travel-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/baume-hdr-travel-grant/9e5a20986b5edbbc09823f5f52777e55', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Baume HDR Travel Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This Grant is offered by the Research School of Physics in the ANU College of Science. The Grant will aid students who are experiencing special difficulties and require financial assistance to continue and/or to complete their studies.', sc.`eligibility` = 'is an international or domestic student; is experiencing special difficulties and require financial assistance to continue and/or to complete their studies. Such cases as, but not exclusively related to, mental illness, disability, extended sickness or family issues are examples of those that may qualify for assistance; is enrolled in either an undergraduate or postgraduate program offered by the Research School of Physics, such as Honours program in Physics, Bachelor of Philosophy (majoring in Physics), Bachelor of Science (majoring in Physics), Master of Nuclear Science, Master of Photonics, Master of Philosophy (specialising in Physics) and Doctor of Philosophy (specialising in Physics).', sc.`scholarship_amount` = '$14,000 per annum which maybe shared among multiple recipients', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/ben-williams-student-support-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ben-williams-student-support-grant/9e794529879ddc33e57b1b2be91100a1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Ben Williams Student Support Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This annual grant is offered by the College of Asia and the Pacific but open to students of all Colleges at the Australian National University. It is funded in perpetuity by the Bhati Family Endowment to foster regional interconnectedness and encourage talented students to build mutually beneficial relationships between Australia and India. The grant will assist current ANU students from any discipline who need to travel to India for their research. The aim of the grant is to help create a better understanding and knowledge of Australia in India and/or a better understanding and knowledge of India in Australia.', sc.`eligibility` = 'The recipient must be enrolled and remain enrolled at ANU while the travel is being undertaken; Travel to India is vital for research and output of research will contribute to the aim of the grant.; The applicant has obtained approval of his/ her supervisor and has established a link with an institution in India.; For details on these and additional selection criteria, see section 5 of the Conditions of Award (see reference document). https://d3gu8jtw4r0om.cloudfront.net/files/2024-03/Bhati%20Family%20India%20Travel%20Grant%20-%20Revised%20CoA%20for%202018%20-%20Final.pdf', sc.`scholarship_amount` = 'AUD $3500/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/bhati-family-india-travel-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/bhati-family-india-travel-grant/7b5ccd5e8d3d40a32f4e8d1a7ce972d9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Bhati Family India Travel Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the Research School of Astronomy and Astrophysics (RSAA) in the ANU College of Science may offer an award known as the Bok Honours Year Scholarship in Astrophysics. The objective of the award is to support students with an outstanding academic record to undertake their Honours year in Astronomy and Astrophysics with the Research School of Astronomy and Astrophysics in the ANU College of Science. The Scholarship is offered in honour of the late Professor Bart J. Bok, a former Director of the Mount Stromlo and Siding Spring Observatories from 1957 to 1966 and Professor of Astronomy at the Australian National University.', sc.`eligibility` = 'is a domestic or international student; is enrolled/enrolling in the Astronomy and Astrophysics Honours Year within the Research School of Astronomy and Astrophysics in the ANU College of Science.', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/bok-honours-year-scholarship-astrophysics', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/bok-honours-year-scholarship-in-astrophysics/e03aa27ed12a34c8e48c175508efeeb3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Bok Honours Year Scholarship in Astrophysics' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the School of Literature, Languages and Linguistics, ANU College of Arts and Social Sciences (\'the School\') may offer an award/s known as the Brynrefail Honours Grant for Classical Studies (\'the Award\'). The objective of the Award is to support Honours students in Classical Studies, including the study of Ancient Greek and Latin, and to inspire them to undertake additional research and study in this field. Funding for this Award has been provided by the Lord Mayor\'s Charitable Foundation, one of Australia\'s leading philanthropic organisations.', sc.`eligibility` = 'The Award is available each year to a commencing or continuing ANU student who:; is a domestic or international student; receives an offer of admission to an Honours program in the field of Classical Studies at the College of Arts and Social Sciences.', sc.`scholarship_amount` = 'AUD $3000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/brynrefail-honours-grant-classical-studies', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/brynrefail-honours-grant-for-classical-studies/71f2d1440cd73d4d1a806922bce7842d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Brynrefail Honours Grant for Classical Studies' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Centre in Critical Resources for the Future (CCRF) are offering TWO PhD scholarships in partnership with the Australian National University (ANU). These opportunities are ideal for highly motivated graduates interested in: Partitioning of REE and CM between crystals melts, and fluids and in situ XAS studies of metal transport. (led by Andrew Berry); Experimental investigations of the magmatic-hydrothermal transition in carbonatites and the factors controlling REE and CM enrichment. (Led by Prof Greg Yaxley)', sc.`eligibility` = 'Have applied for admission to the PhD program with the Research School of Earth Science; Have a Bachelor degree with first-class honours, or a Master degree with a research component, or equivalent from a recognised University.', sc.`scholarship_amount` = 'AUD $36652/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/centre-critical-resources-future-ccrf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/centre-for-critical-resources-for-the-future-ccrf/2ec88c7099b3aa0e90bb63ab513b3eae', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Centre for Critical Resources for the Future (CCRF)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the Research School of Earth Sciences (RSES) within the College of Science and Medicine and Fenner School of Environment and Society (FSES) within the College of Systems and Society may offer a number of awards known as the Centre of Excellence for the Weather of the 21st Century Research Grant. The objective of the Award is to encourage students to undertake a research project in climate, weather, or related fields. Funding for this Award has been provided by ARC Centre of Excellence for the Weather of the 21st Century.', sc.`eligibility` = 'The Award is available each year to a commencing or continuing ANU student who:; is a domestic student or international student; receives an offer of admission to an Honours program offered by RSES/FSES; has a career GPA of 6 or higher.', sc.`scholarship_amount` = 'AUD $7500/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/centre-excellence-weather-21st-century-research-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/centre-of-excellence-for-the-weather-of-the-21st-century-research-grant/15f7b2343bb62c1cb193c936cf280ce9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Centre of Excellence for the Weather of the 21st Century Research Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Once every three years the Research School of Earth Sciences may offer a PhD scholarship known as the Chappell and White PhD Scholarship (the Award). The objective of the Award is to support high achieving domestic and international PhD students who are conducting research in the areas of petrology and ore petrology. Funding for this Award has been provided by Professor Bruce Chappell and Professor Allan White. Professor Bruce Chappells career at ANU spanned more than 30 years, from 1960 to 1997. In 1967 he graduated with an ANU PhD and was awarded an ANU DSC in 1990. His sustained research contributions were recognised with many international awards including election to Fellowship of the Australian Academy of Science. Professor Allan White was a member of the Geology Department at ANU from 1960 to 1971. He was an undergraduate student of the famous Australian geologist and Antarctic explorer, Professor Sir Douglas Mawson. White left ANU to establish the Department of Geology at La Trobe University.', sc.`eligibility` = 'a domestic and/or international student; enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy in Earth Sciences and are conducting research in the areas of petrology and ore petrology at the University; holds a Bachelor degree with first-class honours, or a Master degree with a research component or equivalent from a recognized university.', sc.`scholarship_amount` = 'AUD $34000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/chappell-and-white-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/chappell-and-white-phd-scholarship/489462620ae9328c44267de6029f022c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Chappell and White PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Professor Chris Heyde and Professor Joe Gani were well known and well regarded amongst their colleagues for their substantial contribution to many areas of Probability, Statistics and Stochastic Analysis during their lifetime.  To honour their memory, the Chris Heyde & Joe Gani Scholarship has been established at the ANU to enable students to study and expand research into these fields. The Scholarships are funded by the interest on contributions from friends, colleagues, family and the ANU Endowment for Excellence.  Two Scholarships will be offered annually subject to funds beings available.', sc.`eligibility` = 'a domestic and/or international student; enrolled in a program of study leading to the award of a PhD; undertaking research in areas of probability, statistical science or stochastic analysis.', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/chris-heyde-joe-gani-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/chris-heyde-joe-gani-scholarship/c2d3df04317cc1c0a67b5d6efb4fe340', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Chris Heyde & Joe Gani Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Clark Davis Ivins Memorial Endowment in 2014 by the family of Private Clark Davis Ivins, an Australian soldier who died during World War II. He was just 24-years-old when he died of wounds received at the Battle of Milne Bay in Papua New Guinea in 1942.  His life may have been a short one, but the part he played in the Battle of Milne Bay, a battle that was the first Japanese defeat on land in the Pacific War, is one that certainly made a difference to the lives of many Australians, both young and old, today.  To commemorate the 75th Anniversary of the Battle of Milne Bay in 2017, the Endowment was expanded to offer the Clark Davis Ivins Memorial Travel Grant.', sc.`eligibility` = 'a domestic or international student; enrolled in a Bachelor of International Security Studies; participating in a Global Learning Program offered by the ANU', sc.`scholarship_amount` = 'Variable once off payment. The value of the award is stated in your letter of offer. The award will be paid in a single instalment prior to the recipients travel departure, unless otherwise stated in the letter of offer.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/clark-davis-ivins-memorial-travel-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/clark-davis-ivins-memorial-travel-grant/e60e8780cdddb68ad3b798b9033ad621', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Clark Davis Ivins Memorial Travel Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Funding for this Award has been provided by the John Anthony Deakin Endowment.', sc.`eligibility` = 'Domestic or International; Prospective or continuing; Enrolled or enrolling in a program of study for the degree of Doctor of Philosophy at the Australian National University; Has been awarded a Bachelor degree with first class honours, or a Master degree with a research component, or equivalent from a recognised University', sc.`scholarship_amount` = 'AUD $36652/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/deakin-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/deakin-phd-scholarship/bb815be91fcdf32fa1b22717b810736b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Deakin PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Deans International Science Excellence Scholarship is jointly offered by ANU College of Science and ANU College of Health & Medicine. It is a prestigious scholarship awarded to the very best international students from the Colleges institutional partners.', sc.`eligibility` = 'an international student. Dependents of the staff of diplomatic or consular missions are also eligible; undertaking undergraduate or postgraduate studies at an institute which has an articulation agreement with the Colleges. Click here for the list of the Colleges articulation partners; enrolling at ANU for the first time in an undergraduate or postgraduate coursework program in the Colleges.', sc.`scholarship_amount` = 'AUD $5000/year — Once-off payment for full value', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/deans-international-science-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/deans-international-science-excellence-scholarship/5cbc11b28fb63a93bfb68b5652ba03f7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Dean\'s International Science Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the John Curtin School of Medical Research (JCSMR) in the ANU College of Health and Medicine may offer an award known as the Dewar Milne Prize in Immunology.\r\nFunding for this Award has been provided by John Dewar Milne, a graduate of the ANU. The objective of the prize is to acknowledge a high-achieving research candidate who has carried out the most significant piece of research during their doctoral candidature, whilst enrolled in a PhD program based in the College of Health and Medicine.', sc.`eligibility` = 'The Award is available each year to a person who was awarded the degree of Doctor of Philosophy in the previous year for research conducted at JCSMR in the field of immunology.', sc.`scholarship_amount` = 'AUD $2000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/dewar-milne-prize-immunology', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/dewar-milne-prize-in-immunology/c4a66aa41c8e4ec192c72cc3003398ab', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Dewar Milne Prize in Immunology' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'ANU-CSIRO Digital Agriculture PhD Scholarship provides funding to support outstanding candidates to pursue a PhD program at ANU, where the focus of their research is on a collaborative project between CSIRO and ANU in the field of information science relevant to agriculture. Funding for this award has been provided by CSIRO’s Data61 - Australia\' leading data innovation group. Their mission is to create Australia’s data driven future by building the world’s leading data-focused research and innovation powerhouse.', sc.`eligibility` = 'The Award will be available to a prospective domestic or international candidate who:; is enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy in the field of Information Science relevant to the Agriculture domain, based in the either the ANU College of Science and Medicine or the ANU College of Systems and Society; will be undertaking research for CSIRO / ANU projects under a Collaboration Agreement; has demonstrated First class honours (H1), or equivalence; have signed a Student Agreement with CSIRO, unless otherwise agreed in writing with CSIRO; must not be in full-time employment.', sc.`scholarship_amount` = '$39,069 per annum and $15,000 per annum supplementary scholarship', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/digital-agriculture-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/digital-agriculture-phd-scholarship/a4be1ecbd4444d708482a192a31692ce', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Digital Agriculture PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Directors Scholarship for Academic Excellence is offered by ANU College of Science to the very best international students from the ANU - SDU Joint Science College (JSC) at Shandong University, Weihai, China. The scholarship rewards high quality, top-performing students from JSC who come to study at ANU.', sc.`eligibility` = 'is an International student; is currently enrolled in the ANU-SDU Joint Science College at Shandong University, Weihai; receives an offer of admission to a vertical double degree combination of undergraduate and postgraduate coursework programs offered by the ANU College of Science; has not received the Award previously.', sc.`scholarship_amount` = 'AUD $7500/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/directors-scholarships-academic-excellence', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/directors-scholarships-for-academic-excellence/97f902f83bc460e7ae2b34b992afb00d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Director’s Scholarships for Academic Excellence' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the John Curtin School of Medical Research in the ANU College of Health and Medicine may offer an award known as the Doherty PhD Supplementary Scholarship with the aim to attract students of high calibre, with clinical qualifications, to pursue postgraduate studies at the JCSMR involving a clinical research project, in order to facilitate interaction between basic biomedical science and clinical research. The award was established in honour of Professor Peter Doherty, who shared the Nobel Prize for Physiology or Medicine with Professor Rolf Zinkernagel in 1996, for work done at JCSMR.', sc.`eligibility` = 'is awarded and continues to hold an Australian Government Research Training Program (AGRTP) Stipend Scholarship, or a similar living expenses PhD scholarship; is enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy at the John Curtin School of Medical Research; holds an Australian Bachelor Honours degree with First Class Honours or equivalent,and has research publications and/or relevant research experience.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/doherty-phd-supplementary-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/doherty-phd-supplementary-scholarship/ee98e1be37edae439add32a51dfcc49b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Doherty PhD Supplementary Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is offered by the John Curtin School of Medical Research (JCSMR). The Doherty Scholarship (Clinical) is to attract students of high calibre with clinical qualifications to pursue graduate research involving a clinical research project for a PhD degree at the JCSMR.', sc.`eligibility` = 'Students of high calibre with clinical qualifications. Preference given to Australian or New Zealand Citizens and Permanent Residents of Australia however International students will also be considered.', sc.`scholarship_amount` = 'AUD $34000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/doherty-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/doherty-scholarship/e87c4a44ec17259f943e5832e66c2855', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Doherty Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the Research School of Earth Sciences within the ANU College of Science and Medicine may offer an award known as the Dr Matthew Valetich Honours Scholarship in Geoscience. The objective of the Award is to provide financial assistance to a student undertaking their honours year in geoscience.  Funding for this Award has been provided by Anglo American Exploration (Australia) Pty Limited in honour of Dr Matthew Valetich, a PhD graduate of the Research School of Earth Sciences.', sc.`eligibility` = 'The Award is available each year to a commencing or continuing ANU student who:; is a domestic or international student; receives an offer of admission to a Bachelor of Science (Honours), Bachelor of Philosophy (Honours), or Bachelor of Science (Advanced) (Honours) program within the ANU College of Science and Medicine; is enrolled in an Honours research project based in the Research School of Earth Sciences (RSES). Supervision by staff from other ANU research schools within the ANU College of Science and Medicine is permitted and encouraged; can demonstrate financial hardship that may impact their ability to commence, continue, or complete their studies.', sc.`scholarship_amount` = 'AUD $9000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/dr-matthew-valetich-honours-scholarship-geoscience', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/dr-matthew-valetich-honours-scholarship-in-geoscience/01c3c32524e8d98cbc52adfda59eb6d9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Dr Matthew Valetich Honours Scholarship in Geoscience' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Ellison Institute of Technology (EIT), funded by Larry Ellison, is committed to advancing technology to solve some of humanity’s most serious problems. They are now launching a unique scholarship programme to invite the global technology innovators and leaders of the future to join their mission. EIT will fully fund undergraduate or graduate study at the University of Oxford.', sc.`eligibility` = 'Please Contact ANU for more information about Eligibility', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/ellison-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ellison-scholarship/754de292244a46424e5d8cea1f7a8d9c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Ellison Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Emergency Accommodation Bursary is designed to assist students who are currently enrolled at the ANU as an award-status student, and are experiencing unexpected financial difficulty in meeting their accommodation costs. Assistance is not ongoing and the bursary is not designed for pre-arrival costs or as a method of income. Funds are granted subject to eligibility. Applications are assessed and awarded at the discretion of the Bursary Review Committee. The Committee will determine the amount of any bursary granted from an assessment of the students need and the availability of funds. The Emergency Accommodation Bursary can provide up to 52 weeks of financial support over the course of your current level of study at the ANU. If living on campus, bursary funds will be paid directly to a student\'s residential account.', sc.`eligibility` = 'is a domestic or international student; is enrolled in an undergraduate, honours or postgraduate degree offered by the University; is enrolled in at least one course (if a coursework student) or at least 24 units (if a higher degree research student) during the period; has not received the Award for 52 weeks during their current level of study; if residing in an on-campus residence, does not have any serious breaches of their Occupancy Agreement recorded; can demonstrate a change in personal circumstances that has affected their ability to meet financial obligations; can demonstrate financial hardship.', sc.`scholarship_amount` = 'Scholarship Value : Variable', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/emergency-accommodation-bursary', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/emergency-accommodation-bursary/f291a1d1225791c1ff7218bc9b953a5a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Emergency Accommodation Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the School of Cybernetics in the ANU College of Engineering and Computer Science (College) may offer up to 10 awards known as the FMK Supplementary Scholarship (Award). Funding for this Award has been provided by the Florence Violet McKenzie Chair. The Australian National University (ANU) College of Engineering and Computer Science is embarking on an ambitious agenda to reimagine engineering and computing to launch our society into the middle of the 21st Century. We are bringing non-traditional skills to engineering and computing to put people in the centre of delivering solutions to global challenges.', sc.`eligibility` = 'Have received a statement of support from the SOCY cohort PhD program convenor; are enrolled full-time in the cohort program of study for the degree of Doctor of Philosophy at SOCY at the ANU; have been awarded, and continue to hold, an ANU approved PhD base stipend scholarship; have agreed to assign the ownership of any Student Material (as defined in the Student Assignment and Confidentiality Deed (Deed)) including any Intellectual Property embodied in the Student Material to the University, in accordance with the terms of the Deed between the recipient and the University. The recipient is encouraged to seek independent advice before signing the Deed and accepting this Award, for example via the ANU Postgraduate & Research Students\' Association (PARSA).', sc.`scholarship_amount` = 'AUD $20908/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/florence-mckenzie-chair', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/florence-mckenzie-chair/1c273c9c470780d035057b0755a1f6c3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Florence McKenzie Chair' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The ARC Training Centre for Future Crops is working directly with industry and the community to train the next generation of research and industry leaders to deliver impactful projects with real-world implications for food security. Students in plant science and communication in science will have opportunities to engage with industry partners and communities on projects to improve the yield and nutritional value of the crops that underpin the energy and protein content of the human diet. Together, the Centre will build future R&D capabilities in the Agrifood sector to drive growth, productivity and competitiveness for the benefit of agriculture and global food security. These scholarships will enable students to pursue a PhD program conducting research that is either a core project within the Centre, or closely aligns with the strategic directions of the Centre, based in the College of Science.', sc.`eligibility` = 'is enrolling full-time in a program of study for the degree of Doctor of Philosophy, based in the ANU College of Science; has been awarded a first-class honours or equivalent; is undertaking one of the core Centre PhD research projects, or a project approved by the Centre Executive.', sc.`scholarship_amount` = 'AUD $34938/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/future-crops-centre-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/future-crops-centre-scholarship/7b7331b3755082e4fe412af87cadc11b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Future Crops Centre Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'An Award has been established and named in honour of Dr. Geoff Mercer, a highly regarded Professor at the National Centre of Epidemiology and Population Health (NCEPH) in the Research School of Population Health (RSPH), who passed away suddenly in April 2014 at the peak of his career. This Award will continue Geoff\'s legacy of mentoring and support of students, by funding a grant for postgraduate RSPH students to undertake an activity in pursuit of their academic goals, including travel to a national or international conference. Given Geoffs commitment to applying mathematics to population health, especially infectious disease problems, students undertaking research in that area are particularly encouraged to apply.', sc.`eligibility` = 'The Award shall be awarded each year to the student who, enrolled in the Research School of Population Health, has completed an application for funding support that is judged by the Selection Committee to be the most likely to enhance the pursuit of the applicant\'s academic goals.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/geoff-mercer-award', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/geoff-mercer-award/45c9cc8577527edeb508a5a3d483522d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Geoff Mercer Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The purpose of this scholarship is to support students enrolled in the Master of Energy Change (Advanced) program and undertaking a research project in the field of the hydrogen economy.', sc.`eligibility` = 'Applicants must be enrolled in: the Master of Energy Change (Advanced) program or the Master of Energy Change program and eligible for transfer to the Master of Energy Change (Advanced ); Applicants must have a suitable supervisor and meet conditions for enrolling into  SCNC8021 Science Research Project (24 units over 2 semesters).; The research project approved by the supervisor must be in the field of the Hydrogen Economy; Applicants must have achieved at least 70% average in the coursework component of the program.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/global-power-generation-australia-scholarship-hydrogen-economy', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/global-power-generation-australia-scholarship-in-the-hydrogen-economy/520a7ccb4b4327b5f51b820f35fe77a1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Global Power Generation Australia Scholarship in The Hydrogen Economy' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Grace Groom Memorial Scholarship has been established from a donation by the Mental Health Australia Ltd in memory of Grace Groom. The purpose of the Scholarship is to provide financial support to international or domestic postgraduate students enrolled in study and research relating to mental health issues. Applicants may be enrolled in any research program within the ANU College of Health and Medicine (CHM). Their research program should have meaningful and real application to the daily lives of people with a mental illness and/or the people who care for them.', sc.`eligibility` = 'be enrolled in a graduate research program offered within the ANU College of Health and Medicine; be already undertaking study in a mental health related field.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/grace-groom-memorial-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/grace-groom-memorial-scholarship/30f95576c8bf69516517751b5dc2929c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Grace Groom Memorial Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'ANU Colleges may offer Fee Remission Merit Scholarships to eligible International students.', sc.`eligibility` = 'be enrolled in a postgraduate research program; be an International student; have been ranked as part of a competitive scholarship process for another ANU or external scholarship.', sc.`scholarship_amount` = 'Full tuition', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/hdr-fee-remission-merit-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/hdr-fee-remission-merit-scholarship/f0214097422bc5e1d692d4da343129d5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'HDR Fee Remission Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the Division of Genome Sciences and Cancer at the John Curtin School of Medical Research (JCSMR) within the ANU College of Science and Medicine may offer an award known as the Helen Winslade Honours Scholarship in Cancer Research.  The objective of the Award is to support high-achieving students undertaking the Honours Year of their undergraduate degree, who are conducting research projects focused on cancer.  Funding for this Award has been provided by Mr Michael Winslade and family in memory of Mrs Helen C. Winslade, an ANU alumna.', sc.`eligibility` = 'The scholarship is available to an applicant:; who is an International or domestic student; who is enrolled in an Honours year at the John Curtin School of Medical Research; whose Honours project is related to cancer research.; whose primary supervisor is a member of the Division of Genome Sciences and Cancer.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/helen-winslade-honours-scholarship-cancer-research', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/helen-winslade-honours-scholarship-in-cancer-research/66d39a5a144553e22d1b62f30852689d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Helen Winslade Honours Scholarship in Cancer Research' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Research School of Earth Sciences (RSES) within the ANU College of Science and Medicine may offer a number of awards known as the Ian McDougall Honours Scholarship. The objective of the Award is to support an Honours student in Geochronology in the RSES. Funding for this Award is provided by Professor Ian McDougall, who has been described as "one of Australia\'s most internationally distinguished earth scientists" and was awarded the Centenary Medal in 2001.', sc.`eligibility` = 'The Award is available to a commencing or continuing ANU student who:; is a domestic or international student; receives an offer of admission to an Honours program offered by the Research School of Earth Sciences within the ANU College of Science and Medicine; is undertaking a research project in the field of geochronology.', sc.`scholarship_amount` = 'AUD $8000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/ian-mcdougall-honours-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ian-mcdougall-honours-scholarship/74db721cd70dff7587020da648f6284d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Ian McDougall Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the John Curtin School of Medical Research (the JCSMR) in the ANU College of Health & Medicine may offer funding of up to $10,000 from the JCSMR Gender Equity Fund. Funding has been provided by a generous initial donation by Professor Carola Vinuesa and continues with the support of Richard Miller and the School, as funding permits. The objective of this Fund is to provide funding for an early or mid-career researcher or domestic or international PhD student who is experiencing significant career disruption resulting from the birth of a child, or the primary care of a child, which limits or prevents their career progression and research activities in the John Curtin School of Medical Research.', sc.`eligibility` = 'a female-identifying researcher at the JCSMR who holds a current academic appointment at level A-C and intends to return to a career in research; a continuing domestic or international female-identifying student who is enrolled in a program of study for the degree of Doctor of Philosophy, based in the John Curtin School of Medical Research (the JCSMR) and, in relation to the birth or care of a child,; is experiencing a period of significant career disruption (generally at least 12 weeks) or expects to do so within the next 6 months; within the last 12 months, has applied for or returned from a period of career disruption (generally at least 12 weeks).', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/jcsmr-gender-equity-fund', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/jcsmr-gender-equity-fund/73f35e5e333e36767b40b86ede2c2f49', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'JCSMR Gender Equity Fund' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the ANU College of Asia and the Pacific (the College) may offer an award known as the Jamie Mackie Southeast Asia Travel Grant (the Award). The objective of the Award is to assist students to undertake research or study where they will benefit from travel to Southeast Asia. The aim of the Award is to promote Australias engagement with Southeast Asia and/or Southeast Asias engagement with Australia. Funding for this Award has been provided by friends, family and colleagues in memory of the late Emeritus Professor Jamie Mackie, scholar, mentor, advocate and pioneer in our collective understanding of Indonesia and Southeast Asia. The endowment promotes Jamies lifelong passions: Indonesia and Southeast Asia, Australias engagement in our region and racial respect and tolerance.', sc.`eligibility` = 'is a domestic or international student; is undertaking an undergraduate or postgraduate coursework program at the College; is enrolled in a mobility course at the College; is intending to travel to Southeast Asia for the purpose of furthering their understanding of the region; can demonstrate that their travel will contribute to a better understanding and knowledge of any aspect of Australia in Southeast Asia, or any aspect of Southeast Asia in Australia.', sc.`scholarship_amount` = 'Up to AUD $5000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/jamie-mackie-southeast-asia-travel-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/jamie-mackie-southeast-asia-travel-grant/e7640ebf69ecfb92699418e228d9f3a2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Jamie Mackie Southeast Asia Travel Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Biology may offer an award known as the Research School of Biology Jan Anderson ANU-NTU HDR Supplementary Scholarship.  The award is to provide financial support for students currently enrolled in a RSB HDR program and travelling to Nanyang Technical University (NTU, Singapore) to undertake the joint research and help them develop their scientific and professional skills.', sc.`eligibility` = 'a domestic or international student; enrolled or enrolling full-time in a Doctor of Philosophy study program within the RSB; Undertaking a research project that suitably demonstrates collaboration with one or more researchers at Nanyang Technological University (NTU); has been awarded, and has accepted, an ANU HDR base stipend scholarship.', sc.`scholarship_amount` = 'AUD $7000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/jan-anderson-anu-ntu-hdr-supplementary-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/jan-anderson-anu-ntu-hdr-supplementary-scholarship/84edc611068f4248b107f467b1c6dbfb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Jan Anderson ANU-NTU HDR Supplementary Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Jason Passioura Bursary honours its namesake who passed away in 2022 after battling Glioblastoma Multiforme (GBM) brain cancer for 16 months. Jason was a valued member of the NCEPH community who showed enthusiasm for his work and demonstrated exceptional commitment to data accuracy and ensuring that evidence-based research was undertaken with a focus on improving the quality of source data. This Bursary recognises Jasons outstanding contribution to research, in particular Jasons achievements in using spatial analysis to inform suicide prevention research; work carried out at the NCEPH as a collaboration between GRAPHC (the National Centre for Geographic Resources & Analysis in Primary Health Care) and the Black Dog Institute. Funding for this Award has been provided by NCEPH. The Jason Passioura Bursary will continue Jasons legacy, by each year funding one or more students or researchers (academic Level A or B or professional staff) to undertake activity in pursuit of their research goals. The Bursary is intended to support the use of high-quality data in research. Given Jasons commitment to spatial analyses especially regarding suicide prevention, applications that relate to these areas will be considered favourably.', sc.`eligibility` = 'The Award is available each year to a continuing domestic or international ANU student (honours, postgraduate or HDR) who is enrolled in a program of study at NCEPH; and/or an ECR (Level A or B); and/or a professional staff member with suitable experience working at NCEPH.', sc.`scholarship_amount` = 'AUD $1500/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/jason-passioura-bursary', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/jason-passioura-bursary/183ad9e04a0c970f86e8efcb8f6b9b33', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Jason Passioura Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the John Curtin School of Medical Research (JCSMR) within the ANU College of Science and Medicine may offer a number of awards known as the Joyce Fildes Honours Scholarship in Medical Science.  The objective of the Award is to support students undertaking their Honours project, with research conducted in any area of medical science.  Funding for this Award has been provided in memory of its donor, Dr Joyce Fildes, a former staff member of the John Curtin School of Medical Research.', sc.`eligibility` = 'The scholarship is available to an applicant:; who is an International or domestic student; who is enrolled in an Honours year at the John Curtin School of Medical Research; whose Honours project is in any field of biomedical research conducted at the John Curtin School of Medical Research.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/joyce-fildes-honours-scholarship-medical-science', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/joyce-fildes-honours-scholarship-in-medical-science/a48294b7daa61f5da93cbb6bd087189b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Joyce Fildes Honours Scholarship in Medical Science' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Kloeden Foundation Forestry Grant supports undergraduate and postgraduate domestic and international students with a bona fide interest in developing a career in forestry and plantation management.', sc.`eligibility` = 'is a domestic or international student; has completed a minimum of 72 units of studies in their undergraduate program; is a commencing or continuing postgraduate student; is enrolled/enrolling in one of the following programs:; Bachelor of Environment of Sustainability or Bachelor of Environment of Sustainability (Advanced) (Honours); Bachelor of Science or Bachelor of Science (Advanced) (Honours); Master of Forestry or Master of Forestry (Advanced); Master of Environment or Master of Environment (Advanced)', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/kloeden-foundation-forestry-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/kloeden-foundation-forestry-grant/e2007f74b82dc48c30e3a044bff6f84c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Kloeden Foundation Forestry Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Centre for Mental Health Research (CMHR) of the National Centre for Epidemiology and Population Health (NCEPH) in the ANU College of Health and Medicine may offer an award known as the Korten Prize. Funding for this Award has been provided by the Centre for Mental Health Research in memory of Mrs Ailsa Korten who worked as a research officer in CMHR between 1986 and 2005. Ailsa Korten published over 120 research papers during this period. The objective of the prize is to acknowledge a high-achieving research candidate who has written the best research paper in the year of the award, whilst enrolled in a PhD program based in the College of Health and Medicine.', sc.`eligibility` = 'is enrolled in a program of study for the degree of Doctor of Philosophy in the field of Mental Health Research, with their Primary Supervisor based in the National Centre for Epidemiology and Population Health (NCEPH) of the ANU College of Health and Medicine (CHM); has published, or had a paper accepted for publication in the year of the award.', sc.`scholarship_amount` = 'AUD $1000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/korten-prize', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/korten-prize/9901b48ab065b6c4b958f7f21c199f32', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Korten Prize' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is offered by the ANU College of Arts and Social Sciences.', sc.`eligibility` = 'Selection is made on the basis of applicants meeting the eligibility criteria. Other factors, such as interview at time of audition, may be taken into consideration.', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/leonard-margaret-doman-undergraduate-scholarship-flute', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/leonard-and-margaret-doman-undergraduate-scholarship-for-flute/2cca2838097ee5f8add0f395d184b5f0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Leonard and Margaret Doman Undergraduate Scholarship for Flute' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Astronomy and Astrophysics (the School) may offer an award known as the Master of Science (Advanced) in Astronomy and Astrophysics Scholarship (the award). The objective of the award is to support an outstanding domestic or international student to enable them to pursue the Master of Science (Advanced) in Astronomy and Astrophysics, offered by the Research School of Astronomy and Astrophysics in the ANU College of Science. Funding for this award has been provided by the Research School of Astronomy and Astrophysics.', sc.`eligibility` = 'is a domestic or international student; is currently enrolled in the Master of Science (Advanced) in Astronomy and Astrophysics; has completed at least 48 units of the Master of Science (Advanced) in Astronomy and Astrophysics degree program with a minimum Weighted Average Mark (WAM) of 80%; is not receiving Commonwealth support for this degree program.', sc.`scholarship_amount` = 'Up to AUD $20000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/master-science-advanced-astronomy-and-astrophysics-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/master-of-science-advanced-in-astronomy-and-astrophysics-scholarship/7de8e3bd0e4eef9ee2714dbfb1c2a0c2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Master of Science (Advanced) in Astronomy and Astrophysics Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is offered by the ANU College of Science.', sc.`eligibility` = 'Students enrolled full-time in a graduate research program in the Research School of Earth Sciences. Must have been enrolled in their research program for a minimum of 6 months.; Selection basis: The Committee shall select for the Scholarship a person who, in the opinion of the Committee, is at the stage in their Program where their research would be greatly enhanced by their attending a major international conference and visiting an overseas institution.', sc.`scholarship_amount` = 'AUD $7500/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/mervyn-katalin-paterson-fellowship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/mervyn-katalin-paterson-fellowship/ff6e04b0f5d2a943ba43216c6346fb9a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Mervyn & Katalin Paterson Fellowship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Research School of Astronomy and Astrophysics (RSAA) offers the Olin J Eggen Research Award to up to 3 outstanding international students commencing in the PhD program at RSAA. Funding for this Award is made possible by an endowment setup to commemorate the contributions of the late Professor Olin J Eggen. Professor Eggen, a native of Wisconsin, USA, was Director of Mt Stromlo Observatory from 1966 through 1977, a period that saw considerable growth and with it the foundation of the high international regard in which the Observatory (now the Research School of Astronomy & Astrophysics) is held. The objective of the Award is to support outstanding international students to enable them to pursue a Doctor of Philosophy (PhD) program in Astronomy & Astrophysics based in the Research School of Astronomy & Astrophysics.', sc.`eligibility` = 'is enrolling full-time in a program of study for the degree of Doctor of Philosophy in Astronomy & Astrophysics based in the Research School of Astronomy & Astrophysics; and is and remains an international student; has a demonstrated track record of significant research that contributes to the field of Astronomy & Astrophysics.', sc.`scholarship_amount` = 'AUD $2500/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/olin-j-eggen-research-award', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/olin-j-eggen-research-award/e2fabf845cad95de850b3734cf441176', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Olin J Eggen Research Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the ANU College of Asia and the Pacific (the College) may offer a number of awards known as the Pacific Institute PhD Grant for research (the Award). Funding for this Award has been provided by the Pacific Institute Endowment. The Pacific Institute recognizes the achievements of Jim Davidson, Professor of the Research School of Pacific and Asian Studies, Sir Peter Buck, distinguished Maori Historian, and Senator John Knight who established a Pacific Fellowship Fund. The objective of the Award is to advance the higher education of Pacific Islanders and research on Pacific-related topics by providing support for an outstanding domestic or international candidate.', sc.`eligibility` = 'is enrolling full-time in a program of study for the degree of Doctor of Philosophy in the ANU College of Asia and the Pacific; is of Pacific Islander Heritage; is conducting fieldwork in a Pacific studies related area', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/pacific-institute-phd-fieldwork-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/pacific-institute-phd-fieldwork-grant/de71a811d3d2fe7735c23ba24719c555', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Pacific Institute PhD Fieldwork Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the ANU College of Asia and the Pacific (the College) may offer a number of awards known as the Pacific Institute PhD Grant for research (the Award). Funding for this Award has been provided by the Pacific Institute Endowment. The Pacific Institute recognizes the achievements of Jim Davidson, Professor of the Research School of Pacific and Asian Studies, Sir Peter Buck, distinguished Maori Historian, and Senator John Knight who established a Pacific Fellowship Fund. The objective of the Award is to advance the higher education of Pacific Islanders and research on Pacific-related topics by providing support for an outstanding domestic or international candidate.', sc.`eligibility` = 'is enrolling full-time in a program of study for the degree of Doctor of Philosophy in the ANU College of Asia and the Pacific; is of Pacific Islander Heritage.', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/pacific-institute-phd-grant-research', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/pacific-institute-phd-grant-for-research/df48c874121903c7f5e39b8554dbac52', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Pacific Institute PhD Grant for Research' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the John Curtin School of Medical Research (JCSMR) within the ANU College of Science and Medicine may offer a number of awards known as the Paul Bunyan Memorial Scholarship in Medical Sciences. \r\n\r\nThe objective of the Award is to support students undertaking their Honours project, with research to be conducted in medical science, preferably in a field related to cancer research.\r\n\r\nFunding for this Award has been provided by Mr and Mrs Bunyan, in memory of their son, Paul.', sc.`eligibility` = 'The scholarship is available to an applicant:;who is an International or domestic student; who is enrolled in an Honours year at the John Curtin School of Medical Research; whose Honours project is preferably related to cancer research.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/paul-bunyan-memorial-scholarship-medical-sciences', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/paul-bunyan-memorial-scholarship-in-medical-sciences/68264d8256f1e68ad1efcd1a12795d87', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Paul Bunyan Memorial Scholarship in Medical Sciences' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Peter Gage Supplementary Scholarship in Membrane Physiology is named in honour of Professor Peter William Gage, in recognition of his having been one of Australias leaders in membrane physiology, biophysics and neuroscience. Peter influenced and encouraged a great many research students, postdoctoral fellows and senior colleagues in their scientific careers. The objective of the Award is to encourage outstanding domestic or international candidates to pursue a Doctor of Philosophy (PhD) program in the field of medical sciences, based in the JCSMR.', sc.`eligibility` = 'is enrolled or will be enrolling full-time in a program of study for the degree of Doctor of Philosophy, based in the John Curtin School of Medical Research; has completed qualifications comparable to the educational level of an Australian Bachelor first class Honours degree, or has demonstrated research experience to a standard equivalent to an ANU first class Honours; has been awarded, and continues to hold, an approved ANU HDR base stipend scholarship at the minimum AGRTP base rate.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/peter-gage-memorial-supplementary-scholarship-membrane-physiology', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/peter-gage-memorial-supplementary-scholarship-in-membrane-physiology/37ab3b8d333b6dbb37569c257560fe55', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Peter Gage Memorial Supplementary Scholarship in Membrane Physiology' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The objective of the award is to reward excellence in research in the Research School of Astronomy & Astrophysics instrumentation program or excellence in research that has a substantial instrumentation component, and to encourage outstanding students to pursue PhD degree programs in astronomy and astrophysics at the ANU with a special emphasis on instrumentation development.', sc.`eligibility` = 'The award is available each year to a new or continuing student who is enrolled in the PhD program at the Research School of Astronomy & Astrophysics and is working on a project in astronomy and astrophysics that incorporates instrumentation development or innovative use of instrumentation.  The student must also have completed all required milestones to the satisfaction of the Delegated Authority.', sc.`scholarship_amount` = 'AUD $6000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/peter-mcgregor-hdr-supplementary-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/peter-mcgregor-hdr-supplementary-scholarship/ddbc5985e9ea6b33d73edfe7540159c7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Peter McGregor HDR Supplementary Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the ANU College of Science and Medicine may offer a number of awards known as the PhB Science Scholarship.  The objective of the Award is to provide support to PhB Science students from disadvantaged backgrounds and/or to assist PhB Science students with relocation costs to support their move to Canberra.  Funding for this Award has been provided by the ANU College of Science and Medicine.', sc.`eligibility` = 'The Award is available each year to a commencing ANU student who:; (a) is a domestic or international student; (b) receives an offer of admission to the Bachelor of Philosophy (Honours) - Science; (c) is commencing their first undergraduate degree.', sc.`scholarship_amount` = 'AUD $6500/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/phb-science-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/phb-science-scholarship/3d4202adeaafe2e7424009c1527451d1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'PhB Science Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Research School of Astronomy and Astrophysics', sc.`eligibility` = 'This supplementary scholarship is extended to all Research School of Astronomy & Astrophysics PhD students, excluding those receiving an ARC Laureate Scholarship.; Eligible programs: Phd', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/rsaa-supplementary-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rsaa-supplementary-scholarships/d5d9be063c8dfe81599417db5476edf9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'RSAA Supplementary Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Economics (the School) in the ANU College of Business and Economics (the College) may offer an award known as the Research School of Economics Bob Gregory Honours in Economics Scholarship for International Students (the award). The objective of the Award is to attract high achieving international students to enrol in an Honours in Economics program offered by the Research School of Economics. Funding for this award has been provided by the Research School of Economics.', sc.`eligibility` = 'is an international student; is currently completing, or has completed in the past 12 months, an undergraduate degree in Economics at an Australian university or recognised overseas institution; has accepted an offer of admission in the one-year Bachelor of Economics (Honours) program offered at the ANU College of Business and Economics; has accepted an offer of admission in the final year of the Honours in Economics program of the Bachelor of Finance, Economics and Statistics, offered at the College.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/rse-bob-gregory-honours-economics-scholarship-international-students', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rse-bob-gregory-honours-in-economics-scholarship-for-international-students/60ca85ad1f6ec7797a9b907378e562e6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'RSE Bob Gregory Honours in Economics Scholarship for International Students' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Earth Sciences (the School) may offer a number of awards known as the Earth Sciences Opportunity Scholarship (the Award). The objective of the Award is to provide financial assistance to students enrolled in an Earth Sciences degree program to allow them to commence, continue and/or complete their studies.Funding for this Award has been provided by various donors.', sc.`eligibility` = 'is a domestic or international student; is enrolled in or has completed EMSC1006 or EMSC1008 (undergraduate applicants); is enrolled in an undergraduate or postgraduate coursework program offered by the Research School of Earth Sciences; can demonstrate financial need.', sc.`scholarship_amount` = 'Scholarship Value: Variable', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/rses-opportunity-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rses-opportunity-scholarship/c4c0922de50f72718da7a2b03cb2a050', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'RSES Opportunity Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The award is a top-up to the Australian Government Research Training Program (AGRTP) Stipend Scholarship (previously the Australian Postgraduate Award), for the top-ranked Higher Degree Research applicant enrolling full-time in a program of study for the degree of Doctor of Philosophy in the Research School of Social Sciences.', sc.`eligibility` = 'a domestic or international student; enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy in the Research School of Social Sciences at the Australian National University; has been awarded an AGRTP Stipend Scholarship.', sc.`scholarship_amount` = 'AUD $20000/year — The amount will not exceed 75% of the AGRTP, so the amount will vary based on the value of the AGRTP.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/rsss-directors-award-higher-degree-research', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rsss-directors-award-for-higher-degree-research/0e597fb71cc76ef548682a735ee575ad', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'RSSS Director’s Award for Higher Degree Research' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is to assist students enrolled in a one year Honours program, undertaking research utilising non-animal alternative methods to replace the use of animals or animal products in medical research.', sc.`eligibility` = 'is a domestic or international student; receives an offer of admission to an honours specialisation in the ANU College of Science or the ANU College of Health and Medicine; is undertaking research utilising non-animal alternative methods to replace the use of animals or animal products in medical research.', sc.`scholarship_amount` = 'AUD $15000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/replacing-animals-medical-research-honours-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/replacing-animals-in-medical-research-honours-scholarship/680266e7c9c8d73dea1d60d5634b5bad', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Replacing Animals in Medical Research Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Accounting within the ANU College of Business and Economics may offer a number of awards known as the Research School of Accounting Pre-Master Training Program Scholarship (the Award). The objective of the Award is to continue the long-standing partnership and successful pre-masters agreement between ANU and selected Partners. Funding for this Award has been provided by the Research School of Accounting.', sc.`eligibility` = 'is an international student; is completing, or has completed a recognised Pre-Master Training Program at a home institution; is enrolled in, or has received an offer of admission to the Master of Accounting (4 semesters), or the Master of Professional Accounting (3 semesters).', sc.`scholarship_amount` = '25% Tuition Fee waiver', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-accounting-pre-master-training-program-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-school-of-accounting-pre-master-training-program-scholarship/d4d5a69320d71ae20aa45aeaf770f4f1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Research School of Accounting Pre-Master Training Program Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the ANU Research School of Biology (RSB) may offer one or more scholarships known as the Research School of Biology International PhD Scholarship to attract the highest calibre international students to pursue a PhD degree within the school.', sc.`eligibility` = 'an International student; enrolling full-time in a program of study for the degree of Doctor of Philosophy at ANU in RSB.', sc.`scholarship_amount` = 'AUD $36652/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-biology-international-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-school-of-biology-international-phd-scholarship/937c872c3e8143301f674cd485222add', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Research School of Biology International PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is to assist students enrolled in the Honours Year of an undergraduate degree offered by the ANU College of Science, specialising in Chemistry', sc.`eligibility` = 'is a domestic or international student; receives an offer of admission to Honours in Science, specialising in Chemistry; obtains a GPA of 6.00 or above out of 7.00 across 48 units of Chemistry or cognate courses', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-chemistry-honours-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-school-of-chemistry-honours-scholarship/d504bcf22139a171ad3f9601adbfa71e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Research School of Chemistry Honours Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Finance, Actuarial Studies and Statistics (RSFAS) within the ANU College of Business and Economics may offer a number of awards known as the Research School of Finance, Actuarial Studies and Statistics Foundation Scholarship (the Award). The objective of the Award is to continue the long-standing partnership and successful Foundation agreement between the ANU and selected partners. Funding for this Award has been provided by RSFAS.', sc.`eligibility` = 'is an international student; is enrolled in or has received an offer of admission to one of the following programs:; Bachelor of Actuarial Studies or; Bachelor of Finance or; Bachelor of Statistics', sc.`scholarship_amount` = '10% of international student fee', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-finance-actuarial-studies-and-statistics-foundation', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-school-of-finance-actuarial-studies-and-statistics-foundation-scholarship/76dc4bb3cacbd3628d48250aab9c506a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Research School of Finance, Actuarial Studies and Statistics Foundation Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Finance, Actuarial Studies and Statistics (RFSAS) within the ANU College of Business and Economics may offer a number of awards known as the Research School of Finance, Actuarial Studies and Statistics Pre-Master Training Program Scholarship (the Award). The objective of the Award is to continue the long-standing partnership and successful pre-masters agreement between ANU and selected Partners. Funding for this Award has been provided by RFSAS.', sc.`eligibility` = 'is an international student; is completing or has completed a recognised Pre-Master Training Program at a home institution; is enrolled in or has received an offer of admission to one of the following programs:; Master of Finance (4 semesters); Master of Actuarial Studies (4 semesters); Master of Financial Management (2 semesters); Master of Statistics (4 semesters); Master of Applied Finance (3 semesters); Master of Actuarial Practice (5 semesters)', sc.`scholarship_amount` = '25% of international student fee', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/research-school-finance-actuarial-studies-and-statistics-pre-master', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-school-of-finance-actuarial-studies-and-statistics-pre-master-training-program-scholarship/f2a3ed0009d08b75e1b9a3bebf253ebd', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Research School of Finance, Actuarial Studies and Statistics Pre-Master Training Program Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Commonwealth Department of Education and Training provides funding to Universities to award scholarships to International students undertaking Higher Degree Research programs under the Australian Government Research Training Program (RTP).  Note the duration of this scholarship has been updated from 3 years to 3.5 years following the VCs announcement relating to scholarship changes in effect from 1.10.2022.  Candidates now no longer have to apply to extend this scholarship from 3 years to 3.5 years.', sc.`eligibility` = 'The Commonwealth Scholarship Guidelines (Research) 2017 set the basis for the conditions of award and outline the basic eligibility requirements for this scholarship.; The ANU has established an RTP Policy & Procedure which outlines the standards, processes and conditions for this scholarship.  These documents are available from the reference document section of this page.; Candidates are ranked and scholarships are awarded based on a competitive ranking process, to the top ranked candidates, subject to evidence they meet merit-based selection criteria, and subject to confirmation of a qualified supervisor, space and resources being available, in an area of research that is aligned with ANU research strategy.', sc.`scholarship_amount` = 'Full Tuition fees for 3.5 years', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/research-training-program-rtp-international-fee-offset-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-training-program-rtp-international-fee-offset-scholarship/0ade3a1a62278cc92222ba7f7c416989', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Research Training Program (RTP) International Fee Offset Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Earth Sciences may offer an award known as the Ross Taylor PhD Supplementary Scholarship in Geochemistry. Funding for this Award has been provided by generous donations from associates of Ross Taylor, and matching School funds. Professor Taylor has made an outstanding contribution in geochemistry and as a pioneer of lunar science. His work spans the moon, the Earths continental crust, island arc rocks and beyond. Fifty years ago, the Canberra scientist Professor Ross Taylor made one of the big discoveries about the nature of the moon. Professor Taylor was chosen by NASA as the best person to analyze the first moon rocks brought back by Apollo 11. The launchpad for Taylors success was the environment of excellence at ANU, which included an almost identical lab to NASA. Taylors involvement with the moon was not his only contribution to science. Apart from many academic awards, he was elected as a Foreign Associate of the US National Academy of Sciences in 1994 and he was appointed a Companion of the Order of Australia in 2008.', sc.`eligibility` = 'a domestic or international student; enrolled or enrolling full-time in a program of study for the degree of Doctor of Philosophy in Earth Sciences at the ANU.', sc.`scholarship_amount` = 'AUD $8000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/ross-taylor-phd-supplementary-scholarship-geochemistry', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ross-taylor-phd-supplementary-scholarship-in-geochemistry/b90d01f5d3293d8fc73c39f3f7881694', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Ross Taylor PhD Supplementary Scholarship in Geochemistry' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the ANU College of Asia and the Pacific (the College) in conjunction with the ANU Indonesia Project may offer an award known as the Ruth Daroesman Graduate Study Grant (the Award). The objective of the Award is to support a graduate or higher degree research (HDR) student in their research associated with Indonesia. Funding for this Award has been provided by the Ruth Daroesman Endowment.', sc.`eligibility` = 'is a domestic or international student; is enrolled in a postgraduate coursework or higher degree research program in the College; is undertaking study or research related to Indonesia and that is relevant to their degree program.', sc.`scholarship_amount` = 'AUD $6000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/ruth-daroesman-graduate-study-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ruth-daroesman-graduate-study-grant/55c0d5187a4c29f20bd162972f3ec6d3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Ruth Daroesman Graduate Study Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Research School of Earth Sciences (the School) may offer two awards known as the Scholarship in Regolith Science (the Award). The objective of the Award is to support regolith-related research, especially important for Australian environments. Funding for this Award has been provided through an endowment established in 2008 by the Cooperative Research Centre for Landscape Environments and Mineral Exploration - a joint - venture including the Australian National University (ANU).', sc.`eligibility` = 'is a domestic or international student; is enrolled or will enrol in one of the following programs:; Bachelor of Science (Honours); Bachelor of Science (Advanced) (Honours); Bachelor of Philosophy (Honours); Master of Earth Sciences (Advanced); is undertaking a research project that is consistent with the broad field of regolith science. Projects can include laboratory and/or field and/or modelling studies.', sc.`scholarship_amount` = 'AUD $5000/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/scholarship-regolith-science', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/scholarship-in-regolith-science/64ffb8cef767caa23a2972696137b1b1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Scholarship in Regolith Science' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The objective of the Award is to support students who are undertaking the School of Cybernetics Masters of Applied Cybernetics. The Award aims to help build the recipients leadership skills in technology, business and community areas, and to develop a mentoring relationship with prominent professionals in the private and public sectors.', sc.`eligibility` = 'is a domestic student or international student; receives an offer of admission to or is enrolled in the Master of Applied Cybernetics.', sc.`scholarship_amount` = 'AUD $34000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/school-cybernetics-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/school-of-cybernetics-scholarship/4bb1b180f241acb4f8b04d873c5cb27a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'School of Cybernetics Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Schwarzman Scholars is an unparalleled graduate program for the next generation of young leaders, anchored in a fully-funded 10-month Masters Degree in Global Affairs at Beijings Tsinghua University. The experience encompasses unique opportunities in and outside the classroom, including extensive leadership training, a network of senior mentors, opportunities to engage in high-level interactions with Chinese leaders and visiting speakers, optional internships, career development, and travel seminars around China. Scholars will learn from world-class faculty and guest speakers about the Chinas importance on the global stage through a rigorous and dynamic core curriculum. Schwarzman Scholars prepares young leaders for a globally interconnected future and for careers in which they will join a growing alumni network of leaders who are working to build mutual understanding between China and the rest of the world.  Students spend a year immersed in an international community of thinkers, innovators and senior leaders in business, politics and society. In an environment of intellectual engagement, professional development and cultural exchange, they learn from one another and pursue their academic disciplines while building their leadership capacities. This experience will expand students understanding of the world and create a growing network of global leaders that will build strong ties between China and the rest of the world.', sc.`eligibility` = 'Undergraduate degree or first degree from an accredited college or university or its equivalent.; Age Requirement.; English language proficiency.', sc.`scholarship_amount` = 'Tuition, Room & Board, Stipend & more', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/schwarzman-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/schwarzman-scholarship/7250d6c4385e092be7332d87eb1264a6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Schwarzman Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Shen-su Sun PhD Supplementary Scholarship is offered by the Research School of Earth Sciences (RSES), in the ANU College of Science, to outstanding Chinese PhD Candidates who have been awarded a scholarship by the Chinese Scholarship Council. It is aimed at attracting the highest quality Chinese PhD Candidates to the RSES.', sc.`eligibility` = 'All successful ANU-CSC Scholarship recipients who enrol with RSES will be considered for this Award.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/shen-su-sun-phd-supplementary-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/shen-su-sun-phd-supplementary-scholarship/65a51b77a7af615a6853609bb12c3457', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Shen-su Sun PhD Supplementary Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'In 2024, the Shine-Dalgarno Centre for RNA Innovation, John Curtin School of Medical Research (JCSMR), ANU College of Health and Medicine offers one full scholarship known as the Shine-Dalgarno PhD Scholarship (the Award)', sc.`eligibility` = 'Have demonstrated H1 or H1 equivalence; Are enrolling in a full-time program (with exceptions for special circumstances to be part-time) of study for the degree of Doctor of Philosophy at the ANU in the subject area of RNA biology, with supervision from a member of the Shine-Dalgarno Centre for RNA Innovation (SDCRI).', sc.`scholarship_amount` = 'AUD $36652/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/shine-dalgarno-centre-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/shine-dalgarno-centre-phd-scholarship/9303cebfc9615820dd21dda245e9066e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Shine-Dalgarno Centre PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the Shine-Dalgarno Centre for RNA Innovation, John Curtin School of Medical Research (JCSMR), ANU College of Health and Medicine may offer up to ten awards known as the Shine-Dalgarno PhD Supplementary Scholarship (the Award).', sc.`eligibility` = 'A domestic or international candidate; Is a recipient of an ANU approved HDR base stipend scholarship; is enrolled in a full-time program of study for the degree of Doctor of Philosophy in the subject area of RNA biology, with supervision from a member of the Shine-Dalgarno Centre for RNA Innovation (SDCRI).', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/shine-dalgarno-centre-phd-supplementary-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/shine-dalgarno-centre-phd-supplementary-scholarship/83b9559c31886d6060cabe38fd4da7f5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Shine-Dalgarno Centre PhD Supplementary Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the School of Culture History and Language (CHL), in the ANU College of Asia and the Pacific (CAP), may offer an award known as the Stephen and Helen Wurm PhD Scholarship in Asia-Pacific Linguistics. This Award provides funding for an outstanding domestic or international student, to enable them to pursue a PhD program in Linguistics, based in the CHL, and study a lesser-described Asia-Pacific language, or languages.', sc.`eligibility` = 'Continuation based on academic performance; 6 month extension available.', sc.`scholarship_amount` = 'AUD $39069/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/stephen-helen-wurm-phd-scholarship-asia-pacific-linguistics', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/stephen-helen-wurm-phd-scholarship-in-asia-pacific-linguistics/a21cee760952d9db6b8c4310057491ac', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Stephen & Helen Wurm PhD Scholarship in Asia-Pacific Linguistics' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'In 2023, ANU re-signed an agreement with the Department of International and Cross-Strait Education of the Ministry of Education of the Republic of China (Taiwan) (hereunder referred to as "DICE") to continue the Taiwan Australian National University Scholarship until 2028. The scholarship program commenced in 2013 and provides tuition fees and stipends for up to 5 Taiwanese students per year to undertake PhD studies at ANU over the course of the five year agreement. The scholarships will be jointly funded by ANU and DICE.', sc.`eligibility` = 'Continuation based on academic performance; 6 month extension available.', sc.`scholarship_amount` = 'AUD $39069/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/taiwan-australian-national-university-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/taiwan-australian-national-university-scholarship/d54c5649a2b2b8fa571b7f0b80741296', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Taiwan Australian National University Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the John Curtin School of Medical Research (JCSMR), ANU College of Health and Medicine may offer up to six awards known as the Taiyang and Loong PhD Supplementary Scholarship (the Award). The objective/s of the Award are to encourage interest in computational biology, accelerate knowledge and skill development and cultivate an entrepreneurial research and learning environment for PhD students.', sc.`eligibility` = 'A domestic and/or international student; Have obtained first-class Honours, or equivalent in the field of computer science or a related discipline; Enrolling full-time in a program of study for the degree of Doctor of Philosophy at the ANU in the subject area of computational biology, with the John Curtin School of Medical Research; A recipient of an ANU approved HDR base stipend scholarship; Candidates must demonstrate keen interest in developing new computer science tools and applications that directly address real-world biomedical problems. PhD projects will focus on specific biological questions, with defined potential industry partners and computational areas.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/taiyang-and-loong-phd-supplementary-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/taiyang-and-loong-phd-supplementary-scholarship/4ae0ac5b0b41c7fa9948ab5559d25343', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Taiyang and Loong PhD Supplementary Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the John Curtin School of Medical Research, ANU College of Health and Medicine (JCSMR) may offer awards known as the Taiyang and Loong Innovator Grant (the Award) offered as part of the Talo Computational Biology Talent Accelerator Program. The objectives of the Award are to support PhD candidates and early-career researchers (up to five years post-PhD) for projects requiring proof-of-concept evidence of a new, promising computational technology. Funding for this Award has been provided by Taiyang Zhang and Loong Wang through the JCSMR Talo Computational Biology Talent Accelerator program.', sc.`eligibility` = 'The Award/s will be made available each year (subject to availability) to a continuing ANU PhD candidate or early-career researcher (up to five years post-PhD) undertaking a research project at JCSMR or in collaboration with a JCSMR research group.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/talo-computational-biology-talent-accelerator-innovator-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/talo-computational-biology-talent-accelerator-innovator-grant/e166221b07201512a6fc8e8cbe467647', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Talo Computational Biology Talent Accelerator Innovator Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the John Curtin School of Medical Research (JCSMR) (the School) in the ANU College of Health and Medicine(theCollege) may offer up to six awards known as the Talo Computational Biology Talent Accelerator Program Travel Grant (the Award). Funding for this Award has been provided by Taiyang Zhang and Loong Wang through the JCSMR Talo Computational Biology Talent Accelerator program. The objective of the Award is to fund short-term research placements in industry and external academic institutions to enable recipients engaged in computational biology affiliated with JCSMR to develop further research and translational expertise relevant to their field of study.', sc.`eligibility` = 'The Award is available each year to a continuing domestic or international ANU PhD student or Early Career Researcher (up to five years post-PhD) carrying out computational biology research affiliated with JCSMR.; Travel or research must be undertaken in the year the Award is granted.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/talo-computational-biology-talent-accelerator-program-travel-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/talo-computational-biology-talent-accelerator-program-travel-grant/126efe767907affe5dfc78553b241f9e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'Talo Computational Biology Talent Accelerator Program Travel Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The objective of the Award is to support and provide funding for a domestic or international candidate with financial need who is eligible for membership of the Institution of Engineers Australia to enable them to pursue a Master\'s program in Cybernetics at the School.', sc.`eligibility` = 'is a domestic student or international student; receives an offer of admission to the Master of Applied Cybernetics, College of Engineering, Computing and Cybernetics; is eligible for membership to the Institution for Engineers Australia.', sc.`scholarship_amount` = 'AUD $34000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/bill-hickson-engineers-australia-scholarship-master-applied', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-bill-hickson-engineers-australia-scholarship-for-the-master-of-applied-cybernetics/c66d3b72e253c0b0f6835a0aa2cfaf4d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'The Bill Hickson & Engineers Australia Scholarship for the Master of Applied Cybernetics' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This award is intended to aid coursework students undertaking research in the area of Space Exploration, Moon and Mars. Funding is provided by the Boswell Technologies Endowment fund, established by Prof Roderick Boswell. The award could be used towards travel, acquiring of equipment or collaboration activities.', sc.`eligibility` = 'a domestic and/or international student; enrolled full or part-time; be enrolled in a postgraduate or undergraduate program in the College of Science; undertaking a research project related to space exploration, moon and Mars.', sc.`scholarship_amount` = 'AUD $4000/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/boswell-technologies-grant-space-exploration-moon-and-mars', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-boswell-technologies-grant-for-space-exploration-moon-and-mars/00d573eec7f3526e16f81ffa76991c86', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'The Boswell Technologies Grant for Space Exploration, Moon and Mars' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This award is intended to aid higher degree research students undertaking research in the area of Space Exploration, Moon and Mars.\r\n\r\nFunding is provided by the Boswell Technologies Endowment fund, established by Prof Roderick Boswell.\r\n\r\nThe award could be used towards travel, acquiring of equipment or collaboration activities.', sc.`eligibility` = 'a domestic and/or international student; enrolled full or part-time; be enrolled in a Higher Degree Research program, (and in exceptional cases an undergraduate program) in the College of Science; undertaking a research project related to Space Exploration, Moon and Mars.', sc.`scholarship_amount` = 'AUD $4002/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/boswell-technologies-hdr-award-space-exploration-moon-and-mars', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-boswell-technologies-hdr-award-for-space-exploration-moon-and-mars/653bf1532610cf95651d0a41441f283e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'The Boswell Technologies HDR Award for Space Exploration, Moon and Mars' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Applications are invited for a PhD scholarship in Latin literature and/or Roman slavery. The scholarship is supported by the Australian National University (ANU) and is part of an Australian Research Council (ARC) Future Fellowship.   The Elephant in the Study: Working Latin Literature for the Enslaved is an ARC supported inquiry into the role and significance of enslaved co-authors in the production of Latin literature between approximately 100 BCE and 100 CE. The project will examine the implications of enslaved collaboration for the form, content and reception of classical Latin literature, and probe how such collaboration changes our notion of the histories of literature, authorship, and slavery.', sc.`eligibility` = 'Continuation based on academic performance; 6 month extension available.', sc.`scholarship_amount` = 'AUD $40475/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/elephant-study-working-latin-literature-enslaved-phd-scholarship-0', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-elephant-in-the-study-working-latin-literature-for-the-enslaved-phd-scholarship/51fcd5a2afd5d803e00d4b00206d5e01', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'The Elephant in the Study: Working Latin Literature for the Enslaved PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year the School of Literature, Languages and Linguistics may offer an award known as The Friends of the ANU Classics Museum Grant for Collection Research.  The objective of the Award is to support Honours and Master\'s students in one of the eligible specialisations listed below whose thesis research will include the study of objects in the collection of the ANU Classics Museum, especially their provenance and collection history.', sc.`eligibility` = 'The Award is available each year to a commencing or continuing ANU student who:; is a domestic or international student; receives an offer of admission to an Honours program or a Master’s program at the ANU College of Arts and Social Sciences in one of the following fields:; Classical Studies; Archaeology; Anthropology; Art History and Theory; History; Middle Eastern and Central Asian Studies; Museums and Collections; Museum Education and Heritage Interpretation; Intangible Cultural Heritage; any other field deemed relevant by the Selection Committee; will conduct research on the provenance and/or collection history of objects in the ANU Classics Museum.', sc.`scholarship_amount` = 'AUD $2000/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/friends-anu-classics-museum-grant-collection-research', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-friends-of-the-anu-classics-museum-grant-for-collection-research/d83f5ed529b9a98c2a38f3864b638a02', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'The Friends of the ANU Classics Museum Grant for Collection Research' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Each year, the School of Literature, Languages and Linguistics within the ANU College of Arts and Social Sciences may offer an award known as The Friends of the ANU Classics Museum Honours Grant in Classical Studies. The objective of the Award is to support Honours students in Classical Studies whose thesis research will include the study of objects in the collection of the ANU Classics Museum. Funding for this Award has been provided by The Friends of the ANU Classics Museum, established in 1985 to promote the interests of the Museum and to encourage interest in Ancient Greece and Rome in the wider community.', sc.`eligibility` = 'The Award is available each year to a commencing or continuing ANU student who: ; is a domestic or international student; receives an offer of admission to an Honours program in the field of Classical Studies at the ANU College of Arts and Social Sciences; will study objects in the collection of the ANU Classics Museum as part of their thesis research.', sc.`scholarship_amount` = 'AUD $2000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/friends-anu-classics-museum-honours-grant-classical-studies', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-friends-of-the-anu-classics-museum-honours-grant-in-classical-studies/c424eb1a0465fef48ff4d2684df2df40', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'The Friends of the ANU Classics Museum Honours Grant in Classical Studies' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Knight-Hennessy Scholars cultivates and supports a multidisciplinary and multicultural community of graduate students from across Stanford University, and delivers engaging experiences that prepare graduates to be visionary, courageous, and collaborative leaders who address complex challenges facing the world. Scholars participate in up to three years of programming that complements their graduate studies and prepares them to take on leadership roles in academia, industry, government, nonprofits, and the community at large.', sc.`eligibility` = 'Please Contact ANU for more information about Eligibility', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://study.anu.edu.au/scholarships/find-scholarship/knight-hennessy-scholars-program', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-knight-hennessy-scholars-program/9a36eb520ad82eba80c7d7b3ae277aa7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00120C' AND sc.`scholarship_name` = 'The Knight-Hennessy Scholars program' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship supports outstanding students from African countries to pursue their academic goals at RMIT University in Melbourne, Australia.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of countries in Africa; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; achieve Australian equivalent grade GPA of 2.5 or 70% average or ATAR 75 in your qualifying qualification at the time of application; hold a full or conditional offer letter commencing in 2026 or later in Vocational Education, Associate Degree*, Bachelor’s degree*, Graduate Certificate, Graduate Diploma or Masters by Coursework program; not be an existing RMIT University student (existing ELICOS or Foundation Studies may qualify and will be notified after Foundation Studies completion).', sc.`scholarship_amount` = 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible program(s)* as outlined in your offer letter.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/academic-merit-scholarship-africa', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-merit-scholarship-for-africa/d6a2a3a3f3c753cbedfe7cb4a0857a17', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Academic Merit Scholarship for Africa' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship supports outstanding students from Brunei Darussalam, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Timor-Leste or Vietnam to pursue their academic goals at RMIT University in Melbourne, Australia.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of Brunei Darussalam, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Timor-Leste or Vietnam; be applying offshore from Brunei Darussalam, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Timor-Leste or Vietnam (RMIT Vietnam students who completed cross-campus studies and immediately apply for the same qualification (course) in Melbourne campus are not eligible); be an international student holding a valid student visa or plan to apply for a student visa prior to the course commencement; achieve Australian equivalent grade GPA of 2.5 or 70% average or ATAR 75 in your qualifying qualification at the time of application; hold a full or conditional offer letter to commence studies in Vocational Education, Associate Degree*, Bachelor’s degree*, Graduate Certificate, Graduate Diploma or Masters by Coursework degree; not be an existing RMIT University student (existing ELICOS or Foundation Studies may be qualified and will be notified after Foundation Studies completion).', sc.`scholarship_amount` = 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible course(s)* as outlined in your offer letter.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/academic-merit-scholarship-southeast-asia#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-merit-scholarship-for-south-east-asia/c4ebbacce3c2c99cc8e6c57414bed5b6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Academic Merit Scholarship for South East Asia' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship provides financial assistance to outstanding students from Vietnam.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of Vietnam and be applying offshore from Vietnam (RMIT Vietnam students who completed cross-campus studies and immediately apply for the same qualification (program) in Melbourne campus are not eligible); be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; achieve Australian equivalent grade GPA of 3.0 or 75% average in your qualifying qualification at the time of application; hold a full or conditional offer letter to commence studies in Bachelor’s degree, Graduate Certificate, Graduate Diploma or Masters by Coursework programs offered by: School of Accounting, Information Systems and Supply Chain, School of Economics, Finance and Marketing, School of Management; not be an existing RMIT University student (existing ELICOS or Foundation Studies may be qualified and will be notified after Foundation Studies completion).', sc.`scholarship_amount` = '25% tuition fee reduction for the eligible program(s) duration outlined on your offer letter.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/cobl-academic-merit-scholarships-for-vietnam#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/cobl-academic-merit-scholarships-for-vietnam/2b3803b7ff25e436eb7936867ddc405f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'COBL Academic Merit Scholarships for Vietnam' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This bursary provides financial assistance to international students studying in the College of Design and Social Context (DSC).', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be an international student holding a valid student visa or plan to apply for a student visa prior to the commencement of your degree; have existing offer letter (full or conditional offer) and be a commencing student in:; Semester 2 2026 intake in any College of Design and Social Context course (excluding Master by Research or PhD); Semester 3 2026 intake for Master of Project Management, Master of Energy Efficient and Sustainable Building; achieve Australian equivalent grade GPA of 2.0 or 60% average or ATAR 60 in your qualifying qualification at the time of application; not be an existing RMIT student (including RMIT Vietnam students); not be receiving another RMIT-funded scholarship or external sponsorship covering tuition fees', sc.`scholarship_amount` = 'Up to AUD $5000 — The total value of the bursary is a AU$5,000, one-off payment towards future tuition fees to be paid after the first census date into student\'s university account.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/college-of-design-and-social-context-student-bursary#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/college-of-design-and-social-context-student-bursary/a4f0b0c43be03f6b561534343be3bb84', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'College of Design and Social Context Student Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you plan to study an English language pathway to either an RMIT Foundation Studies or Fast Track program in 2027, you may qualify for our English to Foundation Studies/Fast Track Pathway Bursary.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be studying Academic English and plan to progress to an RMIT Foundation Studies or Fast Track program in 2027; be an offshore offshore students from one of the following regions:; China: Mainland and Hong Kong SAR; South-East Asia: Myanmar, Malaysia, the Philippines and Indonesia', sc.`scholarship_amount` = '10% of the tuition fee for Academic English.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/english-pathway-bursary#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/english-to-foundation-studiesfast-track-pathway-bursary/7575029365164d1de7815f7c105845db', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'English to Foundation Studies/Fast Track Pathway Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'RMIT welcomes students who have scholarship funded by their home government (sponsored students). RMIT currently has over 800 sponsored students. They are enrolled in a wide range programs in all study levels. Prospective sponsored students need to make their own enquiries about scholarship opportunities available within their home country or about potential sponsorship opportunities (such as funding from your employer to study in RMIT).', sc.`eligibility` = 'Please contact RMIT for further information via isscholarships@rmit.edu.au.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/external-scholarships-sponsorship/217a3888b1c86f6fdf4076e50f839a01', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'External Scholarships (Sponsorship)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you are an international student from Mexico applying for a Masters by Coursework program at RMIT University, you may be eligible for this jointly funded scholarship by RMIT and the Mexican Foundation for Education, Technology and Science (FUNED).', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of Mexico; have applied for a Masters by Coursework at RMIT; satisfy the general and specific requirements of the FUNED credit scholarship; meet the academic requirements for entry to RMIT and have been given an unconditional offer of a place in the program; have been awarded the FUNED credit scholarship; be commencing full time enrolment as an international student at RMIT in Melbourne.', sc.`scholarship_amount` = 'Up to AUD $12000 — RMIT UP Academic English Bursary for Latin American students if you are required to study ELICOS; tuition fee support by RMIT to the value of 25% of the tuition fees for Masters by Coursework program for a maximum of two years.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/funed-rmit-scholarship#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/funed-rmit-scholarship/d5f28687a45f8e471ca15ff3f7ccf446', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'FUNED - RMIT Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship provides financial assistance to high achieving Fast Track University Pathway international students.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; have existing offer letter (full or conditional offer) and be a commencing student in Semester 2 2027 intake in any stream of Fast Track University Pathways program', sc.`scholarship_amount` = 'Up to AUD $5000 — The total value of the scholarship is a AU$5,000, one-off payment towards future tuition fees to be paid after the first census date into student\'s university account.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/fast-track-university-pathway-academic-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/fast-track-university-pathway-academic-scholarship/56375cbc569ed634d3d9a4e8d5269a1d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Fast Track University Pathway Academic Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship provides financial assistance to high achieving Foundation Studies international students.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; have existing offer letter (full or conditional offer) and be commencing student in either Semester 1 or Semester 2 2027 intake in any stream of Foundation Studies program', sc.`scholarship_amount` = 'Up to AUD $5000 — The total value of the scholarship is AU$5,000, one-off payment towards future tuition fee to be paid after the first census date into student\'s university account.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/foundation-academic-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/foundation-academic-scholarships/799e1e8b4fcb86d16b89d9c20b95755f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Foundation Academic Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Provides students from India and the subcontinent with a 20% tuition fee reduction for eligible Bachelor and Masters programs that have received an offer from 2026.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of India, Sri Lanka, Bangladesh, Bhutan, Nepal or Pakistan (including dual citizenship holding one of these country\'s passport); be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; have an offer letter to commence from 2026 intakes onwards in one of the following programs at RMIT: Bachelor degree, Masters by Coursework; not be an existing student who commence in another program within the same study level', sc.`scholarship_amount` = 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible program(s)* as outlined in your offer letter.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/future-leaders-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/future-leaders-scholarship/b5c7348d68d65c7feaaa58c6da528204', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Future Leaders Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'For students enrolled in the Bachelor of Fine Arts program who can demonstrate artistic merit and circumstances which impact their study worth up to $1,300.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident or an international student who has resided in Australia for at least two years; be enrolling full-time in Semester 1 and 2 in your second or third year of the Bachelor of Fine Arts (BP201) at RMIT in 2027; be able to demonstrate circumstance(s) that impact your ability to study, or be from an RMIT priority group.', sc.`scholarship_amount` = 'Up to AUD $1300', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/coursework/gavin-teague', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/gavin-teague-memorial-scholarship/00bb801d06053d9be644b22c11010734', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Gavin Teague Memorial Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Medibank Excellence Scholarship is available to international students studying Australian Year 12 or International Baccalaureate in Australia. In addition to receiving AU$12,000 successful applicants will have the opportunity to attend Medibank workshops, participate in event-coordination for Medibank on Open Day, meet recent graduates working at Medibank, and be involved in a customer focus group.', sc.`eligibility` = 'In order to qualify for this scholarship, you must:; be applying from Australia; be a current year 12 student in Australia graduating in 2026; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; submit your application via VTAC and receive an offer from RMIT for an Associate degree or Undergraduate degree; not be an existing RMIT student.', sc.`scholarship_amount` = 'Up to AUD $12000 — The total value of the scholarship is AU$12,000, to be paid to recipient\'s Australian bank account in AU$6,000 installments after the census date of each semester of the first year.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/medibank-excellence-scholarship#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/medibank-excellence-scholarship/bda799bcfae582af445fda7a51dec7bb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Medibank Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship, valued at AU$20,000, is available to international students studying Australian Year 12 or International Baccalaureate in Australia.', sc.`eligibility` = 'In order to qualify for this scholarship, you must:; be applying from Australia; be a current year 12 student in Australia graduating in 2026; be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; submit your application via VTAC and receive an offer from RMIT for an Associate degree or Undergraduate degree; not be an existing RMIT student.', sc.`scholarship_amount` = 'Up to AUD $20000 — The total value of the scholarship is AU$20,000, to be paid to recipient\'s Australian bank account in AU$10,000 installments after the census date of each semester of the first year.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/medibank-high-achiever-international-scholarship#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/medibank-high-achiever-international-scholarship/9b727152663ae97c96185362ffea0e9d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Medibank High Achiever International Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship supports students from China to study a Bachelor program at RMIT University in Melbourne, Australia.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of the People\'s Republic of China (including Hong Kong SAR and Macau SAR); be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; hold a Bachelor* offer commencing in 2026 or later that is packaged with ELICOS, Foundation Studies or Fast Track University Pathway, a Vocational Education (VE), or Associate Degree program. Students who have a packaged offer and are currently enrolled or recently completed a pathway program(s) will be eligible.; not be an existing RMIT University student studying a Bachelor program', sc.`scholarship_amount` = 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible Bachelor program(s) as outlined in your offer letter.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/pathway-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/pathway-scholarship-for-china/29a20b3e33c9cf077ecae8e3491b0da9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Pathway Scholarship for China' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'For students enrolled full-time in the ELICOS English for Academic Purposes (EAP) Program who can demonstrate hardship; worth $5,000.', sc.`eligibility` = 'Applicants must: have been born overseas; have recently migrated to Australia; be from a non-English speaking background; have an Australian bank account; be enrolling full-time in RMIT English Worldwide’s ELICOS Academic English Program EL000 with the course start date typically at the end of August in the year of award. See website for full criteria.', sc.`scholarship_amount` = 'Up to AUD $5000 — This scholarship provides $5,000 as a one-off payment. A short student report must be completed before payment is made to the successful recipient.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/coursework/david-phillips', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rmit-david-phillips-memorial-scholarship/d2ec6bbb95a42533d1bc38a55330b012', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'RMIT David Phillips Memorial Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'For 2025 and 2026 commencement: 35% of the total program fee for an ELICOS program (you pay $355 per week after the discount)', sc.`eligibility` = 'be a citizen of Latin America countries; applying from Australia or overseas; enrol in an English for Academic Purposes program at RMIT University Pathways (RMIT UP) commencing in 2025 or 2026; be a commencing RMIT UP student (including extending your program in Australia).For further information contact RMIT via isscholarships@rmit.edu.au', sc.`scholarship_amount` = '35% of the total program fee for an ELICOS program (you pay $338 per week after the discount)', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Languages', sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-english-bursary-for-latin-american-students', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rmit-english-language-bursary-for-latin-american-students/475b48e53aeac5761f333d81f6e302ae', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'RMIT English Language Bursary for Latin American Students' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'For Thailand born students studying full-time in an undergraduate or postgraduate by coursework program who can demonstrate circumstances which impact their study; worth up to $10,000.', sc.`eligibility` = 'Applicants must: have been born in Thailand; be an Australian or New Zealand citizen, Australian permanent resident or permanent humanitarian visa holder, asylum seeker or an international student; be enrolling full-time in an associate or bachelor degree, a graduate certificate, graduate diploma or a masters by coursework program at RMIT University; be able to demonstrate circumstance/s which impact your ability to study or be from an under-represented background such as current/former refugee; be residing in Australia. See website for full eligibility criteria.', sc.`scholarship_amount` = 'Up to AUD $30000 — This scholarship provides up to $10,000 for one year ($5,000 per semester).', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/coursework/bush', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rmit-john-bush-memorial-scholarship/3a785f30cc5138b5f234712fe4577486', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'RMIT John Bush Memorial Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'For commencing first-year students who are passionate about business, law or construction/project development, and who can demonstrate circumstances which impact their study; worth up to $50,000.', sc.`eligibility` = 'Applications must: be an Australian citizen, Australian permanent resident, permanent humanitarian visa holder or international student visa holder; commencing first year in a Bachelor of Business, Bachelor of Business Professional, Bachelor of Commerce, Bachelor of Laws, Bachelor of Property Development, Investment and Valuation (Honours) or a Bachelor of Construction Management (Honours); be able to demonstrate circumstance/s which impact your ability to study or be from an under-represented background such as a current/former refugee. Visit website for full eligibility criteria.', sc.`scholarship_amount` = 'Up to AUD $50000 — The scholarship provides $10,000 per year for the standard duration of program.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Built environment, Business and management, Law', sc.`website` = 'https://www.rmit.edu.au/scholarships/coursework/mai-foundation', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rmit-mai-foundation-scholarship/ae3c50f1e28f2f8c5490f3d6ad0ceb30', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'RMIT MAI Foundation Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you are a citizen of Cambodia, Japan, Laos, South Korea, Taiwan, Thailand or Vietnam this bursary provides a tuition fee discount on your Academic English course.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of Cambodia, Japan, Laos, South Korea, Taiwan, Thailand or Vietnam; applying from Australia or overseas; enrol in an Academic English course at RMIT University Pathways (RMIT UP) commencing in 2026 or 2027 for 10 weeks or more; not be the recipient of any other English Language scholarship (including external scholarships); be a commencing RMIT UP student (including extending your program in Australia).', sc.`scholarship_amount` = '10% of the total program fee in 2026 study period for an Academic English course (you pay $491 per week after the discount); 20% of the total program fee in 2027 study period for an Academic English course (you pay $452 per week after the discount)', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-english-bursary-for-asia#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rmit-up-academic-english-bursary-for-asia/e23775d1b6c08ef32f6529c7f3b749e6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'RMIT UP Academic English Bursary for Asia' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you are a citizen of a Latin American country, Spain or Türkiye this bursary provides a tuition fee discount on your Academic English course.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of Latin America countries, Spain or Türkiye; applying from Australia or overseas; enrol in an Academic English course at RMIT University Pathways (RMIT UP) commencing in 2026 or 2027; be a commencing RMIT UP student (including extending your program in Australia).', sc.`scholarship_amount` = '35% of the total program fee for an Academic English course (you pay $355 per week after the discount); 40% of the total program fee for an Academic English course (you pay $339 per week after the discount)', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-english-bursary-for-latin-american-students#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rmit-up-academic-english-bursary-for-latin-america-spain-and-turkiye/6011ba21b73e30f5349c92358cc8381e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'RMIT UP Academic English Bursary for Latin America, Spain and Türkiye' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you are a citizen of Japan, South Korea, Taiwan or Thailand this bursary provides a tuition fee discount on your General English language course.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be citizen of Japan, South Korea, Taiwan or Thailand; be applying from Australia or overseas; enrol in a General English course at RMIT University Pathways (RMIT UP) commencing in 2026 or 2027 for 10 weeks or more; not be the recipient of any other English Language scholarship (including external scholarships); be a commencing RMIT UP student (including extending your course in Australia).', sc.`scholarship_amount` = 'For 2026 commencement: 20% of the total fee in 2026 study period for the General English course., You pay $436 per week after the discount. For 2027 commencement: 20% of the total fee in 2027 study period for the General English course., You pay $452', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-up-general-english-bursary-for-asia', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rmit-up-general-english-bursary-for-asia/3ed9fa68865a1b3041c913ade5d2c8ae', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'RMIT UP General English Bursary for Asia' AND sc.`course_id` IS NULL;
