UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This top-up scholarship program is available to talented Vietnamese students aims to address Vietnam\'s future industry and workforce needs, prioritising key research areas such as digital technologies, physics, biotechnologies and energy & environment.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of Vietnam; have an offer for a PhD program at RMIT; be nominated to receive the Vietnam government scholarship (Project 89); commence full-time enrolment as an onshore international student at RMIT in Melbourne', sc.`scholarship_amount` = 'a tuition fee scholarship of up to $25,000 USD; a stipend scholarship of $1,120 USD per month; an international return airfare and travel allowances; Overseas Student Health Cover (OSHC) for the time spent in Australia (up to $1,000 USD per year).', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/vietnam-government-project-89-rmit-scholarship#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rmit-university-top-up-scholarship-for-vietnam-government-project-89/a94967c86db3e1c7d38995242b6601e1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'RMIT University Top-up Scholarship for Vietnam Government (Project 89)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is awarded to RMIT Vietnam alumni who will commence Master by Coursework program at RMIT Australia.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be alumni who completed a degree at an RMIT Vietnam campus. This can include:; an undergraduate degree or postgraduate degree (including those who undertake exchange for up to 1 year in RMIT Melbourne campuses); packaged RMIT Vietnam Undergraduate and RMIT Melbourne Postgraduate offer holders; have an offer letter and enrol in one of Masters by Coursework program at RMIT Australia.', sc.`scholarship_amount` = '10% tuition fee reduction for the program duration outlined on your offer letter.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/rmit-vietnam-alumni-postgraduate-scholarship#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/rmit-vietnam-alumni-postgraduate-scholarship/f932be51645d920b03c37898ca03674b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'RMIT Vietnam Alumni Postgraduate Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Sallie Mae Student Loans can be used for tuition fees and material fees associated with your course.', sc.`eligibility` = 'The availability of the Sallie Mae loan is dependant on the course, campus and study load you select.', sc.`scholarship_amount` = 'The loan amount you can apply for is capped by the ‘cost of attendance’, which is calculated by RMIT. The cost of attendance includes tuition fees and living expenses for an academic year. The loan amount is distributed in two equal payments, paid ou', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/us-financial-aid', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/sallie-mae-private-student-loans/7154dff7fe8d896ddd5014841222a498', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'Sallie Mae private student loans' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'For art honours students who can demonstrate outstanding academic achievement; worth up to $4,000.', sc.`eligibility` = 'To be eligible for this grant you must:; be enrolled full-time in Semester 1 and 2 in 2026, in either the:; Bachelor of Arts (Fine Art) (Honours) (BH052); Bachelor of Arts (Photography) (Honours) (BH125); have achieved high distinction or distinction grades during Semester 1 2026; be undertaking travel related to your art/studio practice; submit your own original art works with your application', sc.`scholarship_amount` = 'Up to AUD $4000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/coursework/school-art-travel', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/school-of-art-honours-travelling-grant/1014804555fd213fd8719f8ab5092156', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'School of Art Honours Travelling Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship supports outstanding students from China to pursue their academic goals in education or teaching discipline at RMIT University in Melbourne, Australia.', sc.`eligibility` = 'In order to qualify for this scholarship you must:; be a citizen of the People’s Republic of China (including Hong Kong SAR and Macau SAR); be an international student holding a valid student visa or plan to apply for a student visa prior to the program commencement; achieve Australian equivalent grade GPA of 2.5 or 70% average or ATAR 75 in your qualifying qualification at the time of application; hold a full or conditional offer letter in one of the eligible programs: Bachelor of Education, Master of Teaching Practice (Primary Education), Master of Teaching Practice (Secondary Education); not be an existing RMIT University student studying one of the eligible programs.', sc.`scholarship_amount` = 'The value of the scholarship is a 20% tuition fee reduction for the duration of the eligible program(s) as outlined in your offer letter.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.rmit.edu.au/scholarships/international-scholarships/school-of-education-academic-merit-scholarship#overview', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/school-of-education-academic-merit-scholarship-for-china/582d3047521e1078e71bb993a1623764', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00122A' AND sc.`scholarship_name` = 'School of Education Academic Merit Scholarship for China' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The 2026 VU Sydney and VU Brisbane Diversity Scholarship provides an additional 10% tuition fee reduction for students enrolling in our undergraduate, postgraduate, and higher education diploma programs in IT and Business. This 10% reduction is offered on top of the 2026 VU Sydney and Brisbane International Scholarship, which provides a 22.5% tuition fee discount. This scholarship is available to international students (both offshore and onshore) from designated diverse regions who commence their studies at VU Sydney or VU Brisbane in 2026.', sc.`eligibility` = 'The scholarship is available all international students commencing an undergraduate or postgraduate courses (including ELSIS EAP packages) at VU Sydney or VU Brisbane who is a citizen of one of the following regions/ countries.', sc.`scholarship_amount` = '10% reduction of the course tuition fee the duration of the course. (Applied in addition to the 22.5% VU Sydney and Brisbane 2026 International Scholarship)', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-vu-sydney-brisbane-global-diversity-scholarship/b7fd495dbbf2ea0f5f15159d3f66ae7f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00124K' AND sc.`scholarship_name` = '2026 VU Sydney & Brisbane Global Diversity Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Australia Awards scholarships are long-term development awards, offered by the Australian Government and administered by the Department of Foreign Affairs and Trade (DFAT). They aim to contribute to the long-term development needs of Australia\'s partner countries.', sc.`eligibility` = 'Citizen of a participating country, all study levels, Please Contact Victoria University for more information.', sc.`scholarship_amount` = 'Tuition fees, living allowance, Overseas Student Health Cover and academic support.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarships/19bf9630a38d6462cbd0b9a888376bef', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00124K' AND sc.`scholarship_name` = 'Australia Awards Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The 2025 Early Childhood Education International Scholarship supports new international students who plan to commence an Early Childhood Education course in 2025. \r\n\r\nDo not miss this incredible opportunity to get a world-class qualification from a globally ranked university!', sc.`eligibility` = 'All new international students commencing a course in Early Childhood Education at VU Sydney or Brisbane in 2025 are eligible for the scholarship.', sc.`scholarship_amount` = '-Graduate Diploma in Early Childhood Education (EGEC): 20% tuition fee reduction for the entire standard duration of eligible courses (calculated from the date of commencement to the course end date in the letter of offer). – Only applicable for Febr', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/early-childhood-education-international-scholarship-2025/58c7f915169bf8c2bf1f1aa70fbf0c7b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00124K' AND sc.`scholarship_name` = 'Early Childhood Education International Scholarship (2025)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Enjoy a stress-free start to your studies and save up to $15,500 with the unique STEM Accommodation Scholarship at Victoria University (VU).  Our exciting merit-based scholarship offers eligible international students free accommodation at UniLodge Victoria University for up to your entire first year of study. Scholarships will be awarded to select offshore international applicants for science, engineering and information technology degrees offered at VU Melbourne, particularly at our Footscray Park Campus, the main hub of our STEM-related courses. Limited scholarships are available for the July and September intakes in 2025, as well as February 2026. Eligibility is assessed on merit, based on previous academic results. With scholarships awarded on a first-come, first-served basis to eligible students, apply now for the best chance of success!', sc.`eligibility` = 'In order to be eligible for this scholarship, you must be an international student applying to VU from outside Australia and meet the entry requirements for one of the following STEM-related course:; Bachelor of Architectural Design; Bachelor of Biomedical Science; Bachelor of Biomedical and Exercise Science; Bachelor of Construction Management (Honours); Bachelor of Cyber Security; Bachelor of Data Science; Bachelor of Dermal Sciences; Bachelor of Information Technology; Bachelor of Information Technology (Professional); Bachelor of Engineering (Honours) (Civil Engineering); Bachelor of Engineering (Honours) (Electrical and Electronic Engineering); Bachelor of Engineering (Honours) (Mechanical Engineering); Bachelor of Exercise Science (Clinical Practice); Bachelor of Exercise Science (Sport Practice); Bachelor of Health Science; Bachelor of Sport Science; Bachelor of Sport Science (Human Movement) / Bachelor of Sport Management; Bachelor of Sport Science (Human Movement) / Bachelor of Psychological Studies; Master of Applied Information Technology; Master of Clinical Exercise Science and Rehabilitation; Master of Construction Management; Master of Project Management; Priority will be given to applicants with a strong academic background. Limited scholarships are available for Semester 2, Block 1 (July), 2025, Semester 2, Block 3 (September), 2025, and Semester 1, Block 1 (February), 2026, so apply as soon as you can; We strongly encourage applications from female students as part of our commitment to closing the gender gap in STEM. Please note: you must be over 18 years old when you start your VU studies in order to be eligible for this scholarship.', sc.`scholarship_amount` = 'Successful undergraduate applicants will receive one year (52 weeks) of free accommodation at UniLodge VU, valued at $15,548. / Successful postgraduate applicants will receive six months (26 weeks) of free accommodation at UniLodge VU, valued at $8,5', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/stem-accommodation-scholarship/0748f0863d6b0ae158cf0aee70028610', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00124K' AND sc.`scholarship_name` = 'STEM Accommodation Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'At Victoria University (VU), were committed to supporting your success. Our unique VU Block Model® International Scholarship offers all eligible international students up to 30% off tuition fees for the entire first year. Study well and youll have the chance to keep or increase the scholarship for the full duration of your course. VU is a world-class university, renowned for our inclusive environment, industry connections and innovative approach to education. Our award-winning VU Block Model teaching method will allow you to achieve your best, studying one or two subjects at a time in small, interactive classes.', sc.`eligibility` = 'New international students commencing a foundation, higher education diploma, undergraduate or postgraduate (coursework) course with VU Melbourne in 2025 are eligible for the scholarship. You must also meet the course entry requirements. English courses, VET and Research courses are not eligible for this scholarship. Sponsored students are not eligible for the scholarship.To be eligible to continue receiving the scholarship in subsequent years, you will need to complete 96 credit points each year and achieve the following WAM:50% WAM: 10% scholarship70% WAM: 20% scholarship80% WAM: 30% scholarshipThe value of the VU Block Model® International Scholarship will vary for students in certain circumstances. Please see the Eligibility Exceptions section below for further information', sc.`scholarship_amount` = 'Up to 30% off your first year tuition fees – based on merit. Study well and youll have the chance to keep or increase the scholarship for the full duration of your course.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships/vu-block-model-international-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vu-block-model-international-scholarship/f9b97fcda6a91a6a47fa7331a978ab5c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00124K' AND sc.`scholarship_name` = 'VU Block Model International Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'At Victoria University (VU), we’re committed to empowering the next generation of research leaders. Our exciting new VU Global Research Scholarship offers eligible international students 20% off tuition fees for the entire duration of a masters by research degree. With state-of-the-art facilities and an outstanding research profile, VU is the ideal place to commence your research career. You’ll benefit from expert supervision, comprehensive support and a vibrant academic community. Our world-class researchers are proud of the positive impact their work has locally, nationally and globally. Choose from our tailored masters degrees, designed for students with different levels of research experience, and join our welcoming team to achieve your academic ambitions.', sc.`eligibility` = 'Please contact Victoria University for more information about Eligibility Criteria.', sc.`scholarship_amount` = 'The VU Global Research Scholarship is valued at 20% off tuition fees for the entire duration of your masters by research degree at Victoria University.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vu-global-research-scholarship/b854afc113728b62f9328bf623d08b1f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00124K' AND sc.`scholarship_name` = 'VU Global Research Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The VU Sydney & Brisbane 2026 International Scholarship provides students with up to a 22.5% reduction in tuition fees. Students commencing our undergraduate, postgraduate and higher education diploma programs are eligible for this scholarship. The Scholarship is open to all international onshore and offshore students who are commencing with VU Sydney and Brisbane in 2026 and who meet the entry requirements.', sc.`eligibility` = 'All new students commencing an undergraduate or postgraduate (coursework) course (including ELSIS EAP packages) with VU Sydney in 2025 are eligible. Please refer to terms and conditions below.', sc.`scholarship_amount` = '22.5% off the course tuition fees for the full course duration.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vu-sydney-brisbane-2026-international-scholarship/c42394de7a9075a6e908163f63c0e469', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00124K' AND sc.`scholarship_name` = 'VU Sydney & Brisbane 2026 International Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Ready to return to Murdoch to achieve your postgraduate degree? As an alumnus you\'re an important part of our community, so to help support your study goals we\'re offering a 10% reduction in postgraduate fees on eligible courses.', sc.`eligibility` = 'Please Contact Murdoch University for more information.', sc.`scholarship_amount` = '10% tuition fee deduction', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.murdoch.edu.au/study/scholarship/alumni-10-fee-tuition-discount', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alumni-10-fee-tuition-discount/81c9da54a7b3d00892101f5130e774c5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00125J' AND sc.`scholarship_name` = 'Alumni 10% Fee Tuition Discount' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Have you recently joined our alumni community and are ready to start postgraduate study? To help support your goals, we’re offering a 25% reduction in postgraduate fees if you’ve finished your undergraduate or Masters level degree in the past 12 months and are transitioning into an eligible postgraduate course (excludes Honours) in the next available teaching period.​', sc.`eligibility` = 'Please Contact Murdoch University for more information.', sc.`scholarship_amount` = '25% tuition fee deduction', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.murdoch.edu.au/study/scholarship/alumni-25-fee-tuition-discount', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alumni-25-fee-tuition-discount/73716f1cba8becfb38dd6c2b9bcba70f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00125J' AND sc.`scholarship_name` = 'Alumni 25% Fee Tuition Discount' AND sc.`course_id` IS NULL;
