UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Award primarily supports travel costs to attend a conference or meeting where papers and/or seminars relevant to veterinary anaesthesia and / or analgesia are presented, which ultimately, will be helpful for examination preparation.', sc.`eligibility` = 'Must be a resident or registrar employed by Murdoch University learning in the subject disciplines of veterinary Anaesthesia and / or analgesia.; Must travel in the following academic year; Must not have been in receipt of this award previously', sc.`scholarship_amount` = 'Up to AUD $2500', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.murdoch.edu.au/study/scholarship/len-cullen-veterinary-anaesthesia-2027-award', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/len-cullen-veterinary-anaesthesia-2027-award/fa4f6edaea96d5798ef91f7f5a747937', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00125J' AND sc.`scholarship_name` = 'Len Cullen Veterinary Anaesthesia 2027 Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Murdoch is offering a 30% fee reduction scholarship for international students who have been awarded the Mauritian Laureate Additional Scholarship Scheme by the Mauritian Ministry of Education, Tertiary Education, Science and Technology.', sc.`eligibility` = 'You are eligible to receive the above scholarship if you meet all the following requirements:; you are an international, full-fee-paying student.; you are starting studies at one of Murdoch’s Western Australian campuses from 2025 onwards.; you are starting studies for an eligible Murdoch coursework degree set out below.; you have been awarded scholarship under the Mauritian Laureate Additional Scholarship Scheme by the Mauritian Ministry of Education, Tertiary Education, Science and Technology.; you are not a fully sponsored student by the Government of Mauritius - students who receive full sponsorship covering all expenses (university tuition fees, flights, accommodation and living allowance).; you are not receiving any other Murdoch scholarship.', sc.`scholarship_amount` = '30% discount', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.murdoch.edu.au/study/scholarship/murdoch-university-30--scholarship-for-mauritian-laureate-additional-scholarship-scheme', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/murdoch-university-30-scholarship-for-mauritian-laureate-additional-scholarship-scheme/73a7449228b45c1829c3ed51ab2294b8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00125J' AND sc.`scholarship_name` = 'Murdoch University 30% Scholarship for Mauritian Laureate Additional Scholarship Scheme' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Graduate Research Office is pleased to announce that the 2025 scholarship round opens in July 2025. Scholarships are awarded on academic merit, research experience and/or potential.', sc.`eligibility` = 'Applicants must be full time and meet the admission requirements of the required HDR degree to be eligible (first or upper second-class Honours degree, Masters degree by research, or equivalent).; Applicants must possess a First Class Honours degree, H2A (or equivalent) or a Masters with a significant thesis component.', sc.`scholarship_amount` = 'AUD $37000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.murdoch.edu.au/study/scholarship/research-training-program-stipends-(international-students)', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-training-program-stipends-international-students/2fafcec05ab9fbe87b09e7524e313fe9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00125J' AND sc.`scholarship_name` = 'Research Training Program Stipends (International students)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Murdoch is offering a 25% fee reduction scholarship for TNE Students following your transfer from Murdoch Singapore, Murdoch Dubai or Murdoch Malaysia to one of Murdoch’s Western Australian campuses (Local Campus), and commencing studies at the Local Campus.', sc.`eligibility` = 'You are eligible to receive this scholarship if you meet all the following requirements:; you are a student transferring your studies from Murdoch Singapore, Murdoch Dubai or Murdoch Malaysia to one of Murdoch’s Western Australian campuses (Local Campus), and commencing studies at the Local Campus in 2026; you will be studying an eligible course at the Local Campus; you do not fall within any of the exclusions', sc.`scholarship_amount` = '25% tuition fee reduction', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.murdoch.edu.au/study/scholarship/tne-transfer-scholarship-2026', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/tne-transfer-scholarship-2026/1ece19983305389bc9315c57bd202c01', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00125J' AND sc.`scholarship_name` = 'TNE Transfer Scholarship 2026' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Buru Energy Limited have donated the sum funds to The University of Western Australia (the University) to provide scholarships to support female students undertaking research and studies in petroleum geoscience.', sc.`eligibility` = 'female; enrolled or eligible to enrol in either; an honours course in geology or; a masters by thesis and coursework degree course in geoscience or petroleum geoscience and; undertaking research and studies in the field of petroleum geoscience.', sc.`scholarship_amount` = 'Up to AUD $10000 — Value$10,000.00', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Sciences', sc.`website` = 'https://www.uwa.edu.au/study/scholarship-listing/buru-energy-scholarship-for-women-in-petroleum-geoscience-f512241', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/buru-energy-scholarship-for-women-in-petroleum-geoscience/9bd709079f0b3dcea5ba793fcfdd30cf', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'Buru Energy Scholarship for Women in Petroleum Geoscience' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Verna Rowbotham has bequeathed funds to The University of Australia (the University) to provide a scholarship to assist and encourage a high-achieving student to continue their undergraduate studies with a major in Environmental Science, Conservation Biology, Marine Science or Geographical Sciences at the UWA Albany campus. Verna, a UWA alumna, maintained a lifelong association with UWA, firstly through the work of her father Professor Alexander Ross, the founding professor in physics and mathematics, and then through her own support and life membership of the Friends of the UWA Albany Centre.', sc.`eligibility` = 'Please Contact The University of Western Australia for more information about Eligibilty.', sc.`scholarship_amount` = 'Up to AUD $5000 — Value$5,000.00', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Environmental studies, Sciences', sc.`website` = 'https://www.uwa.edu.au/study/scholarship-listing/friends-of-uwa-albany-verna-rowbotham-scholarship-f826601', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/friends-of-uwa-albany-verna-rowbotham-scholarship/0aa91196685d53a7fe0f8b29065e7d26', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'Friends of UWA Albany Verna Rowbotham Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'We are looking to recruit up to three PhD students through the recently awarded Industry Fellowship for the Integrative geophysics Under cover: getting images of the Unknown Unknown project, supported by the Australia Research Council, the University of Western Australia (UWA), the Geological Survey of Western Australia (GSWA), and the Commonwealth Scientific and Industrial Research Organisation (CSIRO). The goal of the project is to develop and extend new algorithms for integrating geophysical and geological data in undercover exploration scenarios at different scales, with applications to idealised and real-world data from Western Australia provided by GSWA. The methods to be investigated include geometrical (geophysical) inversion, trans-dimensional inversion, multi-physics integration, the integration of geophysical inversion with geological modelling.', sc.`eligibility` = 'Skills in geophysics/physics, and/or numerical geology, and capability to code are essential.; Willingness to learn is a requirement. The capability to work in a team and independently and to take initiative will be appreciated.', sc.`scholarship_amount` = 'AUD $37000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://researchdegrees.uwa.edu.au/scholarships/17z09z/fully-funded-scholarship-for-a-phd-project-in-integrative-geophysics', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/fully-funded-scholarship-for-a-phd-project-in-integrative-geophysics/ef872235d94264f938c75a0415f71749', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'Fully Funded Scholarship For a PhD Project in Integrative Geophysics' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Global Excellence Scholarship is an annual tuition fee discount for the normal full-time duration of the awardee’s course as specified in their letter of offer. The value of the scholarship is determined by the applicant’s equivalent Australian Tertiary Admission Rank (ATAR) or UWA weighted average mark (WAM).', sc.`eligibility` = 'Please contact The University of Western Australia (UWA) for further information.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uwa.edu.au/study/international-students/fees-and-scholarships/uwa-funded-scholarships/global-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/global-excellence-scholarship/fe653755ce0d2d5075b82783823e953f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'Global Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Ground rotation sensors have wide applications, such as precision instrumentation, environment monitoring, and rotational seismology, as well as for improving the sensitivities of gravitation wave detectors.  Currently available rotation sensors have issues of either low sensitivities or too fragile/too large to be used in the field. At UWA we are developing a compact, and robust with a high sensitivity rotation sensor using many innovative technologies.  This PhD project is to build, characterize and field test the rotation sensor.', sc.`eligibility` = 'Honours or Master\'s degree in Mechanical Engineering or Experimental Physics.; Meet the UWA PhD entrance requirements with adequate English.; Have a high academic achievement in the coursework.; Demonstrated research capabilities through high quality research thesis and/or published peer-reviewed journal papers.', sc.`scholarship_amount` = 'Stipend scholarship / 	Tuition fee scholarship', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://researchdegrees.uwa.edu.au/scholarships/17z0x3/high-precision-rotation-sensor', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/high-precision-rotation-sensor/1a4e56e45303955b0e9e76ed04fd63b9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'High Precision Rotation Sensor' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Are you ready to be at the forefront of the next big leap in global finance? Digital finance is changing the game by using cutting-edge blockchain technology and digital distributed ledgers to turn real-world assets into secure, tradeable digital tokens. This breakthrough is opening new markets, driving efficiency, reducing costs and creating a more inclusive financial system worldwide. Our industry PhD scholarships are now open to students passionate about researching in the rapidly evolving world of digital finance. If youre ready to make an impact, we want to hear from you.', sc.`eligibility` = 'Candidates interested in researching the technological, financial and/or legal innovations required to enable the global transition to financial markets 3.0.', sc.`scholarship_amount` = 'AUD $70000/year — Other allowance : AUD $10,000 total / 	Research allowance: 	AUD $4,500', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://researchdegrees.uwa.edu.au/scholarships/1905zx/industry-phd-scholarship-digital-finance-crc', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/industry-phd-scholarship-digital-finance-crc/da6645736feee784b12d1506ce71d184', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'Industry PhD Scholarship - Digital Finance CRC' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Digital finance is a technological toolkit incorporating blockchain technology and other digital distributed ledgers that transforms real-world assets into digital tokens that can be traded seamlessly and securely across borders, time zones, asset classes and individuals. It will open new markets, and make existing markets more functional, less costly and more efficient, and has the potential to create a more inclusive and fair financial system.', sc.`eligibility` = 'Our top-up scholarships are available to PhD students researching any of the following disciplines:; applied finance (eg Automated Market Makers, pricing, estimating gains from tokenisation); law (eg compliance, regulation, legislation, policy implications of the digital finance transformation and smart contracts); computer and data science (eg blockchain, digital distributed ledgers, market manipulation and fraud detection, security, data management, machine learning, LLM).', sc.`scholarship_amount` = 'AUD $15000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://researchdegrees.uwa.edu.au/scholarships/190601/industry-phd-top-up-scholarship-digital-finance-crc', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/industry-phd-top-up-scholarship-digital-finance-crc/aabb27d636dd0b3323387b8432f451e0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'Industry PhD Top-up Scholarship - Digital Finance CRC' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'https://www.uwa.edu.au/study/international-students/international-student-award', sc.`eligibility` = 'Please contact The University of Western Australia (UWA) for further information.', sc.`scholarship_amount` = 'Up to AUD $20000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uwa.edu.au/study/scholarship-listing/uwa-international-student-award-f221201', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-student-award/75e0695bafd19056a81934b5cf38b71a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'International Student Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University of Western Australia (\'the University\') provides fee discount scholarships to encourage and assist students from eligible countries to pursue an undergraduate or postgraduate qualification at the University.', sc.`eligibility` = 'To be eligible to be considered for the scholarship, candidates must-; (a) be an international student from: Brunei Darussalam, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Vietnam, Timor-Leste; have applied to commence an eligible postgraduate degree;  have not discontinued an equivalent level course, with an immediate break in enrolment after discontinuation.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uwa.edu.au/study/scholarship-listing/uwa-asean-scholarship-f191752', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uwa-asean-scholarship/d1a35831d953a9741e903d83c71777d9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'UWA ASEAN SCHOLARSHIP' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University of Western Australia (\'the University\') provides a fee discount scholarship to encourage and assist eligible high-achieving international students to commence and pursue an undergraduate or postgraduate qualification at the University.', sc.`eligibility` = 'To be eligible to be considered for the scholarship, applicants must; be an International Student; have received an offer for an eligible undergraduate or postgraduate course at The University of Western Australia; have achieved an equivalent ATAR of at least 85 if commencing undergraduate study or have achieved an equivalent WAM of at least 65 if commencing postgraduate study; have not discontinued an equivalent level course, with an immediate break in enrolment after discontinuation.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uwa.edu.au/study/scholarship-listing/uwa-global-excellence-scholarship-f1917561', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uwa-global-excellence-scholarship/0753d2c03240f997e696e8d16a2eeea5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'UWA GLOBAL EXCELLENCE SCHOLARSHIP' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University of Western Australia (\'the University\') provides fee discount scholarship to encourage and assist eligible high-achieving international students from Singapore Polytechnic institutions to commence and pursue an undergraduate qualification at the University.', sc.`eligibility` = 'To be eligible to be considered for the scholarship, candidates must; Be an international student; Be commencing one of the following courses at UWA: Bachelor of Business, Bachelor of Commerce, Bachelor of Engineering (Honours), Bachelor of Biomedical Science, Bachelor of Science; have not commenced or discontinued an equivalent level course at the University; have completed a Polytechnic Diploma program at one of the following polytechnic institutions in Singapore: Nanyang Polytechnic, Ngee Ann Polytechnic, Republic Polytechnic, Singapore Polytechnic, Temasek Polytechnic', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uwa.edu.au/study/scholarship-listing/uwa-singapore-polytechnic-scholarship-f269491', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uwa-singapore-polytechnic-scholarship/b92ed1cb45b34926e8026e58d175d720', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00126G' AND sc.`scholarship_name` = 'UWA SINGAPORE POLYTECHNIC SCHOLARSHIP' AND sc.`course_id` IS NULL;
