UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = NULL, sc.`eligibility` = 'Applicants must meet the following criteria:\r\n A willingness to be a member of the St Andrew’s Choir\r\n; A willingness to be fully involved in the Choir from the beginning of Term 1 until Christmas Day each year.\r\n Selection is based on the following criteria:\r\nThe results of a 20-minute audition\r\n; A 40-minute music aptitude test\r\n; Ability to sight read; Previous music and school reports\r\n;Interview', sc.`scholarship_amount` = '75% tuition fee remission', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/st-andrews-choir-scholarship/31217adb7572f67382a6c701beb09f12', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/st-andrews-choir-scholarship/31217adb7572f67382a6c701beb09f12', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00132K' AND sc.`scholarship_name` = 'St Andrew\'s Choir Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Mirams Scholarship was established in the 1970s by Mary Ida Mirams in memory of her son, James Herbert Mirams, an Old Boy of the School, who tragically lost his life in World War One at the age of 25.\r\n\r\nThe Mirams Scholarship is awarded to an Old Boy who, after completing his secondary schooling at BGS, goes on to study an engineering degree at Melbourne University.', sc.`eligibility` = 'Applicants for this scholarship must be Old Boys of the School who are enrolled in an engineering degree at Melbourne University.', sc.`scholarship_amount` = 'All scholarships are at the discretion of the Headmaster; this scholarship covers a percentage of the Melbourne University tuition fees and is awarded at the end of each year of study, usually two years.', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/the-mirams-scholarship/7c7917ea6ef7decd36800b6c3b3f76c8', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-mirams-scholarship/7c7917ea6ef7decd36800b6c3b3f76c8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00132K' AND sc.`scholarship_name` = 'The Mirams Scholarship' AND sc.`course_id` IS NULL;
