UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Academic Scholarships based on performance on an examination, and following an interview with the relevant Head of Campus, will be awarded to begin at either Malvern Campus or Wheelers Hill Campus. Applications should be submitted online and a fee of $115 is required. The Primary examination will be held at Wheelers Hill Campus on Saturday 13 February, 2021. Caulfield Grammar School uses ACER scholarship tests.', sc.`eligibility` = 'Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter. Opening Date :Applications for entry in 2023 will open in early December 2021.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-primary/4f67754246bda847c7581f084cc1dcd7', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-primary/4f67754246bda847c7581f084cc1dcd7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00136F' AND sc.`scholarship_name` = 'Academic Scholarships (Primary)' AND sc.`course_id` IS NULL;
