UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Caulfield Grammarians’ Association (CGA) offers Scholarships awarded to children of past students for entry into Year 7 and Years 9 – 11 at either Caulfield Campus or Wheelers Hill Campus. \r\n\r\nCGA scholarships are awarded through the General Excellence applications process. The Caulfield Grammarians’ Association is proud to be a strong supporter of the School’s Scholarship program which acknowledges the ongoing partnerships between past, current and future Grammarians.', sc.`eligibility` = 'For entry into Years 7, 9, 10, 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/caulfield-grammarians-association-scholarship/713245815016369ec3faa2e304348091', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/caulfield-grammarians-association-scholarship/713245815016369ec3faa2e304348091', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00136F' AND sc.`scholarship_name` = 'Caulfield Grammarians\' Association Scholarship' AND sc.`course_id` IS NULL;
