UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Dance Scholarships are available for entry into Year 10 or 11 at either Caulfield Campus or Wheelers Hill Campus.\r\n\r\nApplicants should demonstrate exceptional Dance Technique and Performance skills. Successful candidates will enjoy state-of-the-art facilities and be expected to be involved in two performances each year and also provide leadership within the field of Performing Arts.\r\n\r\nIn accepting a scholarship offer, students must complete VCE Dance Units 1/2 in Year 11 and Units 3/4 in Year 12 as part of their VCE Course.', sc.`eligibility` = 'For Years 10, 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/dance-scholarships/ca6a00921008b3f233db7a3a682399d4', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/dance-scholarships/ca6a00921008b3f233db7a3a682399d4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00136F' AND sc.`scholarship_name` = 'Dance Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'General Excellence Scholarships will be awarded to begin at either Caulfield Campus or Wheelers Hill Campus in Year 7 and Years 9 – 11. Typically a 50 percent concession, General Excellence Scholarships offer part remission of tuition fees; offers will take into account parent’s financial means.These scholarships are awarded to students who are able to demonstrate excellence and achievement in the following fields: AcademicLeadership and ServiceThe Arts (Performing Arts and/or Visual Arts) Sport (students must be competing in teams at a State/National Level). Applicants will need to provide information on levels of achievement in each field and must demonstrate excellence in at least three fields. Scholarships are awarded following an interview with senior staff.', sc.`eligibility` = 'For Years 7, 9, 10, 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarships/d6cd424c87c5ec09f68bd638244e5bb1', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/general-excellence-scholarships/d6cd424c87c5ec09f68bd638244e5bb1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00136F' AND sc.`scholarship_name` = 'General Excellence Scholarships' AND sc.`course_id` IS NULL;
