UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'An innovative program offers students excellent opportunities in solo and ensemble performance. Our School’s various bands, orchestras, ensembles and choirs perform at regular concerts and assemblies, eisteddfods, festivals and productions. Music auditions will commence in early February, and all applicants will be notified at the conclusion of the audition process. Results of Scholarships are confidential and are not released by the School. Please do not send copies of your child’s School Reports to Caulfield Grammar School. This information will be requested from short-listed candidates at the time of interview.', sc.`eligibility` = 'For entry into Year 7, 9, 10. Awarded for outstanding musical ability. Based on an audition and an interview. For Year 7 entry: AMEB Grade 8 Pianoforte, AMEB Grade 7 Violin, AMEB Grade 6 for other instruments. For Years 9 and 10 entry AMEB AMusA Pianoforte, AMEB Grade 8 Violin, AMEB Grade 7 for other instruments.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-scholarships/1650fd3443b78dd49d93fa1e9ab7f619', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/music-instrumental-scholarships/1650fd3443b78dd49d93fa1e9ab7f619', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00136F' AND sc.`scholarship_name` = 'Music (Instrumental) Scholarships' AND sc.`course_id` IS NULL;
