UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Visual Arts Scholarships are available for entry in Year 10 or 11 at either Caulfield Campus or Wheelers Hill Campus.\r\n\r\nSuccessful students will be expected to demonstrate outstanding abilities in both the practical and theoretical aspects of the Visual Arts, and be actively involved in the broader Visual Arts programs as a role model for others.\r\n\r\nIn accepting a scholarship offer, students must complete VCE Studies in Visual Arts at both Units 1/2 and Units 3/4 levels.', sc.`eligibility` = 'For entry into Years 10 and 11. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/visual-arts-scholarships/e173896c79ae1e3b241f011680fca741', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/visual-arts-scholarships/e173896c79ae1e3b241f011680fca741', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00136F' AND sc.`scholarship_name` = 'Visual Arts Scholarships' AND sc.`course_id` IS NULL;
