UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'W.S. Morcom Rural Boarding Scholarships will be awarded for entry in Years 9 to 11 at the Caulfield Campus.These scholarships will be awarded to students who are able to demonstrate achievement in several fields of endeavour who will therefore contribute strongly to the boarding community: Academic Leadership and Service, The Arts (Performing Arts and/or Visual Arts) Sport (students should be competing at a representative / regional / State / National level). In addition to part remission of tuition fees, these scholarships will provide some assistance to parents in meeting the cost associated with boarding. Applicants who have submitted an application for a General Excellence scholarship but are unsuccessful will have their applications considered for the W.S. Morcom scholarships. There is no need to complete a second application form.', sc.`eligibility` = 'For entry into Years 9, 10, 11 as boarders. Interviews will then be conducted with short listed candidates. Scholarships will be offered to successful applicants shortly thereafter.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/ws-morcom-rural-boarding-scholarship-at-caulfield-campus/aa2dbacb1870803743cb95884ac43bbd', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ws-morcom-rural-boarding-scholarship-at-caulfield-campus/aa2dbacb1870803743cb95884ac43bbd', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00136F' AND sc.`scholarship_name` = 'W.S. Morcom Rural Boarding Scholarship at Caulfield Campus' AND sc.`course_id` IS NULL;
