UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A limited offering for international students who are enrolling into Kent’s higher education Bachelor degree courses. Students must have applied through authorised Kent Agents at both the Sydney and Melbourne campuses.', sc.`eligibility` = 'All Bursaries are awarded at the discretion of Kent to:; Applicants who undertake a full-time study load of a Kent undergraduate higher education \r\ndegree (subject to unit availability).; Applicants who enrol in cross institutional or non-awards units.; Applicants who come to Kent as direct applicants or applicants from approved Kent Agents.; Applicants who study on either the Sydney or Melbourne campuses, or via online class delivery.', sc.`scholarship_amount` = 'Up to AUD $300 — The bursary awards applicants with a $300 per unit reduction in tuition fees for the first 24 units enrolled.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://kent.edu.au/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/kent-higher-education-bursary-for-international-students/21dd025f1314512f7fb0dc70d001fbf1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00161E' AND sc.`scholarship_name` = 'Kent Higher Education Bursary for International Students' AND sc.`course_id` IS NULL;
