UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This PhD project focuses on developing the first-ever closed-loop cardiopulmonary resuscitation (CPR) feedback device. The device uses non-invasive sensors to measure blood oxygenation in the brain and tells the CPR provider how to adjust their compression depth, rate, and release to improve patient outcomes. The student will have the opportunity to work with a range of engineers, doctors, and paramedics and will help to develop this prototype into an ambulance-ready device, ready for deployment in large-scale clinical trials.', sc.`eligibility` = 'You need to meet the entry requirements for QUT\'s Doctor of Philosophy, including any English language requirements.; Enrol as a full-time, internal student.; Have a background in electrical, mechatronic, or biomedical engineering, expertise in biosensors or optics. Should be comfortable being hands-on. Requires experience in circuit design and microcontroller programming.', sc.`scholarship_amount` = 'AUD $33637/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/a-smart-cpr-feedback-device-for-cardiac-arrest-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/a-smart-cpr-feedback-device-for-cardiac-arrest-phd-scholarship/0b6b29fc7a416b77c32a6bfb937838a0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'A smart CPR feedback device for cardiac arrest (PhD scholarship)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'As an Australia Awards student you need to attend a five-week Introductory Academic Program (IAP). It’s a chance for you to get help with enrolment, learning skills, language expectations and our technology and teaching systems. You will receive program information to your student email.', sc.`eligibility` = '-', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/australia-awards-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarship/c91bd86d2c6d99745facf696367dc009', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Australia Awards Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Australian South Sea Islander Community Foundation was established by the Queensland Government in 2001 as a perpetual fund to provide scholarships to Australian South Sea Islander undergraduate students.', sc.`eligibility` = 'an Australian South Sea Islander who is a direct descendant of the South Sea Islanders who were brought into Queensland between 1863 and 1904 and worked as indentured labourers, not have previously completed an undergraduate degree at any university, be intending to enrol or are currently enrolled in an undergraduate program (either part time or full time) at QUT, from a low-income background, experiencing financial hardship, enrolled in or applying for an undergraduate course, personal medical conditions, disabilities, dependants with special needs.', sc.`scholarship_amount` = 'You will receive an Australian South Sea Islander Community Foundation Scholarship. The value and number of scholarships will vary annually depending on funding. These scholarships are subject to annual funding.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/australian-south-sea-islander-community-foundation-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australian-south-sea-islander-community-foundation-scholarship/8d3162228bfef1e724bf31c3eea1d690', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Australian South Sea Islander Community Foundation Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Bachelor of Arts Impact Scholarship is awarded to high-achieving school leavers and eligible gap year students starting our Bachelor of Arts degree. This scholarship is targeted at high achievers to enable their continued success at QUT through financial support, peer support, mentoring and networking opportunities.', sc.`eligibility` = 'You must:; demonstrate exceptional academic excellence in school studies, based on your adjusted Australian Tertiary Admissions Rank (ATAR) or adjusted selection rank for International Baccalaureate (IB); be graduating Year 12 in 2026, or have graduated Year 12 in 2025, and are applying through the Queensland Tertiary Admissions Centre (QTAC) to QUT for the first time; nominate QUT\'s Bachelor of Arts as your first preference on your QTAC application at the time of the main December and January admission offer rounds and receive an offer in the first preference; be starting a university undergraduate degree for the first time in 2027; have not undertaken/commenced any tertiary study, other than studies in special university programs designed for secondary school students', sc.`scholarship_amount` = 'Up to AUD $15000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/bachelor-of-arts-impact-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/bachelor-of-arts-impact-scholarship/04c21ed2e6bb871c753cd5c97aa29181', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Bachelor of Arts Impact Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A scholarship for future research students studying in any faculty.', sc.`eligibility` = 'You must:; meet the China Scholarship Council requirements, as outlined on the China Scholarship Council website (in Mandarin); apply for and be admitted to a PhD, research masters or professional doctorate at QUT; To apply for this scholarship, you must meet the entry requirements for a Doctor of Philosophy (PhD), Master of Philosophy, or professional doctorate at QUT, including any English language requirements for international students.\r\n\r\nYou must:; meet the China Scholarship Council requirements, as outlined on the China Scholarship Council website (in Mandarin); apply for and be admitted to a PhD, research masters or professional doctorate at QUT; To apply for this scholarship, you must meet the entry requirements for a Doctor of Philosophy (PhD), Master of Philosophy, or professional doctorate at QUT, including any English language requirements for international students.', sc.`scholarship_amount` = 'a tuition fee waiver for the duration of your course, which is normally 1.5 years for masters students and 3 years for doctoral students.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/china-scholarship-council', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/china-scholarship-council-scholarship/cbc16bf079d440444fdcc8f796911f37', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'China Scholarship Council Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Clayton Adam Florence Wilson Award is available to promote spine research at QUT, and honours the stellar contribution to scientific innovation in spine research made by our former Research Director, Professor Clayton Adam. Clayton joined QUT in 1999 and dedicated his work to helping children with spinal disorders, and to improving treatment outcomes for patients who undergo spinal surgery. He brought together a dedicated team of researchers, scientists, engineers, surgeons and industry partners to perform cutting edge research aimed at minimising risks and improving spinal surgery results for patients. Clayton’s leadership of the research program resulted in QUT receiving a substantial bequest from a donor impressed by his work: the Florence Wilson Bequest. In 2015, Clayton was diagnosed with a terminal illness yet continued his active research during treatment until early 2018. Sadly, his health battle ended in March 2018, but his dedication and contribution to biomechanics and spinal research will long be remembered and admired.', sc.`eligibility` = 'You must have experience in biomechanics and/or spine research. Further eligibility criteria will be provided following successful acceptance of your application.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Computing and information technology, Engineering and technology, Health services and support, Humanities and social sciences, Mathematics, Sciences', sc.`website` = 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/CAFW-Award', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/clayton-adam-florence-wilson-award-for-biomechanics-and-spine-research/d945ac0fc1f41fced0575e8b5704dc96', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Clayton Adam Florence Wilson Award for Biomechanics and Spine Research' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'At CSIRO\'s Data61, we aim to develop top-quality doctoral students who will prosper in careers in Australia’s data-skilled workforce. Our PhD scholarship program provides opportunities for outstanding postgraduate students with demonstrated academic and research excellence to further their careers at one of Australia’s most trusted organisations.\r\n\r\nWe offer a diverse, inclusive and flexible working environment where our people are supported and empowered to come up with digital and data solutions with impact.\r\n\r\nYou’ll work closely with your supervisors and teams on research projects that are aligned to our strategic goals. Our scholarships are awarded in partnership with Australian universities, so you’ll receive support and guidance from university supervisors alongside some of the country’s leading data and digital science experts.', sc.`eligibility` = 'domestic and international students who currently live in Australia, \r\ninternational students overseas at the time of application, who hold a visa to study in Australia, \r\nhold a first-class honours (H1) Bachelor’s degree or equivalent in the relevant research area (completed or near completion), \r\nhave applied for admission to a PhD program at an Australian university or have completed less than 12 months study in a PhD program at an Australian university at the start of the scholarship’s commencement period, \r\nhave a university supervisor who confirms they are willing and able to supervise you listed in your application, as Data61 does not organise your academic supervisor, \r\nnot already hold a PhD degree, \r\nbe ready to commence within the specific time and period noted in the advertisement.', sc.`scholarship_amount` = 'a full scholarship which includes a base stipend at the Australian Government Research Training (RTP) Program base rate supplemented with a top-up scholarship of $10,000 per annum. Data61 PhD scholarships have a maximum term of 3 years and 6 months.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Built environment, Computing and information technology, Engineering and technology, Mathematics, Sciences', sc.`website` = 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/data61-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/data61-phd-scholarship/e18d26a8362937016e062999ef29aa34', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Data61 PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'As the successful applicant you will complete your PhD in the field of organic photochemistry for advanced reprogrammable material design.Based in our Science and Engineering Faculty, you will also spend time at our research hub at the Karlsruhe Institute of Technology (KIT) in Germany.', sc.`eligibility` = 'fulfil our PhD admission criteria, including English language requirements (an IELTS score of 6.5 or above if English is not your first language).', sc.`scholarship_amount` = 'a minimum of $30,000 per year, for 3 yearsa QUT tuition fee sponsorship (for international students).', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Mathematics, Sciences', sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/dynamic-soft-matter-materials-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/dynamic-soft-matter-materials-phd-scholarship/663db6124f3eb4f6d8511f1e8ec2d239', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Dynamic soft matter materials PhD scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you\'re completing a work integrated learning (WIL) placement and experiencing financial hardship, you may be eligible for a bursary of up to $750.', sc.`eligibility` = 'currently enrolled as a student, struggling financially, undertaking a work integrated learning (WIL) placement, unable to meet the costs of placement.', sc.`scholarship_amount` = 'Up to AUD $1000 — bursary of $300, $500, $750 or $1000 based on your demonstrated need.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/equity-work-integrated-learning-wil-bursaries', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/equity-work-integrated-learning-wil-bursaries/49629bcecc57af26ba15ca0a063a6630', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Equity Work Integrated Learning (WIL) Bursaries' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The QUT Equity Scholarships Scheme is an application-based scheme offered to students who experience financial difficulty. It is funded by significant contributions from the Learning Potential Fund. The scholarships and bursaries are offered to commencing or continuing domestic and international students.', sc.`eligibility` = 'You must be from a low-income background, and experiencing financial hardship. We also take personal hardship into consideration when assessing applications. This includes personal medical conditions, disabilities and dependants with special needs.', sc.`scholarship_amount` = 'Up to AUD $4200', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/equity-scholarships-scheme', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/equity-scholarships-scheme/53b646db0a38d87929e99fc755b2469b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Equity scholarships scheme' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A high achievement scholarship for future international undergraduate and postgraduate students.', sc.`eligibility` = 'Meet the academic entry requirements, meet minimum English language entry requirements for the degree program. If you complete a QUT pathway program for the purpose of satisfying QUT English language requirements, you may be eligible for this scholarship once you start your degree program, receive an admission offer letter into one of the eligible courses offered by participating faculties.', sc.`scholarship_amount` = 'a scholarship to cover 25% of your tuition fees for your first two semesters (one year) of study at QUT, provided you meet the minimum academic standards.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Built environment, Computing and information technology, Engineering and technology, Mathematics, Sciences', sc.`website` = 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/international-merit-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-merit-scholarship/834f5a383770ab75e9d4ad02cc79375a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'International Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A new scholarship for 2026 that covers tuition fees, with eligibility based on your prior academic achievements.', sc.`eligibility` = 'You must:; meet the academic entry requirements; have an eligible nationality; meet minimum English language entry requirements for the course; be commencing the course for the first time; receive an admission offer letter into one of the eligible courses.', sc.`scholarship_amount` = 'You\'ll receive an ongoing scholarship to cover 20% of your tuition fees per semester of study at QUT', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/international-talent-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-talent-scholarship/461afe36373be72657bc184811ea79e1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'International Talent Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'We are seeking a PhD candidate to investigate gas bubble dynamics under the influence of electric fields, with a particular focus on applications in electrochemical hydrogen production. The project will examine the physical mechanisms governing bubble generation, growth, detachment, coalescence, and transport near electrode surfaces, with the aim of improving bubble removal and enhancing the efficiency of water electrolysis systems.', sc.`eligibility` = 'Completion of a Bachelor (Honours) or Master by Research degree in mechanical engineering, electrical engineering, chemical engineering, applied mathematics, applied physics or related disciplines', sc.`scholarship_amount` = 'AUD $37010/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/investigation-on-bubble-dynamics-under-electric-fields-in-water-electrolysis-process', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/investigation-on-bubble-dynamics-under-electric-fields-in-water-electrolysis-process/a60cc9ee661e96ba2b80bef2375ffebf', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Investigation on Bubble Dynamics Under Electric Fields in Water Electrolysis Process' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A tuition fee concession for commencing students from selected countries to study English for Academic Purposes or IELTS Advanced Program at QUT College.', sc.`eligibility` = 'A tuition fee concession for commencing students from selected countries to study General English or English for Academic Purposes at QUT International College. These concessions are available for prospective students from Colombia and Latin America, Hong Kong, India, Japan, Korea, Sri Lanka, Taiwan, Thailand and Vietnam.', sc.`scholarship_amount` = 'A reduction of 25% from the tuition fee of your English for Academic Purposes (EAP) and IELTS Advanced programs at QUT College.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Languages', sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-college-english-language-concession', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/qut-college-english-language-concession/f3886f22ee4e66ab67c405f39021117b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'QUT College English Language Concession' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is sponsored by QUT College. It is available to international students who have demonstrated academic achievement or can demonstrate how they intend to commit to success in their future studies.', sc.`eligibility` = 'Your eligibility will depend on your secondary school results.\r\n\r\nIf you are eligible for an International Merit Scholarship for your degree course, you are also eligible for the College Merit Scholarship.', sc.`scholarship_amount` = 'A scholarship to cover 25% of the tuition fees for the first semester of your Diploma or Foundation program at QUT International College. An invitation to a Pathway Scholarship ceremony, certificate of recognition, and access to extra-curricular prof', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-international-college-pathway-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/qut-college-merit-scholarship/119c6423cfe25e0776520252337f9b72', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'QUT College Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The QUT Excellence Scholarship is our premier offering for high achievers. We award more than 130 scholarships annually, worth more than $3.5 million.In addition to the financial support, the program helps you to make the most of your QUT experience through extra development opportunities, which build your leadership skills and professional networks.', sc.`eligibility` = 'an Australian or New Zealand citizena permanent resident, a holder of a permanent humanitarian visa, an international student studying the Australian Year 12 curriculum, either in Australia or overseas.be starting university for the first time in 2025, be graduating Year 12 in 2024, or have graduated Year 12 in 2023 and have had no more than one gap year since graduating, have achieved a minimum unadjusted Australian Tertiary Admissions Rank (ATAR) of 98.00 or equivalent to be considered for the scholarship, noting it is a competitive process and not all applicants on an unadjusted ATAR of 98.00 or above will be made an offer, have placed QUT as your first preference on your QTAC application at the time of the main December and main January admissions offer roundsreceive a QUT offer in your first preference.', sc.`scholarship_amount` = 'Up to AUD $30000 — scholarships valued at $30,000 each for study in any discipline, scholarships valued at $30,000 each for courses in the Faculty of Science and Faculty of Engineering only.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Creative arts', sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/excellence-scholarship-academic', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/qut-excellence-scholarship-academic/681083bc23ea5cc6ae00e5b7d63072b9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'QUT Excellence Scholarship (Academic)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'We are building research excellence by supporting students of exceptional research potential with QUTPRAs. The number of QUTPRAs offered varies from year to year.', sc.`eligibility` = 'New applicants to QUT research degrees need to: meet QUT’s admission criteria for a research degree, which includes meeting QUT’s English language requirements, not be in receipt of another living allowance scholarship to undertake the research degree.\r\nCurrent QUT research students need to have consumed less than the below equivalent full-time study load (EFTSL) to apply: less than 1 year EFTSL for enrolled research doctorate students, less than 6 months EFTSL for enrolled research masters students', sc.`scholarship_amount` = 'A living allowance for three years, indexed annually ($27,596 in 2019). The scholarship is tax exempt for full-time students, and can be used to support living costs.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-postgraduate-research-award-qutpra', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/qut-postgraduate-research-award-qutpra/d6c913e04e2d91bedf6935fb82f0abfb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'QUT Postgraduate Research Award (QUTPRA)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Four scholarships are available for German applicants wishing to study in Science or Engineering', sc.`eligibility` = 'You must also meet QUT\'s Doctor of Philosophy Academic Entry requirements, and be applying to complete your degree in either QUT\'s Faculty of Science or Faculty of Engineering.', sc.`scholarship_amount` = 'AUD $33637/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-and-gostralia!-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/qut-and-gostralia-phd-scholarship/9017c9a93df484d2d1b60076603a3b0e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'QUT and GoStralia! PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Hyperspectral imaging is one of the rapidly growing domains in remote sensing primarily due to the breadth of applications on a variety of areas, from plant disease detection to object tracking. For example, hyperspectral imaging provides an opportunity to develop fast and non-invasive methods of detecting plant diseases and potentially discriminating between different disease types (e.g. virus, fungus, bacteria) before the human eye can see them. The principal aim of this PhD research program is to develop methods to improve the hyperspectral image classification using deep learning techniques. The developed systems will be evaluated on their ability to detect plant diseases and potentially discriminating between different disease types using the hyperspectral imaging dataset which has been already collected by CSIRO.', sc.`eligibility` = 'You must: meet QUT’s PhD admission criteria (Degree in Electrical Engineering and/or Computer Science with first class honours). We would like you to have: sound knowledge of machine learning, computer vision and image processing, strong programming skills.', sc.`scholarship_amount` = 'A scholarship between $37,000 and $40,000 per year for 3 years (consisting of a base stipend of $27,000 and a top-up between $10,000 and $13,000) with a possible extension of 6 months. Up to $5,000 per year for project costs (to be agreed between CSI', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Computing and information technology, Mathematics, Sciences', sc.`website` = 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-csiro-phd-scholarship-in-deep-learning-for-hyperspectral-image-classification', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/qut-csiro-phd-scholarship-in-deep-learning-for-hyperspectral-image-classification/32630098caf9d4da3a62dcaf80274225', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'QUT-CSIRO PhD Scholarship in Deep Learning for Hyperspectral Image Classification' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A scholarship for future postgraduate research students in any faculty.', sc.`eligibility` = 'New applicants to QUT research degrees need to:; meet QUT\'s admission criteria for a research degree, which includes meeting QUT\'s English language requirements at the time of application; not be in receipt of another living allowance scholarship to undertake the research degree.', sc.`scholarship_amount` = 'AUD $38310/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/research-training-program-stipend', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-training-program-rtp-stipend-scholarship/b007b0a25e142822f7e05d986057c98a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Research Training Program (RTP) Stipend Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Headquartered at the Queensland University of Technology (QUT), AVR3 is a pioneering research hub dedicated to advancing automated vehicle (AV) technologies specifically tailored for the unique challenges of rural, regional, and remote Australian roads. AVR3 fosters a collaborative network of experts from multiple academic partners (including QUT, the University of Sydney, UTS, UWA, Deakin, and Swinburne), and industry leaders such as Ford Australia, Seeing Machines, RACQ, The Department of Transport and Main Roads, National Transport Commission, Transport For NSW, and end users in agriculture, mining, and defense.', sc.`eligibility` = 'You need to meet the entry requirements for a QUT research degree, including any English language requirements.; Enrol as a full time, internal student (unless approval for part-time and/or external study is obtained).; Have an Honours or Master\'s degree (or equivalent) in one of these areas:\r\nEngineering, Computer Science, Human Factors, Psychology, Data Science, Robotics, or a related policy/business discipline.; Have familiarity with empirical research methods, experimental design, or technical modelling relevant to your field.; Having a demonstrated publication record or potential in peer-reviewed conferences or journals is highly advantageous.', sc.`scholarship_amount` = 'AUD $41555/year — You\'ll receive a stipend of $41,555 per annum for a maximum duration of 3.5 years while undertaking a QUT PhD (1.75 years for MPhil). The duration includes an extension of up to 6 months (PhD) or 3 months (MPhil) if approved for you', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/shaping-the-future-of-mobility-in-rural-and-remote-regions-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/shaping-the-future-of-mobility-in-rural-and-remote-regions-phd-scholarship/db2f4c39bdadeee874d2ea9ea22ecb6e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Shaping the future of mobility in rural and remote regions (PhD scholarship)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'We are seeking a PhD candidate to investigate system-level multiphase flow processes in electrochemical hydrogen production. The project will focus on how operating conditions, porous transport layers, electrode properties, and gas bubble transport influence hydrogen and oxygen generation in water electrolysis systems. Efficient removal of gas bubbles is critical to the performance of electrochemical hydrogen production devices. Bubbles generated during water electrolysis can block active reaction sites, increase electrical resistance, disturb liquid flow and mass transport, and reduce overall production efficiency. At the system level, these effects are governed by coupled interactions between electrochemical operation, multiphase flow, porous media transport, surface wettability, temperature, and flow conditions. This project will investigate these coupled processes to identify practical strategies for improving electrolyser performance.', sc.`eligibility` = 'Completion of a Bachelor (Honours) or Master by Research degree in mechanical engineering, electrical engineering, chemical engineering, applied mathematics, applied physics or related disciplines', sc.`scholarship_amount` = 'AUD $37010/year', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/system-level-multiphase-flow-and-bubble-transport-for-efficient-electrochemical-hydrogen-production', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/system-level-multiphase-flow-and-bubble-transport-for-efficient-electrochemical-hydrogen-production/26c29746c86de06a35005739ca93f67a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'System-Level Multiphase Flow and Bubble Transport for Efficient Electrochemical Hydrogen Production' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A sponsorship to help international student pay tuition fees.', sc.`eligibility` = 'International students who enrol in a QUT research degree and are in receipt of:; a stipend scholarship awarded by QUT; a stipend scholarship funded by an organisation with which QUT has an external agreement to sponsor fees for this student or relevant cohort of students.; Candidates will not be eligible if they receive another tuition fees offset or sponsorship from any source, including QUT.; You cannot apply for a Tuition Fee Sponsorship - your eligibility is reviewed via your application for admission.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/tuition-fee-sponsorship-tfs-for-research-students', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/tuition-fee-sponsorship-tfs-for-research-students/0508a2146c6b8084b7f5699bc78ef0d4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Tuition Fee Sponsorship (TFS) for research students' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This PhD project will investigate quantum geometry-driven electronic transport in kagome lattices as a pathway beyond the scaling limits of conventional silicon electronics. By engineering crystal symmetry and magnetic order through controlled chemical doping, the research aims to tune the quantum metric and realize giant nonlinear Hall effects in transition-metal kagome compounds. High-quality single crystals will be synthesised, fabricated into micro-devices, and studied via physical property measurements to probe quantum-metric responses. This project will deliver fundamental insights into quantum materials and establish a platform for low-power quantum devices.', sc.`eligibility` = 'You need to meet the entry requirements for QUT\'s Doctor of Philosophy, including any English language requirements.; enrol as a full-time, internal student (unless approval for part-time and/or external study is obtained); commence your degree by 1 Oct 2026; have an honours or master degree in one of these areas:; physics; theoretical chemistry; materials science and engineering.', sc.`scholarship_amount` = 'AUD $40000/year — You\'ll receive a stipend of $40,000 per annum for a maximum duration of 3.5 years while undertaking a QUT PhD. The duration includes an extension of up to six months if approved for your candidature. This is the full-time, tax exemp', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/understand-and-manipulate-quantum-geometry-in-kagome-metals-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/understand-and-manipulate-quantum-geometry-in-kagome-metals-phd-scholarship/4a1edfc5258e221763a24ee4f43121bc', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Understand and manipulate quantum geometry in kagome metals (PhD scholarship)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Neuropathic pain effects "1 in every 10 adults over the age of 30". The treatments available for neuropathic pain can at best be described as having "moderate efficacy". Due to the nature of neuropathic pain, the ability to scientifically study and understand its fundamental causes has been limited to animal models and trials. There are over 27 animal models for neuropathic pain where pain has been induced by macroscopic & microscopic nerve lesions, chemotherapy, viral infections and diabetes mellitus. Looking at clinical studies, the current research process is to propose a model, conduct animal tests and then evaluate whether the original model is consistent with results. This is difficult as it requires humans to evaluate pain in animals which cannot be directly measured. This process is not systematic in the way it comes up with models and has thus resulted in many models of limited effectiveness.', sc.`eligibility` = 'You need to meet the entry requirements for a QUT research degree / Doctor of Philosophy / professional doctorate, including any English language requirements.; enrol as a full-time, internal student; have a background in either mechanical or medical engineering.', sc.`scholarship_amount` = 'AUD $32500/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/using-systems-engineering-to-model-neuropathic-pain-phd-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/using-systems-engineering-to-model-neuropathic-pain-phd-scholarship/2d267fa6130c6a60c90cff60bf21a72d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'Using Systems Engineering to Model Neuropathic Pain (PhD Scholarship)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'QUT is working with the Vietnam Ministry of Education and Training (MOET) through the Vietnam International Education Development (VIED) Office.', sc.`eligibility` = 'This scholarship is available to eligible Vietnamese postgraduate research students. You must be an international from Vietnam with an offer from QUT, meet all academic requirements, meet English language entry requirements for admission to the QUT course and meet any additional relevant requirements.', sc.`scholarship_amount` = 'a full scholarship covering your tuition fees and living expenses for the duration of your three-year PhD.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/project-911-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vied-phd-scholarship/9731fb149c23f2465f5fc9a9254adfc8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00213J' AND sc.`scholarship_name` = 'VIED PhD Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'We believe a quality education can be for everyone – regardless of background, location, or life circumstances. That’s why we offer a variety of scholarships and bursaries to cater for all student needs. This can include financial support to assist with living expenses, and non-deferrable costs such as textbooks, uniforms, technology, course-specific equipment, travel costs associated with compulsory residential schools and unpaid placement, accommodation, and general living expenses such as rent, groceries and fuel. Whether you’re a commencing student or continuing your studies, receiving a scholarship can help balance your studies and life commitments. A scholarship looks good on your resume and may open the door to industry networks and work experience opportunities.', sc.`eligibility` = 'Eligibility requirements vary depending on the scholarship. Please review the specific eligibility criteria for each scholarship you are interested in.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET, Postgraduate', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.cqu.edu.au/study/prepare/scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/browse-cquniversity-scholarships/4f95b5a94355ac225ed0f62e30339cf7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00219C' AND sc.`scholarship_name` = 'Browse CQUniversity Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The CQUniversity ASEAN Student Scholarship is a highly competitive scholarship offering 50 per cent off tuition fees for eligible undergraduate, postgraduate coursework and research courses at CQUniversity Australia. This scholarship is limited and awarded to high‑achieving international students who demonstrate strong academic performance, leadership potential and a commitment to making a positive impact in their community or chosen field. Designed to recognise future changemakers from Southeast Asia, this scholarship supports motivated students to access a world‑class Australian education while investing in their long‑term career success.', sc.`eligibility` = 'To be eligible for the CQUniversity ASEAN Student Scholarship, you must:; plan to commence your studies in 2026 or 2027; hold citizenship from a Southeast Asian country; have demonstrated outstanding academic achievement, achieving a minimum grade average of 75 per cent or equivalent, as assessed by the University; submit your application from offshore, outside Australia.', sc.`scholarship_amount` = '50% off tuition fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1271035/asean-student-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/cquniversity-asean-student-scholarship/45d84db1f2761c9fc1f0a5cf5a975428', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00219C' AND sc.`scholarship_name` = 'CQUniversity ASEAN Student Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Indonesia Student Scholarship supports Indonesian students in pursuing their study ambitions in Australia. By offering 50 per cent off tuition fees, this scholarship helps you focus on what matters most - achieving academic success and building a strong future.', sc.`eligibility` = 'To be eligible for the Indonesia Student Scholarship, you must:;hold an Indonesian citizenship; meet the academic and English language proficiency requirements at CQUniversity; submit your application from offshore, outside Australia', sc.`scholarship_amount` = '50% off tuition fees // Duration of course', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1273751/indonesia-student-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/indonesia-student-scholarship/53866b3fb22cf14773b5b757e21395d1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00219C' AND sc.`scholarship_name` = 'Indonesia Student Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Alumni Scholarship offers eligible international students the opportunity to continue their academic journey at CQUniversity Australia. Designed to support recent graduates, this scholarship provides a 15 per cent reduction in tuition fees for the duration of the course.', sc.`eligibility` = 'To receive the International Alumni Scholarship, you must be an international student who has completed a CQUniversity qualification and commence a new course at CQUniversity within 12 months of your conferral date. You must meet the academic and English language proficiency requirements for your chosen course.', sc.`scholarship_amount` = '15 percent reduction in tuition fees for the duration of the course.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1253043/international-alumni-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-alumni-scholarship/45b30657a750ab8cd83f0801c054e7a5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00219C' AND sc.`scholarship_name` = 'International Alumni Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Merit Scholarship is available to all new international students who plan to enrol in undergraduate, postgraduate coursework, research, or packaged academic courses at any campus or online.', sc.`eligibility` = 'Please Contact CQUniversity Australia for more information.', sc.`scholarship_amount` = 'Valued at up to 25% of your course fees, this scholarship recognises strong academic performance and supports students committed to achieving excellence in their studies.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/745776/international-merit-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-merit-scholarship/c1bcce1dc3c90a311746600eb403a0a5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00219C' AND sc.`scholarship_name` = 'International Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Live, Earn and Learn Scholarship is designed specifically for international students who have received an offer to study at our Rockhampton North campus.  Through this scholarship, you can excel academically while building practical experience in Central Queensland. You\'ll receive a 35% accommodation scholarship at Capricornia College (terms and conditions apply), work part-time on campus or in the local community, and immerse yourself in a vibrant campus lifestyle. Availability for 2027 intakes is currently under review. Updates will be published on this page and communicated to eligible future students when available.', sc.`eligibility` = 'You must meet the following requirements:; Have applied and received an offer to study at the Rockhampton North campus in an eligible term.; Have applied to live at our on-campus student residence during your study.', sc.`scholarship_amount` = '35% of accommodation cost and paid part-time work.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1188590/live-earn-learn-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/live-earn-and-learn-scholarship/d98a2d488e6959fe12e8948b5fdb3d6e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00219C' AND sc.`scholarship_name` = 'Live, Earn and Learn Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'RTP Stipend Scholarships are funded by the Australian Government. They provide funding allocated to students to assist with their living costs while undertaking a research higher degree.', sc.`eligibility` = 'To be eligible for an RTP Stipend a candidate must not be receiving income from another source to support the candidates general living costs while undertaking their course of study if that income is greater than 75 per cent of the candidate\'s RTP Stipend rate. Income unrelated to the candidates course of study or income received for the candidates course of study but not for the purposes of supporting general living costs is not taken into account.; To be eligible for a RTP Fees Offset a candidate must not be receiving an equivalent award of scholarship from the Commonwealth designed to offset RHD tuition fees.', sc.`scholarship_amount` = 'Up to AUD $114000', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/745610/research-training-program-rtp-stipend-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-training-program-rtp-stipend-scholarship-research/8bb271e210abf5102281316d6a2701bb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00219C' AND sc.`scholarship_name` = 'Research Training Program (RTP) Stipend Scholarship (Research)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Southeast Asia Excellence Scholarship offers a 25% course fee reduction to offshore international students from Southeast Asian countries.  It supports greater diversity by encouraging students from the region to pursue their studies in an inclusive, globally engaged environment.', sc.`eligibility` = 'To receive the Southeast Asia Excellence Scholarship, you must be an international student and apply from outside Australia. Additionally, you must be a citizen of one of the following Southeast Asian countries: Brunei, Cambodia, Indonesia, Laos, Malaysia, Myanmar, Philippines, Singapore, Thailand, Timor-Leste (East Timor), or Vietnam.', sc.`scholarship_amount` = '25% for new students', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.cqu.edu.au/study/prepare/scholarships/find-a-scholarship/1247065/southeast-asia-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/southeast-asia-excellence-scholarship/7889778b06f7c7438cc4d145030756ed', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00219C' AND sc.`scholarship_name` = 'Southeast Asia Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Commonwealth Governments Research Training Program (RTP) provides funding to universities to support the research training of both domestic and international higher degree research (HDR) candidates. The funding provided through the RTP offers the provision for universities to administer and award a number of stipend scholarships known as Australian Government Research Training Program (RTP) Scholarships. These awards are governed by the Commonwealth Scholarship Guidelines (Research) 2017. Griffith University awards RTP Stipends via a competitive application process to candidates commencing or enrolled in a HDR program. RTP Stipends are provided to assist with candidates general living costs and do not cover program tuition fees. This website sets out the allowances and conditions attached to the RTP Stipend award.', sc.`eligibility` = 'be commencing or enrolled in a HDR program (for which RTP support is available) at Griffith University.; not be receiving income from another source to support the candidates general living costs that provides a benefit greater than 75% of the GUPRS stipend rate to undertake the proposed program. Income unrelated to the candidates HDR program, or income received for the candidates HDR program but not for the purposes of supporting general living costs, is not to be taken into account.', sc.`scholarship_amount` = 'AUD $35656/year — RTP Stipends are provided to assist with candidates’ general living costs and do not cover program tuition fees.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.griffith.edu.au/research-study/scholarships/au-gov-research-training-program', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australian-government-research-training-program/89c369e992f49267872d97838a4c368c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00233E' AND sc.`scholarship_name` = 'Australian Government Research Training Program' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Our Griffith College Diploma to Degree Scholarship rewards outstanding Griffith College Diploma graduates who are articulating into an undergraduate degree program at Griffith University.', sc.`eligibility` = 'Please contact Griffith University for further information.', sc.`scholarship_amount` = '$3,000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/griffith-college-diploma-degree', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/griffith-international-scholarship-for-griffith-college-diploma-to-degree-following-completion-of-a-griffith-college-diploma/a19bf63ab53a0c420bef6774828ea7a7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00233E' AND sc.`scholarship_name` = 'Griffith International Scholarship for Griffith College Diploma to Degree (following completion of a Griffith College diploma)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Our International Academic Merit Scholarship recognises international students with strong academic results applying for undergraduate and postgraduate coursework programs at Griffith University.', sc.`eligibility` = 'Applicant must be a citizen of a country other than Australia or New Zealand. Have a minimum GPA in previous studies of 4.5 on a 7 point scale or equivalent. Satisfy all academic and English language entry requirements for your chosen undergraduate or postgraduate coursework program. Be a full-time student starting in any trimester in 2026 or 2027. Excludes the following programs: Bachelor of Medical Science, Bachelor of Dental Health Science, Doctor of Medicine, Master of Dentistry, Master of Speech Pathology, MBA and Graduate Diploma of Flight Management (see full list in Terms and Conditions).', sc.`scholarship_amount` = '20% of tuition fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/international-academic-merit-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-academic-merit-scholarship/8365995ba87a8d52f4444e9a523e46d3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00233E' AND sc.`scholarship_name` = 'International Academic Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The founding Vice Chancellor of Griffith University, Professor John Willett (1922 - 1993) is remembered by many people throughout Australia as an academic and organisation builder of insight, innovation and drive. In memory of Professor Willett\'s work in management education, particularly in Asia, a fund was established to provide a scholarship for students from selected countries in Asia within the Griffith Business School, formerly the Graduate School of Management. The John Willett International Scholarship will offer a 50% tuition fee waiver for a maximum period of two years for the selected recipient to complete their Master of Global Development at Griffith. This will provide an opportunity for the recipient to acquire knowledge and skills needed to promote global sustainable development.', sc.`eligibility` = 'Please contact Griffith University for further information.', sc.`scholarship_amount` = '50% of tuition fees', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/john-willett-international-endowed-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/john-willett-international-scholarship/b160f2eb575dd92a7a1eb20713ef8ae4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00233E' AND sc.`scholarship_name` = 'John Willett International Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Our Vice Chancellor\'s International Scholarship rewards exceptional international students applying for undergraduate and postgraduate coursework degree programs at Griffith University.', sc.`eligibility` = 'Applicants must: Be a citizen of a country other than Australia or New Zealand; Have a minimum GPA in previous studies of 6.0 or above on a 7 point scale or equivalent; Have received an offer to study at Griffith by the scholarship application closing date; Satisfy all academic and English language entry requirements for your chosen undergraduate or postgraduate coursework program; Be a full-time student starting in 2026 or 2027.', sc.`scholarship_amount` = 'Valued at 50% of tuition fees.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Architecture, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Creative arts', sc.`website` = 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/vice-chancellors-international-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-international-scholarship/2e5d9eba62517e3f72417b98c198a85a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00233E' AND sc.`scholarship_name` = 'Vice Chancellor\'s International Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Griffith offers these respected scholarships to outstanding students commencing their first-ever undergraduate degree in 2026. The Vice Chancellor\'s Academic Achievement Scholarships will be focused on excellence and will also consider the barriers to education that students have faced.', sc.`eligibility` = 'To be eligible, you must: be either: an Australian Citizen or Australian Permanent Humanitarian Visa holder.; an Australian Permanent Resident, New Zealand Citizen or international student who is completing or has completed Years 11 and 12 in Australia.; be a student commencing university for the first time in Trimester 1 2026.; have not undertaken/commenced any tertiary study (bachelor degree or postgraduate degree), with the exception of that undertaken as part of Year 11–12 studies (e.g. Enhanced Studies program, Head Start).; have applied to commence at Griffith University in Trimester 1 2026 through either Queensland Tertiary Admissions Centre (QTAC); Universities Admission Centre (UAC), or via direct entry.; receive an unadjusted ATAR of 95.45 or above (or equivalent rank OP 3 or above, and IB 37 or above). Griffith may use your Educational Disadvantage Assessment score* to adjust your ATAR rank.', sc.`scholarship_amount` = 'Up to AUD $15000 — Maximum value of the scholarship is determined by the length of the undergraduate degree for which you are awarded, and is calculated at a rate of $625/10 CP. For example: $15,000 for a single degree (240 CP), $20,000 for a double', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = 'Accounting, Agriculture, Architecture, Built environment, Business and management, Communications, Computing and information technology, Environmental studies, Dentistry, Economics, Education and training, Engineering and technology, Rehabilitation, Health services and support, Tourism and hospitality, Humanities and social sciences, Languages, Law, Para-legal studies, Pharmacy, Sport and leisure, Mathematics, Medicine, Nursing, Psychology, Sciences, Social work, Surveying, Veterinary science, Creative arts', sc.`website` = 'https://www.griffith.edu.au/scholarships/scholarship-listings/vice-chancellors-academic-achievement-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-academic-achievement-scholarship/76d97f3c27985f7fc003c788692c7cf3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00233E' AND sc.`scholarship_name` = 'Vice-Chancellor\'s Academic Achievement Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University of Southern Queensland will offer grants to non-award international students commencing or continuing their enrolment in the Study Abroad program, in Trimester 1, Trimester 2 or Trimester 3 2025.', sc.`eligibility` = 'Applicants must:; Be an international student; Be commencing or continuing their studies in the Study Abroad program (fee paying) at UniSQ in Trimester 1, Trimester 2 or Trimester 3 2025; Be studying on-campus; Be enrolled in a minimum of three study units for each trimester in accordance with the duration of the grant awarded; Be studying the Study Abroad program (fee paying) at UniSQ (not be studying Cross-institutional, Professional Development, Bachelor or Master courses); Have not already been awarded two grants over two trimesters.', sc.`scholarship_amount` = 'Up to AUD $2000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.unisq.edu.au/scholarships/unisqi-incoming-study-abroad-international-travel-grant', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/incoming-study-abroad-international-travel-grant-2025/961ed1ebae9e8031d02f0316af6f7e51', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00244B' AND sc.`scholarship_name` = 'Incoming Study Abroad International Travel Grant - 2025' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'In 2025, the University of Southern Queensland (UniSQ) will offer scholarships to new international students studying on-campus, external or online. This scholarship is based on meeting the entry requirements for the program of study and maintaining satisfactory academic performance for duration of study at UniSQ. International students in all areas of award programs undergraduate, postgraduate and research are welcome to apply.', sc.`eligibility` = 'Applicants must:; Be an international student; Be enrolled in on-campus, external or online mode; Be a commencing student (i.e. be new to UniSQ) in 2025; meet the academic and English requirements for the UniSQ award program for which they apply; not be in receipt of another UniSQ tuition fee scholarship; not be a sponsored student, unless student is sponsored by an NGO or a government of a low or middle income country; not be studying through an offshore partner.', sc.`scholarship_amount` = 'Each scholarship will have a maximum value of 15% of the tuition fees for the duration of the approved award program and will be applied as a 15% reduction of the tuition fees. (Students are responsible for paying the remainder of the fees as per the', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.unisq.edu.au/scholarships/unisq-international-student-support-scholarship-2025', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-student-support-scholarship-2025/e5dc6cf372245a8b0fce1d4882c288c9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00244B' AND sc.`scholarship_name` = 'International Student Support Scholarship - 2025' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'There’s more than one path to university. As an international student in Australia, you may be eligible for the Alternative Study Path Scholarship if you have completed studies onshore, or if you are in Australia and in the process of applying for a student visa. This scholarship covers 15 percent of your total course tuition.', sc.`eligibility` = 'As an international student in Australia, you may be eligible if you have completed an onshore English language program, Australian Year 12, a vocational program or six months of higher education study (unless a release from your current registered provider is obtained, or you may be in the process of applying for a Student Visa onshore in Australia).; Postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. Scholarship applicable on tuition fee only and on first attempt subjects only. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study.', sc.`scholarship_amount` = '15% of your total tuition costs', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alternative-study-path-scholarship/368c2664ec5711c69611a4bb473179f7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00246M' AND sc.`scholarship_name` = 'Alternative Study Path Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Does your passport say you re from Latin America or Europe? If so, you have the chance to take advantage of this scholarship, which gives you 15 percent off your total course tuition when you start studying Health at Think Education.', sc.`eligibility` = 'Regional scholarships are provided based on new international students’ passports. Undergraduate and postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. Scholarship applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study.', sc.`scholarship_amount` = '15% of your total tuition costs', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/americas-european-health-scholarship/f73ec300f90be6735ac6214c95f2d743', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00246M' AND sc.`scholarship_name` = 'Americas & European Health Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you are from Asia or Greater China and are planning to combine an English language course with one of our Health degrees, you have the opportunity to apply for this regional scholarship. It will cover 20 per cent of your total course tuition.', sc.`eligibility` = 'Regional scholarships are provided based on new international students’ passports. Undergraduate students need to display a credit average from high school, and postgraduate students need to display a credit average in a previous degree.; Undergraduate and postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. The scholarship is applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. The scholarship may not be eligible for any course changes during the duration of study.', sc.`scholarship_amount` = '20% of your total tuition costs', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/asia-greater-china-health-merit-scholarship/5595f4e6d4ce3cb71571fd83ffc0f094', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/asia-greater-china-health-merit-scholarship/5595f4e6d4ce3cb71571fd83ffc0f094', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00246M' AND sc.`scholarship_name` = 'Asia & Greater China Health Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Do you have a certified passport from Japan? Are you planning to study one of our Diploma or Bachelor of Health Science courses at Think Education? If so, you have the chance to take advantage of a scholarship that will cover 20 percent of your total course tuition.', sc.`eligibility` = 'Applicable to new Japanese applicants only, who will be commencing their studies in 2024.; Undergraduate and postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. Scholarship applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study.', sc.`scholarship_amount` = '20% of your total tuition costs', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/japanese-undergraduate-health-science/47e9e0dfaba68a6e9d2ef32c6bc81a3e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00246M' AND sc.`scholarship_name` = 'Japanese Undergraduate Health Science' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you re starting your studies offshore and online, you can take advantage of this scholarship, which offers up to 30 percent off your total course tuition (you have to continue studying offshore and online for the whole course).', sc.`eligibility` = 'Applicable to full-time undergraduate and postgraduate students studying the full duration of their course offshore. Scholarship applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study.', sc.`scholarship_amount` = 'up to 30% of your total tuition costs', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.think.edu.au/studying-with-us/fees-scholarships/scholarships/international-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/offshore-online/d750628fce4a7e2155697f03e5b108c4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00246M' AND sc.`scholarship_name` = 'Offshore Online' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The ECU Creative Excellence Scholarship is offered to international students commencing in eligible creative discipline courses at ECU. The scholarship offers a 10 percent reduction in your tuition fees for the duration of your course. The scholarship is open to future international students seeking to enrol at Edith Cowan University in one of the designated undergraduate courses.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen); study onshore at ECU City Campus; not be in receipt of a government scholarship or industry sponsorship; not be in receipt of another ECU scholarship; meet both ECU\'s Academic and English Proficiency entry requirements for the course and commence study onshore at ECU, Western Australia in Semester One, 2026 or Semester Two 2026; be entering into one of the eligible courses', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/2026-ecu-creative-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-ecu-creative-excellence-scholarship/423f95553a7087c2e1c39b1f19289b52', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = '2026 ECU Creative Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Edith Cowan University (ECU), in partnership with the Stan Perron Charitable Foundation, is offering top-up scholarships for 2026 to support impactful research in child health. These scholarships are designed to attract motivated and passionate Higher Degree by Research (HDR) candidates who want to improve the health and wellbeing of children and young people in Western Australia.', sc.`eligibility` = 'To be eligible, you must:; Undertake research within Childhood Health, adopting The Nest framework to define health holistically. This includes physical, mental, emotional, social, and spiritual dimensions of wellbeing, recognising the interconnected factors that contribute to thriving across the life course.; Be enrolled into a PhD course at ECU.', sc.`scholarship_amount` = 'AUD $10000/year', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/2026-ecu-stan-perron-charitable-foundation-top-up-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-ecu-stan-perron-charitable-foundation-top-up-scholarship/52ad7937b4b64f0d717038fa3b95d601', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = '2026 ECU Stan Perron Charitable Foundation Top Up Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This bursary is intended to support travel costs for international non-award students who study at Edith Cowan University for only 1 semester or 1 year in 2026.', sc.`eligibility` = 'To be eligible for this bursary you must:; be an international student studying in one of the categories below:; Study Abroad, Student Exchange, Joint Master’s; be studying a minimum 45 credit points in one of the above categories on-campus for the first time commencing in Semester 1, 2026 or Semester 2, 2026; be able to meet mandatory vaccination and travel requirements set by the Australian and Western Australian Governments; have paid $2,000 to the Australian Government for the Student Visa application, lodged on or after 1 July 2025 (and provide evidence when requested); have paid $1,600 to the Australian Government for the Student Visa application, lodged on or after 1 July 2024 (and provide evidence when requested); have had the Student Visa subsequently approved; accept the bursary notification offer within 28 calendar days, for the bursary payment to be made.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/2026-ecu-study-abroad-bursary', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-ecu-study-abroad-bursary/5f35eb197b41cef6288776d788b0ab5d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = '2026 ECU Study Abroad Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This bursary is to provide new international students commencing at ECU in 2026 or 2027 with a total of $1,000 - $1,500 allowance to support them with living costs, while studying Bachelor of Science (Nursing) C33 on ECU Southwest Campus.', sc.`eligibility` = 'To be eligible for this bursary you must:; be a full-fee paying on-campus international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen); be commencing Bachelor of Science (Nursing) C33 at ECU Southwest (Bunbury) Campus in 2026 or 2027; be a new international student commencing Bachelor of Science (Nursing) C33 at ECU Southwest in 2026 or 2027 through direct entry, i.e. not through a pathway packaged program, not an existing ECU student (except ECU Alumni).; not receive a government scholarship or industry sponsorship or ECU full scholarship for your studies.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/2026-2027-ecu-bachelor-of-science-nursing-c33-regional-living-allowance-bursary', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-2027-ecu-bachelor-of-science-nursing-c33-regional-living-allowance-bursary/0cff13b1593fbc50090c8350a7a766c9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = '2026-2027 ECU Bachelor of Science (Nursing) C33 Regional Living Allowance Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Greg Benjamin WAAPA Music Equity Scholarship has been established to support students enrolled in WAAPA\'s Bachelor of Music. The Scholarship is aimed to assist students to complete their course who have a passion for Music and are experiencing financial hardship. The scholarship is valued at $11,000 for 1 year ($5,500 per Semester)', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, International Student Visa Holder or International Non-Student Visa Holder; be enrolled in the Bachelor of Music or Bachelor of Music Honours course at WAAPA; have and maintain an academic progression status of GREEN; be studying full-time on campus (60 credit points or course equivalent); be able to demonstrate financial hardship; not be in receipt of another scholarship over $5000', sc.`scholarship_amount` = 'Up to AUD $11000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/greg-benjamin-waapa-music-equity-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/greg-benjamin-waapa-music-equity-scholarship/7fa9c34ddadf4550def9ec2063b191db', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = 'Greg Benjamin WAAPA Music Equity Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Greg Benjamin WAPPA Music Excellence Scholarship is awarded to an exceptional Piano student in the jazz or classical discipline. Students enrolled in the Bachelor of Music course in Piano (jazz or classical) will automatically be considered for the Scholarship. The Scholarship is valued at $11,000.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, International Student Visa Holder or International Non-Student Visa Holder; be enrolled in W76 - Bachelor of Music - Piano (Jazz or Classical) at WAAPA; have and maintain an academic progression status of GREEN; be studying full-time on campus (60 credit points or course equivalent); not be in receipt of another scholarship over $5000 per annum; not be a previous recipient of the Greg Benjamin Entrance Scholarship.', sc.`scholarship_amount` = 'Up to AUD $11000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/greg-benjamin-waapa-music-excellence-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/greg-benjamin-waapa-music-excellence-scholarship/85dd2fd3dd9ee57b53c029139c6f3a95', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = 'Greg Benjamin WAAPA Music Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Lincoln McCashney Memorial Scholarship is awarded to recognise an Education student who demonstrates the qualities that made the late Lincoln McCashney such an outstanding teacher, educator and mentor to many ECU students, thereby encouraging the development of those qualities and honouring Lincoln\'s contribution to education in WA. The scholarship is valued at up to $5,000 as a one-off payment.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, New Zealand citizen or International student; have an academic progression status of GREEN; be enrolled in a Bachelor of Education and be on track to complete a minimum of 360 credit points by end of Semester 2, 2026; be studying a minimum of 30 credit points; have a minimum weighted average mark (WAM) of 60%', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/lincoln-mccashney-memorial-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/lincoln-mccashney-memorial-scholarship/1240f5ceb8aba0d18d7f5f42ef764581', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = 'Lincoln McCashney Memorial Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This three-year PhD project, part of the ARC Industrial Transformation Research Hub for Critical Energy Separation Materials (ARC CREST), will develop an innovative and sustainable pathway for lithium recovery by coupling α-spodumene processing with downstream solvent-based direct lithium extraction (DLE). The research will focus on optimising lithium extraction and purification, understanding the effects of feedstock properties and impurities, and integrating the processes into an efficient flowsheet. The project offers multidisciplinary experience in critical mineral processing, hydrometallurgy, solvent extraction, materials characterisation, and process optimisation.', sc.`eligibility` = 'This position is open to domestic and international candidates. To be eligible for this scholarship applicants must:; Meet the entry requirements for a PhD at ECU; Hold a Master by Research degree in chemical engineering, metallurgical/extractive metallurgy, chemistry, materials science, or a closely related discipline', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/phd-scholarship-coupling-downstream-solvent-based-direct-lithium-extraction-with-direct-alkaline-digestion-of-spodumene-arc-crest', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/phd-scholarship-solvent-based-direct-lithium-extraction/00ef7fa940dea61c58707ab9e5a9861f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = 'PhD Scholarship - Solvent-Based Direct Lithium Extraction' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Haselhurst Family Scholarship in Contemporary and Jazz - Vocal has been established to support Bachelor of Music (Contemporary or Jazz Performance) students with a specialisation in Vocal. The scholarship will provide financial support to students who demonstrate a \'need\' that requires financial aid to be able to graduate their course. The scholarship is valued at $7,500 as a one off payment.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, New Zealand citizen or International student; have and maintain an academic progression status of GREEN; experiencing financial difficulties; be enrolled full-time (60 credit point minimum requirement) in one of the below courses majoring in either- Contemporary or Jazz Performance with a specialisation in Vocal: Bachelor of Music, Bachelor of Music Honours; previous recipients can reapply.', sc.`scholarship_amount` = 'Up to AUD $7500', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/the-haselhurst-scholarship-contemporary-and-jazz-vocal', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-haselhurst-family-scholarship-contemporary-and-jazz-vocal/ad6c3a826281adec1e4bb0583757951a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = 'The Haselhurst Family Scholarship - Contemporary and Jazz - Vocal' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Haselhurst Family Scholarship in Classical Performance has been established to support Classical Performance students enrolled in WAAPA\'s Bachelor of Music. The scholarship will provide financial support to students who demonstrate a need that requires financial aid to be able to graduate their course. The $10,000 Scholarship is paid as $5000 across 2 semesters.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an Australian citizen, Australian permanent resident, New Zealand citizen or International student; have and maintain an academic progression status of GREEN; experiencing financial difficulties; be enrolled full-time (60 credit point minimum requirement) in one of the below courses with a major in  - Classical Performance:; Bachelor of Music, Bachelor of Music Honours; previous recipients can reapply', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/the-haselhurst-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-haselhurst-family-scholarship-in-classical-performance/d797cf8de63e33cff89517bb625c0406', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = 'The Haselhurst Family Scholarship in Classical Performance' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Western Australian Premier’s WACE Bursary (the Bursary) provides successful international Western Australian Certificate of Education (WACE) graduates with a total payment of $20,000 towards their living, travel and study expenses. The Bursary is provided to support international WACE graduates who commence undergraduate or tertiary pathway studies in-person at one of Western Australia\'s 5 universities or as part of a packaged pathway course to one of these university.', sc.`eligibility` = 'Please contact Edith Cowan University (ECU) for further information.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/the-western-australian-premiers-wace-bursary', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-western-australian-premiers-wace-bursary/625a3086c4f23d30e20bc76c498ab223', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00279B' AND sc.`scholarship_name` = 'The Western Australian Premier’s WACE Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The NTG Operation Thrive Veteran Community Scholarships aims to provide scholarships for Australian Defence Force veterans, their partners and dependents in alignment with the Operation Thrive campaign. Operation Thrive is a Territory wide initiative to support veterans and their families with transition, employment, education, health, wellbeing, respect and recognition. The initiative was created based on the real-life experiences and insights of veterans and families in the Territory.', sc.`eligibility` = 'Ensure that you meet the eligibility criteria of this scholarship before applying.; Must be a current resident of the Northern Territory; Must be enrolled in a Higher Education course at CDU; Must be commencing the course no earlier than semester 2 2026; Must be a Veteran or partner/dependent of a Veteran; Must submit DVA Certified White Card, Gold Card or Defence Common Access Card; or a statutory declaration from the serving member/veteran confirming the partner\'s or dependent\'s relationship to the member', sc.`scholarship_amount` = 'Up to AUD $15000 — $2,500 per semester, and an additional $1,200 (one-off) for computer or tools in the first semester', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://stapps.cdu.edu.au/apex/f?p=1000:600', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ntg-operation-thrive-veteran-community-scholarship/8026b88f6316265874cf82ad7e75b314', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00300K' AND sc.`scholarship_name` = 'NTG Operation Thrive Veteran Community Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Larsen Jewellery Scholarship (Scholarship) has been developed by Larsen Jewellery to support and educate young adults wishing to begin a career in jewellery, design or visual arts; or who wish to further their studies in a jewellery, design or visual arts related course.', sc.`eligibility` = 'Be either accepted, enrolled or in the process of applying to a relevant course related to design or program at an Australian University or TAFE.', sc.`scholarship_amount` = 'Up to AUD $3000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7861', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-larsen-jewellery-scholarship/6c0113bbd69daab6c75128205faa530d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = '2026 - Larsen Jewellery Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Curtin On-Campus Accommodation Equity Bursary (the Scholarship) has been established to provide assistance for domestic and international students living in on-campus accommodation at Curtin Bentley who are experiencing financial hardship.', sc.`eligibility` = 'Applicants must meet all of the following criteria to be eligible to apply for the Scholarship:; Domestic or international student; Have applied for a place (or currently residing) in one of the following on-campus accommodation residences at Curtin Bentley in a Semester 2, 2026 agreement at the time of application:; St. Catherine\'s College\r\n,Twin Dolphin Hall, Kurrajong Village, Erica Underwood House, Guild House, Vickery House; Have a minimum Course Weighted Average (CWA) of 50 (if applicable) at the time of applying', sc.`scholarship_amount` = 'Up to AUD $3000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7885', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-semester-2-curtin-on-campus-accommodation-equity-bursary-bentley/fb339ebd91e8e4bfdd95c53209dc5245', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = '2026 - Semester 2 - Curtin On-Campus Accommodation Equity Bursary - Bentley' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Curtin On-Campus Accommodation Equity Bursary (the Scholarship) has been established to provide assistance for domestic and international students living in on-campus accommodation at Curtin Kalgoorlie who are experiencing financial hardship.', sc.`eligibility` = 'Applicants must meet all of the following criteria to be eligible to apply for the Scholarship:; Domestic or international student; Enrolled (minimum 25 credits) in an eligible degree at Curtin in Semester 2, 2026; Have applied for a place (or currently residing) at Agricola, Curtin Kalgoorlie on-campus accommodation in Semester 2, 2026 and/or 2026 annual agreement at the time of application; Have a minimum Course Weighted Average (CWA) of 50 (if applicable) at the time of applying.', sc.`scholarship_amount` = 'Up to AUD $2600', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7886', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-semester-2-curtin-on-campus-accommodation-equity-bursary-kalgoorlie/6958e43cce0a1fa57f318d9d5970ada5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = '2026 - Semester 2 - Curtin On-Campus Accommodation Equity Bursary - Kalgoorlie' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Knight-Hennessy Scholars Program supports outstanding graduate students from around the world to pursue an eligible graduate degree at Stanford University in the United States. The program offers scholars the opportunity to join a diverse, multidisciplinary community while participating in leadership development alongside their Stanford studies.', sc.`eligibility` = 'To be eligible to apply, applicants must:; have earned, in January 2020 or later, a U.S. bachelor\'s degree or an equivalent qualification from a recognised college or university; apply to, be accepted by and enrol in an eligible full-time Stanford graduate degree program; meet one of the following conditions:; apply separately but concurrently to Knight-Hennessy Scholars and a full-time Stanford graduate degree program, commencing both in the same year; be a current Stanford graduate student applying to add a new full-time Stanford graduate degree program, commencing both Knight-Hennessy Scholars and the new program in the same year; be a current Stanford PhD student in the first year of enrolment, applying to begin Knight-Hennessy Scholars in the second year of PhD enrolment.', sc.`scholarship_amount` = 'funding for up to three years of graduate study at Stanford, depending on the length of the degree program; a stipend for living and academic expenses, plus a travel stipend for one annual trip to and from Stanford; leadership development opportuniti', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7996', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2027-knight-hennessy-scholars-program-at-stanford-university/002f40f37e2b4cfd47337788e2be89b2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = '2027 - Knight Hennessy Scholars Program at Stanford University' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Curtin Humanitarian Scholarship (Scholarship) has been developed by Curtin University to support Curtin undergraduate and postgraduate students from a refugee-like background who are experiencing financial difficulty in meeting the costs of pursuing higher education.', sc.`eligibility` = 'Australian citizen, Australian permanent resident, Australian permanent humanitarian visa holder, New Zealand citizen or an international student with any of the below:;  The applicant has applied for a Protection visa in Australia and is the holder of one of the following visas:; o Bridging visa A (class WA) (Subclass 010); o Bridging visa C (Class WC) (Subclass 030); o Bridging visa E (Class WE) (Subclass 050 or Subclass 051); o Bridging visa R (Class WR) (Subclass 070); the applicant is the holder of one of the following temporary visas:; Temporary (Humanitarian Concern) visa (Class UO) (Subclass786); Temporary Safe Haven visa (Class UJ) (Subclass 449); Temporary Protection visa (Class XD) (Subclass 785); Safe Haven Enterprise visa (Class XE); Higher education Visa (subclass 573)', sc.`scholarship_amount` = 'Up to AUD $5000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7943', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2027-semester-1-curtin-humanitarian-scholarship-future-students/1c720b717ee89ae6dfb1fa9434d6086e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = '2027 - Semester 1 - Curtin Humanitarian Scholarship (Future Students)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Australia Awards Scholarship (AAS) are funded by Australian Government to provide higher education opportunities for people from developing countries to study in Australia to build the skills and knowledge to drive change as the next generation of global leaders. These scholarships aim to contribute to the development needs of Australia\'s partner countries in line with bilateral and regional agreements. Scholarships are mainly at postgraduate level however there is a limited number of undergraduate scholarships (country specific). Curtin will work with AAS recipients to equip you with the skills and knowledge you need to drive change and contribute to the economic and social development in your home country and build enduring connections within the community.', sc.`eligibility` = 'Please Contact Curtin University for more information', sc.`scholarship_amount` = 'Please Contact Curtin University for more information', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=990', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australia-awards-scholarships/aeffe1368ecc0d3be7a6f908581c1911', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'Australia Awards Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Curtin University strives to give international students the opportunity to pursue their ambitions and gain a world-class education through the Curtin Global Future Leader Scholarship. This scholarship provides eligible students a one-off credit of AUD$10,000 against the tuition fee of the course they are undertaking.', sc.`eligibility` = 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Will be studying in an eligible Curtin undergraduate degree course, OR a Masters degree by coursework (your Course); Will be studying at a Curtin Western Australian campus (WA Campus) commencing in 2027; Will be studying at least 1.5 years (minimum of 300 credits) (Scholarship term) at the WA Campus; Achieved a Credit level in your academic status with the required Course-Weighted-Average or equivalent scores in your most recent and eligible course of study.; Are not enrolled in one of the following: (1) Not-for-Degree Exchange or Study Abroad program (2) campus transfer from a Curtin global campus (3) a recognised joint program at a Curtin Transnational Partner Location outside Australia; Will not be enrolled in one of the courses excluded from this Scholarship program. The list of Excluded courses is determined by Curtin University and may change without notice.; Are not a recipient of an international scholarship offered by Global Curtin in a previous course of study at Curtin that is incomplete.', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7987', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/curtin-global-future-leaders-scholarship-10k/c09137a5e1f93ee8fc7591832426817c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'Curtin Global Future Leaders Scholarship ($10K)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Curtin Global Merit scholarship is designed to reward academic performance and empower students to continue their education and further their success in their chosen field. Eligible students will receive 20% off the tuition fee for the duration of the course.', sc.`eligibility` = 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Are enrolled in a Curtin undergraduate degree course OR a Master degree by coursework; Will be studying at a Curtin Western Australian campus (WA Campus) commencing in 2027 or 2028; Achieved Distinction status in your academic status with the required Course-Weighted Average or equivalent scores in your most recent and eligible course of study. This is determined by Curtin University and may change without notice; Are not enrolled in one of the following: (1) Not-for-Degree Exchange or Study Abroad program (2) campus transfer from a Curtin global campus (3) a recognised joint program at a Curtin Transnational Partner Location outside Australia; Will not be enrolled in one of the courses excluded from this Scholarship program. The list of Excluded courses is determined by Curtin University and may change without notice.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7986', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/curtin-global-merit-scholarship/7c5d1fe2b1099be574eb603de128876c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'Curtin Global Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A dedicated scholarship for international students who have commenced their studies at one of Curtin\'s global campuses or in a recognised joint program at Curtin\'s offshore partner location. This scholarship provides eligible students who wish to transfer to the Curtin Western Australian campus for the remaining duration of their degree, with a one-off credit of AUD$10,000 towards their tuition fees.', sc.`eligibility` = 'This scholarship is only for:; International, full fee-paying, non-sponsored students of any nationality except Australian; Will be studying either an undergraduate or postgraduate degree by coursework (Course); Will be studying at a Curtin Western Australian campus (WA Campus) commencing in 2027; Will be studying at least one year (minimum of 200 credits) (Scholarship term) at the WA Campus; Are enrolled in one of the following: (1) campus transfer from a Curtin global campus of the same course level (2) a recognised joint program at a Curtin Transnational Partner Location outside Australia (3) Not-for-Degree Exchange or Study Abroad program', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7994', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/curtin-global-talent-scholarship/28bec936ceada8b303eee4ddcf385649', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'Curtin Global Talent Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Curtin Student Guild Childcare Grant is a SSAF funded program designed to assist current Curtin students who have demonstrated that financial hardship has prevented access to childcare while attending class, practicums, exams, supervisor meeting etc.', sc.`eligibility` = 'Currently enrolled Curtin student (Must provide Confirmation of Enrolment).; Primary carer for a child under the age of 12.; In receipt of a means tested Centrelink benefit or on low income (Must provide 3 months bank statements/transactions).; Have an unexpected need to access childcare services in order to satisfactorily meet the current study commitments.; With the assistance of the Guild’s Financial counsellor, demonstrate financial hardship', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=4051', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/curtin-student-guild-childcare-grant/cc275a393ecb35130543d3f069fb31e0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'Curtin Student Guild Childcare Grant' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This Curtin top up scholarship supports high-achieving Vietnamese candidates to undertake a Doctor of Philosophy (PhD) at Curtin University, Perth Western Australia.', sc.`eligibility` = 'To be eligible to apply you must:; Be a citizen or permanent resident of Vietnam at the time of your application; Meet Curtin\'s PhD eligibility requirements.; Meet Curtin\'s English language proficiency requirements', sc.`scholarship_amount` = 'Up to AUD $100000 — Curtin will provide the below benefits:; Top up living stipend up to the current Curtin PhD stipend rate to support students whilst studying in Australia (Curtin stipend rate is AUD $37,500 per annum in 2025. Curtin PhD Stipends a', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=6612', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/curtin-university-top-up-scholarship-vietnam-government-phd-scholarship-project-89/2bb4674c0cf48d6f53d386fc251e9254', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'Curtin University top up scholarship - Vietnam Government PhD Scholarship (Project 89)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Global Scholars program offers a global perspective and industry connections while completing a Curtin degree at two of our global campuses.', sc.`eligibility` = 'This scholarship is only for:; Students of the Global Scholars Program at Curtin; Are International, fee-paying, non-sponsored students of any nationality except Australian; have successfully completed 200 credits at one of Curtin\'s global campuses within two study periods, in a selected undergraduate degree course (Course) of the Global Scholars Program; Will be studying at least two years in duration (minimum of 400 credits) at the Perth Western Australia (Perth) Campus', sc.`scholarship_amount` = 'Up to AUD $15000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7566', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/global-scholars-program-scholarship/a897bb19dcc52cb1dfea239bcb27f9e8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'Global Scholars Program Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Through the John Curtin Global Excellence Scholarship, eligible students will receive 40% off the tuition fee for the duration of the course. Curtin University is proud to award this prestigious scholarship to students who have demonstrated exceptional academic performance and a commitment to excellence in their studies.', sc.`eligibility` = 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Are enrolled in a Curtin undergraduate degree course OR a Master degree by coursework; Will be studying at a Curtin Western Australian campus (WA Campus) commencing in 2027 or 2028; Achieved a Course-Weighted Average (CWA) of 95% or equivalent scores in your most recent and eligible course of study. This is determined by Curtin University and may change without notice; Are not enrolled in one of the following: (1) Not-for-Degree Exchange or Study Abroad program (2) campus transfer from a Curtin global campus (3) a recognised joint program at a Curtin Transnational Partner Location outside Australia; Will not be enrolled in one of the courses excluded from this Scholarship program. The list of Excluded courses is determined by Curtin University and may change without notice.', sc.`scholarship_amount` = 'This scholarship provides eligible students 40% off the tuition fee of the course they are undertaking.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7985', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/john-curtin-global-excellence-scholarship/7ab822cf002b4ccacc7ea2103c71e19e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'John Curtin Global Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Curtin University strives to give international students the opportunity to pursue their ambitions and gain a world-class education through the Curtin Global Future Leader Scholarship. This scholarship provides eligible students a one-off credit of AUD$12,500 against the tuition fee of the course they are undertaking.', sc.`eligibility` = 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Are enrolled in a non-quota Curtin undergraduate degree course or Master degree by coursework (Course); Will be studying at a Curtin Western Australian campus (WA Campus) commencing in a study period between May - December 2026; Will be studying at least 1.5 years (minimum of 300 credits) (Scholarship term) at the WA Campus; Achieved a strong Credit level or equivalent Course-Weighted-Average in your most recent and eligible course of study.', sc.`scholarship_amount` = 'Up to AUD $12500', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7844', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/semester-2-2026-curtin-global-future-leaders-scholarship/2ca651763e993507b91bc53999c99479', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'Semester 2 - 2026 - Curtin Global Future Leaders Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Curtin University strives to give international students the opportunity to pursue their ambitions and gain a world-class education through the Curtin Global Future Leader Scholarship. This scholarship provides eligible students a one-off credit of AUD$10,000 against the tuition fee of the course they are undertaking.', sc.`eligibility` = 'This scholarship is only for:; International, fee-paying, non-sponsored students of any nationality except Australian; Are enrolled in a non-quota Curtin undergraduate degree course or Master degree by coursework (Course); Will be studying at a Curtin Western Australian campus (WA Campus) commencing in a study period between May - December 2026; Will be studying at least 1.5 years (minimum of 300 credits) (Scholarship term) at the WA Campus; Achieved a minimum Credit level or equivalent Course-Weighted-Average in your most recent and eligible course of study.', sc.`scholarship_amount` = 'Up to AUD $10000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://scholarships.curtin.edu.au/Scholarship/?id=7856', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/semester-2-2026-curtin-global-future-leaders-scholarship-10k/eb124cff4a1f53ffb4c344cae79c21f7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00301J' AND sc.`scholarship_name` = 'Semester 2 - 2026 - Curtin Global Future Leaders Scholarship ($10K)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Destination Australia is an Australian Government initiative, offering amounts of up to $15,000 (AUD) per year to eligible students who wish to study full time and live in regional Australia. Our Destination Australia scholarship program is open to international & domestic students who wish to study Animation, Games, Film, Audio & Music on-campus at SAE Byron Bay in 2024.', sc.`eligibility` = 'Applicants are to be domestic or onshore international students wishing to commence study in a Bachelor Program in 2024. NOTE: International students must be residing in Australia with a valid VISA.; Applicants must be a commencing student enrolled full time at the SAE Byron Bay (on-campus study); Scholarships will be prioritized to applicants from underrepresented groups such as low socio−economic status, those who are first in family to tertiary study, those living with a disability and First Nations people.; Must demonstrate and maintain residency in the Northern Rivers Region at the time of commencing study for the duration of the scholarship Northern.; Applicants must meet SAEs published domestic or international entry requirements.', sc.`scholarship_amount` = 'Up to AUD $15000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://sae.edu.au/how-to-apply/international-scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/15k-destination-australia-scholarships/ade2ca75bbd538bf8594e03e1603a27e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00312F' AND sc.`scholarship_name` = '$15K Destination Australia Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Destination Australia is an Australian Government initiative, offering amounts of up to $15,000 (AUD) per year to eligible students who wish to study full time and live in regional Australia. Our Destination Australia scholarship program is open to international & domestic students who wish to study Animation, Games, Film, Audio & Music on-campus at SAE Byron Bay in 2024.', sc.`eligibility` = 'Applicants are to be domestic or onshore international students wishing to commence study in a Bachelor Program in 2024. NOTE: International students must be residing in Australia with a valid VISA.; Applicants must be a commencing student enrolled full time at the SAE Byron Bay (on-campus study); Scholarships will be prioritized to applicants from underrepresented groups such as low socio−economic status, those who are first in family to tertiary study, those living with a disability and First Nations people.; Must demonstrate and maintain residency in the Northern Rivers Region at the time of commencing study for the duration of the scholarship Northern.; Applicants must meet SAEs published domestic or international entry requirements.', sc.`scholarship_amount` = 'Up to AUD $15000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://sae.edu.au/how-to-apply/domestic-scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/destination-australia-scholarship/082d9016f7acd51c7d781de6582a73d9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00312F' AND sc.`scholarship_name` = 'Destination Australia Scholarship' AND sc.`course_id` IS NULL;
