UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Our Contributing Citizen Scholarships are awarded to new students who have already demonstrated strong community spirit and a desire to make a difference to the world around them.', sc.`eligibility` = 'While demonstrated leadership and community service is a significant factor, we also want our students to develop their life skills across a broad range of competencies, and other areas of strength or passion are well regarded. This may include sport, the performing arts, visual arts or design, science and technology, environmental sustainability, politics, social justice, academia, or other community endeavours.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/contributing-citizen-scholarship/f4e21f23ba668f25a9b5b493f4362a93', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/contributing-citizen-scholarship/f4e21f23ba668f25a9b5b493f4362a93', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00345G' AND sc.`scholarship_name` = 'Contributing Citizen Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = NULL, sc.`eligibility` = 'Open to one new male student and one new female student looking to enter the School in Year 7, the Head of the School Scholarship provides educational opportunity to students with proven academic performance and high potential, but who do not have the financial means to experience a St Michael’s education.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/head-of-the-school-scholarship/650c0b412c744f430e56b906abf8c2d0', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/head-of-the-school-scholarship/650c0b412c744f430e56b906abf8c2d0', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00345G' AND sc.`scholarship_name` = 'Head of the School Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'High Achiever Scholarships recognise students who have demonstrated outstanding talent in one or more areas of endeavour and who wish to continue to develop those talents. It is expected that students who receive a High Achiever Scholarships will remain committed to nurturing their talents and enriching the School through active participation in School programs.\r\n\r\nThese scholarships are not restricted to academic achievements, and applications are welcomed from new and current students who excel in one or more of the following:  sport, the performing arts – dance, drama, voice or instrumental music, visual arts and design, science and technology.', sc.`eligibility` = 'Students who have an outstanding academic record and can demonstrate excellence in two or more areas of endeavour are invited to apply for the High Achiever Scholarship. Areas of endeavour might include a specific academic subject, sport, the arts, design, leadership or community service.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/high-achiever-scholarship/308db076f187e247f3d094a60304d9f4', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/high-achiever-scholarship/308db076f187e247f3d094a60304d9f4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00345G' AND sc.`scholarship_name` = 'High Achiever Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A female student whose area of excellence is Science, Maths and/or Technology may be awarded the Judith Whitworth Science, Maths and Technology Scholarship for girls.', sc.`eligibility` = 'The Judith Whitworth Scholarship supports and promotes girls in Mathematics and Science at St Michael’s and beyond. The Whitworth Scholarship encourages young women to not only excel in Maths and Science but also look to a thriving career in the STEM fields.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/judith-whitworth-science-maths-and-technology-scholarship-for-girls/b325c71e4e246b37fff5ed93edf12a36', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/judith-whitworth-science-maths-and-technology-scholarship-for-girls/b325c71e4e246b37fff5ed93edf12a36', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00345G' AND sc.`scholarship_name` = 'Judith Whitworth Science, Maths and Technology Scholarship for Girls' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Performing Arts and Music are central to life at St Michael\'s Grammar, which is why we offer comprehensive Performing Arts Scholarships and Music Scholarships to attract and support  students with exceptional talent. These Scholarships recognise creativity, ability, and leadership. Scholarships are open to students entering Year 5-11, providing opportunities to grow as artists while experiencing all that St Michael’s has to offer.', sc.`eligibility` = 'Providing educational opportunity to talented young musicians entering Years 7 to 9, the Music Scholarship is open to students with a commitment and passion for music and learning an instrument.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.stmichaels.vic.edu.au/enrolments/scholarships/performing-arts-and-music-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/a0baf527c7aa7e06c4fd5f89e4ba81d7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00345G' AND sc.`scholarship_name` = 'Music Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = NULL, sc.`eligibility` = 'Through the generous endowment of a former St Michael’s Chaplain and Board member, the Gidleigh Scholarship provides an educational opportunity to a student in Year 10 who, for financial or other reasons, would not ordinarily be able to attend, or continue their studies, at St Michael’s.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/the-gidleigh-scholarship/3812d41ac33a869ce95caf2441d3e99b', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-gidleigh-scholarship/3812d41ac33a869ce95caf2441d3e99b', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00345G' AND sc.`scholarship_name` = 'The Gidleigh Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Academic Achievement and Leadership Scholarships are awarded on the basis of the student’s results from an independent academic examination, as well as their completed application, NAPLAN results, school reports and accompanying documentation. Students will also need to demonstrate broader involvement and engagement in co- and extra-curricular activities outside the classroom. Academic performance must be maintained throughout the holder’s journey through the School. Shortlisted candidates will attend an interview with the Principal or Vice Principal.', sc.`eligibility` = 'Academic Achievement and Leadership Scholarships are awarded on the basis of the student’s results from an independent academic examination, as well as their completed application, NAPLAN results, school reports and accompanying documentation. Students will also need to demonstrate broader involvement and engagement in co- and extra-curricular activities outside the classroom. Academic performance must be maintained throughout the holder’s journey through the School. Shortlisted candidates will attend an interview with the Principal or Vice Principal.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/academic-achievement-leadership-scholarship/25bcaf5aca25ece29d6fc6bf2be40ed6', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-achievement-leadership-scholarship/25bcaf5aca25ece29d6fc6bf2be40ed6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00348E' AND sc.`scholarship_name` = 'Academic Achievement & Leadership Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Future Voices Scholarships are awarded on the basis of the student’s application which will demonstrate a balance of academic potential and commitment, leadership qualities and involvement, commitment to a range of co-and extra-curricular activities, and willingness to contribute across multiple facets of school life. This may be in the areas of sport, community or public service, environmental responsibility, or other fields of significance. Both leadership and involvement, must be maintained throughout the holder’s journey through the School.\r\n\r\nAll Future Voices applicants are required to sit an independent academic examination and short-listed candidates will attend an interview with the Principal or Vice Principal.', sc.`eligibility` = 'Future Voices Scholarships are awarded on the basis of the student’s application which will demonstrate a balance of academic potential and commitment, leadership qualities and involvement, commitment to a range of co-and extra-curricular activities, and willingness to contribute across multiple facets of school life. This may be in the areas of sport, community or public service, environmental responsibility, or other fields of significance. Both leadership and involvement, must be maintained throughout the holder’s journey through the School.\r\n\r\nAll Future Voices applicants are required to sit an independent academic examination and short-listed candidates will attend an interview with the Principal or Vice Principal.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/future-voices-general-excellence-scholarship/06e40213f813792534c5893992407c57', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/future-voices-general-excellence-scholarship/06e40213f813792534c5893992407c57', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00348E' AND sc.`scholarship_name` = 'Future Voices (General Excellence) Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Music Scholarships are offered on the basis of the student’s music audition as well as the results from the independent academic examination. During the audition students must demonstrate outstanding musical ability. Students are required to play two contrasting pieces on their main instrument and arrange for their own accompanist to attend the audition.\r\n\r\nCommitment to tuition and involvement in ensembles and performance must be maintained throughout the holder’s journey through the school.\r\n\r\nYears 7 and 8 entry\r\n\r\nString and Woodwind instruments must be at Grade 4 AMEB standard or above\r\nBrass instruments must be at Grade 2 AMEB standard or above\r\nYear 9, 10 and 11 entry\r\n\r\nString and Woodwind instruments must be at Grade 5 AMEB standard or above\r\nBrass instruments must be at Grade 3 AMEB standard or above\r\nAuditions will take place at Tintern Grammar', sc.`eligibility` = 'Music Scholarships are offered on the basis of the student’s music audition as well as the results from the independent academic examination. During the audition students must demonstrate outstanding musical ability. Students are required to play two contrasting pieces on their main instrument and arrange for their own accompanist to attend the audition.\r\n\r\nCommitment to tuition and involvement in ensembles and performance must be maintained throughout the holder’s journey through the school.\r\n\r\nYears 7 and 8 entry\r\n\r\nString and Woodwind instruments must be at Grade 4 AMEB standard or above\r\nBrass instruments must be at Grade 2 AMEB standard or above\r\nYear 9, 10 and 11 entry\r\n\r\nString and Woodwind instruments must be at Grade 5 AMEB standard or above\r\nBrass instruments must be at Grade 3 AMEB standard or above\r\nAuditions will take place at Tintern Grammar', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/320469dbbaa8559b4624d803c3be9e4d', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/music-scholarship/320469dbbaa8559b4624d803c3be9e4d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00348E' AND sc.`scholarship_name` = 'Music Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Performing Arts Scholarships are offered on the basis of the student’s audition in either drama, dance or musical theatre or a combination of these areas as well as the results from the independent academic examination. Students are required to perform two contrasting pieces in their chosen area and arrange an accompanist to attend the audition if required.\r\n\r\nPerforming Arts Applicants will be assessed using a combination of the following selection criteria:\r\n\r\nAbility to demonstrate excellence in drama, dance or musical theatre performance, or a combination of these areas.\r\nPreparedness to fully engage in the life of the School and participate in a range of Performing Arts co-curricular activities.\r\nA commitment to the Performing Arts at Tintern Grammar through academic study in Drama and/or Theatre Studies through to Year 12.\r\nA willingness to uphold the School’s compass values.\r\nAudition Performance of two contrasting pieces that shows ability in the chosen area/s.\r\nPerforming Arts Scholarship auditions will take place at Tintern Grammar', sc.`eligibility` = 'Performing Arts Scholarships are offered on the basis of the student’s audition in either drama, dance or musical theatre or a combination of these areas as well as the results from the independent academic examination. Students are required to perform two contrasting pieces in their chosen area and arrange an accompanist to attend the audition if required.\r\n\r\nPerforming Arts Applicants will be assessed using a combination of the following selection criteria:\r\n\r\nAbility to demonstrate excellence in drama, dance or musical theatre performance, or a combination of these areas.\r\nPreparedness to fully engage in the life of the School and participate in a range of Performing Arts co-curricular activities.\r\nA commitment to the Performing Arts at Tintern Grammar through academic study in Drama and/or Theatre Studies through to Year 12.\r\nA willingness to uphold the School’s compass values.\r\nAudition Performance of two contrasting pieces that shows ability in the chosen area/s.\r\nPerforming Arts Scholarship auditions will take place at Tintern Grammar', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/performing-arts-scholarship/8b65b9eebea03f2b9de0edce3b5b4e14', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/performing-arts-scholarship/8b65b9eebea03f2b9de0edce3b5b4e14', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00348E' AND sc.`scholarship_name` = 'Performing Arts Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Social Justice Scholarships will be awarded on the basis of the student’s application which will demonstrate a balance of academic potential and commitment, leadership qualities and involvement, and a commitment to a range of co-and extra-curricular activities. In addition, a willingness to contribute across multiple facets of school life as well as a demonstration of how they have made a positive impact on their local or global communities and a commitment to continue this involvement in leadership, community and social justice activities must be maintained throughout the holder’s journey through the School.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with the Principal and any additional information as required during the application process.\r\n\r\nThis scholarship is aimed at those who would not normally have the financial means to attend Tintern Grammar. These scholarships are means tested and shortlisted candidates will be required to provide financial disclosure upon request.', sc.`eligibility` = 'The scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with the Principal and any additional information as required during the application process.\r\n\r\nThis scholarship is aimed at those who would not normally have the financial means to attend Tintern Grammar. These scholarships are means tested and shortlisted candidates will be required to provide financial disclosure upon request.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/social-justice-scholarship/63117d78170d96aa3cef0d1caa0a6c53', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/social-justice-scholarship/63117d78170d96aa3cef0d1caa0a6c53', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00348E' AND sc.`scholarship_name` = 'Social Justice Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is awarded to a female child of a past student of the School and is available for students entering Years 7 to 11 in 2024 and is intended for families who would not normally have the financial means to attend Tintern Grammar.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and any additional information as required during the application process. This scholarship is means tested, and shortlisted candidates will be required to provide financial disclosure upon request.', sc.`eligibility` = 'This scholarship is awarded to a female child of a past student of the School and is available for students entering Years 7 to 11 in 2024 and is intended for families who would not normally have the financial means to attend Tintern Grammar.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and any additional information as required during the application process. This scholarship is means tested, and shortlisted candidates will be required to provide financial disclosure upon request.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/the-dr-sylvia-walton-ao-alumni-scholarship/97455d37685897b2357310076d7f6fa6', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-dr-sylvia-walton-ao-alumni-scholarship/97455d37685897b2357310076d7f6fa6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00348E' AND sc.`scholarship_name` = 'The Dr Sylvia Walton AO Alumni Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Henry Speagle joined the Tintern Community some 60 years ago when he was appointed to the School Council by the Archbishop-In-Council. He remained a member of the School Council for nearly 40 years; in the final years of his term he was the Deputy Chairman. Among many contributions, his skill as an historian was put to good use in supporting the production of the School’s centenary history in 1977. Jean stood by Henry’s side on many occasions, supporting and enjoying many formal and celebratory events and activities, particularly those with a musical flavour. In 2001 Henry was inducted as a Life Governor of the School and in further recognition, in 1991, the Science block of classrooms was named in his honour, recognising his enormous contribution to the strength and development of Tintern Grammar. In 2019 the Speagle family was honoured when the building was refurbished and renamed as the Speagle Science Centre. Now in her 95th year, Jean continues to enjoy her connection to the Tintern Community and even though unable to attend in person, keeps up to date with the happenings around the school.The Henry and Jean Speagle Scholarship has been pledged to the school by Henry and Jean and their son. Following Henry’s death in 2020, the Speagle family made an initial gift to the Scholarship Fund. The family will continue to build the corpus for the Scholarship (including through a bequest) until a 50% Scholarship can be awarded in perpetuity to suitable recipients.Applicants must meet all or most of the criteria to be considered for the scholarship.The conditions are:A female student who does not currently attend Tintern GrammarFrom a family who for financial reasons could not otherwise afford the benefit of a Tintern educationA family (or student) who has an affiliation and is a practising member of a recognised Christian denomination, preferably Anglican.The scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and meeting the above criteria. This scholarship is aimed at those who would not normally have the financial means to attend Tintern Grammar and is means tested. Shortlisted candidates will be required to provide financial disclosure upon request.', sc.`eligibility` = 'Henry Speagle joined the Tintern Community some 60 years ago when he was appointed to the School Council by the Archbishop-In-Council. He remained a member of the School Council for nearly 40 years; in the final years of his term he was the Deputy Chairman. Among many contributions, his skill as an historian was put to good use in supporting the production of the School’s centenary history in 1977. Jean stood by Henry’s side on many occasions, supporting and enjoying many formal and celebratory events and activities, particularly those with a musical flavour. In 2001 Henry was inducted as a Life Governor of the School and in further recognition, in 1991, the Science block of classrooms was named in his honour, recognising his enormous contribution to the strength and development of Tintern Grammar. In 2019 the Speagle family was honoured when the building was refurbished and renamed as the Speagle Science Centre. Now in her 95th year, Jean continues to enjoy her connection to the Tintern Community and even though unable to attend in person, keeps up to date with the happenings around the school.The Henry and Jean Speagle Scholarship has been pledged to the school by Henry and Jean and their son. Following Henry’s death in 2020, the Speagle family made an initial gift to the Scholarship Fund. The family will continue to build the corpus for the Scholarship (including through a bequest) until a 50% Scholarship can be awarded in perpetuity to suitable recipients.Applicants must meet all or most of the criteria to be considered for the scholarship.The conditions are:A female student who does not currently attend Tintern GrammarFrom a family who for financial reasons could not otherwise afford the benefit of a Tintern educationA family (or student) who has an affiliation and is a practising member of a recognised Christian denomination, preferably Anglican.The scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and meeting the above criteria. This scholarship is aimed at those who would not normally have the financial means to attend Tintern Grammar and is means tested. Shortlisted candidates will be required to provide financial disclosure upon request.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/the-henry-and-jean-speagle-scholarship/468d45807006054650662cfbbb47df19', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-henry-and-jean-speagle-scholarship/468d45807006054650662cfbbb47df19', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00348E' AND sc.`scholarship_name` = 'The Henry and Jean Speagle Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is awarded to a male child of a past student of the School and is available for students entering into Years 7 to 11 in 2024 and is intended for families who would not normally have the financial means to attend Tintern Grammar.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and any additional information as required during the application process. This scholarship is means tested, and shortlisted candidates will be required to provide financial disclosure upon request.', sc.`eligibility` = 'This scholarship is awarded to a male child of a past student of the School and is available for students entering into Years 7 to 11 in 2024 and is intended for families who would not normally have the financial means to attend Tintern Grammar.\r\n\r\nThe scholarship will be awarded on the basis of the student’s application as well as the results from an independent academic examination, school reports and NAPLAN results, along with an interview with a senior member of staff and any additional information as required during the application process. This scholarship is means tested, and shortlisted candidates will be required to provide financial disclosure upon request.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/the-mike-blood-alumni-scholarship/ba9842a173503c74e4cfabdfe5739480', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-mike-blood-alumni-scholarship/ba9842a173503c74e4cfabdfe5739480', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00348E' AND sc.`scholarship_name` = 'The Mike Blood Alumni Scholarship' AND sc.`course_id` IS NULL;
