UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Academic Scholarships are awarded to students who demonstrate outstanding academic potential. The scholarships are open to students in Years 6 and 9 in 2023 and will be offered for Years 7 and 10 in 2024. Applicants will sit the ACER Scholarship Examination on Saturday 25 February 2023.', sc.`eligibility` = 'Academic Scholarships for students entering Year 7 and Year 10 in 2024 are now open. Testing will take place on Saturday 25 February 2023 using the Academic Scholarship Exam prepared by the Australian Council of Educational Research (ACER). See our website for information on how to register. https://www.concordia.qld.edu.au/enrolment/scholarships', sc.`scholarship_amount` = 'The awarding of a scholarship of financial subsidy of each scholarship is determined by the Head of College and the Scholarship Testing Committee. The amount is based on merit and achievement in testing.', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/7a2db5ecc5972d90adee7355677eccdc', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/7a2db5ecc5972d90adee7355677eccdc', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00581G' AND sc.`scholarship_name` = 'Academic Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A 10% reduction on registered tuition fees will be awarded to University of Tasmania international students who meet the eligibility requirements as outlined in the below bursary or scholarship theme areas.', sc.`eligibility` = 'Please contact University of Tasmania for further information.', sc.`scholarship_amount` = '10% reduction in registered tuition fees for the duration of the course.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/10-tuition-fee-discounts', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/10-tuition-fee-discounts/6e92e903e350edd34bb9ee7f74a8842c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00586B' AND sc.`scholarship_name` = '10% Tuition fee discounts' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Awarded competitively to students of exceptional research potential to assist with living costs while undertaking a Higher Degree by Research. Living Allowance', sc.`eligibility` = 'To be eligible for an RTP Stipend a candidate must not be receiving income from another source related to their Higher Degree by Research, to support the candidates general living costs while undertaking their research degree, if that income is greater than 75% of the candidates RTP Stipend rate. Income unrelated to the candidates research degree or income received for the candidates research degree, but not for the purpose of supporting general living costs, will not be taken into account; To be eligible for an RTP Fees Offset a candidate must not be receiving an equivalent award or scholarship from the Commonwealth Government designed to offset tuition fees for their Higher Degree by Research.; In 2025 all domestic applicants will be offered an RTP Fees Offset provided they are not receiving an equivalent award or scholarship from the Commonwealth designed to offset Higher Degree by Research tuition fees.; The scholarship holder is expected to diligently pursue the degree for which they are enrolled. Continued \r\npayment of the scholarship is therefore subject to the scholarship holder making satisfactory academic progress and terminates on the expiry of the scholarship or on submission of the thesis for examination, whichever is the sooner', sc.`scholarship_amount` = 'Up to AUD $33511 — PhD: 3.5 years FTE. It is important to be aware that the duration of the scholarship is less than the maximum length of candidature, which is 4 years.; Masters: 2 years FTE.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.utas.edu.au/research/degrees/scholarships-and-fees', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australian-government-research-training-program-rtp-scholarships/193de31bd851abd2188f7d6fb3495270', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00586B' AND sc.`scholarship_name` = 'Australian Government Research Training Program (RTP) Scholarships' AND sc.`course_id` IS NULL;
