UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = NULL, sc.`eligibility` = 'The Gonzaga Barry Scholarship is offered to new students wishing to enter Loreto College. A maximum of two scholarships will be awarded annually. To be eligible the student must be a daughter, granddaughter, or niece of an Old Scholar from Loreto College Marryatville. The scholarship is means-tested and is directed towards students who would not be able to attend Loreto College due to financial hardship. Students must also meet the all-rounder scholarship criteria. The all-rounder scholarship is based on presentation of a portfolio. The student will not only provide evidence of a growth mindset with regard to academic success but also demonstrate how they encapsulate the values of a Loreto education through their contribution to their schoo', sc.`scholarship_amount` = 'Gonzaga Barry ibvm was the foundress of Loreto Education in Australia. Her passion for girls’ education had a significant influence on the development of education across Australia. In order to celebrate Gonzaga Barry’s vision for the education of gi', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/gonzaga-barry-scholarship-full-bursary-for-years-7-11/d83fda061999ee38f9f6b31521c397e2', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/gonzaga-barry-scholarship-full-bursary-for-years-7-11/d83fda061999ee38f9f6b31521c397e2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00629G' AND sc.`scholarship_name` = 'Gonzaga Barry Scholarship (full bursary) for Years 7-11' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = NULL, sc.`eligibility` = 'The Music Scholarship is offered to new and continuing students from Years 5-11. The applicant will provide a portfolio with copies of recent school reports and any other documentation that is relevant in promoting the music scholarship application. Students should be able to demonstrate a minimum performance standard of Grade 2 AMEB (or equivalent) on their first instrument or voice. Scholarship are awarded primarily on the basis of an audition. Scholarship holders agree to contribute actively and generously to the co-curricular program and performance activities of the College. Scholarship holders who are involved in other performance groups outside school are expected to give priority to scheduled school co-curricular events if there is', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-years-5-11/9329b7929a94e877566f953789e8d4b7', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/music-scholarship-years-5-11/9329b7929a94e877566f953789e8d4b7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00629G' AND sc.`scholarship_name` = 'Music Scholarship (Years 5-11)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'We are pleased to announce that the 2025 International Scholarship is now available to AIM students commencing study in 2025.\r\n\r\nTo qualify for a scholarship, you must first complete your AIM enrolment application to study at AIM.', sc.`eligibility` = 'To qualify for a scholarship, you must first complete your AIM enrolment application to study at AIM.', sc.`scholarship_amount` = 'This scholarship is valued at up to 10% of tuition for the full duration of the course. Students must pass all classes/units to maintain the scholarship.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://aim.edu.au/how-to-apply/international/international-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2025-international-scholarship/ba79a682db37a3f88db870169731df4d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00665C' AND sc.`scholarship_name` = '2025 International Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = NULL, sc.`eligibility` = 'The Champagnat Trust has been established to provide assistance to student’s in necessitous circumstances selected on the basis of financial need. The Trust takes its name from the founder of the Marist Brothers, St. Marcellin Champagnat. These bursaries offer half or part thereof of tuition, boarding (where applicable) and compulsory fees for students entering Years 7 to 12. Families applying for fee relief in the form of a bursary are asked to completing a confidential Champagnat Trust Application Form and provide supporting documentation.', sc.`scholarship_amount` = 'Please visit our website for more information - https://www.marash.qld.edu.au/bursaries', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/champagnat-trust/fcb6f70d895cd7466262aec3bb91933e', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/champagnat-trust/fcb6f70d895cd7466262aec3bb91933e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00670F' AND sc.`scholarship_name` = 'Champagnat Trust' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The fund supports international students who have been involved in Christian ministry in the Australian context and who are seeking further theological education to equip them for ministry and leadership.   Under God, it is our prayer that this fund will enable many men and women to be trained to be sent into the world to proclaim the gospel.', sc.`eligibility` = 'Please Contact Moore Theological College for more information about Eligibility', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://moore.edu.au/bursaries-and-scholarships/global-ministry-bursary/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/global-ministry-bursary/4768777b14a9ebd9fcd8112bde52c0c5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00682B' AND sc.`scholarship_name` = 'Global Ministry Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Student Bursary offers postgraduate and undergraduate bursaries for the growing number of church leaders seeking training at Moore in order to return to their home countries. Increasingly, Moore College is equipping and sending graduates to varied ministries around the world, including overseas and Australian students who commit to global ministries. The majority of international students who join us at Moore return to varied ministries in Asia, Africa, Europe and North America, primarily as preachers or missionaries.', sc.`eligibility` = 'Please Contact Moore Theological College', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://moore.edu.au/bursaries-and-scholarships/international-student-award/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-student-bursary/3f1e8e88d103c35ed937fd9c6ce34e67', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00682B' AND sc.`scholarship_name` = 'International Student Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Overseas DBT Bursary program offers an external program in the international student’s home country typically to equip them for an existing ministry. The scholarship provides up to 75% of the fees payable for each successful recipient for the 8 subjects within the Diploma of Biblical Theology. Recipients must be overseas students not resident in Australia, engaging in ministry in their home country, or preparing for a specific ministry role.', sc.`eligibility` = 'Please Contact Moore Theological College for more information about Eligibility', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://moore.edu.au/bursaries-and-scholarships/overseas-dbt-bursary/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/overseas-dbt-bursary/723a69fc81f6bf7d20ce97c1c987aba3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00682B' AND sc.`scholarship_name` = 'Overseas DBT Bursary' AND sc.`course_id` IS NULL;
