UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The China Scholarship Council Research Scholarship is a collaborative arrangement that provides support to candidates from the People\'s Republic of China to undertake a PhD at Western Sydney University. We encourage applications from candidates in all areas of study across our Schools and Institutes.', sc.`eligibility` = 'be a citizen and permanent resident of the People\'s Republic of China at the time of your application; satisfy the Australian Government requirements for a student visa(opens in new window)Opens in a new window for postgraduate research; have applied for admission and meet all admission entry requirements, including English proficiency; have received a conditional or unconditional offer for admission into a PhD program at Western Sydney University; have received a conditional offer for scholarship from Western Sydney University and; satisfy all other eligibility criteria as defined by the China Scholarship Council.', sc.`scholarship_amount` = '"Western Sydney University will provide a tuition fee waiver for successful applicants for a maximum period of up to 48 months.\r\n"', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.westernsydney.edu.au/schools/grs/scholarships/china_scholarship_council_research_scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/china-scholarship-council-research-scholarships/a1cec40e9d58deaf18c10f5bc8c5b27d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00917K' AND sc.`scholarship_name` = 'China Scholarship Council Research Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Western Sydney University supports higher degree research candidates with a range of scholarship opportunities. Research scholarships are released periodically, and each type of scholarship has specific application dates, eligibility criteria and conditions.\n\nThe information below outlines the requirements for our PhD Research Scholarships for Western Sydney University graduates of Masters of Research and Honours programs.', sc.`eligibility` = 'Doctor of Philosophy (PhD); Professional Doctorate (DCA, DCR or EdD)', sc.`scholarship_amount` = 'Up to AUD $105564', sc.`level_of_studies` = 'Undergraduate / VET, Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.westernsydney.edu.au/schools/grs/scholarships/main_round_scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/research-scholarships/60316806b548599f4f59bbfee791e144', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00917K' AND sc.`scholarship_name` = 'Research Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship provides financial support, in the form of a fee subsidy, to students undertaking HDR research at AC. This is a merit-based scholarship for students with a demonstrated record of academic excellence.', sc.`eligibility` = 'To be eligible for the Alphacrucis Higher Degree Scholarship, applicants must: be accepted for entry to (or recently enrolled in) an HDR degree at AC; have a record of academic excellence and a demonstrated research potential; recipients must maintain satisfactory progress as a research candidate at AC.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ac.edu.au/research/higher-degree-research/funding-opportunities/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/alphacrucis-higher-degree-scholarship/8d3513b5dc559c1b3fd5fa00222ca836', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '00958A' AND sc.`scholarship_name` = 'Alphacrucis Higher Degree Scholarship' AND sc.`course_id` IS NULL;
