UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University of Notre Dame Australia (University) offers the International Business and Commerce scholarship to provide tuition assistance to international students enrolling in Undergraduate Business and Commerce programs at the University of Notre Dame Australia.', sc.`eligibility` = 'Be international full fee-paying students commencing an undergraduate coursework program, in Business or Commerce for the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission requirements to study in any CRICOS registered undergraduate Business or Commerce degree where the program is delivered on the University’s Sydney or Fremantle (Perth) Campuses and; Be eligible to apply for a Higher Education Sector Visa (Subclass 500)', sc.`scholarship_amount` = 'The value of the Scholarship is $10,000 fee reduction of annual indicative tuition fees for the full duration of the program.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.notredame.edu.au/__data/assets/pdf_file/0032/339944/NDA-International-Business-and-Commerce-Undergraduate-Scholarship-T-and-Cs.pdf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/notre-dame-australia-international-business-and-commerce-scholarship/448e681128dec7e965ded68204b9ed21', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01032F' AND sc.`scholarship_name` = 'Notre Dame Australia International Business and Commerce Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University of Notre Dame Australia (University) offers the International Scholarship Master of Social Work \r\n(Qualifying) to provide tuition assistance to international students enrolling in the Master of Social Work \r\n(Qualifying).', sc.`eligibility` = 'To be eligible for the Scholarship, students must:; Be international full fee-paying students commencing a Master of Social Work (Qualifying) program \r\nfor the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission \r\nrequirements to study the CRICOS registered Master of Social Work (Qualifying) delivered on the \r\nUniversity\'s Sydney or Fremantle (Perth) Campuses; Be eligible to apply for a Higher Education Sector Visa (Subclass 500).', sc.`scholarship_amount` = 'The value of the Scholarship is 20 percent (20%) of annual indicative tuition fees for the full duration of the \r\nprogram. The Scholarship is awarded as a partial tuition fee waiver and does not cover costs such as living \r\nexpenses, accommodation, t', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.notredame.edu.au/__data/assets/pdf_file/0039/746976/TCs-Mof-Social-Work-Conditions-2026-updated.pdf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/notre-dame-australia-international-scholarship-master-of-social-work-qualifying/c0c4e5055084cc3e5e30276bcdab71cf', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01032F' AND sc.`scholarship_name` = 'Notre Dame Australia International Scholarship Master of Social Work (Qualifying).' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University of Notre Dame Australia (University) offers the International Welcome Scholarship to provide tuition assistance to international students enrolling in Undergraduate programs at Notre Dame, excluding the Bachelor of Nursing.', sc.`eligibility` = 'Be international full fee-paying students commencing an undergraduate coursework program, excluding the Bachelor of Nursing for the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission requirements to study in any CRICOS registered undergraduate degree where the program is delivered on the University’s Sydney or Fremantle (Perth) Campuses and; Be eligible to apply for a Higher Education Sector Visa (Subclass 500).', sc.`scholarship_amount` = 'The value of the Scholarship is 25 percent (25%) of annual indicative tuition fees for the full duration of the program.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.notredame.edu.au/__data/assets/pdf_file/0029/258941/NDA-International-Welcome-Scholarship-Undergraduate-2022-T-and-Cs.pdf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/notre-dame-australia-international-welcome-scholarship-undergraduate/9a1bb6cd1e3448c938269c7ed793de21', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01032F' AND sc.`scholarship_name` = 'Notre Dame Australia International Welcome Scholarship (Undergraduate)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University of Notre Dame Australia (University) offers the International Welcome Scholarship for Nursing\r\nto provide tuition assistance to international students enrolling in the Bachelor of Nursing program at Notre \r\nDame.', sc.`eligibility` = 'Be international full fee-paying students commencing the Bachelor of Nursing program for the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission requirements to study the Bachelor of Nursing CRICOS registered degree delivered on the Universitys Sydney or Fremantle (Perth) Campuses and; Be eligible to apply for a Higher Education Sector Visa (Subclass 500)', sc.`scholarship_amount` = 'The value of the Scholarship is 20 percent (20%) of annual indicative tuition fees for the full duration of the \r\nprogram.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.notredame.edu.au/__data/assets/pdf_file/0032/258944/NDA-International-Welcome-Scholarship-Nursing-2022-T-and-Cs.pdf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/notre-dame-australia-international-welcome-scholarship-for-nursing/9ab1303d015574e08e45b25b6efcb8f2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01032F' AND sc.`scholarship_name` = 'Notre Dame Australia International Welcome Scholarship for Nursing' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University of Notre Dame Australia (University) offers the International Welcome Scholarship to provide tuition assistance to international students enrolling in Postgraduate coursework programs at Notre Dame, with the exception of the Doctor of Medicine, Master of Physiotherapy, and all Graduate Certificates.', sc.`eligibility` = 'Be international full fee-paying students commencing an postgraduate coursework program for the first time at The University of Notre Dame Australia; Have accepted an Offer of Admission (by the relevant deadline) and satisfied any admission requirements to study in any CRICOS registered postgraduate degree where the program is delivered on the Universitys Sydney or Fremantle (Perth) Campuses, excluding the Doctor of Medicine and all Graduate Certificates; Be eligible to apply for a Higher Education Sector Visa (Subclass 500).', sc.`scholarship_amount` = 'The value of the Scholarship is 20 percent (20%) of annual indicative tuition fees for the full duration of the program.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.notredame.edu.au/__data/assets/pdf_file/0021/437700/Postgraduate-Coursework-conditions.pdf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/notre-dame-international-welcome-scholarship-postgraduate/da90cfeab521aa972c245690e1821aeb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01032F' AND sc.`scholarship_name` = 'Notre Dame International Welcome Scholarship (Postgraduate)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The purpose of the Scholarship is to assist students holding one of the classes of visa listed in Appendix 1 to commence or continue their studies at the University of Notre Dame Australia, Fremantle and Sydney Campuses.', sc.`eligibility` = 'Be from a refugee or asylum seeker background as evidenced by the applicant holding one of the classes of visa listed in Appendix 1 which permits the recipient to undertake tertiary studies in Australia and; Have been offered a place or be enrolled as a student in an undergraduate bachelor\'s program or in the Tertiary Pathway Program at the University of Notre Dame Australia, Fremantle or Sydney Campus.', sc.`scholarship_amount` = 'Full fee remission.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.notredame.edu.au/__data/assets/pdf_file/0021/266070/VCs-Humanitarian-Scholarship-Conditions.pdf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-humanitarian-scholarship/4eb86ff3527e69acfe0c4f93c4106691', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01032F' AND sc.`scholarship_name` = 'Vice Chancellors Humanitarian Scholarship' AND sc.`course_id` IS NULL;
