UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Kangan Institute Access Scholarship has been designed to provide opportunities for access to education. The scholarship is available to domestic and international students enrolled in any course at Kangan Institute. It is intended to alleviate financial pressures associated with engagement and the successful completion of the course.', sc.`eligibility` = 'Students must be enrolled in any course at Kangan Institute.; To be eligible for the Kangan Institute Access Scholarship, applicants must meet the following criteria and provide supporting documents; Must hold a valid visa (student visa, temporary graduate visa, spouse visa or anyone paying International Fee); Must be an onshore student;  Provide evidence of financial or personal disadvantage. Disadvantage(s) may include; a.   financial difficulty (payslips, bank statements or statutory declaration); b.   experienced delay or interruption to studies due to compassionate reason(s), which may include but death in the immediate family, family violence, homelessness, or at authorised officers’ discretion Evidence – death certificate, eviction notice, personal statement or statutory declaration; Currently enrolled and studying at Kangan Institute and have current outstanding fees.', sc.`scholarship_amount` = 'Up to AUD $1000 — Domestic Students: up to $500 per scholarship\r\nInternational Students: up to $1,000 per scholarship', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.kangan.edu.au/study-with-us/prospective-students/scholarships/access-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/access-scholarship-enrolled-students-only/3bc23eec83ffa60201a7611812d4c695', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01218G' AND sc.`scholarship_name` = 'Access Scholarship (Enrolled Students Only)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Please contact Southern Cross University for further information.', sc.`eligibility` = 'Please contact Southern Cross University for further information.', sc.`scholarship_amount` = 'Up to AUD $26000 — The $26,000 tuition fees will apply to all new and continuing international students in Australia, in all courses with the exception of the Master of Nursing, Bachelor of Veterinary Technology and Bachelor of Veterinary Medicine pl', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scu.edu.au/study/international-study/access26/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/access26/a747c733167765a70b78b781f037f0de', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01241G' AND sc.`scholarship_name` = 'Access26' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship will support a current student to continue to achieve outstandingly in her studies. The scholarship will form part of the celebrations of International Women’s Day.\r\n\r\nInternational Women’s Day celebrates and acknowledges the achievements of women globally on 8 March each year.', sc.`eligibility` = 'This scholarship will support a current student to continue to achieve outstandingly in her studies. The scholarship will form part of the celebrations of International Women’s Day. International Women’s Day celebrates and acknowledges the achievements of women globally on 8 March each year.', sc.`scholarship_amount` = 'Up to AUD $5000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scu.edu.au/scholarships/international-womens-day-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-womens-day-scholarship/7da620117e0069ad51f55ed9f7cc84ae', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01241G' AND sc.`scholarship_name` = 'International Women\'s Day Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Preparing for Success Pathway Scholarship which will assist students transition into their chosen degree. The scholarship supports students through an initial preparatory program (Preparing for Success Program) where the student gains skills required for successful degree studies. Upon successful completion of Preparing for Success Program students will be able to progress onto a bachelor program. A bonus payment will be made upon commencement of study in the student\'s chosen Bachelor degree.', sc.`eligibility` = 'Recipients must be:; Commencing Preparing for Success pathway program in 2027; Be offered the Preparing for Success program as an Early Offer; Complete Preparing for Success in 2027; Progress immediately into the first available offering of the packaged Bachelor degree upon completion of the Preparing for Success program', sc.`scholarship_amount` = 'Up to AUD $2500', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scu.edu.au/scholarships/preparing-for-success-pathway-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/preparing-for-success-pathway-scholarship/ac8d27d103c06eb6a4a258109f594595', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01241G' AND sc.`scholarship_name` = 'Preparing for Success Pathway Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Ralph Barclay Braun Memorial Scholarship is awarded to students who have a formal acceptance into the Bachelor of Science with Honours. Students must be based, full-time, at the National Marine Science Centre (NMSC) — and have a supervisor who is based, full-time, at the NMSC. This scholarship will support a student who will be engaged in important research in areas such as Biodiversity, Ecological Interactions, Aquaculture and Sustainable Fisheries. Successful recipients demonstrate outstanding academic achievement in their undergraduate study and are committed to a research career.', sc.`eligibility` = 'Enrolled full-time and on-campus at the Southern Cross University’s National Marine Science Centre in the Bachelor of Science with Honours program. Applications should provide a copy of their undergraduate record and must have attained a GPA higher than 5.5 for the last year (or last 8 units if part-time study was undertaken) of their undergraduate degree. Provision of a 100-word statement outlining a passion for marine science research and a commitment to developing a research career path. A one-page (A4) research proposal.', sc.`scholarship_amount` = 'Up to AUD $5000 — $5000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scu.edu.au/scholarships/ralph-barclay-braun-memorial-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ralph-barclay-braun-memorial-scholarship/8e462b80a07aff5743f74e9284a689a9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01241G' AND sc.`scholarship_name` = 'Ralph Barclay Braun Memorial Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The University’s Rugby Club, known as the Gold Rats, marked its 50th season in 2019. The club offers scholarships to students studying in a degree at the Lismore campus.', sc.`eligibility` = 'Applicants applying for this scholarship must:; Be admitted and enrolled either full-time or part-time in an undergraduate or postgraduate degree at Southern Cross University, Lismore campus; Be a current or new player in the Far North Coast first grade rugby competition, or Women’s competition, for the SCU Rugby Club in the year the scholarship is offered. Scholarship holders must have experience as a representative or first grade, or Women’s rugby player.', sc.`scholarship_amount` = 'Up to AUD $3000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scu.edu.au/scholarships/southern-cross-university-rugby-gold-rats-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/scu-rugby-gold-rats-scholarship/3778705ef1d8bc94f7601315c6a517da', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01241G' AND sc.`scholarship_name` = 'SCU Rugby Gold Rats Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Southern Cross University is committed to helping provide exceptional students with exceptional opportunities to broaden their professional networks and opportunities. The Southern Cross Student Opportunities Fund will provide students with the opportunity to apply for a scholarship worth up to $7,500 each to help subsidise the cost of travel, accommodation and necessary activities to help them realise their full professional potential.', sc.`eligibility` = 'Please note that this scholarship is only available to students who have progressed their opportunity to such a point that its occurrence is almost certain. As such, students may have to purchase tickets or accommodation in advance of being awarded this scholarship, in which case, the scholarship panel will consider the costs already incurred and include that in their deliberations as to the amount granted if successful. The strength of each application will be measured against the above selection criteria. A report will make recommendations to the selection panel, which will be represented by the Office of Engagement, Office of Research, Finance, Governance and other work units where specialist insights may be required.', sc.`scholarship_amount` = 'Up to AUD $7500', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.scu.edu.au/current-students/opportunities/student-opportunities-fund/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/student-opportunities-fund/47f113bf4fa5ad1d041d32139240811d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01241G' AND sc.`scholarship_name` = 'Student Opportunities Fund' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship celebrates the diversity of nations with international students attending Southern Cross University.', sc.`eligibility` = 'Apply to study an undergraduate or postgraduate coursework degree commencing in 2024 or 2025 (Excludes quota-restricted programs, e.g. Graduate Diploma of Early Childhood and Master of Nursing) at the Gold Coast, Lismore, or Coffs Harbour campus, or online for international students on a non-student visa.  Please note, this scholarship is only applicable to students paying international fees and does not include programs offered online through SCU Ventures, The Hotel School or Keypath Education. Meet the admission entry requirements of the program you have applied for. Assessment of eligibility for this scholarship will be undertaken by the Southern Cross admissions team on application to Southern Cross University. To maintain scholarship eligibility, students must pass all the requirements for all enrolled units in each Term. Students must be meeting the requirements of the program. Students must meet the attendance requirements of their program and visa conditions to remain eligible for the scholarship. Specific countries only are eligible, contact your Regional Manager for more details. Students who are Australian citizens, Australian permanent residents, or New Zealand citizens are not eligible to apply.', sc.`scholarship_amount` = '$8,000 maximum fee reduction per year for the duration of your program', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'http://www.scu.edu.au/scholarships/international-student-scholarships/vice-chancellors-international-diversification-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/vice-chancellors-international-diversification-scholarship/cca133370db7c2fbd1fb7ea23531c00d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01241G' AND sc.`scholarship_name` = 'Vice Chancellor\'s International Diversification Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Masters Scholarship 2025 and 2026 is offered to international students from selected countries who are applying for select Master degrees at ECU. The scholarship offers a 20 percent reduction in your tuition fees for the offered duration of your Master course at ECU. The scholarships are open to future international students seeking to enroll at Edith Cowan University in Semester Two, 2025; or Semester One and Two, 2026.', sc.`eligibility` = 'Be a citizen of one of the countries identified above; \r\nBe an international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen); \r\nStudy onshore at ECU Joondalup, ECU Mount Lawley, ECU City Campus or ECU South West (Bunbury) Campus; \r\nMeet ECU’s entry requirements for the course and commence study onshore, in an eligible postgraduate degree listed as below at ECU, Western Australia in Semester Two 2025; or Semester One and Two, 2026. \r\nBe commencing your ECU packaged pathway course with an ECU registered pathway partner leading to an eligible postgraduate degree listed as below in 2025 and 2026.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/2025-international-masters-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2025-and-2026-international-masters-scholarship/f04c5121e639907836592e59c1cc646d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01312J' AND sc.`scholarship_name` = '2025 and 2026 International Masters Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Undergraduate Scholarship 2025 and 2026 is offered to international students from selected countries who are applying for a Bachelor degree at ECU. The scholarship offers a 20 percent reduction in your tuition fees for the offered duration of your course at ECU. The scholarships are open to future international students seeking to enroll at Edith Cowan University in a Bachelor degree in Semester Two, 2025 ; or Semester One and Two, 2026.', sc.`eligibility` = 'be a citizen of one of the countries identified above;\r\nbe an international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen);\r\nstudy onshore at ECU Joondalup, ECU Mount Lawley, ECU City Campus or ECU South West (Bunbury) Campus;\r\nmeet ECU’s entry requirements for the course and commence study onshore at ECU, Western Australia in Semester Two 2025; or Semester One and Two, 2026\r\nbe commencing your ECU packaged pathway course with an ECU registered pathway partner leading to an eligible CRICOS registered undergraduate degree in 2025 and 2026.\r\nstudy in an eligible CRICOS registered undergraduate degree (excluding Bachelor of Arts (Acting) (Y93), Bachelor of Arts (Arts and Cultural Management) (T74), Bachelor of Arts (Dance) (T73), Bachelor of Arts (Music Theatre) (G44), Bachelor of Arts Honours (C34), Bachelor of Counter Terrorism Security and Intelligence (Y14), Bachelor of Education (Early Childhood Studies) (Y42), Bachelor of Education (Primary) (Y41), Bachelor of Education (Secondary) (Y68), Bachelor of Music (W76), Bachelor of Music Honours (K35), Bachelor of Performing Arts (Y97), Bachelor of Performing Arts Honours (W92), Bachelor of Preclinical Foundations of Imaging Science (T78), Bachelor of Science (Cybercrime, Security and Intelligence) (W87), Bachelor of Science (Nursing) (C33), Bachelor of Science (Nursing)/Bachelor of Science (Midwifery) (Y76), Bachelor of Science (Paramedical) (K89)).', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/international-undergraduate-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2025-and-2026-international-undergraduate-scholarship/ae1b4c01a8730e0e9b4d494955748a62', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01312J' AND sc.`scholarship_name` = '2025 and 2026 International Undergraduate Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A $5,000 bursary available to new international students commencing an undergraduate or master\'s by coursework program at ECU City Campus in Semester One or Two, 2026. Eligible students must maintain full-time enrolment (60 credit points per semester), and meet all terms and conditions. The bursary is paid in two instalments of $2,500 after the census date of each of the first two semesters.', sc.`eligibility` = 'Be an international student (not an Australian Citizen, Australian Permanent Resident, or New Zealand Citizen); \r\nBe studying an undergraduate or masters by coursework program on-campus for the first time, at ECU City Campus in Semester One, 2026, or Semester Two, 2026 (excluding Bachelor of Science (Nursing) C33 and Master of Nursing (Graduate Entry) J46); \r\nEot be in receipt of a government scholarship or industry sponsorship for your studies; and \r\nEnrolled to study in 60 credit points each Semester or study period in 2026 and remain enrolled in 60 credit points post census date of the commencing semester.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.ecu.edu.au/scholarships/details/2026-ecu-city-campus-welcome-bursary', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/2026-ecu-city-campus-welcome-bursary/e009206c4d6daeea29576bd3198b87e9', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01312J' AND sc.`scholarship_name` = '2026 ECU City Campus Welcome Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Australian College of Applied Professions (ACAP) and the Law Institute of Victoria (LIV) are committed to creating opportunities for First Nations Victorian law graduates through industry-led learning and genuine connections to the profession.', sc.`eligibility` = 'Completed a bachelors degree or higher in Law leading to admission to the legal profession, or No more than two academic subjects to complete in a bachelors degree, or higher in Law, of which neither are Priestley 11 subjects (1) AND Are completing these units while undertaking the PLT course; AND Has received the prior permission of the Admitting Authority (VLAB) to commence the PLT course.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.acap.edu.au/pages/fees-payments/scholarships/fns/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/gdlp-first-nations-scholarship/eb5473d935cded51756a6c6eb34baec5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01328A' AND sc.`scholarship_name` = 'GDLP First Nations Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Available for ACAP’s Graduate Certificate of Applied Coaching Alumni who want to take the next step with our Master of Business Administration (MBA) program. Our MBA is delivered on campus in Perth and offers eligible graduates up to four units of credit, allowing you to fast track your studies and complete fewer units to graduate. ACAP is also offering coaching graduates 15% off the course fee for their MBA program.', sc.`eligibility` = 'Completed ACAP\'s Graduate Certificate of Applied Coaching program.', sc.`scholarship_amount` = 'ACAP coaching graduates can be eligible for up to 15% off the course fee for their MBA program.', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.acap.edu.au/pages/fees-payments/scholarships/mba-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/mba-scholarship-for-acap-coaching-graduates/dbbe15c42b875158ba3e3d21296bed41', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01328A' AND sc.`scholarship_name` = 'MBA Scholarship for ACAP Coaching Graduates' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Memorial Fund Scholarship (VIC / NSW) was established to commemorate the lives of two William Angliss Institute students from Indonesia, who tragically lost their lives in the 2009 Victorian Bushfires. The Memorial Fund is awarded to international students (continuing) in any study area, based on merit or equity.', sc.`eligibility` = 'To be considered for this scholarship, you must:\r\n• Be an international student and hold a valid student visa; and\r\n• Have completed one full semester of full-time studies at William Angliss Institute in the previous semester; and\r\n• Be enrolled and continuing as a full time student in any VET or Faculty of Higher Education courses in any study area at William Angliss Institute (Melbourne or Sydney campus).\r\n• Fall into one of two categories;\r\n- Merit basis\r\n   - Demonstrate academic excellence via results achieved during previous and current studies\r\n- Equity basis\r\n   - Demonstrate financial and/or educational disadvantage. Include evidence that you;\r\n   - Experiencing short-term financial difficulties; or\r\n   - Have a disability, long-term medical illness or mental health condition or\r\n   - Experience difficult circumstances', sc.`scholarship_amount` = 'AUD $3000/year — Scholarships of up to $3,000 (AUD) each will be available to students in Semesters 1 and 2. This is awarded to support the students\' skill development, travel, living and other study related tools, resources or/and equipment expenses', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/the-memorial-fund-scholarship-vicnsw/76859c8983733901273fc1d7b32187f4', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-memorial-fund-scholarship-vicnsw/76859c8983733901273fc1d7b32187f4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01505M' AND sc.`scholarship_name` = 'The Memorial Fund Scholarship (VIC/NSW)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Merit Scholarship is awarded to international students (continuing) in any study area, based on merit.', sc.`eligibility` = 'To be considered for this scholarship, you must:\r\n• Be an international student and hold a valid student visa; and\r\n• Have completed one full semester of full-time studies at William Angliss Institute in the previous semester; and\r\n• Be enrolled and continuing as a full time student in any VET or Faculty of Higher Education courses in any study area at William Angliss Institute (Melbourne or Sydney campus).\r\n• Demonstrate academic excellence via results achieved during previous and current studies.', sc.`scholarship_amount` = 'Up to AUD $3000 — Scholarships of up to $3,000 (AUD) each will be available to students in Semesters 1 and 2. This is awarded to support the students\' skill development, travel, living and other study related tools, resources or/and equipment expense', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = 'Tourism and hospitality', sc.`website` = 'https://www.angliss.edu.au/study-with-us/scholarships/the-sir-william-angliss-international-merit-scholarships-vicnsw/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/the-sir-william-angliss-international-merit-scholarships-vicnsw/a802b9d7e506fe99f2a7b0dc2349bd67', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01505M' AND sc.`scholarship_name` = 'The Sir William Angliss International Merit Scholarships (VIC/NSW)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Graduate Progression Scholarship is available to international students who have completed a Bachelor\'s or Master\'s degree at MIT and are commencing a Higher Degree by Research at MIT in 2025. Eligible students will receive a 10% tuition fee reduction each trimester for the duration of their program.', sc.`eligibility` = 'Have completed a Bachelor\'s or Master\'s degree at Mit; Be enrolling in a Higher Degree by Research at MIT in 2025', sc.`scholarship_amount` = '10% tuition fee reduction per trimester, including the thesis component.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.mit.edu.au/study-with-us/scholarships/graduate-progression-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/mit-graduate-progression-scholarship/7baa4cbbb672efe3f10479b79f5055d7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01545C' AND sc.`scholarship_name` = 'MIT Graduate Progression Scholarship' AND sc.`course_id` IS NULL;
