UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Deakin College is committed to helping you achieve your goals by offering tuition fee scholarships to selected international students.', sc.`eligibility` = 'Be a citizen of Brunei, Cambodia, China, Hong Kong, Indonesia, Japan, Korea, Laos, Macau, Malaysia, Mongolia, Myanmar, Philippines, Singapore, Taiwan, Thailand, Timor-Leste or Vietnam, residing outside of Australia; or be a citizen of any country, residing onshore in Australia; Enrol as an international student; Commence a Foundation or Diploma program in 2025 or Trimester 1 2026.', sc.`scholarship_amount` = 'The scholarship is valued between 10%-20% of your Foundation and/or diploma program tuition fees', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.deakincollege.edu.au/how-apply/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/deakin-college-international-scholarships/28794144fc4caa9ef1ae081a5b39189a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01590J' AND sc.`scholarship_name` = 'Deakin College International Scholarships' AND sc.`course_id` IS NULL;
