UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = '-', sc.`eligibility` = 'Family Bursary applies where two or more students from the same family study at a Navitas institution.; The first family member can be studying at a Navitas institution at the same time as the other family members or may have studied at any Navitas institution previously.; The family bursary is granted to the second and subsequent family members who study at a Navitas institution.; This scholarship cannot be awarded in conjunction with any other Navitas scholarships; Recipients must not have previously received a Navitas scholarship or bursary, or had a scholarship or bursary from Navitas withdrawn.', sc.`scholarship_amount` = 'The bursary is equivalent to 10% of the tuition fee for up to 8 units of study within one program only with a Navitas member institution. The bursary does not apply to additional units or repeat units that may also be undertaken. It excludes mixed En', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.deakincollege.edu.au/how-apply/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/navitas-family-bursaries/21c8524508b59424ed81e0b5ba7bf11a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01590J' AND sc.`scholarship_name` = 'Navitas Family Bursaries' AND sc.`course_id` IS NULL;
