UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The International Bright Futures Scholarship is a 20% tuition fee reduction that is awarded to commencing international students in 2025 who enrol in a newly launched UniSC program (i.e. Bachelor of Education Studies (Early Childhood), Master of Business Intelligence and Analytics and Master of Business Administration / Master of Business Intelligence and Analytics dual degree). The scholarship is calculated per course and will be reflected on your UniSC student account after acceptance and prior to the fees due date of the relevant teaching period to which the scholarship applies. If you are eligible, your offer will automatically include this scholarship.', sc.`eligibility` = 'Please Contact University of the Sunshine Coast for more information about Eligibility Criteria', sc.`scholarship_amount` = '20% tuition fee reduction', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.usc.edu.au/international/programs-and-fees/international-scholarships#tab-2025-unisc-international-scholarships-for-new-students_98937', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-bright-futures-scholarship/4d63b3d03170de99f71e2ed6f048f55a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01595D' AND sc.`scholarship_name` = 'International Bright Futures Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Please Contact University of the Sunshine Coast Australia for more information.', sc.`eligibility` = 'Please Contact University of the Sunshine Coast Australia for more information.', sc.`scholarship_amount` = 'The International Student Scholarship is a 15% tuition fee reduction offered to commencing international students in 2025.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.usc.edu.au/international/programs-and-fees/international-scholarships#tab-2025-unisc-international-scholarships-for-new-students_37511', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarship/4aed132be66c6671e4a0790afc74a879', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01595D' AND sc.`scholarship_name` = 'International Student Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The newly established Australian National Centre for Timber Durability and Design Life is seeking highly motivated students interested in pursuing PhDs in the area of wood deterioration and its prevention. The Centre is based in Brisbane Australia and is a joint venture between the University of the Sunshine Coast (UniSC), the University of Queensland and the Queensland Department of Agriculture and Fisheries (QDAF).', sc.`eligibility` = 'Domestic student or International HDR student at UniSC; Bachelors Degree with First Class Honours or equivalent previous study, relevant work experience, research publications, or other research experience; Maintain satisfactory progress; Not hold an equivalent qualification to the one currently being applied for; Not have previously held a Commonwealth-funded postgraduate research scholarship unless it was terminated within six months of the current scholarship’s payments commencing; Not be the recipient of an equivalent award, scholarship, or salary, providing a benefit greater than 75 percent of the RTP rate to undertake a HDR. Income unrelated to the course of study is not to be taken into account.', sc.`scholarship_amount` = 'Annual stipend / If the successful recipient is an International student the scholarship will include tuition fees and Overseas Student Health Cover (single cover)', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.usc.edu.au/study/scholarships/research-scholarships/national-centre-for-timber-durability-and-design-life-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/national-centre-for-timber-durability-and-design-life-scholarship/713d7627bb9a007ce212843cfdd96832', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01595D' AND sc.`scholarship_name` = 'National Centre for Timber Durability and Design Life Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'To welcome new students to our college and help them kickstart their study adventure in Australia, we are offering an International Student Scholarship* to eligible new students in Trimester 1, 2025. *Terms and conditions apply. See our website for details and/or submit a contact form to confirm your eligibility.', sc.`eligibility` = 'To qualify for a scholarship*, students must:  1. Accept their offer by the cut-off date for each trimester  2. Pay all relevant fees  3. Commence study in their accepted intake (no deferrals)  4. Remain enrolled past census date. Scholarships can only be redeemed for their intended purpose and are not transferable or exchangeable in any way. Quotas apply to all scholarships, delays in accepting your offer may affect eligibility.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.griffithcollege.edu.au/how-apply/scholarships/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-student-scholarships/6cec9bc8d5d1983aefe396a5aed12d3c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01737F' AND sc.`scholarship_name` = 'International Student Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Academic Scholarships, remitting up to 50% of tuition fees, are offered to students entering Years 7-12. Applicants must demonstrate outstanding academic ability as determined by performance on the scholarship exam, academic reports and interview.To learn more and apply, please visit: https://www.mfac.edu.au/enrolments/scholarships/', sc.`eligibility` = 'Academic Scholarships, remitting up to 50% of tuition fees, are offered to students entering Years 7-12. Applicants must demonstrate outstanding academic ability as determined by performance on the scholarship exam, academic reports and interview.To learn more and apply, please visit: https://www.mfac.edu.au/enrolments/scholarships/', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/12b85013783155fa2c81b77323bee9bb', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/12b85013783155fa2c81b77323bee9bb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01748C' AND sc.`scholarship_name` = 'Academic Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Matthew Flinders Anglican College is committed to providing a wide range of learning opportunities across all areas of the curriculum and to nurturing individual student’s talents and interests. As part of this commitment, our College offers Academic, General Excellence, Music, Sport and Principal’s Scholarships for students with special talents who, in turn, will make a significant contribution to the life of our College. To learn more and to apply, visit https://www.mfac.edu.au/enrolments/scholarships', sc.`eligibility` = 'The Flinders Foundation Scholarship offers 50% remission of tuition fees to a student who does not attend the College but is keen to commence Year 10 or Year 11 at Flinders in Term 1, 2024. The student must exhibit attributes of an outstanding all-round contributor. To learn more about the Flinders Foundation Scholarship, please visit https://www.mfac.edu.au/community/flinders-foundation/flinders-foundation-scholarship/', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/flinders-foundation-scholarship/5f341f006c012dffe6a3f61aeb1fd974', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/flinders-foundation-scholarship/5f341f006c012dffe6a3f61aeb1fd974', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01748C' AND sc.`scholarship_name` = 'Flinders Foundation Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Matthew Flinders Anglican College is committed to providing a wide range of learning opportunities across all areas of the curriculum and to nurturing individual student’s talents and interests. As part of this commitment, our College offers Academic, General Excellence, Music, Sport and Principal’s Scholarships for students with special talents who, in turn, will make a significant contribution to the life of our College. To learn more and to apply, visit https://www.mfac.edu.au/enrolments/scholarships', sc.`eligibility` = 'General Excellence Scholarships, remitting up to 50% of tuition fees, are offered to students entering Years 7-12. Applicants must demonstrate excellence across three areas: strong academic ability (as opposed to the requirement of outstanding academic ability for an Academic Scholarship, leadership and/or service to the community, and significant achievement in ONE of the following: Music, Sport or The Arts. Applicants are required to sit the scholarship exam and must first apply for the Academic Scholarship.To learn more and apply, please visit: https://www.mfac.edu.au/enrolments/scholarships/', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/general-excellence/c8de19ba14b4965869d9dde2b45cbd8a', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/general-excellence/c8de19ba14b4965869d9dde2b45cbd8a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01748C' AND sc.`scholarship_name` = 'General Excellence' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Matthew Flinders Anglican College is committed to providing a wide range of learning opportunities across all areas of the curriculum and to nurturing individual student’s talents and interests. As part of this commitment, our College offers Academic, General Excellence, Music, Sport and Principal’s Scholarships for students with special talents who, in turn, will make a significant contribution to the life of our College. To learn more and to apply, visit https://www.mfac.edu.au/enrolments/scholarships', sc.`eligibility` = 'Music Scholarships, remitting up to 50% of tuition fees, are offered to students entering Years 7-12. Applicants must demonstrate outstanding musical ability. Scholarships are offered on the basis of an audition and a subsequent interview with the Principal. Applicants are also required to sit the academic testing.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/music-scholarships/f965bfc0fc1389432b3998cba37652fc', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/music-scholarships/f965bfc0fc1389432b3998cba37652fc', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01748C' AND sc.`scholarship_name` = 'Music Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Matthew Flinders Anglican College is committed to providing a wide range of learning opportunities across all areas of the curriculum and to nurturing individual student’s talents and interests. As part of this commitment, our College offers Academic, General Excellence, Music, Sport and Principal’s Scholarships for students with special talents who, in turn, will make a significant contribution to the life of our College. To learn more and to apply, visit https://www.mfac.edu.au/enrolments/scholarships', sc.`eligibility` = 'The Principal’s Scholarship, offering full remission of tuition fees, is offered to an outstanding student not currently enrolled at the College. The winner will be selected, at the Principal’s discretion, from the applicants for Academic, General Excellence and Music scholarships categories. Applicants must demonstrate sound academic ability along with outstanding performance in the field of sport (including chess or debating). Applicants are also to show evidence of broad involvement across school life.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/principals-scholarship/62a864677570a79f53b55fd07670b657', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/principals-scholarship/62a864677570a79f53b55fd07670b657', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01748C' AND sc.`scholarship_name` = 'Principal\'s Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'ACPE values the vibrant contribution that students have in the sport industry globally and want to reward you to start your postgraduate studies offshore and online with this scholarship.', sc.`eligibility` = 'This scholarship is applicable to new international students undertaking postgraduate studies offshore online for the full duration of their course. Applicants must: meet the entry required for their desired course. Prove your English language proficiency through IELTS scores or other accepted alternatives including Pearson Test of English (PTE) and TOEFL. Maintain a full-time study load, 1 EFTSL over a 12-month study period. \r\nInternational scholarships are only available for first attempt subjects only. Full price is charged on retake for subjects if previously failed. Scholarship are also no deferrable.', sc.`scholarship_amount` = '10% off 1 unit fee', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://acpe.edu.au/admissions/scholarships/international-scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/offshore-online-scholarships/44aae35725537f97a7dc6d4ad8971b86', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '01822J' AND sc.`scholarship_name` = 'Offshore Online Scholarships' AND sc.`course_id` IS NULL;
