UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Are you a current Kaplan Business School student achieving exceptional academic results while contributing positively to the KBS community? Submit an application and you could be the winner of the Dean\'s Award!', sc.`eligibility` = 'For students to be eligible for the award, they must fulfil the following criteria:; At the time of application, the student must have a Distinction average or higher grade; Submit a 500-word personal statement or 2-minute video on why they should receive the award; Provide evidence or examples of where they have gone above and beyond for the KBS community; You must have completed at least one (1) trimester with KBS before applying for the Dean\'s Award; Any submissions which exceed the word count or time limit by more than 10% will be disqualified since their inclusion would bestow an unfair advantage to the detriment of other applicants who have complied with the entry requirements.', sc.`scholarship_amount` = 'Awarded to up to two students nationally each trimester, the Dean\'s Award winners are awarded a 50% scholarship for the remainder of their current course and any future Kaplan Business School course. The award winners will be determined based on acad', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.kbs.edu.au/student-life/deans-award', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/deans-award/e2c123b2f5905cadf87a53f4cc97d44e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02426B' AND sc.`scholarship_name` = 'Dean\'s Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'In our genuine ambition to help individuals around the world reach their educational \r\nand career goals, Kaplan Business School is offering a limited number of High Achievers \r\nScholarships to students who can display a record of outstanding academic merit.', sc.`eligibility` = 'To be eligible for the High Achievers Scholarship, you must:; Demonstrate exceptional academic success in a related field of study. \r\nFor details refer to www.kbs.edu.au/scholarships.; Not be a recipient of any other Kaplan Business School scholarship, \r\naward or promotion.; Have met Kaplan Business School’s English language proficiency \r\nrequirements for the course offered or will have met these requirements \r\nprior to commencing study with Kaplan Business School.', sc.`scholarship_amount` = 'The International Student Scholarship will provide a reduced tuition fee for the relevant Kaplan Business School undergraduate or postgraduate degree to any student that meets the eligibility criteria.', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.kbs.edu.au/admissions/scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/high-achievers-scholarship/c2c45a5c67ae7cbfc32a64e17dfd7445', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02426B' AND sc.`scholarship_name` = 'High Achievers Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = NULL, sc.`eligibility` = NULL, sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/scholarships-available/65f92cbdf663c9055910a78f9b8585ca', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/scholarships-available/65f92cbdf663c9055910a78f9b8585ca', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02448G' AND sc.`scholarship_name` = 'Scholarships Available' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Academic Excellence Award', sc.`eligibility` = 'A student will be eligible to receive an Academic Excellence Award based on their academic results, based on the following; $500 reward: average mark between 85-89 marks for any four (4) subjects in one (1) term of study; $1,000 reward average mark above 90+ for any four (4) subjects in one (1) term of study.; The student will not be eligible for any reward if the student reaches the above average marks for his/her first term but does not enrol in a further four (4) subject within the next two (2) terms.; The monetary reward will be paid by electronic funds transfer to a bank account nominated by the student at the end of each calendar year after the student has completed at least two (2) terms at IMC.; The student must enrol in at least eight (8) or more subjects at IMC. The above reward will not be open to students who have only enrolled in one (1) term at IMC.', sc.`scholarship_amount` = 'Up to AUD $1000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.imc.edu.au/study/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-excellence-award/71897fca4cd08cab7621bc4706f3f0c1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02491D' AND sc.`scholarship_name` = 'Academic Excellence Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Australian National Institute of Management and Commerce Award', sc.`eligibility` = 'Each application will be assessed on a case by case basis and at the discretion of the Dean of School, or his or her delegate, pursuant to the selection procedure outlined in the Terms and Conditions for Scholarship Awards.; This Award is available to domestic and international students enrolled in at least eight (8) units per year offered by the Business School which is equal to a total of 48 credit points per year.; This Award is available to eligible undergraduate Business applicants only.', sc.`scholarship_amount` = 'AUD $3000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.imc.edu.au/study/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/australian-national-institute-of-management-and-commerce-award/1eade73573dff239d30c947538d288dd', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02491D' AND sc.`scholarship_name` = 'Australian National Institute of Management and Commerce Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'China Graduate Scholarship', sc.`eligibility` = 'The student must have completed an equivalent Australian qualification, hold a valid Australian visa and Chinese passport.; Meet the minimum admission entry requirements of IMC including English language proficiency.; The student will be required to enrol in no less than 8 subjects per year.; This Award is dependent on the student ensuring compliance with their Genuine Temporary Entrant (GTE) requirements and visa obligations.', sc.`scholarship_amount` = 'Please contact a member of the recruitment team for the most up-to-date value.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.imc.edu.au/study/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/china-graduate-scholarship/238d0e98ebe7c17d972a92f941f96bf5', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02491D' AND sc.`scholarship_name` = 'China Graduate Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Dean\'s Award', sc.`eligibility` = 'Each application will be assessed on a case by case basis and at the discretion of the Dean of School, or his or her delegate, pursuant to the selection procedure outlined in the Terms and Conditions for Scholarship Awards.; This Award is available to domestic and international students enrolled in at least eight (8) units per year offered by Business School which is equal to a total of 48 credit points per year.; The Award is available to eligible undergraduate Business applicants.; Evidentiary requirements include; For School leavers, Gap year students and Mature age students: ATAR results (or its equivalent) of 85.0 and records as part of the application process including any final secondary schooling reports. This Award not only focuses on academic merit but also on a student’s contribution to the wider community. A recommendation letter from the student’s secondary school/employers/community organisation or any other references will be required to establish the student’s contribution and involvement in the community e.g. mentoring programs, volunteering for a community-based organisation, organising charity or fundraising activities for the community.; For International students: ATAR results (or its equivalent) of a minimum of 85.0, the original foreign passport, student visa, IELTS results indicating the required score of 7.0 or its equivalent as a minimum as well as secondary school reports. International students are also to provide a translated recommendation letter as described above.; For all previous Tertiary students, academic transcripts are requested to establish a minimum credit average.; The student who is the recipient of this Award must ensure that they maintain a GPA (Grade Point Average) of 2.0 each year i.e. credits each year eight (8) units in order to maintain their eligibility to this Award.', sc.`scholarship_amount` = 'AUD $2000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.imc.edu.au/study/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/deans-award/313c416b80ac08ba811f5089872fb815', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02491D' AND sc.`scholarship_name` = 'Dean\'s Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'English Language Achiever', sc.`eligibility` = 'This Award is available to offshore international students that are enrolled in an International Pathway Program between the Institute and international universities/institutes. The Award will apply and take effect once the student engages in their studies at the Institute in Australia.; The student is to be in Australia and enrolled at the Institute for a minimum eight (8) units per year which is equal to a total of 48 credit points per year as part of the International Pathway Program in order to be eligible for this Award.; Evidentiary requirements include the original foreign passport, student visa, IELTS results indicating the required score; First-class Award: to achieve IELTS of 6.5 overall with minimum 6 in each band; Second-class Award: to achieve IELTS of 6.0 overall with minimum 5.5 in each band; Third-class Award: to achieve IELTS of 5.5 overall with minimum 5 in each band; The Institute allocates a limited number of these awards. As part of a competitive application process, students must submit the application before the cut-off date, normally 4 weeks before the Institute’s course commences, accept their full offer and pay their fees within 14 business days. A scholarship offer cannot be deferred.; The value of the Award is assessed based on established eligibility criteria and the evidence provided.; This Award is dependent on the student ensuring compliance with their Genuine Temporary Entrant (GTE) requirements and visa obligations. If the Institute is put on notice of any non-compliance, the Award may be terminated in accordance with clause 4.', sc.`scholarship_amount` = 'Up to AUD $3000 — $3,000 one-off (first-tier), $2,000 one-off (second-tier) & $1,000 one-off (third-tier)', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.imc.edu.au/study/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/english-language-achiever/0a0efe0e86aa186f6bdc05a1bbca01da', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02491D' AND sc.`scholarship_name` = 'English Language Achiever' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Global Young Leaders Scholarship', sc.`eligibility` = 'This Award is available to offshore international students that are enrolled in an International Pathway Program between the Institute and international universities/institutes. The Award will apply and take effect once the student engages in their studies at the Institute in Australia.; The student is to be in Australia and enrolled at the Institute for a minimum eight (8) units per year which is equal to a total of 48 credit points per year as part of the International Pathway Program in order to be eligible for this scholarship.; Evidentiary requirements include, the original foreign passport, student visa, IELTS results indicating the required score of 6.5 or its equivalent for the first-class award and 6.0 or its equivalent for the second-class award as well as any academic transcripts. Students are also to provide an English translated recommendation letter that confirms that the student’s performance is in the top 20 % of their course.; The Award is assessed based on established eligibility criteria and the evidence provided.; This Award is dependent on the student ensuring compliance with their Genuine Temporary Entrant (GTE) requirements and visa obligations. If the Institute is put on notice of any non-compliance, the Award may be terminated in accordance with clause 4.', sc.`scholarship_amount` = 'Up to AUD $4000 — $4,000 one-off (first-tier) & $3,000 one-off (second-tier)', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.imc.edu.au/study/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/global-young-leaders-scholarship/d1ebbfa2192f8d3e0dd386f5787b53f2', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02491D' AND sc.`scholarship_name` = 'Global Young Leaders Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'IMC\'s Outstanding Achievement Award', sc.`eligibility` = 'Each application will be assessed on a case by case basis and at the discretion of the Dean of School, or his or her delegate, pursuant to the selection procedure outlined in the Terms and Conditions for Scholarship Awards.; This Award is available to domestic and international students enrolled in at least eight (8) units per year offered b Business School which is equal to a total of 48 credit points per year.; The Award is available to eligible undergraduate Business applicants.; The winning of this award precludes a student from eligibility for other Awards under the Institute\'s Scholarship Program.', sc.`scholarship_amount` = 'AUD $8000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.imc.edu.au/study/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/imcs-outstanding-achievement-award/f3a8fc4d5e95305f4dca43c0898c5f1f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02491D' AND sc.`scholarship_name` = 'IMC\'s Outstanding Achievement Award' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'International Excellence Scholarship', sc.`eligibility` = 'This Award is available to onshore international students that are enrolled in at least eight (8) units per year offered by Law or Business School which is equal to a total of 48 credit points per year.; This Award is available to eligible students that are granted less than 48 credit points from advanced standing.', sc.`scholarship_amount` = '15%-25% of tuition fee', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.imc.edu.au/study/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-excellence-scholarship/dd8d1bfaa39245408040d4b5703b3873', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02491D' AND sc.`scholarship_name` = 'International Excellence Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Young Achiever', sc.`eligibility` = 'Each application will be assessed on a case by case basis and at the discretion of the Dean of School, or his or her delegate, pursuant to the selection procedure outlined in the Terms and Conditions for Scholarship Awards.; This Award is available to domestic and international students enrolled in at least eight (8) units per year offered by Business School which is equal to a total of 48 credit points per year.; The Award is available to eligible undergraduate Business applicants.; Evidentiary requirements include; For School leavers and Gap year students: ATAR results (or its equivalent) of minimum 85.0 and records as part of the application process including any final secondary schooling reports. This Award not only focuses on academic merit but also on a student’s involvement in leadership within their school environment. A recommendation letter from the student’s secondary school/employers/community organisation and others as applicable will also be required. Documents are to establish the student’s leadership skills and the initiatives they have been involved in which have required the exercise of leadership skills e.g. leadership positions held in school, Student Representative Councils and student leadership programs.; For International students: ATAR results (or its equivalent) of a minimum of 85.0, the original foreign passport, student visa, IELTS results indicating the required score of 7.0 or its equivalent as a minimum as well as secondary school reports. International students are also to provide a translated recommendation letter as described above.; The student who is the recipient of this Award must ensure that they maintain a GPA (Grade Point Average) of 2.0 each year i.e. credits each year as a full-time student in order to maintain their eligibility to this Award.', sc.`scholarship_amount` = 'AUD $2000/year', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.imc.edu.au/study/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/young-achiever/0ad84f96f744f35d27d9b6711cd23b1a', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02491D' AND sc.`scholarship_name` = 'Young Achiever' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Applicants must have submitted a completed Application for Admission before they will be considered for an academic scholarship. Scholarships will only be awarded to applicants who have fulfilled all other entrance requirements as outlined in the relevant School Course Information Brochure and the current Excelsia College Student Handbook. Scholarships are awarded at the commencement of each academic year for students commencing in that year only.', sc.`eligibility` = 'All new domestic and overseas undergraduate applicants. Overseas applicants are not linked to round offers and, therefore, should ensure their full application has arrived by the scholarship closing date. Overseas applicants also need to consider visa processing times for their country and the mode of audition when applying for scholarships.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://excelsia.edu.au/wp-content/uploads/Undergraduate-Scholarship-Application.pdf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/undergraduate-academic-scholarship/601527f54485f41c1eddfba152f83d17', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02664K' AND sc.`scholarship_name` = 'Undergraduate Academic Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'English Language Bursary', sc.`eligibility` = 'To be eligible to receive a bursary or scholarship with UOW College Australia, the applicant must be a citizen of the stipulated country.; Where a student extends their course after course commencement at UOW College Australia, the tuition fee for the period of the extension will be at the same bursary or scholarship rate. ; The bursary or scholarship can only be used on the course dates as specified in the offer of admission. Where an applicant defers or otherwise changes the course commencement date, the bursary or scholarship will be reassessed and may not be re-offered for that deferred course commencement date. ; This scholarship and bursary scheme supersedes all previous offers.; Scholarship and bursary recipients may be invited to participate in selected marketing initiatives by UOW College Australia and are expected to be willing to engage in these activities.; All fees are in Australian Dollars (AUD) and are dependent on the actual year of commencement and are subject to change without notice and in accordance with approved annual fee increases.', sc.`scholarship_amount` = '2025 academic year: reduced tuition fee of $399 per week (from $585 ); 2026 academic year: reduced tuition fee of $420 per week (from $599)', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uowcollege.edu.au/support-resources/student-services/fees/international/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/english-language-bursary/f834ebea78e6dd7deb4f72c3c4e04023', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02723D' AND sc.`scholarship_name` = 'English Language Bursary' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'English Language Pathway Bursary', sc.`eligibility` = 'To be eligible to receive a bursary or scholarship with UOW College Australia, the applicant must be a citizen of the stipulated country.; Where a student extends their course after course commencement at UOW College Australia, the tuition fee for the period of the extension will be at the same bursary or scholarship rate. ; The bursary or scholarship can only be used on the course dates as specified in the offer of admission. Where an applicant defers or otherwise changes the course commencement date, the bursary or scholarship will be reassessed and may not be re-offered for that deferred course commencement date. ; This scholarship and bursary scheme supersedes all previous offers.; Scholarship and bursary recipients may be invited to participate in selected marketing initiatives by UOW College Australia and are expected to be willing to engage in these activities.; All fees are in Australian Dollars (AUD) and are dependent on the actual year of commencement and are subject to change without notice and in accordance with approved annual fee increases.', sc.`scholarship_amount` = '20% tuition fee waiver', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uowcollege.edu.au/support-resources/student-services/fees/international/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/english-language-pathway-bursary/ffbe3500c12f15c83d1155a9dccc76c7', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02723D' AND sc.`scholarship_name` = 'English Language Pathway Bursary' AND sc.`course_id` IS NULL;
