UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'These scholarships provide opportunity for students to participate in a program of supervised research. Students can extend their knowledge, develop their analytical and critical thinking, and their communication skills. The scholarship is open to all Avondale students who are enrolled beyond the first year of their course and have a GPA of 5.0 or above.', sc.`eligibility` = 'The scholarship holder (scholar) is required to complete 160 hours of research. This may take place in a block of full-time work, or may be negotiated with the project supervisor to take place part-time over a longer period. Research may be conducted on campus (Lake Macquarie or Sydney) or off campus. At the completion of the project, the scholar and their supervisor will give an oral presentation of their research. The supervisor will be responsible for organising a suitable format, time and venue for the presentation in consultation with the scholar.', sc.`scholarship_amount` = 'Up to AUD $4000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.avondale.edu.au/scholarship/avondale-student-research-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/avondale-student-research-scholarship/0e3606346f4219405388b45e1f67b987', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '02731D' AND sc.`scholarship_name` = 'Avondale Student Research Scholarship' AND sc.`course_id` IS NULL;
