UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Building on ALG’s strong track record in Early Childhood Education and Care, we are excited to announce the introduction of a 20% tuition fee scholarship for new international students starting an ALG Early Childhood Education and Care course in any intake in 2026.', sc.`eligibility` = 'This scholarship is open to international students and applies to the full duration of the program (including packaged ALG courses). Eligible courses are:\r\n\r\nCHC30121 Certificate III in Early Childhood Education and Care\r\nCHC50125 Diploma of Early Childhood Education and Care\r\nThis 20% scholarship will help more students access ALG’s high-quality training and support Australia’s growing demand for skilled early childhood educators.\r\n\r\nGraduates of the Diploma of Early Childhood Education and Care may also be eligible for entry into the second year of Ikon’s Bachelor of Early Childhood Education. Eligible applicants may receive course credit for up to 66 credit points.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/20-early-childhood-education-and-care-scholarship/5d00d5bbc9621ad30cc1642b72ba9234', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/20-early-childhood-education-and-care-scholarship/5d00d5bbc9621ad30cc1642b72ba9234', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03071E' AND sc.`scholarship_name` = '20% Early Childhood Education and Care Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'We offer a 20% scholarship for eligible academic pathway programs for students who commence their studies in 2025.', sc.`eligibility` = 'Your studies at Murdoch College must commence in 2025; You are an academic pathways student at Murdoch College.; You must not be a recipient of any other College scholarship or grant, or a government-sponsored student for the duration of this College scholarship.', sc.`scholarship_amount` = 'We offer a 20% scholarship for eligible academic pathway programs for students who commence their studies in 2025.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://murdochcollege.edu.au/scholarships.html', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/murdoch-college-scholarships/8de989298ef79903fcace8d7f163128d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03127E' AND sc.`scholarship_name` = 'Murdoch College Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'King\'s Own Institute (KOI) is helping individuals around the world to reach their educational and career goals by\r\noffering KOI International Student Scholarships (KISS) to students who can display a record of outstanding\r\nacademic and English merit.', sc.`eligibility` = 'Eligibility (Onshore); 1 - You must have a passing record of 100% with your most recent provide; Your previous provider must be a higher education institute or university. Your proposed studies at KOI\r\nmust be of the same AQF level; Eligibility Offshore (Undergraduate); 1 - You must have achieved a Higher Secondary (year 12) result of a minimum 70% or an equivalent CGPA in previous study; 2 - You must have achieved an IELTS / PTE or an equivalent score of overall 6.5 or more; Eligibility Offshore (Postgraduate); 1 - You must have achieved a Bachelor qualification with a minimum of 60% or an equivalent CGPA in previous study; 2 - You must have achieved an IELTS / PTE or an equivalent score of overall 7.0 or more.', sc.`scholarship_amount` = 'Up to $500 scholarship per trimester (pro-rated)', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://koi.edu.au/wp-content/uploads/2025/02/KOI-KISS-Scholarship-2025_20Jan2025.pdf', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/koi-international-student-scholarship-2025/5c3a1f07672d242193fe630180fdd4cc', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03171A' AND sc.`scholarship_name` = 'KOI INTERNATIONAL STUDENT SCHOLARSHIP 2025' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'To honour Venerable Master Hsing Yun, HYEF is offering this scholarship to assist high achieving international students to undertake Applied Buddhist Studies and Humanistic Buddhism programs at Nan Tien Institute (NTI). We hope that people with similar visions can contribute to this great initiative.', sc.`eligibility` = 'The applicant must have been admitted or been offered admission to one of the following courses at NTI:; Master of Arts (Applied Buddhist Studies); Graduate Diploma of Applied Buddhist Studies; Graduate Certificate in Applied Buddhist Studies; Graduate Certificate in Humanistic Buddhism', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.nantien.edu.au/admissions/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/hsing-yun-education-foundation-hyef-scholarship/118d8bf202e91807d9276b782e4c9dda', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03233C' AND sc.`scholarship_name` = 'Hsing Yun Education Foundation (HYEF) Scholarship' AND sc.`course_id` IS NULL;
