UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Academic Merit Scholarship is awarded to the student who achieves the most outstanding academic results in their first trimester of studies at Navitas member institution.', sc.`eligibility` = 'Be continuing (current) student, enrolled and studying towards a Navitas Diploma, Advanced Diploma or Associate Degree (Australia) UTP Stage II or Associate Degree (Canada), UPP or IUTP (USA), Undergraduate pathway program (UK), University Foundation or Bachelor Degree program (Australia) or Master’s programs (Australia); Be currently studying full-time; Have achieved competencies in all courses across their current program (for which the scholarship is applied for) in the semester prior to being eligible for the scholarship; Not have any outstanding fees on their student account; Not have previously received a Navitas scholarship or bursary, or had a scholarship or bursary from Navitas withdrawn.', sc.`scholarship_amount` = 'These scholarships are for one academic semester or part thereof (equivalent to the maximum of up to five academic subjects) for a Navitas Diploma, Advanced Diploma or Associate Degree (Australia), UTP Stage II or Associate Degree (Canada), UPP or IU', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobecollegeaustralia.edu.au/how-apply/scholarships/navitas-academic-merit-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/navitas-academic-merit-scholarship/1cf1d1b652a8b0955638c100fcca736d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03312D' AND sc.`scholarship_name` = 'Navitas Academic Merit Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The bursary is equivalent to 10% of the tuition fee for up to 8 units of study within one program only with a Navitas member institution. The bursary does not apply to additional units or repeat units that may also be undertaken and excludes mixed English options.', sc.`eligibility` = 'Family Bursary applies where two or more students from the same family study at a Navitas institution.; The first family member can be studying at a Navitas institution at the same time as the other family members or may have studied at any Navitas institution previously.; The family bursary is granted to the second and subsequent family members who study at a Navitas institution.; Not have previously received a Navitas scholarship (or bursary) or had a scholarship (or bursary) from Navitas withdrawn.', sc.`scholarship_amount` = 'The bursary is equivalent to 10% of the tuition fee for up to 8 units of study within one program only with a Navitas member institution. The bursary does not apply to additional units or repeat units that may also be undertaken and excludes mixed En', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.latrobecollegeaustralia.edu.au/how-apply/scholarships/navitas-family-bursary/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/navitas-family-bursary/ed3da166f84e5f59a4f46780b3fa77a8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03312D' AND sc.`scholarship_name` = 'Navitas Family Bursary' AND sc.`course_id` IS NULL;
