UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Have you recently completed your Graduate Diploma of Agribusiness from Ironwood Institute? Join us on the Master of Business Administration Advanced course, and take advantage of 20 per cent scholarship off your total course tuition.', sc.`eligibility` = 'Students who complete their Graduate Diploma of Agribusiness from Ironwood Institute can pathway into our MBAA with a 20% Scholarship provided they meet admissions entry requirements.', sc.`scholarship_amount` = '20% off tuition fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/ironwood-pathway-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ironwood-pathway-scholarship/9cd9e614768fd7a0a528a8da5aa05478', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03389E' AND sc.`scholarship_name` = 'Ironwood Pathway Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Are you a current student at Kings College Malaysia studying a Business degree, looking to study with Torrens University Australia? You may be eligible for a scholarship of up to 45% off your tuition fees when you study concurrently with Torrens University or transition from Kings College Malaysia to continue your studies at Torrens University Australia.', sc.`eligibility` = 'This scholarship is available to students enrolled in a Business course at Kings College Malaysia who are either studying concurrently with Torrens University Australia or transferring from Kings College Malaysia to Torrens University Australia. To be eligible, students must meet Torrens University’s admission entry requirements and provide an offer letter from Kings College Malaysia. A conditional offer and conditional CoE will be issued based on this documentation, and the scholarship will be confirmed once the student commences concurrent study or transfers to Torrens University Australia.', sc.`scholarship_amount` = '45% off tuition fees', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/kings-college-malaysia-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/kings-college-malaysia-scholarship/c4640aa7b8717e02515ad2e0af3aa27c', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03389E' AND sc.`scholarship_name` = 'Kings College Malaysia Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'If you\'re a new international students commencing study in 2026 who hold a passport from Africa, Bhutan, Mauritius, Middle East, Philippines, South Asia (including Maldives), East Asia and South East Asia, you may be you may be eligible for this scholarship. It covers up to 25 per cent of your total course tuition.', sc.`eligibility` = 'To be considered, students must hold a passport from an eligible country and meet the scholarship requirements. A limited quota applies.', sc.`scholarship_amount` = 'Up to 25% off tuition fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/motivational-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/motivational-scholarship/8d6679f69636a357308b4f92253447d4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03389E' AND sc.`scholarship_name` = 'Motivational scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Are you a new student from Kenya? Torrens University Australia in partnership with the County Government of Elgeyo Marakwet, is proud to offer a scholarship initiative that expands access to higher education for talented students from disadvantaged backgrounds. This program empowers the next generation of Kenyan leaders and innovators to achieve their academic and professional goals.', sc.`eligibility` = 'This scholarship requires students to provide a scholarship letter from the Elgeyo Marakwet County Government, Kenya, and hold a valid passport from an eligible country. It applies to students commencing academic coursework programs (not applicable for English language courses) and applying for a Confirmation of Enrolment (COE). This scholarship is not available to Study Abroad students and cannot be combined with any other scholarships. A limited quota applies.', sc.`scholarship_amount` = '50% off tuition fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/pepea-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/pepea-scholarship/8ed9cf1eebf8adeef29f5b422ecbc27e', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03389E' AND sc.`scholarship_name` = 'PEPEA Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Have you recently completed your Foundation Diploma, Basic Diploma and Advanced Diploma of Fashion Design / Communication Design from Pearl Academy? Join us on one of the Bachelor of Communication Design, Bachelor of Branded Fashion Design, Bachelor of Interior Design (Commercial) or Bachelor of Interior Design (Residential), and take advantage of 30 per cent scholarship off your total course tuition.', sc.`eligibility` = 'Students who complete their Foundation Diploma, Basic Diploma and Advanced Diploma of Fashion Design / Communication Design from Pearl Academy can pathway into our Bachelor of Communication Design, Bachelor of Branded Fashion Design, Bachelor of Interior Design (Commercial) and Bachelor of Interior Design (Residential) provided they meet admissions entry requirements.', sc.`scholarship_amount` = '30% off tuition fees', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships/pearl-pathway-scholarship', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/pearl-pathway-partnership/c0c68fcf46f67d009d8b8eb014495381', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03389E' AND sc.`scholarship_name` = 'Pearl Pathway Partnership' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is based on a Three-Pillar Approach to learning: Professional and Personal Growth, Practical Skills Development, and Academic Achievement. Its designed to help you graduate well-rounded, worldly, confident and prepared for a rewarding future. This scholarship will cover up to 30 percent of your total course tuition. Its available to new international students enrolling at the Blue Mountains International Hotel Management School in 2025.', sc.`eligibility` = 'Undergraduate and postgraduate international students must maintain a full-time study load, 1 EFTSL over a 12-month study period, to maintain their scholarship. Scholarship applicable on tuition fee only and on first attempt subjects. Full price charged on retake subjects if previously failed. Scholarship may not be eligible for any course changes during the duration of study. Successful applicants will be requested to assist with additional duties during their time as a student. These responsibilities will include, becoming members of the Student Representative Council, undertaking additional student ambassadorial duties and being available for promotional opportunities.', sc.`scholarship_amount` = 'Limited 3 pillar scholarships ranging from 10% to 30%', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.torrens.edu.au/how-to-apply/fees-scholarships/scholarships/international-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/three-pillars-blue-mountains-international-hotel-management-school-hospitality-scholarship/444582e94b6376c63d1a5474cf13845f', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03389E' AND sc.`scholarship_name` = 'Three Pillars Blue Mountains International Hotel Management School Hospitality Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Scholarships will be awarded based on our Three Pillar Approach to learning. These three pillars are Professional and Personal Growth, Practical Skills Development, and Academic Achievement - ensure that you graduate well-rounded, worldly, confident and prepared for a rewarding future.', sc.`eligibility` = 'Recipients must be new BMIHMS at Torrens University students commencing studies. For more information, please click on \'more information\'', sc.`scholarship_amount` = 'Up to AUD $20000', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.bluemountains.edu.au/apply/scholarships-available/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/three-pillars-scholarship/6980b5b2f3ee6dd56620ff48709699d4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03389E' AND sc.`scholarship_name` = 'Three Pillars Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Value: Full tuition for the Diploma degree (1 year). The Val Cook Scholarship, named after BMIHMS long term Alumni Ambassador and sponsored by the school`s Alumni board, will grant one student a scholarship (tuition, room and board) for the first year of their Bachelor course (diploma level).', sc.`eligibility` = 'Applicants must have 2-5 years of hospitality/ tourism industry experience.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.bluemountains.edu.au/apply/scholarships-available/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/val-cook-scholarship/be6c73b37d507b05f554bc6c78bb88e4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03389E' AND sc.`scholarship_name` = 'Val Cook Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Scholarship provides tuition assistance to graduating international high school students who have completed studies in commerce, accounting, or business in high school. Applicants must demonstrate a strong commitment to their community and provide evidence of involvement in cocurricular or extracurricular activities throughout high school. This is a merit-based scholarship that recognises applicants with a strong academic background and incentivises them to continue striving for excellence.', sc.`eligibility` = 'Be an international student commencing a Bachelor of Business for the first time at Sheridan in Semester 2, 2025 or Semester 1, 2026; Be 17 years of age or over; Apply for direct entry only; Have submitted the Scholarship application form and provided requested evidence by the relevant deadline; Satisfy all entry requirements for an intended course and Sheridan’s admissions process, including the student interview; Have accepted a Letter of Offer & Acceptance issued by Sheridan; Have signed and returned the Scholarship Terms and Conditions to Sheridan by the relevant deadline; Agree the Scholarship is not transferrable; Successfully commence study in the semester and year indicated in the Letter of Offer and Acceptance. If commencement is deferred, the scholarship may be forfeited; Successfully organise his/her Australian Student Visa to be able to arrive in Perth and study faceto-face at Sheridan', sc.`scholarship_amount` = 'Recipients will receive a 100% scholarship towards their tuition fees', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://sheridan.edu.au/index.php/component/quix/113-scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/international-merit-based-scholarship/d3d5078fb631f2fd6034b1c6a12a55ca', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03391M' AND sc.`scholarship_name` = 'International Merit Based Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Scholarships are now available for international students and valid for all international study applications from March 2024! Start your dream course in the creative field while we ease the financial load across your studies-eligible students can receive up to $11,000 AUD for a Bachelor or up to $3,600AUD for a Diploma.', sc.`eligibility` = 'Applicants must submit a 300 word statement along with their application explaining why they should be awarded the scholarship; Approved applicants must comply with their visa conditions and obligations as Collarts students; Applicants must meet Collarts entry requirements; Scholarships are limited and awarded at the discretion of the Collarts International Team; Valid for applications received in 2024; Students must pay their fees on time to maintain eligibility; Students must maintain a credit (65%) average or above in their Collarts studies to maintain eligibility.', sc.`scholarship_amount` = 'Up to AUD $11000', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://international.collarts.edu.au/faq#phase-3', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/collarts-international-scholarship/2187f51c2c1f6ebb6e87e039ed84a2c3', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03392K' AND sc.`scholarship_name` = 'Collarts International Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'We recognise the challenges that COVID-19 is presenting to our international as well as domestic students who wish to begin their study at IHM. We understand that this is a difficult time for our international students, particularly when it comes to their finances. Hence, through our scholarships along with continuing support to our students to help them advance in their career. A scholarship provides financial assistance during your study. Some scholarships provide a stipend that covers tuition fees, while others provide only partial funding. We understand how important education is to fulfil your potential, and that access to a scholarship can help make that happen.', sc.`eligibility` = 'To be eligible for IHM’s NCAP Gateway to Global Nursing Scholarship program an applicant should:; Satisfy the admission criteria for IHM courses; Demonstrate successful completion of a recognised Bachelor of Nursing course / 3 year international diploma of Nursing course with a minimum overall score of 70%; Demonstrate superior leadership and initiative in nursing by completing a 500 word response detailing:; why you should be considered for an IHM NCAP Gateway to Global Nursing Scholarship\r\nwhat have you contributed to the nursing sector in your area(s) of work, and your career plans and educational goals; Include a Letter of Support from your current employer or from the Institute where you completed your undergraduate nursing education.', sc.`scholarship_amount` = 'Up to AUD $10000 — Up to 6 months (full-time); Up to 12 months (part-time)', sc.`level_of_studies` = 'Postgraduate', sc.`field_of_studies` = NULL, sc.`website` = 'https://ihm.edu.au/scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/ncap-gateway-to-global-nursing-scholarship-program/5ee458bbdcb0ebaf8690fd7ad2e9a8d4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03407G' AND sc.`scholarship_name` = 'NCAP Gateway to Global Nursing Scholarship Program.' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Oakleigh Grammar offers scholarships to students who are talented, motivated and civic-minded, and who have the potential to make a positive contribution in a leadership and academic capacity, becoming part of our close-knit community. Our scholarships are granted to a handful of talented and passionate students who wish to excel in their learning journey, be it in sport, science, art, music or community.', sc.`eligibility` = 'Successful applicants will be curious learners, active sports participants, musically talented or community focused.\r\n\r\nTo apply for a General Excellence Scholarship, a student will have a good academic standard, plus excellence in at least one the following: sport, music, leadership, community service.\r\n\r\nAll scholarship candidates (including current Oakleigh Grammar students) must sit the ACER examination and also provide the following information when lodging their Scholarship Application form with ACER.\r\n\r\nSchool report\r\nNaplan test results (most recent)\r\nCertificates of achievement\r\nSporting ability/achievements\r\nMusic ability/achievements\r\nLeadership achievements and Community Service.\r\nScholarship applicants must include this information with their application, including levels attained.\r\n\r\nStudents applying for scholarships may like to include a reference from a teacher, principal, sporting organisation, church group, community service organisation, etc (though this is not essential).\r\n\r\nInterviews will be held with the Heads of School after the student scholarship exam results have been released.', sc.`scholarship_amount` = 'Partial remission of tuition fees for the duration of enrolment.', sc.`level_of_studies` = 'Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/general-and-academic-excellence-scholarships/aa1e24974234e7fb6f8ea997ddc48e65', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/general-and-academic-excellence-scholarships/aa1e24974234e7fb6f8ea997ddc48e65', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03423G' AND sc.`scholarship_name` = 'General and Academic Excellence Scholarships' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Academic Scholarship recognises high achieving students with a demonstrated track record of academic excellent. Valued at up to 50% of tuition fees, based on the strength of your application.', sc.`eligibility` = '1. Demonstrated record of academic excellence, evidenced by test scores, results, or grades from one or more subject areas over time. 2. Demonstrated record of outstanding academic achievement, evidenced by honours/awards accomplished through curricular or extracurricular activities, highlighting talent and dedication.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Primary schooling, Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/286fd8ac091b0009f14027a1c9959305', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/286fd8ac091b0009f14027a1c9959305', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03547G' AND sc.`scholarship_name` = 'Academic Scholarship' AND sc.`course_id` IS NULL;
