UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Academic Scholarships are open to both existing students and new students to St George\'s across all year groups. All Academic Scholarship applicants are required to sit the Edutest Scholarship Examination. This will take place at St George\'s Anglican Grammar School - 441 Murray Street, commencing at 9am on Saturday 6 June 2026.', sc.`eligibility` = '1. Demonstrated record of academic excellence, evidenced by test scores, results, or grades from one or more subject areas over time. 2. Demonstrated record of outstanding academic achievement, evidenced by honours/awards accomplished through curricular or extracurricular activities, highlighting talent and dedication.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Primary schooling, Secondary schooling', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.stgeorges.wa.edu.au/enrolment/scholarships', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/5fc45b7f180f4fb7a275019e3d603deb', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03547G' AND sc.`scholarship_name` = 'Academic Scholarship' AND sc.`course_id` IS NULL;
