UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'A student must be enrolled in full-time study load (4 courses per semester OR 3 courses per semester if enrolled in Graduate Diploma of Business or Master of Business Administration) to be eligible for scholarship. The academic scholarship will be credited towards next semester tuition fee. Scholarship cannot be redeemed in cash. Students must apply and use the academic scholarship within 6 months of receiving the notification of results for a particular semester. The academic scholarship will not be available to students who are in their final semester of studies at CIM. The maximum academic scholarship available to each student is $500 per semester. Academic scholarship is provided in the following amounts: $150 for each course in which a student achieves Distinction (DI); $250 for each course in which a student achieves High Distinction (HD); Total academic scholarship amount is capped at $500 per semester.', sc.`eligibility` = 'Contact Canterbury Institute of Management for details.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://ciom.edu.au/apply-for-scholarship/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/academic-scholarships-international-students-only/6f00814297b6fa87fd48c78f843840a1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03809A' AND sc.`scholarship_name` = 'Academic Scholarships (International Students Only)' AND sc.`course_id` IS NULL;
