UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Merit based and only available for continuing students, who has completed first year of study with excellent academic results. Scholarship offered for students enrolled in UHE undergraduate programs and will be available for students who have successfully completed their first year of study at UHE. Candidates who hold UHE Academic Excellence (merit-based) Scholarship or UHE Financial Assistance Scholarship will not be eligible for this scholarship.', sc.`eligibility` = 'Be an international student enrolled as a full-time student in the semester to which the benefit would apply.; Have achieved an average overall percentage of 80.0% or more, with no individual result below 70.0% in the preceding semester and have no fail grades recorded; Have IELTS (academic) result with an overall score of 6.0 with no band less than 5.5 (for Bachelor students) and overall score of 6.5 with no band less than 6.0 (for Masters students). Documentary evidence of a current (test date within two years of date of application) IELTS certification must accompany the application.; Have completed at least two semesters full-time as per program requirements of the program at UHE.; Have a minimum attendance record of 75% in all scheduled classes.; Each application must be accompanied by a 500-750 words personal statement outlining why receipt of the scholarship is important.; Have made the fee payment for the subsequent semester’s full-time enrolment.; Not be sponsored by other organisations or governments.; Have submitted a completed application form before the application closing date.; Have maintained enrolment in the program in which they commenced.; If a student withdraws from the course, they will forfeit the scholarship.w', sc.`scholarship_amount` = 'Up to AUD $1000 — Successful applicants who are awarded a scholarship will receive a fee deduction of equivalent to $1000 of the tuition fee of a program he or she is enrolled for the commencing semester, March, or July. This scholarship is not trans', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uhe.edu.au/scholarships-commendations', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uhe-academic-achievement-scholarship/02aa67783c44200b31bcb7fbea8b97e6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03848E' AND sc.`scholarship_name` = 'UHE Academic Achievement scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'This scholarship is merit based and is available for new students who will be commencing in 2025. The UHE Academic Excellence Scholarship (International Students) would benefit international students, who have demonstrated academic excellence to peruse their higher education dreams in Australia. Candidates who hold this scholarship will not be eligible to apply for UHE Academic Achievement Scholarship for high achievers or UHE Financial Assistance Scholarship.', sc.`eligibility` = 'Enrolled as a full-time student and be a commencing international student for the semester to which the benefit applies.; Completed Australian Year 12 or equivalent with overall grade average of 70% or more, with no individual result below 65% and have no fail grades recorded; IELTS (academic) result with an overall score of 6.0 with no band less than 5.5. Documentary evidence of a current (test date within two years of date of application) IELTS certification must accompany the application.; Application must be accompanied by a 500-750 words personal statement outlining why receipt of the scholarship in important.; Not be sponsored by organisations or governments.; Have submitted a completed application form before the application closing date.; If a student withdraws from the course, they will forfeit the scholarship.', sc.`scholarship_amount` = 'Up to AUD $6000 — Successful applicants who are awarded a scholarship will receive a fee deduction of equivalent to $1000 of the tuition fee of a program he/ she is enrolled for the commencing semester, March, July or November. This scholarship is no', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uhe.edu.au/scholarships-commendations', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uhe-academic-excellence-merit-based-scholarship/bc5669418c7a8d1b28cc91edcd7cdb03', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03848E' AND sc.`scholarship_name` = 'UHE Academic Excellence (merit-based) Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'Awarded to students facing financial hardship in the intention of taking the financial pressure off them. Applicants need to successfully complete first semester of study at UHE. This scholarship will be available for students, who have successfully completed year one of study at UHE. Candidates who hold UHE Academic Excellence (merit-based) Scholarship or UHE Academic Achievement Scholarship for high achievers will not be eligible for this scholarship.', sc.`eligibility` = 'Be an international student enrolled as a full-time student in the semester to which the benefit would apply.; Current financial hardship - Student needs to provide sufficient evidence to demonstrate ongoing financial hardship.; Students must study full-time (0.5 EFTSL / 40 credit points) in each semester.; To continue receiving the scholarship into the future semesters, students must maintain a 100% pass rate each semester.; Application must be accompanied by a 500-750 words personal statement outlining the financial hardship he/she is undergoing and why receipt of the scholarship in important.; Not be sponsored by organisations or governments.; Have submitted a completed application form before the application closing date.; If a student withdraws from the course, they will forfeit the scholarship.', sc.`scholarship_amount` = 'Successful applicants who are awarded a scholarship will receive a fee deduction of equivalent to $1000 of the tuition fee of a program he or she is enrolled for the commencing semester, March or July. This scholarship is not transferable to another', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://www.uhe.edu.au/scholarships-commendations', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/uhe-financial-assistance-scholarship/f5e11599cce68ab1ef5c79e5fb4ffda6', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03848E' AND sc.`scholarship_name` = 'UHE Financial Assistance Scholarship' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'At Sydney Institute of Higher Education (SIHE), we are committed to supporting your academic journey and helping you achieve your educational goals. We offer a range of scholarships to recognise academic excellence, encourage diversity, and make a quality education accessible to deserving students.', sc.`eligibility` = 'Please Contact Sydney Institute if Higher Education for more information about Eligibility', sc.`scholarship_amount` = 'To encourage diversity and support student with developed English language skills, the scholarship, valued at 25% of tuition fees, is available to commencing students who enrol into any SIHE program for the June 2025 intake.', sc.`level_of_studies` = 'Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://sydneyinstitute.edu.au/scholarships/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/25-offshore-scholarship/26df4a34256be32e535346be258694ae', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '03866C' AND sc.`scholarship_name` = '25% Offshore Scholarship' AND sc.`course_id` IS NULL;
