UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Adelaide Academic Excellence Scholarship offers a 50% tuition fee reduction and is a prestigious, highly competitive award with limited places for students with a high distinction average. This scholarship recognises international students commencing undergraduate or postgraduate coursework degrees who have achieved outstanding academic performance in their previous studies.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 96 units / 2 years equivalent) after the application of any credit/RPL, or a CRICOS registered master degree (minimum 72 units / 1.5 years equivalent) after the application of any credit/RPL, at Adelaide University; satisfy one of the following in the qualification used as the basis of admission to the Adelaide University degree:; Undergraduate only: applicants with a minimum ATAR of 99 (or international equivalent).; Undergraduate and postgraduate: applicants with a minimum overall Grade Point Average (GPA) of 6.7 (on a 7.0 scale) or comparable score.; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship value, in which case the fee waiver amount will apply.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://adelaide.edu.au/study/scholarships/int/adelaide-academic-excellence-scholarship-50/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/adelaide-academic-excellence-scholarship-50/9fc72ece7254f4cbc866ef98ea0917df', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '04249J' AND sc.`scholarship_name` = 'Adelaide Academic Excellence Scholarship (50%)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Adelaide Emerging Leaders Award provides a 25% tuition fee reduction for international students starting an undergraduate or postgraduate coursework degree, it is automatically awarded at the time of offer to applicants who have achieved a distinction average and shown leadership qualities through strong academic commitment.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 72 units / 1.5 years equivalent) after the application of any credit/RPL, or a CRICOS registered master degree (minimum 48 units / 1 year equivalent) after the application of any credit/RPL, at Adelaide University; satisfy one of the following as the basis of admission to the Adelaide University degree:; Undergraduate only:; A minimum ATAR of 90 for students who have completed the Australian Senior Secondary Certificate of Education (SSCE).; A minimum score of 33 for students who have completed the International Baccalaureate (IB) Diploma; A minimum score of 12 for students who have completed the GCE A levels; A minimum ATAR of 95 (or international equivalent) for any other secondary certificate.; Undergraduate and postgraduate:; A minimum overall Grade Point Average (GPA) of 5.5 (on a 7.0 scale) for a completed award from Adelaide University (or with a comparable score for a qualification completed at an Australian University).; A minimum overall GPA of 6.0 (on a 7.0 scale) or comparable.; A minimum overall GPA of 5.5 (on a 7.0 scale) or equivalent from a program completed at an approved Adelaide University pathway provider.; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship value, in which case the fee waiver amount will apply.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://adelaide.edu.au/study/scholarships/int/adelaide-emerging-leaders-award-25/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/adelaide-emerging-leaders-award-25/07ecec3064de6ba13f7f7ddd95554c7d', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '04249J' AND sc.`scholarship_name` = 'Adelaide Emerging Leaders Award (25%)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Adelaide Global Alumni Scholarship offers a 10% tuition fee reduction. This scholarship is automatically assessed and awarded to international students commencing undergraduate or postgraduate coursework degrees who have previously studied at Adelaide University, the University of South Australia or the University of Adelaide.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 72 units / 1.5 years equivalent) after the application of any credit / RPL, or a CRICOS registered master degree (minimum 48 units / 1 year equivalent) after the application of any credit / RPL, at Adelaide University; provide verifiable evidence that they have previously completed a degree at Adelaide University or the University of South Australia or the University of Adelaide and / or have completed at least one semester of a Study Abroad Program at one of these institutions; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship value, in which case the fee waiver amount will apply.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://adelaide.edu.au/study/scholarships/int/adelaide-global-alumni-scholarship-10/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/adelaide-global-alumni-scholarship-10/5a506062117057a6431c4fe5001e7bc1', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '04249J' AND sc.`scholarship_name` = 'Adelaide Global Alumni Scholarship (10%)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Adelaide Merit Scholarship provides a 15% tuition fee reduction for international students starting an undergraduate or postgraduate coursework degree and is automatically awarded at the time of offer to applicants who have achieved a credit average and shown strong academic commitment. This scholarship supports international students commencing undergraduate or postgraduate coursework degrees who are committed to their academic achievement.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 72 units / 1.5 years equivalent) after the application of any credit/RPL, or a CRICOS registered master degree (minimum 48 units / 1 year equivalent) after the application of any credit/RPL, at Adelaide University; satisfy one of the following in the qualification used as the basis of admission to the Adelaide University degree:; Undergraduate only:; A minimum ATAR of 75 for students who have completed the Australian Senior Secondary Certificate of Education (SSCE) (or international equivalent for any other secondary certificate).; Successful completion of a competency-based vocational qualification in Australia with an overall non-graded pass.; Undergraduate and postgraduate:; A minimum overall Grade Point Average (GPA) of 4.5 (on a 7.0 scale) for an award completed at Adelaide University (or with a comparable score for a qualification completed at an Australian University).; A minimum overall Grade Point Average (GPA) of 5.0 (on a 7.0 scale) or comparable.; A minimum overall Grade Point Average (GPA) of 4.5 (on a 7.0 scale) or equivalent from a program completed at an approved Adelaide University pathway provider.; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://adelaide.edu.au/study/scholarships/int/adelaide-merit-scholarship-15/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/adelaide-merit-scholarship-15/8f14e2897ea65ca82f25f3641b43d3e4', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '04249J' AND sc.`scholarship_name` = 'Adelaide Merit Scholarship (15%)' AND sc.`course_id` IS NULL;
UPDATE `scholarships` sc INNER JOIN `provider_institution` pi ON pi.`id` = sc.`provider_institution_id` SET sc.`scholarship_description` = 'The Adelaide Partner Award offers a 10% tuition fee reduction and is automatically assessed and awarded to students from an approved Adelaide University partner institution. This scholarship supports international students commencing undergraduate or postgraduate coursework degrees.', sc.`eligibility` = 'To be eligible for this scholarship you must:; be an international student; be applying to study a CRICOS registered bachelor degree (minimum 72 units / 1.5 years equivalent) after the application of any credit/RPL, or a CRICOS registered master degree (minimum 48 units / 1 year equivalent) after the application of any credit/RPL, at Adelaide University; be admitted to an Adelaide University degree using a qualification (complete or incomplete) from an Approved Partner Institution as the basis of admission in the application; not be applying to study one of the Excluded Programs; not be an Australia Awards recipient; not be an International Sponsored Student entitled to a tuition fee waiver equal to or greater than the scholarship value, in which case the fee waiver amount will apply.', sc.`scholarship_amount` = 'See scholarship details', sc.`level_of_studies` = 'Postgraduate, Undergraduate / VET', sc.`field_of_studies` = NULL, sc.`website` = 'https://adelaide.edu.au/study/scholarships/int/adelaide-partner-award-10/', sc.`source_url` = 'https://search.studyaustralia.gov.au/scholarship/adelaide-partner-award-10/a66415a5626881f2ab3702313f2552a8', sc.`updated_at` = '2026-11-06 02:28:27' WHERE pi.`cricos_provider_code` = '04249J' AND sc.`scholarship_name` = 'Adelaide Partner Award (10%)' AND sc.`course_id` IS NULL;
