-- 8. Backfill relational foreign keys across courses, locations, and course_locations
UPDATE `courses` c INNER JOIN `provider_institution` p ON p.`cricos_provider_code` = c.`cricos_provider_code` SET c.`provider_institution_id` = p.`id` WHERE c.`provider_institution_id` IS NULL AND c.`cricos_provider_code` IS NOT NULL;
UPDATE `locations` l INNER JOIN `provider_institution` p ON p.`cricos_provider_code` = l.`cricos_provider_code` SET l.`provider_institution_id` = p.`id` WHERE l.`provider_institution_id` IS NULL AND l.`cricos_provider_code` IS NOT NULL;
UPDATE `course_locations` cl INNER JOIN `provider_institution` p ON p.`cricos_provider_code` = cl.`cricos_provider_code` SET cl.`provider_institution_id` = p.`id` WHERE cl.`provider_institution_id` IS NULL AND cl.`cricos_provider_code` IS NOT NULL;
UPDATE `course_locations` cl INNER JOIN `courses` c ON c.`cricos_course_code` = cl.`cricos_course_code` SET cl.`course_id` = c.`id` WHERE cl.`course_id` IS NULL AND cl.`cricos_course_code` IS NOT NULL;
COMMIT;
